									'change_kind'                    => array(
										'type' => 'string',
									),
									'risk_reason'                    => array(
										'type' => 'string',
									),
									'base_content_hash'              => array(
										'type'    => 'string',
										'pattern' => '^[a-f0-9]{64}$',
									),
									'proposed_content_hash'          => array(
										'type'    => 'string',
										'pattern' => '^[a-f0-9]{64}$',
									),
									'reviewed_proposed_content_hash' => array(
										'type'    => 'string',
										'pattern' => '^[a-f0-9]{64}$',
									),
									'kses_filtered_content_hash'     => array(
										'type'    => 'string',
										'pattern' => '^[a-f0-9]{64}$',
									),
									'review_status'                  => array(
										'type' => 'string',
									),
									'review_evidence_type'           => array(
										'type' => 'string',
									),
									'content_review_policy'          => array(
										'type' => 'string',
									),
								),
							),
