/**
 * Returns REST bases that currently support Distributed Editing recovery.
 *
 * @since 7.1.0
 *
 * @return string[] REST bases keyed by post type.
 */
function wp_de_rtc_get_rest_recovery_post_type_rest_bases() {
	$post_types = array( 'post', 'page' );
	$rest_bases = array();

	foreach ( $post_types as $post_type ) {
		$rest_base = wp_de_rtc_get_post_type_rest_base( $post_type );

		if ( $rest_base ) {
			$rest_bases[ $post_type ] = $rest_base;
		}
	}

	/**
	 * Filters REST bases that support Distributed Editing recovery routes.
	 *
	 * Keys are post type names and values are REST bases.
	 *
	 * @since 7.1.0
	 *
	 * @param string[] $rest_bases REST bases keyed by post type.
	 */
	$rest_bases = apply_filters( 'wp_de_rtc_rest_recovery_post_type_rest_bases', $rest_bases );

	return array_filter( array_map( 'sanitize_key', (array) $rest_bases ) );
}

/**
 * Returns the REST base for a post type.
 *
 * @since 7.1.0
 *
 * @param string $post_type Post type name.
 * @return string REST base, or empty string when unsupported.
 */
function wp_de_rtc_get_post_type_rest_base( $post_type ) {
	$post_type_object = get_post_type_object( $post_type );

	if ( ! $post_type_object || ! $post_type_object->show_in_rest ) {
		return '';
	}

	if ( ! empty( $post_type_object->rest_base ) ) {
		return sanitize_key( $post_type_object->rest_base );
	}

	return sanitize_key( $post_type_object->name );
}

/**
 * Registers Distributed Editing settings.
 *
 * Distributed Editing remains disabled by default. The setting exists so the
 * REST proof endpoint has an explicit opt-in path before any editor save path
 * or post-lock replacement work is introduced.
 *
 * @since 7.1.0
 */
function wp_de_rtc_register_settings() {
	register_setting(
		'writing',
		'wp_de_rtc_enabled',
		array(
			'type'              => 'boolean',
			'label'             => __( 'Distributed Editing' ),
			'description'       => __( 'Enable Distributed Editing recovery and collaboration endpoints for editable posts on this site.' ),
			'sanitize_callback' => 'wp_de_rtc_sanitize_enabled_setting',
			'default'           => false,
			'show_in_rest'      => false,
		)
	);
	register_setting(
		'writing',
		'wp_de_rtc_server_sync_poll_interval_ms',
		array(
			'type'              => 'integer',
			'label'             => __( 'Distributed Editing sync interval' ),
			'description'       => __( 'How often the editor checks WordPress for newer Distributed Editing changes.' ),
			'sanitize_callback' => 'wp_de_rtc_sanitize_server_sync_poll_interval_ms_setting',
			'default'           => wp_de_rtc_get_default_server_sync_poll_interval_ms(),
			'show_in_rest'      => false,
		)
	);

	if ( function_exists( 'add_settings_field' ) ) {
		add_settings_field(
			'wp_de_rtc_enabled',
			__( 'Distributed Editing' ),
			'wp_de_rtc_render_enabled_setting',
			'writing',
			'default'
		);
	}
}
add_action( 'admin_init', 'wp_de_rtc_register_settings' );

/**
 * Returns the capability required to set up Distributed Editing presence storage.
 *
 * @since 7.1.0
 *
 * @return string Required capability.
 */
function wp_de_rtc_get_presence_storage_setup_capability() {
	/**
	 * Filters the capability required to set up Distributed Editing presence storage.
	 *
	 * @since 7.1.0
	 *
	 * @param string $capability Required capability.
	 */
	return apply_filters( 'wp_de_rtc_presence_storage_setup_capability', 'manage_options' );
}

/**
 * Returns the nonce action for the presence storage setup admin action.
 *
 * @since 7.1.0
 *
 * @return string Nonce action.
 */
function wp_de_rtc_get_presence_storage_setup_nonce_action() {
	return 'wp_de_rtc_setup_presence_storage';
}

/**
 * Returns the admin-post action URL for deliberate presence storage setup.
 *
 * @since 7.1.0
 *
 * @param string $redirect_url Optional redirect URL after setup.
 * @return string Nonce-protected admin-post URL.
 */
function wp_de_rtc_get_presence_storage_setup_action_url( $redirect_url = '' ) {
	$query_args = array(
		'action' => 'wp_de_rtc_setup_presence_storage',
	);

	if ( $redirect_url ) {
		$query_args['redirect_to'] = rawurlencode( wp_validate_redirect( $redirect_url, admin_url( 'options-writing.php' ) ) );
	}

	return wp_nonce_url(
		add_query_arg( $query_args, admin_url( 'admin-post.php' ) ),
		wp_de_rtc_get_presence_storage_setup_nonce_action()
	);
}

/**
 * Returns the content-free state for the presence storage setup admin action.
 *
 * This helper may expose whether the setup action is available, but it must not
 * install storage, write heartbeats, save posts, mutate content, create
 * revisions, change post locks, or claim presence correctness.
 *
 * @since 7.1.0
 *
 * @param array $args {
 *     Optional action state arguments.
 *
 *     @type bool   $feature_enabled Whether DE-RTC is enabled for the current context.
 *     @type string $host_profile    Host profile label.
 *     @type string $redirect_url    Redirect URL for the setup action.
 * }
 * @return array Presence storage setup action state.
 */
function wp_de_rtc_get_presence_storage_setup_admin_action_state( $args = array() ) {
	$args = wp_parse_args(
		$args,
		array(
			'feature_enabled' => wp_de_rtc_is_enabled(),
			'host_profile'    => 'cheap_shared_host',
			'redirect_url'    => admin_url( 'options-writing.php' ),
		)
	);

	$readiness             = wp_de_rtc_get_presence_storage_readiness(
		array(
			'feature_enabled' => (bool) $args['feature_enabled'],
			'host_profile'    => $args['host_profile'],
		)
	);
	$required_capability   = wp_de_rtc_get_presence_storage_setup_capability();
	$current_user_can_setup = current_user_can( $required_capability );
	$setup_required        = (bool) $readiness['setupRequired'];
	$action_available      = (bool) $args['feature_enabled'] && $setup_required && $current_user_can_setup;
	$status                = 'action_unavailable';

	if ( ! (bool) $args['feature_enabled'] ) {
		$status = 'feature_disabled';
	} elseif ( 'ready' === $readiness['status'] ) {
		$status = 'ready';
	} elseif ( ! $current_user_can_setup ) {
		$status = 'forbidden';
	} elseif ( $setup_required ) {
		$status = 'available';
	}

	return array(
		'result'                            => $action_available ? 'presence_storage_setup_action_available' : 'presence_storage_setup_action_unavailable',
		'status'                            => $status,
		'actionName'                        => 'wp_de_rtc_setup_presence_storage',
		'method'                            => 'admin_post_nonce_url',
		'url'                               => $action_available ? wp_de_rtc_get_presence_storage_setup_action_url( $args['redirect_url'] ) : '',
		'nonceAction'                       => wp_de_rtc_get_presence_storage_setup_nonce_action(),
		'requiresNonce'                     => true,
		'requiresCapability'                => true,
		'requiredCapability'                => $required_capability,
		'currentUserCanSetup'               => $current_user_can_setup,
		'featureEnabled'                    => (bool) $args['feature_enabled'],
		'setupRequired'                     => $setup_required,
		'readinessStatus'                   => $readiness['status'],
		'expectedReadinessAfterSetup'       => 'ready',
		'contentFree'                       => true,
		'containsRawContent'                => false,
		'exposesRawContent'                 => false,
		'exposesUserIds'                    => false,
		'exposesLogins'                     => false,
		'exposesEmail'                      => false,
		'exposesCursorOffset'               => false,
		'exposesSelection'                  => false,
		'installsPresenceTable'             => false,
		'installTriggeredByEditorLoad'      => false,
		'installTriggeredBySave'            => false,
		'installTriggeredByPresenceRead'    => false,
		'installTriggeredByHeartbeatWrite'  => false,
		'automaticPerRequestInstall'        => false,
		'writesPresence'                    => false,
		'recordsPresenceHeartbeat'          => false,
		'startsPolling'                     => false,
		'callsSave'                         => false,
		'mutatesEditorContent'              => false,
		'mutatesPostContent'                => false,
		'mutatesPersistedPostContent'       => false,
		'createsRevision'                   => false,
		'changesPostLock'                   => false,
		'claimsAbsence'                     => false,
		'claimsSaved'                       => false,
		'repeatedRefreshOptional'           => true,
		'correctnessIndependentOfTransport' => true,
		'transportRequiredForCorrectness'   => false,
		'tableExistsRequiredForSaveCorrectness' => false,
	);
}

/**
 * Runs the deliberate presence storage setup admin action after guards pass.
 *
 * This helper is the write boundary for setup. It must only be called after a
 * nonce has been verified and a capable administrator has deliberately invoked
 * setup.
 *
 * @since 7.1.0
 *
 * @param array $args {
 *     Optional setup arguments.
 *
 *     @type bool   $nonce_verified Whether the admin nonce has already been verified.
 *     @type bool   $feature_enabled Whether DE-RTC is enabled for the current context.
 *     @type string $host_profile    Host profile label.
 * }
 * @return array|WP_Error Setup result, or an error when guards fail.
 */
function wp_de_rtc_run_presence_storage_setup_admin_action( $args = array() ) {
	$args = wp_parse_args(
		$args,
		array(
			'nonce_verified' => false,
			'feature_enabled' => wp_de_rtc_is_enabled(),
			'host_profile'    => 'cheap_shared_host',
		)
	);

	$action_state        = wp_de_rtc_get_presence_storage_setup_admin_action_state( $args );
	$required_capability = $action_state['requiredCapability'];
	$base_data           = array(
		'status'                            => 403,
		'action_name'                       => $action_state['actionName'],
		'nonce_action'                      => $action_state['nonceAction'],
		'requires_nonce'                    => true,
		'requires_capability'               => true,
		'required_capability'               => $required_capability,
		'current_user_can_setup'            => (bool) $action_state['currentUserCanSetup'],
		'install_triggered_by_editor_load'  => false,
		'install_triggered_by_save'         => false,
		'install_triggered_by_presence_read' => false,
		'install_triggered_by_heartbeat_write' => false,
		'automatic_per_request_install'     => false,
		'calls_save'                        => false,
		'mutates_post_content'              => false,
		'mutates_persisted_post_content'    => false,
		'creates_revision'                  => false,
		'changes_post_lock'                 => false,
		'claims_absence'                    => false,
		'claims_saved'                      => false,
		'exposes_raw_content'               => false,
		'exposes_user_ids'                  => false,
		'exposes_logins'                    => false,
		'exposes_email'                     => false,
		'exposes_cursor_offset'             => false,
		'exposes_selection'                 => false,
		'transport_required_for_correctness' => false,
		'table_exists_required_for_save_correctness' => false,
	);

	if ( ! (bool) $args['nonce_verified'] ) {
		return new WP_Error(
			'de_rtc_presence_storage_setup_nonce_required',
			__( 'Distributed Editing presence storage setup requires a valid nonce.' ),
			$base_data
		);
	}

	if ( ! current_user_can( $required_capability ) ) {
		return new WP_Error(
			'de_rtc_presence_storage_setup_forbidden',
			__( 'Sorry, you are not allowed to set up Distributed Editing presence storage.' ),
			$base_data
		);
	}

	if ( ! (bool) $args['feature_enabled'] ) {
		return new WP_Error(
			'de_rtc_feature_disabled',
			__( 'Distributed Editing must be enabled before presence storage is set up.' ),
			array_merge(
				$base_data,
				array(
					'status' => 400,
				)
			)
		);
	}

	$readiness_before = wp_de_rtc_get_presence_storage_readiness(
		array(
			'feature_enabled' => true,
			'host_profile'    => $args['host_profile'],
		)
	);
	$install          = wp_de_rtc_install_presence_table(
		array(
			'host_profile' => $args['host_profile'],
		)
	);
	$readiness_after  = wp_de_rtc_get_presence_storage_readiness(
		array(
			'feature_enabled' => true,
			'host_profile'    => $args['host_profile'],
		)
	);
	$result           = 'ready' === $readiness_after['status'] ? 'presence_storage_setup_completed' : 'presence_storage_setup_failed';

	if ( 'ready' === $readiness_before['status'] ) {
		$result = 'presence_storage_setup_checked';
	}

	return array(
		'result'                            => $result,
		'actionName'                        => $action_state['actionName'],
		'nonceAction'                       => $action_state['nonceAction'],
		'nonceVerified'                     => true,
		'requiresNonce'                     => true,
		'requiresCapability'                => true,
		'requiredCapability'                => $required_capability,
		'currentUserCanSetup'               => true,
		'beforeStatus'                      => $readiness_before['status'],
		'afterStatus'                       => $readiness_after['status'],
		'tableExistsBefore'                 => (bool) $readiness_before['tableExists'],
		'tableExistsAfter'                  => (bool) $readiness_after['tableExists'],
		'schemaCurrentAfter'                => (bool) $readiness_after['schemaCurrent'],
		'installResult'                     => $install['result'],
		'usesDbDelta'                       => (bool) $install['uses_db_delta'],
		'optionUpdated'                     => (bool) $install['option_updated'],
		'installTriggeredByExplicitAdminAction' => true,
		'installTriggeredByEditorLoad'      => false,
		'installTriggeredBySave'            => false,
		'installTriggeredByPresenceRead'    => false,
		'installTriggeredByCleanup'         => false,
		'installTriggeredByHeartbeatWrite'  => false,
		'automaticPerRequestInstall'        => false,
		'writesPresence'                    => false,
		'recordsPresenceHeartbeat'          => false,
		'startsPolling'                     => false,
		'callsSave'                         => false,
		'mutatesEditorContent'              => false,
		'mutatesPostContent'                => false,
		'mutatesPersistedPostContent'       => false,
		'createsRevision'                   => false,
		'changesPostLock'                   => false,
		'claimsAbsence'                     => false,
		'claimsSaved'                       => false,
		'exposesRawContent'                 => false,
		'exposesUserIds'                    => false,
		'exposesLogins'                     => false,
		'exposesEmail'                      => false,
		'exposesCursorOffset'               => false,
		'exposesSelection'                  => false,
		'repeatedRefreshOptional'           => true,
		'correctnessIndependentOfTransport' => true,
		'transportRequiredForCorrectness'   => false,
		'tableExistsRequiredForSaveCorrectness' => false,
	);
}

/**
 * Handles the nonce-protected admin action for presence storage setup.
 *
 * @since 7.1.0
 */
function wp_de_rtc_handle_presence_storage_setup_admin_action() {
	$capability = wp_de_rtc_get_presence_storage_setup_capability();

	if ( ! current_user_can( $capability ) ) {
		wp_die(
			esc_html__( 'Sorry, you are not allowed to set up Distributed Editing presence storage.' ),
			403
		);
	}

	check_admin_referer( wp_de_rtc_get_presence_storage_setup_nonce_action() );

	$result   = wp_de_rtc_run_presence_storage_setup_admin_action(
		array(
			'nonce_verified' => true,
		)
	);
	$status   = is_wp_error( $result ) ? 'failed' : sanitize_key( $result['afterStatus'] );
	$redirect = isset( $_GET['redirect_to'] ) ? rawurldecode( wp_unslash( $_GET['redirect_to'] ) ) : admin_url( 'options-writing.php' );
	$redirect = wp_validate_redirect( $redirect, admin_url( 'options-writing.php' ) );

	wp_safe_redirect(
		add_query_arg(
			'wp_de_rtc_presence_storage_setup',
			$status,
			$redirect
		)
	);
	exit;
}
add_action( 'admin_post_wp_de_rtc_setup_presence_storage', 'wp_de_rtc_handle_presence_storage_setup_admin_action' );

/**
 * Adds a settings notice after presence storage setup redirects.
 *
 * @since 7.1.0
 */
function wp_de_rtc_add_presence_storage_setup_settings_notice() {
	if ( empty( $_GET['wp_de_rtc_presence_storage_setup'] ) || ! function_exists( 'add_settings_error' ) ) {
		return;
	}

	$status = sanitize_key( wp_unslash( $_GET['wp_de_rtc_presence_storage_setup'] ) );

	if ( 'ready' === $status ) {
		add_settings_error(
			'wp_de_rtc_presence_storage',
			'wp_de_rtc_presence_storage_setup_ready',
			__( 'Distributed Editing presence storage is ready.' ),
			'success'
		);
		return;
	}

	add_settings_error(
		'wp_de_rtc_presence_storage',
		'wp_de_rtc_presence_storage_setup_failed',
		__( 'Distributed Editing presence storage setup did not complete.' ),
		'error'
	);
}
add_action( 'admin_init', 'wp_de_rtc_add_presence_storage_setup_settings_notice' );

/**
 * Adds Distributed Editing settings to the post block editor.
 *
 * The site option remains hidden from the REST settings controller. The editor
 * only receives the derived fact it needs to decide whether the guarded
 * Distributed Editing retry-save handoff should be active for the current post.
 *
 * @since 7.1.0
 *
 * @param array                   $editor_settings      Default editor settings.
 * @param WP_Block_Editor_Context $block_editor_context The current block editor context.
 * @return array Block editor settings with Distributed Editing facts.
 */
function wp_de_rtc_add_block_editor_settings( $editor_settings, $block_editor_context ) {
	$enabled                       = false;
	$post                          = null;
	$presence_host_profile         = wp_de_rtc_get_default_presence_host_profile();
	$presence_heartbeat_interval   = wp_de_rtc_get_presence_heartbeat_interval_seconds( $presence_host_profile );
	$presence_polling_interval     = $presence_heartbeat_interval;
	$presence_startup_delay        = 1;
	$server_sync_poll_interval_ms  = wp_de_rtc_get_server_sync_poll_interval_ms();

	if ( ! empty( $block_editor_context->post ) ) {
		$post    = $block_editor_context->post;
		$enabled = wp_de_rtc_is_enabled_for_post( $post );
	}

	$editor_settings['distributedEditing'] = array(
		'enabled'                  => $enabled,
		'retrySaveHandoff'         => $enabled,
		'riskyBlockReview'         => $enabled,
		'automergeRawPostContentSave'    => $enabled,
		'initialPresenceRoster'    => $enabled && $post ? wp_de_rtc_get_post_presence_roster( $post ) : wp_de_rtc_get_empty_post_presence_roster(),
		'presenceStartupPolicy'    => array(
			'allowAutomaticInitialHeartbeat'        => $enabled,
			'allowSlowAutomaticInitialHeartbeat'    => true,
			'hostProfile'                           => $presence_host_profile,
			'selectedInitialHeartbeatDelaySeconds'  => $presence_startup_delay,
			'standardInitialHeartbeatDelaySeconds'  => $presence_startup_delay,
			'cheapHostInitialHeartbeatDelaySeconds' => $presence_startup_delay,
			'minimumInitialHeartbeatDelaySeconds'   => $presence_startup_delay,
		),
		'presenceRepeatedRefreshRuntime' => array(
			'explicitOptIn'                         => $enabled,
			'hostProfile'                           => $presence_host_profile,
			'standardPollingIntervalSeconds'        => wp_de_rtc_get_presence_heartbeat_interval_seconds( 'standard' ),
			'cheapHostPollingIntervalSeconds'       => $presence_polling_interval,
			'minimumPollingIntervalSeconds'         => $presence_heartbeat_interval,
			'selectedPollingIntervalSeconds'        => $presence_polling_interval,
			'heartbeatIntervalSeconds'              => $presence_heartbeat_interval,
			'selectedHeartbeatIntervalSeconds'      => $presence_heartbeat_interval,
		),
		'serverSyncPollingRuntime'        => array(
			'explicitOptIn'                       => $enabled,
			'selectedPollingIntervalMilliseconds' => $server_sync_poll_interval_ms,
			'defaultPollingIntervalMilliseconds'  => wp_de_rtc_get_default_server_sync_poll_interval_ms(),
		),
		'presenceStorageReadiness'        => wp_de_rtc_get_presence_storage_readiness(
			array(
				'feature_enabled' => $enabled,
				'host_profile'    => $presence_host_profile,
			)
		),
	);

	return $editor_settings;
}
add_filter( 'block_editor_settings_all', 'wp_de_rtc_add_block_editor_settings', 10, 2 );

/**
 * Returns the default Distributed Editing presence host profile.
 *
 * Local development should show presence quickly enough for humans and browser
 * proofs. Production-like profiles keep the cheap-host cadence unless a site
 * explicitly opts into a different profile later.
 *
 * @since 7.1.0
 *
 * @return string Presence host profile.
 */
function wp_de_rtc_get_default_presence_host_profile() {
	return 'local' === wp_get_environment_type() ? 'local_development' : 'cheap_shared_host';
}

/**
 * Returns the empty Distributed Editing presence roster contract.
 *
 * This contract is intentionally conservative: it never claims that no other
 * editor exists, only that WordPress has no editor to show from the current
 * read-only source.
 *
 * @since 7.1.0
 *
 * @return array Empty presence roster data for editor bootstrap.
 */
function wp_de_rtc_get_empty_post_presence_roster() {
	return array(
		'status'                     => 'empty',
		'freshness'                  => 'unknown',
		'serverContact'              => 'nominal',
		'entries'                    => array(),
		'visibleCount'               => 0,
		'totalKnownCount'            => 0,
		'hiddenCount'                => 0,
		'expiredCount'               => 0,
		'source'                     => 'wordpress_post_lock_snapshot',
		'storageBacked'              => false,
		'latencyTolerant'            => true,
		'claimsAbsence'              => false,
		'descriptorOnly'             => true,
		'callsRestEndpoint'          => false,
		'callsSave'                  => false,
		'mutatesEditorContent'       => false,
		'mutatesPersistedPostContent' => false,
		'changesPostLock'            => false,
		'claimsSaved'                => false,
		'exposesRawContent'          => false,
		'exposesSelection'           => false,
		'exposesSelectionPresence'   => true,
		'exposesRawSelectedText'     => false,
		'exposesCursorOffset'        => false,
		'exposesUserIds'             => false,
		'culling'                    => wp_de_rtc_get_presence_culling_state(),
	);
}

/**
 * Returns a response-local prefix for opaque presence roster entry keys.
 *
 * Roster entry keys are only client-side rendering handles for the current
 * response. They must not derive from user IDs, post-lock data, actor hashes,
 * or session-key hashes because those values would make the roster stable
 * across reads in ways the privacy contract does not expose.
 *
 * @since 7.1.0
 *
 * @return string Response-local presence entry key prefix.
 */
function wp_de_rtc_generate_presence_response_local_roster_key_prefix() {
	return 'de-rtc-presence-entry-' . wp_generate_uuid4();
}

/**
 * Returns an opaque presence roster key scoped to a single response.
 *
 * @since 7.1.0
 *
 * @param string $response_key_prefix Response-local key prefix.
 * @param int    $ordinal             One-based entry ordinal for this response.
 * @return string Response-local opaque presence roster key.
 */
function wp_de_rtc_get_presence_response_local_roster_key( $response_key_prefix, $ordinal ) {
	$response_key_prefix = is_string( $response_key_prefix ) ? trim( $response_key_prefix ) : '';

	if ( '' === $response_key_prefix ) {
		$response_key_prefix = wp_de_rtc_generate_presence_response_local_roster_key_prefix();
	}

	return $response_key_prefix . '-' . max( 1, absint( $ordinal ) );
}

/**
 * Returns the initial Distributed Editing presence roster for a post.
 *
 * The preferred source is the dedicated Distributed Editing presence table
 * when active rows exist. The existing WordPress edit-lock snapshot remains a
 * read-only fallback. This helper does not create, refresh, steal, release, or
 * replace post locks.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post Post ID or object.
 * @param array       $args Optional roster read arguments.
 * @return array Presence roster data for editor bootstrap.
 */
function wp_de_rtc_get_post_presence_roster( $post, $args = array() ) {
	$post = get_post( $post );

	if ( ! $post ) {
		return wp_de_rtc_get_empty_post_presence_roster();
	}

	$storage_snapshot = wp_de_rtc_get_post_presence_storage_snapshot( $post, $args );
	$entries          = $storage_snapshot['entries'];
	$expired_count    = $storage_snapshot['expiredCount'];
	$hidden_count     = isset( $storage_snapshot['hiddenCount'] ) ? absint( $storage_snapshot['hiddenCount'] ) : 0;
	$culling          = isset( $storage_snapshot['culling'] ) && is_array( $storage_snapshot['culling'] )
		? $storage_snapshot['culling']
		: wp_de_rtc_get_presence_culling_state();
	$roster           = wp_de_rtc_get_empty_post_presence_roster();

	if ( empty( $entries ) && 0 === $expired_count && 0 === $hidden_count && empty( $culling['deletedCount'] ) ) {
		$entry   = wp_de_rtc_get_post_lock_presence_entry( $post );
		$entries = $entry ? array( $entry ) : array();

		if ( empty( $entries ) ) {
			return $roster;
		}

		$roster['status']          = 'recent';
		$roster['freshness']       = 'recent';
		$roster['entries']         = $entries;
		$roster['visibleCount']    = count( $entries );
		$roster['totalKnownCount'] = count( $entries );

		return $roster;
	}

	$current_count = 0;

	foreach ( $entries as $entry ) {
		if ( isset( $entry['freshness'] ) && 'current' === $entry['freshness'] ) {
			++$current_count;
		}
	}

	$roster['status']          = empty( $entries ) ? 'recent' : ( count( $entries ) === $current_count ? 'active' : 'recent' );
	$roster['freshness']       = empty( $entries ) ? 'recent' : ( count( $entries ) === $current_count ? 'current' : 'recent' );
	$roster['source']          = 'de_rtc_presence_storage';
	$roster['storageBacked']   = true;
	$roster['entries']         = $entries;
	$roster['visibleCount']    = count( $entries );
	$roster['totalKnownCount'] = count( $entries ) + $hidden_count + $expired_count;
	$roster['hiddenCount']     = $hidden_count;
	$roster['expiredCount']    = $expired_count;
	$roster['culling']         = $culling;

	return $roster;
}

/**
 * Returns a Distributed Editing presence storage snapshot.
 *
 * The snapshot culls stale ephemeral presence rows before reading so abandoned
 * avatars and pending previews disappear while active editors keep reporting.
 * It does not write heartbeats, install storage, save posts, mutate post
 * content, create revisions, or change post locks.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post Post ID or object.
 * @param array       $args {
 *     Optional read arguments.
 *
 *     @type string $current_time_gmt Current GMT time in mysql format.
 *     @type int    $limit            Maximum entries to return.
 *     @type string $current_session_key Opaque editor session key for the current tab.
 *     @type string $host_profile     Optional host profile label.
 * }
 * @return array Presence storage snapshot.
 */
function wp_de_rtc_get_post_presence_storage_snapshot( $post, $args = array() ) {
	global $wpdb;

	$post = get_post( $post );

	if ( ! $post || ! wp_de_rtc_presence_table_exists() ) {
		return array(
			'entries'      => array(),
			'hiddenCount'  => 0,
			'expiredCount' => 0,
			'culling'      => wp_de_rtc_get_presence_culling_state(),
		);
	}

	$args             = wp_parse_args(
		$args,
		array(
			'current_time_gmt'    => current_time( 'mysql', true ),
			'limit'               => 25,
			'current_session_key' => '',
			'host_profile'        => 'cheap_shared_host',
		)
	);
	$table_name           = wp_de_rtc_get_presence_table_name();
	$table_sql            = '`' . str_replace( '`', '``', $table_name ) . '`';
	$current_time_gmt     = (string) $args['current_time_gmt'];
	$current_time         = strtotime( $current_time_gmt . ' UTC' );
	$current_time         = $current_time ? $current_time : time();
	$host_profile         = is_string( $args['host_profile'] ) ? sanitize_key( $args['host_profile'] ) : '';
	$limit                = null === $args['limit'] ? 25 : max( 1, min( 100, absint( $args['limit'] ) ) );
	$current_actor        = wp_de_rtc_get_presence_actor_hash( get_current_user_id() );
	$current_session_key  = is_string( $args['current_session_key'] ) ? trim( $args['current_session_key'] ) : '';
	$current_session_hash = wp_de_rtc_get_presence_session_key_hash( $post->ID, $current_session_key );
	$schema_current       = wp_de_rtc_presence_table_schema_current();
	$where_clauses        = array( 'post_id = %d' );
	$where_values         = array( (int) $post->ID );

	if ( '' !== $current_session_hash ) {
		$where_clauses[] = 'session_key_hash <> %s';
		$where_values[]  = $current_session_hash;
	} elseif ( '' !== $current_actor ) {
		$where_clauses[] = 'actor_hash <> %s';
		$where_values[]  = $current_actor;
	}

	$culling = wp_de_rtc_cull_presence_storage_rows(
		$post,
		array(
			'current_time_gmt'    => $current_time_gmt,
			'current_session_key' => $current_session_key,
			'host_profile'        => $host_profile,
		)
	);

	$where_sql                  = implode( ' AND ', $where_clauses );
	$non_expired_where_sql      = $where_sql . ' AND expires_at_gmt > %s';
	$expired_where_sql          = $where_sql . ' AND expires_at_gmt <= %s';
	$non_expired_where_values   = array_merge( $where_values, array( $current_time_gmt ) );
	$expired_where_values       = array_merge( $where_values, array( $current_time_gmt ) );
	$visible_eligible_row_count = (int) $wpdb->get_var(
		$wpdb->prepare(
			"SELECT COUNT(*) FROM $table_sql WHERE $non_expired_where_sql",
			$non_expired_where_values
		)
	);
	$expired_count              = (int) $wpdb->get_var(
		$wpdb->prepare(
			"SELECT COUNT(*) FROM $table_sql WHERE $expired_where_sql",
			$expired_where_values
		)
	);
	$select_columns             = $schema_current
		? implode(
			', ',
			array(
				'session_key_hash',
				'actor_hash',
				'display_name',
				'freshness',
				'can_edit_post',
				'can_publish_post',
				'can_save_dangerous_html',
				'confirmed_base_version',
				'confirmed_state_hash',
				'has_pending_changes',
				'confirmed_at_gmt',
				'selection_state_json',
				'pending_preview_json',
				'last_seen_gmt',
				'expires_at_gmt',
				'created_at_gmt',
			)
		)
		: 'session_key_hash, actor_hash, display_name, freshness, last_seen_gmt, expires_at_gmt, created_at_gmt';
	$rows                       = $wpdb->get_results(
		$wpdb->prepare(
			"SELECT $select_columns FROM $table_sql WHERE $non_expired_where_sql ORDER BY last_seen_gmt DESC LIMIT %d",
			array_merge( $non_expired_where_values, array( $limit ) )
		)
	);

	if ( ! $rows ) {
		return array(
			'entries'      => array(),
			'hiddenCount'  => max( 0, $visible_eligible_row_count ),
			'expiredCount' => $expired_count,
			'culling'      => $culling,
		);
	}

	$entries             = array();
	$response_key_prefix = wp_de_rtc_generate_presence_response_local_roster_key_prefix();
	$entry_ordinal       = 0;

	foreach ( $rows as $row ) {
		$session_key_hash = isset( $row->session_key_hash ) ? (string) $row->session_key_hash : '';
		$actor_hash       = isset( $row->actor_hash ) ? (string) $row->actor_hash : '';
		$attribution_key  = wp_de_rtc_get_presence_attribution_key_from_session_hash( $post->ID, $session_key_hash );

		if ( '' === $session_key_hash ) {
			continue;
		}

		$freshness = wp_de_rtc_get_presence_storage_row_freshness(
			$row,
			array(
				'current_time_gmt' => $current_time_gmt,
				'host_profile'     => $host_profile,
			)
		);

		if ( 'expired' === $freshness ) {
			continue;
		}

		$is_same_actor = '' !== $actor_hash && hash_equals( $current_actor, $actor_hash );

		$display_name = isset( $row->display_name ) ? trim( wp_strip_all_tags( (string) $row->display_name ) ) : '';

		if ( '' === $display_name ) {
			$display_name = __( 'Another editor' );
		}

		$session_started_at_gmt  = isset( $row->created_at_gmt ) ? sanitize_text_field( (string) $row->created_at_gmt ) : '';
		$session_started_at      = '' !== $session_started_at_gmt ? strtotime( $session_started_at_gmt . ' UTC' ) : false;
		$session_duration        = $session_started_at ? max( 0, $current_time - $session_started_at ) : null;
		$presence_updated_at_gmt = isset( $row->last_seen_gmt ) ? sanitize_text_field( (string) $row->last_seen_gmt ) : '';
		$confirmed_base_version  = $schema_current && isset( $row->confirmed_base_version ) ? sanitize_text_field( (string) $row->confirmed_base_version ) : '';
		$confirmed_state_hash    = $schema_current && isset( $row->confirmed_state_hash ) && wp_de_rtc_is_sha256_hash( (string) $row->confirmed_state_hash ) ? (string) $row->confirmed_state_hash : '';
		$confirmed_at_gmt        = $schema_current && isset( $row->confirmed_at_gmt ) ? sanitize_text_field( (string) $row->confirmed_at_gmt ) : '';
		$selection_state_json    = $schema_current && isset( $row->selection_state_json ) ? (string) $row->selection_state_json : '';
		$selection_state         = wp_de_rtc_get_unavailable_presence_selection_state( $presence_updated_at_gmt );
		$pending_preview_json    = $schema_current && isset( $row->pending_preview_json ) ? (string) $row->pending_preview_json : '';
		$pending_preview         = wp_de_rtc_get_unavailable_presence_pending_preview_state( $presence_updated_at_gmt );

		if ( '' !== $selection_state_json ) {
			$decoded_selection_state = json_decode( $selection_state_json, true );

			if ( is_array( $decoded_selection_state ) ) {
				$selection_state = wp_de_rtc_get_sanitized_presence_selection_state( $decoded_selection_state, $current_time_gmt );
				$selection_state['presenceUpdatedAtGmt'] = $presence_updated_at_gmt;
			}
		}

		if ( '' !== $pending_preview_json ) {
			$decoded_pending_preview = json_decode( $pending_preview_json, true );

			if ( is_array( $decoded_pending_preview ) ) {
				$pending_preview = wp_de_rtc_get_sanitized_presence_pending_preview_state( $decoded_pending_preview, $current_time_gmt );
				$pending_preview['presenceUpdatedAtGmt'] = $presence_updated_at_gmt;

				if ( ! empty( $pending_preview['items'] ) && is_array( $pending_preview['items'] ) ) {
					foreach ( $pending_preview['items'] as $pending_preview_item_index => $pending_preview_item ) {
						if ( is_array( $pending_preview_item ) ) {
							$pending_preview['items'][ $pending_preview_item_index ]['updatedAtGmt'] = $presence_updated_at_gmt;
						}
					}
				}
			}
			}

		$document_state_available = $schema_current && '' !== $confirmed_base_version;
		$document_state          = $document_state_available
			? array(
				'available'            => true,
				'confirmedBaseVersion' => $confirmed_base_version,
				'confirmedStateHash'   => $confirmed_state_hash,
				'hasPendingChanges'    => ! empty( $row->has_pending_changes ),
				'confirmedAtGmt'       => $confirmed_at_gmt,
				'reportedAtGmt'        => $presence_updated_at_gmt,
				'presenceUpdatedAtGmt' => $presence_updated_at_gmt,
				'source'               => 'client_reported_presence',
				'authoritativeForSave' => false,
				'claimsSaved'          => false,
				'exposesRawContent'    => false,
			)
			: wp_de_rtc_get_unavailable_presence_document_state( $presence_updated_at_gmt );

		$entries[] = array(
			'key'                    => wp_de_rtc_get_presence_response_local_roster_key( $response_key_prefix, ++$entry_ordinal ),
			'displayName'            => $display_name,
			'identityVisibility'     => $is_same_actor ? 'self' : 'named',
			'relationship'           => $is_same_actor ? 'same_user_other_tab' : 'other_user',
			'activity'               => 'editing_post',
			'freshness'              => $freshness,
			'sessionStartedAtGmt'    => $session_started_at_gmt,
			'sessionDurationSeconds' => $session_duration,
			'presenceUpdatedAtGmt'   => $presence_updated_at_gmt,
			'attributionKey'         => $attribution_key,
			'authorshipFocusAvailable' => '' !== $attribution_key,
			'permissionsAvailable'   => $schema_current,
			'permissions'            => array(
				'canEdit'              => $schema_current && ! empty( $row->can_edit_post ),
				'canPublish'           => $schema_current && ! empty( $row->can_publish_post ),
				'canSaveDangerousHtml' => $schema_current && ! empty( $row->can_save_dangerous_html ),
			),
			'documentState'          => $document_state,
			'selectionState'         => $selection_state,
			'pendingPreview'         => $pending_preview,
			'source'                 => 'de_rtc_presence_storage',
			'exposesUserId'          => false,
			'exposesLogin'           => false,
			'exposesEmail'           => false,
			'exposesCursorOffset'    => false,
			'exposesSelection'       => false,
			'exposesSelectionPresence' => ! empty( $selection_state['available'] ),
			'exposesRawSelectedText' => false,
			'exposesRawContent'      => false,
			'exposesPendingPreview'  => ! empty( $pending_preview['available'] ),
			'rawSessionKeyIncluded'  => false,
		);
	}

	return array(
		'entries'      => $entries,
		'hiddenCount'  => max( 0, $visible_eligible_row_count - count( $entries ) ),
		'expiredCount' => $expired_count,
		'culling'      => $culling,
	);
}

/**
 * Returns the balanced stale-session culling policy for presence storage.
 *
 * The short no-pending window keeps abandoned avatars and ghosts from sticking
 * around while another editor is clearly still active. Pending previews get a
 * longer grace period because removing them discards another editor's visible
 * proposed work.
 *
 * @since 7.1.0
 *
 * @param string $host_profile Optional host profile label.
 * @return array Presence culling policy.
 */
function wp_de_rtc_get_presence_culling_policy( $host_profile = '' ) {
	$host_profile               = is_string( $host_profile ) ? sanitize_key( $host_profile ) : '';
	$heartbeat_interval_seconds = wp_de_rtc_get_presence_heartbeat_interval_seconds( $host_profile );
	$expires_after_seconds      = wp_de_rtc_get_presence_heartbeat_expires_after_seconds( $host_profile );
	$no_pending_after_seconds   = min( max( 90, $heartbeat_interval_seconds ), $expires_after_seconds );
	$pending_after_seconds      = min( 300, $expires_after_seconds );

	return array(
		'strategy'                      => 'balanced_stale_session_culling',
		'activeSessionWindowSeconds'    => $heartbeat_interval_seconds,
		'noPendingCullAfterSeconds'     => $no_pending_after_seconds,
		'pendingCullAfterSeconds'       => $pending_after_seconds,
		'hardExpireAfterSeconds'        => $expires_after_seconds,
		'deleteOnRead'                  => true,
		'claimsAbsence'                 => false,
	);
}

/**
 * Returns a content-free presence culling state for roster responses.
 *
 * @since 7.1.0
 *
 * @param array|string $args Optional state arguments or host profile.
 * @return array Presence culling state.
 */
function wp_de_rtc_get_presence_culling_state( $args = array() ) {
	if ( is_string( $args ) ) {
		$args = array( 'host_profile' => $args );
	}

	$args   = wp_parse_args(
		is_array( $args ) ? $args : array(),
		array(
			'host_profile'                       => '',
			'applied'                            => false,
			'active_session_observed'            => false,
			'deleted_count'                      => 0,
			'deleted_expired_count'              => 0,
			'deleted_stale_without_pending_count' => 0,
			'deleted_stale_with_pending_count'   => 0,
			'deleted_pending_preview_count'      => 0,
			'mutates_presence_storage'           => null,
			'storage_failure'                    => false,
		)
	);
	$policy = wp_de_rtc_get_presence_culling_policy( $args['host_profile'] );
	$mutates_presence_storage = null === $args['mutates_presence_storage']
		? (bool) $args['applied']
		: (bool) $args['mutates_presence_storage'];

	return array_merge(
		$policy,
		array(
			'applied'                         => (bool) $args['applied'],
			'activeSessionObserved'          => (bool) $args['active_session_observed'],
			'deletedCount'                   => absint( $args['deleted_count'] ),
			'deletedExpiredCount'            => absint( $args['deleted_expired_count'] ),
			'deletedStaleWithoutPendingCount' => absint( $args['deleted_stale_without_pending_count'] ),
			'deletedStaleWithPendingCount'   => absint( $args['deleted_stale_with_pending_count'] ),
			'deletedPendingPreviewCount'     => absint( $args['deleted_pending_preview_count'] ),
			'mutatesPresenceStorage'         => $mutates_presence_storage,
			'removesPendingPreviews'         => absint( $args['deleted_pending_preview_count'] ) > 0,
			'storageFailure'                 => (bool) $args['storage_failure'],
		)
	);
}

/**
 * Deletes stale presence rows for the current post before building a roster.
 *
 * This culls only ephemeral presence storage. It must not save posts, mutate
 * post content, create revisions, or change post locks.
 *
 * @since 7.1.0
 *
 * @param WP_Post $post Post object.
 * @param array   $args Optional culling arguments.
 * @return array Presence culling state.
 */
function wp_de_rtc_cull_presence_storage_rows( $post, $args = array() ) {
	global $wpdb;

	$post = get_post( $post );

	if ( ! $post || ! wp_de_rtc_presence_table_exists() ) {
		return wp_de_rtc_get_presence_culling_state();
	}

	$args             = wp_parse_args(
		$args,
		array(
			'current_time_gmt'    => current_time( 'mysql', true ),
			'current_session_key' => '',
			'host_profile'        => 'cheap_shared_host',
			'batch_limit'         => null,
		)
	);
	$current_time_gmt = (string) $args['current_time_gmt'];
	$current_time     = strtotime( $current_time_gmt . ' UTC' );
	$current_time     = $current_time ? $current_time : time();
	$host_profile     = is_string( $args['host_profile'] ) ? sanitize_key( $args['host_profile'] ) : '';
	$batch_limit      = null === $args['batch_limit'] ? wp_de_rtc_get_presence_cleanup_batch_limit( $host_profile ) : max( 1, absint( $args['batch_limit'] ) );
	$policy           = wp_de_rtc_get_presence_culling_policy( $host_profile );
	$table_name       = wp_de_rtc_get_presence_table_name();
	$table_sql        = '`' . str_replace( '`', '``', $table_name ) . '`';
	$current_actor    = wp_de_rtc_get_presence_actor_hash( get_current_user_id() );
	$current_session_key  = is_string( $args['current_session_key'] ) ? trim( $args['current_session_key'] ) : '';
	$current_session_hash = wp_de_rtc_get_presence_session_key_hash( $post->ID, $current_session_key );
	$where_clauses        = array( 'post_id = %d' );
	$where_values         = array( (int) $post->ID );

	if ( '' !== $current_session_hash ) {
		$where_clauses[] = 'session_key_hash <> %s';
		$where_values[]  = $current_session_hash;
	} elseif ( '' !== $current_actor ) {
		$where_clauses[] = 'actor_hash <> %s';
		$where_values[]  = $current_actor;
	}

	$active_cutoff_gmt     = gmdate( 'Y-m-d H:i:s', $current_time - (int) $policy['activeSessionWindowSeconds'] );
	$no_pending_cutoff_gmt = gmdate( 'Y-m-d H:i:s', $current_time - (int) $policy['noPendingCullAfterSeconds'] );
	$pending_cutoff_gmt    = gmdate( 'Y-m-d H:i:s', $current_time - (int) $policy['pendingCullAfterSeconds'] );
	$active_session_count  = (int) $wpdb->get_var(
		$wpdb->prepare(
			"SELECT COUNT(*) FROM $table_sql WHERE post_id = %d AND expires_at_gmt > %s AND last_seen_gmt >= %s",
			(int) $post->ID,
			$current_time_gmt,
			$active_cutoff_gmt
		)
	);
	$active_session_observed = $active_session_count > 0;
	$schema_current          = wp_de_rtc_presence_table_schema_current();
	$pending_sql             = $schema_current
		? "( has_pending_changes <> 0 OR ( pending_preview_json IS NOT NULL AND pending_preview_json <> '' ) )"
		: '0 = 1';
	$no_pending_sql          = $schema_current
		? "( has_pending_changes = 0 AND ( pending_preview_json IS NULL OR pending_preview_json = '' ) )"
		: '1 = 1';
	$where_sql               = implode( ' AND ', $where_clauses );
	$deleted_expired               = 0;
	$deleted_stale_without_pending = 0;
	$deleted_stale_with_pending    = 0;
	$deleted_pending_preview       = 0;
	$storage_failure               = false;

	$deleted_expired = $wpdb->query(
		$wpdb->prepare(
			"DELETE FROM $table_sql WHERE $where_sql AND expires_at_gmt <= %s ORDER BY expires_at_gmt ASC LIMIT %d",
			array_merge( $where_values, array( $current_time_gmt, $batch_limit ) )
		)
	);

	if ( false === $deleted_expired ) {
		$storage_failure  = true;
		$deleted_expired  = 0;
	}

	if ( $active_session_observed ) {
		if ( $schema_current ) {
			$deleted_pending_preview = (int) $wpdb->get_var(
				$wpdb->prepare(
					"SELECT COUNT(*) FROM $table_sql WHERE $where_sql AND expires_at_gmt > %s AND last_seen_gmt <= %s AND $pending_sql AND pending_preview_json IS NOT NULL AND pending_preview_json <> ''",
					array_merge( $where_values, array( $current_time_gmt, $pending_cutoff_gmt ) )
				)
			);
		}

		$deleted_stale_with_pending = $wpdb->query(
			$wpdb->prepare(
				"DELETE FROM $table_sql WHERE $where_sql AND expires_at_gmt > %s AND last_seen_gmt <= %s AND $pending_sql ORDER BY last_seen_gmt ASC LIMIT %d",
				array_merge( $where_values, array( $current_time_gmt, $pending_cutoff_gmt, $batch_limit ) )
			)
		);

		if ( false === $deleted_stale_with_pending ) {
			$storage_failure              = true;
			$deleted_stale_with_pending   = 0;
			$deleted_pending_preview      = 0;
		} else {
			$deleted_pending_preview = min( $deleted_pending_preview, (int) $deleted_stale_with_pending );
		}

		$deleted_stale_without_pending = $wpdb->query(
			$wpdb->prepare(
				"DELETE FROM $table_sql WHERE $where_sql AND expires_at_gmt > %s AND last_seen_gmt <= %s AND $no_pending_sql ORDER BY last_seen_gmt ASC LIMIT %d",
				array_merge( $where_values, array( $current_time_gmt, $no_pending_cutoff_gmt, $batch_limit ) )
			)
		);

		if ( false === $deleted_stale_without_pending ) {
			$storage_failure                 = true;
			$deleted_stale_without_pending   = 0;
		}
	}

	return wp_de_rtc_get_presence_culling_state(
		array(
			'host_profile'                        => $host_profile,
			'applied'                             => true,
			'active_session_observed'             => $active_session_observed,
			'deleted_count'                       => (int) $deleted_expired + (int) $deleted_stale_without_pending + (int) $deleted_stale_with_pending,
			'deleted_expired_count'               => (int) $deleted_expired,
			'deleted_stale_without_pending_count' => (int) $deleted_stale_without_pending,
			'deleted_stale_with_pending_count'    => (int) $deleted_stale_with_pending,
			'deleted_pending_preview_count'       => $deleted_pending_preview,
			'storage_failure'                     => $storage_failure,
		)
	);
}

/**
 * Returns visible Distributed Editing presence entries from the dedicated table.
 *
 * This roster source may cull stale ephemeral rows before reading. It does not
 * write heartbeats, install storage, save posts, mutate post content, create
 * revisions, or change post locks.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post Post ID or object.
 * @param array       $args Optional read arguments.
 * @return array[] Presence roster entries.
 */
function wp_de_rtc_get_post_presence_storage_entries( $post, $args = array() ) {
	$storage_snapshot = wp_de_rtc_get_post_presence_storage_snapshot( $post, $args );

	return $storage_snapshot['entries'];
}

/**
 * Classifies a stored Distributed Editing presence row at read time.
 *
 * Stored freshness labels are diagnostic only. The read snapshot derives the
 * visible freshness from server timestamps so slow polling and offline-like
 * latency stay within one communication model.
 *
 * @since 7.1.0
 *
 * @param object $row  Presence storage row.
 * @param array  $args Optional classification arguments.
 * @return string One of current, recent, or expired.
 */
function wp_de_rtc_get_presence_storage_row_freshness( $row, $args = array() ) {
	$args = wp_parse_args(
		$args,
		array(
			'current_time_gmt' => current_time( 'mysql', true ),
			'host_profile'     => 'cheap_shared_host',
		)
	);

	$current_time = strtotime( (string) $args['current_time_gmt'] . ' UTC' );
	$last_seen    = isset( $row->last_seen_gmt ) ? strtotime( (string) $row->last_seen_gmt . ' UTC' ) : false;
	$expires_at   = isset( $row->expires_at_gmt ) ? strtotime( (string) $row->expires_at_gmt . ' UTC' ) : false;

	if ( false === $current_time ) {
		$current_time = time();
	}

	if ( false !== $expires_at && $expires_at <= $current_time ) {
		return 'expired';
	}

	if ( false === $last_seen ) {
		return 'recent';
	}

	$host_profile               = is_string( $args['host_profile'] ) ? sanitize_key( $args['host_profile'] ) : '';
	$heartbeat_interval_seconds = wp_de_rtc_get_presence_heartbeat_interval_seconds( $host_profile );

	return $last_seen >= ( $current_time - $heartbeat_interval_seconds ) ? 'current' : 'recent';
}

/**
 * Returns a presence roster entry from the current WordPress edit lock.
 *
 * @since 7.1.0
 *
 * @param WP_Post $post Post object.
 * @return array|null Presence entry, or null when no other editor is known.
 */
function wp_de_rtc_get_post_lock_presence_entry( $post ) {
	$lock = get_post_meta( $post->ID, '_edit_lock', true );

	if ( ! $lock || ! is_string( $lock ) ) {
		return null;
	}

	$lock_parts = explode( ':', $lock );
	$time       = isset( $lock_parts[0] ) ? (int) $lock_parts[0] : 0;
	$user_id    = isset( $lock_parts[1] ) ? (int) $lock_parts[1] : (int) get_post_meta( $post->ID, '_edit_last', true );

	if ( ! $time || ! $user_id || get_current_user_id() === $user_id ) {
		return null;
	}

	/** This filter is documented in wp-admin/includes/ajax-actions.php. */
	$time_window = (int) apply_filters( 'wp_check_post_lock_window', 150 );

	if ( $time <= time() - $time_window ) {
		return null;
	}

	$user = get_userdata( $user_id );

	if ( ! $user ) {
		return null;
	}

	$permission_summary = wp_de_rtc_get_presence_permission_summary( $post, $user_id );
	$presence_updated_at_gmt = gmdate( 'Y-m-d H:i:s', $time );

	return array(
		'key'                 => wp_de_rtc_get_presence_response_local_roster_key( wp_de_rtc_generate_presence_response_local_roster_key_prefix(), 1 ),
		'displayName'         => $user->display_name ? $user->display_name : __( 'Another editor' ),
		'identityVisibility'  => 'named',
		'relationship'        => 'other_user',
		'activity'            => 'editing_post',
		'freshness'           => 'recent',
		'sessionStartedAtGmt' => $presence_updated_at_gmt,
		'sessionDurationSeconds' => max( 0, time() - $time ),
		'presenceUpdatedAtGmt' => $presence_updated_at_gmt,
		'permissionsAvailable' => true,
		'permissions'         => $permission_summary,
		'documentState'       => wp_de_rtc_get_unavailable_presence_document_state( $presence_updated_at_gmt ),
		'selectionState'      => wp_de_rtc_get_unavailable_presence_selection_state( $presence_updated_at_gmt ),
		'source'              => 'wordpress_post_lock_snapshot',
		'exposesUserId'       => false,
		'exposesCursorOffset' => false,
		'exposesSelection'    => false,
		'exposesSelectionPresence' => false,
		'exposesRawSelectedText' => false,
		'exposesRawContent'   => false,
	);
}

/**
 * Returns a read-only Distributed Editing presence snapshot for a post.
 *
 * This is the first DE-RTC-native read source contract. The current snapshot
 * still derives its roster from WordPress authority, but the route contract is
 * explicit about freshness, privacy, cheap-host polling, and the absence of
 * heartbeat writes or repeated client refresh.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post Post ID or object.
 * @param array       $args Optional presence snapshot arguments.
 * @return array Presence read snapshot.
 */
function wp_de_rtc_get_post_presence_read_snapshot( $post, $args = array() ) {
	$post = get_post( $post );

	if ( ! $post ) {
		return array(
			'result' => 'presence_roster_unavailable',
		);
	}

	$args                = wp_parse_args(
		$args,
		array(
			'current_session_key' => '',
			'current_time_gmt'    => current_time( 'mysql', true ),
			'host_profile'        => 'cheap_shared_host',
			'limit'               => 25,
		)
	);
	$current_session_key = is_string( $args['current_session_key'] ) ? trim( $args['current_session_key'] ) : '';
	$current_time_gmt    = (string) $args['current_time_gmt'];
	$host_profile        = is_string( $args['host_profile'] ) ? sanitize_key( $args['host_profile'] ) : '';
		$limit               = null === $args['limit'] ? 25 : max( 1, min( 100, absint( $args['limit'] ) ) );
	$roster              = wp_de_rtc_get_post_presence_roster(
		$post,
		array(
			'current_session_key' => $current_session_key,
			'current_time_gmt'    => $current_time_gmt,
			'host_profile'        => $host_profile,
			'limit'               => $limit,
		)
	);
	$mutates_presence_storage = ! empty( $roster['storageBacked'] ) && ! empty( $roster['culling']['deleteOnRead'] );

	return array(
		'result'                       => 'presence_roster_snapshot',
		'rest_route'                   => 'post_presence_roster',
		'post_id'                      => (int) $post->ID,
		'post_type'                    => $post->post_type,
		'post_type_rest_base'          => wp_de_rtc_get_post_type_rest_base( $post->post_type ),
		'presence_roster'              => $roster,
		'presence_read_contract'       => wp_de_rtc_get_post_presence_read_contract(
			$post,
			$roster,
			array(
				'current_session_key_provided' => '' !== $current_session_key,
				'host_profile'                 => $host_profile,
			)
		),
		'permission_contract'          => wp_de_rtc_get_rest_recovery_permission_contract( $post ),
		'read_only'                    => ! $mutates_presence_storage,
		'accepts_current_session_key'  => true,
		'current_session_key_compared_by_hash' => '' !== $current_session_key,
		'raw_session_key_included'     => false,
		'calls_save'                   => false,
		'saves_post'                   => false,
		'mutates_presence_storage'     => $mutates_presence_storage,
		'deletes_presence_rows'        => $mutates_presence_storage,
		'mutates_post_content'         => false,
		'mutates_persisted_post_content' => false,
		'creates_revision'             => false,
		'changes_post_lock'            => false,
		'records_presence_heartbeat'   => false,
		'enables_repeated_client_refresh' => false,
		'claims_saved'                 => false,
		'exposes_raw_content'          => false,
		'exposes_user_ids'             => false,
		'exposes_cursor_offset'        => false,
		'exposes_selection'            => false,
		'exposes_selection_presence'   => true,
		'exposes_raw_selected_text'    => false,
	);
}

/**
 * Returns the DE-RTC presence read contract for a post.
 *
 * The contract defines the first roster schema and polling guidance without
 * starting a polling loop or writing presence heartbeats.
 *
 * @since 7.1.0
 *
 * @param WP_Post $post   Post object.
 * @param array   $roster Presence roster data.
 * @param array   $args   Optional contract arguments.
 * @return array Presence read contract.
 */
function wp_de_rtc_get_post_presence_read_contract( $post, $roster, $args = array() ) {
	$rest_base = wp_de_rtc_get_post_type_rest_base( $post->post_type );
	$args      = wp_parse_args(
		$args,
		array(
			'current_session_key_provided' => false,
			'host_profile'                 => 'cheap_shared_host',
		)
	);
	$host_profile = is_string( $args['host_profile'] ) ? sanitize_key( $args['host_profile'] ) : '';
	$mutates_presence_storage = ! empty( $roster['storageBacked'] ) && ! empty( $roster['culling']['deleteOnRead'] );

	return array(
		'schema'                       => 'de-rtc-presence-roster-v2',
		'source'                       => 'de_rtc_presence_read_snapshot',
		'current_snapshot_source'      => isset( $roster['source'] ) ? $roster['source'] : 'unknown',
		'method'                       => 'GET',
		'route'                        => '/wp/v2/' . $rest_base . '/' . (int) $post->ID . '/distributed-editing/presence',
		'requires_edit_post'           => true,
		'requires_feature_enabled'     => true,
		'read_only'                    => ! $mutates_presence_storage,
		'writes_presence'              => false,
		'records_presence_heartbeat'   => false,
		'mutates_presence_storage'     => $mutates_presence_storage,
		'deletes_presence_rows'        => $mutates_presence_storage,
		'enables_repeated_client_refresh' => false,
		'session_identity'             => array(
			'accepts_current_session_key'  => true,
			'current_session_key_compared_by_hash' => (bool) $args['current_session_key_provided'],
			'raw_session_key_included'     => false,
			'same_actor_other_session_relationship' => 'same_user_other_tab',
		),
		'freshness_model'              => array(
			'status_values'         => array( 'active', 'recent', 'stale', 'degraded', 'empty', 'hidden' ),
			'freshness_values'      => array( 'current', 'recent', 'expired', 'stale', 'unknown' ),
			'snapshot_freshness'    => isset( $roster['freshness'] ) ? $roster['freshness'] : 'unknown',
			'hidden_count'          => isset( $roster['hiddenCount'] ) ? (int) $roster['hiddenCount'] : 0,
			'expired_count'         => isset( $roster['expiredCount'] ) ? (int) $roster['expiredCount'] : 0,
			'culling'               => isset( $roster['culling'] ) && is_array( $roster['culling'] ) ? $roster['culling'] : wp_de_rtc_get_presence_culling_state( $host_profile ),
			'claims_absence'        => false,
			'current_after_seconds' => wp_de_rtc_get_presence_heartbeat_interval_seconds( $host_profile ),
			'stale_after_seconds'   => wp_de_rtc_get_presence_heartbeat_interval_seconds( $host_profile ),
			'expires_after_seconds' => wp_de_rtc_get_presence_heartbeat_expires_after_seconds( $host_profile ),
		),
		'cheap_host_polling_guidance'  => array(
			'mode'                                  => 'manual_or_slow_polling',
			'minimum_polling_interval_seconds'      => 15,
			'suggested_polling_interval_seconds'    => 30,
			'cheap_host_polling_interval_seconds'   => 120,
			'repeated_client_refresh_enabled_now'   => false,
			'transport_required_for_correctness'    => false,
		),
		'schema_fields'                => array(
			'roster' => array(
				'status',
				'freshness',
				'serverContact',
				'entries',
				'visibleCount',
				'totalKnownCount',
				'hiddenCount',
				'expiredCount',
				'culling',
				'source',
				'claimsAbsence',
			),
			'entry'  => array(
				'key',
				'displayName',
				'identityVisibility',
				'relationship',
				'activity',
				'freshness',
				'sessionStartedAtGmt',
				'sessionDurationSeconds',
				'presenceUpdatedAtGmt',
				'permissionsAvailable',
				'permissions',
				'documentState',
				'selectionState',
				'source',
			),
		),
		'privacy_filters'              => array(
			'identity_policy'        => 'display_name_only_for_editable_post_context',
			'raw_content_included'   => false,
			'exposes_user_ids'       => false,
			'exposes_logins'         => false,
			'exposes_email'          => false,
			'exposes_cursor_offset'  => false,
			'exposes_selection'      => false,
			'exposes_selection_presence' => true,
			'exposes_raw_selected_text' => false,
			'exposes_raw_content'    => false,
			'redacted_fields'        => array(
				'userId',
				'user_id',
				'userLogin',
				'user_login',
				'email',
				'user_email',
				'cursorOffset',
				'cursor_offset',
				'rawSelection',
				'raw_selection',
				'selectedText',
				'selected_text',
				'rawContent',
				'raw_content',
			),
		),
	);
}

/**
 * Returns the Distributed Editing presence table name for the current site.
 *
 * @since 7.1.0
 *
 * @return string Presence table name.
 */
function wp_de_rtc_get_presence_table_name() {
	global $wpdb;

	return $wpdb->prefix . 'de_rtc_presence';
}

/**
 * Returns whether a database table is visible to the current connection.
 *
 * WordPress' PHPUnit harness can create custom tables as temporary tables,
 * which are usable by the connection but not visible through SHOW TABLES.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $table_name Database table name.
 * @return bool Whether the table exists for this connection.
 */
function wp_de_rtc_database_table_exists( $table_name ) {
	global $wpdb;

	$table_name = (string) $table_name;
	$exists     = $table_name === $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $wpdb->esc_like( $table_name ) ) );

	if ( $exists ) {
		return true;
	}

	$table_sql       = '`' . str_replace( '`', '``', $table_name ) . '`';
	$suppress_errors = $wpdb->suppress_errors( true );
	$columns         = $wpdb->get_results( "DESCRIBE $table_sql", ARRAY_A );
	$wpdb->suppress_errors( $suppress_errors );

	return is_array( $columns ) && ! empty( $columns );
}

/**
 * Returns the bounded cleanup batch limit for presence storage.
 *
 * @since 7.1.0
 *
 * @param string $host_profile Optional host profile label.
 * @return int Cleanup batch limit.
 */
function wp_de_rtc_get_presence_cleanup_batch_limit( $host_profile = '' ) {
	if ( 'cheap_shared_host' === $host_profile ) {
		return 25;
	}

	return 100;
}

/**
 * Returns the current Distributed Editing presence schema version.
 *
 * @since 7.1.0
 *
 * @return string Presence schema version.
 */
function wp_de_rtc_get_presence_schema_version() {
	return '5';
}

/**
 * Returns a privacy-preserving actor hash for presence storage.
 *
 * @since 7.1.0
 *
 * @param int $user_id User ID.
 * @return string Actor hash.
 */
function wp_de_rtc_get_presence_actor_hash( $user_id ) {
	return hash_hmac( 'sha256', (string) (int) $user_id, wp_salt( 'auth' ) );
}

/**
 * Returns a coarse, privacy-safe presence permission summary.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post    Post ID or object.
 * @param int         $user_id User ID.
 * @return array Permission summary.
 */
function wp_de_rtc_get_presence_permission_summary( $post, $user_id ) {
	$post             = get_post( $post );
	$post_type_object = $post ? get_post_type_object( $post->post_type ) : null;
	$publish_cap      = $post_type_object && isset( $post_type_object->cap->publish_posts ) ? $post_type_object->cap->publish_posts : 'publish_posts';

	return array(
		'canEdit'              => $post ? user_can( $user_id, 'edit_post', $post->ID ) : false,
		'canPublish'           => user_can( $user_id, $publish_cap ),
		'canSaveDangerousHtml' => user_can( $user_id, 'unfiltered_html' ),
	);
}

/**
 * Sanitizes the content-free document state reported in a presence heartbeat.
 *
 * The returned fields are advisory presence facts only. They are not save,
 * merge, conflict-resolution, or post-lock authority.
 *
 * @since 7.1.0
 *
 * @param array  $args             Raw heartbeat arguments.
 * @param string $current_time_gmt Current GMT time in mysql format.
 * @return array Sanitized presence document state.
 */
function wp_de_rtc_get_sanitized_presence_document_state( $args, $current_time_gmt ) {
	$confirmed_base_version = '';
	$confirmed_state_hash   = '';
	$current_timestamp      = strtotime( $current_time_gmt . ' UTC' );
	$confirmed_at_gmt       = '';

	if ( isset( $args['confirmed_base_version'] ) && is_scalar( $args['confirmed_base_version'] ) ) {
		$confirmed_base_version = substr(
			sanitize_text_field( (string) $args['confirmed_base_version'] ),
			0,
			191
		);
	}

	if ( isset( $args['confirmed_state_hash'] ) && is_scalar( $args['confirmed_state_hash'] ) ) {
		$confirmed_state_hash = strtolower(
			trim( sanitize_text_field( (string) $args['confirmed_state_hash'] ) )
		);
	}

	if ( ! wp_de_rtc_is_sha256_hash( $confirmed_state_hash ) ) {
		$confirmed_state_hash = '';
	}

	if ( isset( $args['confirmed_at_gmt'] ) && is_scalar( $args['confirmed_at_gmt'] ) ) {
		$confirmed_timestamp = strtotime( (string) $args['confirmed_at_gmt'] );

		if (
			$confirmed_timestamp &&
			( ! $current_timestamp || $confirmed_timestamp <= $current_timestamp + 300 )
		) {
			$confirmed_at_gmt = gmdate( 'Y-m-d H:i:s', $confirmed_timestamp );
		}
	}

	if ( '' === $confirmed_base_version ) {
		return array(
			'available'             => false,
			'confirmedBaseVersion'  => '',
			'confirmedStateHash'    => '',
			'hasPendingChanges'     => false,
			'confirmedAtGmt'        => '',
			'source'                => 'unavailable',
			'authoritativeForSave'  => false,
			'claimsSaved'           => false,
			'exposesRawContent'     => false,
		);
	}

	return array(
		'available'             => true,
		'confirmedBaseVersion'  => $confirmed_base_version,
		'confirmedStateHash'    => $confirmed_state_hash,
		'hasPendingChanges'     => wp_validate_boolean( $args['has_pending_changes'] ),
		'confirmedAtGmt'        => $confirmed_at_gmt,
		'source'                => 'client_reported_presence',
		'authoritativeForSave'  => false,
		'claimsSaved'           => false,
		'exposesRawContent'     => false,
	);
}

/**
 * Returns the schema label for content-free selection presence.
 *
 * Selection presence is ephemeral liveness data. It is deliberately separate
 * from post sync metadata so cursor movement cannot become post content,
 * revision content, or save authority.
 *
 * @since 7.1.0
 *
 * @return string Selection presence schema label.
 */
function wp_de_rtc_get_presence_selection_schema() {
	return 'de-rtc-selection-presence-v2';
}

/**
 * Returns the legacy schema label for content-free selection presence.
 *
 * @since 7.1.0
 *
 * @return string Legacy selection presence schema label.
 */
function wp_de_rtc_get_presence_selection_schema_v1() {
	return 'de-rtc-selection-presence-v1';
}

/**
 * Returns the first available value for one of several array keys.
 *
 * @since 7.1.0
 *
 * @param array $source Source array.
 * @param array $keys   Candidate keys.
 * @return mixed|null Matching value, or null when absent.
 */
function wp_de_rtc_get_presence_selection_value( $source, $keys ) {
	if ( ! is_array( $source ) ) {
		return null;
	}

	foreach ( $keys as $key ) {
		if ( array_key_exists( $key, $source ) ) {
			return $source[ $key ];
		}
	}

	return null;
}

/**
 * Returns whether a proposed selection payload contains forbidden raw fields.
 *
 * The allow-list sanitizer below ignores unknown fields, but these names are
 * treated as explicit privacy mistakes because they commonly carry raw text,
 * DOM authority, identity, or CRDT payloads that presence must never store.
 *
 * @since 7.1.0
 *
 * @param mixed $value Proposed selection payload.
 * @return bool Whether forbidden fields are present.
 */
function wp_de_rtc_presence_selection_contains_forbidden_keys( $value ) {
	if ( ! is_array( $value ) ) {
		return false;
	}

	$forbidden_keys = array(
		'clientid',
		'client_id',
		'cursoroffset',
		'cursor_offset',
		'cssselector',
		'css_selector',
		'domrange',
		'dom_range',
		'dompath',
		'dom_path',
		'email',
		'html',
		'innerhtml',
		'login',
		'outerhtml',
		'postcontent',
		'post_content',
		'rawcontent',
		'raw_content',
		'selectedtext',
		'selected_text',
		'selectionend',
		'selection_end',
		'selectionstart',
		'selection_start',
		'selector',
		'text',
		'useremail',
		'user_email',
		'userid',
		'user_id',
		'userlogin',
		'user_login',
		'xpath',
		'automergeupdate',
		'automerge_update',
	);

	foreach ( $value as $key => $child ) {
		$normalized_key = preg_replace( '/[^a-z0-9_]/', '', strtolower( (string) $key ) );

		if ( in_array( $normalized_key, $forbidden_keys, true ) ) {
			return true;
		}

		if ( is_array( $child ) && wp_de_rtc_presence_selection_contains_forbidden_keys( $child ) ) {
			return true;
		}
	}

	return false;
}

/**
 * Sanitizes a block path for content-free selection presence.
 *
 * @since 7.1.0
 *
 * @param mixed $path Proposed path.
 * @return int[]|null Sanitized top-to-bottom block index path, or null.
 */
function wp_de_rtc_sanitize_presence_selection_block_path( $path ) {
	if ( ! is_array( $path ) || empty( $path ) || count( $path ) > 12 ) {
		return null;
	}

	$sanitized = array();

	foreach ( $path as $part ) {
		if ( ! is_scalar( $part ) || '' === trim( (string) $part ) ) {
			return null;
		}

		$index = absint( $part );

		if ( (string) $index !== trim( (string) $part ) || $index > 10000 ) {
			return null;
		}

		$sanitized[] = $index;
	}

	return $sanitized;
}

/**
 * Sanitizes a server-owned block UID hint for content-free selection presence.
 *
 * Presence may carry this as a hint only. The receiving editor must validate it
 * against confirmed sync metadata before rendering a canvas selection.
 *
 * @since 7.1.0
 *
 * @param mixed $block_uid Proposed block UID.
 * @return string Sanitized block UID, or empty string.
 */
function wp_de_rtc_sanitize_presence_selection_block_uid( $block_uid ) {
	if ( ! is_scalar( $block_uid ) ) {
		return '';
	}

	$block_uid = trim( (string) $block_uid );

	if ( '' === $block_uid || strlen( $block_uid ) > 191 || ! preg_match( '/^[A-Za-z0-9._:-]+$/', $block_uid ) ) {
		return '';
	}

	return $block_uid;
}

/**
 * Sanitizes one selection endpoint for presence storage.
 *
 * @since 7.1.0
 *
 * @param mixed $point Proposed endpoint.
 * @return array|null Sanitized endpoint, or null.
 */
function wp_de_rtc_sanitize_presence_selection_point( $point ) {
	if ( ! is_array( $point ) ) {
		return null;
	}

	$block_path = wp_de_rtc_sanitize_presence_selection_block_path(
		wp_de_rtc_get_presence_selection_value( $point, array( 'blockPath', 'block_path', 'path' ) )
	);
	$block_uid  = wp_de_rtc_sanitize_presence_selection_block_uid(
		wp_de_rtc_get_presence_selection_value( $point, array( 'blockUid', 'block_uid' ) )
	);

	if ( null === $block_path && '' === $block_uid ) {
		return null;
	}

	$attribute_key = wp_de_rtc_get_presence_selection_value(
		$point,
		array( 'attributeKey', 'attribute_key' )
	);
	$attribute_key = is_scalar( $attribute_key ) ? trim( (string) $attribute_key ) : '';

	if ( '' !== $attribute_key && ! preg_match( '/^[A-Za-z0-9_-]{1,64}$/', $attribute_key ) ) {
		$attribute_key = '';
	}

	$offset_value = wp_de_rtc_get_presence_selection_value( $point, array( 'offset' ) );
	$offset       = null;

	if ( null !== $offset_value && '' !== $offset_value ) {
		if ( ! is_scalar( $offset_value ) ) {
			return null;
		}

		$offset = min( 1000000, absint( $offset_value ) );
	}

	return array(
		'blockPath'    => $block_path,
		'blockUid'     => '' === $block_uid ? null : $block_uid,
		'attributeKey' => $attribute_key,
		'offset'       => $offset,
	);
}

/**
 * Sanitizes a selection source-status value.
 *
 * This is sender-reported diagnostic data only. It never grants render
 * authority; the receiving editor computes renderability locally.
 *
 * @since 7.1.0
 *
 * @param mixed $status Proposed status.
 * @return string Sanitized source status.
 */
function wp_de_rtc_sanitize_presence_selection_source_status( $status ) {
	if ( ! is_scalar( $status ) ) {
		return 'unknown';
	}

	$status = sanitize_key( (string) $status );

	return in_array( $status, array( 'base_aligned', 'local_pending_only', 'unsupported_surface', 'unknown' ), true ) ? $status : 'unknown';
}

/**
 * Returns an unavailable selection-presence contract for fallbacks.
 *
 * @since 7.1.0
 *
 * @param string $presence_updated_at_gmt Optional presence update timestamp.
 * @return array Unavailable selection-presence data.
 */
function wp_de_rtc_get_unavailable_presence_selection_state( $presence_updated_at_gmt = '' ) {
	return array(
		'available'                     => false,
		'schema'                        => wp_de_rtc_get_presence_selection_schema(),
		'kind'                          => 'none',
		'isCollapsed'                   => true,
		'anchor'                        => null,
		'focus'                         => null,
		'baseVersion'                   => '',
		'baseStateHash'                 => '',
		'selectionSourceStatus'         => 'unknown',
		'reportedAtGmt'                 => '',
		'presenceUpdatedAtGmt'          => $presence_updated_at_gmt,
		'source'                        => 'unavailable',
		'contentFree'                   => true,
		'authoritativeForSave'          => false,
		'claimsSaved'                   => false,
		'exposesRawContent'             => false,
		'exposesRawSelectedText'        => false,
		'exposesClientId'               => false,
		'exposesDomSelector'            => false,
		'exposesBoundedSelectionOffsets' => false,
	);
}

/**
 * Sanitizes content-free selection presence reported in a heartbeat.
 *
 * The result may include block-relative offsets because those are needed to
 * place remote carets. It must not include raw selected text, HTML, DOM paths,
 * Gutenberg client IDs, user IDs, or save authority.
 *
 * @since 7.1.0
 *
 * @param mixed  $selection_state  Raw selection presence payload.
 * @param string $current_time_gmt Current GMT time in mysql format.
 * @return array Sanitized selection-presence data.
 */
function wp_de_rtc_get_sanitized_presence_selection_state( $selection_state, $current_time_gmt ) {
	if ( ! is_array( $selection_state ) || empty( $selection_state ) ) {
		return wp_de_rtc_get_unavailable_presence_selection_state();
	}

	if ( wp_de_rtc_presence_selection_contains_forbidden_keys( $selection_state ) ) {
		return wp_de_rtc_get_unavailable_presence_selection_state();
	}

	$schema = wp_de_rtc_get_presence_selection_value( $selection_state, array( 'schema' ) );
	$schema = is_scalar( $schema ) ? sanitize_text_field( (string) $schema ) : '';
	$is_v1_schema = wp_de_rtc_get_presence_selection_schema_v1() === $schema;
	$is_v2_schema = wp_de_rtc_get_presence_selection_schema() === $schema;

	if ( ! $is_v1_schema && ! $is_v2_schema ) {
		return wp_de_rtc_get_unavailable_presence_selection_state();
	}

	$kind = wp_de_rtc_get_presence_selection_value( $selection_state, array( 'kind' ) );
	$kind = is_scalar( $kind ) ? sanitize_key( (string) $kind ) : 'none';

	$kind_aliases = array(
		'collapsed_caret'  => 'caret',
		'rich_text_range'  => 'rich_text',
		'multi_block_range' => 'multi_block',
		'block_focus'      => 'block',
	);

	if ( isset( $kind_aliases[ $kind ] ) ) {
		$kind = $kind_aliases[ $kind ];
	}

	if ( ! in_array( $kind, array( 'caret', 'range', 'rich_text', 'multi_block', 'block', 'unsupported_surface' ), true ) ) {
		return wp_de_rtc_get_unavailable_presence_selection_state();
	}

	$base_version            = '';
	$base_state_hash         = '';
	$selection_source_status = 'unknown';

	if ( $is_v2_schema ) {
		$base_version = wp_de_rtc_get_presence_selection_value(
			$selection_state,
			array( 'baseVersion', 'base_version', 'confirmedBaseVersion', 'confirmed_base_version' )
		);
		$base_version = is_scalar( $base_version ) ? sanitize_text_field( (string) $base_version ) : '';

		if ( strlen( $base_version ) > 191 ) {
			$base_version = '';
		}

		$base_state_hash = wp_de_rtc_get_presence_selection_value(
			$selection_state,
			array( 'baseStateHash', 'base_state_hash', 'confirmedStateHash', 'confirmed_state_hash' )
		);
		$base_state_hash = is_scalar( $base_state_hash ) && wp_de_rtc_is_sha256_hash( (string) $base_state_hash ) ? strtolower( (string) $base_state_hash ) : '';

		$selection_source_status = wp_de_rtc_sanitize_presence_selection_source_status(
			wp_de_rtc_get_presence_selection_value(
				$selection_state,
				array( 'selectionSourceStatus', 'selection_source_status', 'sourceStatus', 'source_status' )
			)
		);
	}

	if ( 'unsupported_surface' === $kind ) {
		return array_merge(
			wp_de_rtc_get_unavailable_presence_selection_state(),
			array(
				'available'             => true,
				'schema'                => $schema,
				'kind'                  => 'unsupported_surface',
				'baseVersion'           => $base_version,
				'baseStateHash'         => $base_state_hash,
				'selectionSourceStatus' => 'unsupported_surface',
				'source'                => 'client_reported_presence',
			)
		);
	}

	$anchor = wp_de_rtc_sanitize_presence_selection_point(
		wp_de_rtc_get_presence_selection_value( $selection_state, array( 'anchor' ) )
	);
	$focus  = wp_de_rtc_sanitize_presence_selection_point(
		wp_de_rtc_get_presence_selection_value( $selection_state, array( 'focus' ) )
	);

	if ( null === $anchor ) {
		return wp_de_rtc_get_unavailable_presence_selection_state();
	}

	if ( null === $focus ) {
		$focus = $anchor;
	}

	$is_collapsed = wp_validate_boolean(
		wp_de_rtc_get_presence_selection_value( $selection_state, array( 'isCollapsed', 'is_collapsed' ) )
	);
	$reported_at_gmt  = '';
	$current_time     = strtotime( $current_time_gmt . ' UTC' );
	$reported_at_raw  = wp_de_rtc_get_presence_selection_value( $selection_state, array( 'reportedAtGmt', 'reported_at_gmt', 'updatedAt', 'updated_at' ) );
	$reported_at_time = is_scalar( $reported_at_raw ) ? strtotime( (string) $reported_at_raw ) : false;

	if ( $reported_at_time && ( ! $current_time || $reported_at_time <= $current_time + 300 ) ) {
		$reported_at_gmt = gmdate( 'Y-m-d H:i:s', $reported_at_time );
	}

	return array(
		'available'                     => true,
		'schema'                        => $schema,
		'kind'                          => $kind,
		'isCollapsed'                   => $is_collapsed,
		'anchor'                        => $anchor,
		'focus'                         => $focus,
		'baseVersion'                   => $base_version,
		'baseStateHash'                 => $base_state_hash,
		'selectionSourceStatus'         => $selection_source_status,
		'reportedAtGmt'                 => $reported_at_gmt,
		'presenceUpdatedAtGmt'          => '',
		'source'                        => 'client_reported_presence',
		'contentFree'                   => true,
		'authoritativeForSave'          => false,
		'claimsSaved'                   => false,
		'exposesRawContent'             => false,
		'exposesRawSelectedText'        => false,
		'exposesClientId'               => false,
		'exposesDomSelector'            => false,
		'exposesBoundedSelectionOffsets' => null !== $anchor['offset'] || null !== $focus['offset'],
	);
}

/**
 * Returns an unavailable document-state contract for presence fallbacks.
 *
 * @since 7.1.0
 *
 * @param string $presence_updated_at_gmt Optional presence update timestamp.
 * @return array Unavailable presence document-state data.
 */
function wp_de_rtc_get_unavailable_presence_document_state( $presence_updated_at_gmt = '' ) {
	return array(
		'available'            => false,
		'confirmedBaseVersion' => '',
		'confirmedStateHash'   => '',
		'hasPendingChanges'    => false,
		'confirmedAtGmt'       => '',
		'reportedAtGmt'        => '',
		'presenceUpdatedAtGmt' => $presence_updated_at_gmt,
		'source'               => 'unavailable',
		'authoritativeForSave' => false,
		'claimsSaved'          => false,
		'exposesRawContent'    => false,
	);
}

/**
 * Returns an unavailable pending-preview contract for presence fallbacks.
 *
 * Pending previews are ephemeral and inert. They may reveal a sanitized preview
 * of another editor's local work, but never raw HTML, sync metadata, identity
 * internals, or save authority.
 *
 * @since 7.1.0
 *
 * @param string $presence_updated_at_gmt Optional presence update timestamp.
 * @return array Unavailable pending-preview data.
 */
function wp_de_rtc_get_unavailable_presence_pending_preview_state( $presence_updated_at_gmt = '' ) {
	return array(
		'available'            => false,
		'schema'               => 'de-rtc-pending-preview-v1',
		'hasPendingPreview'    => false,
		'baseVersion'          => '',
		'baseStateHash'        => '',
		'items'                => array(),
		'itemCount'            => 0,
		'reportedAtGmt'        => '',
		'presenceUpdatedAtGmt' => $presence_updated_at_gmt,
		'source'               => 'unavailable',
		'ephemeral'            => true,
		'inert'                => true,
		'authoritativeForSave' => false,
		'claimsSaved'          => false,
		'rawContentIncluded'   => false,
		'exposesRawContent'    => false,
	);
}

/**
 * Sanitizes serialized block preview data while preserving block delimiters.
 *
 * Presence ghosts are rendered through Gutenberg's disabled block preview, so
 * the server keeps wp:block comments as data while sanitizing the HTML between
 * those delimiters. The returned string must never be inserted directly as raw
 * HTML by the editor.
 *
 * @since 7.1.0
 *
 * @param string $preview_source Serialized block source provided by the editor.
 * @return string Sanitized serialized block source.
 */
function wp_de_rtc_get_sanitized_presence_pending_preview_serialized_blocks( $preview_source ) {
	$preview_source = substr( (string) $preview_source, 0, 2000 );
	$preview_source = preg_replace( '#<(script|style|iframe|object|embed|svg|math)\b[^>]*>[\s\S]*?</\1\s*>#i', '', $preview_source );
	$preview_source = preg_replace( '#<(script|style|iframe|object|embed|svg|math)\b[^>]*/?>#i', '', $preview_source );
	$preview_source = preg_replace( '#\s+on[a-z]+\s*=\s*"[^"]*"#i', '', $preview_source );
	$preview_source = preg_replace( "#\s+on[a-z]+\s*=\s*'[^']*'#i", '', $preview_source );
	$preview_source = preg_replace( '#\s+on[a-z]+\s*=\s*[^\s>]+#i', '', $preview_source );
	$preview_source = preg_replace( '#\s+(href|src|xlink:href)\s*=\s*"javascript:[^"]*"#i', ' $1="#"', $preview_source );
	$preview_source = preg_replace( "#\s+(href|src|xlink:href)\s*=\s*'javascript:[^']*'#i", " $1='#'", $preview_source );
	$preview_source = preg_replace( '#\s+(href|src|xlink:href)\s*=\s*javascript:[^\s>]+#i', ' $1="#"', $preview_source );
	$preview_source = preg_replace( '#<!--(?!\s*/?wp:)[\s\S]*?-->#i', ' ', $preview_source );

	$parts = preg_split( '#(<!--\s*/?wp:[\s\S]*?-->)#i', $preview_source, -1, PREG_SPLIT_DELIM_CAPTURE );

	if ( ! is_array( $parts ) ) {
		return '';
	}

	$sanitized = '';

	foreach ( $parts as $part ) {
		if ( preg_match( '#^<!--\s*/?wp:[\s\S]*?-->$#i', $part ) ) {
			$sanitized .= $part;
			continue;
		}

		$sanitized .= wp_kses_post( $part );
	}

	return substr( trim( $sanitized ), 0, 2000 );
}

/**
 * Sanitizes pending-edit preview data reported by a presence heartbeat.
 *
 * The heartbeat may carry a short proposed source string so the server can
 * produce a benign preview. The stored and returned payload contains only
 * KSES-filtered HTML and stripped text; the raw source is discarded before
 * persistence.
 *
 * @since 7.1.0
 *
 * @param mixed  $pending_preview_state Raw pending-preview payload.
 * @param string $current_time_gmt      Current GMT time in mysql format.
 * @return array Sanitized pending-preview data.
 */
function wp_de_rtc_get_sanitized_presence_pending_preview_state( $pending_preview_state, $current_time_gmt ) {
	if ( ! is_array( $pending_preview_state ) || empty( $pending_preview_state ) ) {
		return wp_de_rtc_get_unavailable_presence_pending_preview_state();
	}

	$items = isset( $pending_preview_state['items'] ) && is_array( $pending_preview_state['items'] )
		? array_values( $pending_preview_state['items'] )
		: array();

	if ( empty( $items ) ) {
		return wp_de_rtc_get_unavailable_presence_pending_preview_state();
	}

	$sanitized_items = array();

	foreach ( array_slice( $items, 0, 8 ) as $index => $item ) {
		if ( ! is_array( $item ) ) {
			continue;
		}

		$preview_source            = '';
		$serialized_preview_source = '';

		foreach ( array( 'previewSource', 'preview_source', 'safePreviewHtml', 'safe_preview_html' ) as $source_key ) {
			if ( isset( $item[ $source_key ] ) && is_scalar( $item[ $source_key ] ) ) {
				$preview_source = (string) $item[ $source_key ];
				break;
			}
		}

		foreach ( array( 'safePreviewSerializedBlocks', 'safe_preview_serialized_blocks' ) as $source_key ) {
			if ( isset( $item[ $source_key ] ) && is_scalar( $item[ $source_key ] ) ) {
				$serialized_preview_source = (string) $item[ $source_key ];
				break;
			}
		}

		if ( '' === $serialized_preview_source ) {
			$serialized_preview_source = $preview_source;
		}

		$safe_serialized_blocks = wp_de_rtc_get_sanitized_presence_pending_preview_serialized_blocks( $serialized_preview_source );
		$preview_source         = substr( $preview_source, 0, 2000 );
		$preview_source         = preg_replace( '#<(script|style|iframe|object|embed|svg|math)\b[^>]*>[\s\S]*?</\1\s*>#i', '', $preview_source );
		$preview_source         = preg_replace( '#<(script|style|iframe|object|embed|svg|math)\b[^>]*/?>#i', '', $preview_source );
		$safe_html              = wp_kses_post( $preview_source );
		$safe_html              = substr( $safe_html, 0, 1000 );
		$safe_text              = trim( preg_replace( '/\s+/', ' ', wp_strip_all_tags( $safe_html ) ) );
		$safe_text              = substr( $safe_text, 0, 240 );
		$block_path             = wp_de_rtc_sanitize_presence_selection_block_path(
			isset( $item['blockPath'] ) ? $item['blockPath'] : ( isset( $item['block_path'] ) ? $item['block_path'] : array( $index ) )
		);
		$change_kind            = isset( $item['changeKind'] ) ? sanitize_key( (string) $item['changeKind'] ) : ( isset( $item['change_kind'] ) ? sanitize_key( (string) $item['change_kind'] ) : 'modified_block' );

		if ( ! in_array( $change_kind, array( 'added_block', 'modified_block', 'deleted_block', 'unknown_change' ), true ) ) {
			$change_kind = 'unknown_change';
		}

		$anchor_status = isset( $item['anchorStatus'] ) ? sanitize_key( (string) $item['anchorStatus'] ) : ( isset( $item['anchor_status'] ) ? sanitize_key( (string) $item['anchor_status'] ) : 'exact' );

		if ( ! in_array( $anchor_status, array( 'exact', 'ambiguous', 'unavailable' ), true ) ) {
			$anchor_status = 'exact';
		}

		$preview_scope = isset( $item['previewScope'] ) ? sanitize_key( (string) $item['previewScope'] ) : ( isset( $item['preview_scope'] ) ? sanitize_key( (string) $item['preview_scope'] ) : 'leaf_block' );

		if ( ! in_array( $preview_scope, array( 'leaf_block', 'sibling_collection', 'container_block' ), true ) ) {
			$preview_scope = 'leaf_block';
		}

		$block_range = null;
		$raw_range   = isset( $item['blockRange'] ) && is_array( $item['blockRange'] ) ? $item['blockRange'] : ( isset( $item['block_range'] ) && is_array( $item['block_range'] ) ? $item['block_range'] : null );

		if ( is_array( $raw_range ) ) {
			$range_start = isset( $raw_range['start'] ) ? absint( $raw_range['start'] ) : ( isset( $raw_range['start_index'] ) ? absint( $raw_range['start_index'] ) : null );
			$range_count = isset( $raw_range['count'] ) ? absint( $raw_range['count'] ) : 0;

			if ( null !== $range_start && $range_count > 0 && $range_count <= 8 ) {
				$block_range = array(
					'start' => $range_start,
					'count' => $range_count,
				);
			}
		}

		if ( '' === $safe_html && '' === $safe_text && '' === $safe_serialized_blocks && 'deleted_block' !== $change_kind ) {
			continue;
		}

		$block_name = isset( $item['blockName'] ) ? sanitize_text_field( (string) $item['blockName'] ) : ( isset( $item['block_name'] ) ? sanitize_text_field( (string) $item['block_name'] ) : '' );

		if ( '' === $block_name || strlen( $block_name ) > 128 || ! preg_match( '#^[a-z0-9_/-]+$#i', $block_name ) ) {
			$block_name = 'core/block';
		}

		$sanitized_items[] = array(
			'previewId'                   => 'pending-preview-' . substr( hash( 'sha256', wp_json_encode( array( $index, $block_path, $block_name, $safe_text, $safe_html, $safe_serialized_blocks ) ) ), 0, 12 ),
			'blockPath'                   => $block_path ? $block_path : array( $index ),
			'blockName'                   => $block_name,
			'changeKind'                  => $change_kind,
			'safePreviewSerializedBlocks' => $safe_serialized_blocks,
			'safePreviewHtml'             => $safe_html,
			'safePreviewText'             => $safe_text,
			'isPlaceholder'               => '' === $safe_text && '' === $safe_html && '' === $safe_serialized_blocks,
			'reviewRequired'              => ! empty( $item['reviewRequired'] ) || ! empty( $item['review_required'] ),
			'anchorStatus'                => $anchor_status,
			'previewScope'                => $preview_scope,
			'blockRange'                  => $block_range,
			'updatedAtGmt'                => $current_time_gmt,
			'rawContentIncluded'          => false,
			'exposesRawContent'           => false,
			'inert'                       => true,
		);
	}

	if ( empty( $sanitized_items ) ) {
		return wp_de_rtc_get_unavailable_presence_pending_preview_state();
	}

	$base_version = isset( $pending_preview_state['baseVersion'] ) ? sanitize_text_field( (string) $pending_preview_state['baseVersion'] ) : ( isset( $pending_preview_state['base_version'] ) ? sanitize_text_field( (string) $pending_preview_state['base_version'] ) : '' );
	$base_hash    = isset( $pending_preview_state['baseStateHash'] ) && wp_de_rtc_is_sha256_hash( (string) $pending_preview_state['baseStateHash'] )
		? (string) $pending_preview_state['baseStateHash']
		: ( isset( $pending_preview_state['base_state_hash'] ) && wp_de_rtc_is_sha256_hash( (string) $pending_preview_state['base_state_hash'] ) ? (string) $pending_preview_state['base_state_hash'] : '' );

	return array(
		'available'            => true,
		'schema'               => 'de-rtc-pending-preview-v1',
		'hasPendingPreview'    => true,
		'baseVersion'          => $base_version,
		'baseStateHash'        => $base_hash,
		'items'                => $sanitized_items,
		'itemCount'            => count( $sanitized_items ),
		'reportedAtGmt'        => $current_time_gmt,
		'presenceUpdatedAtGmt' => '',
		'source'               => 'client_reported_presence',
		'ephemeral'            => true,
		'inert'                => true,
		'authoritativeForSave' => false,
		'claimsSaved'          => false,
		'rawContentIncluded'   => false,
		'exposesRawContent'    => false,
	);
}

/**
 * Returns the WordPress presence storage schema contract.
 *
 * This defines the dedicated table and cleanup policy needed by future
 * heartbeat writes. It does not write heartbeats, start polling, save posts,
 * mutate post content, create revisions, or change post locks.
 *
 * @since 7.1.0
 *
 * @param array $args {
 *     Optional schema arguments.
 *
 *     @type string $host_profile Host profile label.
 * }
 * @return array Presence storage schema contract.
 */
function wp_de_rtc_get_presence_storage_schema( $args = array() ) {
	global $wpdb;

	$args              = wp_parse_args(
		$args,
		array(
			'host_profile' => 'cheap_shared_host',
		)
	);
	$table_name        = wp_de_rtc_get_presence_table_name();
	$cleanup_batch     = wp_de_rtc_get_presence_cleanup_batch_limit( $args['host_profile'] );
	$retention_seconds = 900;
	$schema_version    = wp_de_rtc_get_presence_schema_version();
	$charset_collate   = $wpdb->get_charset_collate();
	$create_sql        = "CREATE TABLE $table_name (
presence_id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
post_id bigint(20) unsigned NOT NULL DEFAULT 0,
session_key_hash char(64) NOT NULL DEFAULT '',
actor_hash char(64) NOT NULL DEFAULT '',
display_name varchar(191) NOT NULL DEFAULT '',
freshness varchar(20) NOT NULL DEFAULT 'active',
can_edit_post tinyint(1) unsigned NOT NULL DEFAULT 0,
can_publish_post tinyint(1) unsigned NOT NULL DEFAULT 0,
can_save_dangerous_html tinyint(1) unsigned NOT NULL DEFAULT 0,
confirmed_base_version varchar(191) NOT NULL DEFAULT '',
confirmed_state_hash char(64) NOT NULL DEFAULT '',
has_pending_changes tinyint(1) unsigned NOT NULL DEFAULT 0,
confirmed_at_gmt datetime DEFAULT NULL,
selection_state_json text,
pending_preview_json text,
last_seen_gmt datetime NOT NULL,
expires_at_gmt datetime NOT NULL,
created_at_gmt datetime NOT NULL,
updated_at_gmt datetime NOT NULL,
PRIMARY KEY  (presence_id),
UNIQUE KEY session_key_hash (session_key_hash),
KEY post_id_last_seen_gmt (post_id,last_seen_gmt),
KEY expires_at_gmt (expires_at_gmt)
) $charset_collate;";

	return array(
		'schema'                           => 'de-rtc-presence-storage-v5',
		'schema_version'                   => $schema_version,
		'storage_kind'                     => 'dedicated_presence_table',
		'table_name'                       => $table_name,
		'base_table_name'                  => 'de_rtc_presence',
		'primary_key'                      => 'presence_id',
		'columns'                          => array(
			'presence_id',
			'post_id',
			'session_key_hash',
			'actor_hash',
			'display_name',
			'freshness',
			'can_edit_post',
			'can_publish_post',
			'can_save_dangerous_html',
			'confirmed_base_version',
			'confirmed_state_hash',
			'has_pending_changes',
			'confirmed_at_gmt',
			'selection_state_json',
			'pending_preview_json',
			'last_seen_gmt',
			'expires_at_gmt',
			'created_at_gmt',
			'updated_at_gmt',
		),
		'indexes'                          => array(
			'post_id_last_seen_gmt',
			'session_key_hash',
			'expires_at_gmt',
		),
		'create_sql'                       => $create_sql,
		'cleanup_batch_limit'              => $cleanup_batch,
		'retention_seconds'                => $retention_seconds,
		'cleanup_bounded'                  => true,
		'route_gates'                      => array(
			'requires_feature_enabled'     => true,
			'requires_edit_post'           => true,
			'requires_supported_post_type' => true,
			'requires_nonce'               => true,
		),
		'privacy_filters'                  => array(
			'raw_content_included'  => false,
			'exposes_user_ids'      => false,
			'exposes_logins'        => false,
			'exposes_email'         => false,
			'exposes_cursor_offset' => false,
			'exposes_selection'     => false,
			'exposes_selection_presence' => true,
			'exposes_raw_selected_text' => false,
			'exposes_pending_preview' => true,
			'exposes_raw_content'   => false,
		),
		'heartbeat_writes_enabled_now'     => false,
		'records_presence_heartbeat_now'   => false,
		'runtime_polling_enabled_now'      => false,
		'repeated_refresh_optional'        => true,
		'transport_required_for_correctness' => false,
		'table_exists_required_for_save_correctness' => false,
		'calls_save'                       => false,
		'mutates_post_content'             => false,
		'mutates_persisted_post_content'   => false,
		'creates_revision'                 => false,
		'changes_post_lock'                => false,
		'claims_absence'                   => false,
		'claims_saved'                     => false,
	);
}

/**
 * Installs or updates the Distributed Editing presence table.
 *
 * This is an explicit setup path for future heartbeat storage. It must not run
 * as a side effect of reading presence, saving posts, cleaning up rows, or
 * handling heartbeat requests.
 *
 * @since 7.1.0
 *
 * @param array $args Optional schema arguments.
 * @return array Install result.
 */
function wp_de_rtc_install_presence_table( $args = array() ) {
	global $wpdb;

	$schema              = wp_de_rtc_get_presence_storage_schema( $args );
	$table_exists_before = wp_de_rtc_presence_table_exists();

	if ( ! function_exists( 'dbDelta' ) ) {
		require_once ABSPATH . 'wp-admin/includes/upgrade.php';
	}

	$db_delta           = dbDelta( $schema['create_sql'] );
	$table_exists_after = wp_de_rtc_presence_table_exists();
	$direct_create      = null;

	if ( ! $table_exists_after ) {
		$direct_create      = $wpdb->query( $schema['create_sql'] );
		$table_exists_after = wp_de_rtc_presence_table_exists();
	}

	if ( $table_exists_after ) {
		update_option( 'wp_de_rtc_presence_schema_version', $schema['schema_version'] );
	}

	return array(
		'result'                            => $table_exists_after ? ( $table_exists_before ? 'presence_table_upgrade_checked' : 'presence_table_installed' ) : 'presence_table_install_failed',
		'table_name'                        => $schema['table_name'],
		'schema_version'                    => $schema['schema_version'],
		'table_exists_before'               => $table_exists_before,
		'table_exists_after'                => $table_exists_after,
		'uses_db_delta'                     => true,
		'db_delta'                          => $db_delta,
		'direct_create_attempted'           => null !== $direct_create,
		'direct_create_result'              => $direct_create,
		'option_updated'                    => $table_exists_after,
		'install_triggered_by_explicit_call' => true,
		'automatic_per_request_install'     => false,
		'install_triggered_by_save'         => false,
		'install_triggered_by_presence_read' => false,
		'install_triggered_by_cleanup'      => false,
		'install_triggered_by_heartbeat_write' => false,
		'heartbeat_writes_enabled_now'      => false,
		'runtime_polling_enabled_now'       => false,
		'repeated_refresh_optional'         => true,
		'transport_required_for_correctness' => false,
		'table_exists_required_for_save_correctness' => false,
		'calls_save'                        => false,
		'mutates_post_content'              => false,
		'mutates_persisted_post_content'    => false,
		'creates_revision'                  => false,
		'changes_post_lock'                 => false,
		'claims_absence'                    => false,
		'claims_saved'                      => false,
	);
}

/**
 * Returns a content-free Distributed Editing presence storage readiness fact.
 *
 * This is an operations diagnostic for editor/admin communication. It may read
 * the table and schema-option state, but it must not install storage, write
 * heartbeats, save posts, mutate post content, create revisions, or change post
 * locks.
 *
 * @since 7.1.0
 *
 * @param array $args {
 *     Optional readiness arguments.
 *
 *     @type bool   $feature_enabled Whether DE-RTC is enabled for the current context.
 *     @type string $host_profile    Host profile label.
 * }
 * @return array Presence storage readiness data.
 */
function wp_de_rtc_get_presence_storage_readiness( $args = array() ) {
	$args = wp_parse_args(
		$args,
		array(
			'feature_enabled' => wp_de_rtc_is_enabled(),
			'host_profile'    => 'cheap_shared_host',
		)
	);

	$schema                   = wp_de_rtc_get_presence_storage_schema(
		array(
			'host_profile' => $args['host_profile'],
		)
	);
	$table_exists             = wp_de_rtc_presence_table_exists();
	$installed_schema_version = get_option( 'wp_de_rtc_presence_schema_version', null );
	$schema_current           = $table_exists && (string) $installed_schema_version === (string) $schema['schema_version'];
	$feature_enabled          = (bool) $args['feature_enabled'];
	$status                   = 'setup_required';

	if ( ! $feature_enabled ) {
		$status = 'feature_disabled';
	} elseif ( $schema_current ) {
		$status = 'ready';
	} elseif ( $table_exists ) {
		$status = 'upgrade_required';
	}

	$setup_required = $feature_enabled && 'ready' !== $status;

	return array(
		'result'                              => 'ready' === $status ? 'presence_storage_ready' : 'presence_storage_setup_required',
		'status'                              => $status,
		'tableName'                           => $schema['table_name'],
		'baseTableName'                       => $schema['base_table_name'],
		'tableExists'                         => $table_exists,
		'schemaVersionExpected'               => $schema['schema_version'],
		'schemaVersionInstalled'              => null === $installed_schema_version ? null : (string) $installed_schema_version,
		'schemaCurrent'                       => $schema_current,
		'featureEnabled'                      => $feature_enabled,
		'hostProfile'                         => $args['host_profile'],
		'expectedStartupHeartbeatStatus'      => $feature_enabled ? ( $schema_current ? 'sent' : 'degraded' ) : 'idle',
		'setupRequired'                       => $setup_required,
		'manualSetupRequired'                 => $setup_required,
		'canRetryAfterInstall'                => $setup_required,
		'setupAction'                         => 'call_wp_de_rtc_install_presence_table',
		'setupActionLabel'                    => __( 'Set up Distributed Editing presence storage' ),
		'setupTrigger'                        => 'explicit_setup_only',
		'diagnosticOnly'                      => true,
		'contentFree'                         => true,
		'containsRawContent'                  => false,
		'exposesRawContent'                   => false,
		'exposesUserIds'                      => false,
		'exposesLogins'                       => false,
		'exposesEmail'                        => false,
		'exposesCursorOffset'                 => false,
		'exposesSelection'                    => false,
		'exposesSelectionPresence'            => true,
		'exposesRawSelectedText'              => false,
		'installsPresenceTable'               => false,
		'automaticPerRequestInstall'          => false,
		'installTriggeredByPresenceRead'      => false,
		'installTriggeredByHeartbeatWrite'    => false,
		'writesPresence'                      => false,
		'recordsPresenceHeartbeat'            => false,
		'startsPolling'                       => false,
		'callsSave'                           => false,
		'mutatesEditorContent'                => false,
		'mutatesPostContent'                  => false,
		'mutatesPersistedPostContent'         => false,
		'createsRevision'                     => false,
		'changesPostLock'                     => false,
		'claimsAbsence'                       => false,
		'claimsSaved'                         => false,
		'repeatedRefreshOptional'             => true,
		'correctnessIndependentOfTransport'   => true,
		'transportRequiredForCorrectness'     => false,
		'tableExistsRequiredForSaveCorrectness' => false,
	);
}

/**
 * Returns whether the Distributed Editing presence table exists.
 *
 * @since 7.1.0
 *
 * @return bool Whether the table exists.
 */
function wp_de_rtc_presence_table_exists() {
	return wp_de_rtc_database_table_exists( wp_de_rtc_get_presence_table_name() );
}

/**
 * Returns whether the presence table matches the current schema contract.
 *
 * @since 7.1.0
 *
 * @return bool Whether the presence table schema is current.
 */
function wp_de_rtc_presence_table_schema_current() {
	return wp_de_rtc_presence_table_exists() && (string) get_option( 'wp_de_rtc_presence_schema_version', '' ) === (string) wp_de_rtc_get_presence_schema_version();
}

/**
 * Deletes expired Distributed Editing presence rows in a bounded batch.
 *
 * This helper only cleans presence storage. It does not write heartbeats, start
 * polling, save posts, mutate post content, create revisions, or change post
 * locks.
 *
 * @since 7.1.0
 *
 * @param array $args {
 *     Optional cleanup arguments.
 *
 *     @type int    $batch_limit      Maximum rows to delete.
 *     @type string $current_time_gmt Current GMT time in mysql format.
 * }
 * @return array|WP_Error Cleanup result, or a storage error.
 */
function wp_de_rtc_cleanup_presence_records( $args = array() ) {
	global $wpdb;

	$args             = wp_parse_args(
		$args,
		array(
			'batch_limit'      => wp_de_rtc_get_presence_cleanup_batch_limit( 'cheap_shared_host' ),
			'current_time_gmt' => current_time( 'mysql', true ),
		)
	);
	$table_name       = wp_de_rtc_get_presence_table_name();
	$batch_limit      = max( 1, absint( $args['batch_limit'] ) );
	$current_time_gmt = (string) $args['current_time_gmt'];
	$base_result      = array(
		'table_name'                         => $table_name,
		'batch_limit'                        => $batch_limit,
		'current_time_gmt'                   => $current_time_gmt,
		'bounded'                            => true,
		'cleanup_policy'                     => 'delete_expired_rows_in_bounded_batches',
		'records_presence_heartbeat'         => false,
		'heartbeat_writes_enabled_now'       => false,
		'runtime_polling_enabled_now'        => false,
		'repeated_refresh_optional'          => true,
		'transport_required_for_correctness' => false,
		'calls_save'                         => false,
		'mutates_post_content'               => false,
		'mutates_persisted_post_content'     => false,
		'creates_revision'                   => false,
		'changes_post_lock'                  => false,
		'claims_absence'                     => false,
		'claims_saved'                       => false,
	);

	if ( ! wp_de_rtc_presence_table_exists() ) {
		return array_merge(
			$base_result,
			array(
				'result'        => 'presence_table_missing',
				'deleted_count' => 0,
			)
		);
	}

	$table_sql = '`' . str_replace( '`', '``', $table_name ) . '`';
	$deleted   = $wpdb->query(
		$wpdb->prepare(
			"DELETE FROM $table_sql WHERE expires_at_gmt <= %s ORDER BY expires_at_gmt ASC LIMIT %d",
			$current_time_gmt,
			$batch_limit
		)
	);

	if ( false === $deleted ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_storage_failure',
			__( 'Distributed Editing presence cleanup failed.' ),
			array_merge(
				$base_result,
				array(
					'result'        => 'presence_cleanup_storage_failure',
					'deleted_count' => 0,
				)
			)
		);
	}

	return array_merge(
		$base_result,
		array(
			'result'        => 'presence_cleanup_completed',
			'deleted_count' => (int) $deleted,
		)
	);
}

/**
 * Returns the Distributed Editing review-items table name for the current site.
 *
 * @since 7.1.0
 *
 * @return string Review items table name.
 */
function wp_de_rtc_get_review_items_table_name() {
	global $wpdb;

	return $wpdb->prefix . 'de_rtc_review_items';
}

/**
 * Returns the current Distributed Editing review-items schema version.
 *
 * @since 7.1.0
 *
 * @return string Review item schema version.
 */
function wp_de_rtc_get_review_items_schema_version() {
	return '1';
}

/**
 * Returns the maximum stored source bytes for one review-required block.
 *
 * @since 7.1.0
 *
 * @return int Maximum source bytes.
 */
function wp_de_rtc_get_review_item_max_source_bytes() {
	return 262144;
}

/**
 * Returns the maximum pending review items retained for one post.
 *
 * @since 7.1.0
 *
 * @return int Pending review item limit.
 */
function wp_de_rtc_get_review_items_per_post_limit() {
	return 20;
}

/**
 * Returns the maximum pending review items retained for one proposer.
 *
 * @since 7.1.0
 *
 * @return int Pending review item limit.
 */
function wp_de_rtc_get_review_items_per_proposer_limit() {
	return 5;
}

/**
 * Returns the review item pending TTL in seconds.
 *
 * @since 7.1.0
 *
 * @return int Pending item TTL.
 */
function wp_de_rtc_get_review_items_pending_ttl_seconds() {
	return 7 * DAY_IN_SECONDS;
}

/**
 * Returns the bounded review item cleanup batch limit.
 *
 * @since 7.1.0
 *
 * @return int Cleanup batch limit.
 */
function wp_de_rtc_get_review_items_cleanup_batch_limit() {
	return 100;
}

/**
 * Returns the WordPress review-item storage schema contract.
 *
 * Review-required source is intentionally outside post_content because the post
 * body must remain the durable safe authority. The table stores source encoded
 * for transport safety, bounds pending rows, and expires proposals so review
 * cannot become unbounded durable user content.
 *
 * @since 7.1.0
 *
 * @return array Review item storage schema contract.
 */
function wp_de_rtc_get_review_items_storage_schema() {
	global $wpdb;

	$table_name      = wp_de_rtc_get_review_items_table_name();
	$schema_version  = wp_de_rtc_get_review_items_schema_version();
	$charset_collate = $wpdb->get_charset_collate();
	$create_sql      = "CREATE TABLE $table_name (
review_item_id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
public_id varchar(64) NOT NULL DEFAULT '',
logical_key_hash char(64) NOT NULL DEFAULT '',
post_id bigint(20) unsigned NOT NULL DEFAULT 0,
post_type varchar(20) NOT NULL DEFAULT '',
proposer_user_id bigint(20) unsigned NOT NULL DEFAULT 0,
proposer_actor_hash char(64) NOT NULL DEFAULT '',
proposer_display_name varchar(191) NOT NULL DEFAULT '',
status varchar(20) NOT NULL DEFAULT 'pending',
required_capability varchar(64) NOT NULL DEFAULT 'unfiltered_html',
base_sync_version varchar(191) NOT NULL DEFAULT '',
server_sync_version varchar(191) NOT NULL DEFAULT '',
base_content_hash char(64) NOT NULL DEFAULT '',
proposed_content_hash char(64) NOT NULL DEFAULT '',
kses_filtered_content_hash char(64) NOT NULL DEFAULT '',
block_anchor_hash char(64) NOT NULL DEFAULT '',
block_path varchar(191) NOT NULL DEFAULT '',
block_name varchar(191) NOT NULL DEFAULT '',
block_label varchar(191) NOT NULL DEFAULT '',
change_kind varchar(32) NOT NULL DEFAULT '',
risk_reason varchar(64) NOT NULL DEFAULT '',
encoded_proposed_source longtext NOT NULL,
encoded_kses_filtered_source longtext NOT NULL,
proposed_source_length bigint(20) unsigned NOT NULL DEFAULT 0,
kses_filtered_source_length bigint(20) unsigned NOT NULL DEFAULT 0,
render_as varchar(20) NOT NULL DEFAULT 'text',
executable tinyint(1) unsigned NOT NULL DEFAULT 0,
created_at_gmt datetime NOT NULL,
updated_at_gmt datetime NOT NULL,
expires_at_gmt datetime NOT NULL,
resolved_at_gmt datetime DEFAULT NULL,
resolved_by bigint(20) unsigned NOT NULL DEFAULT 0,
resolution_action varchar(20) NOT NULL DEFAULT '',
PRIMARY KEY  (review_item_id),
UNIQUE KEY public_id (public_id),
UNIQUE KEY logical_key_hash (logical_key_hash),
KEY post_status_expires (post_id,status,expires_at_gmt),
KEY proposer_status (proposer_user_id,status),
KEY expires_at_gmt (expires_at_gmt)
) $charset_collate;";

	return array(
		'schema'                            => 'de-rtc-review-items-v1',
		'schema_version'                    => $schema_version,
		'storage_kind'                      => 'dedicated_review_item_table',
		'table_name'                        => $table_name,
		'base_table_name'                   => 'de_rtc_review_items',
		'primary_key'                       => 'review_item_id',
		'create_sql'                        => $create_sql,
		'pending_ttl_seconds'               => wp_de_rtc_get_review_items_pending_ttl_seconds(),
		'per_post_pending_limit'            => wp_de_rtc_get_review_items_per_post_limit(),
		'per_proposer_pending_limit'        => wp_de_rtc_get_review_items_per_proposer_limit(),
		'max_source_bytes'                  => wp_de_rtc_get_review_item_max_source_bytes(),
		'cleanup_batch_limit'               => wp_de_rtc_get_review_items_cleanup_batch_limit(),
		'stores_raw_content_in_post_content' => false,
		'stored_source_encoding'            => 'base64url',
		'detail_transport'                  => 'html_escaped_text',
		'ephemeral'                         => true,
		'bounded'                           => true,
	);
}

/**
 * Installs or updates the Distributed Editing review-items table.
 *
 * @since 7.1.0
 *
 * @return array Install result.
 */
function wp_de_rtc_install_review_items_table() {
	global $wpdb;

	$schema              = wp_de_rtc_get_review_items_storage_schema();
	$table_exists_before = wp_de_rtc_review_items_table_exists();

	if ( ! function_exists( 'dbDelta' ) ) {
		require_once ABSPATH . 'wp-admin/includes/upgrade.php';
	}

	$db_delta           = dbDelta( $schema['create_sql'] );
	$table_exists_after = wp_de_rtc_review_items_table_exists();
	$direct_create      = null;

	if ( ! $table_exists_after ) {
		/*
		 * dbDelta() can no-op on custom proof tables in isolated test
		 * environments. Review-required proposals must not silently lose their
		 * bounded queue because of that parser boundary, so fall back to the
		 * exact schema contract before reporting storage unavailable.
		 */
		$direct_create      = $wpdb->query( $schema['create_sql'] );
		$table_exists_after = wp_de_rtc_review_items_table_exists();
	}

	if ( $table_exists_after ) {
		update_option( 'wp_de_rtc_review_items_schema_version', $schema['schema_version'] );
	}

	return array(
		'result'                            => $table_exists_after ? ( $table_exists_before ? 'review_items_table_upgrade_checked' : 'review_items_table_installed' ) : 'review_items_table_install_failed',
		'table_name'                        => $schema['table_name'],
		'schema_version'                    => $schema['schema_version'],
		'table_exists_before'               => $table_exists_before,
		'table_exists_after'                => $table_exists_after,
		'uses_db_delta'                     => true,
		'db_delta'                          => $db_delta,
		'direct_create_attempted'           => null !== $direct_create,
		'direct_create_result'              => $direct_create,
		'option_updated'                    => $table_exists_after,
		'stores_raw_content_in_post_content' => false,
		'stored_source_encoding'            => 'base64url',
		'ephemeral'                         => true,
		'bounded'                           => true,
		'saves_post'                        => false,
		'mutates_post_content'              => false,
		'creates_revision'                  => false,
		'changes_post_lock'                 => false,
		'claims_saved'                      => false,
	);
}

/**
 * Returns whether the Distributed Editing review-items table exists.
 *
 * @since 7.1.0
 *
 * @return bool Whether the table exists.
 */
function wp_de_rtc_review_items_table_exists() {
	return wp_de_rtc_database_table_exists( wp_de_rtc_get_review_items_table_name() );
}

/**
 * Returns whether the review-items table matches the current schema contract.
 *
 * @since 7.1.0
 *
 * @return bool Whether the table schema is current.
 */
function wp_de_rtc_review_items_table_schema_current() {
	return wp_de_rtc_review_items_table_exists() && (string) get_option( 'wp_de_rtc_review_items_schema_version', '' ) === (string) wp_de_rtc_get_review_items_schema_version();
}

/**
 * Encodes review-required source for storage.
 *
 * Base64url is obfuscation and transport hardening, not authorization. The
 * authorization boundary is still the review-items REST permission checks.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $source Source text.
 * @return string Encoded source.
 */
function wp_de_rtc_base64url_encode( $source ) {
	return rtrim( strtr( base64_encode( (string) $source ), '+/', '-_' ), '=' );
}

/**
 * Decodes review-required source from storage.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $encoded Encoded source.
 * @return string Decoded source, or an empty string on malformed input.
 */
function wp_de_rtc_base64url_decode( $encoded ) {
	$encoded = (string) $encoded;
	$padded  = strtr( $encoded, '-_', '+/' );
	$padding = strlen( $padded ) % 4;

	if ( $padding ) {
		$padded .= str_repeat( '=', 4 - $padding );
	}

	$decoded = base64_decode( $padded, true );

	return false === $decoded ? '' : $decoded;
}

/**
 * Generates an opaque public review item identifier.
 *
 * @since 7.1.0
 * @access private
 *
 * @return string Public review item ID.
 */
function wp_de_rtc_generate_review_item_public_id() {
	try {
		$random = bin2hex( random_bytes( 16 ) );
	} catch ( Exception $exception ) {
		$random = substr( hash( 'sha256', wp_generate_password( 64, true, true ) . microtime( true ) ), 0, 32 );
	}

	return 'de-rtc-review-' . substr( $random, 0, 32 );
}

/**
 * Sanitizes an opaque public review item identifier.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $public_id Public review item ID.
 * @return string Sanitized review item ID, or empty string.
 */
function wp_de_rtc_sanitize_review_item_public_id( $public_id ) {
	$public_id = sanitize_text_field( (string) $public_id );

	if ( 1 !== preg_match( '/^de-rtc-review-[a-f0-9]{32}$/', $public_id ) ) {
		return '';
	}

	return $public_id;
}

/**
 * Deletes expired or resolved review items in a bounded batch.
 *
 * @since 7.1.0
 *
 * @param array $args Cleanup args.
 * @return array|WP_Error Cleanup result.
 */
function wp_de_rtc_cleanup_review_items( $args = array() ) {
	global $wpdb;

	$args             = wp_parse_args(
		$args,
		array(
			'batch_limit'      => wp_de_rtc_get_review_items_cleanup_batch_limit(),
			'current_time_gmt' => current_time( 'mysql', true ),
		)
	);
	$table_name       = wp_de_rtc_get_review_items_table_name();
	$batch_limit      = max( 1, absint( $args['batch_limit'] ) );
	$current_time_gmt = (string) $args['current_time_gmt'];
	$base_result      = array(
		'table_name'             => $table_name,
		'batch_limit'            => $batch_limit,
		'current_time_gmt'       => $current_time_gmt,
		'bounded'                => true,
		'cleanup_policy'         => 'delete_expired_or_resolved_rows_in_bounded_batches',
		'saves_post'             => false,
		'mutates_post_content'   => false,
		'creates_revision'       => false,
		'changes_post_lock'      => false,
		'claims_saved'           => false,
		'exposes_raw_content'    => false,
	);

	if ( ! wp_de_rtc_review_items_table_exists() ) {
		return array_merge(
			$base_result,
			array(
				'result'        => 'review_items_table_missing',
				'deleted_count' => 0,
			)
		);
	}

	$table_sql = '`' . str_replace( '`', '``', $table_name ) . '`';
	$deleted   = $wpdb->query(
		$wpdb->prepare(
			"DELETE FROM $table_sql WHERE expires_at_gmt <= %s OR ( status <> 'pending' AND resolved_at_gmt IS NOT NULL AND resolved_at_gmt <= %s ) ORDER BY expires_at_gmt ASC LIMIT %d",
			$current_time_gmt,
			gmdate( 'Y-m-d H:i:s', strtotime( $current_time_gmt . ' UTC' ) - wp_de_rtc_get_review_items_pending_ttl_seconds() ),
			$batch_limit
		)
	);

	if ( false === $deleted ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_storage_failure',
			__( 'Distributed Editing review item cleanup failed.' ),
			array_merge(
				$base_result,
				array(
					'result'        => 'review_item_cleanup_storage_failure',
					'deleted_count' => 0,
				)
			)
		);
	}

	return array_merge(
		$base_result,
		array(
			'result'        => 'review_item_cleanup_completed',
			'deleted_count' => (int) $deleted,
		)
	);
}

/**
 * Returns a SQL-safe review-items table reference.
 *
 * @since 7.1.0
 * @access private
 *
 * @return string Escaped table reference.
 */
function wp_de_rtc_get_review_items_table_sql() {
	return '`' . str_replace( '`', '``', wp_de_rtc_get_review_items_table_name() ) . '`';
}

/**
 * Returns active pending review item counts for a post.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post Post ID or object.
 * @return int Pending review item count.
 */
function wp_de_rtc_get_pending_review_item_count_for_post( $post ) {
	global $wpdb;

	$post = get_post( $post );

	if ( ! $post || ! wp_de_rtc_review_items_table_exists() ) {
		return 0;
	}

	$table_sql = wp_de_rtc_get_review_items_table_sql();

	return (int) $wpdb->get_var(
		$wpdb->prepare(
			"SELECT COUNT(*) FROM $table_sql WHERE post_id = %d AND status = 'pending' AND expires_at_gmt > %s",
			(int) $post->ID,
			current_time( 'mysql', true )
		)
	);
}

/**
 * Returns the public descriptor for a stored review item row.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $row  Review item database row.
 * @param array $args Descriptor arguments.
 * @return array Public review item descriptor.
 */
function wp_de_rtc_get_review_item_public_descriptor( $row, $args = array() ) {
	$args = wp_parse_args(
		$args,
		array(
			'include_proposer_display_name' => false,
			'include_escaped_source'        => false,
			'current_time_gmt'              => current_time( 'mysql', true ),
			'current_user_id'               => get_current_user_id(),
			'can_review'                    => current_user_can( 'unfiltered_html' ),
		)
	);

	$status            = isset( $row['status'] ) ? sanitize_key( (string) $row['status'] ) : '';
	$current_timestamp = strtotime( (string) $args['current_time_gmt'] . ' UTC' );
	$expires_timestamp = isset( $row['expires_at_gmt'] ) ? strtotime( (string) $row['expires_at_gmt'] . ' UTC' ) : false;
	$effective_status  = ( 'pending' === $status && $expires_timestamp && $current_timestamp && $expires_timestamp <= $current_timestamp ) ? 'expired' : $status;
	$proposer_user_id  = isset( $row['proposer_user_id'] ) ? (int) $row['proposer_user_id'] : 0;
	$current_user_id   = isset( $args['current_user_id'] ) ? (int) $args['current_user_id'] : 0;
	$can_review        = ! empty( $args['can_review'] );
	$can_discard       = $proposer_user_id > 0 && $current_user_id === $proposer_user_id;
	$is_active_pending = wp_de_rtc_review_item_row_is_active_pending( $row, (string) $args['current_time_gmt'] );
	$descriptor        = array(
		'id'                         => isset( $row['public_id'] ) ? sanitize_text_field( (string) $row['public_id'] ) : '',
		'reviewItemId'               => isset( $row['public_id'] ) ? sanitize_text_field( (string) $row['public_id'] ) : '',
		'status'                     => $status,
		'effectiveStatus'            => $effective_status,
		'blockName'                  => isset( $row['block_name'] ) ? sanitize_text_field( (string) $row['block_name'] ) : '',
		'blockLabel'                 => isset( $row['block_label'] ) ? sanitize_text_field( (string) $row['block_label'] ) : '',
		'blockPath'                  => isset( $row['block_path'] ) && '' !== (string) $row['block_path'] ? array_map( 'absint', explode( '.', (string) $row['block_path'] ) ) : array(),
		'changeKind'                 => isset( $row['change_kind'] ) ? sanitize_key( (string) $row['change_kind'] ) : '',
		'riskReason'                 => isset( $row['risk_reason'] ) ? sanitize_key( (string) $row['risk_reason'] ) : '',
		'requiredCapability'         => isset( $row['required_capability'] ) ? sanitize_key( (string) $row['required_capability'] ) : 'unfiltered_html',
		'contentReviewPolicy'        => 'kses',
		'reviewEvidenceType'         => 'kses_block_encoded_source',
		'baseSyncVersion'            => isset( $row['base_sync_version'] ) ? sanitize_text_field( (string) $row['base_sync_version'] ) : '',
		'serverSyncVersion'          => isset( $row['server_sync_version'] ) ? sanitize_text_field( (string) $row['server_sync_version'] ) : '',
		'baseContentHash'            => isset( $row['base_content_hash'] ) ? sanitize_text_field( (string) $row['base_content_hash'] ) : '',
		'proposedContentHash'        => isset( $row['proposed_content_hash'] ) ? sanitize_text_field( (string) $row['proposed_content_hash'] ) : '',
		'ksesFilteredContentHash'    => isset( $row['kses_filtered_content_hash'] ) ? sanitize_text_field( (string) $row['kses_filtered_content_hash'] ) : '',
		'createdAtGmt'               => isset( $row['created_at_gmt'] ) ? mysql_to_rfc3339( (string) $row['created_at_gmt'] ) : '',
		'updatedAtGmt'               => isset( $row['updated_at_gmt'] ) ? mysql_to_rfc3339( (string) $row['updated_at_gmt'] ) : '',
		'expiresAtGmt'               => isset( $row['expires_at_gmt'] ) ? mysql_to_rfc3339( (string) $row['expires_at_gmt'] ) : '',
		'resolvedAtGmt'              => empty( $row['resolved_at_gmt'] ) ? null : mysql_to_rfc3339( (string) $row['resolved_at_gmt'] ),
		'resolutionAction'           => isset( $row['resolution_action'] ) ? sanitize_key( (string) $row['resolution_action'] ) : '',
		'sourceAvailable'            => ! empty( $row['encoded_proposed_source'] ),
		'contentTransport'           => 'descriptor_only',
		'encodedStorage'             => true,
		'canApprove'                 => $is_active_pending && $can_review,
		'canModifyAdopt'             => $is_active_pending && $can_review,
		'canReject'                  => $is_active_pending && $can_review,
		'canDiscard'                 => $is_active_pending && $can_discard,
		'rawContentIncluded'         => false,
		'exposesRawContent'          => false,
		'executable'                 => false,
		'savesPost'                  => false,
		'mutatesPostContent'         => false,
		'createsRevision'            => false,
		'claimsSaved'                => false,
	);

	if ( ! empty( $args['include_proposer_display_name'] ) ) {
		$descriptor['proposerDisplayName'] = isset( $row['proposer_display_name'] ) ? sanitize_text_field( (string) $row['proposer_display_name'] ) : __( 'Unknown editor' );
	}

	if ( ! empty( $args['include_escaped_source'] ) ) {
		$proposed_source = wp_de_rtc_base64url_decode( isset( $row['encoded_proposed_source'] ) ? (string) $row['encoded_proposed_source'] : '' );
		$filtered_source = wp_de_rtc_base64url_decode( isset( $row['encoded_kses_filtered_source'] ) ? (string) $row['encoded_kses_filtered_source'] : '' );

		$descriptor['contentTransport']         = 'html_escaped_text';
		$descriptor['proposedSourceDisplay']    = esc_html( $proposed_source );
		$descriptor['ksesFilteredSourceDisplay'] = esc_html( $filtered_source );
		$descriptor['proposedSourceLength']     = isset( $row['proposed_source_length'] ) ? (int) $row['proposed_source_length'] : strlen( $proposed_source );
		$descriptor['ksesFilteredSourceLength'] = isset( $row['kses_filtered_source_length'] ) ? (int) $row['kses_filtered_source_length'] : strlen( $filtered_source );
	}

	return $descriptor;
}

/**
 * Returns whether a review item row is still active pending work.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array       $row              Review item row.
 * @param string|null $current_time_gmt Optional current time in GMT.
 * @return bool Whether the row is active and pending.
 */
function wp_de_rtc_review_item_row_is_active_pending( $row, $current_time_gmt = null ) {
	if ( ! is_array( $row ) ) {
		return false;
	}

	$current_time_gmt    = null === $current_time_gmt ? current_time( 'mysql', true ) : (string) $current_time_gmt;
	$current_timestamp   = strtotime( $current_time_gmt . ' UTC' );
	$expires_at_gmt      = isset( $row['expires_at_gmt'] ) ? (string) $row['expires_at_gmt'] : '';
	$expires_timestamp   = '' === $expires_at_gmt ? false : strtotime( $expires_at_gmt . ' UTC' );
	$review_item_status  = isset( $row['status'] ) ? sanitize_key( (string) $row['status'] ) : '';

	return 'pending' === $review_item_status && false !== $expires_timestamp && false !== $current_timestamp && $expires_timestamp > $current_timestamp;
}

/**
 * Creates an archival logical key for a terminal review item row.
 *
 * Terminal review rows keep their public ID for audit/detail routing, but they
 * must release the active logical key so a later identical proposal can create
 * a fresh pending item instead of reviving old terminal state.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array  $row              Review item row.
 * @param string $current_time_gmt Current time in GMT.
 * @param string $reason           Archive reason.
 * @return string Archived logical key hash.
 */
function wp_de_rtc_get_archived_review_item_logical_key_hash( $row, $current_time_gmt, $reason = 'terminal' ) {
	$fields = array(
		isset( $row['review_item_id'] ) ? (int) $row['review_item_id'] : 0,
		isset( $row['public_id'] ) ? (string) $row['public_id'] : '',
		isset( $row['logical_key_hash'] ) ? (string) $row['logical_key_hash'] : '',
		sanitize_key( $reason ),
		(string) $current_time_gmt,
	);

	return hash_hmac( 'sha256', implode( '|', $fields ), wp_salt( 'auth' ) );
}

/**
 * Releases a review item's active logical key while preserving its audit row.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array  $row              Review item row.
 * @param string $current_time_gmt Current time in GMT.
 * @param string $reason           Archive reason.
 * @return bool Whether the archival update succeeded.
 */
function wp_de_rtc_archive_review_item_logical_key( $row, $current_time_gmt, $reason = 'terminal' ) {
	global $wpdb;

	if ( ! is_array( $row ) || empty( $row['review_item_id'] ) ) {
		return false;
	}

	$archived_key = wp_de_rtc_get_archived_review_item_logical_key_hash( $row, $current_time_gmt, $reason );

	return false !== $wpdb->update(
		wp_de_rtc_get_review_items_table_name(),
		array(
			'logical_key_hash' => $archived_key,
			'updated_at_gmt'   => $current_time_gmt,
		),
		array(
			'review_item_id' => (int) $row['review_item_id'],
		),
		array( '%s', '%s' ),
		array( '%d' )
	);
}

/**
 * Claims a pending review item before applying a reviewer write.
 *
 * The review item table is the authority for one-time review decisions. A
 * compare-and-set claim keeps two concurrent approval requests from both
 * saving the same stored proposal.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array  $row              Review item row.
 * @param string $action           Review action.
 * @param string $current_time_gmt Current time in GMT.
 * @return true|WP_Error True on success, otherwise a no-write error.
 */
function wp_de_rtc_claim_review_item_for_resolution( $row, $action, $current_time_gmt ) {
	global $wpdb;

	if ( ! is_array( $row ) || empty( $row['review_item_id'] ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_review_item_not_found',
			__( 'Distributed Editing could not find an active review item.' ),
			array(
				'detail'               => 'review_item_resolution_claim_missing_row',
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$table_sql = wp_de_rtc_get_review_items_table_sql();
	$updated   = $wpdb->query(
		$wpdb->prepare(
			"UPDATE $table_sql SET status = 'applying', updated_at_gmt = %s, resolved_by = %d, resolution_action = %s WHERE review_item_id = %d AND status = 'pending' AND expires_at_gmt > %s",
			(string) $current_time_gmt,
			get_current_user_id(),
			sanitize_key( $action ),
			(int) $row['review_item_id'],
			(string) $current_time_gmt
		)
	);

	if ( false === $updated ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_storage_failure',
			__( 'Distributed Editing could not claim the review item.' ),
			array(
				'detail'               => 'review_item_resolution_claim_storage_failure',
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	if ( 1 !== (int) $updated ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_review_item_not_found',
			__( 'Distributed Editing could not find an active review item.' ),
			array(
				'detail'               => 'review_item_resolution_claim_not_active_pending',
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	return true;
}

/**
 * Releases a review item claim after a failed reviewer write.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array  $row              Review item row.
 * @param string $current_time_gmt Current time in GMT.
 * @return void
 */
function wp_de_rtc_release_review_item_resolution_claim( $row, $current_time_gmt ) {
	global $wpdb;

	if ( ! is_array( $row ) || empty( $row['review_item_id'] ) ) {
		return;
	}

	$wpdb->update(
		wp_de_rtc_get_review_items_table_name(),
		array(
			'status'            => 'pending',
			'updated_at_gmt'    => (string) $current_time_gmt,
			'resolved_by'       => 0,
			'resolution_action' => '',
		),
		array(
			'review_item_id' => (int) $row['review_item_id'],
			'status'         => 'applying',
		),
		array( '%s', '%s', '%d', '%s' ),
		array( '%d', '%s' )
	);
}

/**
 * Supersedes older active pending review items for the same proposer/block.
 *
 * A modified unsafe retry should replace the prior proposal for that block. It
 * must not leave parallel active rows that make the sidebar look like multiple
 * unresolved decisions for one current local proposal.
 *
 * @since 7.1.0
 * @access private
 *
 * @param WP_Post $post             Post object.
 * @param int     $proposer_user_id Proposer user ID.
 * @param string  $block_path       Serialized block path.
 * @param string  $change_kind      Change kind.
 * @param int     $current_item_id  Review item ID that remains active.
 * @param string  $current_time_gmt Current time in GMT.
 * @return int Number of superseded rows.
 */
function wp_de_rtc_supersede_active_review_items_for_same_anchor( $post, $proposer_user_id, $block_path, $change_kind, $current_item_id, $current_time_gmt ) {
	global $wpdb;

	if ( ! $post || '' === (string) $block_path || '' === (string) $change_kind || ! wp_de_rtc_review_items_table_exists() ) {
		return 0;
	}

	$table_sql = wp_de_rtc_get_review_items_table_sql();
	$rows      = $wpdb->get_results(
		$wpdb->prepare(
			"SELECT * FROM $table_sql WHERE post_id = %d AND proposer_user_id = %d AND block_path = %s AND change_kind = %s AND status = 'pending' AND expires_at_gmt > %s AND review_item_id <> %d",
			(int) $post->ID,
			(int) $proposer_user_id,
			(string) $block_path,
			sanitize_key( $change_kind ),
			(string) $current_time_gmt,
			(int) $current_item_id
		),
		ARRAY_A
	);

	if ( ! is_array( $rows ) || empty( $rows ) ) {
		return 0;
	}

	$superseded = 0;
	foreach ( $rows as $row ) {
		$updated = $wpdb->update(
			wp_de_rtc_get_review_items_table_name(),
			array(
				'logical_key_hash' => wp_de_rtc_get_archived_review_item_logical_key_hash( $row, $current_time_gmt, 'superseded' ),
				'status'           => 'superseded',
				'updated_at_gmt'   => $current_time_gmt,
				'resolved_at_gmt'  => $current_time_gmt,
				'resolved_by'      => (int) $proposer_user_id,
				'resolution_action' => 'superseded',
			),
			array(
				'review_item_id' => (int) $row['review_item_id'],
			),
			array( '%s', '%s', '%s', '%s', '%d', '%s' ),
			array( '%d' )
		);

		if ( false !== $updated ) {
			++$superseded;
		}
	}

	return $superseded;
}

/**
 * Returns non-empty parsed blocks for a review-item replacement source.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $source Serialized block source.
 * @return array[] Parsed replacement blocks.
 */
function wp_de_rtc_get_review_item_replacement_blocks( $source ) {
	$blocks = parse_blocks( (string) $source );

	return array_values(
		array_filter(
			$blocks,
			static function ( $block ) {
				if ( ! is_array( $block ) ) {
					return false;
				}

				return ! empty( $block['blockName'] ) || '' !== trim( serialize_block( $block ) );
			}
		)
	);
}

/**
 * Applies a review item replacement to parsed blocks by retained block path.
 *
 * The stored review path uses the same retained-block indexing as KSES review
 * classification, skipping empty freeform separators. This keeps approval from
 * depending on Gutenberg client IDs or whitespace-only parser artifacts.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $blocks             Parsed blocks.
 * @param int[] $path               Retained block path.
 * @param string $change_kind       Review change kind.
 * @param array $replacement_blocks Replacement parsed blocks.
 * @param bool  $applied            Whether a change was applied.
 * @return array Updated parsed blocks.
 */
function wp_de_rtc_apply_review_item_blocks_at_path( $blocks, $path, $change_kind, $replacement_blocks, &$applied ) {
	$target_index   = isset( $path[0] ) ? absint( $path[0] ) : 0;
	$retained_index = 0;

	foreach ( $blocks as $real_index => $block ) {
		if ( ! is_array( $block ) ) {
			continue;
		}

		if ( empty( $block['blockName'] ) && '' === trim( serialize_block( $block ) ) ) {
			continue;
		}

		if ( $retained_index === $target_index ) {
			if ( count( $path ) > 1 ) {
				$block['innerBlocks'] = wp_de_rtc_apply_review_item_blocks_at_path(
					isset( $block['innerBlocks'] ) && is_array( $block['innerBlocks'] ) ? $block['innerBlocks'] : array(),
					array_slice( $path, 1 ),
					$change_kind,
					$replacement_blocks,
					$applied
				);
				$blocks[ $real_index ] = $block;

				return $blocks;
			}

			if ( 'added_block' === $change_kind ) {
				array_splice( $blocks, $real_index, 0, $replacement_blocks );
			} elseif ( 'deleted_block' === $change_kind ) {
				array_splice( $blocks, $real_index, 1 );
			} else {
				array_splice( $blocks, $real_index, 1, $replacement_blocks );
			}

			$applied = true;

			return $blocks;
		}

		++$retained_index;
	}

	if ( ! $applied && 1 === count( $path ) && 'added_block' === $change_kind && $target_index === $retained_index ) {
		array_splice( $blocks, count( $blocks ), 0, $replacement_blocks );
		$applied = true;
	}

	return $blocks;
}

/**
 * Applies one approved review item to stripped post content.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $post_content       Current stripped post content.
 * @param array  $row                Review item row.
 * @param string $replacement_source Serialized replacement source.
 * @return string|WP_Error Updated stripped post content.
 */
function wp_de_rtc_apply_review_item_to_stripped_content( $post_content, $row, $replacement_source ) {
	$change_kind = isset( $row['change_kind'] ) ? sanitize_key( (string) $row['change_kind'] ) : '';
	$block_path  = isset( $row['block_path'] ) && '' !== (string) $row['block_path'] ? array_map( 'absint', explode( '.', (string) $row['block_path'] ) ) : array();

	if ( empty( $block_path ) || ! in_array( $change_kind, array( 'added_block', 'modified_block', 'deleted_block' ), true ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing could not apply the review item because its block location is invalid.' ),
			array(
				'detail'               => 'review_item_apply_invalid_block_path',
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$replacement_blocks = 'deleted_block' === $change_kind ? array() : wp_de_rtc_get_review_item_replacement_blocks( $replacement_source );

	if ( 'deleted_block' !== $change_kind && 1 !== count( $replacement_blocks ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing could not apply the review item because its replacement block is invalid.' ),
			array(
				'detail'               => 'review_item_apply_invalid_replacement_block',
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$applied = false;
	$blocks  = wp_de_rtc_apply_review_item_blocks_at_path(
		parse_blocks( (string) $post_content ),
		$block_path,
		$change_kind,
		$replacement_blocks,
		$applied
	);

	if ( ! $applied ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_rebase_failed',
			__( 'Distributed Editing could not apply the review item because the block location changed.' ),
			array(
				'detail'               => 'review_item_apply_block_location_changed',
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	return serialize_blocks( $blocks );
}

/**
 * Applies an approved or reviewer-modified review item to the canonical post.
 *
 * @since 7.1.0
 *
 * @param WP_Post $post              Post object.
 * @param array   $row               Review item row.
 * @param array   $args              Apply args.
 * @return array|WP_Error Apply result.
 */
function wp_de_rtc_apply_review_item_resolution_to_post( $post, $row, $args = array() ) {
	global $wpdb;

	$args   = wp_parse_args(
		$args,
		array(
			'action'                => 'approve',
			'reviewed_block_source' => null,
		)
	);
	$action = sanitize_key( (string) $args['action'] );

	if ( ! $post || ! is_array( $row ) || ! in_array( $action, array( 'approve', 'modify-adopt' ), true ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing could not apply the review item.' ),
			array(
				'detail'               => 'review_item_apply_invalid_request',
				'post_id'              => $post ? (int) $post->ID : 0,
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	if ( ! wp_de_rtc_review_item_row_is_active_pending( $row ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_review_item_not_found',
			__( 'Distributed Editing could not find an active review item.' ),
			array(
				'detail'               => 'review_item_apply_not_active_pending',
				'post_id'              => (int) $post->ID,
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$current = wp_de_rtc_parse_post_content_sync_meta( $post->post_content );

	if ( is_wp_error( $current ) || ! is_array( $current ) || ! is_array( $current['sync_meta'] ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing could not apply the review item because sync metadata is unavailable.' ),
			array(
				'detail'               => 'review_item_apply_current_sync_meta_unavailable',
				'post_id'              => (int) $post->ID,
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$stored_source      = wp_de_rtc_base64url_decode( isset( $row['encoded_proposed_source'] ) ? (string) $row['encoded_proposed_source'] : '' );
	$replacement_source = 'modify-adopt' === $action && is_string( $args['reviewed_block_source'] )
		? (string) $args['reviewed_block_source']
		: $stored_source;

	if ( 'approve' === $action && ! hash_equals( (string) $row['proposed_content_hash'], wp_de_rtc_hash_content( $stored_source ) ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the review item because its stored proposal changed.' ),
			array(
				'detail'               => 'review_item_apply_stored_proposal_hash_mismatch',
				'post_id'              => (int) $post->ID,
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$next_stripped_content = wp_de_rtc_apply_review_item_to_stripped_content(
		(string) $current['content'],
		$row,
		$replacement_source
	);

	if ( is_wp_error( $next_stripped_content ) ) {
		return $next_stripped_content;
	}

	$previous_version = isset( $current['sync_meta']['version'] ) ? sanitize_text_field( (string) $current['sync_meta']['version'] ) : '';
	$content_hash     = wp_de_rtc_hash_content( $next_stripped_content );
	$next_version     = wp_de_rtc_get_next_sync_meta_version( $previous_version, $content_hash );
	$next_sync_meta   = $current['sync_meta'];

	$next_sync_meta['version']            = $next_version;
	$next_sync_meta['previous_version']   = $previous_version;
	$next_sync_meta['post_content_hash']  = $content_hash;
	$next_sync_meta['content_hash']       = $content_hash;
	$next_sync_meta['last_server_update'] = array(
		'type'                => 'review_item_' . str_replace( '-', '_', $action ),
		'user_id'             => get_current_user_id(),
		'session_label'       => wp_de_rtc_get_history_author_display_name( get_current_user_id() ),
		'review_item_id'      => isset( $row['public_id'] ) ? (string) $row['public_id'] : '',
		'proposer_actor_hash' => isset( $row['proposer_actor_hash'] ) ? (string) $row['proposer_actor_hash'] : '',
		'block_path'          => isset( $row['block_path'] ) ? (string) $row['block_path'] : '',
		'content_hash'        => $content_hash,
	);

	$next_post_content = wp_de_rtc_add_sync_meta_to_post_content(
		$next_stripped_content,
		$current['sync_meta_format'],
		$next_sync_meta,
		$current['sync_meta_position']
	);

	if ( is_wp_error( $next_post_content ) ) {
		return $next_post_content;
	}

	$now_gmt = current_time( 'mysql', true );
	$claim   = wp_de_rtc_claim_review_item_for_resolution( $row, $action, $now_gmt );

	if ( is_wp_error( $claim ) ) {
		return $claim;
	}

	$revision_ids_before_save = wp_de_rtc_get_post_revision_ids( $post->ID );

	wp_de_rtc_enable_sync_meta_script_kses_allowance();

	global $wp_de_rtc_retry_save_candidate_post_content;

	if ( ! is_array( $wp_de_rtc_retry_save_candidate_post_content ) ) {
		$wp_de_rtc_retry_save_candidate_post_content = array();
	}

	$wp_de_rtc_retry_save_candidate_post_content[ (int) $post->ID ] = $next_post_content;

	try {
		$update_result = wp_update_post(
			wp_slash(
				array(
					'ID'           => (int) $post->ID,
					'post_content' => $next_post_content,
				)
			),
			true
		);
	} finally {
		unset( $wp_de_rtc_retry_save_candidate_post_content[ (int) $post->ID ] );
		wp_de_rtc_disable_sync_meta_script_kses_allowance();
	}

	if ( is_wp_error( $update_result ) ) {
		wp_de_rtc_release_review_item_resolution_claim( $row, current_time( 'mysql', true ) );
		return $update_result;
	}

	$now_gmt         = current_time( 'mysql', true );
	$resolved_status = 'modify-adopt' === $action ? 'modified_adopted' : 'approved';
	$archived_key    = wp_de_rtc_get_archived_review_item_logical_key_hash( $row, $now_gmt, $resolved_status );
	$updated         = $wpdb->update(
		wp_de_rtc_get_review_items_table_name(),
		array(
			'logical_key_hash' => $archived_key,
			'status'            => $resolved_status,
			'updated_at_gmt'    => $now_gmt,
			'resolved_at_gmt'   => $now_gmt,
			'resolved_by'       => get_current_user_id(),
			'resolution_action' => $action,
		),
		array(
			'review_item_id' => (int) $row['review_item_id'],
			'status'         => 'applying',
		),
		array( '%s', '%s', '%s', '%s', '%d', '%s' ),
		array( '%d', '%s' )
	);

	if ( false === $updated || 1 !== (int) $updated ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_storage_failure',
			__( 'Distributed Editing saved the reviewed block but could not update review state.' ),
			array(
				'detail'               => 'review_item_apply_resolution_storage_failure',
				'post_id'              => (int) $post->ID,
				'raw_content_included' => false,
				'saves_post'           => true,
				'mutates_post_content' => true,
				'creates_revision'     => true,
				'claims_saved'         => true,
			)
		);
	}

	$row['logical_key_hash']  = $archived_key;
	$row['status']            = $resolved_status;
	$row['updated_at_gmt']    = $now_gmt;
	$row['resolved_at_gmt']   = $now_gmt;
	$row['resolved_by']       = get_current_user_id();
	$row['resolution_action'] = $action;

	$revision_ids_after_save = wp_de_rtc_get_post_revision_ids( $post->ID );

	return array(
		'result'                   => 'review_item_' . $resolved_status,
		'item'                     => wp_de_rtc_get_review_item_public_descriptor(
			$row,
			array(
				'include_proposer_display_name' => true,
			)
		),
		'content'                  => array(
			'raw' => get_post( $post->ID )->post_content,
		),
		'previousServerVersion'    => $previous_version,
		'serverVersion'            => $next_version,
		'savedStrippedContentHash' => $content_hash,
		'revisionIdsBeforeSave'    => $revision_ids_before_save,
		'revisionIdsAfterSave'     => $revision_ids_after_save,
		'createdRevisionIds'       => array_values( array_diff( $revision_ids_after_save, $revision_ids_before_save ) ),
		'revisionCreated'          => $revision_ids_after_save !== $revision_ids_before_save,
		'rawContentIncluded'       => false,
		'exposesRawContent'        => false,
		'savesPost'                => true,
		'mutatesPostContent'       => true,
		'createsRevision'          => true,
		'claimsSaved'              => true,
	);
}

/**
 * Returns a stored review item row by public ID.
 *
 * @since 7.1.0
 * @access private
 *
 * @param int|WP_Post $post      Post ID or object.
 * @param string      $public_id Public review item ID.
 * @return array|null Review item row.
 */
function wp_de_rtc_get_review_item_row( $post, $public_id ) {
	global $wpdb;

	$post      = get_post( $post );
	$public_id = wp_de_rtc_sanitize_review_item_public_id( $public_id );

	if ( ! $post || '' === $public_id || ! wp_de_rtc_review_items_table_exists() ) {
		return null;
	}

	$table_sql = wp_de_rtc_get_review_items_table_sql();

	return $wpdb->get_row(
		$wpdb->prepare(
			"SELECT * FROM $table_sql WHERE post_id = %d AND public_id = %s LIMIT 1",
			(int) $post->ID,
			$public_id
		),
		ARRAY_A
	);
}

/**
 * Returns stored review item descriptors for a post.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post Post ID or object.
 * @param array       $args Read args.
 * @return array|WP_Error Review item list response.
 */
function wp_de_rtc_get_review_items_for_post( $post, $args = array() ) {
	global $wpdb;

	$post = get_post( $post );

	if ( ! $post ) {
		return new WP_Error(
			'rest_post_invalid_id',
			__( 'Invalid post ID.' ),
			array( 'status' => 404 )
		);
	}

	if ( ! wp_de_rtc_review_items_table_exists() ) {
		return array(
			'result'                   => 'review_items_storage_unavailable',
			'post_id'                  => (int) $post->ID,
			'items'                    => array(),
			'count'                    => 0,
			'pendingReviewItemCount'   => 0,
			'storageReady'             => false,
			'rawContentIncluded'       => false,
			'exposesRawContent'        => false,
			'savesPost'                => false,
			'mutatesPostContent'       => false,
			'createsRevision'          => false,
			'claimsSaved'              => false,
		);
	}

	wp_de_rtc_cleanup_review_items();

	$args                = wp_parse_args(
		$args,
		array(
			'current_user_id' => get_current_user_id(),
			'can_review'      => current_user_can( 'unfiltered_html' ),
			'limit'           => 50,
		)
	);
	$current_time_gmt    = current_time( 'mysql', true );
	$table_sql           = wp_de_rtc_get_review_items_table_sql();
	$limit               = max( 1, min( 100, absint( $args['limit'] ) ) );
	$where_clauses       = array( 'post_id = %d', 'status = %s', 'expires_at_gmt > %s' );
	$where_values        = array( (int) $post->ID, 'pending', $current_time_gmt );
	$include_proposer    = (bool) $args['can_review'];

	if ( ! $args['can_review'] ) {
		$where_clauses[] = 'proposer_user_id = %d';
		$where_values[]  = (int) $args['current_user_id'];
	}

	$where_sql             = implode( ' AND ', $where_clauses );
	$visible_pending_count = (int) $wpdb->get_var(
		$wpdb->prepare(
			"SELECT COUNT(*) FROM $table_sql WHERE $where_sql",
			$where_values
		)
	);
	$post_pending_count    = wp_de_rtc_get_pending_review_item_count_for_post( $post );
	$rows                  = $wpdb->get_results(
		$wpdb->prepare(
			"SELECT * FROM $table_sql WHERE $where_sql ORDER BY created_at_gmt ASC LIMIT %d",
			array_merge( $where_values, array( $limit ) )
		),
		ARRAY_A
	);

	if ( ! is_array( $rows ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_storage_failure',
			__( 'Distributed Editing could not read review items.' ),
			array(
				'detail'               => 'review_item_list_storage_failure',
				'post_id'              => (int) $post->ID,
				'rest_route'           => 'post_review_items',
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$current_user_id = (int) $args['current_user_id'];
	$can_review      = (bool) $args['can_review'];
	$items = array_map(
		static function ( $row ) use ( $include_proposer, $current_time_gmt, $current_user_id, $can_review ) {
			return wp_de_rtc_get_review_item_public_descriptor(
				$row,
				array(
					'include_proposer_display_name' => $include_proposer,
					'current_time_gmt'              => $current_time_gmt,
					'current_user_id'               => $current_user_id,
					'can_review'                    => $can_review,
				)
			);
		},
		$rows
	);

	return array(
		'result'                   => 'review_items_loaded',
		'post_id'                  => (int) $post->ID,
		'items'                    => $items,
		'count'                    => count( $items ),
		'pendingReviewItemCount'     => $visible_pending_count,
		'postPendingReviewItemCount' => $post_pending_count,
		'storageReady'             => true,
		'canReviewUnfilteredHtml'  => (bool) $args['can_review'],
		'descriptorOnly'           => true,
		'rawContentIncluded'       => false,
		'exposesRawContent'        => false,
		'savesPost'                => false,
		'mutatesPostContent'       => false,
		'createsRevision'          => false,
		'claimsSaved'              => false,
	);
}

/**
 * Returns source records keyed by block path for review item storage.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $post_content Stripped post content.
 * @return array Source records.
 */
function wp_de_rtc_get_review_item_source_records( $post_content ) {
	return wp_de_rtc_get_kses_block_review_records( (string) $post_content );
}

/**
 * Returns a storage source pair for a hash-only review item.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array  $review_item      Hash-only review item.
 * @param string $base_content     Base stripped post content.
 * @param string $proposed_content Proposed stripped post content.
 * @return array|WP_Error Source pair.
 */
function wp_de_rtc_get_review_item_storage_source_pair( $review_item, $base_content, $proposed_content ) {
	$block_path  = isset( $review_item['block_path'] ) && is_array( $review_item['block_path'] ) ? array_values( array_map( 'absint', $review_item['block_path'] ) ) : array();
	$path_key    = implode( '.', $block_path );
	$change_kind = isset( $review_item['change_kind'] ) ? sanitize_key( (string) $review_item['change_kind'] ) : '';
	$base_records = wp_de_rtc_get_review_item_source_records( $base_content );
	$proposed_records = wp_de_rtc_get_review_item_source_records( $proposed_content );
	$base_record = isset( $base_records[ $path_key ] ) ? $base_records[ $path_key ] : null;
	$proposed_record = isset( $proposed_records[ $path_key ] ) ? $proposed_records[ $path_key ] : null;

	if ( in_array( $change_kind, array( 'added_block', 'modified_block' ), true ) && ! is_array( $proposed_record ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing could not store the review item because the proposed block was unavailable.' ),
			array(
				'detail'               => 'review_item_proposed_block_source_missing',
				'block_path'           => $block_path,
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	if ( 'deleted_block' === $change_kind && ! is_array( $base_record ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing could not store the review item because the base block was unavailable.' ),
			array(
				'detail'               => 'review_item_base_block_source_missing',
				'block_path'           => $block_path,
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$proposed_source = is_array( $proposed_record ) ? (string) $proposed_record['serialized_block'] : '';
	$filtered_source = wp_filter_post_kses( $proposed_source );

	if ( 'deleted_block' === $change_kind ) {
		$proposed_source = '';
		$filtered_source = '';
	}

	$proposed_hash = isset( $review_item['proposed_content_hash'] ) ? sanitize_text_field( (string) $review_item['proposed_content_hash'] ) : '';
	$filtered_hash = isset( $review_item['kses_filtered_content_hash'] ) ? sanitize_text_field( (string) $review_item['kses_filtered_content_hash'] ) : '';

	if ( '' !== $proposed_hash && ! hash_equals( $proposed_hash, wp_de_rtc_hash_content( $proposed_source ) ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the review item because its proposed block hash changed.' ),
			array(
				'detail'               => 'review_item_proposed_hash_mismatch',
				'block_path'           => $block_path,
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	if ( '' !== $filtered_hash && ! hash_equals( $filtered_hash, wp_de_rtc_hash_content( $filtered_source ) ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the review item because its filtered block hash changed.' ),
			array(
				'detail'               => 'review_item_filtered_hash_mismatch',
				'block_path'           => $block_path,
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	return array(
		'base_source'     => is_array( $base_record ) ? (string) $base_record['serialized_block'] : '',
		'proposed_source' => $proposed_source,
		'filtered_source' => $filtered_source,
	);
}

/**
 * Creates a stable dedupe key for a review-required item.
 *
 * @since 7.1.0
 * @access private
 *
 * @param WP_Post $post        Post object.
 * @param array   $review_item Hash-only review item.
 * @return string Dedupe hash.
 */
function wp_de_rtc_get_review_item_logical_key_hash( $post, $review_item ) {
	$block_path = isset( $review_item['block_path'] ) && is_array( $review_item['block_path'] ) ? implode( '.', array_map( 'absint', $review_item['block_path'] ) ) : '';
	$fields     = array(
		(int) $post->ID,
		get_current_user_id(),
		$block_path,
		isset( $review_item['change_kind'] ) ? sanitize_key( (string) $review_item['change_kind'] ) : '',
		isset( $review_item['base_version'] ) ? sanitize_text_field( (string) $review_item['base_version'] ) : '',
		isset( $review_item['server_version'] ) ? sanitize_text_field( (string) $review_item['server_version'] ) : '',
		isset( $review_item['base_content_hash'] ) ? sanitize_text_field( (string) $review_item['base_content_hash'] ) : '',
		isset( $review_item['proposed_content_hash'] ) ? sanitize_text_field( (string) $review_item['proposed_content_hash'] ) : '',
		isset( $review_item['kses_filtered_content_hash'] ) ? sanitize_text_field( (string) $review_item['kses_filtered_content_hash'] ) : '',
	);

	return hash_hmac( 'sha256', implode( '|', $fields ), wp_salt( 'auth' ) );
}

/**
 * Records review-required block proposals for the current save attempt.
 *
 * Safe edits may already have been persisted when this helper runs. Storage
 * failure therefore degrades the review queue instead of rolling back the safe
 * server copy; the response evidence makes that degradation explicit.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post         Post ID or object.
 * @param array       $review_items Hash-only review items.
 * @param array       $args         Record arguments.
 * @return array Review item queue result.
 */
function wp_de_rtc_record_review_required_items( $post, $review_items, $args = array() ) {
	global $wpdb;

	$post = get_post( $post );

	if ( ! $post || empty( $review_items ) || ! is_array( $review_items ) ) {
		return array(
			'review_item_queue_status'       => 'not_needed',
			'review_item_queue_results'      => array(),
			'review_item_descriptors'        => array(),
			'review_item_queued_count'       => 0,
			'review_item_deduplicated_count' => 0,
			'review_item_not_queued_count'   => 0,
			'raw_content_included'           => false,
		);
	}

	if ( ! wp_de_rtc_review_items_table_schema_current() ) {
		wp_de_rtc_install_review_items_table();
	}

	if ( ! wp_de_rtc_review_items_table_schema_current() ) {
		return array(
			'review_item_queue_status'      => 'not_queued',
			'review_item_queue_results'     => array(),
			'review_item_descriptors'       => array(),
			'review_item_queued_count'      => 0,
			'review_item_deduplicated_count' => 0,
			'review_item_not_queued_count'  => count( $review_items ),
			'review_item_not_queued_reason' => 'review_item_storage_unavailable',
			'storage_ready'                 => false,
			'raw_content_included'          => false,
		);
	}

	wp_de_rtc_cleanup_review_items();

	$args              = wp_parse_args(
		$args,
		array(
			'base_post_content'      => '',
			'proposed_post_content'  => '',
			'server_version'         => '',
			'client_base_version'    => '',
			'current_time_gmt'       => current_time( 'mysql', true ),
		)
	);
	$table_sql         = wp_de_rtc_get_review_items_table_sql();
	$current_time_gmt  = (string) $args['current_time_gmt'];

	if ( '' === $current_time_gmt || false === strtotime( $current_time_gmt . ' UTC' ) ) {
		$current_time_gmt = current_time( 'mysql', true );
	}

	$expires_at_gmt    = gmdate( 'Y-m-d H:i:s', strtotime( $current_time_gmt . ' UTC' ) + wp_de_rtc_get_review_items_pending_ttl_seconds() );
	$current_user_id   = get_current_user_id();
	$current_user      = get_userdata( $current_user_id );
	$display_name      = $current_user && is_string( $current_user->display_name ) && '' !== trim( $current_user->display_name ) ? $current_user->display_name : __( 'Unknown editor' );
	$queued_count      = 0;
	$deduped_count     = 0;
	$not_queued_count  = 0;
	$results           = array();
	$descriptors       = array();

	foreach ( array_values( $review_items ) as $review_item ) {
		if ( ! is_array( $review_item ) ) {
			++$not_queued_count;
			$results[] = array(
				'status' => 'not_queued',
				'reason' => 'malformed_review_item',
			);
			continue;
		}

		$logical_key_hash = wp_de_rtc_get_review_item_logical_key_hash( $post, $review_item );
		$existing_row     = $wpdb->get_row(
			$wpdb->prepare(
				"SELECT * FROM $table_sql WHERE logical_key_hash = %s LIMIT 1",
				$logical_key_hash
			),
			ARRAY_A
		);

		if ( is_array( $existing_row ) ) {
			if ( wp_de_rtc_review_item_row_is_active_pending( $existing_row, $current_time_gmt ) ) {
				$wpdb->update(
					wp_de_rtc_get_review_items_table_name(),
					array(
						'updated_at_gmt' => $current_time_gmt,
						'expires_at_gmt' => $expires_at_gmt,
					),
					array(
						'review_item_id' => (int) $existing_row['review_item_id'],
					),
					array( '%s', '%s' ),
					array( '%d' )
				);
				$existing_row['updated_at_gmt'] = $current_time_gmt;
				$existing_row['expires_at_gmt'] = $expires_at_gmt;
				++$deduped_count;
				$descriptor    = wp_de_rtc_get_review_item_public_descriptor( $existing_row );
				$descriptors[] = $descriptor;
				$results[]     = array(
					'status'       => 'deduplicated',
					'reviewItemId' => $descriptor['reviewItemId'],
				);
				continue;
			}

			/*
			 * Terminal rows are audit evidence, not active proposals. Release
			 * their logical key before inserting so a deliberate retry creates a
			 * new pending item instead of making the old decision look alive.
			 */
			wp_de_rtc_archive_review_item_logical_key( $existing_row, $current_time_gmt, 'terminal_requeue' );
		}

		$block_path  = isset( $review_item['block_path'] ) && is_array( $review_item['block_path'] ) ? implode( '.', array_map( 'absint', $review_item['block_path'] ) ) : '';
		$change_kind = isset( $review_item['change_kind'] ) ? sanitize_key( (string) $review_item['change_kind'] ) : '';
		$post_pending_count = (int) $wpdb->get_var(
			$wpdb->prepare(
				"SELECT COUNT(*) FROM $table_sql WHERE post_id = %d AND status = 'pending' AND expires_at_gmt > %s AND NOT ( proposer_user_id = %d AND block_path = %s AND change_kind = %s )",
				(int) $post->ID,
				$current_time_gmt,
				$current_user_id,
				$block_path,
				$change_kind
			)
		);
		$user_pending_count = (int) $wpdb->get_var(
			$wpdb->prepare(
				"SELECT COUNT(*) FROM $table_sql WHERE proposer_user_id = %d AND status = 'pending' AND expires_at_gmt > %s AND NOT ( post_id = %d AND block_path = %s AND change_kind = %s )",
				$current_user_id,
				$current_time_gmt,
				(int) $post->ID,
				$block_path,
				$change_kind
			)
		);

		if (
			$post_pending_count >= wp_de_rtc_get_review_items_per_post_limit() ||
			$user_pending_count >= wp_de_rtc_get_review_items_per_proposer_limit()
		) {
			++$not_queued_count;
			$results[] = array(
				'status' => 'not_queued',
				'reason' => 'review_item_limit_exceeded',
			);
			continue;
		}

		$source_pair = wp_de_rtc_get_review_item_storage_source_pair(
			$review_item,
			(string) $args['base_post_content'],
			(string) $args['proposed_post_content']
		);

		if ( is_wp_error( $source_pair ) ) {
			++$not_queued_count;
			$results[] = array(
				'status' => 'not_queued',
				'reason' => $source_pair->get_error_code(),
			);
			continue;
		}

		$proposed_source = (string) $source_pair['proposed_source'];
		$filtered_source = (string) $source_pair['filtered_source'];

		if (
			strlen( $proposed_source ) > wp_de_rtc_get_review_item_max_source_bytes() ||
			strlen( $filtered_source ) > wp_de_rtc_get_review_item_max_source_bytes()
		) {
			++$not_queued_count;
			$results[] = array(
				'status' => 'not_queued',
				'reason' => 'review_item_payload_too_large',
			);
			continue;
		}

		$base_hash        = isset( $review_item['base_content_hash'] ) ? sanitize_text_field( (string) $review_item['base_content_hash'] ) : '';
		$proposed_hash    = isset( $review_item['proposed_content_hash'] ) ? sanitize_text_field( (string) $review_item['proposed_content_hash'] ) : '';
		$filtered_hash    = isset( $review_item['kses_filtered_content_hash'] ) ? sanitize_text_field( (string) $review_item['kses_filtered_content_hash'] ) : '';
		$public_id        = wp_de_rtc_generate_review_item_public_id();
		$inserted         = $wpdb->insert(
			wp_de_rtc_get_review_items_table_name(),
			array(
				'public_id'                    => $public_id,
				'logical_key_hash'             => $logical_key_hash,
				'post_id'                      => (int) $post->ID,
				'post_type'                    => sanitize_key( $post->post_type ),
				'proposer_user_id'             => $current_user_id,
				'proposer_actor_hash'          => wp_de_rtc_get_presence_actor_hash( $current_user_id ),
				'proposer_display_name'        => sanitize_text_field( $display_name ),
				'status'                       => 'pending',
				'required_capability'          => 'unfiltered_html',
				'base_sync_version'            => isset( $review_item['base_version'] ) ? sanitize_text_field( (string) $review_item['base_version'] ) : sanitize_text_field( (string) $args['client_base_version'] ),
				'server_sync_version'          => isset( $review_item['server_version'] ) ? sanitize_text_field( (string) $review_item['server_version'] ) : sanitize_text_field( (string) $args['server_version'] ),
				'base_content_hash'            => $base_hash,
				'proposed_content_hash'        => $proposed_hash,
				'kses_filtered_content_hash'   => $filtered_hash,
				'block_anchor_hash'            => hash( 'sha256', $block_path . '|' . $base_hash . '|' . $proposed_hash ),
				'block_path'                   => $block_path,
				'block_name'                   => isset( $review_item['block_name'] ) ? sanitize_text_field( (string) $review_item['block_name'] ) : '',
				'block_label'                  => isset( $review_item['block_label'] ) ? sanitize_text_field( (string) $review_item['block_label'] ) : '',
				'change_kind'                  => isset( $review_item['change_kind'] ) ? sanitize_key( (string) $review_item['change_kind'] ) : '',
				'risk_reason'                  => isset( $review_item['risk_reason'] ) ? sanitize_key( (string) $review_item['risk_reason'] ) : '',
				'encoded_proposed_source'      => wp_de_rtc_base64url_encode( $proposed_source ),
				'encoded_kses_filtered_source' => wp_de_rtc_base64url_encode( $filtered_source ),
				'proposed_source_length'       => strlen( $proposed_source ),
				'kses_filtered_source_length'  => strlen( $filtered_source ),
				'render_as'                    => 'text',
				'executable'                   => 0,
				'created_at_gmt'               => $current_time_gmt,
				'updated_at_gmt'               => $current_time_gmt,
				'expires_at_gmt'               => $expires_at_gmt,
			),
			array(
				'%s',
				'%s',
				'%d',
				'%s',
				'%d',
				'%s',
				'%s',
				'%s',
				'%s',
				'%s',
				'%s',
				'%s',
				'%s',
				'%s',
				'%s',
				'%s',
				'%s',
				'%s',
				'%s',
				'%s',
				'%s',
				'%s',
				'%s',
				'%d',
				'%d',
				'%s',
				'%d',
				'%s',
				'%s',
				'%s',
			)
		);

		if ( false === $inserted ) {
			++$not_queued_count;
			$results[] = array(
				'status' => 'not_queued',
				'reason' => 'review_item_storage_failure',
			);
			continue;
		}

		++$queued_count;
		$row = wp_de_rtc_get_review_item_row( $post, $public_id );
		$superseded_count = wp_de_rtc_supersede_active_review_items_for_same_anchor(
			$post,
			$current_user_id,
			$block_path,
			$change_kind,
			is_array( $row ) && isset( $row['review_item_id'] ) ? (int) $row['review_item_id'] : 0,
			$current_time_gmt
		);
		$descriptor = wp_de_rtc_get_review_item_public_descriptor( is_array( $row ) ? $row : array( 'public_id' => $public_id ) );
		$descriptors[] = $descriptor;
		$results[]     = array(
			'status'          => 'queued',
			'reviewItemId'    => $descriptor['reviewItemId'],
			'supersededCount' => $superseded_count,
		);
	}

	$status = 'queued';
	if ( 0 === $queued_count && $deduped_count > 0 && 0 === $not_queued_count ) {
		$status = 'deduplicated';
	} elseif ( 0 === $queued_count && 0 === $deduped_count && $not_queued_count > 0 ) {
		$status = 'not_queued';
	} elseif ( $not_queued_count > 0 ) {
		$status = 'partial';
	}

	return array(
		'review_item_queue_status'       => $status,
		'review_item_queue_results'      => $results,
		'review_item_descriptors'        => $descriptors,
		'review_item_queued_count'       => $queued_count,
		'review_item_deduplicated_count' => $deduped_count,
		'review_item_not_queued_count'   => $not_queued_count,
		'review_item_pending_count'      => wp_de_rtc_get_pending_review_item_count_for_post( $post ),
		'storage_ready'                  => true,
		'stored_source_encoding'         => 'base64url',
		'raw_content_included'           => false,
		'exposes_raw_content'            => false,
	);
}

/**
 * Returns the suggested Distributed Editing presence heartbeat interval.
 *
 * @since 7.1.0
 *
 * @param string $host_profile Optional host profile label.
 * @return int Heartbeat interval in seconds.
 */
function wp_de_rtc_get_presence_heartbeat_interval_seconds( $host_profile = '' ) {
	if ( 'local_development' === $host_profile ) {
		return 5;
	}

	if ( 'cheap_shared_host' === $host_profile ) {
		return 120;
	}

	return 30;
}

/**
 * Returns the expiry window for Distributed Editing presence heartbeats.
 *
 * @since 7.1.0
 *
 * @param string $host_profile Optional host profile label.
 * @return int Expiry window in seconds.
 */
function wp_de_rtc_get_presence_heartbeat_expires_after_seconds( $host_profile = '' ) {
	return max( wp_de_rtc_get_presence_heartbeat_interval_seconds( $host_profile ) * 5, 150 );
}

/**
 * Returns the stored hash for an opaque editor presence session key.
 *
 * Presence storage already uses this hash to avoid persisting raw tab/session
 * keys. Authorship focus derives from the same hidden value so saved changes
 * can be associated with an editor session without exposing the session key.
 *
 * @since 7.1.0
 * @access private
 *
 * @param int    $post_id     Post ID.
 * @param string $session_key Opaque editor session key.
 * @return string Session-key hash, or empty string when unavailable.
 */
function wp_de_rtc_get_presence_session_key_hash( $post_id, $session_key ) {
	$session_key = is_string( $session_key ) ? trim( $session_key ) : '';

	if ( '' === $session_key ) {
		return '';
	}

	return hash_hmac( 'sha256', (int) $post_id . ':' . $session_key, wp_salt( 'nonce' ) );
}

/**
 * Returns a public authorship key derived from a stored presence session hash.
 *
 * The value is stable for a post/session pair and safe to share with editors
 * who can already collaborate on the post. It intentionally does not reveal
 * raw session keys, user IDs, logins, or email addresses.
 *
 * @since 7.1.0
 * @access private
 *
 * @param int    $post_id          Post ID.
 * @param string $session_key_hash Stored presence session-key hash.
 * @return string Public attribution key, or empty string when unavailable.
 */
function wp_de_rtc_get_presence_attribution_key_from_session_hash( $post_id, $session_key_hash ) {
	$session_key_hash = is_string( $session_key_hash ) ? strtolower( trim( $session_key_hash ) ) : '';

	if ( ! wp_de_rtc_is_sha256_hash( $session_key_hash ) ) {
		return '';
	}

	return 'presence:' . substr( hash_hmac( 'sha256', (int) $post_id . ':' . $session_key_hash, wp_salt( 'auth' ) ), 0, 24 );
}

/**
 * Returns a public authorship key for an opaque editor presence session key.
 *
 * @since 7.1.0
 * @access private
 *
 * @param int    $post_id     Post ID.
 * @param string $session_key Opaque editor session key.
 * @return string Public attribution key, or empty string when unavailable.
 */
function wp_de_rtc_get_presence_attribution_key_for_session_key( $post_id, $session_key ) {
	$session_key_hash = wp_de_rtc_get_presence_session_key_hash( $post_id, $session_key );

	return wp_de_rtc_get_presence_attribution_key_from_session_hash( $post_id, $session_key_hash );
}

/**
 * Records a content-free Distributed Editing presence heartbeat.
 *
 * This helper writes only presence liveness evidence to the dedicated presence
 * table. It must not install the table, save posts, mutate post content,
 * create revisions, or change post locks.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post Post ID or object.
 * @param array       $args {
 *     Optional heartbeat arguments.
 *
 *     @type string $session_key      Opaque editor session key.
 *     @type string $host_profile     Host profile label.
 *     @type string $current_time_gmt Current GMT time in mysql format.
 *     @type string $confirmed_base_version Content-free sync version reported by the session.
 *     @type string $confirmed_state_hash   Content-free state hash reported by the session.
 *     @type bool   $has_pending_changes    Whether the session reports unsaved changes.
 *     @type string $confirmed_at_gmt        GMT time when the reported copy was observed.
 *     @type array  $pending_preview_state   Ephemeral pending-edit preview state.
 * }
 * @return array|WP_Error Heartbeat result, or an error when storage/payload fails.
 */
function wp_de_rtc_record_presence_heartbeat( $post, $args = array() ) {
	global $wpdb;

	$post = get_post( $post );

	if ( ! $post ) {
		return new WP_Error(
			'rest_post_invalid_id',
			__( 'Invalid post ID.' ),
			array( 'status' => 404 )
		);
	}

	$args        = wp_parse_args(
		$args,
		array(
			'session_key'      => '',
			'host_profile'     => 'cheap_shared_host',
			'current_time_gmt' => current_time( 'mysql', true ),
			'confirmed_base_version' => '',
			'confirmed_state_hash'   => '',
			'has_pending_changes'    => false,
			'confirmed_at_gmt'       => '',
			'selection_state'        => array(),
			'pending_preview_state'  => array(),
		)
	);
	$session_key = is_string( $args['session_key'] ) ? trim( $args['session_key'] ) : '';

	if ( '' === $session_key ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing presence heartbeat is missing a session key.' ),
			array(
				'detail'                         => 'missing_session_key',
				'post_id'                        => (int) $post->ID,
				'rest_route'                     => 'post_presence_heartbeat',
				'storage_table_ready'            => wp_de_rtc_presence_table_exists(),
				'writes_presence'                => false,
				'records_presence_heartbeat'     => false,
				'installs_presence_table'        => false,
				'automatic_table_install'        => false,
				'calls_save'                     => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'mutates_persisted_post_content' => false,
				'creates_revision'               => false,
				'changes_post_lock'              => false,
				'claims_absence'                 => false,
				'claims_saved'                   => false,
			)
		);
	}

	$table_name = wp_de_rtc_get_presence_table_name();

	if ( ! wp_de_rtc_presence_table_exists() ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_presence_storage_unavailable',
			__( 'Distributed Editing presence storage is not installed.' ),
			array(
				'detail'                         => 'presence_table_missing',
				'result'                         => 'presence_storage_unavailable',
				'post_id'                        => (int) $post->ID,
				'post_type'                      => $post->post_type,
				'post_type_rest_base'            => wp_de_rtc_get_post_type_rest_base( $post->post_type ),
				'rest_route'                     => 'post_presence_heartbeat',
				'table_name'                     => $table_name,
				'storage_table_ready'            => false,
				'writes_presence'                => false,
				'records_presence_heartbeat'     => false,
				'heartbeat_writes_enabled_now'   => false,
				'server_contact'                 => 'degraded',
				'can_retry_after_install'        => true,
				'repeated_refresh_optional'      => true,
				'correctness_independent_of_transport' => true,
				'transport_required_for_correctness' => false,
				'table_exists_required_for_save_correctness' => false,
				'installs_presence_table'        => false,
				'automatic_table_install'        => false,
				'enables_repeated_client_refresh' => false,
				'runtime_polling_enabled_now'    => false,
				'calls_save'                     => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'mutates_persisted_post_content' => false,
				'creates_revision'               => false,
				'changes_post_lock'              => false,
				'claims_absence'                 => false,
				'claims_saved'                   => false,
				'exposes_raw_content'            => false,
				'exposes_user_ids'               => false,
				'exposes_logins'                 => false,
				'exposes_email'                  => false,
				'exposes_cursor_offset'          => false,
				'exposes_selection'              => false,
				'raw_session_key_included'       => false,
			)
		);
	}

	if ( ! wp_de_rtc_presence_table_schema_current() ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_presence_storage_unavailable',
			__( 'Distributed Editing presence storage needs setup.' ),
			array(
				'detail'                         => 'presence_table_schema_upgrade_required',
				'result'                         => 'presence_storage_unavailable',
				'post_id'                        => (int) $post->ID,
				'post_type'                      => $post->post_type,
				'post_type_rest_base'            => wp_de_rtc_get_post_type_rest_base( $post->post_type ),
				'rest_route'                     => 'post_presence_heartbeat',
				'table_name'                     => $table_name,
				'storage_table_ready'            => false,
				'writes_presence'                => false,
				'records_presence_heartbeat'     => false,
				'heartbeat_writes_enabled_now'   => false,
				'server_contact'                 => 'degraded',
				'can_retry_after_install'        => true,
				'repeated_refresh_optional'      => true,
				'correctness_independent_of_transport' => true,
				'transport_required_for_correctness' => false,
				'table_exists_required_for_save_correctness' => false,
				'installs_presence_table'        => false,
				'automatic_table_install'        => false,
				'enables_repeated_client_refresh' => false,
				'runtime_polling_enabled_now'    => false,
				'calls_save'                     => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'mutates_persisted_post_content' => false,
				'creates_revision'               => false,
				'changes_post_lock'              => false,
				'claims_absence'                 => false,
				'claims_saved'                   => false,
				'exposes_raw_content'            => false,
				'exposes_user_ids'               => false,
				'exposes_logins'                 => false,
				'exposes_email'                  => false,
				'exposes_cursor_offset'          => false,
				'exposes_selection'              => false,
				'raw_session_key_included'       => false,
			)
		);
	}

	$host_profile                = is_string( $args['host_profile'] ) ? $args['host_profile'] : 'cheap_shared_host';
	$current_time_gmt            = is_string( $args['current_time_gmt'] ) ? $args['current_time_gmt'] : current_time( 'mysql', true );
	$current_time_timestamp      = strtotime( $current_time_gmt . ' UTC' );
	$current_time_timestamp      = $current_time_timestamp ? $current_time_timestamp : time();
	$heartbeat_interval_seconds  = wp_de_rtc_get_presence_heartbeat_interval_seconds( $host_profile );
	$expires_after_seconds       = wp_de_rtc_get_presence_heartbeat_expires_after_seconds( $host_profile );
	$expires_at_gmt              = gmdate( 'Y-m-d H:i:s', $current_time_timestamp + $expires_after_seconds );
	$current_user                = wp_get_current_user();
	$user_id                     = get_current_user_id();
	$display_name                = $current_user && $current_user->exists() && $current_user->display_name ? $current_user->display_name : __( 'Another editor' );
	$permission_summary          = wp_de_rtc_get_presence_permission_summary( $post, $user_id );
	$session_key_hash            = wp_de_rtc_get_presence_session_key_hash( $post->ID, $session_key );
	$attribution_key             = wp_de_rtc_get_presence_attribution_key_from_session_hash( $post->ID, $session_key_hash );
	$actor_hash                  = wp_de_rtc_get_presence_actor_hash( $user_id );
	$document_state              = wp_de_rtc_get_sanitized_presence_document_state( $args, $current_time_gmt );
	$selection_state             = wp_de_rtc_get_sanitized_presence_selection_state( $args['selection_state'], $current_time_gmt );
	$selection_state_json        = ! empty( $selection_state['available'] ) ? wp_json_encode( $selection_state ) : '';
	$pending_preview_state       = wp_de_rtc_get_sanitized_presence_pending_preview_state( $args['pending_preview_state'], $current_time_gmt );
	$pending_preview_json        = ! empty( $pending_preview_state['available'] ) ? wp_json_encode( $pending_preview_state ) : '';

	if ( strlen( (string) $selection_state_json ) > 4096 ) {
		$selection_state      = wp_de_rtc_get_unavailable_presence_selection_state();
		$selection_state_json = '';
	}

	if ( strlen( (string) $pending_preview_json ) > 8192 ) {
		$pending_preview_state = wp_de_rtc_get_unavailable_presence_pending_preview_state();
		$pending_preview_json  = '';
	}

	$table_sql                   = '`' . str_replace( '`', '``', $table_name ) . '`';
	$heartbeat_write_sql         = "INSERT INTO $table_sql ( post_id, session_key_hash, actor_hash, display_name, freshness, " .
		'can_edit_post, can_publish_post, can_save_dangerous_html, confirmed_base_version, confirmed_state_hash, ' .
		'has_pending_changes, confirmed_at_gmt, selection_state_json, pending_preview_json, last_seen_gmt, expires_at_gmt, created_at_gmt, updated_at_gmt ) ' .
		'VALUES ( %d, %s, %s, %s, %s, %d, %d, %d, %s, %s, %d, NULLIF( %s, \'\' ), NULLIF( %s, \'\' ), NULLIF( %s, \'\' ), %s, %s, %s, %s ) ' .
		'ON DUPLICATE KEY UPDATE post_id = VALUES( post_id ), actor_hash = VALUES( actor_hash ), ' .
		'display_name = VALUES( display_name ), freshness = VALUES( freshness ), can_edit_post = VALUES( can_edit_post ), ' .
		'can_publish_post = VALUES( can_publish_post ), can_save_dangerous_html = VALUES( can_save_dangerous_html ), ' .
		'confirmed_base_version = VALUES( confirmed_base_version ), confirmed_state_hash = VALUES( confirmed_state_hash ), ' .
		'has_pending_changes = VALUES( has_pending_changes ), confirmed_at_gmt = VALUES( confirmed_at_gmt ), ' .
		'selection_state_json = VALUES( selection_state_json ), pending_preview_json = VALUES( pending_preview_json ), ' .
		'last_seen_gmt = VALUES( last_seen_gmt ), expires_at_gmt = VALUES( expires_at_gmt ), ' .
		'updated_at_gmt = VALUES( updated_at_gmt )';
	$written                     = $wpdb->query(
		$wpdb->prepare(
			$heartbeat_write_sql,
			(int) $post->ID,
			$session_key_hash,
			$actor_hash,
			$display_name,
			'active',
			! empty( $permission_summary['canEdit'] ) ? 1 : 0,
			! empty( $permission_summary['canPublish'] ) ? 1 : 0,
			! empty( $permission_summary['canSaveDangerousHtml'] ) ? 1 : 0,
			$document_state['confirmedBaseVersion'],
			$document_state['confirmedStateHash'],
			! empty( $document_state['hasPendingChanges'] ) ? 1 : 0,
			$document_state['confirmedAtGmt'],
			$selection_state_json,
			$pending_preview_json,
			$current_time_gmt,
			$expires_at_gmt,
			$current_time_gmt,
			$current_time_gmt
		)
	);

	if ( false === $written ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_storage_failure',
			__( 'Distributed Editing presence heartbeat storage failed.' ),
			array(
				'detail'                     => 'presence_heartbeat_storage_failure',
				'post_id'                    => (int) $post->ID,
				'rest_route'                 => 'post_presence_heartbeat',
				'table_name'                 => $table_name,
				'storage_table_ready'        => true,
				'writes_presence'            => false,
				'records_presence_heartbeat' => false,
				'installs_presence_table'    => false,
				'automatic_table_install'    => false,
				'calls_save'                 => false,
				'saves_post'                 => false,
				'mutates_post_content'       => false,
				'creates_revision'           => false,
				'changes_post_lock'          => false,
				'claims_saved'               => false,
			)
		);
	}

	return array(
		'result'                         => 'presence_heartbeat_recorded',
		'rest_route'                     => 'post_presence_heartbeat',
		'post_id'                        => (int) $post->ID,
		'post_type'                      => $post->post_type,
		'post_type_rest_base'            => wp_de_rtc_get_post_type_rest_base( $post->post_type ),
		'table_name'                     => $table_name,
		'storage_table_ready'            => true,
		'writes_presence'                => true,
		'records_presence_heartbeat'     => true,
		'heartbeat_writes_enabled_now'   => true,
		'session_key_hash_recorded'      => true,
		'attribution_key'                => $attribution_key,
		'attributionKey'                 => $attribution_key,
		'authorship_focus_available'     => '' !== $attribution_key,
		'actor_hash_recorded'            => true,
		'display_name_recorded'          => true,
		'permission_summary_recorded'    => true,
		'document_state_recorded'        => (bool) $document_state['available'],
		'selection_state_recorded'       => (bool) $selection_state['available'],
		'pending_preview_recorded'       => (bool) $pending_preview_state['available'],
		'document_state'                 => array_merge(
			$document_state,
			array(
				'reportedAtGmt'        => $current_time_gmt,
				'presenceUpdatedAtGmt' => $current_time_gmt,
			)
		),
		'selection_state'                => array_merge(
			$selection_state,
			array(
				'presenceUpdatedAtGmt' => $current_time_gmt,
			)
		),
		'pending_preview'                => array_merge(
			$pending_preview_state,
			array(
				'presenceUpdatedAtGmt' => $current_time_gmt,
			)
		),
		'permissions'                    => $permission_summary,
		'last_seen_recorded'             => true,
		'expires_at_recorded'            => true,
		'session_started_at_gmt'         => $current_time_gmt,
		'session_duration_seconds'       => 0,
		'freshness'                      => 'active',
		'server_contact'                 => 'nominal',
		'heartbeat_interval_seconds'     => $heartbeat_interval_seconds,
		'expires_after_seconds'          => $expires_after_seconds,
		'repeated_refresh_optional'      => true,
		'correctness_independent_of_transport' => true,
		'transport_required_for_correctness' => false,
		'table_exists_required_for_save_correctness' => false,
		'installs_presence_table'        => false,
		'automatic_table_install'        => false,
		'enables_repeated_client_refresh' => false,
		'runtime_polling_enabled_now'    => false,
		'calls_save'                     => false,
		'saves_post'                     => false,
		'mutates_post_content'           => false,
		'mutates_persisted_post_content' => false,
		'creates_revision'               => false,
		'changes_post_lock'              => false,
		'claims_absence'                 => false,
