/**
 * Returns a privacy-safe author label for a history row.
 *
 * @since 7.1.0
 *
 * @param int $user_id User ID stored by WordPress.
 * @return string Display label.
 */
function wp_de_rtc_get_history_author_display_name( $user_id ) {
	$user = get_userdata( (int) $user_id );

	if ( $user && is_string( $user->display_name ) && '' !== trim( $user->display_name ) ) {
		return $user->display_name;
	}

	return __( 'Unknown editor' );
}

/**
 * Returns a privacy-safe session label for a history row.
 *
 * @since 7.1.0
 *
 * @param mixed $sync_meta Sync metadata from the row.
 * @return string Session label.
 */
function wp_de_rtc_get_history_session_label( $sync_meta ) {
	$recovery_attribution = wp_de_rtc_get_sync_meta_recovery_attribution( $sync_meta );

	if (
		is_array( $recovery_attribution ) &&
		isset( $recovery_attribution['actor']['display_name'] ) &&
		is_string( $recovery_attribution['actor']['display_name'] ) &&
		'' !== trim( $recovery_attribution['actor']['display_name'] )
	) {
		return sanitize_text_field( $recovery_attribution['actor']['display_name'] );
	}

	if ( is_array( $sync_meta ) && isset( $sync_meta['last_server_update'] ) && is_array( $sync_meta['last_server_update'] ) ) {
		if ( isset( $sync_meta['last_server_update']['session_label'] ) && is_string( $sync_meta['last_server_update']['session_label'] ) && '' !== trim( $sync_meta['last_server_update']['session_label'] ) ) {
			return sanitize_text_field( $sync_meta['last_server_update']['session_label'] );
		}

		if ( isset( $sync_meta['last_server_update']['type'] ) && is_string( $sync_meta['last_server_update']['type'] ) && '' !== trim( $sync_meta['last_server_update']['type'] ) ) {
			return sanitize_text_field( str_replace( '_', ' ', $sync_meta['last_server_update']['type'] ) );
		}
	}

	return __( 'Unknown session' );
}

/**
 * Builds one document-history row from a post or revision object.
 *
 * @since 7.1.0
 *
 * @param WP_Post $item       Post or revision object.
 * @param bool    $is_current Whether the row represents current post content.
 * @return array History row.
 */
function wp_de_rtc_get_history_row_from_post( $item, $is_current = false ) {
	$parsed            = wp_de_rtc_parse_post_content_sync_meta( $item->post_content );
	$content           = '';
	$sync_meta         = null;
	$sync_meta_format  = null;
	$preview_available = false;
	$parse_error       = null;

	if ( is_wp_error( $parsed ) ) {
		$parse_error = $parsed->get_error_code();
	} else {
		$content           = is_string( $parsed['content'] ) ? $parsed['content'] : '';
		$sync_meta         = $parsed['sync_meta'];
		$sync_meta_format  = $parsed['sync_meta_format'];
		$preview_available = true;
	}

	$sync_version = '';
	if ( is_array( $sync_meta ) && isset( $sync_meta['version'] ) ) {
		$sync_version = sanitize_text_field( (string) $sync_meta['version'] );
	}

	$recovery_attribution = wp_de_rtc_get_sync_meta_recovery_attribution( $sync_meta );
	$actor_type           = is_array( $recovery_attribution ) ? 'system' : 'human';
	$author_display_name  = wp_de_rtc_get_history_author_display_name( $item->post_author );
	$session_label        = wp_de_rtc_get_history_session_label( $sync_meta );

	if ( is_array( $recovery_attribution ) ) {
		$author_display_name = 'WordPress';
	}

	return array(
		'id'                       => $is_current ? 'current' : 'revision-' . (int) $item->ID,
		'revision_id'              => $is_current ? 0 : (int) $item->ID,
		'is_current'               => (bool) $is_current,
		'date'                     => mysql_to_rfc3339( $item->post_date ),
		'date_gmt'                 => mysql_to_rfc3339( $item->post_date_gmt ),
		'author_display_name'      => $author_display_name,
		'session_label'            => $session_label,
		'actor_type'               => $actor_type,
		'recovery_attribution'     => is_array( $recovery_attribution ) ? wp_de_rtc_get_recovery_attribution_response_fields( $recovery_attribution )['recovery_attribution'] : null,
		'sync_version'             => $sync_version,
		'previous_sync_version'    => is_array( $sync_meta ) && isset( $sync_meta['previous_version'] ) ? sanitize_text_field( (string) $sync_meta['previous_version'] ) : '',
		'sync_meta_format'         => is_string( $sync_meta_format ) ? sanitize_key( $sync_meta_format ) : '',
		'content'                  => $content,
		'content_hash'             => $preview_available ? wp_de_rtc_hash_content( $content ) : '',
		'preview_available'        => $preview_available,
		'parse_error'              => $parse_error,
		'can_restore'              => $preview_available,
		'can_revert'               => $preview_available,
		'saves_post'               => false,
		'mutates_post_content'     => false,
		'creates_revision'         => false,
		'changes_post_lock'        => false,
		'claims_saved'             => false,
		'exposes_user_ids'         => false,
		'exposes_raw_session_keys' => false,
		'exposes_cursor_data'      => false,
		'exposes_selection_data'   => false,
	);
}

/**
 * Returns a chronological document-history timeline for a post.
 *
 * @since 7.1.0
 *
 * @param WP_Post $post Post object.
 * @return array History response data.
 */
function wp_de_rtc_get_post_history_timeline( $post ) {
	$revisions = wp_get_post_revisions(
		$post->ID,
		array(
			'posts_per_page' => -1,
			'orderby'        => 'date ID',
			'order'          => 'ASC',
		)
	);
	$rows      = array();

	foreach ( $revisions as $revision ) {
		$rows[] = wp_de_rtc_get_history_row_from_post( $revision, false );
	}

	$rows[] = wp_de_rtc_get_history_row_from_post( $post, true );

	$current_content_hash = ! empty( $rows ) && isset( $rows[ count( $rows ) - 1 ]['content_hash'] ) ? (string) $rows[ count( $rows ) - 1 ]['content_hash'] : '';

	foreach ( $rows as $index => &$row ) {
		$row['index']       = $index;
		$row['can_revert']  = ! empty( $row['can_revert'] ) && $index > 0 && hash_equals( $current_content_hash, (string) $row['content_hash'] );
		$row['can_restore'] = ! empty( $row['can_restore'] );
	}
	unset( $row );

	return array(
		'result'                   => 'history_loaded',
		'post_id'                  => (int) $post->ID,
		'post_type'                => sanitize_key( $post->post_type ),
		'history_items'            => $rows,
		'count'                    => count( $rows ),
		'read_only'                => true,
		'saves_post'               => false,
		'mutates_post_content'     => false,
		'creates_revision'         => false,
		'changes_post_lock'        => false,
		'claims_saved'             => false,
		'exposes_user_ids'         => false,
		'exposes_raw_session_keys' => false,
		'exposes_logins'           => false,
		'exposes_email'            => false,
		'exposes_cursor_data'      => false,
		'exposes_selection_data'   => false,
		'revert_requires_save'     => true,
		'restore_requires_save'    => true,
	);
}

/**
 * Finds a history row by revision ID.
 *
 * @since 7.1.0
 *
 * @param array $rows        Timeline rows.
 * @param int   $revision_id Revision ID, or 0 for current.
 * @return array|null Indexed row wrapper.
 */
function wp_de_rtc_find_history_row_by_revision_id( $rows, $revision_id ) {
	foreach ( $rows as $index => $row ) {
		if ( isset( $row['revision_id'] ) && (int) $row['revision_id'] === (int) $revision_id ) {
			return array(
				'index' => $index,
				'row'   => $row,
			);
		}
	}

	return null;
}

/**
 * Plans a no-write document-history action.
 *
 * Restore stages the selected full state. Revert currently uses the strict
 * safe case: the selected revision must still be the current stripped content,
 * so the inverse can be represented by replacing it with the previous revision.
 *
 * @since 7.1.0
 *
 * @param WP_Post $post Post object.
 * @param array   $args Action args.
 * @return array|WP_Error Planning result.
 */
function wp_de_rtc_plan_post_history_action( $post, $args ) {
	$action      = isset( $args['history_action'] ) ? sanitize_key( (string) $args['history_action'] ) : '';
	$revision_id = isset( $args['revision_id'] ) ? (int) $args['revision_id'] : -1;
	$history     = wp_de_rtc_get_post_history_timeline( $post );
	$rows        = $history['history_items'];
	$selected    = wp_de_rtc_find_history_row_by_revision_id( $rows, $revision_id );

	if ( ! in_array( $action, array( 'revert', 'restore' ), true ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing could not plan the history action because the action is unsupported.' ),
			array(
				'detail'               => 'history_action_unsupported',
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	if ( null === $selected || empty( $selected['row']['preview_available'] ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing could not plan the history action because the selected revision is unavailable.' ),
			array(
				'detail'               => 'history_revision_unavailable',
				'revision_id'          => $revision_id,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$selected_hash = isset( $selected['row']['content_hash'] ) ? (string) $selected['row']['content_hash'] : '';

	if ( ! empty( $args['selected_content_hash'] ) && ! hash_equals( $selected_hash, (string) $args['selected_content_hash'] ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing could not plan the history action because the selected revision hash changed.' ),
			array(
				'detail'               => 'history_selected_hash_mismatch',
				'revision_id'          => $revision_id,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$candidate_content = (string) $selected['row']['content'];
	$result            = 'history_restore_planned';

	if ( 'revert' === $action ) {
		if ( $selected['index'] < 1 || empty( $rows[ $selected['index'] - 1 ]['preview_available'] ) ) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_rebase_failed',
				__( 'Distributed Editing could not revert this revision automatically.' ),
				array(
					'detail'               => 'history_revert_previous_revision_unavailable',
					'revision_id'          => $revision_id,
					'saves_post'           => false,
					'mutates_post_content' => false,
					'creates_revision'     => false,
					'claims_saved'         => false,
				)
			);
		}

		$current = $rows[ count( $rows ) - 1 ];

		if ( ! hash_equals( (string) $current['content_hash'], $selected_hash ) ) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_rebase_failed',
				__( 'Distributed Editing could not revert this revision because newer content must be reviewed first.' ),
				array(
					'detail'                 => 'history_revert_current_content_drift',
					'revision_id'            => $revision_id,
					'selected_content_hash'  => $selected_hash,
					'current_content_hash'   => (string) $current['content_hash'],
					'requires_manual_review' => true,
					'saves_post'             => false,
					'mutates_post_content'   => false,
					'creates_revision'       => false,
					'claims_saved'           => false,
				)
			);
		}

		$candidate_content = (string) $rows[ $selected['index'] - 1 ]['content'];
		$result            = 'history_revert_planned';
	}

	return array(
		'result'                      => $result,
		'history_action'              => $action,
		'revision_id'                 => $revision_id,
		'candidate_post_content'      => $candidate_content,
		'candidate_post_content_hash' => wp_de_rtc_hash_content( $candidate_content ),
		'selected_content_hash'       => $selected_hash,
		'requires_save'               => true,
		'saves_post'                  => false,
		'mutates_post_content'        => false,
		'creates_revision'            => false,
		'changes_post_lock'           => false,
		'claims_saved'                => false,
	);
}

/**
 * Handles the presence snapshot REST endpoint.
 *
 * @since 7.1.0
 *
 * @param WP_REST_Request $request Full details about the request.
 * @return WP_REST_Response REST response.
 */
function wp_de_rtc_rest_presence_endpoint( $request ) {
	$result = wp_de_rtc_get_post_presence_read_snapshot(
		(int) $request['id'],
		array(
			'current_session_key' => (string) $request->get_param( 'session_key' ),
			'limit'               => $request->get_param( 'limit' ),
		)
	);

	return wp_de_rtc_rest_ensure_no_store_response( $result );
}

/**
 * Handles the Distributed Editing post snapshot REST endpoint.
 *
 * @since 7.1.0
 *
 * @param WP_REST_Request $request Full details about the request.
 * @return WP_REST_Response|WP_Error REST response.
 */
function wp_de_rtc_rest_post_snapshot_endpoint( $request ) {
	$post     = get_post( (int) $request['id'] );
	$snapshot = wp_de_rtc_get_post_snapshot_for_distributed_editing( $post );

	if ( is_wp_error( $snapshot ) ) {
		return $snapshot;
	}

	$etag          = '"' . $snapshot['state_hash'] . '"';
	$cache_control = 'private, no-store';

	if ( wp_de_rtc_rest_if_none_match_matches_state_hash( $request->get_header( 'if-none-match' ), $snapshot['state_hash'] ) ) {
		$response = new WP_REST_Response( null, 304 );
		$response->header( 'ETag', $etag );
		$response->header( 'Cache-Control', $cache_control );

		return $response;
	}

	$response = rest_ensure_response( $snapshot );
	$response->header( 'ETag', $etag );
	$response->header( 'Cache-Control', $cache_control );

	return $response;
}

/**
 * Returns the current persisted post content and state validator for the editor.
 *
 * The validator is intentionally opaque to the client. WordPress owns the split
 * between sync metadata and human post content, so client code can only echo
 * the last accepted hash and let the server decide whether anything changed.
 *
 * @since 7.1.0
 * @access private
 *
 * @param WP_Post $post Post object.
 * @return array|WP_Error Snapshot response data, or a WP_Error when the persisted content cannot be trusted.
 */
function wp_de_rtc_get_post_snapshot_for_distributed_editing( $post ) {
	if ( ! $post || empty( $post->ID ) ) {
		return new WP_Error(
			'rest_post_invalid_id',
			__( 'Invalid post ID.' ),
			array( 'status' => 404 )
		);
	}

	$parsed = wp_de_rtc_parse_post_content_sync_meta( $post->post_content );
	$snapshot_raw_content = $post->post_content;
	$external_repair      = null;
	$external_repair_applied = false;
	$external_repair_revision_created = false;

	if ( is_wp_error( $parsed ) ) {
		$parsed->add_data(
			array_merge(
				(array) $parsed->get_error_data(),
				array(
					'status'               => 409,
					'rest_route'           => 'post_distributed_editing_snapshot',
					'read_only'            => true,
					'saves_post'           => false,
					'mutates_post_content' => false,
					'creates_revision'     => false,
					'changes_post_lock'    => false,
					'claims_saved'         => false,
					'exposes_raw_content'  => false,
				)
			)
		);

		return $parsed;
	}

	$repaired = wp_de_rtc_get_repaired_automerge_current_post_snapshot(
		$post,
		$parsed,
		array(
			'allow_empty_import' => true,
		)
	);

	if ( is_wp_error( $repaired ) ) {
		$repaired->add_data(
			array_merge(
				(array) $repaired->get_error_data(),
				array(
					'status'               => 409,
					'post_id'              => (int) $post->ID,
					'rest_route'           => 'post_distributed_editing_snapshot',
					'read_only'            => true,
					'saves_post'           => false,
					'mutates_post_content' => false,
					'creates_revision'     => false,
					'changes_post_lock'    => false,
					'claims_saved'         => false,
					'exposes_raw_content'  => false,
				)
			)
		);

		return $repaired;
	}

	if ( is_array( $repaired ) ) {
		$recovery_plan  = wp_de_rtc_plan_sync_meta_recovery_update( $post );
		$recovery_apply = wp_de_rtc_apply_sync_meta_recovery_update(
			$recovery_plan,
			array(
				'mode' => 'apply',
			)
		);

		if ( is_wp_error( $recovery_apply ) ) {
			$recovery_apply->add_data(
				array_merge(
					(array) $recovery_apply->get_error_data(),
					array(
						'status'               => 409,
						'post_id'              => (int) $post->ID,
						'rest_route'           => 'post_distributed_editing_snapshot',
						'read_only'            => true,
						'saves_post'           => false,
						'mutates_post_content' => false,
						'creates_revision'     => false,
						'changes_post_lock'    => false,
						'claims_saved'         => false,
						'exposes_raw_content'  => false,
					)
				)
			);

			return $recovery_apply;
		}

		if ( empty( $recovery_apply['applied'] ) ) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_storage_failure',
				__( 'Distributed Editing could not repair the persisted post snapshot.' ),
				array(
					'detail'               => 'snapshot_recovery_apply_not_applied',
					'post_id'              => (int) $post->ID,
					'rest_route'           => 'post_distributed_editing_snapshot',
					'saves_post'           => false,
					'mutates_post_content' => false,
					'creates_revision'     => false,
					'changes_post_lock'    => false,
					'claims_saved'         => false,
				)
			);
		}

		$post = get_post( (int) $post->ID );

		if ( ! $post ) {
			return new WP_Error(
				'rest_post_invalid_id',
				__( 'Invalid post ID.' ),
				array( 'status' => 404 )
			);
		}

		$reparsed = wp_de_rtc_parse_post_content_sync_meta( $post->post_content );

		if ( is_wp_error( $reparsed ) ) {
			return $reparsed;
		}

		$parsed                           = $reparsed;
		$snapshot_raw_content             = $post->post_content;
		$external_repair_applied          = true;
		$external_repair_revision_created = ! empty( $recovery_apply['revision_created'] );
		$external_repair                  = array(
			'mode'                           => $repaired['external_repair_mode'],
			'base_version'                   => $repaired['base_version'],
			'repaired_version'               => isset( $parsed['sync_meta']['version'] ) ? (string) $parsed['sync_meta']['version'] : $repaired['server_version'],
			'planned_repaired_version'       => $repaired['server_version'],
			'base_revision_id'               => $repaired['base_revision_id'],
			'base_content_hash'              => $repaired['base_content_hash'],
			'current_content_hash'           => $repaired['current_content_hash'],
			'repair_actor'                   => isset( $repaired['recovery_actor'] ) ? $repaired['recovery_actor'] : null,
			'content_hash_algorithm'         => 'sha256',
			'applied'                        => true,
			'apply_result'                   => isset( $recovery_apply['result'] ) ? $recovery_apply['result'] : null,
			'revision_created'               => $external_repair_revision_created,
			'created_revision_ids'           => isset( $recovery_apply['created_revision_ids'] ) && is_array( $recovery_apply['created_revision_ids'] )
				? array_values( array_map( 'intval', $recovery_apply['created_revision_ids'] ) )
				: array(),
			'read_only'                      => false,
			'saves_post'                     => true,
			'mutates_post_content'           => true,
			'mutates_persisted_post_content' => true,
			'creates_revision'               => $external_repair_revision_created,
			'changes_post_lock'              => false,
			'claims_saved'                   => false,
		);
	}

	if ( ! is_array( $parsed['sync_meta'] ) || ! is_string( $parsed['sync_meta_format'] ) || '' === $parsed['sync_meta_format'] ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing sync metadata is required before this post can be synchronized.' ),
			array(
				'status'               => 409,
				'detail'               => 'missing_sync_meta',
				'post_id'              => (int) $post->ID,
				'rest_route'           => 'post_distributed_editing_snapshot',
				'read_only'            => true,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'changes_post_lock'    => false,
				'claims_saved'         => false,
				'exposes_raw_content'  => false,
			)
		);
	}

	if ( ! in_array( $parsed['sync_meta_format'], wp_de_rtc_get_supported_sync_meta_formats(), true ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_unknown_sync_meta_format',
			__( 'The Distributed Editing sync metadata format is not supported.' ),
			array(
				'status'               => 409,
				'format'               => $parsed['sync_meta_format'],
				'post_id'              => (int) $post->ID,
				'rest_route'           => 'post_distributed_editing_snapshot',
				'read_only'            => true,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'changes_post_lock'    => false,
				'claims_saved'         => false,
				'exposes_raw_content'  => false,
			)
		);
	}

	$rest_base      = wp_de_rtc_get_post_type_rest_base( $post->post_type );
	$body_hash      = wp_de_rtc_hash_content( $parsed['content'] );
	$sync_meta_hash = wp_de_rtc_hash_content( (string) $parsed['raw_sync_meta'] );
	$raw_hash       = wp_de_rtc_hash_content( $snapshot_raw_content );
	$server_version = isset( $parsed['sync_meta']['version'] ) ? sanitize_text_field( (string) $parsed['sync_meta']['version'] ) : '';
	$pending_review_item_count = wp_de_rtc_get_pending_review_item_count_for_post( $post );
	$state_hash     = wp_de_rtc_get_post_snapshot_state_hash(
		array(
			'post_id'          => (int) $post->ID,
			'post_type'        => sanitize_key( $post->post_type ),
			'rest_base'        => $rest_base,
			'server_version'   => $server_version,
			'raw_hash'         => $raw_hash,
			'body_hash'        => $body_hash,
			'sync_meta_hash'   => $sync_meta_hash,
			'sync_meta_format' => $parsed['sync_meta_format'],
		)
	);

	return array(
		'id'                              => (int) $post->ID,
		'type'                            => sanitize_key( $post->post_type ),
		'modified'                        => mysql_to_rfc3339( $post->post_modified ),
		'modified_gmt'                    => mysql_to_rfc3339( $post->post_modified_gmt ),
		'content'                         => array(
			'raw' => $snapshot_raw_content,
		),
		'server_version'                  => $server_version,
		'state_hash'                      => $state_hash,
		'distributed_editing'             => array(
			'state_hash'              => $state_hash,
			'body_hash'               => $body_hash,
			'sync_meta_hash'          => $sync_meta_hash,
			'raw_content_hash'        => $raw_hash,
			'sync_meta_format'        => $parsed['sync_meta_format'],
			'sync_meta_position'      => $parsed['sync_meta_position'],
			'server_version'          => $server_version,
			'read_only'               => ! $external_repair_applied,
			'saves_post'              => $external_repair_applied,
			'mutates_post_content'    => $external_repair_applied,
			'mutates_persisted_post_content' => $external_repair_applied,
			'creates_revision'        => $external_repair_revision_created,
			'changes_post_lock'       => false,
			'claims_saved'            => false,
			'exposes_raw_content'     => true,
			'external_repair'         => $external_repair,
			'repair_candidate'        => is_array( $external_repair ),
			'repair_applied'          => $external_repair_applied,
			'pending_review_item_count' => $pending_review_item_count,
			'review_items_descriptor_only' => true,
		),
		'pending_review_item_count'    => $pending_review_item_count,
		'read_only'                       => ! $external_repair_applied,
		'saves_post'                      => $external_repair_applied,
		'mutates_post_content'            => $external_repair_applied,
		'mutates_persisted_post_content'  => $external_repair_applied,
		'creates_revision'                => $external_repair_revision_created,
		'changes_post_lock'               => false,
		'claims_saved'                    => false,
		'exposes_raw_content'             => true,
	);
}

/**
 * Computes an opaque state validator for the Distributed Editing post snapshot.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $state_data State data derived from persisted post content.
 * @return string Opaque SHA-256 HMAC.
 */
function wp_de_rtc_get_post_snapshot_state_hash( $state_data ) {
	$encoded = wp_json_encode( $state_data, JSON_UNESCAPED_SLASHES );

	if ( ! is_string( $encoded ) ) {
		$encoded = serialize( $state_data );
	}

	return hash_hmac( 'sha256', $encoded, wp_salt( 'auth' ) );
}

/**
 * Returns whether an If-None-Match header carries the current state hash.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string|null $header     If-None-Match header value.
 * @param string      $state_hash Current opaque state hash.
 * @return bool Whether the header matches.
 */
function wp_de_rtc_rest_if_none_match_matches_state_hash( $header, $state_hash ) {
	if ( ! is_string( $header ) || '' === trim( $header ) || ! is_string( $state_hash ) || '' === $state_hash ) {
		return false;
	}

	foreach ( explode( ',', $header ) as $candidate ) {
		$candidate = trim( $candidate );

		if ( 0 === stripos( $candidate, 'W/' ) ) {
			$candidate = trim( substr( $candidate, 2 ) );
		}

		$candidate = trim( $candidate, '"' );

		if ( hash_equals( $state_hash, $candidate ) ) {
			return true;
		}
	}

	return false;
}

/**
 * Handles the document history REST endpoint.
 *
 * @since 7.1.0
 *
 * @param WP_REST_Request $request Full details about the request.
 * @return WP_REST_Response REST response.
 */
function wp_de_rtc_rest_history_endpoint( $request ) {
	$post = get_post( (int) $request['id'] );

	return rest_ensure_response( wp_de_rtc_get_post_history_timeline( $post ) );
}

/**
 * Handles the no-write document history action planning endpoint.
 *
 * @since 7.1.0
 *
 * @param WP_REST_Request $request Full details about the request.
 * @return WP_REST_Response|WP_Error REST response.
 */
function wp_de_rtc_rest_history_plan_endpoint( $request ) {
	$post = get_post( (int) $request['id'] );

	return rest_ensure_response(
		wp_de_rtc_plan_post_history_action(
			$post,
			array(
				'history_action'        => $request->get_param( 'history_action' ),
				'revision_id'           => $request->get_param( 'revision_id' ),
				'selected_content_hash' => $request->get_param( 'selected_content_hash' ),
			)
		)
	);
}

/**
 * Handles the presence heartbeat REST endpoint.
 *
 * @since 7.1.0
 *
 * @param WP_REST_Request $request Full details about the request.
 * @return WP_REST_Response|WP_Error REST response on success, otherwise a WP_Error.
 */
function wp_de_rtc_rest_presence_heartbeat_endpoint( $request ) {
	$result = wp_de_rtc_record_presence_heartbeat(
		(int) $request['id'],
		array(
			'session_key'            => (string) $request->get_param( 'session_key' ),
			'confirmed_base_version' => (string) $request->get_param( 'confirmed_base_version' ),
			'confirmed_state_hash'   => (string) $request->get_param( 'confirmed_state_hash' ),
			'has_pending_changes'    => $request->get_param( 'has_pending_changes' ),
			'confirmed_at_gmt'       => (string) $request->get_param( 'confirmed_at_gmt' ),
			'selection_state'        => $request->get_param( 'selection_state' ),
			'pending_preview_state'  => $request->get_param( 'pending_preview_state' ),
		)
	);

	if ( is_wp_error( $result ) ) {
		return $result;
	}

	return rest_ensure_response( $result );
}

/**
 * Handles the presence storage readiness REST endpoint.
 *
 * This endpoint lets an already-open editor re-check whether deliberate setup
 * completed elsewhere. It only reads the readiness diagnostic; it must not
 * install storage, write presence, save posts, mutate content, create revisions,
 * change post locks, or start polling.
 *
 * @since 7.1.0
 *
 * @param WP_REST_Request $request Full details about the request.
 * @return WP_REST_Response REST response.
 */
function wp_de_rtc_rest_presence_storage_readiness_endpoint( $request ) {
	$post      = get_post( (int) $request['id'] );
	$rest_base = wp_de_rtc_get_post_type_rest_base( $post->post_type );
	$result    = wp_de_rtc_get_presence_storage_readiness(
		array(
			'feature_enabled' => true,
			'host_profile'    => 'cheap_shared_host',
		)
	);

	$result['postId']                         = (int) $post->ID;
	$result['post_id']                        = (int) $post->ID;
	$result['postType']                       = $post->post_type;
	$result['post_type']                      = $post->post_type;
	$result['postTypeRestBase']               = $rest_base;
	$result['post_type_rest_base']            = $rest_base;
	$result['restRoute']                      = 'post_presence_storage_readiness';
	$result['rest_route']                     = 'post_presence_storage_readiness';
	$result['method']                         = 'GET';
	$result['route']                          = '/wp/v2/' . $rest_base . '/' . (int) $post->ID . '/distributed-editing/presence/storage-readiness';
	$result['readOnly']                       = true;
	$result['read_only']                      = true;
	$result['calls_save']                     = false;
	$result['saves_post']                     = false;
	$result['mutates_post_content']           = false;
	$result['mutates_persisted_post_content'] = false;
	$result['creates_revision']               = false;
	$result['changes_post_lock']              = false;
	$result['records_presence_heartbeat']     = false;
	$result['writes_presence']                = false;
	$result['installs_presence_table']        = false;
	$result['automatic_table_install']        = false;
	$result['starts_polling']                 = false;
	$result['enables_repeated_client_refresh'] = false;
	$result['claims_absence']                 = false;
	$result['claims_saved']                   = false;
	$result['contains_raw_content']           = false;
	$result['exposes_raw_content']            = false;
	$result['exposes_user_ids']               = false;
	$result['exposes_logins']                 = false;
	$result['exposes_email']                  = false;
	$result['exposes_cursor_offset']          = false;
	$result['exposes_selection']              = false;
	$result['exposes_selection_presence']     = true;
	$result['exposes_raw_selected_text']      = false;

	return rest_ensure_response( $result );
}

/**
 * Handles the sync-meta recovery REST endpoint.
 *
 * @since 7.1.0
 *
 * @param WP_REST_Request $request Full details about the request.
 * @return WP_REST_Response|WP_Error REST response on success, otherwise a WP_Error.
 */
function wp_de_rtc_rest_recovery_endpoint( $request ) {
	$post_id = (int) $request['id'];
	$mode    = $request->get_param( 'mode' );
	$mode    = is_string( $mode ) ? $mode : 'dry_run';
	$plan    = wp_de_rtc_plan_sync_meta_recovery_update( $post_id );

	if ( is_wp_error( $plan ) ) {
		return $plan;
	}

	if ( $request->has_param( 'candidate_post_content_hash' ) ) {
		$plan['candidate_post_content_hash'] = (string) $request->get_param( 'candidate_post_content_hash' );
	}

	if ( 'apply' === $mode ) {
		$result = wp_de_rtc_apply_sync_meta_recovery_update(
			$plan,
			array(
				'mode' => 'apply',
			)
		);
	} else {
		$result = wp_de_rtc_dry_run_sync_meta_recovery_update( $plan );
	}

	if ( is_wp_error( $result ) ) {
		return $result;
	}

	$result['rest_route']          = 'post_sync_meta_recovery';
	$result['permission_contract'] = wp_de_rtc_get_rest_recovery_permission_contract( $post_id );

	return rest_ensure_response( $result );
}

/**
 * Handles the stale-base rejection REST endpoint.
 *
 * This proof endpoint models the future save-path response contract only. It
 * does not save, rebase, refetch, repair sync metadata, replace post locks, or
 * create revisions.
 *
 * @since 7.1.0
 *
 * @param WP_REST_Request $request Full details about the request.
 * @return WP_Error Stale-base rejection error with normalized DE-RTC data.
 */
function wp_de_rtc_rest_stale_base_endpoint( $request ) {
	return wp_de_rtc_get_stale_base_rejection_error(
		(int) $request['id'],
		array(
			'client_base_version'      => $request->get_param( 'client_base_version' ),
			'server_version'           => $request->get_param( 'server_version' ),
			'pending_change_count'     => $request->get_param( 'pending_change_count' ),
			'remote_change_count'      => $request->get_param( 'remote_change_count' ),
			'can_attempt_local_rebase' => $request->get_param( 'can_attempt_local_rebase' ),
			'rest_route'               => 'post_stale_base_rejection',
		)
	);
}

/**
 * Handles the retry-submit proof REST endpoint.
 *
 * This endpoint proves the server-side acceptance gate for a rebased client
 * retry. It compares the client base version against the current sync metadata
 * version and returns either an accepted-for-future-save response or the
 * canonical stale-base rejection. It does not save, mutate post content, create
 * revisions, replace post locks, or claim the post is persisted.
 *
 * @since 7.1.0
 *
 * @param WP_REST_Request $request Full details about the request.
 * @return WP_REST_Response|WP_Error REST response on success, otherwise a stale-base error.
 */
function wp_de_rtc_rest_retry_submit_endpoint( $request ) {
	$result = wp_de_rtc_get_retry_submit_acceptance_result(
		(int) $request['id'],
		array(
			'client_base_version'        => $request->get_param( 'client_base_version' ),
			'rebased_from_version'       => $request->get_param( 'rebased_from_version' ),
			'pending_change_count'       => $request->get_param( 'pending_change_count' ),
			'proposed_post_content_hash'  => $request->get_param( 'proposed_post_content_hash' ),
		)
	);

	if ( is_wp_error( $result ) ) {
		return $result;
	}

	return rest_ensure_response( $result );
}

/**
 * Handles the retry-save REST endpoint.
 *
 * This endpoint is the first explicit write boundary for a retry after stale-
 * base local rebase. It requires evidence from an accepted retry-submit proof,
 * verifies the server version is still current, and lets the server own the
 * updated sync metadata embedded in post_content.
 *
 * @since 7.1.0
 *
 * @param WP_REST_Request $request Full details about the request.
 * @return WP_REST_Response|WP_Error REST response on success, otherwise an error.
 */
function wp_de_rtc_rest_retry_save_endpoint( $request ) {
	$result = wp_de_rtc_save_retry_submitted_post(
		(int) $request['id'],
		array(
			'client_base_version'                 => $request->get_param( 'client_base_version' ),
			'accepted_proof_server_version'      => $request->get_param( 'accepted_proof_server_version' ),
			'rebased_from_version'               => $request->get_param( 'rebased_from_version' ),
			'pending_change_count'               => $request->get_param( 'pending_change_count' ),
			'proposed_post_content'              => $request->get_param( 'proposed_post_content' ),
			'proposed_post_content_hash'         => $request->get_param( 'proposed_post_content_hash' ),
			'accepted_proof_saves_post'          => $request->get_param( 'accepted_proof_saves_post' ),
			'accepted_proof_mutates_post_content' => $request->get_param( 'accepted_proof_mutates_post_content' ),
			'accepted_proof_creates_revision'    => $request->get_param( 'accepted_proof_creates_revision' ),
			'accepted_proof_claims_saved'        => $request->get_param( 'accepted_proof_claims_saved' ),
			'review_approval_proof'              => $request->has_param( 'accepted_review_approval_proof' ) ? $request->get_param( 'accepted_review_approval_proof' ) : $request->get_param( 'review_approval_proof' ),
			'accepted_fresh_review_decision'     => $request->get_param( 'accepted_fresh_review_decision' ),
			'block_identity_request_proof'       => $request->get_param( 'block_identity_request_proof' ),
			'automerge_client_update'            => $request->get_param( 'automerge_client_update' ),
			'session_key'                        => $request->get_param( 'session_key' ),
			'post_type_rest_base'                => wp_de_rtc_get_rest_retry_save_request_rest_base( $request ),
		)
	);

	if ( is_wp_error( $result ) ) {
		return $result;
	}

	return rest_ensure_response( $result );
}

/**
 * Ensures review workflow REST responses cannot be cached.
 *
 * Review item responses describe ephemeral security workflow state. Even when
 * they contain only descriptors, intermediaries must not reuse them across
 * users, sessions, or review decisions.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $result REST response data.
 * @return WP_REST_Response REST response with no-store headers.
 */
function wp_de_rtc_rest_ensure_no_store_response( $result ) {
	$response = is_wp_error( $result ) ? rest_convert_error_to_response( $result ) : rest_ensure_response( $result );

	$response->header( 'Cache-Control', 'private, no-store, no-cache, must-revalidate, max-age=0' );
	$response->header( 'Pragma', 'no-cache' );
	$response->header( 'Expires', 'Wed, 11 Jan 1984 05:00:00 GMT' );

	return $response;
}

/**
 * Handles the unfiltered-HTML review approval proof REST endpoint.
 *
 * This endpoint accepts only hash and version evidence from the existing
 * retry-save review-required contract. It does not save, mutate post content,
 * create revisions, apply recovery, replace post locks, or claim saved state.
 *
 * @since 7.1.0
 *
 * @param WP_REST_Request $request Full details about the request.
 * @return WP_REST_Response|WP_Error REST response on success, otherwise an error.
 */
function wp_de_rtc_rest_review_approval_endpoint( $request ) {
	$result = wp_de_rtc_get_unfiltered_html_review_approval_result(
		(int) $request['id'],
		array(
			'client_base_version'                  => $request->get_param( 'client_base_version' ),
			'accepted_proof_server_version'        => $request->get_param( 'accepted_proof_server_version' ),
			'pending_change_count'                 => $request->get_param( 'pending_change_count' ),
			'proposed_post_content_hash'           => $request->get_param( 'proposed_post_content_hash' ),
			'reviewed_proposed_content_hash'       => $request->get_param( 'reviewed_proposed_content_hash' ),
			'candidate_post_content_hash'          => $request->get_param( 'candidate_post_content_hash' ),
			'reviewed_candidate_content_hash'      => $request->get_param( 'reviewed_candidate_content_hash' ),
			'kses_filtered_proposed_content_hash'  => $request->get_param( 'kses_filtered_proposed_content_hash' ),
			'kses_filtered_candidate_content_hash' => $request->get_param( 'kses_filtered_candidate_content_hash' ),
			'reviewed_block_items'                 => $request->get_param( 'reviewed_block_items' ),
			'raw_request_params'                   => $request->get_params(),
		)
	);

	return wp_de_rtc_rest_ensure_no_store_response( $result );
}

