/**
 * Returns a proof-only fresh-review request result.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post Post ID or object.
 * @param array       $args {
 *     Fresh-review request arguments.
 *
 *     @type mixed $client_base_version        Client base version.
 *     @type mixed $server_version             Server version known to the caller.
 *     @type mixed $pending_change_count       Pending local change count. Default 1.
 *     @type mixed $proposed_post_content_hash Proposed stripped post-content hash.
 *     @type mixed $candidate_post_content_hash Optional candidate stripped post-content hash.
 *     @type array $raw_request_params         Full request parameters for raw-content rejection.
 * }
 * @return array|WP_Error Fresh-review request result, or rejection.
 */
function wp_de_rtc_get_fresh_review_request_result( $post, $args = array() ) {
	$post = get_post( $post );

	if ( ! $post ) {
		return new WP_Error(
			'rest_post_invalid_id',
			__( 'Invalid post ID.' ),
			array( 'status' => 404 )
		);
	}

	$raw_content_param_paths = isset( $args['raw_request_params'] ) && is_array( $args['raw_request_params'] )
		? wp_de_rtc_find_raw_post_content_param_paths( $args['raw_request_params'] )
		: array();

	if ( ! empty( $raw_content_param_paths ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the fresh review request because raw post content is not allowed.' ),
			array(
				'detail'                       => 'fresh_review_request_raw_post_content_rejected',
				'post_id'                      => (int) $post->ID,
				'rest_route'                   => 'post_fresh_review_request',
				'request_raw_content_included' => true,
				'raw_content_included'         => false,
				'raw_content_param_paths'      => $raw_content_param_paths,
				'saves_post'                   => false,
				'mutates_post_content'         => false,
				'creates_revision'             => false,
				'claims_saved'                 => false,
				'resolves_proof'               => false,
				'resolves_proof_token'         => false,
				'approves_review_proof'        => false,
				'retry_save_attempted'         => false,
				'normal_save_attempted'        => false,
				'applies_recovery'             => false,
				'changes_locks'                => false,
			)
		);
	}

	$client_base_version    = isset( $args['client_base_version'] ) ? sanitize_text_field( (string) $args['client_base_version'] ) : '';
	$request_server_version = isset( $args['server_version'] ) ? sanitize_text_field( (string) $args['server_version'] ) : '';
	$local_import_status    = isset( $args['local_updates_import_status'] ) ? sanitize_text_field( (string) $args['local_updates_import_status'] ) : '';
	$local_import_reason    = isset( $args['local_updates_import_reason'] ) ? sanitize_text_field( (string) $args['local_updates_import_reason'] ) : '';
	$request_status         = isset( $args['fresh_review_request_status'] ) ? sanitize_text_field( (string) $args['fresh_review_request_status'] ) : '';
	$server_version         = wp_de_rtc_get_post_sync_meta_version( $post );
	$pending_change_count   = array_key_exists( 'pending_change_count', $args ) ? max( 0, (int) $args['pending_change_count'] ) : 1;
	$is_imported_fresh_review_request = (
		'blocked' === $local_import_status &&
		'fresh_review_required' === $local_import_reason &&
		'fresh_review_required' === $request_status
	);
	$request_server_matches_current = ( null !== $server_version && $request_server_version === $server_version );
	$client_base_matches_current    = ( null !== $server_version && $client_base_version === $server_version );

	if (
		'' === $client_base_version ||
		'' === $request_server_version ||
		null === $server_version ||
		! $request_server_matches_current ||
		( ! $client_base_matches_current && ! $is_imported_fresh_review_request )
	) {
		return wp_de_rtc_get_stale_base_rejection_error(
			$post,
			array(
				'client_base_version'      => $client_base_version,
				'server_version'           => $server_version,
				'pending_change_count'     => $pending_change_count,
				'remote_change_count'      => 1,
				'can_attempt_local_rebase' => false,
				'rest_route'               => 'post_fresh_review_request_stale_base',
				'saves_post'               => false,
				'mutates_post_content'     => false,
				'creates_revision'         => false,
				'claims_saved'             => false,
			)
		);
	}

	$proposed_post_content_hash  = wp_de_rtc_get_request_hash_evidence( $args, 'proposed_post_content_hash' );
	$candidate_post_content_hash = wp_de_rtc_get_request_hash_evidence( $args, 'candidate_post_content_hash' );
	$missing_hash_fields         = array();

	if ( ! wp_de_rtc_is_sha256_hash( $proposed_post_content_hash ) ) {
		$missing_hash_fields[] = 'proposed_post_content_hash';
	}

	if ( null !== $candidate_post_content_hash && ! wp_de_rtc_is_sha256_hash( $candidate_post_content_hash ) ) {
		$missing_hash_fields[] = 'candidate_post_content_hash';
	}

	if ( ! empty( $missing_hash_fields ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the fresh review request because hash evidence is incomplete.' ),
			array(
				'detail'                       => 'missing_fresh_review_request_hash_evidence',
				'post_id'                      => (int) $post->ID,
				'rest_route'                   => 'post_fresh_review_request',
				'missing_hash_evidence_fields' => $missing_hash_fields,
				'raw_content_included'         => false,
				'saves_post'                   => false,
				'mutates_post_content'         => false,
				'creates_revision'             => false,
				'claims_saved'                 => false,
				'resolves_proof'               => false,
				'resolves_proof_token'         => false,
				'approves_review_proof'        => false,
				'retry_save_attempted'         => false,
				'normal_save_attempted'        => false,
				'applies_recovery'             => false,
				'changes_locks'                => false,
			)
		);
	}

	$request_record = wp_de_rtc_create_opaque_fresh_review_request_record(
		$post,
		array(
			'client_base_version'         => $client_base_version,
			'server_version'              => $server_version,
			'pending_change_count'        => $pending_change_count,
			'proposed_post_content_hash'  => $proposed_post_content_hash,
			'candidate_post_content_hash' => $candidate_post_content_hash,
			'hash_evidence_fields'        => null === $candidate_post_content_hash
				? array( 'proposed_post_content_hash' )
				: array( 'proposed_post_content_hash', 'candidate_post_content_hash' ),
			'is_imported_fresh_review_request' => $is_imported_fresh_review_request,
		)
	);

	if ( is_wp_error( $request_record ) ) {
		return $request_record;
	}

	$request_record_evidence = wp_de_rtc_get_opaque_fresh_review_request_public_evidence( $request_record );

	return array(
		'result'                              => 'fresh_review_request_accepted_for_admin_review',
		'fresh_review_request_accepted'       => true,
		'fresh_review_request_status'         => 'requested',
		'fresh_review_request_recorded'       => true,
		'fresh_review_request_record_id'      => $request_record['public_record_id'],
		'fresh_review_request_record'         => $request_record_evidence,
		'rest_route'                          => 'post_fresh_review_request',
		'post_id'                             => (int) $post->ID,
		'post_type'                           => $post->post_type,
		'client_base_version'                 => $client_base_version,
		'server_version'                      => $server_version,
		'pending_change_count'                => $pending_change_count,
		'hash_evidence_status'                => 'accepted',
		'hash_evidence_fields'                => null === $candidate_post_content_hash
			? array( 'proposed_post_content_hash' )
			: array( 'proposed_post_content_hash', 'candidate_post_content_hash' ),
		'raw_content_included'                => false,
		'reviewed_block_items_included'       => false,
		'requires_admin_review'               => true,
		'review_status'                       => 'fresh_review_requested',
		'review_action'                       => 'request_admin_review',
		'review_scope'                        => 'collaborative_post_content',
		'requires_server_state_refetch'       => false,
		'requires_manual_conflict_resolution' => false,
		'can_export_local_updates'            => $pending_change_count > 0,
		'save_path_required'                  => true,
		'saves_post'                          => false,
		'mutates_post_content'                => false,
		'creates_revision'                    => false,
		'claims_saved'                        => false,
		'resolves_proof'                      => false,
		'resolves_proof_token'                => false,
		'approves_review_proof'               => false,
		'retry_save_attempted'                => false,
		'normal_save_attempted'               => false,
		'applies_recovery'                    => false,
		'changes_locks'                       => false,
		'permission_contract'                 => wp_de_rtc_get_rest_recovery_permission_contract( $post ),
	);
}

/**
 * Returns a proof-only fresh-review decision result.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post Post ID or object.
 * @param array       $args {
 *     Fresh-review decision arguments.
 *
 *     @type mixed $fresh_review_request_record_id Opaque public fresh-review request record ID.
 *     @type mixed $client_base_version            Client base version.
 *     @type mixed $server_version                 Server version known to the reviewer.
 *     @type mixed $fresh_review_decision          Reviewer decision, either approved or rejected.
 *     @type mixed $proposed_post_content_hash     Proposed stripped post-content hash.
 *     @type mixed $reviewed_proposed_content_hash Reviewer-confirmed proposed stripped post-content hash.
 *     @type mixed $candidate_post_content_hash    Optional retry-save candidate post-content hash.
 *     @type mixed $reviewed_candidate_content_hash Optional reviewer-confirmed retry-save candidate hash.
 *     @type array $reviewed_block_items           Optional hash-only risky-block decision items.
 *     @type array $raw_request_params             Full request parameters for raw-content rejection.
 * }
 * @return array|WP_Error Fresh-review decision result, or rejection.
 */
function wp_de_rtc_get_fresh_review_decision_result( $post, $args = array() ) {
	$post = get_post( $post );

	if ( ! $post ) {
		return new WP_Error(
			'rest_post_invalid_id',
			__( 'Invalid post ID.' ),
			array( 'status' => 404 )
		);
	}

	$raw_content_param_paths = isset( $args['raw_request_params'] ) && is_array( $args['raw_request_params'] )
		? wp_de_rtc_find_raw_post_content_param_paths( $args['raw_request_params'] )
		: array();

	if ( ! empty( $raw_content_param_paths ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the fresh review decision because raw post content is not allowed.' ),
			array(
				'detail'                       => 'fresh_review_decision_raw_post_content_rejected',
				'post_id'                      => (int) $post->ID,
				'rest_route'                   => 'post_fresh_review_decision',
				'request_raw_content_included' => true,
				'raw_content_included'         => false,
				'raw_content_param_paths'      => $raw_content_param_paths,
				'saves_post'                   => false,
				'mutates_post_content'         => false,
				'creates_revision'             => false,
				'claims_saved'                 => false,
				'resolves_proof'               => false,
				'resolves_proof_token'         => false,
				'approves_review_proof'        => false,
				'retry_save_attempted'         => false,
				'normal_save_attempted'        => false,
				'applies_recovery'             => false,
				'changes_locks'                => false,
			)
		);
	}

	$record_id = isset( $args['fresh_review_request_record_id'] ) ? sanitize_text_field( (string) $args['fresh_review_request_record_id'] ) : '';
	$record    = wp_de_rtc_get_opaque_fresh_review_request_record( $record_id );

	if (
		! is_array( $record ) ||
		(int) $record['post_id'] !== (int) $post->ID ||
		(string) $record['post_type'] !== (string) $post->post_type
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the fresh review decision because the request record is unavailable.' ),
			array(
				'detail'                         => 'fresh_review_request_record_unavailable',
				'post_id'                        => (int) $post->ID,
				'rest_route'                     => 'post_fresh_review_decision',
				'fresh_review_request_record_id' => $record_id,
				'raw_content_included'           => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
				'resolves_proof'                 => false,
				'resolves_proof_token'           => false,
				'approves_review_proof'          => false,
				'retry_save_attempted'           => false,
				'normal_save_attempted'          => false,
				'applies_recovery'               => false,
				'changes_locks'                  => false,
			)
		);
	}

	$client_base_version    = isset( $args['client_base_version'] ) ? sanitize_text_field( (string) $args['client_base_version'] ) : '';
	$request_server_version = isset( $args['server_version'] ) ? sanitize_text_field( (string) $args['server_version'] ) : '';
	$server_version         = wp_de_rtc_get_post_sync_meta_version( $post );
	$record_client_version  = isset( $record['client_base_version'] ) ? sanitize_text_field( (string) $record['client_base_version'] ) : '';
	$record_server_version  = isset( $record['server_version'] ) ? sanitize_text_field( (string) $record['server_version'] ) : '';
	$pending_change_count   = isset( $record['pending_change_count'] ) ? max( 0, (int) $record['pending_change_count'] ) : 1;

	if (
		'' === $client_base_version ||
		'' === $request_server_version ||
		null === $server_version ||
		$client_base_version !== $record_client_version ||
		$request_server_version !== $server_version ||
		$record_server_version !== $server_version
	) {
		return wp_de_rtc_get_stale_base_rejection_error(
			$post,
			array(
				'client_base_version'      => $client_base_version,
				'server_version'           => $server_version,
				'pending_change_count'     => $pending_change_count,
				'remote_change_count'      => 1,
				'can_attempt_local_rebase' => false,
				'rest_route'               => 'post_fresh_review_decision_stale_base',
				'saves_post'               => false,
				'mutates_post_content'     => false,
				'creates_revision'         => false,
				'claims_saved'             => false,
			)
		);
	}

	$decision = wp_de_rtc_normalize_fresh_review_decision( isset( $args['fresh_review_decision'] ) ? $args['fresh_review_decision'] : '' );

	if ( '' === $decision ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the fresh review decision because the decision is missing or invalid.' ),
			array(
				'detail'                         => 'missing_fresh_review_decision',
				'post_id'                        => (int) $post->ID,
				'rest_route'                     => 'post_fresh_review_decision',
				'fresh_review_request_record_id' => $record['public_record_id'],
				'raw_content_included'           => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
				'resolves_proof'                 => false,
				'resolves_proof_token'           => false,
				'approves_review_proof'          => false,
			)
		);
	}

	$proposed_post_content_hash       = wp_de_rtc_get_request_hash_evidence( $args, 'proposed_post_content_hash' );
	$reviewed_proposed_content_hash  = wp_de_rtc_get_request_hash_evidence( $args, 'reviewed_proposed_content_hash' );
	$candidate_post_content_hash     = wp_de_rtc_get_request_hash_evidence( $args, 'candidate_post_content_hash' );
	$reviewed_candidate_content_hash = wp_de_rtc_get_request_hash_evidence( $args, 'reviewed_candidate_content_hash' );
	$record_proposed_hash            = isset( $record['proposed_post_content_hash'] ) ? sanitize_text_field( (string) $record['proposed_post_content_hash'] ) : '';
	$record_candidate_hash           = isset( $record['candidate_post_content_hash'] ) ? sanitize_text_field( (string) $record['candidate_post_content_hash'] ) : '';
	$missing_hash_fields             = array();

	foreach (
		array(
			'proposed_post_content_hash'      => $proposed_post_content_hash,
			'reviewed_proposed_content_hash' => $reviewed_proposed_content_hash,
		) as $field => $hash
	) {
		if ( ! wp_de_rtc_is_sha256_hash( $hash ) ) {
			$missing_hash_fields[] = $field;
		}
	}

	if ( '' !== $record_candidate_hash || null !== $candidate_post_content_hash || null !== $reviewed_candidate_content_hash ) {
		foreach (
			array(
				'candidate_post_content_hash'          => $candidate_post_content_hash,
				'reviewed_candidate_content_hash'     => $reviewed_candidate_content_hash,
			) as $field => $hash
		) {
			if ( ! wp_de_rtc_is_sha256_hash( $hash ) ) {
				$missing_hash_fields[] = $field;
			}
		}
	}

	if ( ! empty( $missing_hash_fields ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the fresh review decision because hash evidence is incomplete.' ),
			array(
				'detail'                         => 'missing_fresh_review_decision_hash_evidence',
				'post_id'                        => (int) $post->ID,
				'rest_route'                     => 'post_fresh_review_decision',
				'fresh_review_request_record_id' => $record['public_record_id'],
				'missing_hash_evidence_fields'   => $missing_hash_fields,
				'raw_content_included'           => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
				'resolves_proof'                 => false,
				'resolves_proof_token'           => false,
				'approves_review_proof'          => false,
			)
		);
	}

	$mismatched_hash_fields = array();

	if ( ! hash_equals( $record_proposed_hash, $proposed_post_content_hash ) ) {
		$mismatched_hash_fields[] = 'proposed_post_content_hash';
	}

	if ( ! hash_equals( $record_proposed_hash, $reviewed_proposed_content_hash ) ) {
		$mismatched_hash_fields[] = 'reviewed_proposed_content_hash';
	}

	if ( '' !== $record_candidate_hash && ! hash_equals( $record_candidate_hash, $candidate_post_content_hash ) ) {
		$mismatched_hash_fields[] = 'candidate_post_content_hash';
	}

	if ( '' !== $record_candidate_hash && ! hash_equals( $record_candidate_hash, $reviewed_candidate_content_hash ) ) {
		$mismatched_hash_fields[] = 'reviewed_candidate_content_hash';
	} elseif ( '' === $record_candidate_hash && null !== $candidate_post_content_hash && ! hash_equals( $candidate_post_content_hash, $reviewed_candidate_content_hash ) ) {
		$mismatched_hash_fields[] = 'reviewed_candidate_content_hash';
	}

	if ( ! empty( $mismatched_hash_fields ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the fresh review decision because the reviewed hash evidence does not match.' ),
			array(
				'detail'                          => 'fresh_review_decision_hash_evidence_mismatch',
				'post_id'                         => (int) $post->ID,
				'rest_route'                      => 'post_fresh_review_decision',
				'fresh_review_request_record_id'  => $record['public_record_id'],
				'mismatched_hash_evidence_fields' => $mismatched_hash_fields,
				'raw_content_included'            => false,
				'saves_post'                      => false,
				'mutates_post_content'            => false,
				'creates_revision'                => false,
				'claims_saved'                    => false,
				'resolves_proof'                  => false,
				'resolves_proof_token'            => false,
				'approves_review_proof'           => false,
			)
		);
	}

	$reviewed_block_items = wp_de_rtc_get_normalized_fresh_review_decision_block_items( $post, $args, $decision );

	if ( is_wp_error( $reviewed_block_items ) ) {
		return $reviewed_block_items;
	}

	$updated_record = wp_de_rtc_record_opaque_fresh_review_decision(
		$record,
		$post,
		array(
			'client_base_version'             => $client_base_version,
			'server_version'                  => $server_version,
			'fresh_review_decision'           => $decision,
			'proposed_post_content_hash'      => $proposed_post_content_hash,
			'reviewed_proposed_content_hash'  => $reviewed_proposed_content_hash,
			'candidate_post_content_hash'     => $candidate_post_content_hash,
			'reviewed_candidate_content_hash' => $reviewed_candidate_content_hash,
			'reviewed_block_items'            => $reviewed_block_items,
		)
	);

	if ( is_wp_error( $updated_record ) ) {
		return $updated_record;
	}

	$review_status = 'approved' === $decision ? 'approved_by_unfiltered_html_reviewer' : 'rejected_by_unfiltered_html_reviewer';
	$hash_fields   = array( 'proposed_post_content_hash', 'reviewed_proposed_content_hash' );

	if ( null !== $candidate_post_content_hash || '' !== $record_candidate_hash ) {
		$hash_fields[] = 'candidate_post_content_hash';
		$hash_fields[] = 'reviewed_candidate_content_hash';
	}

	return array(
		'result'                              => 'approved' === $decision ? 'fresh_review_decision_approved_for_retry_save' : 'fresh_review_decision_rejected_for_author_revision',
		'fresh_review_decision_accepted'      => true,
		'fresh_review_decision'               => $decision,
		'fresh_review_decision_status'        => $decision,
		'fresh_review_request_status'         => 'decision_recorded',
		'fresh_review_request_record_id'      => $updated_record['public_record_id'],
		'fresh_review_request_record'         => wp_de_rtc_get_opaque_fresh_review_request_public_evidence( $updated_record ),
		'rest_route'                          => 'post_fresh_review_decision',
		'post_id'                             => (int) $post->ID,
		'post_type'                           => $post->post_type,
		'client_base_version'                 => $client_base_version,
		'server_version'                      => $server_version,
		'pending_change_count'                => $pending_change_count,
		'hash_evidence_status'                => 'accepted',
		'hash_evidence_fields'                => $hash_fields,
		'raw_content_included'                => false,
		'reviewed_block_items_included'       => ! empty( $reviewed_block_items ),
		'reviewed_block_item_count'           => count( $reviewed_block_items ),
		'reviewed_block_decision_counts'      => wp_de_rtc_count_fresh_review_decision_block_items( $reviewed_block_items ),
		'requires_admin_review'               => false,
		'review_status'                       => $review_status,
		'review_action'                       => 'record_fresh_review_decision',
		'review_scope'                        => 'collaborative_post_content',
		'requires_server_state_refetch'       => false,
		'requires_manual_conflict_resolution' => false,
		'can_export_local_updates'            => $pending_change_count > 0,
		'save_path_required'                  => true,
		'saves_post'                          => false,
		'mutates_post_content'                => false,
		'creates_revision'                    => false,
		'claims_saved'                        => false,
		'resolves_proof'                      => false,
		'resolves_proof_token'                => false,
		'approves_review_proof'               => false,
		'retry_save_attempted'                => false,
		'normal_save_attempted'               => false,
		'applies_recovery'                    => false,
		'changes_locks'                       => false,
		'permission_contract'                 => wp_de_rtc_get_rest_recovery_permission_contract( $post ),
	);
}

/**
 * Returns a no-write fresh-review decision consumption result.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post Post ID or object.
 * @param array       $args {
 *     Fresh-review consume arguments.
 *
 *     @type mixed $fresh_review_request_record_id Opaque public fresh-review request record ID.
 *     @type mixed $client_base_version            Client base version from the recorded decision.
 *     @type mixed $server_version                 Server version known to the caller.
 *     @type mixed $proposed_post_content_hash     Proposed stripped post-content hash.
 *     @type mixed $reviewed_proposed_content_hash Reviewer-confirmed proposed stripped post-content hash.
 *     @type mixed $candidate_post_content_hash    Optional retry-save candidate post-content hash.
 *     @type mixed $reviewed_candidate_content_hash Optional reviewer-confirmed retry-save candidate hash.
 *     @type array $raw_request_params             Full request parameters for raw-content rejection.
 * }
 * @return array|WP_Error Fresh-review consumption result, or rejection.
 */
function wp_de_rtc_get_fresh_review_consume_result( $post, $args = array() ) {
	$post = get_post( $post );

	if ( ! $post ) {
		return new WP_Error(
			'rest_post_invalid_id',
			__( 'Invalid post ID.' ),
			array( 'status' => 404 )
		);
	}

	$raw_content_param_paths = isset( $args['raw_request_params'] ) && is_array( $args['raw_request_params'] )
		? wp_de_rtc_find_raw_post_content_param_paths( $args['raw_request_params'] )
		: array();

	if ( ! empty( $raw_content_param_paths ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected fresh-review decision consumption because raw post content is not allowed.' ),
			array(
				'detail'                       => 'fresh_review_consume_raw_post_content_rejected',
				'post_id'                      => (int) $post->ID,
				'rest_route'                   => 'post_fresh_review_consume',
				'request_raw_content_included' => true,
				'raw_content_included'         => false,
				'raw_content_param_paths'      => $raw_content_param_paths,
				'saves_post'                   => false,
				'mutates_post_content'         => false,
				'creates_revision'             => false,
				'claims_saved'                 => false,
				'resolves_proof'               => false,
				'resolves_proof_token'         => false,
				'approves_review_proof'        => false,
				'consumes_review_decision'     => false,
				'retry_save_attempted'         => false,
				'normal_save_attempted'        => false,
				'applies_recovery'             => false,
				'changes_locks'                => false,
			)
		);
	}

	$record_id = isset( $args['fresh_review_request_record_id'] ) ? sanitize_text_field( (string) $args['fresh_review_request_record_id'] ) : '';
	$record    = wp_de_rtc_get_opaque_fresh_review_request_record( $record_id );

	if (
		! is_array( $record ) ||
		(int) $record['post_id'] !== (int) $post->ID ||
		(string) $record['post_type'] !== (string) $post->post_type
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected fresh-review decision consumption because the decision record is unavailable.' ),
			array(
				'detail'                         => 'fresh_review_decision_record_unavailable',
				'post_id'                        => (int) $post->ID,
				'rest_route'                     => 'post_fresh_review_consume',
				'fresh_review_request_record_id' => $record_id,
				'raw_content_included'           => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
				'resolves_proof'                 => false,
				'resolves_proof_token'           => false,
				'approves_review_proof'          => false,
				'consumes_review_decision'       => false,
				'retry_save_attempted'           => false,
				'normal_save_attempted'          => false,
				'applies_recovery'               => false,
				'changes_locks'                  => false,
			)
		);
	}

	if (
		! empty( $record['fresh_review_decision_consumed'] ) ||
		! empty( $record['fresh_review_decision_consumption_claimed'] ) ||
		! empty( $record['consumes_review_decision'] ) ||
		! empty( $record['retry_save_applied'] )
	) {
		return wp_de_rtc_get_fresh_review_decision_consumption_conflict_error( $post, $record, 'post_fresh_review_consume' );
	}

	if (
		empty( $record['decision_recorded'] ) ||
		! isset( $record['fresh_review_decision'] ) ||
		'approved' !== wp_de_rtc_normalize_fresh_review_decision( $record['fresh_review_decision'] )
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected fresh-review decision consumption because the recorded decision is not approved.' ),
			array(
				'detail'                         => 'fresh_review_decision_not_approved_for_retry_save',
				'post_id'                        => (int) $post->ID,
				'rest_route'                     => 'post_fresh_review_consume',
				'fresh_review_request_record_id' => $record['public_record_id'],
				'fresh_review_decision_status'   => isset( $record['fresh_review_decision_status'] ) ? sanitize_key( (string) $record['fresh_review_decision_status'] ) : '',
				'raw_content_included'           => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
				'resolves_proof'                 => false,
				'resolves_proof_token'           => false,
				'approves_review_proof'          => false,
				'consumes_review_decision'       => false,
				'retry_save_attempted'           => false,
				'normal_save_attempted'          => false,
				'applies_recovery'               => false,
				'changes_locks'                  => false,
			)
		);
	}

	$reviewer_authority_error = wp_de_rtc_get_fresh_review_reviewer_authority_recheck_error( $post, $record, 'post_fresh_review_consume' );

	if ( is_wp_error( $reviewer_authority_error ) ) {
		return $reviewer_authority_error;
	}

	$client_base_version    = isset( $args['client_base_version'] ) ? sanitize_text_field( (string) $args['client_base_version'] ) : '';
	$request_server_version = isset( $args['server_version'] ) ? sanitize_text_field( (string) $args['server_version'] ) : '';
	$server_version         = wp_de_rtc_get_post_sync_meta_version( $post );
	$record_client_version  = isset( $record['client_base_version_at_decision'] ) ? sanitize_text_field( (string) $record['client_base_version_at_decision'] ) : '';
	$record_server_version  = isset( $record['server_version_at_decision'] ) ? sanitize_text_field( (string) $record['server_version_at_decision'] ) : '';
	$pending_change_count   = isset( $record['pending_change_count'] ) ? max( 0, (int) $record['pending_change_count'] ) : 1;
	$is_imported_fresh_review_request = ! empty( $record['is_imported_fresh_review_request'] ) || ! empty( $record['imported_fresh_review_handoff'] );
	$client_base_matches_record       = $client_base_version === $record_client_version;
	$client_base_matches_current      = null !== $server_version && $client_base_version === $server_version;

	if (
		'' === $client_base_version ||
		'' === $request_server_version ||
		null === $server_version ||
		( ! $client_base_matches_record && ! ( $is_imported_fresh_review_request && $client_base_matches_current ) ) ||
		$request_server_version !== $server_version ||
		$record_server_version !== $server_version
	) {
		return wp_de_rtc_get_stale_base_rejection_error(
			$post,
			array(
				'client_base_version'      => $client_base_version,
				'server_version'           => $server_version,
				'pending_change_count'     => $pending_change_count,
				'remote_change_count'      => 1,
				'can_attempt_local_rebase' => false,
				'rest_route'               => 'post_fresh_review_consume_stale_base',
				'saves_post'               => false,
				'mutates_post_content'     => false,
				'creates_revision'         => false,
				'claims_saved'             => false,
			)
		);
	}

	$proposed_post_content_hash       = wp_de_rtc_get_request_hash_evidence( $args, 'proposed_post_content_hash' );
	$reviewed_proposed_content_hash  = wp_de_rtc_get_request_hash_evidence( $args, 'reviewed_proposed_content_hash' );
	$candidate_post_content_hash     = wp_de_rtc_get_request_hash_evidence( $args, 'candidate_post_content_hash' );
	$reviewed_candidate_content_hash = wp_de_rtc_get_request_hash_evidence( $args, 'reviewed_candidate_content_hash' );
	$record_proposed_hash            = isset( $record['proposed_post_content_hash'] ) ? sanitize_text_field( (string) $record['proposed_post_content_hash'] ) : '';
	$record_reviewed_proposed_hash   = isset( $record['reviewed_proposed_content_hash'] ) ? sanitize_text_field( (string) $record['reviewed_proposed_content_hash'] ) : '';
	$record_candidate_hash           = isset( $record['candidate_post_content_hash'] ) ? sanitize_text_field( (string) $record['candidate_post_content_hash'] ) : '';
	$record_reviewed_candidate_hash  = isset( $record['reviewed_candidate_content_hash'] ) ? sanitize_text_field( (string) $record['reviewed_candidate_content_hash'] ) : '';
	$missing_hash_fields             = array();

	foreach (
		array(
			'proposed_post_content_hash'      => $proposed_post_content_hash,
			'reviewed_proposed_content_hash' => $reviewed_proposed_content_hash,
		) as $field => $hash
	) {
		if ( ! wp_de_rtc_is_sha256_hash( $hash ) ) {
			$missing_hash_fields[] = $field;
		}
	}

	if ( '' !== $record_candidate_hash || '' !== $record_reviewed_candidate_hash || null !== $candidate_post_content_hash || null !== $reviewed_candidate_content_hash ) {
		foreach (
			array(
				'candidate_post_content_hash'          => $candidate_post_content_hash,
				'reviewed_candidate_content_hash'     => $reviewed_candidate_content_hash,
			) as $field => $hash
		) {
			if ( ! wp_de_rtc_is_sha256_hash( $hash ) ) {
				$missing_hash_fields[] = $field;
			}
		}
	}

	if ( ! empty( $missing_hash_fields ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected fresh-review decision consumption because hash evidence is incomplete.' ),
			array(
				'detail'                         => 'missing_fresh_review_consume_hash_evidence',
				'post_id'                        => (int) $post->ID,
				'rest_route'                     => 'post_fresh_review_consume',
				'fresh_review_request_record_id' => $record['public_record_id'],
				'missing_hash_evidence_fields'   => $missing_hash_fields,
				'raw_content_included'           => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
				'resolves_proof'                 => false,
				'resolves_proof_token'           => false,
				'approves_review_proof'          => false,
				'consumes_review_decision'       => false,
			)
		);
	}

	$mismatched_hash_fields = array();

	if ( ! hash_equals( $record_proposed_hash, $proposed_post_content_hash ) ) {
		$mismatched_hash_fields[] = 'proposed_post_content_hash';
	}

	if ( ! hash_equals( $record_reviewed_proposed_hash, $reviewed_proposed_content_hash ) ) {
		$mismatched_hash_fields[] = 'reviewed_proposed_content_hash';
	}

	if ( '' !== $record_candidate_hash && ! hash_equals( $record_candidate_hash, $candidate_post_content_hash ) ) {
		$mismatched_hash_fields[] = 'candidate_post_content_hash';
	}

	if ( '' !== $record_reviewed_candidate_hash && ! hash_equals( $record_reviewed_candidate_hash, $reviewed_candidate_content_hash ) ) {
		$mismatched_hash_fields[] = 'reviewed_candidate_content_hash';
	}

	if ( ! empty( $mismatched_hash_fields ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected fresh-review decision consumption because recorded hash evidence does not match.' ),
			array(
				'detail'                          => 'fresh_review_consume_hash_evidence_mismatch',
				'post_id'                         => (int) $post->ID,
				'rest_route'                      => 'post_fresh_review_consume',
				'fresh_review_request_record_id'  => $record['public_record_id'],
				'mismatched_hash_evidence_fields' => $mismatched_hash_fields,
				'raw_content_included'            => false,
				'saves_post'                      => false,
				'mutates_post_content'            => false,
				'creates_revision'                => false,
				'claims_saved'                    => false,
				'resolves_proof'                  => false,
				'resolves_proof_token'            => false,
				'approves_review_proof'           => false,
				'consumes_review_decision'        => false,
			)
		);
	}

	$hash_fields = array( 'proposed_post_content_hash', 'reviewed_proposed_content_hash' );

	if ( '' !== $record_candidate_hash || '' !== $record_reviewed_candidate_hash ) {
		$hash_fields[] = 'candidate_post_content_hash';
		$hash_fields[] = 'reviewed_candidate_content_hash';
	}

	return array(
		'result'                              => 'fresh_review_decision_eligible_for_retry_save_handoff',
		'fresh_review_decision_consumption_validated' => true,
		'fresh_review_decision_eligible_for_retry_save' => true,
		'fresh_review_decision_status'        => 'approved',
		'fresh_review_request_status'         => 'decision_recorded',
		'fresh_review_request_record_id'      => $record['public_record_id'],
		'fresh_review_request_record'         => wp_de_rtc_get_opaque_fresh_review_request_public_evidence( $record ),
		'rest_route'                          => 'post_fresh_review_consume',
		'post_id'                             => (int) $post->ID,
		'post_type'                           => $post->post_type,
		'client_base_version'                 => $client_base_version,
		'server_version'                      => $server_version,
		'pending_change_count'                => $pending_change_count,
		'hash_evidence_status'                => 'accepted',
		'hash_evidence_fields'                => $hash_fields,
		'raw_content_included'                => false,
		'reviewed_block_items_included'       => ! empty( $record['reviewed_block_items_included'] ),
		'reviewed_block_item_count'           => isset( $record['reviewed_block_item_count'] ) ? max( 0, (int) $record['reviewed_block_item_count'] ) : 0,
		'reviewed_block_decision_counts'      => isset( $record['reviewed_block_decision_counts'] ) && is_array( $record['reviewed_block_decision_counts'] ) ? $record['reviewed_block_decision_counts'] : array(
			'approved' => 0,
			'rejected' => 0,
		),
		'requires_admin_review'               => false,
		'review_status'                       => 'approved_by_unfiltered_html_reviewer',
		'review_action'                       => 'consume_fresh_review_decision',
		'approval_status'                     => 'eligible_for_retry_save_handoff',
		'approval_action'                     => 'prepare_retry_save_handoff',
		'review_required_capability'          => 'unfiltered_html',
		'reviewer_capability'                 => 'unfiltered_html',
		'review_scope'                        => 'collaborative_post_content',
		'requires_server_state_refetch'       => false,
		'requires_manual_conflict_resolution' => false,
		'can_export_local_updates'            => $pending_change_count > 0,
		'save_path_required'                  => true,
		'saves_post'                          => false,
		'mutates_post_content'                => false,
		'creates_revision'                    => false,
		'claims_saved'                        => false,
		'resolves_proof'                      => false,
		'resolves_proof_token'                => false,
		'approves_review_proof'               => false,
		'consumes_review_decision'            => false,
		'retry_save_attempted'                => false,
		'normal_save_attempted'               => false,
		'applies_recovery'                    => false,
		'changes_locks'                       => false,
		'permission_contract'                 => wp_de_rtc_get_rest_recovery_permission_contract( $post ),
	);
}

/**
 * Returns support-safe lifecycle debug evidence for a fresh-review record.
 *
 * This is read-only support evidence. It intentionally returns lifecycle
 * labels, counts, version labels, and field names only. It does not expose raw
 * content, reviewer identity, saver identity, proof internals, or block bodies.
 *
 * @since 7.1.0
 * @access private
 *
 * @param int|WP_Post $post Post ID or object.
 * @param array       $args {
 *     Lifecycle debug arguments.
 *
 *     @type string $fresh_review_request_record_id Opaque public record ID.
 * }
 * @return array|WP_Error Lifecycle debug result, or rejection.
 */
function wp_de_rtc_get_fresh_review_lifecycle_debug_result( $post, $args = array() ) {
	$post      = get_post( $post );
	$post_id   = $post ? (int) $post->ID : 0;
	$record_id = isset( $args['fresh_review_request_record_id'] ) ? sanitize_text_field( (string) $args['fresh_review_request_record_id'] ) : '';
	$record    = wp_de_rtc_get_opaque_fresh_review_request_record( $record_id );
	$action    = isset( $args['lifecycle_action'] ) ? sanitize_key( (string) $args['lifecycle_action'] ) : 'classify';
	$action    = in_array( $action, array( 'inject_stale_consumption_claim', 'reclaim_stale_consumption_claim' ), true ) ? $action : 'classify';

	if (
		! $post ||
		! is_array( $record ) ||
		(int) $record['post_id'] !== $post_id ||
		(string) $record['post_type'] !== (string) $post->post_type
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing could not retrieve the fresh-review lifecycle record.' ),
			array(
				'detail'                         => 'fresh_review_lifecycle_record_unavailable',
				'post_id'                        => $post_id,
				'rest_route'                     => 'post_fresh_review_lifecycle',
				'fresh_review_request_record_id' => $record_id,
				'fresh_review_lifecycle_debug_available' => false,
				'fresh_review_support_evidence_available' => false,
				'raw_content_included'           => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
			)
		);
	}

	$public_record_evidence = wp_de_rtc_get_opaque_fresh_review_request_public_evidence( $record );
	$debug_contract         = wp_de_rtc_get_fresh_review_lifecycle_debug_contract( $record );
	$action_result          = array(
		'fresh_review_lifecycle_action'         => $action,
		'fresh_review_lifecycle_action_applied' => false,
	);

	if ( 'inject_stale_consumption_claim' === $action ) {
		$action_result = wp_de_rtc_inject_stale_fresh_review_decision_consumption_claim(
			$record,
			$post,
			array(
				'previous_server_version'     => isset( $args['previous_server_version'] ) ? $args['previous_server_version'] : null,
				'proposed_post_content_hash'  => isset( $args['proposed_post_content_hash'] ) ? $args['proposed_post_content_hash'] : null,
				'candidate_post_content_hash' => isset( $args['candidate_post_content_hash'] ) ? $args['candidate_post_content_hash'] : null,
				'claim_age_seconds'           => isset( $args['claim_age_seconds'] ) ? $args['claim_age_seconds'] : null,
			)
		);

		if ( is_wp_error( $action_result ) ) {
			return $action_result;
		}

		$record = wp_de_rtc_get_opaque_fresh_review_request_record( $record_id );
	} elseif ( 'reclaim_stale_consumption_claim' === $action ) {
		$action_result = wp_de_rtc_get_stale_fresh_review_decision_consumption_claim_cleanup_result(
			$record,
			$post,
			array(
				'mode' => 'reclaim',
			)
		);

		if ( is_wp_error( $action_result ) ) {
			return $action_result;
		}

		$action_result['fresh_review_lifecycle_action']         = 'reclaim_stale_consumption_claim';
		$action_result['fresh_review_lifecycle_action_applied'] = ! empty( $action_result['fresh_review_claim_reclaimed'] );
		$record = wp_de_rtc_get_opaque_fresh_review_request_record( $record_id );
	}

	if ( ! is_array( $record ) ) {
		$record = array();
	}

	$public_record_evidence = wp_de_rtc_get_opaque_fresh_review_request_public_evidence( $record );
	$debug_contract         = wp_de_rtc_get_fresh_review_lifecycle_debug_contract( $record );
	$claim_cleanup_mode     = 'reclaim_stale_consumption_claim' === $action ? 'reclaim' : 'classify';
	$claim_cleanup          = 'reclaim_stale_consumption_claim' === $action
		? $action_result
		: wp_de_rtc_get_stale_fresh_review_decision_consumption_claim_cleanup_result(
			$record,
			$post,
			array(
				'mode' => $claim_cleanup_mode,
			)
		);

	if ( is_wp_error( $claim_cleanup ) ) {
		$claim_cleanup = array();
	}

	return array(
		'result'                                  => 'fresh_review_lifecycle_debug_available',
		'fresh_review_lifecycle_debug_available' => true,
		'fresh_review_support_evidence_available' => true,
		'fresh_review_request_record_id'          => $record['public_record_id'],
		'fresh_review_request_record'             => $public_record_evidence,
		'fresh_review_debug_contract'             => $debug_contract,
		'fresh_review_request_status'             => isset( $record['fresh_review_request_status'] ) ? sanitize_key( (string) $record['fresh_review_request_status'] ) : '',
		'fresh_review_decision_recorded'          => ! empty( $record['decision_recorded'] ),
		'fresh_review_decision_status'            => isset( $record['fresh_review_decision_status'] ) ? sanitize_key( (string) $record['fresh_review_decision_status'] ) : '',
		'fresh_review_decision_consumed'          => ! empty( $record['fresh_review_decision_consumed'] ),
		'fresh_review_decision_consumption_claimed' => ! empty( $record['fresh_review_decision_consumption_claimed'] ),
		'fresh_review_retry_save_applied'         => ! empty( $record['retry_save_applied'] ),
		'fresh_review_consumes_review_decision'   => ! empty( $record['consumes_review_decision'] ),
		'fresh_review_lifecycle_status'           => isset( $debug_contract['lifecycle_status'] ) ? $debug_contract['lifecycle_status'] : '',
		'fresh_review_lifecycle_event'            => isset( $debug_contract['lifecycle_event'] ) ? $debug_contract['lifecycle_event'] : '',
		'fresh_review_lifecycle_reason'           => isset( $debug_contract['lifecycle_reason'] ) ? $debug_contract['lifecycle_reason'] : '',
		'fresh_review_claim_cleanup'              => $claim_cleanup,
		'fresh_review_claim_cleanup_status'       => isset( $claim_cleanup['fresh_review_claim_cleanup_status'] ) ? $claim_cleanup['fresh_review_claim_cleanup_status'] : '',
		'fresh_review_claim_is_stale'             => ! empty( $claim_cleanup['fresh_review_claim_is_stale'] ),
		'fresh_review_claim_can_reclaim'          => ! empty( $claim_cleanup['fresh_review_claim_can_reclaim'] ),
		'fresh_review_lifecycle_support_action'   => $action,
		'fresh_review_lifecycle_action_result'    => $action_result,
		'fresh_review_imported_handoff'           => ! empty( $record['imported_fresh_review_handoff'] ),
		'fresh_review_previous_server_version'    => isset( $record['previous_server_version'] ) ? sanitize_text_field( (string) $record['previous_server_version'] ) : '',
		'fresh_review_saved_server_version'       => isset( $record['saved_server_version'] ) ? sanitize_text_field( (string) $record['saved_server_version'] ) : '',
		'fresh_review_reviewed_block_item_count'  => isset( $record['reviewed_block_item_count'] ) ? max( 0, (int) $record['reviewed_block_item_count'] ) : 0,
		'fresh_review_reviewed_block_decision_counts' => isset( $record['reviewed_block_decision_counts'] ) && is_array( $record['reviewed_block_decision_counts'] ) ? wp_de_rtc_get_fresh_review_public_decision_counts( $record['reviewed_block_decision_counts'] ) : array(
			'approved' => 0,
			'rejected' => 0,
		),
		'rest_route'                              => 'post_fresh_review_lifecycle',
		'post_id'                                 => $post_id,
		'post_type'                               => $post->post_type,
		'raw_content_included'                    => false,
		'proof_internals_exposed'                 => false,
		'reviewer_identity_exposed'               => false,
		'saver_identity_exposed'                  => false,
		'saves_post'                              => false,
		'mutates_post_content'                    => false,
		'creates_revision'                        => false,
		'claims_saved'                            => false,
	);
}

/**
 * Returns the redacted lifecycle debug contract for a fresh-review record.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $record Fresh-review request record.
 * @return array Support-safe lifecycle debug contract.
 */
function wp_de_rtc_get_fresh_review_lifecycle_debug_contract( $record ) {
	if ( ! is_array( $record ) ) {
		$record = array();
	}

	$hash_evidence_fields = isset( $record['hash_evidence_fields'] ) && is_array( $record['hash_evidence_fields'] )
		? array_values( array_unique( array_map( 'sanitize_key', $record['hash_evidence_fields'] ) ) )
		: array();

	foreach ( array( 'proposed_post_content_hash', 'reviewed_proposed_content_hash', 'candidate_post_content_hash', 'reviewed_candidate_content_hash', 'saved_post_content_hash', 'retry_save_proposed_post_content_hash' ) as $field ) {
		if ( isset( $record[ $field ] ) && '' !== (string) $record[ $field ] ) {
			$hash_evidence_fields[] = $field;
		}
	}

	$hash_evidence_fields = array_values( array_unique( array_map( 'sanitize_key', $hash_evidence_fields ) ) );
	sort( $hash_evidence_fields );

	$lifecycle_status = isset( $record['fresh_review_lifecycle_status'] ) ? sanitize_key( (string) $record['fresh_review_lifecycle_status'] ) : '';

	if ( '' === $lifecycle_status ) {
		if ( ! empty( $record['fresh_review_decision_consumed'] ) ) {
			$lifecycle_status = 'retry_save_consumed';
		} elseif ( ! empty( $record['decision_recorded'] ) ) {
			$lifecycle_status = 'decision_recorded';
		} elseif ( ! empty( $record['public_record_id'] ) ) {
			$lifecycle_status = 'requested';
		}
	}

	$reviewer_identity_retained = ! empty( $record['reviewer_user_id'] );
	$claim_stale_after_seconds = wp_de_rtc_get_fresh_review_decision_consumption_claim_stale_after_seconds();
	$claim_started_at          = isset( $record['fresh_review_decision_consumption_claimed_at'] ) && is_numeric( $record['fresh_review_decision_consumption_claimed_at'] )
		? (int) $record['fresh_review_decision_consumption_claimed_at']
		: 0;

	return array(
		'contract'                                   => 'support_safe_fresh_review_lifecycle_debug',
		'contract_version'                           => 1,
		'storage'                                    => isset( $record['audit_storage_engine'] ) ? sanitize_key( (string) $record['audit_storage_engine'] ) : 'option',
		'record_found'                               => ! empty( $record['public_record_id'] ),
		'record_id'                                  => isset( $record['public_record_id'] ) ? sanitize_text_field( (string) $record['public_record_id'] ) : '',
		'status'                                     => isset( $record['status'] ) ? sanitize_key( (string) $record['status'] ) : '',
		'lifecycle_status'                           => $lifecycle_status,
		'lifecycle_event'                            => isset( $record['fresh_review_lifecycle_event'] ) ? sanitize_key( (string) $record['fresh_review_lifecycle_event'] ) : '',
		'lifecycle_reason'                           => isset( $record['fresh_review_lifecycle_reason'] ) ? sanitize_key( (string) $record['fresh_review_lifecycle_reason'] ) : '',
		'decision_recorded'                          => ! empty( $record['decision_recorded'] ),
		'decision_status'                            => isset( $record['fresh_review_decision_status'] ) ? sanitize_key( (string) $record['fresh_review_decision_status'] ) : '',
		'decision_consumed'                          => ! empty( $record['fresh_review_decision_consumed'] ),
		'decision_consumption_claimed'               => ! empty( $record['fresh_review_decision_consumption_claimed'] ),
		'decision_consumption_claim_stale_after_seconds' => $claim_stale_after_seconds,
		'decision_consumption_claim_cleanup_supported' => ! empty( $record['fresh_review_decision_consumption_claimed'] ),
		'decision_consumption_claim_reclaim_eligible_at' => $claim_started_at > 0 ? $claim_started_at + $claim_stale_after_seconds : 0,
		'imported_fresh_review_handoff'              => ! empty( $record['imported_fresh_review_handoff'] ),
		'retry_save_attempted'                       => ! empty( $record['retry_save_attempted'] ),
		'retry_save_applied'                         => ! empty( $record['retry_save_applied'] ),
		'consumes_review_decision'                   => ! empty( $record['consumes_review_decision'] ),
		'stale_consumption_claim_reclaimed'          => ! empty( $record['fresh_review_stale_consumption_claim_reclaimed'] ),
		'previous_server_version'                    => isset( $record['previous_server_version'] ) ? sanitize_text_field( (string) $record['previous_server_version'] ) : '',
		'saved_server_version'                       => isset( $record['saved_server_version'] ) ? sanitize_text_field( (string) $record['saved_server_version'] ) : '',
		'created_revision_count'                     => isset( $record['created_revision_count'] ) ? max( 0, (int) $record['created_revision_count'] ) : 0,
		'reviewed_block_item_count'                  => isset( $record['reviewed_block_item_count'] ) ? max( 0, (int) $record['reviewed_block_item_count'] ) : 0,
		'reviewed_block_decision_counts'             => isset( $record['reviewed_block_decision_counts'] ) && is_array( $record['reviewed_block_decision_counts'] ) ? wp_de_rtc_get_fresh_review_public_decision_counts( $record['reviewed_block_decision_counts'] ) : array(
			'approved' => 0,
			'rejected' => 0,
		),
		'hash_evidence_fields'                       => $hash_evidence_fields,
		'version_evidence_fields'                    => array_values(
			array_intersect(
				array( 'client_base_version', 'server_version', 'client_base_version_at_decision', 'server_version_at_decision', 'previous_server_version', 'saved_server_version' ),
				array_keys( $record )
			)
		),
		'reviewer_identity_retained'                 => $reviewer_identity_retained,
		'reviewer_capability_drift_recheck_supported' => $reviewer_identity_retained,
		'requires_new_review_if_reviewer_authority_cannot_be_rechecked' => ! $reviewer_identity_retained,
		'exposes_raw_content'                        => false,
		'exposes_reviewer_identity'                  => false,
		'exposes_saver_identity'                     => false,
		'exposes_proof_internals'                    => false,
		'exposes_reviewed_block_items'               => false,
	);
}

/**
 * Returns a no-write error when the original fresh-review reviewer drifted.
 *
 * The opaque record may retain reviewer identity privately so WordPress can
 * recheck authority at consumption. Public responses expose only generic drift
 * status and support-safe record evidence.
 *
 * @since 7.1.0
 * @access private
 *
 * @param WP_Post $post       Post object.
 * @param array   $record     Fresh-review request record.
 * @param string  $rest_route REST route label for the rejection.
 * @return WP_Error|null Rejection error, or null when reviewer authority is current.
 */
function wp_de_rtc_get_fresh_review_reviewer_authority_recheck_error( $post, $record, $rest_route ) {
	$post = get_post( $post );

	if ( ! $post || ! is_array( $record ) ) {
		return null;
	}

	$reviewer_user_id = isset( $record['reviewer_user_id'] ) ? absint( $record['reviewer_user_id'] ) : 0;
	$reviewer         = $reviewer_user_id ? get_userdata( $reviewer_user_id ) : false;
	$detail           = '';
	$error_code       = 'de_rtc_sync_meta_tampered';
	$authority_status = '';
	$account_status   = 'active';
	$capability_status = 'current';
	$required_capability = 'unfiltered_html';

	if ( ! $reviewer_user_id || ! $reviewer ) {
		$detail            = 'fresh_review_reviewer_account_deleted';
		$authority_status  = 'reviewer_account_deleted';
		$account_status    = 'deleted';
		$capability_status = 'unavailable';
	} elseif ( ! user_can( $reviewer_user_id, 'unfiltered_html' ) ) {
		$detail            = 'fresh_review_reviewer_unfiltered_html_missing';
		$error_code        = 'de_rtc_review_approval_requires_unfiltered_html';
		$authority_status  = 'reviewer_unfiltered_html_missing';
		$capability_status = 'missing_unfiltered_html';
	} elseif ( ! user_can( $reviewer_user_id, 'edit_post', (int) $post->ID ) ) {
		$detail              = 'fresh_review_reviewer_edit_post_missing';
		$authority_status    = 'reviewer_edit_post_missing';
		$capability_status   = 'missing_edit_post';
		$required_capability = 'edit_post';
	}

	if ( '' === $detail ) {
		return null;
	}

	$public_record_evidence = wp_de_rtc_get_opaque_fresh_review_request_public_evidence( $record );

	return wp_de_rtc_get_reason_error(
		$error_code,
		__( 'Distributed Editing rejected fresh-review consumption because reviewer authority changed.' ),
		array(
			'detail'                                  => $detail,
			'post_id'                                 => (int) $post->ID,
			'rest_route'                              => sanitize_key( (string) $rest_route ),
			'fresh_review_request_record_id'          => isset( $record['public_record_id'] ) ? sanitize_text_field( (string) $record['public_record_id'] ) : '',
			'fresh_review_request_record'             => $public_record_evidence,
			'fresh_review_request_status'             => isset( $record['fresh_review_request_status'] ) ? sanitize_key( (string) $record['fresh_review_request_status'] ) : '',
			'fresh_review_decision_recorded'          => ! empty( $record['decision_recorded'] ),
			'fresh_review_decision_consumed'          => false,
			'fresh_review_decision_lifecycle_status'  => 'capability_drift',
			'fresh_review_decision_lifecycle_action'  => 'request_new_fresh_review',
			'fresh_review_requires_new_review'        => true,
			'fresh_review_support_evidence_available' => true,
			'fresh_review_reviewer_authority_rechecked' => true,
			'fresh_review_reviewer_authority_status'  => $authority_status,
			'fresh_review_reviewer_account_status'    => $account_status,
			'fresh_review_reviewer_capability_status' => $capability_status,
			'fresh_review_reviewer_required_capability' => $required_capability,
			'fresh_review_reviewer_identity_retained' => true,
			'fresh_review_reviewer_identity_exposed'  => false,
			'raw_content_included'                    => false,
			'proof_internals_exposed'                 => false,
			'reviewer_identity_exposed'               => false,
			'saver_identity_exposed'                  => false,
			'requires_unfiltered_html'                => 'unfiltered_html' === $required_capability,
			'unfiltered_html_allowed'                 => current_user_can( 'unfiltered_html' ),
			'requires_edit_post'                      => true,
			'authorship_review_required'              => true,
			'content_capability_review_required'      => true,
			'review_status'                           => 'reviewer_capability_missing',
			'review_action'                           => 'request_new_fresh_review',
			'review_required_capability'              => $required_capability,
			'reviewer_capability'                     => 'unfiltered_html',
			'review_scope'                            => 'collaborative_post_content',
			'can_export_local_updates'                => true,
			'saves_post'                              => false,
			'mutates_post_content'                    => false,
			'creates_revision'                        => false,
			'claims_saved'                            => false,
			'consumes_review_decision'                => false,
			'retry_save_attempted'                    => false,
			'normal_save_attempted'                   => false,
			'applies_recovery'                        => false,
			'changes_locks'                           => false,
			'permission_contract'                     => wp_de_rtc_get_rest_recovery_permission_contract( $post ),
		)
	);
}

/**
 * Returns a no-write error when fresh-review consumption is already claimed.
 *
 * @since 7.1.0
 * @access private
 *
 * @param WP_Post $post       Post object.
 * @param array   $record     Fresh-review request record.
 * @param string  $rest_route REST route label for the rejection.
 * @return WP_Error Consumption conflict error.
 */
function wp_de_rtc_get_fresh_review_decision_consumption_conflict_error( $post, $record, $rest_route ) {
	$post                   = get_post( $post );
	$public_record_evidence = wp_de_rtc_get_opaque_fresh_review_request_public_evidence( $record );
	$is_claimed             = ! empty( $record['fresh_review_decision_consumption_claimed'] ) && empty( $record['fresh_review_decision_consumed'] ) && empty( $record['retry_save_applied'] );
	$claim_cleanup          = $is_claimed ? wp_de_rtc_get_stale_fresh_review_decision_consumption_claim_cleanup_result(
		$record,
		$post,
		array(
			'mode' => 'classify',
		)
	) : array();

	if ( is_wp_error( $claim_cleanup ) ) {
		$claim_cleanup = array();
	}

	$is_stale_claim   = $is_claimed && ! empty( $claim_cleanup['fresh_review_claim_is_stale'] );
	$lifecycle_status = $is_claimed ? 'consumption_in_progress' : 'already_consumed';
	$lifecycle_event  = $is_claimed ? 'consume_claimed' : 'consumed';
	$lifecycle_reason = $is_claimed ? 'guarded_retry_save_in_progress' : 'guarded_retry_save_applied';

	if ( $is_stale_claim ) {
		$lifecycle_status = 'stale_consumption_claim';
		$lifecycle_event  = 'consume_claim_stale';
		$lifecycle_reason = 'interrupted_guarded_retry_save_write';
	}

	return wp_de_rtc_get_reason_error(
		'de_rtc_sync_meta_tampered',
		__( 'Distributed Editing rejected fresh-review consumption because the decision was already claimed or consumed.' ),
		array(
			'detail'                                  => $is_claimed ? 'fresh_review_decision_consumption_already_claimed_for_retry_save' : 'fresh_review_decision_already_consumed_for_retry_save',
			'post_id'                                 => $post ? (int) $post->ID : 0,
			'rest_route'                              => sanitize_key( (string) $rest_route ),
			'fresh_review_request_record_id'          => isset( $record['public_record_id'] ) ? sanitize_text_field( (string) $record['public_record_id'] ) : '',
			'fresh_review_request_record'             => $public_record_evidence,
			'fresh_review_request_status'             => isset( $record['fresh_review_request_status'] ) ? sanitize_key( (string) $record['fresh_review_request_status'] ) : '',
			'fresh_review_decision_record_consumed'   => ! $is_claimed,
			'fresh_review_decision_consumption_claimed' => $is_claimed,
			'fresh_review_decision_consumed'          => false,
			'fresh_review_decision_lifecycle_status'  => $lifecycle_status,
			'fresh_review_decision_lifecycle_event'   => $lifecycle_event,
			'fresh_review_decision_lifecycle_reason'  => $lifecycle_reason,
			'fresh_review_decision_lifecycle_action'  => 'request_new_fresh_review',
			'fresh_review_previous_server_version'    => isset( $record['previous_server_version'] ) ? sanitize_text_field( (string) $record['previous_server_version'] ) : '',
			'fresh_review_saved_server_version'       => isset( $record['saved_server_version'] ) ? sanitize_text_field( (string) $record['saved_server_version'] ) : '',
			'fresh_review_consumption_recorded'       => ! empty( $public_record_evidence['recorded'] ),
			'fresh_review_support_evidence_available' => true,
			'fresh_review_claim_cleanup'              => $claim_cleanup,
			'fresh_review_claim_cleanup_status'       => isset( $claim_cleanup['fresh_review_claim_cleanup_status'] ) ? $claim_cleanup['fresh_review_claim_cleanup_status'] : '',
			'fresh_review_claim_is_stale'             => ! empty( $claim_cleanup['fresh_review_claim_is_stale'] ),
			'fresh_review_claim_can_reclaim'          => ! empty( $claim_cleanup['fresh_review_claim_can_reclaim'] ),
			'raw_content_included'                    => false,
			'consumes_review_decision'                => false,
			'saves_post'                              => false,
			'mutates_post_content'                    => false,
			'creates_revision'                        => false,
			'claims_saved'                            => false,
		)
	);
}

/**
 * Returns retry-save fresh-review decision consumption evidence.
 *
 * This helper is the retry-save write-boundary reader for the no-write
 * fresh-review consume handoff. It validates the client-carried hash/version
 * envelope against the durable request record and the current retry-save
 * candidate. The record is claimed atomically immediately before the guarded
 * retry-save write so concurrent consumers cannot both pass the no-write
 * validation boundary.
 *
 * @since 7.1.0
 * @access private
 *
 * @param WP_Post $post Post object.
 * @param array   $args {
 *     Retry-save fresh-review evidence arguments.
 *
 *     @type array  $accepted_fresh_review_decision Hash-only fresh-review consume evidence.
 *     @type string $client_base_version            Retry-save client base version.
 *     @type string $accepted_proof_server_version  Retry-save accepted proof server version.
 *     @type string $server_version                 Current server sync-meta version.
 *     @type int    $pending_change_count           Pending local change count.
 *     @type string $proposed_post_content_hash     Hash of stripped proposed post content.
 *     @type string $candidate_post_content_hash    Hash of server candidate post content.
 * }
 * @return array|WP_Error Fresh-review consumption evidence, or rejection.
 */
function wp_de_rtc_get_retry_save_fresh_review_decision_consumption_result( $post, $args ) {
	$post    = get_post( $post );
	$post_id = $post ? (int) $post->ID : 0;
	$proof   = isset( $args['accepted_fresh_review_decision'] ) ? $args['accepted_fresh_review_decision'] : null;

	if ( is_object( $proof ) ) {
		$proof = get_object_vars( $proof );
	}

	if ( ! $post || ! is_array( $proof ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the retry save because fresh-review evidence is malformed.' ),
			array(
				'detail'                         => 'malformed_retry_save_fresh_review_decision_evidence',
				'post_id'                        => $post_id,
				'rest_route'                     => 'post_retry_save',
				'fresh_review_decision_consumed' => false,
				'raw_content_included'           => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
			)
		);
	}

	$raw_content_param_paths = wp_de_rtc_find_raw_post_content_param_paths( $proof, 'accepted_fresh_review_decision' );

	if ( ! empty( $proof['raw_content_included'] ) || ! empty( $proof['exposes_raw_content'] ) || ! empty( $raw_content_param_paths ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because fresh-review evidence included raw content.' ),
			array(
				'detail'                         => 'retry_save_fresh_review_raw_content_rejected',
				'post_id'                        => $post_id,
				'rest_route'                     => 'post_retry_save',
				'request_raw_content_included'   => true,
				'raw_content_included'           => false,
				'raw_content_param_paths'        => $raw_content_param_paths,
				'fresh_review_decision_consumed' => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
			)
		);
	}

	$proof_leakage_param_paths = wp_de_rtc_find_private_proof_param_paths( $proof, 'accepted_fresh_review_decision' );

	if ( ! empty( $proof_leakage_param_paths ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because fresh-review evidence included proof internals.' ),
			array(
				'detail'                         => 'retry_save_fresh_review_proof_leakage_rejected',
				'post_id'                        => $post_id,
				'rest_route'                     => 'post_retry_save',
				'proof_leakage_param_paths'      => $proof_leakage_param_paths,
				'raw_content_included'           => false,
				'fresh_review_decision_consumed' => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
			)
		);
	}

	$record_id = isset( $proof['fresh_review_request_record_id'] ) ? sanitize_text_field( (string) $proof['fresh_review_request_record_id'] ) : '';

	if ( '' === $record_id && isset( $proof['fresh_review_request_record'] ) && is_array( $proof['fresh_review_request_record'] ) && isset( $proof['fresh_review_request_record']['record_id'] ) ) {
		$record_id = sanitize_text_field( (string) $proof['fresh_review_request_record']['record_id'] );
	}

	$record = wp_de_rtc_get_opaque_fresh_review_request_record( $record_id );

	if (
		! is_array( $record ) ||
		(int) $record['post_id'] !== $post_id ||
		(string) $record['post_type'] !== (string) $post->post_type
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the retry save because the fresh-review decision record is unavailable.' ),
			array(
				'detail'                         => 'fresh_review_decision_record_unavailable',
				'post_id'                        => $post_id,
				'rest_route'                     => 'post_retry_save',
				'fresh_review_request_record_id' => $record_id,
				'raw_content_included'           => false,
				'fresh_review_decision_consumed' => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
			)
		);
	}

	if ( ! current_user_can( 'unfiltered_html' ) ) {
		$public_record_evidence = wp_de_rtc_get_opaque_fresh_review_request_public_evidence( $record );

		return wp_de_rtc_get_reason_error(
			'de_rtc_review_approval_requires_unfiltered_html',
			__( 'Distributed Editing requires an unfiltered HTML reviewer to consume fresh-review evidence.' ),
			array(
				'detail'                                  => 'retry_save_fresh_review_requires_unfiltered_html_saver',
				'post_id'                                 => $post_id,
				'rest_route'                              => 'post_retry_save',
				'fresh_review_request_record_id'          => $record['public_record_id'],
				'fresh_review_request_record'             => $public_record_evidence,
				'fresh_review_decision_lifecycle_status'  => 'capability_drift',
				'fresh_review_decision_lifecycle_action'  => 'request_new_fresh_review',
				'fresh_review_support_evidence_available' => true,
				'requires_edit_post'                      => true,
				'requires_unfiltered_html'                => true,
				'unfiltered_html_allowed'                 => false,
				'authorship_review_required'              => true,
				'content_capability_review_required'      => true,
				'review_status'                           => 'reviewer_capability_missing',
				'review_action'                           => 'consume_fresh_review_decision',
				'review_required_capability'              => 'unfiltered_html',
				'reviewer_capability'                     => 'unfiltered_html',
				'review_scope'                            => 'collaborative_post_content',
				'fresh_review_decision_consumed'          => false,
				'raw_content_included'                    => false,
				'saves_post'                              => false,
				'mutates_post_content'                    => false,
				'creates_revision'                        => false,
				'claims_saved'                            => false,
				'permission_contract'                     => wp_de_rtc_get_rest_recovery_permission_contract( $post ),
			)
		);
	}

	if (
		! empty( $record['fresh_review_decision_consumed'] ) ||
		! empty( $record['fresh_review_decision_consumption_claimed'] ) ||
		! empty( $record['consumes_review_decision'] ) ||
		! empty( $record['retry_save_applied'] )
	) {
		return wp_de_rtc_get_fresh_review_decision_consumption_conflict_error( $post, $record, 'post_retry_save' );
	}

	if (
		empty( $record['decision_recorded'] ) ||
		! isset( $record['fresh_review_decision'] ) ||
		'approved' !== wp_de_rtc_normalize_fresh_review_decision( $record['fresh_review_decision'] )
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the retry save because the recorded fresh-review decision is not approved.' ),
			array(
				'detail'                         => 'fresh_review_decision_not_approved_for_retry_save',
				'post_id'                        => $post_id,
				'rest_route'                     => 'post_retry_save',
				'fresh_review_request_record_id' => $record['public_record_id'],
				'fresh_review_decision_status'   => isset( $record['fresh_review_decision_status'] ) ? sanitize_key( (string) $record['fresh_review_decision_status'] ) : '',
				'raw_content_included'           => false,
				'fresh_review_decision_consumed' => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
			)
		);
	}

	$reviewer_authority_error = wp_de_rtc_get_fresh_review_reviewer_authority_recheck_error( $post, $record, 'post_retry_save' );

	if ( is_wp_error( $reviewer_authority_error ) ) {
		return $reviewer_authority_error;
	}

	$proof_result     = isset( $proof['result'] ) ? sanitize_key( (string) $proof['result'] ) : '';
	$proof_rest_route = isset( $proof['rest_route'] ) ? sanitize_key( (string) $proof['rest_route'] ) : '';
	$proof_status     = isset( $proof['fresh_review_decision_status'] ) ? sanitize_key( (string) $proof['fresh_review_decision_status'] ) : '';
	$proof_validated  = ! empty( $proof['fresh_review_decision_consumption_validated'] ) && wp_validate_boolean( $proof['fresh_review_decision_consumption_validated'] );
	$proof_eligible   = ! empty( $proof['fresh_review_decision_eligible_for_retry_save'] ) && wp_validate_boolean( $proof['fresh_review_decision_eligible_for_retry_save'] );

	if (
		'fresh_review_decision_eligible_for_retry_save_handoff' !== $proof_result ||
		'post_fresh_review_consume' !== $proof_rest_route ||
		'approved' !== $proof_status ||
		! $proof_validated ||
		! $proof_eligible
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because fresh-review consumption evidence was not accepted.' ),
			array(
				'detail'                         => 'retry_save_fresh_review_consumption_evidence_rejected',
				'post_id'                        => $post_id,
				'rest_route'                     => 'post_retry_save',
				'fresh_review_request_record_id' => $record['public_record_id'],
				'fresh_review_decision_consumed' => false,
				'raw_content_included'           => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
			)
		);
	}

	$client_base_version            = isset( $args['client_base_version'] ) ? sanitize_text_field( (string) $args['client_base_version'] ) : '';
	$accepted_proof_server_version = isset( $args['accepted_proof_server_version'] ) ? sanitize_text_field( (string) $args['accepted_proof_server_version'] ) : '';
	$server_version                 = isset( $args['server_version'] ) ? sanitize_text_field( (string) $args['server_version'] ) : '';
	$proof_client_base_version      = isset( $proof['client_base_version'] ) ? sanitize_text_field( (string) $proof['client_base_version'] ) : '';
	$proof_server_version           = isset( $proof['server_version'] ) ? sanitize_text_field( (string) $proof['server_version'] ) : '';
	$record_client_base_version     = isset( $record['client_base_version_at_decision'] ) ? sanitize_text_field( (string) $record['client_base_version_at_decision'] ) : '';
	$record_server_version          = isset( $record['server_version_at_decision'] ) ? sanitize_text_field( (string) $record['server_version_at_decision'] ) : '';
	$pending_change_count           = array_key_exists( 'pending_change_count', $args ) ? max( 0, (int) $args['pending_change_count'] ) : 1;
	$is_imported_fresh_review_request = ! empty( $record['is_imported_fresh_review_request'] ) || ! empty( $record['imported_fresh_review_handoff'] );
	$proof_client_matches_record    = $proof_client_base_version === $record_client_base_version;
	$proof_client_matches_current   = $proof_client_base_version === $server_version && $client_base_version === $server_version;

	if (
		'' === $proof_client_base_version ||
		'' === $proof_server_version ||
		$proof_client_base_version !== $client_base_version ||
		$proof_server_version !== $accepted_proof_server_version ||
		( ! $proof_client_matches_record && ! ( $is_imported_fresh_review_request && $proof_client_matches_current ) ) ||
		$proof_server_version !== $record_server_version ||
		$proof_server_version !== $server_version
	) {
		$error = wp_de_rtc_get_stale_base_rejection_error(
			$post,
			array(
				'client_base_version'      => $client_base_version,
				'server_version'           => $server_version,
				'pending_change_count'     => $pending_change_count,
				'remote_change_count'      => 1,
				'can_attempt_local_rebase' => false,
				'rest_route'               => 'post_retry_save_fresh_review_consumption_stale_base',
				'saves_post'               => false,
				'mutates_post_content'     => false,
				'creates_revision'         => false,
				'claims_saved'             => false,
			)
		);
		$data  = $error->get_error_data( 'stale_base_version_rejected' );

		if ( is_array( $data ) ) {
			$data['fresh_review_decision_consumed']       = false;
			$data['fresh_review_decision_stale']          = true;
			$data['fresh_review_requires_new_review']     = true;
			$data['fresh_review_request_record_id']       = $record['public_record_id'];
			$data['fresh_review_client_base_version']     = $proof_client_base_version;
			$data['fresh_review_server_version']          = $proof_server_version;
			$data['fresh_review_record_server_version']   = $record_server_version;
			$data['fresh_review_current_server_version']  = $server_version;
			$error->add_data( $data, 'stale_base_version_rejected' );
		}

		return $error;
	}

	$proposed_post_content_hash       = isset( $args['proposed_post_content_hash'] ) ? sanitize_text_field( (string) $args['proposed_post_content_hash'] ) : '';
	$candidate_post_content_hash     = isset( $args['candidate_post_content_hash'] ) ? sanitize_text_field( (string) $args['candidate_post_content_hash'] ) : '';
	$proof_proposed_hash             = wp_de_rtc_get_request_hash_evidence( $proof, 'proposed_post_content_hash' );
	$proof_reviewed_proposed_hash    = wp_de_rtc_get_request_hash_evidence( $proof, 'reviewed_proposed_content_hash' );
	$proof_candidate_hash            = wp_de_rtc_get_request_hash_evidence( $proof, 'candidate_post_content_hash' );
	$proof_reviewed_candidate_hash   = wp_de_rtc_get_request_hash_evidence( $proof, 'reviewed_candidate_content_hash' );
	$record_proposed_hash            = isset( $record['proposed_post_content_hash'] ) ? sanitize_text_field( (string) $record['proposed_post_content_hash'] ) : '';
	$record_reviewed_proposed_hash   = isset( $record['reviewed_proposed_content_hash'] ) ? sanitize_text_field( (string) $record['reviewed_proposed_content_hash'] ) : '';
	$record_candidate_hash           = isset( $record['candidate_post_content_hash'] ) ? sanitize_text_field( (string) $record['candidate_post_content_hash'] ) : '';
	$record_reviewed_candidate_hash  = isset( $record['reviewed_candidate_content_hash'] ) ? sanitize_text_field( (string) $record['reviewed_candidate_content_hash'] ) : '';
	$missing_hash_fields             = array();
	$requires_candidate_hash_evidence = '' !== $record_candidate_hash || '' !== $record_reviewed_candidate_hash || null !== $proof_candidate_hash || null !== $proof_reviewed_candidate_hash;

	foreach (
		array(
			'accepted_fresh_review_decision.proposed_post_content_hash'          => $proof_proposed_hash,
			'accepted_fresh_review_decision.reviewed_proposed_content_hash'     => $proof_reviewed_proposed_hash,
			'fresh_review_record.proposed_post_content_hash'                    => $record_proposed_hash,
			'fresh_review_record.reviewed_proposed_content_hash'                => $record_reviewed_proposed_hash,
		) as $field => $hash
	) {
		if ( ! wp_de_rtc_is_sha256_hash( $hash ) ) {
			$missing_hash_fields[] = $field;
		}
	}

	if ( $requires_candidate_hash_evidence ) {
		foreach (
			array(
				'accepted_fresh_review_decision.candidate_post_content_hash'          => $proof_candidate_hash,
				'accepted_fresh_review_decision.reviewed_candidate_content_hash'     => $proof_reviewed_candidate_hash,
				'fresh_review_record.candidate_post_content_hash'                    => $record_candidate_hash,
				'fresh_review_record.reviewed_candidate_content_hash'                => $record_reviewed_candidate_hash,
			) as $field => $hash
		) {
			if ( ! wp_de_rtc_is_sha256_hash( $hash ) ) {
				$missing_hash_fields[] = $field;
			}
		}
	}

	if ( ! empty( $missing_hash_fields ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the retry save because fresh-review hash evidence is incomplete.' ),
			array(
				'detail'                         => 'missing_retry_save_fresh_review_hash_evidence',
				'post_id'                        => $post_id,
				'rest_route'                     => 'post_retry_save',
				'fresh_review_request_record_id' => $record['public_record_id'],
				'missing_hash_evidence_fields'   => $missing_hash_fields,
				'fresh_review_decision_consumed' => false,
				'raw_content_included'           => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
			)
		);
	}

	$mismatched_hash_fields = array();

	if ( ! hash_equals( $proposed_post_content_hash, $proof_proposed_hash ) || ! hash_equals( $record_proposed_hash, $proof_proposed_hash ) ) {
		$mismatched_hash_fields[] = 'accepted_fresh_review_decision.proposed_post_content_hash';
	}

	if ( ! hash_equals( $proposed_post_content_hash, $proof_reviewed_proposed_hash ) || ! hash_equals( $record_reviewed_proposed_hash, $proof_reviewed_proposed_hash ) ) {
		$mismatched_hash_fields[] = 'accepted_fresh_review_decision.reviewed_proposed_content_hash';
	}

	if ( $requires_candidate_hash_evidence ) {
		if ( ! hash_equals( $candidate_post_content_hash, $proof_candidate_hash ) || ! hash_equals( $record_candidate_hash, $proof_candidate_hash ) ) {
			$mismatched_hash_fields[] = 'accepted_fresh_review_decision.candidate_post_content_hash';
		}

		if ( ! hash_equals( $candidate_post_content_hash, $proof_reviewed_candidate_hash ) || ! hash_equals( $record_reviewed_candidate_hash, $proof_reviewed_candidate_hash ) ) {
			$mismatched_hash_fields[] = 'accepted_fresh_review_decision.reviewed_candidate_content_hash';
		}
	}

	if ( ! empty( $mismatched_hash_fields ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because fresh-review hash evidence does not match.' ),
			array(
				'detail'                          => 'retry_save_fresh_review_hash_evidence_mismatch',
				'post_id'                         => $post_id,
				'rest_route'                      => 'post_retry_save',
				'fresh_review_request_record_id'  => $record['public_record_id'],
				'mismatched_hash_evidence_fields' => $mismatched_hash_fields,
				'fresh_review_decision_consumed'  => false,
				'raw_content_included'            => false,
				'saves_post'                      => false,
				'mutates_post_content'            => false,
				'creates_revision'                => false,
				'claims_saved'                    => false,
			)
		);
	}

	return array(
		'fresh_review_decision_ready_for_retry_save' => true,
		'fresh_review_request_record_id'             => $record['public_record_id'],
		'fresh_review_decision_status'               => 'approved',
		'fresh_review_request_status'                => 'decision_recorded',
		'fresh_review_reviewed_block_item_count'     => isset( $record['reviewed_block_item_count'] ) ? max( 0, (int) $record['reviewed_block_item_count'] ) : 0,
		'fresh_review_reviewed_block_decision_counts' => isset( $record['reviewed_block_decision_counts'] ) && is_array( $record['reviewed_block_decision_counts'] ) ? $record['reviewed_block_decision_counts'] : array(
			'approved' => 0,
			'rejected' => 0,
		),
		'_fresh_review_request_record'               => $record,
	);
}

/**
 * Atomically updates a stored opaque fresh-review request record.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $option_name     Option name.
 * @param array  $expected_record Expected currently stored record.
 * @param array  $updated_record  Replacement record.
 * @return bool Whether the compare-and-swap update succeeded.
 */
function wp_de_rtc_atomic_update_opaque_fresh_review_request_record( $option_name, $expected_record, $updated_record ) {
	global $wpdb;

	if ( '' === $option_name || ! is_array( $expected_record ) || ! is_array( $updated_record ) ) {
		return false;
	}

	$updated = $wpdb->query(
		$wpdb->prepare(
			"UPDATE $wpdb->options
			SET option_value = %s
			WHERE option_name = %s
			AND BINARY option_value = BINARY %s",
			maybe_serialize( $updated_record ),
			$option_name,
			maybe_serialize( $expected_record )
		)
	);

	wp_cache_delete( $option_name, 'options' );

	return 1 === (int) $updated;
}

/**
 * Returns the stale window for retry-save fresh-review consumption claims.
 *
 * @since 7.1.0
 * @access private
 *
 * @return int Stale-claim age in seconds.
 */
function wp_de_rtc_get_fresh_review_decision_consumption_claim_stale_after_seconds() {
	return 15 * MINUTE_IN_SECONDS;
}

/**
 * Injects a support-safe stale fresh-review consumption claim.
 *
 * This is a deterministic browser-harness support boundary. It only updates
 * the opaque fresh-review support record to model an interrupted guarded
 * retry-save claim. It does not save posts, create revisions, change locks,
 * expose raw content, expose reviewer identity, or affect normal save paths.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array   $record Fresh-review request record.
 * @param WP_Post $post   Post object.
 * @param array   $args   Claim injection arguments.
 * @return array|WP_Error Support-safe injection result, or rejection.
 */
function wp_de_rtc_inject_stale_fresh_review_decision_consumption_claim( $record, $post, $args = array() ) {
	$post        = get_post( $post );
	$args        = is_array( $args ) ? $args : array();
	$record_id   = is_array( $record ) && isset( $record['public_record_id'] ) ? sanitize_text_field( (string) $record['public_record_id'] ) : '';
	$option_name = wp_de_rtc_get_opaque_fresh_review_request_record_option_name( $record_id );

	if (
		! $post ||
		! is_array( $record ) ||
		'' === $record_id ||
		'' === $option_name ||
		! isset( $record['post_id'], $record['post_type'] ) ||
		(int) $record['post_id'] !== (int) $post->ID ||
		(string) $record['post_type'] !== (string) $post->post_type
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing could not inject the fresh-review lifecycle claim.' ),
			array(
				'detail'                         => 'fresh_review_claim_injection_record_unavailable',
				'post_id'                        => $post ? (int) $post->ID : 0,
				'rest_route'                     => 'post_fresh_review_lifecycle',
				'fresh_review_request_record_id' => $record_id,
				'fresh_review_lifecycle_action'  => 'inject_stale_consumption_claim',
				'raw_content_included'           => false,
				'proof_internals_exposed'        => false,
				'reviewer_identity_exposed'      => false,
				'saver_identity_exposed'         => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
				'changes_locks'                  => false,
				'affects_normal_save_paths'      => false,
			)
		);
	}

	if (
		empty( $record['decision_recorded'] ) ||
		'approved' !== ( isset( $record['fresh_review_decision_status'] ) ? sanitize_key( (string) $record['fresh_review_decision_status'] ) : '' ) ||
		! empty( $record['fresh_review_decision_consumption_claimed'] ) ||
		! empty( $record['fresh_review_decision_consumed'] ) ||
		! empty( $record['consumes_review_decision'] ) ||
		! empty( $record['retry_save_applied'] )
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing could not inject the fresh-review lifecycle claim because the decision is not claimable.' ),
			array(
				'detail'                         => 'fresh_review_claim_injection_decision_not_claimable',
				'post_id'                        => (int) $post->ID,
				'rest_route'                     => 'post_fresh_review_lifecycle',
				'fresh_review_request_record_id' => $record_id,
				'fresh_review_lifecycle_action'  => 'inject_stale_consumption_claim',
				'fresh_review_request_record'    => wp_de_rtc_get_opaque_fresh_review_request_public_evidence( $record ),
				'raw_content_included'           => false,
				'proof_internals_exposed'        => false,
				'reviewer_identity_exposed'      => false,
				'saver_identity_exposed'         => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
				'changes_locks'                  => false,
				'affects_normal_save_paths'      => false,
			)
		);
	}

	$proposed_hash = isset( $args['proposed_post_content_hash'] ) ? sanitize_text_field( (string) $args['proposed_post_content_hash'] ) : '';

	if ( '' === $proposed_hash && isset( $record['proposed_post_content_hash'] ) ) {
		$proposed_hash = sanitize_text_field( (string) $record['proposed_post_content_hash'] );
	}

	if ( ! wp_de_rtc_is_sha256_hash( $proposed_hash ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing could not inject the fresh-review lifecycle claim because hash evidence is incomplete.' ),
			array(
				'detail'                         => 'missing_fresh_review_claim_injection_hash_evidence',
				'post_id'                        => (int) $post->ID,
				'rest_route'                     => 'post_fresh_review_lifecycle',
				'fresh_review_request_record_id' => $record_id,
				'missing_hash_evidence_fields'   => array( 'proposed_post_content_hash' ),
				'fresh_review_lifecycle_action'  => 'inject_stale_consumption_claim',
				'raw_content_included'           => false,
				'proof_internals_exposed'        => false,
				'reviewer_identity_exposed'      => false,
				'saver_identity_exposed'         => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
				'changes_locks'                  => false,
				'affects_normal_save_paths'      => false,
			)
		);
	}

	$previous_server_version = isset( $args['previous_server_version'] ) && null !== $args['previous_server_version']
		? sanitize_text_field( (string) $args['previous_server_version'] )
		: '';

	if ( '' === $previous_server_version ) {
		if ( isset( $record['server_version_at_decision'] ) && '' !== (string) $record['server_version_at_decision'] ) {
			$previous_server_version = sanitize_text_field( (string) $record['server_version_at_decision'] );
		} elseif ( isset( $record['server_version'] ) ) {
			$previous_server_version = sanitize_text_field( (string) $record['server_version'] );
		}
	}

	$candidate_hash = isset( $args['candidate_post_content_hash'] ) ? sanitize_text_field( (string) $args['candidate_post_content_hash'] ) : '';

	if ( '' !== $candidate_hash && ! wp_de_rtc_is_sha256_hash( $candidate_hash ) ) {
		$candidate_hash = '';
	}

	$claim = wp_de_rtc_claim_opaque_fresh_review_decision_retry_save_consumption(
		$record,
		$post,
		array(
			'previous_server_version'     => $previous_server_version,
			'proposed_post_content_hash'  => $proposed_hash,
			'candidate_post_content_hash' => $candidate_hash,
		)
	);

	if ( is_wp_error( $claim ) ) {
		return $claim;
	}

	$claimed_record = isset( $claim['_fresh_review_request_record'] ) && is_array( $claim['_fresh_review_request_record'] )
		? $claim['_fresh_review_request_record']
		: wp_de_rtc_get_opaque_fresh_review_request_record( $record_id );
	$stale_after    = wp_de_rtc_get_fresh_review_decision_consumption_claim_stale_after_seconds();
	$claim_age      = isset( $args['claim_age_seconds'] ) && is_numeric( $args['claim_age_seconds'] )
		? max( $stale_after + 1, (int) $args['claim_age_seconds'] )
		: $stale_after + 1;
	$now            = time();
	$claimed_at     = $now - $claim_age;
	$stale_record   = $claimed_record;

	$stale_record['fresh_review_decision_consumption_claimed_at'] = $claimed_at;
	$stale_record['updated_at']                                  = $claimed_at;
	$stale_record['fresh_review_lifecycle_reason']               = 'interrupted_guarded_retry_save_write';

	if ( ! wp_de_rtc_atomic_update_opaque_fresh_review_request_record( $option_name, $claimed_record, $stale_record ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_storage_failure',
			__( 'Distributed Editing could not inject the fresh-review lifecycle claim.' ),
			array(
				'detail'                         => 'fresh_review_claim_injection_update_failed',
				'post_id'                        => (int) $post->ID,
				'rest_route'                     => 'post_fresh_review_lifecycle',
				'fresh_review_request_record_id' => $record_id,
				'fresh_review_lifecycle_action'  => 'inject_stale_consumption_claim',
				'raw_content_included'           => false,
				'proof_internals_exposed'        => false,
				'reviewer_identity_exposed'      => false,
				'saver_identity_exposed'         => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
				'changes_locks'                  => false,
				'affects_normal_save_paths'      => false,
			)
		);
	}

	$cleanup = wp_de_rtc_get_stale_fresh_review_decision_consumption_claim_cleanup_result(
		$stale_record,
		$post,
		array(
			'mode' => 'classify',
			'now'  => $now,
		)
	);

	return array(
		'fresh_review_lifecycle_action'         => 'inject_stale_consumption_claim',
		'fresh_review_lifecycle_action_applied' => true,
		'fresh_review_request_record_id'        => $record_id,
		'fresh_review_request_record'           => wp_de_rtc_get_opaque_fresh_review_request_public_evidence( $stale_record ),
		'fresh_review_claim_cleanup'            => is_wp_error( $cleanup ) ? array() : $cleanup,
		'fresh_review_claim_cleanup_status'     => is_wp_error( $cleanup ) ? '' : $cleanup['fresh_review_claim_cleanup_status'],
		'fresh_review_claim_is_stale'           => is_wp_error( $cleanup ) ? false : ! empty( $cleanup['fresh_review_claim_is_stale'] ),
		'fresh_review_claim_can_reclaim'        => is_wp_error( $cleanup ) ? false : ! empty( $cleanup['fresh_review_claim_can_reclaim'] ),
		'fresh_review_claim_reclaimed'          => false,
		'raw_content_included'                  => false,
		'proof_internals_exposed'               => false,
		'reviewer_identity_exposed'             => false,
		'saver_identity_exposed'                => false,
		'saves_post'                            => false,
		'mutates_post_content'                  => false,
		'creates_revision'                      => false,
		'claims_saved'                          => false,
		'changes_locks'                         => false,
		'affects_normal_save_paths'             => false,
	);
}

/**
 * Classifies or reclaims a stale retry-save fresh-review consumption claim.
 *
 * This cleanup boundary only touches the opaque fresh-review support record.
 * It does not expose reviewer identity, raw content, proof internals, claim
 * IDs, or token material, and it does not save posts, create revisions, change
 * locks, settings, or normal save behavior.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array   $record Fresh-review request record.
 * @param WP_Post $post   Post object.
 * @param array   $args   Optional cleanup arguments.
 * @return array|WP_Error Support-safe claim cleanup result, or rejection.
 */
function wp_de_rtc_get_stale_fresh_review_decision_consumption_claim_cleanup_result( $record, $post, $args = array() ) {
	$post        = get_post( $post );
	$args        = is_array( $args ) ? $args : array();
	$mode        = isset( $args['mode'] ) ? sanitize_key( (string) $args['mode'] ) : 'classify';
	$mode        = 'reclaim' === $mode ? 'reclaim' : 'classify';
	$now         = isset( $args['now'] ) && is_numeric( $args['now'] ) ? (int) $args['now'] : time();
	$stale_after = isset( $args['stale_after_seconds'] ) && is_numeric( $args['stale_after_seconds'] )
		? max( 1, (int) $args['stale_after_seconds'] )
		: wp_de_rtc_get_fresh_review_decision_consumption_claim_stale_after_seconds();
	$record_id   = is_array( $record ) && isset( $record['public_record_id'] ) ? sanitize_text_field( (string) $record['public_record_id'] ) : '';
	$option_name = wp_de_rtc_get_opaque_fresh_review_request_record_option_name( $record_id );

	if (
		! $post ||
		! is_array( $record ) ||
		'' === $record_id ||
		'' === $option_name ||
		! isset( $record['post_id'], $record['post_type'] ) ||
		(int) $record['post_id'] !== (int) $post->ID ||
		(string) $record['post_type'] !== (string) $post->post_type
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing could not classify the fresh-review claim cleanup record.' ),
			array(
				'detail'                         => 'fresh_review_claim_cleanup_record_unavailable',
				'post_id'                        => $post ? (int) $post->ID : 0,
				'rest_route'                     => 'post_fresh_review_claim_cleanup',
				'fresh_review_request_record_id' => $record_id,
				'fresh_review_claim_cleanup_available' => false,
				'raw_content_included'           => false,
				'proof_internals_exposed'        => false,
				'reviewer_identity_exposed'      => false,
				'saver_identity_exposed'         => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
				'changes_locks'                  => false,
				'affects_normal_save_paths'      => false,
			)
		);
	}

	$claimed     = ! empty( $record['fresh_review_decision_consumption_claimed'] ) && empty( $record['fresh_review_decision_consumed'] ) && empty( $record['retry_save_applied'] ) && empty( $record['consumes_review_decision'] );
	$consumed    = ! empty( $record['fresh_review_decision_consumed'] ) || ! empty( $record['retry_save_applied'] ) || ! empty( $record['consumes_review_decision'] );
	$claimed_at  = isset( $record['fresh_review_decision_consumption_claimed_at'] ) && is_numeric( $record['fresh_review_decision_consumption_claimed_at'] )
		? (int) $record['fresh_review_decision_consumption_claimed_at']
		: 0;
	$claim_age   = $claimed && $claimed_at > 0 ? max( 0, $now - $claimed_at ) : 0;
	$eligible_at = $claimed && $claimed_at > 0 ? $claimed_at + $stale_after : 0;
	$is_stale    = $claimed && $eligible_at > 0 && $eligible_at <= $now;
	$can_reclaim = $is_stale && ! $consumed;
	$status      = 'not_claimed';
	$reason      = 'no_retry_save_claim_present';

	if ( $consumed ) {
		$status = 'already_consumed';
		$reason = 'guarded_retry_save_already_applied';
	} elseif ( $claimed && 0 === $claimed_at ) {
		$status = 'claim_timestamp_unavailable';
		$reason = 'claim_timestamp_missing';
	} elseif ( $claimed && $is_stale ) {
		$status = 'stale_claim_reclaim_available';
		$reason = 'interrupted_guarded_retry_save_write';
	} elseif ( $claimed ) {
		$status = 'active_claim';
		$reason = 'guarded_retry_save_may_still_be_in_progress';
	}

	$result = array(
		'fresh_review_claim_cleanup_available' => true,
		'fresh_review_claim_cleanup_mode'      => $mode,
		'fresh_review_claim_cleanup_status'    => $status,
		'fresh_review_claim_cleanup_reason'    => $reason,
		'fresh_review_request_record_id'       => $record_id,
		'fresh_review_request_record'          => wp_de_rtc_get_opaque_fresh_review_request_public_evidence( $record ),
		'fresh_review_decision_consumption_claimed' => $claimed,
		'fresh_review_decision_consumed'       => $consumed,
		'fresh_review_claim_started_at'        => $claimed_at,
		'fresh_review_claim_age_seconds'       => $claim_age,
		'fresh_review_claim_stale_after_seconds' => $stale_after,
		'fresh_review_claim_reclaim_eligible_at' => $eligible_at,
		'fresh_review_claim_is_stale'          => $is_stale,
		'fresh_review_claim_can_reclaim'       => $can_reclaim,
		'fresh_review_claim_reclaimed'         => false,
		'fresh_review_support_evidence_available' => true,
		'raw_content_included'                 => false,
		'proof_internals_exposed'              => false,
		'reviewer_identity_exposed'            => false,
		'saver_identity_exposed'               => false,
		'saves_post'                           => false,
		'mutates_post_content'                 => false,
		'creates_revision'                     => false,
		'claims_saved'                         => false,
		'changes_locks'                        => false,
		'affects_normal_save_paths'            => false,
	);

	if ( 'reclaim' !== $mode || ! $can_reclaim ) {
		return $result;
	}

	wp_cache_delete( $option_name, 'options' );

	$stored_record = wp_de_rtc_get_opaque_fresh_review_request_record( $record_id );
	$claim_id      = isset( $record['fresh_review_decision_consumption_claim_id'] ) ? sanitize_text_field( (string) $record['fresh_review_decision_consumption_claim_id'] ) : '';

	if (
		! is_array( $stored_record ) ||
		'' === $claim_id ||
		empty( $stored_record['fresh_review_decision_consumption_claimed'] ) ||
		! isset( $stored_record['fresh_review_decision_consumption_claim_id'] ) ||
		! hash_equals( $claim_id, (string) $stored_record['fresh_review_decision_consumption_claim_id'] ) ||
		! empty( $stored_record['fresh_review_decision_consumed'] ) ||
		! empty( $stored_record['retry_save_applied'] ) ||
		! empty( $stored_record['consumes_review_decision'] )
	) {
		$result['fresh_review_claim_cleanup_status'] = 'stale_claim_reclaim_changed';
		$result['fresh_review_claim_cleanup_reason'] = 'fresh_review_claim_record_changed_before_reclaim';
		$result['fresh_review_claim_can_reclaim']    = false;

		return $result;
	}

	$stored_claimed_at = isset( $stored_record['fresh_review_decision_consumption_claimed_at'] ) && is_numeric( $stored_record['fresh_review_decision_consumption_claimed_at'] )
		? (int) $stored_record['fresh_review_decision_consumption_claimed_at']
		: 0;
	$stored_eligible_at = $stored_claimed_at > 0 ? $stored_claimed_at + $stale_after : 0;

	if ( 0 === $stored_claimed_at || $stored_eligible_at > $now ) {
		$result['fresh_review_claim_cleanup_status'] = 0 === $stored_claimed_at ? 'claim_timestamp_unavailable' : 'active_claim';
		$result['fresh_review_claim_cleanup_reason'] = 0 === $stored_claimed_at ? 'claim_timestamp_missing' : 'guarded_retry_save_may_still_be_in_progress';
		$result['fresh_review_claim_can_reclaim']    = false;
		$result['fresh_review_claim_is_stale']       = false;

		return $result;
	}

	$reclaimed = $stored_record;

	$reclaimed['status']                                      = 'decision_recorded';
	$reclaimed['fresh_review_request_status']                 = 'decision_recorded';
	$reclaimed['updated_at']                                  = $now;
	$reclaimed['retry_save_attempted']                        = false;
	$reclaimed['fresh_review_lifecycle_status']               = 'retry_save_claim_reclaimed';
	$reclaimed['fresh_review_lifecycle_event']                = 'consume_claim_reclaimed';
	$reclaimed['fresh_review_lifecycle_reason']               = 'interrupted_guarded_retry_save_write_cleanup';
	$reclaimed['fresh_review_stale_consumption_claim_reclaimed'] = true;
	$reclaimed['fresh_review_stale_consumption_claim_reclaimed_at'] = $now;
	$reclaimed['fresh_review_stale_consumption_claim_age_seconds'] = max( 0, $now - $stored_claimed_at );
	$reclaimed['normal_save_attempted']                       = false;
	$reclaimed['applies_recovery']                            = false;
	$reclaimed['changes_locks']                               = false;
	unset(
		$reclaimed['fresh_review_decision_consumption_claimed'],
		$reclaimed['fresh_review_decision_consumption_claimed_at'],
		$reclaimed['fresh_review_decision_consumption_claim_id'],
		$reclaimed['previous_server_version'],
		$reclaimed['retry_save_proposed_post_content_hash'],
		$reclaimed['retry_save_candidate_post_content_hash']
	);

	if ( ! wp_de_rtc_atomic_update_opaque_fresh_review_request_record( $option_name, $stored_record, $reclaimed ) ) {
		$result['fresh_review_claim_cleanup_status'] = 'stale_claim_reclaim_failed';
		$result['fresh_review_claim_cleanup_reason'] = 'fresh_review_claim_record_update_failed';
		$result['fresh_review_claim_can_reclaim']    = false;

		return $result;
	}

	$result['fresh_review_claim_cleanup_status']       = 'stale_claim_reclaimed';
	$result['fresh_review_claim_cleanup_reason']       = 'interrupted_guarded_retry_save_write_cleanup';
	$result['fresh_review_decision_consumption_claimed'] = false;
	$result['fresh_review_claim_can_reclaim']          = false;
	$result['fresh_review_claim_reclaimed']            = true;
	$result['fresh_review_request_record']             = wp_de_rtc_get_opaque_fresh_review_request_public_evidence( $reclaimed );

	return $result;
}

/**
 * Claims an approved fresh-review decision before retry-save writes.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array   $record Fresh-review request record validated for retry-save.
 * @param WP_Post $post   Post object.
 * @param array   $args   Retry-save claim evidence.
 * @return array|WP_Error Claim result, or no-write rejection.
 */
function wp_de_rtc_claim_opaque_fresh_review_decision_retry_save_consumption( $record, $post, $args ) {
	$post        = get_post( $post );
	$option_name = isset( $record['public_record_id'] ) ? wp_de_rtc_get_opaque_fresh_review_request_record_option_name( $record['public_record_id'] ) : '';

	if ( ! $post || '' === $option_name || ! is_array( $record ) || ! is_array( $args ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_storage_failure',
			__( 'Distributed Editing could not claim the fresh review decision for retry save.' ),
			array(
				'detail'                         => 'fresh_review_decision_consumption_claim_failed',
				'post_id'                        => $post ? (int) $post->ID : 0,
				'rest_route'                     => 'post_retry_save',
				'fresh_review_request_record_id' => isset( $record['public_record_id'] ) ? sanitize_text_field( (string) $record['public_record_id'] ) : '',
				'fresh_review_decision_consumed' => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
			)
		);
	}

	wp_cache_delete( $option_name, 'options' );

	$stored_record = wp_de_rtc_get_opaque_fresh_review_request_record( $record['public_record_id'] );

	if (
		! is_array( $stored_record ) ||
		(int) $stored_record['post_id'] !== (int) $post->ID ||
		(string) $stored_record['post_type'] !== (string) $post->post_type
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the retry save because the fresh-review decision record is unavailable.' ),
			array(
				'detail'                         => 'fresh_review_decision_record_unavailable',
				'post_id'                        => (int) $post->ID,
				'rest_route'                     => 'post_retry_save',
				'fresh_review_request_record_id' => $record['public_record_id'],
				'raw_content_included'           => false,
				'fresh_review_decision_consumed' => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
			)
		);
	}

	if (
		! empty( $stored_record['fresh_review_decision_consumed'] ) ||
		! empty( $stored_record['fresh_review_decision_consumption_claimed'] ) ||
		! empty( $stored_record['consumes_review_decision'] ) ||
		! empty( $stored_record['retry_save_applied'] )
	) {
		return wp_de_rtc_get_fresh_review_decision_consumption_conflict_error( $post, $stored_record, 'post_retry_save' );
	}

	if ( $stored_record !== $record ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because the fresh-review decision changed before consumption.' ),
			array(
				'detail'                         => 'fresh_review_decision_consumption_record_changed',
				'post_id'                        => (int) $post->ID,
				'rest_route'                     => 'post_retry_save',
				'fresh_review_request_record_id' => $stored_record['public_record_id'],
				'fresh_review_decision_consumed' => false,
				'fresh_review_decision_consumption_claimed' => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
			)
		);
	}

	$now      = time();
	$claim_id = wp_generate_uuid4();
	$claimed  = $stored_record;

	$claimed['status']                                      = 'retry_save_consuming';
	$claimed['fresh_review_request_status']                 = 'retry_save_consuming';
	$claimed['fresh_review_decision_consumption_claimed']   = true;
	$claimed['fresh_review_decision_consumption_claimed_at'] = $now;
	$claimed['fresh_review_decision_consumption_claim_id']  = $claim_id;
	$claimed['updated_at']                                  = $now;
	$claimed['fresh_review_lifecycle_status']               = 'retry_save_consuming';
	$claimed['fresh_review_lifecycle_event']                = 'consume_claimed';
	$claimed['fresh_review_lifecycle_reason']               = 'guarded_retry_save_in_progress';
	$claimed['previous_server_version']                     = isset( $args['previous_server_version'] ) ? sanitize_text_field( (string) $args['previous_server_version'] ) : '';
	$claimed['retry_save_proposed_post_content_hash']       = isset( $args['proposed_post_content_hash'] ) ? sanitize_text_field( (string) $args['proposed_post_content_hash'] ) : '';
	$claimed['retry_save_candidate_post_content_hash']      = isset( $args['candidate_post_content_hash'] ) ? sanitize_text_field( (string) $args['candidate_post_content_hash'] ) : '';
	$claimed['retry_save_attempted']                        = true;
	$claimed['normal_save_attempted']                       = false;
	$claimed['applies_recovery']                            = false;
	$claimed['changes_locks']                               = false;

	if ( ! wp_de_rtc_atomic_update_opaque_fresh_review_request_record( $option_name, $stored_record, $claimed ) ) {
		wp_cache_delete( $option_name, 'options' );

		$latest_record = wp_de_rtc_get_opaque_fresh_review_request_record( $record['public_record_id'] );

		if (
			is_array( $latest_record ) &&
			(
				! empty( $latest_record['fresh_review_decision_consumed'] ) ||
				! empty( $latest_record['fresh_review_decision_consumption_claimed'] ) ||
				! empty( $latest_record['consumes_review_decision'] ) ||
				! empty( $latest_record['retry_save_applied'] )
			)
		) {
			return wp_de_rtc_get_fresh_review_decision_consumption_conflict_error( $post, $latest_record, 'post_retry_save' );
		}

		return wp_de_rtc_get_reason_error(
			'de_rtc_storage_failure',
			__( 'Distributed Editing could not claim the fresh review decision for retry save.' ),
			array(
				'detail'                         => 'fresh_review_decision_consumption_claim_failed',
				'post_id'                        => (int) $post->ID,
				'rest_route'                     => 'post_retry_save',
				'fresh_review_request_record_id' => $record['public_record_id'],
				'fresh_review_decision_consumed' => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
			)
		);
	}

	return array(
		'fresh_review_decision_consumption_claimed' => true,
		'fresh_review_decision_consumption_claim_id' => $claim_id,
		'fresh_review_request_record_id'            => $claimed['public_record_id'],
		'fresh_review_request_record'               => wp_de_rtc_get_opaque_fresh_review_request_public_evidence( $claimed ),
		'_fresh_review_request_record'              => $claimed,
	);
}

/**
 * Releases a retry-save fresh-review consumption claim after failed persistence.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array   $record Claimed fresh-review request record.
 * @param WP_Post $post   Post object.
 * @return bool Whether the claim was released.
 */
function wp_de_rtc_release_opaque_fresh_review_decision_retry_save_consumption_claim( $record, $post ) {
	$post        = get_post( $post );
	$option_name = isset( $record['public_record_id'] ) ? wp_de_rtc_get_opaque_fresh_review_request_record_option_name( $record['public_record_id'] ) : '';
	$claim_id    = isset( $record['fresh_review_decision_consumption_claim_id'] ) ? sanitize_text_field( (string) $record['fresh_review_decision_consumption_claim_id'] ) : '';

	if ( ! $post || '' === $option_name || '' === $claim_id || ! is_array( $record ) ) {
		return false;
	}

	wp_cache_delete( $option_name, 'options' );

	$stored_record = wp_de_rtc_get_opaque_fresh_review_request_record( $record['public_record_id'] );

	if (
		! is_array( $stored_record ) ||
		empty( $stored_record['fresh_review_decision_consumption_claimed'] ) ||
		! isset( $stored_record['fresh_review_decision_consumption_claim_id'] ) ||
		! hash_equals( $claim_id, (string) $stored_record['fresh_review_decision_consumption_claim_id'] )
	) {
		return false;
	}

	$released = $stored_record;

	$released['status']                    = 'decision_recorded';
	$released['fresh_review_request_status'] = 'decision_recorded';
	$released['updated_at']                = time();
	$released['retry_save_attempted']      = false;
	unset(
		$released['fresh_review_decision_consumption_claimed'],
		$released['fresh_review_decision_consumption_claimed_at'],
		$released['fresh_review_decision_consumption_claim_id'],
		$released['fresh_review_lifecycle_status'],
		$released['fresh_review_lifecycle_event'],
		$released['fresh_review_lifecycle_reason'],
		$released['previous_server_version'],
		$released['retry_save_proposed_post_content_hash'],
		$released['retry_save_candidate_post_content_hash']
	);

	return wp_de_rtc_atomic_update_opaque_fresh_review_request_record( $option_name, $stored_record, $released );
}

/**
 * Creates a durable opaque fresh-review request record.
 *
 * @since 7.1.0
 * @access private
 *
 * @param WP_Post $post Post object.
 * @param array   $args Request evidence.
 * @return array|WP_Error Fresh-review request record, or storage failure.
 */
function wp_de_rtc_create_opaque_fresh_review_request_record( $post, $args ) {
	$post = get_post( $post );

	if ( ! $post || ! is_array( $args ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_storage_failure',
			__( 'Distributed Editing could not store the fresh review request.' ),
			array(
				'detail'               => 'fresh_review_request_record_store_failed',
				'post_id'              => $post ? (int) $post->ID : 0,
				'rest_route'           => 'post_fresh_review_request',
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$now = time();

	for ( $attempt = 0; $attempt < 5; $attempt++ ) {
		$record_id   = wp_de_rtc_generate_opaque_fresh_review_request_record_id();
		$option_name = wp_de_rtc_get_opaque_fresh_review_request_record_option_name( $record_id );

		if ( '' === $option_name ) {
			continue;
		}

		$record = array(
			'type'                             => 'opaque_fresh_review_request_record',
			'record_version'                   => 1,
			'audit_storage_engine'             => 'option',
			'public_record_id'                 => $record_id,
			'status'                           => 'requested',
			'fresh_review_request_status'      => 'requested',
			'decision_recorded'                => false,
			'created_at'                       => $now,
			'updated_at'                       => $now,
			'post_id'                          => (int) $post->ID,
			'post_type'                        => $post->post_type,
			'client_base_version'              => isset( $args['client_base_version'] ) ? sanitize_text_field( (string) $args['client_base_version'] ) : '',
			'server_version'                   => isset( $args['server_version'] ) ? sanitize_text_field( (string) $args['server_version'] ) : '',
			'pending_change_count'             => isset( $args['pending_change_count'] ) ? max( 0, (int) $args['pending_change_count'] ) : 1,
			'proposed_post_content_hash'       => isset( $args['proposed_post_content_hash'] ) ? sanitize_text_field( (string) $args['proposed_post_content_hash'] ) : '',
			'candidate_post_content_hash'      => isset( $args['candidate_post_content_hash'] ) && null !== $args['candidate_post_content_hash'] ? sanitize_text_field( (string) $args['candidate_post_content_hash'] ) : '',
			'hash_evidence_fields'             => isset( $args['hash_evidence_fields'] ) && is_array( $args['hash_evidence_fields'] ) ? array_values( array_map( 'sanitize_key', $args['hash_evidence_fields'] ) ) : array(),
			'imported_fresh_review_handoff'    => ! empty( $args['is_imported_fresh_review_request'] ),
			'raw_content_included'             => false,
			'reviewed_block_items_included'    => false,
			'reviewed_block_item_count'        => 0,
			'saves_post'                       => false,
			'mutates_post_content'             => false,
			'creates_revision'                 => false,
			'claims_saved'                     => false,
			'resolves_proof'                   => false,
			'resolves_proof_token'             => false,
			'approves_review_proof'            => false,
			'retry_save_attempted'             => false,
			'normal_save_attempted'            => false,
			'applies_recovery'                 => false,
			'changes_locks'                    => false,
		);

		if ( add_option( $option_name, $record, '', 'no' ) ) {
			return $record;
		}
	}

	return wp_de_rtc_get_reason_error(
		'de_rtc_storage_failure',
		__( 'Distributed Editing could not store the fresh review request.' ),
		array(
			'detail'               => 'fresh_review_request_record_store_failed',
			'post_id'              => (int) $post->ID,
			'rest_route'           => 'post_fresh_review_request',
			'saves_post'           => false,
			'mutates_post_content' => false,
			'creates_revision'     => false,
			'claims_saved'         => false,
		)
	);
}

/**
 * Records a durable opaque fresh-review decision.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array   $record Fresh-review request record.
 * @param WP_Post $post   Post object.
 * @param array   $args   Decision evidence.
 * @return array|WP_Error Updated fresh-review request record, or storage failure.
 */
function wp_de_rtc_record_opaque_fresh_review_decision( $record, $post, $args ) {
	$post        = get_post( $post );
	$option_name = isset( $record['public_record_id'] ) ? wp_de_rtc_get_opaque_fresh_review_request_record_option_name( $record['public_record_id'] ) : '';

	if ( ! $post || '' === $option_name || ! is_array( $record ) || ! is_array( $args ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_storage_failure',
			__( 'Distributed Editing could not store the fresh review decision.' ),
			array(
				'detail'               => 'fresh_review_decision_record_store_failed',
				'post_id'              => $post ? (int) $post->ID : 0,
				'rest_route'           => 'post_fresh_review_decision',
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$decision             = wp_de_rtc_normalize_fresh_review_decision( isset( $args['fresh_review_decision'] ) ? $args['fresh_review_decision'] : '' );
	$reviewed_block_items = isset( $args['reviewed_block_items'] ) && is_array( $args['reviewed_block_items'] ) ? $args['reviewed_block_items'] : array();
	$now                  = time();

	$record['status']                            = 'decision_recorded';
	$record['fresh_review_request_status']       = 'decision_recorded';
	$record['fresh_review_decision']             = $decision;
	$record['fresh_review_decision_status']      = $decision;
	$record['decision_recorded']                 = true;
	$record['decision_recorded_at']              = $now;
	$record['updated_at']                        = $now;
	$record['client_base_version_at_decision']   = isset( $args['client_base_version'] ) ? sanitize_text_field( (string) $args['client_base_version'] ) : '';
	$record['server_version_at_decision']        = isset( $args['server_version'] ) ? sanitize_text_field( (string) $args['server_version'] ) : '';
	$record['reviewed_proposed_content_hash']    = isset( $args['reviewed_proposed_content_hash'] ) ? sanitize_text_field( (string) $args['reviewed_proposed_content_hash'] ) : '';
	$record['reviewed_candidate_content_hash']   = isset( $args['reviewed_candidate_content_hash'] ) && null !== $args['reviewed_candidate_content_hash'] ? sanitize_text_field( (string) $args['reviewed_candidate_content_hash'] ) : '';
	$record['reviewed_block_items']              = $reviewed_block_items;
	$record['reviewed_block_items_included']     = ! empty( $reviewed_block_items );
	$record['reviewed_block_item_count']         = count( $reviewed_block_items );
	$record['reviewed_block_decision_counts']    = wp_de_rtc_count_fresh_review_decision_block_items( $reviewed_block_items );
	$record['reviewer_user_id']                  = get_current_user_id();
	$record['reviewer_capability']               = 'unfiltered_html';
	$record['review_scope']                      = 'collaborative_post_content';
	$record['raw_content_included']              = false;
	$record['saves_post']                        = false;
	$record['mutates_post_content']              = false;
	$record['creates_revision']                  = false;
	$record['claims_saved']                      = false;
	$record['resolves_proof']                    = false;
	$record['resolves_proof_token']              = false;
	$record['approves_review_proof']             = false;
	$record['retry_save_attempted']              = false;
	$record['normal_save_attempted']             = false;
	$record['applies_recovery']                  = false;
	$record['changes_locks']                     = false;

	if ( update_option( $option_name, $record, false ) ) {
		return $record;
	}

	$stored_record = get_option( $option_name, null );

	if ( $stored_record === $record ) {
		return $record;
	}

	return wp_de_rtc_get_reason_error(
		'de_rtc_storage_failure',
		__( 'Distributed Editing could not store the fresh review decision.' ),
		array(
			'detail'                         => 'fresh_review_decision_record_store_failed',
			'post_id'                        => (int) $post->ID,
			'rest_route'                     => 'post_fresh_review_decision',
			'fresh_review_request_record_id' => isset( $record['public_record_id'] ) ? sanitize_text_field( (string) $record['public_record_id'] ) : '',
			'saves_post'                     => false,
			'mutates_post_content'           => false,
			'creates_revision'               => false,
			'claims_saved'                   => false,
		)
	);
}

/**
 * Records that retry-save consumed an approved fresh-review decision.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array   $record Fresh-review request record.
 * @param WP_Post $post   Post object.
 * @param array   $args   Retry-save result evidence.
 * @return array Public, non-sensitive record evidence.
 */
function wp_de_rtc_record_opaque_fresh_review_decision_retry_save_consumed( $record, $post, $args ) {
	$post        = get_post( $post );
	$option_name = isset( $record['public_record_id'] ) ? wp_de_rtc_get_opaque_fresh_review_request_record_option_name( $record['public_record_id'] ) : '';
	$claim_id    = isset( $record['fresh_review_decision_consumption_claim_id'] ) ? sanitize_text_field( (string) $record['fresh_review_decision_consumption_claim_id'] ) : '';

	if ( ! $post || '' === $option_name || '' === $claim_id || ! is_array( $record ) || ! is_array( $args ) ) {
		return array(
			'storage'                => 'option',
			'recorded'               => false,
			'record_found'           => false,
			'record_id'              => isset( $record['public_record_id'] ) ? sanitize_text_field( (string) $record['public_record_id'] ) : '',
			'status'                 => 'consumption_record_unavailable',
			'consumption_recorded'   => false,
			'decision_consumed'      => false,
			'raw_content_included'   => false,
			'proof_internals_exposed' => false,
		);
	}

	wp_cache_delete( $option_name, 'options' );

	$stored_record = wp_de_rtc_get_opaque_fresh_review_request_record( $record['public_record_id'] );

	if (
		! is_array( $stored_record ) ||
		empty( $stored_record['fresh_review_decision_consumption_claimed'] ) ||
		! isset( $stored_record['fresh_review_decision_consumption_claim_id'] ) ||
		! hash_equals( $claim_id, (string) $stored_record['fresh_review_decision_consumption_claim_id'] )
	) {
		$public_evidence = wp_de_rtc_get_opaque_fresh_review_request_public_evidence( is_array( $stored_record ) ? $stored_record : $record );
		$public_evidence['consumption_recorded']    = false;
		$public_evidence['decision_consumed']       = false;
		$public_evidence['proof_internals_exposed'] = false;
		$public_evidence['raw_content_included']    = false;

		return $public_evidence;
	}

	$record = $stored_record;
	$now = time();

	$record['status']                          = 'retry_save_consumed';
	$record['fresh_review_request_status']     = 'retry_save_consumed';
	$record['fresh_review_decision_consumed']  = true;
	$record['fresh_review_decision_consumed_at'] = $now;
	$record['updated_at']                      = $now;
	$record['fresh_review_lifecycle_status']  = 'retry_save_consumed';
	$record['fresh_review_lifecycle_event']   = 'consumed';
	$record['fresh_review_lifecycle_reason']  = 'guarded_retry_save_applied';
	$record['updated_post_id']                 = isset( $args['updated_post_id'] ) ? (int) $args['updated_post_id'] : (int) $post->ID;
	$record['previous_server_version']         = isset( $args['previous_server_version'] ) ? sanitize_text_field( (string) $args['previous_server_version'] ) : '';
	$record['saved_server_version']            = isset( $args['server_version'] ) ? sanitize_text_field( (string) $args['server_version'] ) : '';
	$record['saved_post_content_hash']         = isset( $args['saved_post_content_hash'] ) ? sanitize_text_field( (string) $args['saved_post_content_hash'] ) : '';
	$record['retry_save_proposed_post_content_hash'] = isset( $args['proposed_post_content_hash'] ) ? sanitize_text_field( (string) $args['proposed_post_content_hash'] ) : '';
	$record['retry_save_attempted']            = true;
	$record['retry_save_applied']              = true;
	$record['consumes_review_decision']        = true;
	$record['saves_post']                      = true;
	$record['mutates_post_content']            = true;
	$record['creates_revision']                = ! empty( $args['revision_created'] ) && wp_validate_boolean( $args['revision_created'] );
	$record['created_revision_count']          = isset( $args['created_revision_count'] ) ? max( 0, (int) $args['created_revision_count'] ) : 0;
	$record['claims_saved']                    = true;
	$record['raw_content_included']            = false;
	$record['resolves_proof']                  = false;
	$record['resolves_proof_token']            = false;
	$record['approves_review_proof']           = false;
	$record['normal_save_attempted']           = false;
	$record['applies_recovery']                = false;
	$record['changes_locks']                   = false;
	unset(
		$record['fresh_review_decision_consumption_claimed'],
		$record['fresh_review_decision_consumption_claimed_at'],
		$record['fresh_review_decision_consumption_claim_id'],
		$record['retry_save_candidate_post_content_hash']
	);

	$recorded = wp_de_rtc_atomic_update_opaque_fresh_review_request_record( $option_name, $stored_record, $record );

	$public_evidence = wp_de_rtc_get_opaque_fresh_review_request_public_evidence( $record );
	$public_evidence['consumption_recorded']    = (bool) $recorded;
	$public_evidence['decision_consumed']       = (bool) $recorded;
	$public_evidence['proof_internals_exposed'] = false;
	$public_evidence['raw_content_included']    = false;

	return $public_evidence;
}

/**
 * Returns a stored opaque fresh-review request record.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $record_id Public fresh-review request record ID.
 * @return array|null Fresh-review request record, or null when unavailable.
 */
function wp_de_rtc_get_opaque_fresh_review_request_record( $record_id ) {
	$option_name = wp_de_rtc_get_opaque_fresh_review_request_record_option_name( $record_id );

	if ( '' === $option_name ) {
		return null;
	}

	$record = get_option( $option_name, null );

	if (
		! is_array( $record ) ||
		! isset( $record['type'], $record['record_version'], $record['public_record_id'] ) ||
		'opaque_fresh_review_request_record' !== $record['type'] ||
		1 !== (int) $record['record_version']
	) {
		return null;
	}

	return $record;
}

/**
 * Returns the option name for an opaque fresh-review request record.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $record_id Public fresh-review request record ID.
 * @return string Option name, or empty string when invalid.
 */
function wp_de_rtc_get_opaque_fresh_review_request_record_option_name( $record_id ) {
	$record_id = sanitize_text_field( (string) $record_id );

	if ( 1 !== preg_match( '/^de-rtc-fresh-review-[a-f0-9]{24}$/', $record_id ) ) {
		return '';
	}

	return 'de_rtc_fresh_review_request_' . hash( 'sha256', $record_id );
}

/**
 * Generates a public opaque fresh-review request record ID.
 *
 * @since 7.1.0
 * @access private
 *
 * @return string Public record ID.
 */
function wp_de_rtc_generate_opaque_fresh_review_request_record_id() {
	try {
		$random = bin2hex( random_bytes( 12 ) );
	} catch ( Exception $exception ) {
		$random = substr( hash( 'sha256', wp_generate_password( 64, true, true ) . microtime( true ) ), 0, 24 );
	}

	return 'de-rtc-fresh-review-' . substr( $random, 0, 24 );
}

/**
 * Returns public, non-sensitive fresh-review request record evidence.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $record Fresh-review request record.
 * @return array Public record evidence.
 */
function wp_de_rtc_get_opaque_fresh_review_request_public_evidence( $record ) {
	if ( ! is_array( $record ) ) {
		$record = array();
	}

	$evidence = array(
		'storage'      => 'option',
		'recorded'     => ! empty( $record['public_record_id'] ),
		'record_found' => ! empty( $record['public_record_id'] ),
		'record_id'    => isset( $record['public_record_id'] ) ? sanitize_text_field( (string) $record['public_record_id'] ) : '',
		'status'       => isset( $record['status'] ) ? sanitize_key( (string) $record['status'] ) : '',
	);

	if ( ! empty( $record['decision_recorded'] ) ) {
		$evidence['decision_recorded'] = true;
		$evidence['decision_status']   = isset( $record['fresh_review_decision_status'] ) ? sanitize_key( (string) $record['fresh_review_decision_status'] ) : '';
	} else {
		$evidence['decision_recorded'] = false;
	}

	if ( isset( $record['reviewed_block_item_count'] ) ) {
		$evidence['reviewed_block_item_count'] = max( 0, (int) $record['reviewed_block_item_count'] );
	}

	if ( ! empty( $record['fresh_review_decision_consumed'] ) ) {
		$evidence['decision_consumed'] = true;
	}

	if ( isset( $record['fresh_review_lifecycle_status'] ) ) {
		$evidence['lifecycle_status'] = sanitize_key( (string) $record['fresh_review_lifecycle_status'] );
	} elseif ( ! empty( $record['fresh_review_decision_consumed'] ) ) {
		$evidence['lifecycle_status'] = 'retry_save_consumed';
	}

	if ( isset( $record['fresh_review_lifecycle_event'] ) ) {
		$evidence['lifecycle_event'] = sanitize_key( (string) $record['fresh_review_lifecycle_event'] );
	}

	if ( isset( $record['fresh_review_lifecycle_reason'] ) ) {
		$evidence['lifecycle_reason'] = sanitize_key( (string) $record['fresh_review_lifecycle_reason'] );
	}

	foreach ( array( 'previous_server_version', 'saved_server_version' ) as $version_field ) {
		if ( isset( $record[ $version_field ] ) && '' !== (string) $record[ $version_field ] ) {
			$evidence[ $version_field ] = sanitize_text_field( (string) $record[ $version_field ] );
		}
	}

	if ( isset( $record['fresh_review_decision_consumed_at'] ) ) {
		$evidence['decision_consumed_at'] = max( 0, (int) $record['fresh_review_decision_consumed_at'] );
	}

	return $evidence;
}

/**
 * Normalizes a fresh-review decision label.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $decision Decision label.
 * @return string Normalized decision, or empty string.
 */
function wp_de_rtc_normalize_fresh_review_decision( $decision ) {
	$decision = sanitize_key( (string) $decision );

	if ( in_array( $decision, array( 'approved', 'approve', 'approved_for_retry_save', 'approved_by_unfiltered_html_reviewer' ), true ) ) {
		return 'approved';
	}

	if ( in_array( $decision, array( 'rejected', 'reject', 'rejected_by_reviewer', 'rejected_by_unfiltered_html_reviewer' ), true ) ) {
		return 'rejected';
	}

	return '';
}

/**
 * Returns normalized hash-only fresh-review block decisions.
 *
 * @since 7.1.0
 * @access private
 *
 * @param WP_Post $post             Post object.
 * @param array   $args             Decision request arguments.
 * @param string  $default_decision Default decision for items without status.
 * @return array[]|WP_Error Normalized block decision items, or rejection.
 */
function wp_de_rtc_get_normalized_fresh_review_decision_block_items( $post, $args, $default_decision ) {
	$post = get_post( $post );

	if ( ! array_key_exists( 'reviewed_block_items', $args ) || null === $args['reviewed_block_items'] ) {
		return array();
	}

	if ( ! is_array( $args['reviewed_block_items'] ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the fresh review decision because reviewed block items are malformed.' ),
			array(
				'detail'               => 'malformed_fresh_review_decision_block_items',
				'post_id'              => $post ? (int) $post->ID : 0,
				'rest_route'           => 'post_fresh_review_decision',
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$items = array();

	foreach ( array_values( $args['reviewed_block_items'] ) as $index => $item ) {
		if ( is_object( $item ) ) {
			$item = get_object_vars( $item );
		}

		if ( ! is_array( $item ) ) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_malformed_sync_payload',
				__( 'Distributed Editing rejected the fresh review decision because a reviewed block item is malformed.' ),
				array(
					'detail'               => 'malformed_fresh_review_decision_block_item',
					'post_id'              => $post ? (int) $post->ID : 0,
					'rest_route'           => 'post_fresh_review_decision',
					'raw_content_included' => false,
					'saves_post'           => false,
					'mutates_post_content' => false,
					'creates_revision'     => false,
					'claims_saved'         => false,
				)
			);
		}

		$raw_content_param_paths = wp_de_rtc_find_raw_post_content_param_paths( $item, 'reviewed_block_items.' . $index );

		if ( ! empty( $raw_content_param_paths ) ) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_sync_meta_tampered',
				__( 'Distributed Editing rejected the fresh review decision because reviewed block raw content is not allowed.' ),
				array(
					'detail'                       => 'fresh_review_decision_block_item_raw_content_rejected',
					'post_id'                      => $post ? (int) $post->ID : 0,
					'rest_route'                   => 'post_fresh_review_decision',
					'request_raw_content_included' => true,
					'raw_content_included'         => false,
					'raw_content_param_paths'      => $raw_content_param_paths,
					'saves_post'                   => false,
					'mutates_post_content'         => false,
					'creates_revision'             => false,
					'claims_saved'                 => false,
					'resolves_proof'               => false,
					'resolves_proof_token'         => false,
					'approves_review_proof'        => false,
				)
			);
		}

		$decision              = wp_de_rtc_normalize_fresh_review_decision( isset( $item['review_status'] ) ? $item['review_status'] : $default_decision );
		$review_evidence_type  = isset( $item['review_evidence_type'] ) ? sanitize_key( (string) $item['review_evidence_type'] ) : '';
		$content_review_policy = isset( $item['content_review_policy'] ) ? sanitize_key( (string) $item['content_review_policy'] ) : '';
		$proposed_hash         = wp_de_rtc_get_request_hash_evidence( $item, 'proposed_content_hash' );
		$reviewed_hash         = wp_de_rtc_get_request_hash_evidence( $item, 'reviewed_proposed_content_hash' );
		$filtered_hash         = wp_de_rtc_get_request_hash_evidence( $item, 'kses_filtered_content_hash' );
		$missing_fields        = array();

		if ( '' === $decision ) {
			$missing_fields[] = 'review_status';
		}

		if ( 'kses_block_hash_only_change' !== $review_evidence_type ) {
			$missing_fields[] = 'review_evidence_type';
		}

		if ( 'kses' !== $content_review_policy ) {
			$missing_fields[] = 'content_review_policy';
		}

		if ( ! wp_de_rtc_is_sha256_hash( $proposed_hash ) ) {
			$missing_fields[] = 'proposed_content_hash';
		}

		if ( ! wp_de_rtc_is_sha256_hash( $reviewed_hash ) ) {
			$missing_fields[] = 'reviewed_proposed_content_hash';
		}

		if ( null !== $filtered_hash && ! wp_de_rtc_is_sha256_hash( $filtered_hash ) ) {
			$missing_fields[] = 'kses_filtered_content_hash';
		}

		if ( ! empty( $missing_fields ) ) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_malformed_sync_payload',
				__( 'Distributed Editing rejected the fresh review decision because reviewed block hash evidence is incomplete.' ),
				array(
					'detail'                         => 'missing_fresh_review_decision_block_item_evidence',
					'post_id'                        => $post ? (int) $post->ID : 0,
					'rest_route'                     => 'post_fresh_review_decision',
					'missing_hash_evidence_fields'   => $missing_fields,
					'raw_content_included'           => false,
					'saves_post'                     => false,
					'mutates_post_content'           => false,
					'creates_revision'               => false,
					'claims_saved'                   => false,
				)
			);
		}

		if ( ! hash_equals( $proposed_hash, $reviewed_hash ) ) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_sync_meta_tampered',
				__( 'Distributed Editing rejected the fresh review decision because reviewed block hashes do not match.' ),
				array(
					'detail'                          => 'fresh_review_decision_block_item_hash_evidence_mismatch',
					'post_id'                         => $post ? (int) $post->ID : 0,
					'rest_route'                      => 'post_fresh_review_decision',
					'mismatched_hash_evidence_fields' => array( 'reviewed_proposed_content_hash' ),
					'raw_content_included'            => false,
					'saves_post'                      => false,
					'mutates_post_content'            => false,
					'creates_revision'                => false,
					'claims_saved'                    => false,
				)
			);
		}

		$items[] = array(
			'id'                           => isset( $item['id'] ) ? sanitize_key( (string) $item['id'] ) : 'fresh-review-item-' . $index,
			'review_status'                => $decision,
			'review_evidence_type'         => 'kses_block_hash_only_change',
			'content_review_policy'        => 'kses',
			'proposed_content_hash'        => $proposed_hash,
			'reviewed_proposed_content_hash' => $reviewed_hash,
			'kses_filtered_content_hash'   => $filtered_hash,
			'raw_content_included'         => false,
			'exposes_raw_content'          => false,
		);
	}

	return $items;
}

/**
 * Counts normalized fresh-review block decisions by decision status.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array[] $items Normalized decision items.
 * @return int[] Decision counts.
 */
function wp_de_rtc_count_fresh_review_decision_block_items( $items ) {
	$counts = array(
		'approved' => 0,
		'rejected' => 0,
	);

	foreach ( (array) $items as $item ) {
		$status = isset( $item['review_status'] ) ? sanitize_key( (string) $item['review_status'] ) : '';

		if ( isset( $counts[ $status ] ) ) {
			$counts[ $status ]++;
		}
	}

	return $counts;
}

/**
 * Normalizes public fresh-review decision counts.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $counts Decision counts.
 * @return int[] Public decision counts.
 */
function wp_de_rtc_get_fresh_review_public_decision_counts( $counts ) {
	return array(
		'approved' => isset( $counts['approved'] ) ? max( 0, (int) $counts['approved'] ) : 0,
		'rejected' => isset( $counts['rejected'] ) ? max( 0, (int) $counts['rejected'] ) : 0,
	);
}

/**
 * Returns a proof-only unfiltered-HTML review approval result.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post Post ID or object.
 * @param array       $args {
 *     Review approval arguments.
 *
 *     @type mixed $client_base_version                  Client base version after local rebase.
 *     @type mixed $accepted_proof_server_version        Server version from accepted proof.
 *     @type mixed $pending_change_count                 Pending local change count. Default 1.
 *     @type mixed $proposed_post_content_hash           Proposed stripped post-content hash.
 *     @type mixed $reviewed_proposed_content_hash       Reviewer-approved proposed stripped post-content hash.
 *     @type mixed $candidate_post_content_hash          Retry-save candidate post-content hash.
 *     @type mixed $reviewed_candidate_content_hash      Reviewer-approved retry-save candidate hash.
 *     @type mixed $kses_filtered_proposed_content_hash  Optional filtered proposed-content hash.
 *     @type mixed $kses_filtered_candidate_content_hash Optional filtered retry-save candidate hash.
 *     @type array $reviewed_block_items                 Optional approved risky-block review items.
 *     @type array $raw_request_params                   Full request parameters for raw-content rejection.
 * }
 * @return array|WP_Error Review approval result, or rejection.
 */
function wp_de_rtc_get_unfiltered_html_review_approval_result( $post, $args = array() ) {
	$post = get_post( $post );

	if ( ! $post ) {
		return new WP_Error(
			'rest_post_invalid_id',
			__( 'Invalid post ID.' ),
			array( 'status' => 404 )
		);
	}

	$raw_content_param_paths = isset( $args['raw_request_params'] ) && is_array( $args['raw_request_params'] )
		? wp_de_rtc_find_raw_post_content_param_paths( $args['raw_request_params'] )
		: array();

	if ( ! empty( $raw_content_param_paths ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the review approval because raw post content is not allowed.' ),
			array(
				'detail'                       => 'review_approval_raw_post_content_rejected',
				'post_id'                      => (int) $post->ID,
				'rest_route'                   => 'post_retry_save_review_approval',
				'request_raw_content_included' => true,
				'raw_content_included'         => false,
				'raw_content_param_paths'      => $raw_content_param_paths,
				'saves_post'                   => false,
				'mutates_post_content'         => false,
				'creates_revision'             => false,
				'claims_saved'                 => false,
			)
		);
	}

	$client_base_version            = isset( $args['client_base_version'] ) ? sanitize_text_field( (string) $args['client_base_version'] ) : '';
	$accepted_proof_server_version = isset( $args['accepted_proof_server_version'] ) ? sanitize_text_field( (string) $args['accepted_proof_server_version'] ) : '';
	$server_version                 = wp_de_rtc_get_post_sync_meta_version( $post );
	$pending_change_count           = array_key_exists( 'pending_change_count', $args ) ? max( 0, (int) $args['pending_change_count'] ) : 1;

	if (
		'' === $client_base_version ||
		'' === $accepted_proof_server_version ||
		null === $server_version ||
		$client_base_version !== $server_version ||
		$accepted_proof_server_version !== $server_version
	) {
		return wp_de_rtc_get_stale_base_rejection_error(
			$post,
			array(
				'client_base_version'      => $client_base_version,
				'server_version'           => $server_version,
				'pending_change_count'     => $pending_change_count,
				'remote_change_count'      => 1,
				'can_attempt_local_rebase' => false,
				'rest_route'               => 'post_retry_save_review_approval_stale_base',
				'saves_post'               => false,
				'mutates_post_content'     => false,
				'creates_revision'         => false,
				'claims_saved'             => false,
			)
		);
	}

	$proposed_post_content_hash      = wp_de_rtc_get_request_hash_evidence( $args, 'proposed_post_content_hash' );
	$reviewed_proposed_content_hash  = wp_de_rtc_get_request_hash_evidence( $args, 'reviewed_proposed_content_hash' );
	$candidate_post_content_hash     = wp_de_rtc_get_request_hash_evidence( $args, 'candidate_post_content_hash' );
	$reviewed_candidate_content_hash = wp_de_rtc_get_request_hash_evidence( $args, 'reviewed_candidate_content_hash' );
	$missing_hash_fields             = array();

	foreach (
		array(
			'proposed_post_content_hash'      => $proposed_post_content_hash,
			'reviewed_proposed_content_hash'  => $reviewed_proposed_content_hash,
			'candidate_post_content_hash'     => $candidate_post_content_hash,
			'reviewed_candidate_content_hash' => $reviewed_candidate_content_hash,
		) as $field => $hash
	) {
		if ( ! wp_de_rtc_is_sha256_hash( $hash ) ) {
			$missing_hash_fields[] = $field;
		}
	}

	$kses_filtered_proposed_content_hash  = wp_de_rtc_get_request_hash_evidence( $args, 'kses_filtered_proposed_content_hash' );
	$kses_filtered_candidate_content_hash = wp_de_rtc_get_request_hash_evidence( $args, 'kses_filtered_candidate_content_hash' );

	foreach (
		array(
			'kses_filtered_proposed_content_hash'  => $kses_filtered_proposed_content_hash,
			'kses_filtered_candidate_content_hash' => $kses_filtered_candidate_content_hash,
		) as $field => $hash
	) {
		if ( null !== $hash && ! wp_de_rtc_is_sha256_hash( $hash ) ) {
			$missing_hash_fields[] = $field;
		}
	}

	if ( ! empty( $missing_hash_fields ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the review approval because hash evidence is incomplete.' ),
			array(
				'detail'                       => 'missing_review_approval_hash_evidence',
				'post_id'                      => (int) $post->ID,
				'rest_route'                   => 'post_retry_save_review_approval',
				'missing_hash_evidence_fields' => $missing_hash_fields,
				'raw_content_included'         => false,
				'saves_post'                   => false,
				'mutates_post_content'         => false,
				'creates_revision'             => false,
				'claims_saved'                 => false,
			)
		);
	}

	$mismatched_hash_fields = array();

	if ( ! hash_equals( $proposed_post_content_hash, $reviewed_proposed_content_hash ) ) {
		$mismatched_hash_fields[] = 'reviewed_proposed_content_hash';
	}

	if ( ! hash_equals( $candidate_post_content_hash, $reviewed_candidate_content_hash ) ) {
		$mismatched_hash_fields[] = 'reviewed_candidate_content_hash';
	}

	if ( ! empty( $mismatched_hash_fields ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the review approval because the approved hash evidence does not match.' ),
			array(
				'detail'                          => 'review_approval_hash_evidence_mismatch',
				'post_id'                         => (int) $post->ID,
				'rest_route'                      => 'post_retry_save_review_approval',
				'mismatched_hash_evidence_fields' => $mismatched_hash_fields,
				'proposed_post_content_hash'      => $proposed_post_content_hash,
				'reviewed_proposed_content_hash'  => $reviewed_proposed_content_hash,
				'candidate_post_content_hash'     => $candidate_post_content_hash,
				'reviewed_candidate_content_hash' => $reviewed_candidate_content_hash,
				'raw_content_included'            => false,
				'saves_post'                      => false,
				'mutates_post_content'            => false,
				'creates_revision'                => false,
				'claims_saved'                    => false,
			)
		);
	}

	$reviewed_block_items = wp_de_rtc_get_normalized_review_approval_block_items( $post, $args );

	if ( is_wp_error( $reviewed_block_items ) ) {
		return $reviewed_block_items;
	}

	$review_approval_proof = array(
		'type'                              => 'unfiltered_html_retry_save_review_approval',
		'status'                            => 'approved_by_unfiltered_html_reviewer',
		'post_id'                           => (int) $post->ID,
		'post_type'                         => $post->post_type,
		'reviewer_user_id'                  => get_current_user_id(),
		'reviewer_capability'               => 'unfiltered_html',
		'review_scope'                      => 'collaborative_post_content',
		'server_version'                    => $server_version,
		'client_base_version'               => $client_base_version,
		'accepted_proof_server_version'     => $accepted_proof_server_version,
		'proposed_post_content_hash'        => $proposed_post_content_hash,
		'reviewed_proposed_content_hash'    => $reviewed_proposed_content_hash,
		'candidate_post_content_hash'       => $candidate_post_content_hash,
		'reviewed_candidate_content_hash'   => $reviewed_candidate_content_hash,
		'candidate_post_content_hash_scope' => 'current_saver_candidate',
		'requires_unfiltered_html_saver'    => false,
		'raw_content_included'              => false,
		'saves_post'                        => false,
		'mutates_post_content'              => false,
		'creates_revision'                  => false,
		'claims_saved'                      => false,
		'reviewed_block_items'              => $reviewed_block_items,
		'reviewed_block_item_count'         => count( $reviewed_block_items ),
		'block_review_status'               => ! empty( $reviewed_block_items ) ? 'approved_for_retry_save' : null,
	);

	if ( null !== $kses_filtered_proposed_content_hash ) {
		$review_approval_proof['kses_filtered_proposed_content_hash'] = $kses_filtered_proposed_content_hash;
	}

	if ( null !== $kses_filtered_candidate_content_hash ) {
		$review_approval_proof['kses_filtered_candidate_content_hash'] = $kses_filtered_candidate_content_hash;
	}

	$review_approval_proof = wp_de_rtc_add_review_approval_proof_signature( $review_approval_proof );
	$review_approval_proof_envelope = wp_de_rtc_create_opaque_review_approval_proof_token_envelope( $review_approval_proof );

	if ( is_wp_error( $review_approval_proof_envelope ) ) {
		return $review_approval_proof_envelope;
	}

	return array(
		'result'                              => 'review_approval_accepted_for_retry_save',
		'review_approval_accepted'            => true,
		'unfiltered_html_review_approved'     => true,
		'rest_route'                          => 'post_retry_save_review_approval',
		'post_id'                             => (int) $post->ID,
		'reviewer_user_id'                    => get_current_user_id(),
		'client_base_version'                 => $client_base_version,
		'accepted_proof_server_version'       => $accepted_proof_server_version,
		'server_version'                      => $server_version,
		'pending_change_count'                => $pending_change_count,
		'approval_status'                     => 'approved_for_retry_save',
		'approval_action'                     => 'retry_save_with_reviewer_approval',
		'review_status'                       => 'approved_by_unfiltered_html_reviewer',
		'review_action'                       => 'request_unfiltered_html_reviewer',
		'review_required_capability'          => 'unfiltered_html',
		'reviewer_capability'                 => 'unfiltered_html',
		'review_scope'                        => 'collaborative_post_content',
		'proposed_post_content_hash'          => $proposed_post_content_hash,
		'reviewed_proposed_content_hash'      => $reviewed_proposed_content_hash,
		'candidate_post_content_hash'         => $candidate_post_content_hash,
		'reviewed_candidate_content_hash'     => $reviewed_candidate_content_hash,
		'kses_filtered_proposed_content_hash'  => $kses_filtered_proposed_content_hash,
		'kses_filtered_candidate_content_hash' => $kses_filtered_candidate_content_hash,
		'reviewed_block_items'                => $reviewed_block_items,
		'reviewed_block_item_count'           => count( $reviewed_block_items ),
		'block_review_status'                 => ! empty( $reviewed_block_items ) ? 'approved_for_retry_save' : null,
		'raw_content_included'                => false,
		'requires_server_state_refetch'       => false,
		'requires_manual_conflict_resolution' => false,
		'can_export_local_updates'            => $pending_change_count > 0,
		'save_path_required'                  => true,
		'saves_post'                          => false,
		'mutates_post_content'                => false,
		'creates_revision'                    => false,
		'claims_saved'                        => false,
		'review_approval_proof_format'        => 'opaque_review_approval_proof_token',
		'review_approval_proof'               => $review_approval_proof_envelope,
		'permission_contract'                 => wp_de_rtc_get_rest_recovery_permission_contract( $post ),
	);
}

/**
 * Returns normalized hash-only risky-block approval proof items.
 *
 * @since 7.1.0
 * @access private
 *
 * @param WP_Post $post Post object.
 * @param array   $args Review approval arguments.
 * @return array[]|WP_Error Normalized block review items, or a rejection.
 */
function wp_de_rtc_get_normalized_review_approval_block_items( $post, $args ) {
	if (
		! array_key_exists( 'reviewed_block_items', $args ) ||
		null === $args['reviewed_block_items']
	) {
		return array();
	}

	if ( ! is_array( $args['reviewed_block_items'] ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the review approval because block review proof is malformed.' ),
			array(
				'detail'                       => 'malformed_review_approval_block_items',
				'post_id'                      => (int) $post->ID,
				'rest_route'                   => 'post_retry_save_review_approval',
				'raw_content_included'         => false,
				'saves_post'                   => false,
				'mutates_post_content'         => false,
				'creates_revision'             => false,
				'claims_saved'                 => false,
			)
		);
	}

	$normalized_items  = array();
	$missing_fields    = array();
	$mismatched_fields = array();
	$unapproved_items  = array();

	foreach ( $args['reviewed_block_items'] as $index => $item ) {
		if ( is_object( $item ) ) {
			$item = get_object_vars( $item );
		}

		if ( ! is_array( $item ) ) {
			$missing_fields[] = 'reviewed_block_items.' . $index;
			continue;
		}

		if (
			! empty( $item['raw_content_included'] ) ||
			! empty( $item['exposes_raw_content'] )
		) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_sync_meta_tampered',
				__( 'Distributed Editing rejected the review approval because a block review item included raw content evidence.' ),
				array(
					'detail'                       => 'review_approval_block_item_raw_content_rejected',
					'post_id'                      => (int) $post->ID,
					'rest_route'                   => 'post_retry_save_review_approval',
					'reviewed_block_item_index'    => $index,
					'request_raw_content_included' => true,
					'raw_content_included'         => false,
					'saves_post'                   => false,
					'mutates_post_content'         => false,
					'creates_revision'             => false,
					'claims_saved'                 => false,
				)
			);
		}

		$id                             = isset( $item['id'] ) ? sanitize_text_field( (string) $item['id'] ) : '';
		$review_status                  = isset( $item['review_status'] ) ? sanitize_key( (string) $item['review_status'] ) : '';
		$proposed_content_hash          = wp_de_rtc_get_request_hash_evidence( $item, 'proposed_content_hash' );
		$reviewed_proposed_content_hash = wp_de_rtc_get_request_hash_evidence( $item, 'reviewed_proposed_content_hash' );
		$base_content_hash              = wp_de_rtc_get_request_hash_evidence( $item, 'base_content_hash' );
		$kses_filtered_content_hash     = wp_de_rtc_get_request_hash_evidence( $item, 'kses_filtered_content_hash' );
		$review_evidence_type           = isset( $item['review_evidence_type'] )
			? sanitize_key( (string) $item['review_evidence_type'] )
			: 'kses_block_hash_only_change';
		$content_review_policy          = isset( $item['content_review_policy'] )
			? sanitize_key( (string) $item['content_review_policy'] )
			: 'kses';

		if ( '' === $id ) {
			$missing_fields[] = 'reviewed_block_items.' . $index . '.id';
		}

		if ( 'approved_for_retry_save' !== $review_status ) {
			$unapproved_items[] = $id ? $id : (string) $index;
		}

		if ( ! wp_de_rtc_is_sha256_hash( $proposed_content_hash ) ) {
			$missing_fields[] = 'reviewed_block_items.' . $index . '.proposed_content_hash';
		}

		if ( null === $reviewed_proposed_content_hash ) {
			$reviewed_proposed_content_hash = $proposed_content_hash;
		}

		if ( ! wp_de_rtc_is_sha256_hash( $reviewed_proposed_content_hash ) ) {
			$missing_fields[] = 'reviewed_block_items.' . $index . '.reviewed_proposed_content_hash';
		}

		if ( null !== $base_content_hash && ! wp_de_rtc_is_sha256_hash( $base_content_hash ) ) {
			$missing_fields[] = 'reviewed_block_items.' . $index . '.base_content_hash';
		}

		if ( null !== $kses_filtered_content_hash && ! wp_de_rtc_is_sha256_hash( $kses_filtered_content_hash ) ) {
			$missing_fields[] = 'reviewed_block_items.' . $index . '.kses_filtered_content_hash';
		}

		if (
			null !== $proposed_content_hash &&
			null !== $reviewed_proposed_content_hash &&
			! hash_equals( $proposed_content_hash, $reviewed_proposed_content_hash )
		) {
			$mismatched_fields[] = 'reviewed_block_items.' . $index . '.reviewed_proposed_content_hash';
		}

		if ( 'kses_block_hash_only_change' !== $review_evidence_type ) {
			$missing_fields[] = 'reviewed_block_items.' . $index . '.review_evidence_type';
		}

		if ( 'kses' !== $content_review_policy ) {
			$missing_fields[] = 'reviewed_block_items.' . $index . '.content_review_policy';
		}

		$normalized_items[] = array(
			'id'                             => $id,
			'block_client_id'                => isset( $item['block_client_id'] )
				? sanitize_text_field( (string) $item['block_client_id'] )
				: '',
			'block_name'                     => isset( $item['block_name'] )
				? sanitize_text_field( (string) $item['block_name'] )
				: '',
			'block_label'                    => isset( $item['block_label'] )
				? sanitize_text_field( (string) $item['block_label'] )
				: '',
			'block_path'                     => isset( $item['block_path'] ) && is_array( $item['block_path'] )
				? array_map( 'absint', $item['block_path'] )
				: array(),
			'change_kind'                    => isset( $item['change_kind'] )
				? sanitize_key( (string) $item['change_kind'] )
				: '',
			'risk_reason'                    => isset( $item['risk_reason'] )
				? sanitize_key( (string) $item['risk_reason'] )
				: '',
			'base_content_hash'              => $base_content_hash,
			'proposed_content_hash'          => $proposed_content_hash,
			'reviewed_proposed_content_hash' => $reviewed_proposed_content_hash,
			'kses_filtered_content_hash'     => $kses_filtered_content_hash,
			'review_status'                  => 'approved_for_retry_save',
			'review_evidence_type'           => 'kses_block_hash_only_change',
			'content_review_policy'          => 'kses',
			'raw_content_included'           => false,
			'exposes_raw_content'            => false,
		);
	}

	if ( ! empty( $missing_fields ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the review approval because block review hash evidence is incomplete.' ),
			array(
				'detail'                       => 'missing_review_approval_block_item_evidence',
				'post_id'                      => (int) $post->ID,
				'rest_route'                   => 'post_retry_save_review_approval',
				'missing_hash_evidence_fields' => $missing_fields,
				'raw_content_included'         => false,
				'saves_post'                   => false,
				'mutates_post_content'         => false,
				'creates_revision'             => false,
				'claims_saved'                 => false,
			)
		);
	}

	if ( ! empty( $unapproved_items ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the review approval because not every block review item was approved.' ),
			array(
				'detail'                         => 'review_approval_block_item_not_approved',
				'post_id'                        => (int) $post->ID,
				'rest_route'                     => 'post_retry_save_review_approval',
				'unapproved_review_item_ids'     => $unapproved_items,
				'raw_content_included'           => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
			)
		);
	}

	if ( ! empty( $mismatched_fields ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the review approval because block review hash evidence does not match.' ),
			array(
				'detail'                          => 'review_approval_block_item_hash_evidence_mismatch',
				'post_id'                         => (int) $post->ID,
				'rest_route'                      => 'post_retry_save_review_approval',
				'mismatched_hash_evidence_fields' => $mismatched_fields,
				'raw_content_included'            => false,
				'saves_post'                      => false,
				'mutates_post_content'            => false,
				'creates_revision'                => false,
				'claims_saved'                    => false,
			)
		);
	}

	return $normalized_items;
}

/**
 * Extracts the field-based review approval proof from an accepted proof envelope.
 *
 * Current clients submit the signed field graph directly. This helper keeps that
 * shape compatible while giving future opaque or nonce-backed proof a single
 * server-side boundary to resolve before retry-save validation.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $proof_envelope Accepted review approval proof or envelope.
 * @param int   $post_id        Post ID for error evidence.
 * @return array|null|WP_Error Field-based proof, null when absent, or rejection.
 */
function wp_de_rtc_get_accepted_review_approval_proof_from_envelope( $proof_envelope, $post_id = 0 ) {
	if ( is_object( $proof_envelope ) ) {
		$proof_envelope = get_object_vars( $proof_envelope );
	}

	if ( null === $proof_envelope || '' === $proof_envelope ) {
		return null;
	}

	if ( ! is_array( $proof_envelope ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the retry save because review approval proof is malformed.' ),
			array(
				'detail'               => 'malformed_retry_save_review_approval_proof',
				'post_id'              => (int) $post_id,
				'rest_route'           => 'post_retry_save',
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	if ( ! array_key_exists( 'proof_envelope_type', $proof_envelope ) ) {
		return $proof_envelope;
	}

	$raw_content_param_paths = wp_de_rtc_find_raw_post_content_param_paths( $proof_envelope, 'review_approval_proof_envelope' );

	if ( ! empty( $raw_content_param_paths ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because review approval proof included raw content.' ),
			array(
				'detail'                       => 'retry_save_review_approval_raw_content_rejected',
				'post_id'                      => (int) $post_id,
				'rest_route'                   => 'post_retry_save',
				'review_approval_proof_format' => isset( $proof_envelope['proof_envelope_type'] ) ? sanitize_key( (string) $proof_envelope['proof_envelope_type'] ) : '',
				'request_raw_content_included' => true,
				'raw_content_included'         => false,
				'raw_content_param_paths'      => $raw_content_param_paths,
				'saves_post'                   => false,
				'mutates_post_content'         => false,
				'creates_revision'             => false,
				'claims_saved'                 => false,
			)
		);
	}

	$envelope_type = sanitize_key( (string) $proof_envelope['proof_envelope_type'] );

	if ( 'opaque_review_approval_proof_token' === $envelope_type ) {
		return wp_de_rtc_get_review_approval_proof_from_opaque_token_envelope( $proof_envelope, $post_id );
	}

	if ( 'field_based_review_approval_proof' !== $envelope_type ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the retry save because the review approval proof envelope is unsupported.' ),
			array(
				'detail'                       => 'unsupported_retry_save_review_approval_proof_envelope',
				'post_id'                      => (int) $post_id,
				'rest_route'                   => 'post_retry_save',
				'review_approval_proof_format' => $envelope_type,
				'saves_post'                   => false,
				'mutates_post_content'         => false,
				'creates_revision'             => false,
				'claims_saved'                 => false,
			)
		);
	}

	$proof = isset( $proof_envelope['proof'] ) ? $proof_envelope['proof'] : null;

	if ( is_object( $proof ) ) {
		$proof = get_object_vars( $proof );
	}

	if ( ! is_array( $proof ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the retry save because the review approval proof envelope is malformed.' ),
			array(
				'detail'                       => 'malformed_retry_save_review_approval_proof_envelope',
				'post_id'                      => (int) $post_id,
				'rest_route'                   => 'post_retry_save',
				'review_approval_proof_format' => $envelope_type,
				'saves_post'                   => false,
				'mutates_post_content'         => false,
				'creates_revision'             => false,
				'claims_saved'                 => false,
			)
		);
	}

	return $proof;
}

/**
 * Creates an opaque token envelope for an accepted review approval proof.
 *
 * The token cache is a proof-continuation cache only. It does not update post
 * content, create revisions, replace locks, apply recovery, or claim saved
 * state.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $proof Signed field-based review approval proof.
 * @return array|WP_Error Opaque token envelope, or storage failure.
 */
function wp_de_rtc_create_opaque_review_approval_proof_token_envelope( $proof ) {
	if ( ! is_array( $proof ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing could not create a review approval proof token because the proof is malformed.' ),
			array(
				'detail'               => 'malformed_review_approval_proof_for_token',
				'rest_route'           => 'post_retry_save_review_approval',
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$issued_at  = isset( $proof['issued_at'] ) && is_numeric( $proof['issued_at'] ) ? (int) $proof['issued_at'] : time();
	$expires_at = isset( $proof['expires_at'] ) && is_numeric( $proof['expires_at'] ) ? (int) $proof['expires_at'] : $issued_at + wp_de_rtc_get_review_approval_proof_lifetime_seconds();
	$now        = time();
	$ttl        = max( 1, $expires_at - $now );
	$token      = wp_de_rtc_generate_opaque_review_approval_proof_token();
	$key        = wp_de_rtc_get_opaque_review_approval_proof_token_transient_key( $token );
	$site_scope = wp_de_rtc_get_review_approval_proof_site_scope();
	$record     = array(
		'type'                              => 'opaque_review_approval_proof_token_record',
		'token_version'                     => 1,
		'field_based_review_approval_proof' => $proof,
		'issued_at'                         => $issued_at,
		'expires_at'                        => $expires_at,
		'site_id'                           => $site_scope['site_id'],
		'site_url'                          => $site_scope['site_url'],
		'post_id'                           => isset( $proof['post_id'] ) ? (int) $proof['post_id'] : 0,
		'post_type'                         => isset( $proof['post_type'] ) ? sanitize_key( (string) $proof['post_type'] ) : '',
		'server_version'                    => isset( $proof['server_version'] ) ? sanitize_text_field( (string) $proof['server_version'] ) : '',
		'proposed_post_content_hash'        => isset( $proof['proposed_post_content_hash'] ) ? sanitize_text_field( (string) $proof['proposed_post_content_hash'] ) : '',
		'reviewer_user_id'                  => isset( $proof['reviewer_user_id'] ) ? (int) $proof['reviewer_user_id'] : 0,
		'low_privileged_saver_user_id'      => isset( $proof['low_privileged_saver_user_id'] ) ? (int) $proof['low_privileged_saver_user_id'] : null,
	);

	if ( ! set_transient( $key, $record, $ttl ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_storage_failure',
			__( 'Distributed Editing could not store the review approval proof token.' ),
			array(
				'detail'               => 'review_approval_proof_token_store_failed',
				'post_id'              => (int) $record['post_id'],
				'rest_route'           => 'post_retry_save_review_approval',
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$reviewed_block_item_count = 0;

	if ( isset( $proof['reviewed_block_item_count'] ) ) {
		$reviewed_block_item_count = (int) $proof['reviewed_block_item_count'];
	} elseif ( isset( $proof['reviewed_block_items'] ) && is_array( $proof['reviewed_block_items'] ) ) {
		$reviewed_block_item_count = count( $proof['reviewed_block_items'] );
	}

	$token_audit = wp_de_rtc_record_opaque_review_approval_proof_token_audit_event(
		$token,
		'minted',
		array(
			'create_if_missing'             => true,
			'token_version'                 => 1,
			'post_id'                       => $record['post_id'],
			'post_type'                     => $record['post_type'],
			'server_version'                => $record['server_version'],
			'proposed_post_content_hash'    => $record['proposed_post_content_hash'],
			'candidate_post_content_hash'   => isset( $proof['candidate_post_content_hash'] ) ? sanitize_text_field( (string) $proof['candidate_post_content_hash'] ) : '',
			'reviewed_block_item_count'     => $reviewed_block_item_count,
			'issued_at'                     => $issued_at,
			'expires_at'                    => $expires_at,
			'rest_route'                    => 'post_retry_save_review_approval',
			'review_approval_proof_format'  => 'opaque_review_approval_proof_token',
			'review_approval_proof_storage' => 'transient_with_option_backed_audit',
		)
	);

	return array(
		'proof_envelope_type' => 'opaque_review_approval_proof_token',
		'token'               => $token,
		'token_version'       => 1,
		'issued_at'           => $issued_at,
		'expires_at'          => $expires_at,
		'post'                => array(
			'id'   => (int) $record['post_id'],
			'type' => $record['post_type'],
		),
		'token_audit'         => wp_de_rtc_get_opaque_review_approval_proof_token_audit_public_evidence( $token_audit ),
	);
}

/**
 * Generates an opaque bearer token for review approval proof resolution.
 *
 * @since 7.1.0
 * @access private
 *
 * @return string Opaque token.
 */
function wp_de_rtc_generate_opaque_review_approval_proof_token() {
	try {
		return bin2hex( random_bytes( 32 ) );
	} catch ( Exception $exception ) {
		return wp_generate_password( 64, false, false );
	}
}

/**
 * Returns the transient key for an opaque review approval proof token.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $token Opaque bearer token.
 * @return string Transient key.
 */
function wp_de_rtc_get_opaque_review_approval_proof_token_transient_key( $token ) {
	return 'de_rtc_review_approval_proof_' . hash( 'sha256', (string) $token );
}

/**
 * Returns the opaque token from a review approval proof envelope.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $proof_envelope Review approval proof or envelope.
 * @return string Opaque token, or empty string when unavailable.
 */
function wp_de_rtc_get_opaque_review_approval_proof_token_from_envelope( $proof_envelope ) {
	if ( is_object( $proof_envelope ) ) {
		$proof_envelope = get_object_vars( $proof_envelope );
	}

	if ( ! is_array( $proof_envelope ) ) {
		return '';
	}

	$envelope_type = isset( $proof_envelope['proof_envelope_type'] ) ? sanitize_key( (string) $proof_envelope['proof_envelope_type'] ) : '';

	if ( 'opaque_review_approval_proof_token' !== $envelope_type || empty( $proof_envelope['token'] ) ) {
		return '';
	}

	return sanitize_text_field( (string) $proof_envelope['token'] );
}

/**
 * Returns the option name for an opaque review approval proof token audit record.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $token Opaque bearer token.
 * @return string Option name, or empty string when the token is empty.
 */
function wp_de_rtc_get_opaque_review_approval_proof_token_audit_option_name( $token ) {
	$token = sanitize_text_field( (string) $token );

	if ( '' === $token ) {
		return '';
	}

	return 'de_rtc_review_approval_token_audit_' . hash( 'sha256', $token );
}

/**
 * Returns the public audit record ID for an opaque review approval proof token.
 *
 * The ID is suitable for support correlation. It is derived from the stored
 * token hash plus post/version evidence, but does not expose the token secret,
 * proof graph, reviewer, saver, or raw content.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $token_hash     SHA-256 token hash.
 * @param int    $post_id        Post ID.
 * @param string $server_version Server sync version.
 * @return string Public audit record ID, or empty string when unavailable.
 */
function wp_de_rtc_get_opaque_review_approval_proof_token_audit_public_record_id( $token_hash, $post_id = 0, $server_version = '' ) {
	$token_hash = sanitize_text_field( (string) $token_hash );

	if ( ! wp_de_rtc_is_sha256_hash( $token_hash ) ) {
		return '';
	}

	$record_id_material = implode(
		'|',
		array(
			'wp-de-rtc-review-approval-token-audit-v1',
			$token_hash,
			max( 0, (int) $post_id ),
			sanitize_text_field( (string) $server_version ),
		)
	);

	return 'de-rtc-audit-' . substr( hash( 'sha256', $record_id_material ), 0, 24 );
}

/**
 * Returns how long opaque token audit records should be retained after lifecycle evidence.
 *
 * @since 7.1.0
 * @access private
 *
 * @return int Retention period in seconds.
 */
function wp_de_rtc_get_opaque_review_approval_proof_token_audit_retention_seconds() {
	return 30 * DAY_IN_SECONDS;
}

/**
 * Returns when an opaque token audit record becomes cleanup-eligible.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array    $record            Audit record.
 * @param int|null $retention_seconds Optional retention period in seconds.
 * @return int Unix timestamp, or 0 when unavailable.
 */
function wp_de_rtc_get_opaque_review_approval_proof_token_audit_cleanup_eligible_at( $record, $retention_seconds = null ) {
	if ( ! is_array( $record ) ) {
		return 0;
	}

	$retention_seconds = null === $retention_seconds
		? wp_de_rtc_get_opaque_review_approval_proof_token_audit_retention_seconds()
		: max( 0, (int) $retention_seconds );
	$lifecycle_time        = 0;
	$lifecycle_time_fields = array( 'updated_at', 'expires_at', 'consumed_at', 'unavailable_at', 'expired_at', 'minted_at', 'created_at', 'issued_at' );

	foreach ( $lifecycle_time_fields as $time_field ) {
		if ( isset( $record[ $time_field ] ) && is_numeric( $record[ $time_field ] ) ) {
			$lifecycle_time = max( $lifecycle_time, (int) $record[ $time_field ] );
		}
	}

	if ( 0 === $lifecycle_time ) {
		return 0;
	}

	return $lifecycle_time + $retention_seconds;
}

/**
 * Returns a durable audit record for an opaque review approval proof token.
 *
 * This record is audit evidence only. It must not include the proof graph,
 * proof signature, reviewed block items, reviewer IDs, low-privilege saver IDs,
 * or raw risky content, and it must never be used to resolve a token for save.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $token_or_envelope Opaque token string or token envelope.
 * @return array|null Audit record, or null when unavailable.
 */
function wp_de_rtc_get_opaque_review_approval_proof_token_audit_record( $token_or_envelope ) {
	$token = is_array( $token_or_envelope ) || is_object( $token_or_envelope )
		? wp_de_rtc_get_opaque_review_approval_proof_token_from_envelope( $token_or_envelope )
		: sanitize_text_field( (string) $token_or_envelope );

	$option_name = wp_de_rtc_get_opaque_review_approval_proof_token_audit_option_name( $token );

	if ( '' === $option_name ) {
		return null;
	}

	$record = get_option( $option_name, null );

	if (
		! is_array( $record ) ||
		! isset( $record['type'], $record['audit_record_version'] ) ||
		'opaque_review_approval_proof_token_audit_record' !== $record['type'] ||
		1 !== (int) $record['audit_record_version']
	) {
		return null;
	}

	return $record;
}

/**
 * Records a privacy-preserving audit event for an opaque review approval token.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $token Opaque bearer token.
 * @param string $event Lifecycle event.
 * @param array  $args  Optional audit metadata.
 * @return array Public audit evidence summary.
 */
function wp_de_rtc_record_opaque_review_approval_proof_token_audit_event( $token, $event, $args = array() ) {
	$token       = sanitize_text_field( (string) $token );
	$event       = sanitize_key( (string) $event );
	$option_name = wp_de_rtc_get_opaque_review_approval_proof_token_audit_option_name( $token );

	if ( '' === $token || '' === $event || '' === $option_name ) {
		return wp_de_rtc_get_opaque_review_approval_proof_token_audit_summary( $event, false, null, false );
	}

	$now             = time();
	$existing_record = get_option( $option_name, null );
	$record_found    = is_array( $existing_record )
		&& isset( $existing_record['type'], $existing_record['audit_record_version'] )
		&& 'opaque_review_approval_proof_token_audit_record' === $existing_record['type']
		&& 1 === (int) $existing_record['audit_record_version'];

	if ( ! $record_found && empty( $args['create_if_missing'] ) ) {
		return wp_de_rtc_get_opaque_review_approval_proof_token_audit_summary( $event, false, null, false );
	}

	$previous_status = $record_found && isset( $existing_record['lifecycle_status'] )
		? sanitize_key( (string) $existing_record['lifecycle_status'] )
		: null;
	$record          = $record_found ? $existing_record : array(
		'type'                 => 'opaque_review_approval_proof_token_audit_record',
		'audit_record_version' => 1,
		'token_hash'           => hash( 'sha256', $token ),
		'created_at'           => $now,
		'events'               => array(),
	);

	$record['token_hash']           = isset( $record['token_hash'] ) ? sanitize_text_field( (string) $record['token_hash'] ) : hash( 'sha256', $token );
	$record['lifecycle_status']     = $event;
	$record['updated_at']           = $now;
	$record['audit_storage_engine'] = 'option';

	foreach ( array( 'token_version', 'post_id', 'issued_at', 'expires_at', 'reviewed_block_item_count' ) as $int_field ) {
		if ( array_key_exists( $int_field, $args ) && null !== $args[ $int_field ] ) {
			$record[ $int_field ] = max( 0, (int) $args[ $int_field ] );
		}
	}

	foreach ( array( 'post_type', 'server_version', 'rest_route', 'review_approval_proof_format', 'review_approval_proof_storage' ) as $text_field ) {
		if ( array_key_exists( $text_field, $args ) && '' !== (string) $args[ $text_field ] ) {
			$record[ $text_field ] = sanitize_text_field( (string) $args[ $text_field ] );
		}
	}

	foreach ( array( 'proposed_post_content_hash', 'candidate_post_content_hash' ) as $hash_field ) {
		if ( array_key_exists( $hash_field, $args ) && wp_de_rtc_is_sha256_hash( $args[ $hash_field ] ) ) {
			$record[ $hash_field ] = $args[ $hash_field ];
		}
	}

	$record['public_record_id'] = wp_de_rtc_get_opaque_review_approval_proof_token_audit_public_record_id(
		$record['token_hash'],
		isset( $record['post_id'] ) ? (int) $record['post_id'] : 0,
		isset( $record['server_version'] ) ? (string) $record['server_version'] : ''
	);

	if ( 'minted' === $event ) {
		$record['minted_at'] = $now;
	} elseif ( 'consumed' === $event ) {
		$record['consumed_at'] = $now;
	} elseif ( 'unavailable' === $event ) {
		$record['unavailable_at'] = $now;
	} elseif ( 'expired' === $event ) {
		$record['expired_at'] = $now;
	}

	$event_record = array(
		'event' => $event,
		'at'    => $now,
	);

	foreach ( array( 'rest_route', 'storage_status', 'lifetime_status' ) as $event_field ) {
		if ( array_key_exists( $event_field, $args ) && '' !== (string) $args[ $event_field ] ) {
			$event_record[ $event_field ] = sanitize_text_field( (string) $args[ $event_field ] );
		}
	}

	$events = isset( $record['events'] ) && is_array( $record['events'] ) ? array_values( $record['events'] ) : array();
	$events[] = $event_record;

	if ( count( $events ) > 10 ) {
		$events = array_slice( $events, -10 );
	}

	$record['events']                    = $events;
	$record['event_count']               = isset( $record['event_count'] )
		? max( 0, (int) $record['event_count'] ) + 1
		: count( $events );
	$record['audit_retention_policy']    = 'opaque_review_approval_token_audit_option_retention_v1';
	$record['audit_retention_seconds']   = wp_de_rtc_get_opaque_review_approval_proof_token_audit_retention_seconds();
	$record['audit_cleanup_eligible_at'] = wp_de_rtc_get_opaque_review_approval_proof_token_audit_cleanup_eligible_at(
		$record,
		$record['audit_retention_seconds']
	);

	$recorded = $record_found
		? update_option( $option_name, $record, false )
		: add_option( $option_name, $record, '', 'no' );

	return wp_de_rtc_get_opaque_review_approval_proof_token_audit_summary( $event, (bool) $recorded, $previous_status, true, $record['public_record_id'] );
}

/**
 * Returns public, non-sensitive token audit evidence for REST payloads.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $audit Audit summary.
 * @return array Public audit evidence.
 */
function wp_de_rtc_get_opaque_review_approval_proof_token_audit_public_evidence( $audit ) {
	if ( ! is_array( $audit ) ) {
		$audit = array();
	}

	$evidence = array(
		'storage'  => 'option',
		'status'   => isset( $audit['status'] ) ? sanitize_key( (string) $audit['status'] ) : '',
		'recorded' => ! empty( $audit['recorded'] ),
	);

	if ( array_key_exists( 'previous_status', $audit ) && null !== $audit['previous_status'] ) {
		$evidence['previous_status'] = sanitize_key( (string) $audit['previous_status'] );
	}

	if ( array_key_exists( 'record_found', $audit ) ) {
		$evidence['record_found'] = ! empty( $audit['record_found'] );
	}

	if ( ! empty( $audit['public_record_id'] ) ) {
		$evidence['public_record_id'] = sanitize_text_field( (string) $audit['public_record_id'] );
	}

	return $evidence;
}

/**
 * Returns a token audit summary for use in REST payloads.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string      $event           Lifecycle event.
 * @param bool        $recorded        Whether the audit record was written.
 * @param string|null $previous_status Previous lifecycle status.
 * @param bool        $record_found    Whether an audit record existed or was created.
 * @param string      $public_record_id Public support-safe audit record ID.
 * @return array Public audit summary.
 */
function wp_de_rtc_get_opaque_review_approval_proof_token_audit_summary( $event, $recorded, $previous_status = null, $record_found = false, $public_record_id = '' ) {
	return array(
		'status'           => sanitize_key( (string) $event ),
		'recorded'         => (bool) $recorded,
		'previous_status'  => null === $previous_status ? null : sanitize_key( (string) $previous_status ),
		'record_found'     => (bool) $record_found,
		'public_record_id' => sanitize_text_field( (string) $public_record_id ),
	);
}

/**
 * Deletes retention-expired opaque token audit option records.
 *
 * This cleanup is intentionally narrow: it only deletes valid audit option
 * records after their retention window. It does not delete transients, resolve
 * proof, mutate posts, create revisions, apply recovery, save, or change locks.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $args {
 *     Optional cleanup arguments.
 *
 *     @type int $limit Maximum audit options to scan. Default 50, maximum 200.
 *     @type int $now   Unix timestamp used for eligibility. Default current time.
 * }
 * @return array Cleanup summary with support-safe public record IDs.
 */
function wp_de_rtc_cleanup_opaque_review_approval_proof_token_audit_records( $args = array() ) {
	global $wpdb;

	$args  = is_array( $args ) ? $args : array();
	$limit = array_key_exists( 'limit', $args ) ? absint( $args['limit'] ) : 50;
	$limit = min( $limit, 200 );
	$now   = isset( $args['now'] ) && is_numeric( $args['now'] ) ? (int) $args['now'] : time();

	$summary = array(
		'audit_record_type'          => 'opaque_review_approval_proof_token_audit_record',
		'audit_storage_engine'       => 'option',
		'limit'                      => $limit,
		'scanned'                    => 0,
		'deleted'                    => 0,
		'skipped'                    => 0,
		'deleted_public_record_ids'  => array(),
		'deletes_proof_transients'   => false,
		'resolves_proof'             => false,
		'saves_post'                 => false,
		'mutates_post_content'       => false,
		'creates_revision'           => false,
		'applies_recovery'           => false,
		'changes_locks'              => false,
		'affects_normal_save_paths'  => false,
	);

	if ( 0 === $limit ) {
		return $summary;
	}

	$option_prefix = 'de_rtc_review_approval_token_audit_';
	$option_names  = $wpdb->get_col(
		$wpdb->prepare(
			"SELECT option_name
			FROM $wpdb->options
			WHERE option_name LIKE %s
			ORDER BY option_id ASC
			LIMIT %d",
			$wpdb->esc_like( $option_prefix ) . '%',
			$limit
		)
	);

	foreach ( $option_names as $option_name ) {
		$summary['scanned']++;
		$record = get_option( $option_name, null );

		if (
			! is_array( $record ) ||
			! isset( $record['type'], $record['audit_record_version'] ) ||
			'opaque_review_approval_proof_token_audit_record' !== $record['type'] ||
			1 !== (int) $record['audit_record_version']
		) {
			$summary['skipped']++;
			continue;
		}

		$stored_cleanup_eligible_at   = isset( $record['audit_cleanup_eligible_at'] ) && is_numeric( $record['audit_cleanup_eligible_at'] )
			? (int) $record['audit_cleanup_eligible_at']
			: 0;
		$computed_cleanup_eligible_at = wp_de_rtc_get_opaque_review_approval_proof_token_audit_cleanup_eligible_at( $record );
		$cleanup_eligible_at          = max( $stored_cleanup_eligible_at, $computed_cleanup_eligible_at );

		if ( 0 === $cleanup_eligible_at || $cleanup_eligible_at > $now ) {
			$summary['skipped']++;
			continue;
		}

		if ( delete_option( $option_name ) ) {
			$summary['deleted']++;
			$public_record_id = ! empty( $record['public_record_id'] )
				? sanitize_text_field( (string) $record['public_record_id'] )
				: wp_de_rtc_get_opaque_review_approval_proof_token_audit_public_record_id(
					isset( $record['token_hash'] ) ? $record['token_hash'] : '',
					isset( $record['post_id'] ) ? (int) $record['post_id'] : 0,
					isset( $record['server_version'] ) ? (string) $record['server_version'] : ''
				);

			if ( '' !== $public_record_id ) {
				$summary['deleted_public_record_ids'][] = $public_record_id;
			}
		} else {
			$summary['skipped']++;
		}
	}

	return $summary;
}

/**
 * Returns the WP-Cron hook for opaque review approval proof token audit cleanup.
 *
 * @since 7.1.0
 * @access private
 *
 * @return string WP-Cron hook name.
 */
function wp_de_rtc_get_opaque_review_approval_proof_token_audit_cleanup_cron_hook() {
	return 'wp_de_rtc_opaque_review_approval_proof_token_audit_cleanup';
}

/**
 * Schedules bounded opaque review approval proof token audit cleanup.
 *
 * This helper only schedules a daily WP-Cron event. It does not run cleanup,
 * resolve proof tokens, mutate posts, create revisions, save, or change locks.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $args {
 *     Optional scheduling arguments.
 *
 *     @type int $timestamp First run timestamp. Default one hour from now.
 * }
 * @return array Scheduling summary.
 */
function wp_de_rtc_schedule_opaque_review_approval_proof_token_audit_cleanup( $args = array() ) {
	$args      = is_array( $args ) ? $args : array();
	$hook      = wp_de_rtc_get_opaque_review_approval_proof_token_audit_cleanup_cron_hook();
	$timestamp = isset( $args['timestamp'] ) && is_numeric( $args['timestamp'] )
		? max( time(), (int) $args['timestamp'] )
		: time() + HOUR_IN_SECONDS;
	$scheduled = wp_next_scheduled( $hook );

	$summary = array(
		'cron_hook'                 => $hook,
		'cron_recurrence'           => 'daily',
		'next_scheduled'            => $scheduled ? (int) $scheduled : 0,
		'scheduled'                 => false,
		'already_scheduled'         => (bool) $scheduled,
		'runs_cleanup_in_request'   => false,
		'deletes_proof_transients'  => false,
		'resolves_proof'            => false,
		'saves_post'                => false,
		'mutates_post_content'      => false,
		'creates_revision'          => false,
		'applies_recovery'          => false,
		'changes_locks'             => false,
		'affects_normal_save_paths' => false,
	);

	if ( $scheduled || wp_installing() ) {
		return $summary;
	}

	$summary['scheduled']      = (bool) wp_schedule_event( $timestamp, 'daily', $hook );
	$summary['next_scheduled'] = wp_next_scheduled( $hook );
	$summary['next_scheduled'] = $summary['next_scheduled'] ? (int) $summary['next_scheduled'] : 0;

	return $summary;
}

/**
 * Runs one bounded opaque review approval proof token audit cleanup batch.
 *
 * This cron callback delegates only to the existing retention cleanup helper.
 * It does not resolve proof, delete proof transients, mutate posts, create
 * revisions, save, apply recovery, or change locks.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $args Optional cleanup arguments.
 * @return array Cleanup summary.
 */
function wp_de_rtc_run_opaque_review_approval_proof_token_audit_cleanup( $args = array() ) {
	$summary = wp_de_rtc_cleanup_opaque_review_approval_proof_token_audit_records( is_array( $args ) ? $args : array() );

	$summary['cron_hook']       = wp_de_rtc_get_opaque_review_approval_proof_token_audit_cleanup_cron_hook();
	$summary['cron_recurrence'] = 'daily';
	$summary['cleanup_trigger'] = 'wp_cron';

	return $summary;
}

/**
 * Resolves an opaque review approval proof token envelope to a field proof.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $proof_envelope Opaque proof token envelope.
 * @param int   $post_id        Post ID for error evidence.
 * @return array|WP_Error Field-based proof, or rejection.
 */
function wp_de_rtc_get_review_approval_proof_from_opaque_token_envelope( $proof_envelope, $post_id = 0 ) {
	$token         = wp_de_rtc_get_opaque_review_approval_proof_token_from_envelope( $proof_envelope );
	$token_version = isset( $proof_envelope['token_version'] ) ? absint( $proof_envelope['token_version'] ) : 0;
	$now           = time();

	if ( '' === $token || 1 !== $token_version ) {
		return wp_de_rtc_get_opaque_review_approval_proof_token_error(
			'de_rtc_malformed_sync_payload',
			'malformed_retry_save_review_approval_proof_token',
			$post_id
		);
	}

	if ( isset( $proof_envelope['expires_at'] ) && is_numeric( $proof_envelope['expires_at'] ) && (int) $proof_envelope['expires_at'] <= $now ) {
		$token_audit = wp_de_rtc_record_opaque_review_approval_proof_token_audit_event(
			$token,
			'expired',
			array(
				'post_id'         => $post_id,
				'expires_at'      => (int) $proof_envelope['expires_at'],
				'rest_route'      => 'post_retry_save',
				'lifetime_status' => 'expired',
			)
		);

		return wp_de_rtc_get_opaque_review_approval_proof_token_error(
			'de_rtc_sync_meta_tampered',
			'retry_save_review_approval_proof_token_expired',
			$post_id,
			array(
				'review_approval_proof_token_expires_at'     => (int) $proof_envelope['expires_at'],
				'review_approval_proof_current_time'         => $now,
				'review_approval_proof_lifetime_status'      => 'expired',
				'review_approval_proof_requires_new_review' => true,
				'can_export_local_updates'                  => true,
				'review_approval_proof_token_audit'         => wp_de_rtc_get_opaque_review_approval_proof_token_audit_public_evidence( $token_audit ),
			)
		);
	}

	$record = get_transient( wp_de_rtc_get_opaque_review_approval_proof_token_transient_key( $token ) );

	if ( ! is_array( $record ) ) {
		$token_audit = wp_de_rtc_record_opaque_review_approval_proof_token_audit_event(
			$token,
			'unavailable',
			array(
				'post_id'         => $post_id,
				'rest_route'      => 'post_retry_save',
				'storage_status'  => 'missing_or_evicted',
				'lifetime_status' => 'unavailable',
			)
		);

		return wp_de_rtc_get_opaque_review_approval_proof_token_error(
			'de_rtc_malformed_sync_payload',
			'unknown_retry_save_review_approval_proof_token',
			$post_id,
			array(
				'review_approval_proof_lifetime_status'      => 'unavailable',
				'review_approval_proof_token_storage_status' => 'missing_or_evicted',
				'review_approval_proof_requires_new_review'  => true,
				'can_export_local_updates'                   => true,
				'review_approval_proof_token_audit'          => wp_de_rtc_get_opaque_review_approval_proof_token_audit_public_evidence( $token_audit ),
			)
		);
	}

	$site_scope = wp_de_rtc_get_review_approval_proof_site_scope();

	if (
		! isset( $record['type'], $record['token_version'], $record['field_based_review_approval_proof'] ) ||
		'opaque_review_approval_proof_token_record' !== $record['type'] ||
		1 !== (int) $record['token_version'] ||
		! is_array( $record['field_based_review_approval_proof'] )
	) {
		return wp_de_rtc_get_opaque_review_approval_proof_token_error(
			'de_rtc_malformed_sync_payload',
			'malformed_retry_save_review_approval_proof_token_record',
			$post_id
		);
	}

	if ( ! isset( $record['expires_at'] ) || ! is_numeric( $record['expires_at'] ) || (int) $record['expires_at'] <= $now ) {
		$token_audit = wp_de_rtc_record_opaque_review_approval_proof_token_audit_event(
			$token,
			'expired',
			array(
				'post_id'         => $post_id,
				'expires_at'      => isset( $record['expires_at'] ) ? (int) $record['expires_at'] : null,
				'rest_route'      => 'post_retry_save',
				'lifetime_status' => 'expired',
			)
		);

		return wp_de_rtc_get_opaque_review_approval_proof_token_error(
			'de_rtc_sync_meta_tampered',
			'retry_save_review_approval_proof_token_expired',
			$post_id,
			array(
				'review_approval_proof_token_expires_at'     => isset( $record['expires_at'] ) ? (int) $record['expires_at'] : null,
				'review_approval_proof_current_time'         => $now,
				'review_approval_proof_lifetime_status'      => 'expired',
				'review_approval_proof_requires_new_review' => true,
				'can_export_local_updates'                  => true,
				'review_approval_proof_token_audit'         => wp_de_rtc_get_opaque_review_approval_proof_token_audit_public_evidence( $token_audit ),
			)
		);
	}

	if (
		! isset( $record['site_id'], $record['site_url'] ) ||
		(int) $record['site_id'] !== (int) $site_scope['site_id'] ||
		untrailingslashit( (string) $record['site_url'] ) !== $site_scope['site_url']
	) {
		return wp_de_rtc_get_opaque_review_approval_proof_token_error(
			'de_rtc_sync_meta_tampered',
			'retry_save_review_approval_proof_token_site_scope_mismatch',
			$post_id
		);
	}

	return $record['field_based_review_approval_proof'];
}

/**
 * Returns the transient key for an opaque token envelope, when available.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $proof_envelope Review approval proof or envelope.
 * @return string Transient key, or empty string when the envelope is not an opaque token.
 */
function wp_de_rtc_get_opaque_review_approval_proof_token_transient_key_from_envelope( $proof_envelope ) {
	$token = wp_de_rtc_get_opaque_review_approval_proof_token_from_envelope( $proof_envelope );

	if ( '' === $token ) {
		return '';
	}

	return wp_de_rtc_get_opaque_review_approval_proof_token_transient_key( $token );
}

/**
 * Returns a standard opaque review approval proof token error.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $code    Reason code.
 * @param string $detail  Detail code.
 * @param int    $post_id Post ID for evidence.
 * @param array  $extra   Additional error data.
 * @return WP_Error Error object.
 */
function wp_de_rtc_get_opaque_review_approval_proof_token_error( $code, $detail, $post_id = 0, $extra = array() ) {
	return wp_de_rtc_get_reason_error(
		$code,
		__( 'Distributed Editing rejected the retry save because the review approval proof token is invalid.' ),
		array_merge(
			array(
				'detail'                       => $detail,
				'post_id'                      => (int) $post_id,
				'rest_route'                   => 'post_retry_save',
				'review_approval_proof_format' => 'opaque_review_approval_proof_token',
				'saves_post'                   => false,
				'mutates_post_content'         => false,
				'creates_revision'             => false,
				'claims_saved'                 => false,
			),
			$extra
		)
	);
}

/**
 * Validates hash-only review-approval proof before retry-save persistence.
 *
 * @since 7.1.0
 * @access private
 *
 * @param WP_Post $post Post object.
 * @param array   $args {
 *     Proof consumption arguments.
 *
 *     @type mixed  $review_approval_proof         Review approval proof object.
 *     @type string $client_base_version           Client base version.
 *     @type string $accepted_proof_server_version Accepted proof server version.
 *     @type string $server_version                Current server sync version.
 *     @type int    $pending_change_count          Pending change count.
 *     @type string $proposed_post_content_hash    Hash of proposed content without sync metadata.
 *     @type string $candidate_post_content_hash   Hash of candidate post_content with sync metadata.
 *     @type string $rebased_from_version          Original stale version that was rebased from.
 *     @type bool   $proof_required                Whether a proof is required before persistence.
 * }
 * @return array|WP_Error Proof consumption result, or rejection.
 */
function wp_de_rtc_get_retry_save_review_approval_proof_consumption_result( $post, $args ) {
	$proof_required            = ! empty( $args['proof_required'] );
	$proof_envelope            = isset( $args['review_approval_proof'] ) ? $args['review_approval_proof'] : null;
	$post_id                   = $post ? (int) $post->ID : 0;
	$proof_token               = wp_de_rtc_get_opaque_review_approval_proof_token_from_envelope( $proof_envelope );
	$proof_token_transient_key = wp_de_rtc_get_opaque_review_approval_proof_token_transient_key_from_envelope( $proof_envelope );
	$proof                     = wp_de_rtc_get_accepted_review_approval_proof_from_envelope( $proof_envelope, $post_id );

	if ( is_wp_error( $proof ) ) {
		return $proof;
	}

	if ( null === $proof || '' === $proof ) {
		if ( ! $proof_required ) {
			return array(
				'review_approval_proof_consumed' => false,
				'reviewed_block_item_count'      => 0,
			);
		}

		return new WP_Error(
			'de_rtc_unfiltered_html_would_change_content',
			__( 'Distributed Editing requires unfiltered HTML review before retry save.' )
		);
	}

	$raw_content_param_paths = wp_de_rtc_find_raw_post_content_param_paths( $proof, 'review_approval_proof' );
	$proof_raw_content_flag  = ! empty( $proof['raw_content_included'] ) || ! empty( $proof['exposes_raw_content'] );

	if ( $proof_raw_content_flag || ! empty( $raw_content_param_paths ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because review approval proof included raw content.' ),
			array(
				'detail'                       => 'retry_save_review_approval_raw_content_rejected',
				'post_id'                      => $post_id,
				'rest_route'                   => 'post_retry_save',
				'request_raw_content_included' => true,
				'raw_content_included'         => false,
				'raw_content_param_paths'      => $raw_content_param_paths,
				'saves_post'                   => false,
				'mutates_post_content'         => false,
				'creates_revision'             => false,
				'claims_saved'                 => false,
			)
		);
	}

	$proof_type      = isset( $proof['type'] ) ? sanitize_key( (string) $proof['type'] ) : '';
	$proof_status    = isset( $proof['status'] ) ? sanitize_key( (string) $proof['status'] ) : '';
	$proof_status    = '' !== $proof_status || ! isset( $proof['proof_status'] ) ? $proof_status : sanitize_key( (string) $proof['proof_status'] );
	$reviewer_cap    = isset( $proof['reviewer_capability'] ) ? sanitize_key( (string) $proof['reviewer_capability'] ) : '';
	$proof_saves     = ! empty( $proof['saves_post'] ) && wp_validate_boolean( $proof['saves_post'] );
	$proof_mutates   = ! empty( $proof['mutates_post_content'] ) && wp_validate_boolean( $proof['mutates_post_content'] );
	$proof_revisions = ! empty( $proof['creates_revision'] ) && wp_validate_boolean( $proof['creates_revision'] );
	$proof_claims    = ! empty( $proof['claims_saved'] ) && wp_validate_boolean( $proof['claims_saved'] );
	$proof_post_id   = isset( $proof['post_id'] ) ? absint( $proof['post_id'] ) : 0;
	$proof_post_type = isset( $proof['post_type'] ) ? sanitize_key( (string) $proof['post_type'] ) : '';

	if (
		'unfiltered_html_retry_save_review_approval' !== $proof_type ||
		'approved_by_unfiltered_html_reviewer' !== $proof_status ||
		'unfiltered_html' !== $reviewer_cap ||
		$post_id !== $proof_post_id ||
		$post->post_type !== $proof_post_type ||
		$proof_saves ||
		$proof_mutates ||
		$proof_revisions ||
		$proof_claims
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because review approval proof is contradictory.' ),
			array(
				'detail'               => 'retry_save_review_approval_proof_rejected',
				'post_id'              => $post_id,
				'rest_route'           => 'post_retry_save',
				'proof_post_id'        => $proof_post_id,
				'proof_post_type'      => $proof_post_type,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	if ( ! wp_de_rtc_is_review_approval_proof_signature_valid( $proof ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because review approval proof was not issued by this server.' ),
			array(
				'detail'               => 'retry_save_review_approval_proof_signature_mismatch',
				'post_id'              => $post_id,
				'rest_route'           => 'post_retry_save',
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$proof_scope_error = wp_de_rtc_get_review_approval_proof_time_site_scope_error( $proof, $post_id );

	if ( is_wp_error( $proof_scope_error ) ) {
		return $proof_scope_error;
	}

	$client_base_version            = isset( $args['client_base_version'] ) ? sanitize_text_field( (string) $args['client_base_version'] ) : '';
	$accepted_proof_server_version = isset( $args['accepted_proof_server_version'] ) ? sanitize_text_field( (string) $args['accepted_proof_server_version'] ) : '';
	$server_version                 = isset( $args['server_version'] ) ? sanitize_text_field( (string) $args['server_version'] ) : '';
	$proof_client_base_version      = isset( $proof['client_base_version'] ) ? sanitize_text_field( (string) $proof['client_base_version'] ) : '';
	$proof_accepted_server_version  = isset( $proof['accepted_proof_server_version'] ) ? sanitize_text_field( (string) $proof['accepted_proof_server_version'] ) : '';
	$proof_server_version           = isset( $proof['server_version'] ) ? sanitize_text_field( (string) $proof['server_version'] ) : '';
	$rebased_from_version           = isset( $args['rebased_from_version'] ) ? sanitize_text_field( (string) $args['rebased_from_version'] ) : $client_base_version;
	$proof_rebased_from_version     = isset( $proof['rebased_from_version'] ) ? sanitize_text_field( (string) $proof['rebased_from_version'] ) : $rebased_from_version;
	$pending_change_count           = array_key_exists( 'pending_change_count', $args ) ? max( 0, (int) $args['pending_change_count'] ) : 1;

	if (
		'' === $proof_client_base_version ||
		'' === $proof_accepted_server_version ||
		'' === $proof_server_version ||
		$proof_client_base_version !== $client_base_version ||
		$proof_accepted_server_version !== $accepted_proof_server_version ||
		$proof_server_version !== $server_version ||
		$proof_rebased_from_version !== $rebased_from_version
	) {
		$error = wp_de_rtc_get_stale_base_rejection_error(
			$post,
			array(
				'client_base_version'      => $client_base_version,
				'server_version'           => $server_version,
				'pending_change_count'     => $pending_change_count,
				'remote_change_count'      => 1,
				'can_attempt_local_rebase' => false,
				'rest_route'               => 'post_retry_save_review_approval_consumption_stale_base',
				'saves_post'               => false,
				'mutates_post_content'     => false,
				'creates_revision'         => false,
				'claims_saved'             => false,
			)
		);

		$data = $error->get_error_data( 'stale_base_version_rejected' );

		if ( is_array( $data ) ) {
			$data['review_approval_proof_consumed']                 = false;
			$data['review_approval_proof_lifetime_status']          = 'stale_after_server_version_advanced';
			$data['review_approval_proof_client_base_version']      = $proof_client_base_version;
			$data['review_approval_proof_server_version']           = $proof_server_version;
			$data['review_approval_proof_accepted_server_version']  = $proof_accepted_server_version;
			$data['review_approval_proof_rebased_from_version']     = $proof_rebased_from_version;
			$data['review_approval_proof_current_server_version']   = $server_version;
			$data['review_approval_proof_expected_server_version']  = $accepted_proof_server_version;
			$data['review_approval_proof_stale']                    = true;
			$data['review_approval_proof_requires_new_review']      = true;
			$error->add_data( $data, 'stale_base_version_rejected' );
		}

		return $error;
	}

	$proposed_hash                      = isset( $args['proposed_post_content_hash'] ) ? sanitize_text_field( (string) $args['proposed_post_content_hash'] ) : '';
	$candidate_hash                     = isset( $args['candidate_post_content_hash'] ) ? sanitize_text_field( (string) $args['candidate_post_content_hash'] ) : '';
	$proof_proposed_hash                = wp_de_rtc_get_request_hash_evidence( $proof, 'proposed_post_content_hash' );
	$proof_reviewed_proposed            = wp_de_rtc_get_request_hash_evidence( $proof, 'reviewed_proposed_content_hash' );
	$proof_candidate_hash               = wp_de_rtc_get_request_hash_evidence( $proof, 'candidate_post_content_hash' );
	$proof_reviewed_candidate           = wp_de_rtc_get_request_hash_evidence( $proof, 'reviewed_candidate_content_hash' );
	$missing_hash_fields                = array();
	$proof_candidate_hash_scope         = isset( $proof['candidate_post_content_hash_scope'] ) ? sanitize_key( (string) $proof['candidate_post_content_hash_scope'] ) : '';
	$proof_requires_unfiltered_saver    = ! empty( $proof['requires_unfiltered_html_saver'] ) && wp_validate_boolean( $proof['requires_unfiltered_html_saver'] );
	$proof_reviewer_user_id             = isset( $proof['reviewer_user_id'] ) ? absint( $proof['reviewer_user_id'] ) : 0;
	$proof_low_privileged_saver_user_id = isset( $proof['low_privileged_saver_user_id'] ) ? absint( $proof['low_privileged_saver_user_id'] ) : 0;
	$can_consume_handoff_candidate_hash = current_user_can( 'unfiltered_html' )
		&& $proof_requires_unfiltered_saver
		&& 'low_privileged_saver_candidate' === $proof_candidate_hash_scope;
	$identity_mismatch_fields           = array();

	foreach (
		array(
			'review_approval_proof.proposed_post_content_hash'           => $proof_proposed_hash,
			'review_approval_proof.reviewed_proposed_content_hash'       => $proof_reviewed_proposed,
			'review_approval_proof.candidate_post_content_hash'          => $proof_candidate_hash,
			'review_approval_proof.reviewed_candidate_content_hash'      => $proof_reviewed_candidate,
		) as $field => $hash
	) {
		if ( ! wp_de_rtc_is_sha256_hash( $hash ) ) {
			$missing_hash_fields[] = $field;
		}
	}

	if ( ! empty( $missing_hash_fields ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the retry save because review approval hash evidence is incomplete.' ),
			array(
				'detail'                       => 'missing_retry_save_review_approval_hash_evidence',
				'post_id'                      => $post_id,
				'rest_route'                   => 'post_retry_save',
				'missing_hash_evidence_fields' => $missing_hash_fields,
				'raw_content_included'         => false,
				'saves_post'                   => false,
				'mutates_post_content'         => false,
				'creates_revision'             => false,
				'claims_saved'                 => false,
			)
		);
	}

	$proof_reviewer = $proof_reviewer_user_id ? get_userdata( $proof_reviewer_user_id ) : false;

	if ( ! $proof_reviewer_user_id || ! $proof_reviewer ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because the review approval reviewer account no longer exists.' ),
			array(
				'detail'                              => 'retry_save_review_approval_reviewer_account_deleted',
				'post_id'                             => $post_id,
				'rest_route'                          => 'post_retry_save',
				'reviewer_user_id'                    => $proof_reviewer_user_id,
				'reviewer_account_status'             => 'deleted',
				'reviewer_capability_status'          => 'unavailable',
				'reviewer_required_capability'        => 'unfiltered_html',
				'mismatched_identity_evidence_fields' => array( 'review_approval_proof.reviewer_user_id' ),
				'raw_content_included'                => false,
				'saves_post'                          => false,
				'mutates_post_content'                => false,
				'creates_revision'                    => false,
				'claims_saved'                        => false,
			)
		);
	}

	if ( ! user_can( $proof_reviewer_user_id, 'unfiltered_html' ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because the review approval reviewer no longer has unfiltered HTML capability.' ),
			array(
				'detail'                              => 'retry_save_review_approval_reviewer_capability_missing',
				'post_id'                             => $post_id,
				'rest_route'                          => 'post_retry_save',
				'reviewer_user_id'                    => $proof_reviewer_user_id,
				'reviewer_account_status'             => 'active',
				'reviewer_capability_status'          => 'missing',
				'reviewer_required_capability'        => 'unfiltered_html',
				'mismatched_identity_evidence_fields' => array( 'review_approval_proof.reviewer_user_id', 'review_approval_proof.reviewer_capability' ),
				'raw_content_included'                => false,
				'saves_post'                          => false,
				'mutates_post_content'                => false,
				'creates_revision'                    => false,
				'claims_saved'                        => false,
			)
		);
	}

	if ( ! user_can( $proof_reviewer_user_id, 'edit_post', $post_id ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because the review approval reviewer can no longer edit this post.' ),
			array(
				'detail'                              => 'retry_save_review_approval_reviewer_edit_post_missing',
				'post_id'                             => $post_id,
				'rest_route'                          => 'post_retry_save',
				'reviewer_user_id'                    => $proof_reviewer_user_id,
				'reviewer_account_status'             => 'active',
				'reviewer_capability_status'          => 'missing_edit_post',
				'reviewer_required_capability'        => 'edit_post',
				'mismatched_identity_evidence_fields' => array( 'review_approval_proof.reviewer_user_id', 'review_approval_proof.reviewer_edit_post' ),
				'raw_content_included'                => false,
				'saves_post'                          => false,
				'mutates_post_content'                => false,
				'creates_revision'                    => false,
				'claims_saved'                        => false,
			)
		);
	}

	if ( $proof_requires_unfiltered_saver || 'low_privileged_saver_candidate' === $proof_candidate_hash_scope ) {
		if ( ! $proof_requires_unfiltered_saver || 'low_privileged_saver_candidate' !== $proof_candidate_hash_scope ) {
			$identity_mismatch_fields[] = 'review_approval_proof.candidate_post_content_hash_scope';
		}

		if ( ! $proof_low_privileged_saver_user_id ) {
			$identity_mismatch_fields[] = 'review_approval_proof.low_privileged_saver_user_id';
		}
	}

	if ( ! empty( $identity_mismatch_fields ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because review approval identity evidence does not match.' ),
			array(
				'detail'                              => 'retry_save_review_approval_identity_evidence_mismatch',
				'post_id'                             => $post_id,
				'rest_route'                          => 'post_retry_save',
				'mismatched_identity_evidence_fields' => $identity_mismatch_fields,
				'raw_content_included'                => false,
				'saves_post'                          => false,
				'mutates_post_content'                => false,
				'creates_revision'                    => false,
				'claims_saved'                        => false,
			)
		);
	}

	$mismatched_fields = array();

	if ( ! hash_equals( $proposed_hash, $proof_proposed_hash ) ) {
		$mismatched_fields[] = 'review_approval_proof.proposed_post_content_hash';
	}

	if ( ! hash_equals( $proposed_hash, $proof_reviewed_proposed ) ) {
		$mismatched_fields[] = 'review_approval_proof.reviewed_proposed_content_hash';
	}

	if ( ! hash_equals( $candidate_hash, $proof_candidate_hash ) && ! $can_consume_handoff_candidate_hash ) {
		$mismatched_fields[] = 'review_approval_proof.candidate_post_content_hash';
	}

	if ( $can_consume_handoff_candidate_hash ) {
		$handoff_candidate_hash = wp_de_rtc_get_retry_save_candidate_post_content_hash_for_user(
			$post,
			array(
				'user_id'                       => $proof_low_privileged_saver_user_id,
				'server_version'                => $server_version,
				'client_base_version'           => $client_base_version,
				'accepted_proof_server_version' => $accepted_proof_server_version,
				'rebased_from_version'          => $rebased_from_version,
				'pending_change_count'          => $pending_change_count,
				'proposed_post_content_hash'    => $proposed_hash,
				'proposed_post_content'         => isset( $args['proposed_post_content'] ) ? (string) $args['proposed_post_content'] : '',
			)
		);

		if ( is_wp_error( $handoff_candidate_hash ) ) {
			return $handoff_candidate_hash;
		}

		if ( ! hash_equals( $handoff_candidate_hash, $proof_candidate_hash ) ) {
			$mismatched_fields[] = 'review_approval_proof.candidate_post_content_hash';
		}
	}

	if ( ! hash_equals( $proof_candidate_hash, $proof_reviewed_candidate ) ) {
		$mismatched_fields[] = 'review_approval_proof.reviewed_candidate_content_hash';
	} elseif ( ! hash_equals( $candidate_hash, $proof_reviewed_candidate ) && ! $can_consume_handoff_candidate_hash ) {
		$mismatched_fields[] = 'review_approval_proof.reviewed_candidate_content_hash';
	}

	if ( ! empty( $mismatched_fields ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because review approval hash evidence does not match.' ),
			array(
				'detail'                          => 'retry_save_review_approval_hash_evidence_mismatch',
				'post_id'                         => $post_id,
				'rest_route'                      => 'post_retry_save',
				'mismatched_hash_evidence_fields' => $mismatched_fields,
				'raw_content_included'            => false,
				'saves_post'                      => false,
				'mutates_post_content'            => false,
				'creates_revision'                => false,
				'claims_saved'                    => false,
			)
		);
	}

	$reviewed_block_items = wp_de_rtc_get_normalized_review_approval_block_items(
		$post,
		array(
			'reviewed_block_items' => isset( $proof['reviewed_block_items'] ) ? $proof['reviewed_block_items'] : array(),
		)
	);

	if ( is_wp_error( $reviewed_block_items ) ) {
		$code = $reviewed_block_items->get_error_code();
		$data = $reviewed_block_items->get_error_data( $code );

		if ( is_array( $data ) ) {
			$data['rest_route'] = 'post_retry_save';
			$reviewed_block_items->add_data( $data, $code );
		}

		return $reviewed_block_items;
	}

	$requires_unfiltered_html_saver = ! current_user_can( 'unfiltered_html' );
	$accepted_review_approval_proof = array(
		'type'                              => 'unfiltered_html_retry_save_review_approval',
		'status'                            => 'approved_by_unfiltered_html_reviewer',
		'post_id'                           => $post_id,
		'post_type'                         => $post->post_type,
		'reviewer_user_id'                  => $proof_reviewer_user_id,
		'reviewer_capability'               => 'unfiltered_html',
		'review_scope'                      => 'collaborative_post_content',
		'review_status'                     => 'approved_by_unfiltered_html_reviewer',
		'approval_status'                   => 'approved_for_retry_save',
		'review_action'                     => 'request_unfiltered_html_reviewer',
		'approval_action'                   => $requires_unfiltered_html_saver ? 'retry_save_with_unfiltered_html_saver' : 'retry_save_with_reviewer_approval',
		'review_required_capability'        => 'unfiltered_html',
		'client_base_version'               => $client_base_version,
		'accepted_proof_server_version'     => $accepted_proof_server_version,
		'server_version'                    => $server_version,
		'rebased_from_version'              => $rebased_from_version,
		'proposed_post_content_hash'        => $proof_proposed_hash,
		'reviewed_proposed_content_hash'    => $proof_reviewed_proposed,
		'candidate_post_content_hash'       => $proof_candidate_hash,
		'reviewed_candidate_content_hash'   => $proof_reviewed_candidate,
		'candidate_post_content_hash_scope' => $requires_unfiltered_html_saver ? 'low_privileged_saver_candidate' : 'current_saver_candidate',
		'requires_unfiltered_html_saver'    => $requires_unfiltered_html_saver,
		'low_privileged_saver_user_id'      => $requires_unfiltered_html_saver ? get_current_user_id() : null,
		'reviewed_block_items'              => $reviewed_block_items,
		'reviewed_block_item_count'         => count( $reviewed_block_items ),
		'block_review_status'               => ! empty( $reviewed_block_items ) ? 'approved_for_retry_save' : null,
		'raw_content_included'              => false,
		'saves_post'                        => false,
		'mutates_post_content'              => false,
		'creates_revision'                  => false,
		'claims_saved'                      => false,
	);
	$accepted_review_approval_proof = wp_de_rtc_add_review_approval_proof_signature( $accepted_review_approval_proof );

	return array(
		'review_approval_proof_consumed'             => true,
		'accepted_review_approval_proof'             => $accepted_review_approval_proof,
		'reviewed_block_items'                       => $reviewed_block_items,
		'reviewed_block_item_count'                  => count( $reviewed_block_items ),
		'block_review_status'                        => ! empty( $reviewed_block_items ) ? 'approved_for_retry_save' : null,
		'_review_approval_proof_token'               => $proof_token,
		'_review_approval_proof_token_transient_key' => $proof_token_transient_key,
	);
}

/**
 * Adds a server signature to a review approval proof.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $proof Review approval proof.
 * @return array Review approval proof with a server signature.
 */
function wp_de_rtc_add_review_approval_proof_signature( $proof ) {
	$proof = wp_de_rtc_add_review_approval_proof_time_site_scope( $proof );
	$proof['proof_signature'] = wp_de_rtc_sign_review_approval_proof( $proof );

	return $proof;
}

/**
 * Adds server-issued time and site scope to a review approval proof.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $proof Review approval proof.
 * @return array Review approval proof with time and site scope.
 */
function wp_de_rtc_add_review_approval_proof_time_site_scope( $proof ) {
	if ( ! is_array( $proof ) ) {
		return $proof;
	}

	$site_scope = wp_de_rtc_get_review_approval_proof_site_scope();
	$issued_at  = isset( $proof['issued_at'] ) && is_numeric( $proof['issued_at'] ) ? (int) $proof['issued_at'] : time();

	$proof['issued_at']  = $issued_at;
	$proof['expires_at'] = isset( $proof['expires_at'] ) && is_numeric( $proof['expires_at'] )
		? (int) $proof['expires_at']
		: $issued_at + wp_de_rtc_get_review_approval_proof_lifetime_seconds();
	$proof['site_id']    = isset( $proof['site_id'] ) && '' !== (string) $proof['site_id']
		? absint( $proof['site_id'] )
		: $site_scope['site_id'];
	$proof['site_url']   = isset( $proof['site_url'] ) && '' !== (string) $proof['site_url']
		? untrailingslashit( (string) $proof['site_url'] )
		: $site_scope['site_url'];

	return $proof;
}

/**
 * Returns the current site scope used by review approval proofs.
 *
 * @since 7.1.0
 * @access private
 *
 * @return array Site scope evidence.
 */
function wp_de_rtc_get_review_approval_proof_site_scope() {
	return array(
		'site_id'  => (int) get_current_blog_id(),
		'site_url' => untrailingslashit( get_site_url() ),
	);
}

/**
 * Returns the lifetime for server-issued review approval proofs.
 *
 * @since 7.1.0
 * @access private
 *
 * @return int Proof lifetime in seconds.
 */
function wp_de_rtc_get_review_approval_proof_lifetime_seconds() {
	return 15 * MINUTE_IN_SECONDS;
}

/**
 * Returns the tolerated clock skew for server-issued review approval proofs.
 *
 * @since 7.1.0
 * @access private
 *
 * @return int Clock skew window in seconds.
 */
function wp_de_rtc_get_review_approval_proof_clock_skew_seconds() {
	return 5 * MINUTE_IN_SECONDS;
}

/**
 * Returns a stable server signature for a review approval proof.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $proof Review approval proof.
 * @return string Proof signature, or an empty string when the proof cannot be encoded.
 */
function wp_de_rtc_sign_review_approval_proof( $proof ) {
	if ( ! is_array( $proof ) ) {
		return '';
	}

	unset( $proof['proof_signature'] );

	$payload = wp_json_encode( wp_de_rtc_sort_review_approval_proof_value( $proof ) );

	if ( ! is_string( $payload ) ) {
		return '';
	}

	return hash_hmac( 'sha256', $payload, wp_salt( 'de_rtc_review_approval_proof' ) );
}

/**
 * Returns whether a review approval proof signature is valid.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $proof Review approval proof.
 * @return bool Whether the server signature is present and valid.
 */
function wp_de_rtc_is_review_approval_proof_signature_valid( $proof ) {
	if ( ! is_array( $proof ) || ! isset( $proof['proof_signature'] ) || ! wp_de_rtc_is_sha256_hash( $proof['proof_signature'] ) ) {
		return false;
	}

	return hash_equals( wp_de_rtc_sign_review_approval_proof( $proof ), $proof['proof_signature'] );
}

/**
 * Returns an error when a signed review approval proof has invalid time or site scope.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $proof   Signed review approval proof.
 * @param int   $post_id Post ID for error evidence.
 * @return WP_Error|null Scope error, or null when scope is valid.
 */
function wp_de_rtc_get_review_approval_proof_time_site_scope_error( $proof, $post_id ) {
	$issued_at  = isset( $proof['issued_at'] ) && is_numeric( $proof['issued_at'] ) ? (int) $proof['issued_at'] : null;
	$expires_at = isset( $proof['expires_at'] ) && is_numeric( $proof['expires_at'] ) ? (int) $proof['expires_at'] : null;
	$now        = time();

	if ( null === $issued_at || null === $expires_at || $issued_at <= 0 || $expires_at <= $issued_at ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because review approval proof time scope is invalid.' ),
			array(
				'detail'                                => 'retry_save_review_approval_proof_time_scope_invalid',
				'post_id'                               => $post_id,
				'rest_route'                            => 'post_retry_save',
				'review_approval_proof_consumed'        => false,
				'review_approval_proof_issued_at'       => $issued_at,
				'review_approval_proof_expires_at'      => $expires_at,
				'review_approval_proof_current_time'    => $now,
				'review_approval_proof_lifetime_status' => 'invalid_time_scope',
				'raw_content_included'                  => false,
				'saves_post'                            => false,
				'mutates_post_content'                  => false,
				'creates_revision'                      => false,
				'claims_saved'                          => false,
			)
		);
	}

	if ( $expires_at <= $now ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because review approval proof expired.' ),
			array(
				'detail'                                => 'retry_save_review_approval_proof_expired',
				'post_id'                               => $post_id,
				'rest_route'                            => 'post_retry_save',
				'review_approval_proof_consumed'        => false,
				'review_approval_proof_issued_at'       => $issued_at,
				'review_approval_proof_expires_at'      => $expires_at,
				'review_approval_proof_current_time'    => $now,
				'review_approval_proof_lifetime_status' => 'expired',
				'raw_content_included'                  => false,
				'saves_post'                            => false,
				'mutates_post_content'                  => false,
				'creates_revision'                      => false,
				'claims_saved'                          => false,
			)
		);
	}

	$clock_skew_seconds = wp_de_rtc_get_review_approval_proof_clock_skew_seconds();

	if ( $issued_at > $now + $clock_skew_seconds ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because review approval proof was issued in the future.' ),
			array(
				'detail'                                   => 'retry_save_review_approval_proof_future_issued',
				'post_id'                                  => $post_id,
				'rest_route'                               => 'post_retry_save',
				'review_approval_proof_consumed'           => false,
				'review_approval_proof_issued_at'          => $issued_at,
				'review_approval_proof_expires_at'         => $expires_at,
				'review_approval_proof_current_time'       => $now,
				'review_approval_proof_clock_skew_seconds' => $clock_skew_seconds,
				'review_approval_proof_lifetime_status'    => 'future_issued',
				'raw_content_included'                     => false,
				'saves_post'                               => false,
				'mutates_post_content'                     => false,
				'creates_revision'                         => false,
				'claims_saved'                             => false,
			)
		);
	}

	$site_scope     = wp_de_rtc_get_review_approval_proof_site_scope();
	$proof_site_id  = isset( $proof['site_id'] ) ? absint( $proof['site_id'] ) : 0;
	$proof_site_url = isset( $proof['site_url'] ) ? untrailingslashit( (string) $proof['site_url'] ) : '';

	if ( $proof_site_id !== $site_scope['site_id'] || $proof_site_url !== $site_scope['site_url'] ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because review approval proof came from a different site.' ),
			array(
				'detail'                         => 'retry_save_review_approval_site_scope_mismatch',
				'post_id'                        => $post_id,
				'rest_route'                     => 'post_retry_save',
				'review_approval_proof_consumed' => false,
				'review_approval_proof_site_id'  => $proof_site_id,
				'review_approval_proof_site_url' => $proof_site_url,
				'expected_site_id'               => $site_scope['site_id'],
				'expected_site_url'              => $site_scope['site_url'],
				'raw_content_included'           => false,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
			)
		);
	}

	return null;
}

/**
 * Sorts a review approval proof value before signing.
 *
 * Associative array keys are sorted recursively. Numeric lists preserve order.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $value Proof value.
 * @return mixed Sorted proof value.
 */
function wp_de_rtc_sort_review_approval_proof_value( $value ) {
	if ( is_object( $value ) ) {
		$value = get_object_vars( $value );
	}

	if ( ! is_array( $value ) ) {
		return $value;
	}

	foreach ( $value as $key => $nested_value ) {
		$value[ $key ] = wp_de_rtc_sort_review_approval_proof_value( $nested_value );
	}

	if ( array_keys( $value ) !== range( 0, count( $value ) - 1 ) ) {
		ksort( $value );
	}

	return $value;
}

/**
 * Returns the retry-save candidate content hash for a specific saver identity.
 *
 * @since 7.1.0
 * @access private
 *
 * @param WP_Post $post Post object.
 * @param array   $args Candidate construction arguments.
 * @return string|WP_Error Candidate post-content hash, or an error.
 */
function wp_de_rtc_get_retry_save_candidate_post_content_hash_for_user( $post, $args ) {
	$user_id                       = isset( $args['user_id'] ) ? absint( $args['user_id'] ) : 0;
	$server_version                = isset( $args['server_version'] ) ? sanitize_text_field( (string) $args['server_version'] ) : '';
	$client_base_version           = isset( $args['client_base_version'] ) ? sanitize_text_field( (string) $args['client_base_version'] ) : '';
	$accepted_proof_server_version = isset( $args['accepted_proof_server_version'] ) ? sanitize_text_field( (string) $args['accepted_proof_server_version'] ) : '';
	$rebased_from_version          = isset( $args['rebased_from_version'] ) ? sanitize_text_field( (string) $args['rebased_from_version'] ) : $client_base_version;
	$pending_change_count          = array_key_exists( 'pending_change_count', $args ) ? max( 0, (int) $args['pending_change_count'] ) : 1;
	$proposed_post_content_hash    = isset( $args['proposed_post_content_hash'] ) ? sanitize_text_field( (string) $args['proposed_post_content_hash'] ) : '';
	$proposed_post_content         = isset( $args['proposed_post_content'] ) ? (string) $args['proposed_post_content'] : '';
	$current                       = wp_de_rtc_parse_post_content_sync_meta( $post->post_content );
	$actor_hash                    = wp_de_rtc_get_presence_actor_hash( $user_id );
	$attribution_key               = '' !== $actor_hash ? 'user:' . substr( $actor_hash, 0, 24 ) : 'server:unknown';

	if ( ! $user_id || ! is_array( $current ) || ! isset( $current['sync_meta'] ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because review approval identity evidence does not match.' ),
			array(
				'detail'               => 'retry_save_review_approval_identity_evidence_mismatch',
				'post_id'              => (int) $post->ID,
				'rest_route'           => 'post_retry_save',
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$next_sync_meta = $current['sync_meta'];

	$next_sync_meta['version']            = wp_de_rtc_get_next_sync_meta_version( $server_version, $proposed_post_content_hash );
	$next_sync_meta['previous_version']   = $server_version;
	$next_sync_meta['last_server_update'] = array(
		'type'                         => 'retry_save',
		'user_id'                      => $user_id,
		'session_label'                => wp_de_rtc_get_history_author_display_name( $user_id ),
		'attribution_key'              => $attribution_key,
		'client_base_version'          => $client_base_version,
		'accepted_proof_server_version' => $accepted_proof_server_version,
		'rebased_from_version'         => $rebased_from_version,
		'pending_change_count'         => $pending_change_count,
		'proposed_post_content_hash'   => $proposed_post_content_hash,
	);

	$candidate_post_content = wp_de_rtc_add_sync_meta_to_post_content(
		$proposed_post_content,
		$current['sync_meta_format'],
		$next_sync_meta,
		$current['sync_meta_position']
	);

	if ( is_wp_error( $candidate_post_content ) ) {
		return $candidate_post_content;
	}

	return wp_de_rtc_hash_content( $candidate_post_content );
}

/**
 * Returns a proof-only retry-submit acceptance result.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post Post ID or object.
 * @param array       $args {
 *     Retry-submit proof arguments.
 *
 *     @type mixed $client_base_version        Client base version after local rebase.
 *     @type mixed $rebased_from_version       Original stale version that was rebased from.
 *     @type mixed $pending_change_count       Pending local change count. Default 1.
 *     @type mixed $proposed_post_content_hash Hash of the proposed post content.
 * }
 * @return array|WP_Error Retry-submit acceptance result, or stale-base rejection.
 */
function wp_de_rtc_get_retry_submit_acceptance_result( $post, $args = array() ) {
	$post = get_post( $post );

	if ( ! $post ) {
		return new WP_Error(
			'rest_post_invalid_id',
			__( 'Invalid post ID.' ),
			array( 'status' => 404 )
		);
	}

	$client_base_version        = isset( $args['client_base_version'] ) ? sanitize_text_field( (string) $args['client_base_version'] ) : '';
	$current                    = wp_de_rtc_parse_post_content_sync_meta( $post->post_content );
	$pending_change_count       = array_key_exists( 'pending_change_count', $args ) ? max( 0, (int) $args['pending_change_count'] ) : 1;
	$rebased_from_version       = isset( $args['rebased_from_version'] ) ? sanitize_text_field( (string) $args['rebased_from_version'] ) : null;
	$proposed_post_content_hash = isset( $args['proposed_post_content_hash'] ) ? sanitize_text_field( (string) $args['proposed_post_content_hash'] ) : null;

	if ( is_wp_error( $current ) ) {
		return $current;
	}

	$current_external_repair = wp_de_rtc_get_repaired_automerge_current_post_snapshot(
		$post,
		$current,
		array(
			'allow_empty_import' => true,
		)
	);

	if ( is_wp_error( $current_external_repair ) ) {
		return $current_external_repair;
	}

	if ( is_array( $current_external_repair ) ) {
		/*
		 * Retry-submit is still proof-only. This read-only repair keeps its
		 * version check aligned with the snapshot response and the guarded
		 * retry-save write boundary, so a user can save after WordPress rebuilds
		 * missing Automerge metadata from the current body.
		 */
		$current = $current_external_repair;
	}

	$server_version = (
		is_array( $current ) &&
		isset( $current['sync_meta'] ) &&
		is_array( $current['sync_meta'] ) &&
		array_key_exists( 'version', $current['sync_meta'] )
	)
		? (string) $current['sync_meta']['version']
		: null;

	if ( '' === $client_base_version || null === $server_version || $client_base_version !== $server_version ) {
		return wp_de_rtc_get_stale_base_rejection_error(
			$post,
			array(
				'client_base_version'      => $client_base_version,
				'server_version'           => $server_version,
				'pending_change_count'     => $pending_change_count,
				'remote_change_count'      => 1,
				'can_attempt_local_rebase' => false,
				'rest_route'               => 'post_retry_submit_stale_base',
			)
		);
	}

	return array(
		'result'                              => 'retry_submit_accepted_for_future_save',
		'retry_submit_accepted'               => true,
		'rest_route'                          => 'post_retry_submit',
		'post_id'                             => (int) $post->ID,
		'client_base_version'                 => $client_base_version,
		'server_version'                      => $server_version,
		'rebased_from_version'                => $rebased_from_version,
		'pending_change_count'                => $pending_change_count,
		'proposed_post_content_hash'          => $proposed_post_content_hash,
		'requires_server_state_refetch'       => false,
		'requires_manual_conflict_resolution' => false,
		'can_export_local_updates'            => $pending_change_count > 0,
		'save_path_required'                  => true,
		'saves_post'                          => false,
		'mutates_post_content'                => false,
		'creates_revision'                    => false,
		'claims_saved'                        => false,
		'permission_contract'                 => wp_de_rtc_get_rest_recovery_permission_contract( $post ),
	);
}

/**
 * Returns an accepted no-write response for an already-applied retry save.
 *
 * Duplicate visible Save submissions may replay the same accepted proof and
 * proposed content after the first guarded write has already advanced sync
 * metadata. This guard recognizes that persisted state and stops before a
 * second `wp_update_post()` call.
 *
 * @since 7.1.0
 *
 * @param WP_Post $post    Post object.
 * @param array   $current Parsed current post content and sync metadata.
 * @param array   $args {
 *     Duplicate retry-save arguments.
 *
 *     @type mixed      $client_base_version                     Client base version from the repeated request.
 *     @type mixed      $accepted_proof_server_version           Accepted proof server version from the repeated request.
 *     @type mixed      $server_version                          Current server sync version.
 *     @type mixed      $rebased_from_version                    Original stale version, when present.
 *     @type int        $pending_change_count                    Pending local change count.
 *     @type string     $proposed_post_content_hash              Hash of proposed stripped post content.
 *     @type array|null $block_identity_request_proof_validation Validated block identity proof summary, when present.
 * }
 * @return array|null No-write retry-save response, or null when the request is not a duplicate.
 */
function wp_de_rtc_get_duplicate_retry_save_no_write_result( $post, $current, $args ) {
	if (
		! is_array( $current ) ||
		! isset( $current['sync_meta'] ) ||
		! is_array( $current['sync_meta'] ) ||
		! isset( $current['content'] ) ||
		! is_string( $current['content'] )
	) {
		return null;
	}

	$last_server_update = isset( $current['sync_meta']['last_server_update'] ) && is_array( $current['sync_meta']['last_server_update'] ) ? $current['sync_meta']['last_server_update'] : array();
	$last_update_type   = isset( $last_server_update['type'] ) ? sanitize_key( (string) $last_server_update['type'] ) : '';

	if ( ! in_array( $last_update_type, array( 'retry_save', 'retry_save_server_merge', 'retry_save_partial_safe_merge' ), true ) ) {
		return null;
	}

	$client_base_version            = isset( $args['client_base_version'] ) ? sanitize_text_field( (string) $args['client_base_version'] ) : '';
	$accepted_proof_server_version = isset( $args['accepted_proof_server_version'] ) ? sanitize_text_field( (string) $args['accepted_proof_server_version'] ) : '';
	$proposed_post_content_hash     = isset( $args['proposed_post_content_hash'] ) ? sanitize_text_field( (string) $args['proposed_post_content_hash'] ) : '';
	$last_client_base_version       = isset( $last_server_update['client_base_version'] ) ? sanitize_text_field( (string) $last_server_update['client_base_version'] ) : '';
	$last_accepted_proof_version    = isset( $last_server_update['accepted_proof_server_version'] ) ? sanitize_text_field( (string) $last_server_update['accepted_proof_server_version'] ) : '';
	$last_proposed_content_hash     = isset( $last_server_update['proposed_post_content_hash'] ) ? sanitize_text_field( (string) $last_server_update['proposed_post_content_hash'] ) : '';

	if (
		'' === $client_base_version ||
		'' === $accepted_proof_server_version ||
		'' === $proposed_post_content_hash ||
		'' === $last_client_base_version ||
		'' === $last_accepted_proof_version ||
		'' === $last_proposed_content_hash ||
		! hash_equals( $last_client_base_version, $client_base_version ) ||
		! hash_equals( $last_accepted_proof_version, $accepted_proof_server_version ) ||
		! hash_equals( $last_proposed_content_hash, $proposed_post_content_hash )
	) {
		return null;
	}

	$current_stripped_post_content_hash     = wp_de_rtc_hash_content( $current['content'] );
	$last_saved_stripped_post_content_hash = isset( $last_server_update['saved_stripped_post_content_hash'] ) ? sanitize_text_field( (string) $last_server_update['saved_stripped_post_content_hash'] ) : '';
	$current_matches_applied_retry_save    = '' !== $last_saved_stripped_post_content_hash
		? hash_equals( $last_saved_stripped_post_content_hash, $current_stripped_post_content_hash )
		: hash_equals( $proposed_post_content_hash, $current_stripped_post_content_hash );

	if ( ! $current_matches_applied_retry_save ) {
		return null;
	}

	$revision_ids                       = wp_de_rtc_get_post_revision_ids( $post->ID );
	$block_identity_proof_validation    = isset( $args['block_identity_request_proof_validation'] ) ? $args['block_identity_request_proof_validation'] : null;
	$partial_safe_merge_applied         = 'retry_save_partial_safe_merge' === $last_update_type;
	$server_merge_applied               = 'retry_save_server_merge' === $last_update_type;
	$server_merge                       = isset( $last_server_update['server_merge'] ) && is_array( $last_server_update['server_merge'] ) ? $last_server_update['server_merge'] : null;
	$server_version                     = isset( $args['server_version'] ) ? sanitize_text_field( (string) $args['server_version'] ) : '';
	$previous_server_version            = isset( $current['sync_meta']['previous_version'] ) ? sanitize_text_field( (string) $current['sync_meta']['previous_version'] ) : null;
	$rebased_from_version               = isset( $args['rebased_from_version'] ) ? $args['rebased_from_version'] : null;
	$partial_safe_merge                 = isset( $last_server_update['partial_safe_merge'] ) && is_array( $last_server_update['partial_safe_merge'] ) ? $last_server_update['partial_safe_merge'] : array();
	$partial_safe_review_item_count     = isset( $partial_safe_merge['review_item_count'] ) ? max( 0, (int) $partial_safe_merge['review_item_count'] ) : 0;
	$pending_change_count               = $partial_safe_merge_applied && $partial_safe_review_item_count > 0 ? $partial_safe_review_item_count : ( isset( $args['pending_change_count'] ) ? max( 0, (int) $args['pending_change_count'] ) : 1 );
	$block_identity_request_proof_valid = is_array( $block_identity_proof_validation );

	return array(
		'mode'                                      => 'retry_save',
		'result'                                    => $partial_safe_merge_applied ? 'retry_save_partial_safe_merge' : ( $server_merge_applied ? 'retry_save_server_merged' : 'retry_save_applied' ),
		'retry_save_accepted'                       => true,
		'retry_save_duplicate'                      => true,
		'idempotent_no_write'                       => true,
		'already_persisted'                         => true,
		'remaining_review_required'                 => $partial_safe_merge_applied,
		'rest_route'                                => 'post_retry_save',
		'post_id'                                   => (int) $post->ID,
		'updated_post_id'                           => (int) $post->ID,
		'content'                                   => array(
			'raw' => $post->post_content,
		),
		'client_base_version'                       => $client_base_version,
		'accepted_proof_server_version'             => $accepted_proof_server_version,
		'previous_server_version'                   => $previous_server_version,
		'server_version'                            => $server_version,
		'rebased_from_version'                      => $rebased_from_version,
		'pending_change_count'                      => $pending_change_count,
		'proposed_post_content_hash'                => $proposed_post_content_hash,
		'saved_stripped_post_content_hash'          => $current_stripped_post_content_hash,
		'saved_post_content_hash'                   => wp_de_rtc_hash_content( $post->post_content ),
		'partial_safe_merge_applied'                => $partial_safe_merge_applied,
		'partial_safe_merge_persisted'              => false,
		'partial_safe_merge_no_write'               => $partial_safe_merge_applied,
		'partial_safe_merge_status'                 => $partial_safe_merge_applied ? 'safe_subset_already_current' : null,
		'partial_safe_merge_review_item_count'      => $partial_safe_review_item_count,
		'partial_safe_merge_unsafe_block_count'     => $partial_safe_review_item_count,
		'server_merge_applied'                      => $server_merge_applied,
		'server_merge'                              => $server_merge,
		'block_identity_request_proof_validated'    => $block_identity_request_proof_valid,
		'block_identity_request_proof'              => $block_identity_request_proof_valid ? array(
			'status'               => $block_identity_proof_validation['status'],
			'proposed_block_count' => $block_identity_proof_validation['proposed_block_count'],
			'retained_block_count' => $block_identity_proof_validation['retained_block_count'],
			'inserted_block_count' => $block_identity_proof_validation['inserted_block_count'],
			'deleted_block_count'  => $block_identity_proof_validation['deleted_block_count'],
			'moved_block_count'    => $block_identity_proof_validation['moved_block_count'],
			'content_free'         => true,
			'saves_post'           => false,
			'mutates_post_content' => false,
			'creates_revision'     => false,
			'changes_post_lock'    => false,
			'claims_saved'         => false,
		) : null,
		'review_approval_proof_consumed'            => false,
		'review_approval_proof_token_invalidated'   => false,
		'review_approval_proof_token_audit'         => array(),
		'reviewed_block_item_count'                 => 0,
		'fresh_review_decision_consumed'            => false,
		'fresh_review_decision_consumption_recorded' => false,
		'fresh_review_request_record_id'            => null,
		'fresh_review_request_record'               => null,
		'requires_server_state_refetch'             => false,
		'requires_manual_conflict_resolution'       => $partial_safe_merge_applied,
		'can_export_local_updates'                  => false,
		'save_path_required'                        => false,
		'saves_post'                                => false,
		'mutates_post_content'                      => false,
		'creates_revision'                          => false,
		'claims_saved'                              => ! $partial_safe_merge_applied,
		'reason_code'                               => $partial_safe_merge_applied ? 'de_rtc_unfiltered_html_would_change_content' : null,
		'review_status'                             => $partial_safe_merge_applied ? 'requires_reviewer_escalation' : null,
		'review_action'                             => $partial_safe_merge_applied ? 'request_unfiltered_html_reviewer' : null,
		'review_required_capability'                => $partial_safe_merge_applied ? 'unfiltered_html' : null,
		'pre_publish_review_required'               => $partial_safe_merge_applied,
		'safe_server_content_included'              => $partial_safe_merge_applied,
		'unsafe_raw_content_included'               => false,
		'revision_ids_before_save'                  => $revision_ids,
		'revision_ids_after_save'                   => $revision_ids,
		'created_revision_ids'                      => array(),
		'revision_created'                          => false,
		'permission_contract'                       => wp_de_rtc_get_rest_recovery_permission_contract( $post ),
	);
}

/**
 * Ensures the current server sync-meta version is recoverable as a revision.
 *
 * Stale retry-save merges need the accepted-base body. Normal WordPress
 * revision timing is not a sufficient contract for DE-RTC because the next
 * editor may submit immediately after a guarded save advances the sync
 * version. This helper records the pre-update post when no revision for the
 * current sync-meta version exists yet.
 *
 * @since 7.1.0
 * @access private
 *
 * @param WP_Post $post           Post about to be updated.
 * @param string  $server_version Current sync-meta version.
 * @return int|null|WP_Error Created revision ID, null when no write was needed, or an error.
 */
function wp_de_rtc_ensure_current_sync_meta_revision_before_retry_save( $post, $server_version ) {
	$post           = get_post( $post );
	$server_version = sanitize_text_field( (string) $server_version );

	if ( ! $post || '' === $server_version ) {
		return null;
	}

	$existing_revision = wp_de_rtc_find_revision_with_sync_meta_version( $post, $server_version );

	if ( is_wp_error( $existing_revision ) ) {
		return $existing_revision;
	}

	if ( ! empty( $existing_revision['found'] ) ) {
		return null;
	}

	$revision_id = wp_de_rtc_put_retry_save_revision( $post );

	if ( is_wp_error( $revision_id ) ) {
		return $revision_id;
	}

	return $revision_id ? (int) $revision_id : null;
}

/**
 * Suspends WordPress' default post-update revision hook for one DE-RTC save.
 *
 * @since 7.1.0
 * @access private
 *
 * @return array Hook priorities for default revision hooks that were present.
 */
function wp_de_rtc_suspend_retry_save_core_revision_hook() {
	$hooks = array(
		'wp_after_insert_post' => has_action( 'wp_after_insert_post', 'wp_save_post_revision_on_insert' ),
		'post_updated'         => has_action( 'post_updated', 'wp_save_post_revision' ),
	);

	if ( false !== $hooks['wp_after_insert_post'] ) {
		remove_action( 'wp_after_insert_post', 'wp_save_post_revision_on_insert', $hooks['wp_after_insert_post'] );
	}

	if ( false !== $hooks['post_updated'] ) {
		remove_action( 'post_updated', 'wp_save_post_revision', $hooks['post_updated'] );
	}

	return $hooks;
}

/**
 * Restores the default post-update revision hook after a DE-RTC save.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array|int|false $hooks Hook priorities returned by the suspend helper.
 */
function wp_de_rtc_restore_retry_save_core_revision_hook( $hooks ) {
	if ( ! is_array( $hooks ) ) {
		$hooks = array(
			'wp_after_insert_post' => $hooks,
			'post_updated'         => false,
		);
	}

	if ( false !== $hooks['wp_after_insert_post'] && false === has_action( 'wp_after_insert_post', 'wp_save_post_revision_on_insert' ) ) {
		add_action( 'wp_after_insert_post', 'wp_save_post_revision_on_insert', $hooks['wp_after_insert_post'], 3 );
	}

	if ( false !== $hooks['post_updated'] && false === has_action( 'post_updated', 'wp_save_post_revision' ) ) {
		add_action( 'post_updated', 'wp_save_post_revision', $hooks['post_updated'], 1 );
	}
}

/**
 * Creates a matching current-post revision without loading every old revision.
 *
 * Core's default `wp_save_post_revision()` compares against the revision
 * history by materializing previous revision bodies. Long collaborative posts
 * can have hundreds of large revisions, so DE-RTC writes the same current
 * revision through the lower-level primitive after the guarded save confirms
 * storage.
 *
 * @since 7.1.0
 * @access private
 *
 * @param int|WP_Post $post Post ID or object.
 * @return int|null|WP_Error Created revision ID, null when revisions are disabled, or an error.
 */
function wp_de_rtc_put_retry_save_revision( $post ) {
	$post = get_post( $post );

	if ( ! $post ) {
		return null;
	}

	if ( ! post_type_supports( $post->post_type, 'revisions' ) || 'auto-draft' === $post->post_status || ! wp_revisions_enabled( $post ) ) {
		return null;
	}

	if ( ! function_exists( '_wp_put_post_revision' ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_storage_failure',
			__( 'Distributed Editing could not create a retry-save revision.' ),
			array(
				'detail'           => 'retry_save_revision_primitive_missing',
				'post_id'          => (int) $post->ID,
				'creates_revision' => false,
				'claims_saved'     => false,
			)
		);
	}

	$added_sync_meta_kses_allowance = false === has_filter( 'wp_kses_allowed_html', 'wp_de_rtc_filter_sync_meta_script_kses_allowance' );

	if ( $added_sync_meta_kses_allowance ) {
		wp_de_rtc_enable_sync_meta_script_kses_allowance();
	}

	try {
		$revision_id = _wp_put_post_revision( $post );
	} finally {
		if ( $added_sync_meta_kses_allowance ) {
			wp_de_rtc_disable_sync_meta_script_kses_allowance();
		}
	}

	if ( is_wp_error( $revision_id ) ) {
		return $revision_id;
	}

	return $revision_id ? (int) $revision_id : null;
}

/**
 * Applies the safe subset of a retry-save before returning review rejection.
 *
 * Full proposed content is still rejected. This helper only advances the server
 * when the unsafe KSES review blocks have already been removed from the
 * stripped candidate by a conservative partial-safe plan.
 *
 * @since 7.1.0
 * @access private
 *
 * @param WP_Post $post         Post being saved.
 * @param array   $current      Parsed current post content and sync meta.
 * @param array   $partial_plan Partial-safe plan.
 * @param array   $args         Retry-save evidence.
 * @return array|WP_Error Partial-safe response data or an error.
 */
function wp_de_rtc_apply_partial_safe_retry_save_plan( $post, $current, $partial_plan, $args ) {
	$safe_post_content = isset( $partial_plan['safe_post_content'] ) && is_string( $partial_plan['safe_post_content'] )
		? $partial_plan['safe_post_content']
		: null;

	if ( null === $safe_post_content ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_rebase_failed',
			__( 'Distributed Editing could not isolate safe retry-save changes for review.' ),
			array(
				'detail'               => 'partial_safe_merge_candidate_missing',
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$server_version                 = isset( $args['server_version'] ) ? sanitize_text_field( (string) $args['server_version'] ) : '';
	$client_base_version            = isset( $args['client_base_version'] ) ? sanitize_text_field( (string) $args['client_base_version'] ) : '';
	$accepted_proof_server_version = isset( $args['accepted_proof_server_version'] ) ? sanitize_text_field( (string) $args['accepted_proof_server_version'] ) : '';
	$rebased_from_version           = isset( $args['rebased_from_version'] ) ? sanitize_text_field( (string) $args['rebased_from_version'] ) : '';
	$pending_change_count           = isset( $args['pending_change_count'] ) ? max( 0, (int) $args['pending_change_count'] ) : 1;
	$proposed_post_content_hash     = isset( $args['proposed_post_content_hash'] ) ? sanitize_text_field( (string) $args['proposed_post_content_hash'] ) : '';
	$authorship_context             = isset( $args['authorship_context'] ) && is_array( $args['authorship_context'] ) ? $args['authorship_context'] : wp_de_rtc_get_retry_save_authorship_context( $post );
	$safe_post_content_hash         = wp_de_rtc_hash_content( $safe_post_content );
	$current_post_content_hash      = wp_de_rtc_hash_content( $current['content'] );
	$review_classification          = isset( $partial_plan['review_classification'] ) && is_array( $partial_plan['review_classification'] ) ? $partial_plan['review_classification'] : array();
	$review_items                   = isset( $review_classification['review_items'] ) && is_array( $review_classification['review_items'] ) ? array_values( $review_classification['review_items'] ) : array();
	$remaining_pending_change_count = count( $review_items ) > 0 ? count( $review_items ) : $pending_change_count;
	$revision_ids_before_save       = wp_de_rtc_get_post_revision_ids( $post->ID );
	$proposed_post_content          = isset( $args['proposed_post_content'] ) && is_string( $args['proposed_post_content'] ) ? $args['proposed_post_content'] : '';

	if ( hash_equals( $current_post_content_hash, $safe_post_content_hash ) ) {
		$review_item_queue = wp_de_rtc_record_review_required_items(
			$post,
			$review_items,
			array(
				'base_post_content'     => $current['content'],
				'proposed_post_content' => $proposed_post_content,
				'server_version'        => $server_version,
				'client_base_version'   => $client_base_version,
			)
		);

		return array(
			'partial_safe_merge_applied'              => true,
			'partial_safe_merge_persisted'            => false,
			'partial_safe_merge_no_write'             => true,
			'partial_safe_merge_status'               => 'safe_subset_already_current',
			'partial_safe_merge_review_item_count'    => count( $review_items ),
			'partial_safe_merge_unsafe_block_count'   => count( $review_items ),
			'partial_safe_merge_safe_content_hash'    => $safe_post_content_hash,
			'partial_safe_merge_current_content_hash' => $current_post_content_hash,
			'content'                                 => array(
				'raw' => $post->post_content,
			),
			'client_base_version'                     => $client_base_version,
			'accepted_proof_server_version'           => $accepted_proof_server_version,
			'previous_server_version'                 => isset( $current['sync_meta']['previous_version'] ) ? sanitize_text_field( (string) $current['sync_meta']['previous_version'] ) : null,
			'server_version'                          => $server_version,
			'rebased_from_version'                    => $rebased_from_version,
			'pending_change_count'                    => $remaining_pending_change_count,
			'partial_safe_merge_original_pending_change_count' => $pending_change_count,
			'proposed_post_content_hash'              => $proposed_post_content_hash,
			'saved_stripped_post_content_hash'        => $current_post_content_hash,
			'saved_post_content_hash'                 => wp_de_rtc_hash_content( $post->post_content ),
			'requires_server_state_refetch'           => false,
			'requires_manual_conflict_resolution'     => false,
			'can_export_local_updates'                => false,
			'saves_post'                              => false,
			'mutates_post_content'                    => false,
			'creates_revision'                        => false,
			'claims_saved'                            => false,
			'remaining_review_required'               => true,
			'revision_ids_before_save'                => $revision_ids_before_save,
			'revision_ids_after_save'                 => $revision_ids_before_save,
			'created_revision_ids'                    => array(),
			'revision_created'                        => false,
			'safe_server_content_included'            => true,
			'unsafe_raw_content_included'             => false,
			'review_item_queue'                       => $review_item_queue,
		);
	}

	$next_sync_meta                 = $current['sync_meta'];
	$partial_automerge_save_result = null;

	if ( 'automerge' === $current['sync_meta_format'] ) {
		$partial_automerge_save_result = wp_de_rtc_get_automerge_retry_save_result(
			$current['content'],
			$current['content'],
			$safe_post_content,
			null
		);

		if ( is_wp_error( $partial_automerge_save_result ) ) {
			return $partial_automerge_save_result;
		}

		$partial_automerge_save_result = wp_de_rtc_apply_authorship_context_to_automerge_result( $partial_automerge_save_result, $authorship_context );
		$next_sync_meta                = wp_de_rtc_apply_automerge_metadata_to_sync_meta( $next_sync_meta, $partial_automerge_save_result, $safe_post_content_hash );

		if ( is_wp_error( $next_sync_meta ) ) {
			return $next_sync_meta;
		}

		$next_sync_meta = wp_de_rtc_apply_automerge_authorship_to_sync_meta( $next_sync_meta, $safe_post_content, $partial_automerge_save_result, $authorship_context );
	}

	$next_version   = wp_de_rtc_get_next_sync_meta_version( $server_version, $safe_post_content_hash );
	$next_sync_meta = wp_de_rtc_update_automerge_version_snapshots(
		$next_sync_meta,
		$server_version,
		$current['content'],
		$next_version,
		$safe_post_content
	);

	$next_sync_meta['version']          = $next_version;
	$next_sync_meta['previous_version'] = $server_version;
	$next_sync_meta['last_server_update'] = array(
		'type'                          => 'retry_save_partial_safe_merge',
		'user_id'                       => get_current_user_id(),
		'session_label'                 => wp_de_rtc_get_history_author_display_name( get_current_user_id() ),
		'attribution_key'               => isset( $authorship_context['attributionKey'] ) ? $authorship_context['attributionKey'] : null,
		'client_base_version'           => $client_base_version,
		'accepted_proof_server_version' => $accepted_proof_server_version,
		'rebased_from_version'          => $rebased_from_version,
		'pending_change_count'          => $remaining_pending_change_count,
		'original_pending_change_count' => $pending_change_count,
		'proposed_post_content_hash'    => $proposed_post_content_hash,
		'saved_stripped_post_content_hash' => $safe_post_content_hash,
		'partial_safe_merge'            => array(
			'status'             => 'safe_subset_persisted',
			'review_item_count'  => count( $review_items ),
			'unsafe_block_count' => count( $review_items ),
			'content_filter'     => 'wp_filter_post_kses',
		),
	);

	$candidate_post_content = wp_de_rtc_add_sync_meta_to_post_content(
		$safe_post_content,
		$current['sync_meta_format'],
		$next_sync_meta,
		$current['sync_meta_position']
	);

	if ( is_wp_error( $candidate_post_content ) ) {
		return $candidate_post_content;
	}

	$candidate_hash = wp_de_rtc_hash_content( $candidate_post_content );

	wp_de_rtc_enable_sync_meta_script_kses_allowance();

	global $wp_de_rtc_retry_save_candidate_post_content;

	if ( ! is_array( $wp_de_rtc_retry_save_candidate_post_content ) ) {
		$wp_de_rtc_retry_save_candidate_post_content = array();
	}

	$wp_de_rtc_retry_save_candidate_post_content[ (int) $post->ID ] = $candidate_post_content;

	$core_revision_hook_priority = wp_de_rtc_suspend_retry_save_core_revision_hook();

	try {
		$updated_post_id = wp_update_post(
			wp_slash(
				array(
					'ID'           => (int) $post->ID,
					'post_content' => $candidate_post_content,
				)
			),
			true
		);
	} finally {
		wp_de_rtc_restore_retry_save_core_revision_hook( $core_revision_hook_priority );
		unset( $wp_de_rtc_retry_save_candidate_post_content[ (int) $post->ID ] );
		wp_de_rtc_disable_sync_meta_script_kses_allowance();
	}

	if ( is_wp_error( $updated_post_id ) ) {
		return $updated_post_id;
	}

	if ( ! $updated_post_id ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_storage_failure',
			__( 'Distributed Editing could not save the safe retry-save subset.' ),
			array(
				'detail'  => 'partial_safe_merge_post_update_failed',
				'post_id' => (int) $post->ID,
			)
		);
	}

	$persisted_post = get_post( $post->ID );

	if ( ! $persisted_post || ! hash_equals( $candidate_hash, wp_de_rtc_hash_content( $persisted_post->post_content ) ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_storage_failure',
			__( 'Distributed Editing could not confirm that WordPress saved the safe retry-save subset.' ),
			array(
				'detail'                           => 'partial_safe_merge_post_update_confirmation_failed',
				'post_id'                          => (int) $post->ID,
				'expected_saved_post_content_hash' => $candidate_hash,
				'actual_saved_post_content_hash'   => $persisted_post ? wp_de_rtc_hash_content( $persisted_post->post_content ) : null,
				'saves_post'                       => false,
				'mutates_post_content'             => false,
				'creates_revision'                 => false,
				'claims_saved'                     => false,
			)
		);
	}

	$retry_save_revision_id = wp_de_rtc_put_retry_save_revision( $persisted_post );

	if ( is_wp_error( $retry_save_revision_id ) ) {
		return $retry_save_revision_id;
	}

	$revision_ids_after_save = wp_de_rtc_get_post_revision_ids( $post->ID );
	$created_revision_ids    = array_values( array_diff( $revision_ids_after_save, $revision_ids_before_save ) );

	if ( $retry_save_revision_id && ! in_array( (int) $retry_save_revision_id, $created_revision_ids, true ) ) {
		$created_revision_ids[] = (int) $retry_save_revision_id;
	}

	$review_item_queue = wp_de_rtc_record_review_required_items(
		$post,
		$review_items,
		array(
			'base_post_content'     => $current['content'],
			'proposed_post_content' => $proposed_post_content,
			'server_version'        => $next_version,
			'client_base_version'   => $client_base_version,
		)
	);

	return array(
		'partial_safe_merge_applied'              => true,
		'partial_safe_merge_persisted'            => true,
		'partial_safe_merge_no_write'             => false,
		'partial_safe_merge_status'               => 'safe_subset_persisted',
		'partial_safe_merge_review_item_count'    => count( $review_items ),
		'partial_safe_merge_unsafe_block_count'   => count( $review_items ),
		'partial_safe_merge_safe_content_hash'    => $safe_post_content_hash,
		'partial_safe_merge_current_content_hash' => $current_post_content_hash,
		'content'                                 => array(
			'raw' => $candidate_post_content,
		),
		'updated_post_id'                         => (int) $updated_post_id,
		'client_base_version'                     => $client_base_version,
		'accepted_proof_server_version'           => $accepted_proof_server_version,
		'previous_server_version'                 => $server_version,
		'server_version'                          => $next_version,
		'rebased_from_version'                    => $rebased_from_version,
		'pending_change_count'                    => $remaining_pending_change_count,
		'partial_safe_merge_original_pending_change_count' => $pending_change_count,
		'proposed_post_content_hash'              => $proposed_post_content_hash,
		'saved_stripped_post_content_hash'        => $safe_post_content_hash,
		'saved_post_content_hash'                 => $candidate_hash,
		'automerge_update_applied'                      => is_array( $partial_automerge_save_result ),
		'automerge_encoding'                            => wp_de_rtc_get_automerge_result_encoding( $partial_automerge_save_result ),
			'requires_server_state_refetch'           => false,
			'requires_manual_conflict_resolution'     => false,
			'can_export_local_updates'                => false,
			'saves_post'                              => true,
			'partial_safe_merge_saves_post'           => true,
			'mutates_post_content'                    => true,
			'creates_revision'                        => ! empty( $created_revision_ids ),
			'claims_saved'                            => false,
			'remaining_review_required'               => true,
		'revision_ids_before_save'                => $revision_ids_before_save,
		'revision_ids_after_save'                 => $revision_ids_after_save,
		'created_revision_ids'                    => $created_revision_ids,
		'revision_created'                        => ! empty( $created_revision_ids ),
		'safe_server_content_included'            => true,
		'unsafe_raw_content_included'             => false,
		'review_item_queue'                       => $review_item_queue,
	);
}

/**
 * Applies an accepted retry-save request.
 *
 * The client sends stripped proposed post content and proof metadata. The
 * server validates the proof against the current sync-meta version, rejects
 * contradictory proof flags, creates the next sync meta, and persists the
 * combined post_content with revision evidence.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post Post ID or object.
 * @param array       $args {
 *     Retry-save request arguments.
 *
 *     @type mixed $client_base_version                 Client base version after local rebase.
 *     @type mixed $accepted_proof_server_version       Server version from accepted proof.
 *     @type mixed $rebased_from_version                Original stale version that was rebased from.
 *     @type mixed $pending_change_count                Pending local change count. Default 1.
 *     @type mixed $proposed_post_content               Proposed content without sync metadata.
 *     @type mixed $proposed_post_content_hash          Hash of proposed content without sync metadata.
 *     @type mixed $accepted_proof_saves_post           Whether proof claimed to save.
 *     @type mixed $accepted_proof_mutates_post_content Whether proof claimed to mutate content.
 *     @type mixed $accepted_proof_creates_revision     Whether proof claimed to create a revision.
 *     @type mixed $accepted_proof_claims_saved         Whether proof claimed saved state.
 *     @type array $review_approval_proof               Hash-only unfiltered HTML review approval proof.
 *     @type array $accepted_fresh_review_decision      Hash-only fresh-review consume evidence.
 *     @type mixed $post_type_rest_base                 REST base from the retry-save route.
 * }
 * @return array|WP_Error Retry-save result, or rejection.
 */
function wp_de_rtc_save_retry_submitted_post( $post, $args = array() ) {
	$post = get_post( $post );

	if ( ! $post ) {
		return new WP_Error(
			'rest_post_invalid_id',
			__( 'Invalid post ID.' ),
			array( 'status' => 404 )
		);
	}

	$requested_rest_base = isset( $args['post_type_rest_base'] ) ? sanitize_key( (string) $args['post_type_rest_base'] ) : '';
	$post_rest_base      = wp_de_rtc_get_post_type_rest_base( $post->post_type );
	$supported_bases     = wp_de_rtc_get_rest_recovery_post_type_rest_bases();

	if (
		'' !== $requested_rest_base &&
		(
			'' === $post_rest_base ||
			$requested_rest_base !== $post_rest_base ||
			! in_array( $post_rest_base, $supported_bases, true )
		)
	) {
		return new WP_Error(
			'rest_post_invalid_id',
			__( 'Invalid post ID.' ),
			array( 'status' => 404 )
		);
	}

	if ( ! current_user_can( 'edit_post', $post->ID ) ) {
		return new WP_Error(
			'rest_cannot_edit',
			__( 'Sorry, you are not allowed to edit this post.' ),
			array( 'status' => rest_authorization_required_code() )
		);
	}

	if ( ! wp_de_rtc_is_enabled_for_post( $post ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_feature_disabled',
			__( 'Distributed Editing is not enabled for this post.' ),
			array(
				'detail'  => 'feature_disabled_for_post',
				'post_id' => (int) $post->ID,
			)
		);
	}

	$client_base_version            = isset( $args['client_base_version'] ) ? sanitize_text_field( (string) $args['client_base_version'] ) : '';
	$accepted_proof_server_version = isset( $args['accepted_proof_server_version'] ) ? sanitize_text_field( (string) $args['accepted_proof_server_version'] ) : '';
	$pending_change_count           = array_key_exists( 'pending_change_count', $args ) ? max( 0, (int) $args['pending_change_count'] ) : 1;
	$rebased_from_version           = isset( $args['rebased_from_version'] ) ? sanitize_text_field( (string) $args['rebased_from_version'] ) : null;
	$accepted_proof_saves_post      = ! empty( $args['accepted_proof_saves_post'] ) && wp_validate_boolean( $args['accepted_proof_saves_post'] );
	$accepted_proof_mutates_content = ! empty( $args['accepted_proof_mutates_post_content'] ) && wp_validate_boolean( $args['accepted_proof_mutates_post_content'] );
	$accepted_proof_creates_revision = ! empty( $args['accepted_proof_creates_revision'] ) && wp_validate_boolean( $args['accepted_proof_creates_revision'] );
	$accepted_proof_claims_saved    = ! empty( $args['accepted_proof_claims_saved'] ) && wp_validate_boolean( $args['accepted_proof_claims_saved'] );
	$review_approval_proof          = isset( $args['review_approval_proof'] ) ? $args['review_approval_proof'] : null;
	$review_approval_consumption    = null;
	$accepted_fresh_review_decision = isset( $args['accepted_fresh_review_decision'] ) ? $args['accepted_fresh_review_decision'] : null;
	$fresh_review_consumption       = null;
	$fresh_review_consumption_claim = null;
	$block_identity_request_proof   = isset( $args['block_identity_request_proof'] ) ? $args['block_identity_request_proof'] : null;
	$block_identity_request_proof_validation = null;
	$automerge_client_update        = isset( $args['automerge_client_update'] ) ? $args['automerge_client_update'] : null;
	$automerge_retry_save_result    = null;
	$session_key                    = isset( $args['session_key'] ) ? (string) $args['session_key'] : '';
	$authorship_context             = wp_de_rtc_get_retry_save_authorship_context( $post, $session_key );
	$current                        = wp_de_rtc_parse_post_content_sync_meta( $post->post_content );
	$current_external_repair        = null;

	if ( is_wp_error( $current ) ) {
		return $current;
	}

	$current_external_repair = wp_de_rtc_get_repaired_automerge_current_post_snapshot(
		$post,
		$current,
		array(
			'allow_empty_import' => true,
		)
	);

	if ( is_wp_error( $current_external_repair ) ) {
		return $current_external_repair;
	}

	if ( is_array( $current_external_repair ) ) {
		$current = $current_external_repair;
	}

	$server_version = (
		is_array( $current ) &&
		isset( $current['sync_meta'] ) &&
		is_array( $current['sync_meta'] ) &&
		array_key_exists( 'version', $current['sync_meta'] )
	)
		? (string) $current['sync_meta']['version']
		: null;
	$retry_save_versions_match_current = (
		'' !== $client_base_version &&
		'' !== $accepted_proof_server_version &&
		null !== $server_version &&
		$client_base_version === $server_version &&
		$accepted_proof_server_version === $server_version
	);
	$retry_save_server_merge_required  = false;

	if (
		$accepted_proof_saves_post ||
		$accepted_proof_mutates_content ||
		$accepted_proof_creates_revision ||
		$accepted_proof_claims_saved
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because the accepted proof claimed persistence.' ),
			array(
				'detail'      => 'retry_save_proof_claimed_persistence',
				'post_id'     => (int) $post->ID,
				'rest_route'  => 'post_retry_save',
				'saves_post'  => false,
				'claims_saved' => false,
			)
		);
	}

	if ( ! array_key_exists( 'proposed_post_content', $args ) || ! is_string( $args['proposed_post_content'] ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the retry save because proposed post content is missing.' ),
			array(
				'detail'     => 'missing_retry_save_proposed_content',
				'post_id'    => (int) $post->ID,
				'rest_route' => 'post_retry_save',
			)
		);
	}

	$raw_proposed_post_content = (string) $args['proposed_post_content'];
	$proposed_post_content     = wp_de_rtc_canonicalize_post_content_core_block_names( $raw_proposed_post_content );
	$proposed                  = wp_de_rtc_parse_post_content_sync_meta( $raw_proposed_post_content );

	if ( is_wp_error( $proposed ) ) {
		return $proposed;
	}

	if ( null !== $proposed['sync_meta'] ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because clients may not submit altered sync metadata.' ),
			array(
				'detail'               => 'retry_save_client_submitted_sync_meta',
				'post_id'              => (int) $post->ID,
				'rest_route'           => 'post_retry_save',
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$raw_proposed_post_content_hash = hash( 'sha256', $raw_proposed_post_content );
	$proposed_post_content_hash     = wp_de_rtc_hash_content( $proposed_post_content );
	$expected_content_hash          = isset( $args['proposed_post_content_hash'] ) ? sanitize_text_field( (string) $args['proposed_post_content_hash'] ) : null;

	if (
		null !== $expected_content_hash &&
		! hash_equals( $expected_content_hash, $proposed_post_content_hash ) &&
		! hash_equals( $expected_content_hash, $raw_proposed_post_content_hash )
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because the proposed content hash does not match.' ),
			array(
				'detail'                       => 'retry_save_proposed_content_hash_mismatch',
				'post_id'                      => (int) $post->ID,
				'rest_route'                   => 'post_retry_save',
				'proposed_post_content_hash'   => $proposed_post_content_hash,
				'expected_post_content_hash'   => $expected_content_hash,
				'saves_post'                   => false,
				'mutates_post_content'         => false,
				'creates_revision'             => false,
				'claims_saved'                 => false,
			)
		);
	}

	if (
		! is_array( $current['sync_meta'] ) ||
		! is_string( $current['sync_meta_format'] ) ||
		! is_string( $current['sync_meta_position'] )
	) {
		return wp_de_rtc_get_stale_base_rejection_error(
			$post,
			array(
				'client_base_version'      => $client_base_version,
				'server_version'           => null,
				'pending_change_count'     => $pending_change_count,
				'remote_change_count'      => 1,
				'can_attempt_local_rebase' => false,
				'rest_route'               => 'post_retry_save_stale_base',
			)
		);
	}

	if (
		! $retry_save_versions_match_current
	) {
		$retry_save_server_merge_required = (
			'' !== $client_base_version &&
			'' !== $accepted_proof_server_version &&
			null !== $server_version &&
			$client_base_version === $accepted_proof_server_version &&
			$client_base_version !== $server_version
		);

		if ( ! $retry_save_server_merge_required ) {
			return wp_de_rtc_get_stale_base_rejection_error(
				$post,
				array(
					'client_base_version'      => $client_base_version,
					'server_version'           => $server_version,
					'pending_change_count'     => $pending_change_count,
					'remote_change_count'      => 1,
					'can_attempt_local_rebase' => false,
					'rest_route'               => 'post_retry_save_stale_base',
				)
			);
		}
	}

	$save_post_content      = $proposed_post_content;
	$save_post_content_hash = $proposed_post_content_hash;
	$server_merge_result    = null;
	$base_revision          = null;

	if ( null === $block_identity_request_proof ) {
		$duplicate_retry_save = wp_de_rtc_get_duplicate_retry_save_no_write_result(
			$post,
			$current,
			array(
				'client_base_version'           => $client_base_version,
				'accepted_proof_server_version' => $accepted_proof_server_version,
				'server_version'                => $server_version,
				'rebased_from_version'          => $rebased_from_version,
				'pending_change_count'          => $pending_change_count,
				'proposed_post_content_hash'    => $proposed_post_content_hash,
			)
		);

		if ( is_array( $duplicate_retry_save ) ) {
			return $duplicate_retry_save;
		}
	}

	if ( $retry_save_server_merge_required ) {
		$base_revision = wp_de_rtc_find_revision_with_sync_meta_version( $post, $accepted_proof_server_version );

		if ( is_wp_error( $base_revision ) ) {
			return $base_revision;
		}

		if ( empty( $base_revision['found'] ) ) {
			return wp_de_rtc_get_stale_base_rejection_error(
				$post,
				array(
					'client_base_version'      => $client_base_version,
					'server_version'           => $server_version,
					'pending_change_count'     => $pending_change_count,
					'remote_change_count'      => 1,
					'can_attempt_local_rebase' => false,
					'rest_route'               => 'post_retry_save_stale_base',
				)
			);
		}
	}

	if ( null !== $block_identity_request_proof ) {
		$block_identity_request_proof_validation = wp_de_rtc_validate_retry_save_block_identity_request_proof(
			$block_identity_request_proof,
			$retry_save_server_merge_required ? $base_revision['sync_meta'] : $current['sync_meta'],
			$proposed_post_content_hash,
			$post,
			array(
				$raw_proposed_post_content_hash,
				$expected_content_hash,
			)
		);

		if ( is_wp_error( $block_identity_request_proof_validation ) ) {
			return $block_identity_request_proof_validation;
		}
	}

	if ( null !== $block_identity_request_proof ) {
		$duplicate_retry_save = wp_de_rtc_get_duplicate_retry_save_no_write_result(
			$post,
			$current,
			array(
				'client_base_version'                    => $client_base_version,
				'accepted_proof_server_version'          => $accepted_proof_server_version,
				'server_version'                         => $server_version,
				'rebased_from_version'                   => $rebased_from_version,
				'pending_change_count'                   => $pending_change_count,
				'proposed_post_content_hash'             => $proposed_post_content_hash,
				'block_identity_request_proof_validation' => $block_identity_request_proof_validation,
			)
		);

		if ( is_array( $duplicate_retry_save ) ) {
			return $duplicate_retry_save;
		}
	}

	if ( 'automerge' === $current['sync_meta_format'] && ! $retry_save_server_merge_required ) {
		$automerge_retry_save_result = wp_de_rtc_get_automerge_retry_save_result(
			$current['content'],
			$current['content'],
			$proposed_post_content,
			$automerge_client_update
		);

		if ( is_wp_error( $automerge_retry_save_result ) ) {
			return $automerge_retry_save_result;
		}

		$save_post_content      = $automerge_retry_save_result['merged_content'];
		$save_post_content_hash = wp_de_rtc_hash_content( $save_post_content );
	}

	if ( $retry_save_server_merge_required ) {
		if ( 'automerge' === $current['sync_meta_format'] ) {
			$server_merge_result = wp_de_rtc_get_automerge_retry_save_result(
				$base_revision['content'],
				$current['content'],
				$proposed_post_content,
				$automerge_client_update
			);
		} elseif ( null !== $block_identity_request_proof ) {
			$server_merge_result = wp_de_rtc_get_block_identity_server_merge_result(
				$base_revision['content'],
				$current['content'],
				$proposed_post_content,
				$block_identity_request_proof,
				$block_identity_request_proof_validation,
				array(
					'base_version'      => $accepted_proof_server_version,
					'server_version'    => $server_version,
					'base_revision_id'  => $base_revision['revision_id'],
					'pending_changes'   => $pending_change_count,
					'base_sync_meta'    => $base_revision['sync_meta'],
					'current_sync_meta' => $current['sync_meta'],
				)
			);
		} else {
			$server_merge_result = wp_de_rtc_get_serialized_block_server_merge_result(
				$base_revision['content'],
				$current['content'],
				$proposed_post_content,
				array(
					'base_version'      => $accepted_proof_server_version,
					'server_version'    => $server_version,
					'base_revision_id'  => $base_revision['revision_id'],
					'pending_changes'   => $pending_change_count,
				)
			);
		}

		if ( is_wp_error( $server_merge_result ) ) {
			$data = $server_merge_result->get_error_data( 'de_rtc_rebase_failed' );

			if ( ! is_array( $data ) ) {
				$data = array();
			}

			$data['post_id']                             = (int) $post->ID;
			$data['rest_route']                          = 'post_retry_save_server_merge';
			$data['client_base_version']                 = $client_base_version;
			$data['accepted_proof_server_version']       = $accepted_proof_server_version;
			$data['server_version']                      = $server_version;
			$data['pending_change_count']                = $pending_change_count;
			$data['requires_server_state_refetch']       = false;
			$data['requires_manual_conflict_resolution'] = true;
			$data['can_export_local_updates']            = $pending_change_count > 0;
			$data['saves_post']                          = false;
			$data['mutates_post_content']                = false;
			$data['creates_revision']                    = false;
			$data['claims_saved']                        = false;
			$data['permission_contract']                 = wp_de_rtc_get_rest_recovery_permission_contract( $post );

			$server_merge_result->add_data( $data, 'de_rtc_rebase_failed' );

			return $server_merge_result;
		}

		$save_post_content      = $server_merge_result['merged_content'];
		$save_post_content_hash = wp_de_rtc_hash_content( $save_post_content );
		if ( 'automerge' === $current['sync_meta_format'] ) {
			$automerge_retry_save_result = $server_merge_result;
		}
	}

	$next_version   = wp_de_rtc_get_next_sync_meta_version( $server_version, $save_post_content_hash );
	$next_sync_meta = $current['sync_meta'];

	if ( is_array( $block_identity_request_proof_validation ) ) {
		$next_sync_meta = wp_de_rtc_apply_block_identity_request_proof_to_sync_meta(
			$next_sync_meta,
			is_array( $server_merge_result ) && isset( $server_merge_result['block_identity_merged_block_map'] )
				? array_merge(
					(array) $block_identity_request_proof,
					array(
						'proposed_block_map' => $server_merge_result['block_identity_merged_block_map'],
					)
				)
				: $block_identity_request_proof,
			$next_version,
			$save_post_content_hash
		);
	}

	if ( 'automerge' === $current['sync_meta_format'] ) {
		if ( null === $automerge_retry_save_result ) {
			$automerge_retry_save_result = wp_de_rtc_get_automerge_retry_save_result(
				$current['content'],
				$current['content'],
				$save_post_content,
				$automerge_client_update
			);
		}

		if ( is_wp_error( $automerge_retry_save_result ) ) {
			return $automerge_retry_save_result;
		}

		$automerge_retry_save_result = wp_de_rtc_apply_authorship_context_to_automerge_result( $automerge_retry_save_result, $authorship_context );
		$next_sync_meta              = wp_de_rtc_apply_automerge_metadata_to_sync_meta( $next_sync_meta, $automerge_retry_save_result, $save_post_content_hash );

		if ( is_wp_error( $next_sync_meta ) ) {
			return $next_sync_meta;
		}

		$next_sync_meta = wp_de_rtc_apply_automerge_authorship_to_sync_meta( $next_sync_meta, $save_post_content, $automerge_retry_save_result, $authorship_context );
	}

	$next_sync_meta = wp_de_rtc_update_automerge_version_snapshots(
		$next_sync_meta,
		$server_version,
		$current['content'],
		$next_version,
		$save_post_content
	);

	$next_sync_meta['version']           = $next_version;
	$next_sync_meta['previous_version']  = $server_version;
	$next_sync_meta['last_server_update'] = array(
		'type'                         => $retry_save_server_merge_required ? 'retry_save_server_merge' : 'retry_save',
		'user_id'                      => get_current_user_id(),
		'session_label'                => wp_de_rtc_get_history_author_display_name( get_current_user_id() ),
		'attribution_key'              => isset( $authorship_context['attributionKey'] ) ? $authorship_context['attributionKey'] : null,
		'client_base_version'          => $client_base_version,
		'accepted_proof_server_version' => $accepted_proof_server_version,
		'rebased_from_version'         => $rebased_from_version,
		'pending_change_count'         => $pending_change_count,
		'proposed_post_content_hash'   => $proposed_post_content_hash,
	);

	if ( is_array( $block_identity_request_proof_validation ) ) {
		$next_sync_meta['last_server_update']['block_identity_request_proof'] = array(
			'status'               => 'valid',
			'proposed_block_count' => $block_identity_request_proof_validation['proposed_block_count'],
			'retained_block_count' => $block_identity_request_proof_validation['retained_block_count'],
			'inserted_block_count' => $block_identity_request_proof_validation['inserted_block_count'],
			'deleted_block_count'  => $block_identity_request_proof_validation['deleted_block_count'],
			'moved_block_count'    => $block_identity_request_proof_validation['moved_block_count'],
			'content_free'         => true,
		);
	}

		if ( is_array( $server_merge_result ) ) {
			$next_sync_meta['last_server_update']['saved_stripped_post_content_hash'] = $save_post_content_hash;
			$next_sync_meta['last_server_update']['server_merge'] = wp_de_rtc_get_public_server_merge_evidence( $server_merge_result );
		}

		if ( is_array( $current_external_repair ) ) {
			$next_sync_meta['last_server_update']['external_repair'] = array(
				'mode'                   => $current_external_repair['external_repair_mode'],
				'base_version'           => $current_external_repair['base_version'],
				'repaired_version'       => $current_external_repair['server_version'],
				'base_revision_id'       => $current_external_repair['base_revision_id'],
				'base_content_hash'      => $current_external_repair['base_content_hash'],
				'current_content_hash'   => $current_external_repair['current_content_hash'],
				'repair_actor'           => isset( $current_external_repair['recovery_actor'] ) ? $current_external_repair['recovery_actor'] : null,
				'content_hash_algorithm' => 'sha256',
			);
		}

		$candidate_post_content = wp_de_rtc_add_sync_meta_to_post_content(
		$save_post_content,
		$current['sync_meta_format'],
		$next_sync_meta,
		$current['sync_meta_position']
	);

	if ( is_wp_error( $candidate_post_content ) ) {
		return $candidate_post_content;
	}

	$candidate_hash = wp_de_rtc_hash_content( $candidate_post_content );

	if ( null !== $accepted_fresh_review_decision ) {
		$fresh_review_consumption = wp_de_rtc_get_retry_save_fresh_review_decision_consumption_result(
			$post,
			array(
				'accepted_fresh_review_decision' => $accepted_fresh_review_decision,
				'client_base_version'            => $client_base_version,
				'accepted_proof_server_version'  => $accepted_proof_server_version,
				'server_version'                 => $server_version,
				'pending_change_count'           => $pending_change_count,
				'proposed_post_content_hash'     => $proposed_post_content_hash,
				'candidate_post_content_hash'    => $candidate_hash,
			)
		);

		if ( is_wp_error( $fresh_review_consumption ) ) {
			return $fresh_review_consumption;
		}
	}

	if ( ! current_user_can( 'unfiltered_html' ) ) {
		/*
		 * Review only KSES-sensitive changes relative to the current server
		 * body. Existing unsafe HTML may have been saved by an authorized
		 * editor; a lower-privileged safe edit must not be rejected merely
		 * because that unchanged block would be sanitized if authored now.
		 */
		$retry_save_kses_classification = wp_de_rtc_classify_kses_risky_block_review_items(
			$post,
			$save_post_content,
			array(
				'base_post_content'        => $current['content'],
				'client_base_version'      => $client_base_version,
				'server_version'           => $server_version,
				'user_can_unfiltered_html' => false,
				'author_id'                => get_current_user_id(),
			)
		);

		if ( is_wp_error( $retry_save_kses_classification ) ) {
			return $retry_save_kses_classification;
		}

		$retry_save_review_items = isset( $retry_save_kses_classification['review_items'] ) && is_array( $retry_save_kses_classification['review_items'] )
			? array_values( $retry_save_kses_classification['review_items'] )
			: array();

		if ( ! empty( $retry_save_review_items ) ) {
			$proposed_post_content_kses_review  = wp_de_rtc_get_kses_post_content_review_evidence( $proposed_post_content );
			$candidate_post_content_kses_review = wp_de_rtc_get_kses_post_content_review_evidence( $save_post_content );
			$review_approval_consumption        = wp_de_rtc_get_retry_save_review_approval_proof_consumption_result(
				$post,
				array(
					'review_approval_proof'         => $review_approval_proof,
					'client_base_version'           => $client_base_version,
					'accepted_proof_server_version' => $accepted_proof_server_version,
					'server_version'                => $server_version,
					'pending_change_count'          => $pending_change_count,
					'rebased_from_version'          => $rebased_from_version,
					'proposed_post_content'         => $proposed_post_content,
					'proposed_post_content_hash'    => $proposed_post_content_hash,
					'candidate_post_content_hash'   => $candidate_hash,
					'proof_required'                => true,
				)
			);

			if ( is_wp_error( $review_approval_consumption ) ) {
				if ( 'de_rtc_unfiltered_html_would_change_content' === $review_approval_consumption->get_error_code() ) {
					$partial_safe_retry_save_plan = wp_de_rtc_get_kses_partial_safe_retry_save_plan(
						$post,
						$current['content'],
						$save_post_content,
						array(
							'client_base_version' => $client_base_version,
							'server_version'      => $server_version,
						)
					);

					if ( is_wp_error( $partial_safe_retry_save_plan ) ) {
						return $partial_safe_retry_save_plan;
					}

					$review_items       = $retry_save_review_items;
					$partial_safe_merge = array();

					if ( is_array( $partial_safe_retry_save_plan ) ) {
						$review_classification = isset( $partial_safe_retry_save_plan['review_classification'] ) && is_array( $partial_safe_retry_save_plan['review_classification'] ) ? $partial_safe_retry_save_plan['review_classification'] : array();
						$review_items          = isset( $review_classification['review_items'] ) && is_array( $review_classification['review_items'] ) ? array_values( $review_classification['review_items'] ) : $review_items;

						if ( ! empty( $partial_safe_retry_save_plan['safe_candidate_available'] ) ) {
							$partial_safe_merge = wp_de_rtc_apply_partial_safe_retry_save_plan(
								$post,
								$current,
								$partial_safe_retry_save_plan,
								array(
									'server_version'                => $server_version,
									'client_base_version'           => $client_base_version,
									'accepted_proof_server_version' => $accepted_proof_server_version,
									'rebased_from_version'          => $rebased_from_version,
										'pending_change_count'          => $pending_change_count,
										'proposed_post_content'         => $proposed_post_content,
										'proposed_post_content_hash'    => $proposed_post_content_hash,
										'authorship_context'            => $authorship_context,
									)
								);

							if ( is_wp_error( $partial_safe_merge ) ) {
								return $partial_safe_merge;
							}
						}
					}

					return wp_de_rtc_get_unfiltered_html_review_rejection_error(
						$post,
						array(
							'pending_change_count'               => $pending_change_count,
							'rest_route'                         => 'post_retry_save',
							'proposed_post_content_hash'         => $proposed_post_content_hash,
							'candidate_post_content_hash'        => $candidate_hash,
							'proposed_post_content_kses_review'  => $proposed_post_content_kses_review,
							'candidate_post_content_kses_review' => $candidate_post_content_kses_review,
							'review_items'                       => $review_items,
							'partial_safe_merge'                 => $partial_safe_merge,
						)
					);
				}

				return $review_approval_consumption;
			}
		}
	} elseif ( null !== $review_approval_proof ) {
		$review_approval_consumption = wp_de_rtc_get_retry_save_review_approval_proof_consumption_result(
			$post,
			array(
				'review_approval_proof'         => $review_approval_proof,
				'client_base_version'           => $client_base_version,
				'accepted_proof_server_version' => $accepted_proof_server_version,
				'server_version'                => $server_version,
				'pending_change_count'          => $pending_change_count,
				'rebased_from_version'          => $rebased_from_version,
				'proposed_post_content'         => $proposed_post_content,
				'proposed_post_content_hash'    => $proposed_post_content_hash,
				'candidate_post_content_hash'   => $candidate_hash,
				'proof_required'                => false,
			)
		);

		if ( is_wp_error( $review_approval_consumption ) ) {
			return $review_approval_consumption;
		}
	}

	if (
		is_array( $review_approval_consumption ) &&
		! empty( $review_approval_consumption['review_approval_proof_consumed'] ) &&
		! current_user_can( 'unfiltered_html' )
	) {
		$accepted_review_approval_proof_envelope = wp_de_rtc_create_opaque_review_approval_proof_token_envelope( $review_approval_consumption['accepted_review_approval_proof'] );

		if ( is_wp_error( $accepted_review_approval_proof_envelope ) ) {
			return $accepted_review_approval_proof_envelope;
		}

		return wp_de_rtc_get_reason_error(
			'de_rtc_review_approval_requires_unfiltered_html',
			__( 'Distributed Editing requires an unfiltered HTML reviewer to save approved HTML changes.' ),
			array(
				'detail'                         => 'retry_save_review_approval_requires_unfiltered_html_saver',
				'post_id'                        => (int) $post->ID,
				'rest_route'                     => 'post_retry_save',
				'pending_change_count'           => $pending_change_count,
				'review_approval_proof_accepted' => true,
				'review_approval_proof_consumed' => false,
				'accepted_review_approval_proof_available' => true,
				'accepted_review_approval_proof_format' => 'opaque_review_approval_proof_token',
				'accepted_review_approval_proof' => $accepted_review_approval_proof_envelope,
				'reviewed_block_item_count'      => $review_approval_consumption['reviewed_block_item_count'],
				'requires_unfiltered_html'       => true,
				'requires_unfiltered_html_saver' => true,
				'unfiltered_html_allowed'        => false,
				'review_status'                  => 'approved_by_unfiltered_html_reviewer',
				'approval_status'                => 'approved_for_retry_save',
				'review_action'                  => 'request_unfiltered_html_reviewer',
				'approval_action'                => 'retry_save_with_unfiltered_html_saver',
				'review_required_capability'     => 'unfiltered_html',
				'reviewer_capability'            => 'unfiltered_html',
				'review_scope'                   => 'collaborative_post_content',
				'raw_content_included'           => false,
				'can_export_local_updates'       => true,
				'saves_post'                     => false,
				'mutates_post_content'           => false,
				'creates_revision'               => false,
				'claims_saved'                   => false,
			)
		);
	}

	$revision_ids_before_save = wp_de_rtc_get_post_revision_ids( $post->ID );

	$base_revision_before_retry_save = 'automerge' === $current['sync_meta_format']
		? wp_de_rtc_ensure_current_sync_meta_revision_before_retry_save( $post, $server_version )
		: null;

	if ( is_wp_error( $base_revision_before_retry_save ) ) {
		return $base_revision_before_retry_save;
	}

	if (
		is_array( $fresh_review_consumption ) &&
		! empty( $fresh_review_consumption['fresh_review_decision_ready_for_retry_save'] )
	) {
		$fresh_review_consumption_claim = wp_de_rtc_claim_opaque_fresh_review_decision_retry_save_consumption(
			$fresh_review_consumption['_fresh_review_request_record'],
			$post,
			array(
				'previous_server_version'     => $server_version,
				'proposed_post_content_hash'  => $proposed_post_content_hash,
				'candidate_post_content_hash' => $candidate_hash,
			)
		);

		if ( is_wp_error( $fresh_review_consumption_claim ) ) {
			return $fresh_review_consumption_claim;
		}

		$fresh_review_consumption['_fresh_review_request_record'] = $fresh_review_consumption_claim['_fresh_review_request_record'];
	}

	$allow_sync_meta_script_during_save = ! current_user_can( 'unfiltered_html' );

	if ( $allow_sync_meta_script_during_save ) {
		wp_de_rtc_enable_sync_meta_script_kses_allowance();
	}

	global $wp_de_rtc_retry_save_candidate_post_content;

	if ( ! is_array( $wp_de_rtc_retry_save_candidate_post_content ) ) {
		$wp_de_rtc_retry_save_candidate_post_content = array();
	}

	$wp_de_rtc_retry_save_candidate_post_content[ (int) $post->ID ] = $candidate_post_content;

	$core_revision_hook_priority = wp_de_rtc_suspend_retry_save_core_revision_hook();

	try {
		$updated_post_id = wp_update_post(
			wp_slash(
				array(
					'ID'           => (int) $post->ID,
					'post_content' => $candidate_post_content,
				)
			),
			true
		);
	} finally {
		wp_de_rtc_restore_retry_save_core_revision_hook( $core_revision_hook_priority );
		unset( $wp_de_rtc_retry_save_candidate_post_content[ (int) $post->ID ] );

		if ( $allow_sync_meta_script_during_save ) {
			wp_de_rtc_disable_sync_meta_script_kses_allowance();
		}
	}

	if ( is_wp_error( $updated_post_id ) ) {
		if ( is_array( $fresh_review_consumption_claim ) ) {
			wp_de_rtc_release_opaque_fresh_review_decision_retry_save_consumption_claim( $fresh_review_consumption_claim['_fresh_review_request_record'], $post );
		}

		return $updated_post_id;
	}

	if ( ! $updated_post_id ) {
		if ( is_array( $fresh_review_consumption_claim ) ) {
			wp_de_rtc_release_opaque_fresh_review_decision_retry_save_consumption_claim( $fresh_review_consumption_claim['_fresh_review_request_record'], $post );
		}

		return wp_de_rtc_get_reason_error(
			'de_rtc_storage_failure',
			__( 'Distributed Editing could not save the retry update because the post update failed.' ),
			array(
				'detail'  => 'retry_save_post_update_failed',
				'post_id' => (int) $post->ID,
			)
		);
	}

	$persisted_post = get_post( $post->ID );

	if ( ! $persisted_post || ! hash_equals( $candidate_hash, wp_de_rtc_hash_content( $persisted_post->post_content ) ) ) {
		if ( is_array( $fresh_review_consumption_claim ) ) {
			wp_de_rtc_release_opaque_fresh_review_decision_retry_save_consumption_claim( $fresh_review_consumption_claim['_fresh_review_request_record'], $post );
		}

		return wp_de_rtc_get_reason_error(
			'de_rtc_storage_failure',
			__( 'Distributed Editing could not confirm that WordPress saved the retry update.' ),
			array(
				'detail'                              => 'retry_save_post_update_confirmation_failed',
				'post_id'                             => (int) $post->ID,
				'rest_route'                          => 'post_retry_save',
				'expected_saved_post_content_hash'    => $candidate_hash,
				'actual_saved_post_content_hash'      => $persisted_post ? wp_de_rtc_hash_content( $persisted_post->post_content ) : null,
				'saves_post'                          => false,
				'mutates_post_content'                => false,
				'creates_revision'                    => false,
				'claims_saved'                        => false,
			)
		);
	}

	$retry_save_revision_id = wp_de_rtc_put_retry_save_revision( $persisted_post );

	if ( is_wp_error( $retry_save_revision_id ) ) {
		if ( is_array( $fresh_review_consumption_claim ) ) {
			wp_de_rtc_release_opaque_fresh_review_decision_retry_save_consumption_claim( $fresh_review_consumption_claim['_fresh_review_request_record'], $post );
		}

		return $retry_save_revision_id;
	}

	$revision_ids_after_save = wp_de_rtc_get_post_revision_ids( $post->ID );
	$created_revision_ids    = array_values( array_diff( $revision_ids_after_save, $revision_ids_before_save ) );

	if ( $retry_save_revision_id && ! in_array( (int) $retry_save_revision_id, $created_revision_ids, true ) ) {
		$created_revision_ids[] = (int) $retry_save_revision_id;
	}

	$review_approval_proof_token_invalidated = false;
	$review_approval_proof_token_audit       = array();

	if (
		is_array( $review_approval_consumption ) &&
		! empty( $review_approval_consumption['review_approval_proof_consumed'] ) &&
		! empty( $review_approval_consumption['_review_approval_proof_token_transient_key'] )
	) {
		$review_approval_proof_token_invalidated = delete_transient( $review_approval_consumption['_review_approval_proof_token_transient_key'] );

		if ( ! empty( $review_approval_consumption['_review_approval_proof_token'] ) ) {
			$review_approval_proof_token_audit = wp_de_rtc_record_opaque_review_approval_proof_token_audit_event(
				$review_approval_consumption['_review_approval_proof_token'],
				'consumed',
				array(
					'post_id'                       => (int) $post->ID,
					'post_type'                     => $post->post_type,
					'server_version'                => $server_version,
					'proposed_post_content_hash'    => $proposed_post_content_hash,
					'candidate_post_content_hash'   => $candidate_hash,
					'reviewed_block_item_count'     => isset( $review_approval_consumption['reviewed_block_item_count'] ) ? (int) $review_approval_consumption['reviewed_block_item_count'] : 0,
					'rest_route'                    => 'post_retry_save',
					'storage_status'                => $review_approval_proof_token_invalidated ? 'transient_invalidated' : 'transient_invalidation_unconfirmed',
					'lifetime_status'               => 'consumed',
					'review_approval_proof_storage' => 'transient_with_option_backed_audit',
				)
			);
		}
	}

	$fresh_review_consumption_record = array();

	if (
		is_array( $fresh_review_consumption ) &&
		! empty( $fresh_review_consumption['fresh_review_decision_ready_for_retry_save'] )
	) {
		$fresh_review_consumption_record = wp_de_rtc_record_opaque_fresh_review_decision_retry_save_consumed(
			$fresh_review_consumption['_fresh_review_request_record'],
			$post,
			array(
				'updated_post_id'             => (int) $updated_post_id,
				'previous_server_version'     => $server_version,
				'server_version'              => $next_version,
				'proposed_post_content_hash'  => $proposed_post_content_hash,
				'saved_post_content_hash'     => $candidate_hash,
				'revision_created'            => ! empty( $created_revision_ids ),
				'created_revision_count'      => count( $created_revision_ids ),
			)
		);
	}

	$response = array(
		'mode'                                => 'retry_save',
		'result'                              => $retry_save_server_merge_required ? 'retry_save_server_merged' : 'retry_save_applied',
		'retry_save_accepted'                 => true,
		'rest_route'                          => 'post_retry_save',
		'post_id'                             => (int) $post->ID,
		'updated_post_id'                     => (int) $updated_post_id,
		'content'                             => array(
			'raw' => $candidate_post_content,
		),
		'client_base_version'                 => $client_base_version,
		'accepted_proof_server_version'       => $accepted_proof_server_version,
		'previous_server_version'             => $server_version,
		'server_version'                      => $next_version,
		'rebased_from_version'                => $rebased_from_version,
		'pending_change_count'                => $pending_change_count,
		'proposed_post_content_hash'          => $proposed_post_content_hash,
		'saved_stripped_post_content_hash'    => $save_post_content_hash,
		'saved_post_content_hash'             => $candidate_hash,
		'server_merge_applied'                => is_array( $server_merge_result ),
		'server_merge'                        => is_array( $server_merge_result ) ? wp_de_rtc_get_public_server_merge_evidence( $server_merge_result ) : null,
		'automerge_update_applied'                  => is_array( $automerge_retry_save_result ),
		'automerge_encoding'                        => wp_de_rtc_get_automerge_result_encoding( $automerge_retry_save_result ),
		'block_identity_request_proof_validated' => is_array( $block_identity_request_proof_validation ),
		'block_identity_request_proof'           => is_array( $block_identity_request_proof_validation ) ? array(
			'status'               => $block_identity_request_proof_validation['status'],
			'proposed_block_count' => $block_identity_request_proof_validation['proposed_block_count'],
			'retained_block_count' => $block_identity_request_proof_validation['retained_block_count'],
			'inserted_block_count' => $block_identity_request_proof_validation['inserted_block_count'],
			'deleted_block_count'  => $block_identity_request_proof_validation['deleted_block_count'],
			'moved_block_count'    => $block_identity_request_proof_validation['moved_block_count'],
			'content_free'         => true,
			'saves_post'           => false,
			'mutates_post_content' => false,
			'creates_revision'     => false,
			'changes_post_lock'    => false,
			'claims_saved'         => false,
		) : null,
		'review_approval_proof_consumed'          => is_array( $review_approval_consumption ) && ! empty( $review_approval_consumption['review_approval_proof_consumed'] ),
		'review_approval_proof_token_invalidated' => $review_approval_proof_token_invalidated,
		'review_approval_proof_token_audit'       => wp_de_rtc_get_opaque_review_approval_proof_token_audit_public_evidence( $review_approval_proof_token_audit ),
		'reviewed_block_item_count'               => is_array( $review_approval_consumption ) ? $review_approval_consumption['reviewed_block_item_count'] : 0,
		'fresh_review_decision_consumed'          => is_array( $fresh_review_consumption ) && ! empty( $fresh_review_consumption['fresh_review_decision_ready_for_retry_save'] ),
		'fresh_review_decision_consumption_recorded' => is_array( $fresh_review_consumption_record ) && ! empty( $fresh_review_consumption_record['recorded'] ),
		'fresh_review_request_record_id'          => is_array( $fresh_review_consumption ) && isset( $fresh_review_consumption['fresh_review_request_record_id'] ) ? $fresh_review_consumption['fresh_review_request_record_id'] : null,
		'fresh_review_request_record'             => is_array( $fresh_review_consumption_record ) ? $fresh_review_consumption_record : null,
		'requires_server_state_refetch'           => false,
		'requires_manual_conflict_resolution'     => false,
		'can_export_local_updates'                => false,
		'save_path_required'                      => false,
		'saves_post'                              => true,
		'mutates_post_content'                    => true,
		'creates_revision'                        => ! empty( $created_revision_ids ),
		'claims_saved'                            => true,
		'revision_ids_before_save'                => $revision_ids_before_save,
		'revision_ids_after_save'                 => $revision_ids_after_save,
		'created_revision_ids'                    => $created_revision_ids,
		'revision_created'                        => ! empty( $created_revision_ids ),
		'permission_contract'                     => wp_de_rtc_get_rest_recovery_permission_contract( $post ),
	);

	if ( ! empty( $response['fresh_review_decision_consumed'] ) ) {
		unset( $response['content'] );
		$response['raw_content_included'] = false;
	}

	return $response;
}

/**
 * Rejects explicit stale-base probes in the REST post update save path.
 *
 * This is a proof-only save-path boundary. It recognizes only explicit
 * `de_rtc_stale_base_probe` requests and otherwise returns the prepared post
 * unchanged so ordinary REST saves continue through the existing controller.
 *
 * @since 7.1.0
 *
 * @param stdClass|WP_Error $prepared_post Prepared post object or an earlier error.
 * @param WP_REST_Request   $request       Request object.
 * @return stdClass|WP_Error Prepared post when no probe is present, otherwise a stale-base error.
 */
function wp_de_rtc_rest_pre_insert_stale_base_probe( $prepared_post, $request ) {
	if ( ! wp_de_rtc_is_rest_save_stale_base_probe_request( $request ) || is_wp_error( $prepared_post ) ) {
		return $prepared_post;
	}

	$post_id = 0;

	if ( is_object( $prepared_post ) && isset( $prepared_post->ID ) ) {
		$post_id = (int) $prepared_post->ID;
	}

	if ( ! $post_id && isset( $request['id'] ) ) {
		$post_id = (int) $request['id'];
	}

	$post = get_post( $post_id );

	if ( ! $post || ! wp_de_rtc_rest_save_probe_request_matches_post_type( $request, $post ) ) {
		return new WP_Error(
			'rest_post_invalid_id',
			__( 'Invalid post ID.' ),
			array( 'status' => 404 )
		);
	}

	if ( ! current_user_can( 'edit_post', $post->ID ) ) {
		return new WP_Error(
			'rest_cannot_edit',
			__( 'Sorry, you are not allowed to edit this post.' ),
			array( 'status' => rest_authorization_required_code() )
		);
	}

	if ( ! wp_de_rtc_is_enabled_for_post( $post ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_feature_disabled',
			__( 'Distributed Editing is not enabled for this post.' ),
			array(
				'detail'  => 'feature_disabled_for_post',
				'post_id' => (int) $post->ID,
			)
		);
	}

	return wp_de_rtc_get_stale_base_rejection_error(
		$post,
		array(
			'client_base_version'      => $request->get_param( 'client_base_version' ),
			'server_version'           => $request->get_param( 'server_version' ),
			'pending_change_count'     => $request->get_param( 'pending_change_count' ),
			'remote_change_count'      => $request->get_param( 'remote_change_count' ),
			'can_attempt_local_rebase' => $request->get_param( 'can_attempt_local_rebase' ),
			'rest_route'               => wp_de_rtc_get_rest_save_probe_response_route( $request ),
		)
	);
}

/**
 * Returns whether a REST post save request explicitly asks for stale-base proof.
 *
 * @since 7.1.0
 *
 * @param WP_REST_Request $request Request object.
 * @return bool Whether the request is a stale-base proof probe.
 */
function wp_de_rtc_is_rest_save_stale_base_probe_request( $request ) {
	return wp_validate_boolean( $request->get_param( 'de_rtc_stale_base_probe' ) );
}

/**
 * Returns whether the REST save request route matches the post type REST base.
 *
 * @since 7.1.0
 *
 * @param WP_REST_Request $request Request object.
 * @param WP_Post         $post    Post object.
 * @return bool Whether the requested route matches the post type REST base.
 */
function wp_de_rtc_rest_save_probe_request_matches_post_type( $request, $post ) {
	$requested_rest_base = wp_de_rtc_get_rest_save_probe_request_rest_base( $request );
	$post_rest_base      = wp_de_rtc_get_post_type_rest_base( $post->post_type );
	$supported_bases     = wp_de_rtc_get_rest_recovery_post_type_rest_bases();

	return (
		'' !== $requested_rest_base &&
		'' !== $post_rest_base &&
		$requested_rest_base === $post_rest_base &&
		in_array( $post_rest_base, $supported_bases, true )
	);
}

/**
 * Returns the post type REST base from a REST save probe request route.
 *
 * @since 7.1.0
 *
 * @param WP_REST_Request $request Request object.
 * @return string Requested post type REST base, or empty string.
 */
function wp_de_rtc_get_rest_save_probe_request_rest_base( $request ) {
	$route = $request->get_route();

	if ( ! is_string( $route ) ) {
		return '';
	}

	if ( ! preg_match( '#^/wp/v2/([^/]+)/\d+(?:/autosaves)?$#', $route, $matches ) ) {
		return '';
	}

	return sanitize_key( $matches[1] );
}

/**
 * Returns the response route label for a REST save probe request.
 *
 * @since 7.1.0
 *
 * @param WP_REST_Request $request Request object.
 * @return string Response route label.
 */
function wp_de_rtc_get_rest_save_probe_response_route( $request ) {
	$route = $request->get_route();

	if ( is_string( $route ) && preg_match( '#/autosaves$#', $route ) ) {
		return 'post_autosave_stale_base_probe';
	}

	return 'post_save_stale_base_probe';
}

/**
 * Returns the canonical stale-base rejection error.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post Post ID or object.
 * @param array       $args {
 *     Optional stale-base rejection data.
 *
 *     @type mixed  $client_base_version      Client base version.
 *     @type mixed  $server_version           Server version known to the caller.
 *     @type mixed  $pending_change_count     Pending local change count. Default 1.
 *     @type mixed  $remote_change_count      Remote change count. Default 1.
 *     @type mixed  $can_attempt_local_rebase Whether the client thinks it can rebase. Default false.
 *     @type string $rest_route               Response route label. Default 'post_stale_base_rejection'.
 * }
 * @return WP_Error Stale-base rejection error with normalized DE-RTC data.
 */
function wp_de_rtc_get_stale_base_rejection_error( $post, $args = array() ) {
	$post                     = get_post( $post );
	$post_id                  = $post ? (int) $post->ID : 0;
	$pending_change_count     = array_key_exists( 'pending_change_count', $args ) ? max( 0, (int) $args['pending_change_count'] ) : 1;
	$remote_change_count      = array_key_exists( 'remote_change_count', $args ) ? max( 0, (int) $args['remote_change_count'] ) : 1;
	$can_attempt_local_rebase = ! empty( $args['can_attempt_local_rebase'] ) && wp_validate_boolean( $args['can_attempt_local_rebase'] );
	$requires_server_refetch  = true;
	$client_base_version      = isset( $args['client_base_version'] ) ? sanitize_text_field( (string) $args['client_base_version'] ) : '';
	$server_version           = isset( $args['server_version'] ) ? $args['server_version'] : null;
	$server_version           = is_string( $server_version ) && '' !== $server_version
		? sanitize_text_field( $server_version )
		: ( $post ? wp_de_rtc_get_post_sync_meta_version( $post ) : null );
	$can_attempt_local_rebase = $can_attempt_local_rebase && ! $requires_server_refetch;
	$permission_contract      = wp_de_rtc_get_rest_recovery_permission_contract( $post );
	$rest_route               = isset( $args['rest_route'] ) ? sanitize_key( $args['rest_route'] ) : 'post_stale_base_rejection';

	return wp_de_rtc_get_reason_error(
		'stale_base_version_rejected',
		__( 'Distributed Editing rejected the update because the client base version is stale.' ),
		array(
			'detail'                              => 'stale_base_version_rejected',
			'post_id'                             => $post_id,
			'client_base_version'                 => $client_base_version,
			'server_version'                      => $server_version,
			'pending_change_count'                => $pending_change_count,
			'remote_change_count'                 => $remote_change_count,
			'requires_server_state_refetch'       => $requires_server_refetch,
			'can_attempt_local_rebase'            => $can_attempt_local_rebase,
			'requires_manual_conflict_resolution' => false,
			'can_export_local_updates'            => $pending_change_count > 0,
			'rest_route'                          => $rest_route,
			'saves_post'                          => ! empty( $args['saves_post'] ) && wp_validate_boolean( $args['saves_post'] ),
			'mutates_post_content'                => ! empty( $args['mutates_post_content'] ) && wp_validate_boolean( $args['mutates_post_content'] ),
			'creates_revision'                    => ! empty( $args['creates_revision'] ) && wp_validate_boolean( $args['creates_revision'] ),
			'claims_saved'                        => ! empty( $args['claims_saved'] ) && wp_validate_boolean( $args['claims_saved'] ),
			'permission_contract'                 => $permission_contract,
		)
	);
}

/**
 * Returns KSES comparison evidence for post content.
 *
 * This helper mirrors the post-content KSES save filter in memory so DE-RTC can
 * reject before persistence when a non-unfiltered user submits content that the
 * save path would alter. It does not save, update posts, or create revisions.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $post_content Post content to inspect.
 * @param array  $args {
 *     Optional KSES review behavior.
 *
 *     @type bool $allow_sync_meta_script Whether to allow server-owned sync-meta SCRIPT markup.
 *                                        Default false.
 * }
 * @return array KSES comparison evidence.
 */
function wp_de_rtc_get_kses_post_content_review_evidence( $post_content, $args = array() ) {
	$post_content           = (string) $post_content;
	$allow_sync_meta_script = ! empty( $args['allow_sync_meta_script'] );
	$filtered_post_content  = wp_de_rtc_get_kses_filtered_post_content(
		$post_content,
		array(
			'allow_sync_meta_script' => $allow_sync_meta_script,
		)
	);

	return array(
		'filter'                  => 'wp_filter_post_kses',
		'filter_context'          => 'content_save_pre',
		'allows_sync_meta_script' => $allow_sync_meta_script,
		'would_change_content'    => $filtered_post_content !== $post_content,
		'content_hash'            => wp_de_rtc_hash_content( $post_content ),
		'filtered_content_hash'   => wp_de_rtc_hash_content( $filtered_post_content ),
	);
}

/**
 * Returns post content after the same KSES filtering used for post saves.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $post_content Post content to filter.
 * @param array  $args {
 *     Optional KSES review behavior.
 *
 *     @type bool $allow_sync_meta_script Whether to allow server-owned sync-meta SCRIPT markup.
 *                                        Default false.
 * }
 * @return string KSES-filtered post content.
 */
function wp_de_rtc_get_kses_filtered_post_content( $post_content, $args = array() ) {
	$post_content           = (string) $post_content;
	$allow_sync_meta_script = ! empty( $args['allow_sync_meta_script'] );

	if ( $allow_sync_meta_script ) {
		wp_de_rtc_enable_sync_meta_script_kses_allowance();
	}

	try {
		$filtered_post_content = wp_unslash( wp_filter_post_kses( wp_slash( $post_content ) ) );
	} finally {
		if ( $allow_sync_meta_script ) {
			wp_de_rtc_disable_sync_meta_script_kses_allowance();
		}
	}

	return $filtered_post_content;
}

/**
 * Classifies block-level KSES review items for proposed post content.
 *
 * This helper compares the current stripped post content with proposed stripped
 * content and returns hash-only evidence for changed blocks that intersect
 * unfiltered HTML capability boundaries. It does not return raw block content,
 * save posts, create revisions, register REST behavior, replace post locks, or
 * claim saved state.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post                  Post ID or object.
 * @param string      $proposed_post_content Proposed post content without sync metadata.
 * @param array       $args {
 *     Optional classification arguments.
 *
 *     @type string|null $base_post_content        Base post content without sync metadata. Defaults to the current post content.
 *     @type mixed       $client_base_version      Client base version. Defaults to the current sync-meta version.
 *     @type mixed       $server_version           Server version. Defaults to the current sync-meta version.
 *     @type bool        $user_can_unfiltered_html Whether the editing user can publish unfiltered HTML. Defaults to current user capability.
 *     @type int|null    $author_id                Author of the proposed changes, when known.
 * }
 * @return array|WP_Error Hash-only risky block review classification.
 */
function wp_de_rtc_classify_kses_risky_block_review_items( $post, $proposed_post_content, $args = array() ) {
	$post = get_post( $post );

	if ( ! $post ) {
		return new WP_Error(
			'rest_post_invalid_id',
			__( 'Invalid post ID.' ),
			array( 'status' => 404 )
		);
	}

	if ( ! is_string( $proposed_post_content ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing could not classify KSES review items because proposed post content is missing.' ),
			array(
				'detail'               => 'missing_kses_block_review_proposed_content',
				'post_id'              => (int) $post->ID,
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$current = wp_de_rtc_parse_post_content_sync_meta( $post->post_content );

	if ( is_wp_error( $current ) ) {
		return $current;
	}

	$base_post_content = isset( $args['base_post_content'] ) && is_string( $args['base_post_content'] )
		? $args['base_post_content']
		: $current['content'];
	$server_version    = isset( $args['server_version'] ) ? sanitize_text_field( (string) $args['server_version'] ) : wp_de_rtc_get_post_sync_meta_version( $post );
	$client_base_version = isset( $args['client_base_version'] ) ? sanitize_text_field( (string) $args['client_base_version'] ) : $server_version;
	$user_can_unfiltered_html = array_key_exists( 'user_can_unfiltered_html', $args )
		? (bool) $args['user_can_unfiltered_html']
		: current_user_can( 'unfiltered_html' );
	$author_id         = isset( $args['author_id'] ) ? (int) $args['author_id'] : get_current_user_id();

	$review_items = array();

	if ( ! $user_can_unfiltered_html ) {
		$base_records     = wp_de_rtc_get_kses_block_review_records( $base_post_content );
		$proposed_records = wp_de_rtc_get_kses_block_review_records( $proposed_post_content );
		$base_records_by_hash = wp_de_rtc_get_kses_block_review_records_by_hash( $base_records );
		$matched_base_record_keys = array();
		$matched_proposed_record_keys = array();

		foreach ( $proposed_records as $path_key => $proposed_record ) {
			$base_record = isset( $base_records[ $path_key ] ) ? $base_records[ $path_key ] : null;

			if ( is_array( $base_record ) && $base_record['serialized_block'] === $proposed_record['serialized_block'] ) {
				$matched_base_record_keys[ $path_key ]     = true;
				$matched_proposed_record_keys[ $path_key ] = true;
			}
		}

		foreach ( $proposed_records as $path_key => $proposed_record ) {
			if ( isset( $matched_proposed_record_keys[ $path_key ] ) ) {
				continue;
			}

			$matched_base_record_key = wp_de_rtc_find_matching_kses_block_review_record_key(
				$base_records_by_hash,
				wp_de_rtc_hash_content( $proposed_record['serialized_block'] ),
				$matched_base_record_keys
			);

			if ( null !== $matched_base_record_key ) {
				$matched_base_record_keys[ $matched_base_record_key ] = true;
				$matched_proposed_record_keys[ $path_key ]            = true;
			}
		}

		foreach ( $proposed_records as $path_key => $proposed_record ) {
			if ( isset( $matched_proposed_record_keys[ $path_key ] ) ) {
				continue;
			}

			$proposed_record_is_top_level_insert = wp_de_rtc_is_kses_top_level_inserted_review_record(
				$base_post_content,
				$proposed_post_content,
				$proposed_record
			);
			$base_record                         = isset( $base_records[ $path_key ] ) && ! isset( $matched_base_record_keys[ $path_key ] ) && ! $proposed_record_is_top_level_insert ? $base_records[ $path_key ] : null;

			$proposed_review      = wp_de_rtc_get_kses_post_content_review_evidence( $proposed_record['serialized_block'] );
			$proposed_own_review  = wp_de_rtc_get_kses_post_content_review_evidence( $proposed_record['serialized_own_block'] );
			$base_review          = is_array( $base_record ) ? wp_de_rtc_get_kses_post_content_review_evidence( $base_record['serialized_block'] ) : null;
			$base_own_review      = is_array( $base_record ) ? wp_de_rtc_get_kses_post_content_review_evidence( $base_record['serialized_own_block'] ) : null;

			if ( is_array( $base_record ) ) {
				$requires_review = wp_de_rtc_modified_kses_block_change_requires_review(
					$base_record['serialized_own_block'],
					$proposed_record['serialized_own_block'],
					$base_own_review,
					$proposed_own_review
				);
			} else {
				$requires_review = wp_de_rtc_added_kses_block_change_requires_review(
					$proposed_record['serialized_own_block'],
					$proposed_own_review
				);
			}

			if ( ! $requires_review ) {
				if ( is_array( $base_record ) ) {
					$matched_base_record_keys[ $path_key ] = true;
				}

				continue;
			}

			$change_kind = is_array( $base_record ) ? 'modified_block' : 'added_block';
			$review_items[] = wp_de_rtc_create_kses_block_review_item(
				$proposed_record,
				array(
					'change_kind'                 => $change_kind,
					'risk_reason'                 => wp_de_rtc_get_kses_block_review_risk_reason( $change_kind, $base_review, $proposed_review, $proposed_record['serialized_block'] ),
					'author_id'                   => $author_id,
					'base_version'                => $client_base_version,
					'server_version'              => $server_version,
					'base_content_hash'           => is_array( $base_record ) ? wp_de_rtc_hash_content( $base_record['serialized_block'] ) : wp_de_rtc_hash_content( '' ),
					'proposed_content_hash'       => $proposed_review['content_hash'],
					'kses_filtered_content_hash'  => $proposed_review['filtered_content_hash'],
				)
			);

			if ( is_array( $base_record ) ) {
				$matched_base_record_keys[ $path_key ] = true;
			}
		}

		// Base-only records are deletions. Removing KSES-sensitive content does
		// not persist unsafe markup, so deletion-only changes need no review.
	}

	$review_required = ! $user_can_unfiltered_html && ! empty( $review_items );

	return array(
		'result'                      => $review_required ? 'block_review_required' : 'no_review_required',
		'reason_code'                 => $review_required ? 'de_rtc_unfiltered_html_would_change_content' : null,
		'post_id'                     => (int) $post->ID,
		'rest_base'                   => wp_de_rtc_get_post_type_rest_base( $post->post_type ),
		'user_can_unfiltered_html'    => $user_can_unfiltered_html,
		'required_capability'         => 'unfiltered_html',
		'content_review_policy'       => 'kses',
		'review_evidence_type'        => 'kses_block_hash_only_change',
		'server_version'              => $server_version,
		'client_base_version'         => $client_base_version,
		'review_items'                => $review_items,
		'review_item_count'           => count( $review_items ),
		'pending_review_item_count'   => $review_required ? count( $review_items ) : 0,
		'pre_publish_review_required' => $review_required,
		'save_action'                 => $review_required ? 'open_pre_publish_review' : 'continue_save',
		'raw_content_included'        => false,
		'exposes_raw_content'         => false,
		'saves_post'                  => false,
		'mutates_post_content'        => false,
		'creates_revision'            => false,
		'claims_saved'                => false,
	);
}

/**
 * Returns a safe stripped candidate for a retry-save that also needs KSES review.
 *
 * The candidate is intentionally conservative: only same-count top-level
 * modified blocks can be reverted to the current server block. This lets
 * WordPress absorb already-persisted safe edits without guessing at identity for
 * added, removed, nested, or reordered blocks.
 *
 * @since 7.1.0
 * @access private
 *
 * @param int|WP_Post $post             Post ID or object.
 * @param string      $current_content  Current stripped server content.
 * @param string      $proposed_content Proposed stripped retry-save content.
 * @param array       $args             Optional classification arguments.
 * @return array|WP_Error|null Partial-safe plan, an error, or null when review is not required.
 */
function wp_de_rtc_get_kses_partial_safe_retry_save_plan( $post, $current_content, $proposed_content, $args = array() ) {
	$classification = wp_de_rtc_classify_kses_risky_block_review_items(
		$post,
		$proposed_content,
		array(
			'base_post_content'        => $current_content,
			'client_base_version'      => isset( $args['client_base_version'] ) ? $args['client_base_version'] : null,
			'server_version'           => isset( $args['server_version'] ) ? $args['server_version'] : null,
			'user_can_unfiltered_html' => false,
			'author_id'                => get_current_user_id(),
		)
	);

	if ( is_wp_error( $classification ) ) {
		return $classification;
	}

	if ( empty( $classification['review_items'] ) ) {
		return null;
	}

	$safe_candidate = wp_de_rtc_get_kses_partial_safe_top_level_candidate(
		$current_content,
		$proposed_content,
		$classification['review_items']
	);

	if ( is_wp_error( $safe_candidate ) ) {
		return array(
			'review_classification'       => $classification,
			'safe_candidate_available'   => false,
			'safe_candidate_blocked'     => true,
			'safe_candidate_blocked_code' => $safe_candidate->get_error_code(),
			'safe_candidate_blocked_data' => $safe_candidate->get_error_data(),
		);
	}

	$safe_candidate_classification = wp_de_rtc_classify_kses_risky_block_review_items(
		$post,
		$safe_candidate,
		array(
			'base_post_content'        => $current_content,
			'client_base_version'      => isset( $args['client_base_version'] ) ? $args['client_base_version'] : null,
			'server_version'           => isset( $args['server_version'] ) ? $args['server_version'] : null,
			'user_can_unfiltered_html' => false,
			'author_id'                => get_current_user_id(),
		)
	);

	if ( is_wp_error( $safe_candidate_classification ) ) {
		return $safe_candidate_classification;
	}

	$safe_candidate_review_items = isset( $safe_candidate_classification['review_items'] ) && is_array( $safe_candidate_classification['review_items'] )
		? array_values( $safe_candidate_classification['review_items'] )
		: array();

	if ( ! empty( $safe_candidate_review_items ) ) {
		return array(
			'review_classification'       => $classification,
			'safe_candidate_available'   => false,
			'safe_candidate_blocked'     => true,
			'safe_candidate_blocked_code' => 'de_rtc_rebase_failed',
			'safe_candidate_blocked_data' => array(
				'detail'                       => 'partial_safe_merge_candidate_still_requires_kses',
				'review_item_count'            => count( $safe_candidate_review_items ),
				'saves_post'                   => false,
				'mutates_post_content'         => false,
				'creates_revision'             => false,
				'claims_saved'                 => false,
				'unsafe_raw_content_included'  => false,
			),
		);
	}

	return array(
		'review_classification'     => $classification,
		'safe_candidate_available' => true,
		'safe_post_content'        => $safe_candidate,
		'safe_post_content_hash'   => wp_de_rtc_hash_content( $safe_candidate ),
	);
}

/**
 * Reverts unsafe top-level modified blocks to the current server block.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $current_content  Current stripped server content.
 * @param string $proposed_content Proposed stripped retry-save content.
 * @param array  $review_items     Hash-only KSES review items.
 * @return string|WP_Error Safe stripped candidate or an error when the shape is not safe.
 */
function wp_de_rtc_get_kses_partial_safe_top_level_candidate( $current_content, $proposed_content, $review_items ) {
	$current_blocks  = parse_blocks( (string) $current_content );
	$proposed_blocks = parse_blocks( (string) $proposed_content );
	$safe_blocks     = $proposed_blocks;
	$drop_paths      = array();

	foreach ( $review_items as $review_item ) {
		$block_path  = isset( $review_item['block_path'] ) && is_array( $review_item['block_path'] ) ? array_values( array_map( 'absint', $review_item['block_path'] ) ) : array();
		$change_kind = isset( $review_item['change_kind'] ) ? sanitize_key( (string) $review_item['change_kind'] ) : '';

		if ( empty( $block_path ) || ! in_array( $change_kind, array( 'added_block', 'modified_block' ), true ) ) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_rebase_failed',
				__( 'Distributed Editing could not isolate safe retry-save changes for review.' ),
				array(
					'detail'               => 'partial_safe_merge_unsupported_review_block_shape',
					'saves_post'           => false,
					'mutates_post_content' => false,
					'creates_revision'     => false,
					'claims_saved'         => false,
				)
			);
		}

		$proposed_block = wp_de_rtc_get_block_at_path( $safe_blocks, $block_path );
		$current_block  = wp_de_rtc_get_block_at_path( $current_blocks, $block_path );

		if ( ! is_array( $proposed_block ) ) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_rebase_failed',
				__( 'Distributed Editing could not isolate safe retry-save changes for review.' ),
				array(
					'detail'               => 'partial_safe_merge_review_block_index_missing',
					'saves_post'           => false,
					'mutates_post_content' => false,
					'creates_revision'     => false,
					'claims_saved'         => false,
				)
			);
		}

		if (
			isset( $review_item['proposed_content_hash'] ) &&
			! hash_equals( sanitize_text_field( (string) $review_item['proposed_content_hash'] ), wp_de_rtc_hash_content( serialize_block( $proposed_block ) ) )
		) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_rebase_failed',
				__( 'Distributed Editing could not isolate safe retry-save changes for review.' ),
				array(
					'detail'               => 'partial_safe_merge_review_proposed_hash_mismatch',
					'saves_post'           => false,
					'mutates_post_content' => false,
					'creates_revision'     => false,
					'claims_saved'         => false,
				)
			);
		}

		if ( 'added_block' === $change_kind ) {
			if (
				isset( $review_item['base_content_hash'] ) &&
				! hash_equals( sanitize_text_field( (string) $review_item['base_content_hash'] ), wp_de_rtc_hash_content( '' ) )
			) {
				return wp_de_rtc_get_reason_error(
					'de_rtc_rebase_failed',
					__( 'Distributed Editing could not isolate safe retry-save changes for review.' ),
					array(
						'detail'               => 'partial_safe_merge_review_base_hash_mismatch',
						'saves_post'           => false,
							'mutates_post_content' => false,
							'creates_revision'     => false,
							'claims_saved'         => false,
						)
				);
			}

			$drop_paths[] = $block_path;
			continue;
		}

		if ( ! is_array( $current_block ) ) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_rebase_failed',
				__( 'Distributed Editing could not isolate safe retry-save changes for review.' ),
				array(
					'detail'               => 'partial_safe_merge_review_block_index_missing',
					'saves_post'           => false,
					'mutates_post_content' => false,
					'creates_revision'     => false,
					'claims_saved'         => false,
				)
			);
		}

		if (
			isset( $review_item['base_content_hash'] ) &&
			! hash_equals( sanitize_text_field( (string) $review_item['base_content_hash'] ), wp_de_rtc_hash_content( serialize_block( $current_block ) ) )
		) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_rebase_failed',
				__( 'Distributed Editing could not isolate safe retry-save changes for review.' ),
				array(
					'detail'               => 'partial_safe_merge_review_base_hash_mismatch',
					'saves_post'           => false,
					'mutates_post_content' => false,
					'creates_revision'     => false,
					'claims_saved'         => false,
				)
			);
		}

		$set_result = wp_de_rtc_set_block_at_path( $safe_blocks, $block_path, $current_block );

		if ( is_wp_error( $set_result ) ) {
			return $set_result;
		}

		$safe_blocks = $set_result;
	}

	if ( ! empty( $drop_paths ) ) {
		usort(
			$drop_paths,
			static function ( $a, $b ) {
				return count( $b ) <=> count( $a ) ?: strcmp( implode( '.', $b ), implode( '.', $a ) );
			}
		);

		foreach ( $drop_paths as $drop_path ) {
			$remove_result = wp_de_rtc_remove_block_at_path( $safe_blocks, $drop_path );

			if ( is_wp_error( $remove_result ) ) {
				return $remove_result;
			}

			$safe_blocks = $remove_result;
		}
	}

	$safe_candidate = serialize_blocks( wp_de_rtc_remove_empty_freeform_blocks( $safe_blocks ) );
	$current_canonical_content = serialize_blocks( wp_de_rtc_remove_empty_freeform_blocks( parse_blocks( (string) $current_content ) ) );

	if ( hash_equals( wp_de_rtc_hash_content( $current_canonical_content ), wp_de_rtc_hash_content( $safe_candidate ) ) ) {
		return $current_content;
	}

	return $safe_candidate;
}

/**
 * Returns the parsed block at a retained ordinal path.
 *
 * KSES review paths intentionally describe parsed block positions, not
 * Gutenberg client IDs. This keeps the server-side partial-safe rewrite tied to
 * the same parsed post tree that WordPress will eventually serialize.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $blocks Parsed block list.
 * @param int[] $path   Retained block path.
 * @return array|null Parsed block, or null when the path is unavailable.
 */
function wp_de_rtc_get_block_at_path( $blocks, $path ) {
	$blocks = array_values( (array) $blocks );
	$path   = array_values( (array) $path );

	if ( empty( $path ) ) {
		return null;
	}

	$retained_index = array_shift( $path );
	$index          = wp_de_rtc_get_retained_block_raw_index( $blocks, $retained_index );

	if ( null === $index || ! array_key_exists( $index, $blocks ) || ! is_array( $blocks[ $index ] ) ) {
		return null;
	}

	if ( empty( $path ) ) {
		return $blocks[ $index ];
	}

	if ( empty( $blocks[ $index ]['innerBlocks'] ) || ! is_array( $blocks[ $index ]['innerBlocks'] ) ) {
		return null;
	}

	return wp_de_rtc_get_block_at_path( $blocks[ $index ]['innerBlocks'], $path );
}

/**
 * Replaces the parsed block at a retained ordinal path.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $blocks      Parsed block list.
 * @param int[] $path        Retained block path.
 * @param array $replacement Replacement block.
 * @return array|WP_Error Updated parsed block list or an error.
 */
function wp_de_rtc_set_block_at_path( $blocks, $path, $replacement ) {
	$blocks = array_values( (array) $blocks );
	$path   = array_values( (array) $path );

	if ( empty( $path ) || ! is_array( $replacement ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_rebase_failed',
			__( 'Distributed Editing could not isolate safe retry-save changes for review.' ),
			array(
				'detail'               => 'partial_safe_merge_review_block_index_missing',
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$retained_index = array_shift( $path );
	$index          = wp_de_rtc_get_retained_block_raw_index( $blocks, $retained_index );

	if ( null === $index || ! array_key_exists( $index, $blocks ) || ! is_array( $blocks[ $index ] ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_rebase_failed',
			__( 'Distributed Editing could not isolate safe retry-save changes for review.' ),
			array(
				'detail'               => 'partial_safe_merge_review_block_index_missing',
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	if ( empty( $path ) ) {
		$blocks[ $index ] = $replacement;

		return $blocks;
	}

	$inner_blocks = isset( $blocks[ $index ]['innerBlocks'] ) && is_array( $blocks[ $index ]['innerBlocks'] )
		? $blocks[ $index ]['innerBlocks']
		: array();
	$inner_result = wp_de_rtc_set_block_at_path( $inner_blocks, $path, $replacement );

	if ( is_wp_error( $inner_result ) ) {
		return $inner_result;
	}

	$blocks[ $index ]['innerBlocks'] = $inner_result;

	return $blocks;
}

/**
 * Removes the parsed block at a retained ordinal path.
 *
 * The parent `innerContent` null marker must be removed with the child, or
 * WordPress serialization would pull the wrong remaining inner block into that
 * slot.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $blocks Parsed block list.
 * @param int[] $path   Retained block path.
 * @return array|WP_Error Updated parsed block list or an error.
 */
function wp_de_rtc_remove_block_at_path( $blocks, $path ) {
	$blocks = array_values( (array) $blocks );
	$path   = array_values( (array) $path );

	if ( empty( $path ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_rebase_failed',
			__( 'Distributed Editing could not isolate safe retry-save changes for review.' ),
			array(
				'detail'               => 'partial_safe_merge_review_block_index_missing',
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$retained_index = array_shift( $path );
	$index          = wp_de_rtc_get_retained_block_raw_index( $blocks, $retained_index );

	if ( null === $index || ! array_key_exists( $index, $blocks ) || ! is_array( $blocks[ $index ] ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_rebase_failed',
			__( 'Distributed Editing could not isolate safe retry-save changes for review.' ),
			array(
				'detail'               => 'partial_safe_merge_review_block_index_missing',
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	if ( empty( $path ) ) {
		unset( $blocks[ $index ] );

		return array_values( $blocks );
	}

	$inner_blocks = isset( $blocks[ $index ]['innerBlocks'] ) && is_array( $blocks[ $index ]['innerBlocks'] )
		? $blocks[ $index ]['innerBlocks']
		: array();
	$inner_result = wp_de_rtc_remove_block_at_path( $inner_blocks, $path );

	if ( is_wp_error( $inner_result ) ) {
		return $inner_result;
	}

	$blocks[ $index ]['innerBlocks'] = $inner_result;

	if ( 1 === count( $path ) ) {
		$blocks[ $index ]['innerContent'] = wp_de_rtc_remove_inner_content_block_slot(
			isset( $blocks[ $index ]['innerContent'] ) && is_array( $blocks[ $index ]['innerContent'] ) ? $blocks[ $index ]['innerContent'] : array(),
			(int) $path[0]
		);
	}

	return $blocks;
}

/**
 * Returns the raw parsed-block array index for a retained ordinal.
 *
 * `parse_blocks()` preserves whitespace-only freeform records. KSES review
 * paths skip those empty records, so partial-safe rewrites have to translate
 * from retained ordinals back to the raw parsed array before reading or
 * replacing blocks.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $blocks         Parsed block list.
 * @param int   $retained_index Retained block ordinal.
 * @return int|null Raw array index, or null when not found.
 */
function wp_de_rtc_get_retained_block_raw_index( $blocks, $retained_index ) {
	$current_retained_index = 0;

	foreach ( (array) $blocks as $raw_index => $block ) {
		if ( ! is_array( $block ) ) {
			continue;
		}

		$serialized_block = serialize_block( $block );

		if ( empty( $block['blockName'] ) && '' === trim( $serialized_block ) ) {
			continue;
		}

		if ( $current_retained_index === (int) $retained_index ) {
			return (int) $raw_index;
		}

		++$current_retained_index;
	}

	return null;
}

/**
 * Removes whitespace-only freeform records from a parsed block tree.
 *
 * The older partial-safe writer rebuilt documents from serialized block tokens,
 * so empty separators were not durable save evidence. Keeping that canonical
 * shape prevents a review-only rejection from rewriting a post solely because
 * `parse_blocks()` preserved formatting whitespace around the unsafe block.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $blocks Parsed block list.
 * @return array Parsed block list without empty freeform records.
 */
function wp_de_rtc_remove_empty_freeform_blocks( $blocks ) {
	$next_blocks = array();

	foreach ( (array) $blocks as $block ) {
		if ( ! is_array( $block ) ) {
			continue;
		}

		$serialized_block = serialize_block( $block );

		if ( empty( $block['blockName'] ) && '' === trim( $serialized_block ) ) {
			continue;
		}

		if ( ! empty( $block['innerBlocks'] ) && is_array( $block['innerBlocks'] ) ) {
			$block['innerBlocks'] = wp_de_rtc_remove_empty_freeform_blocks( $block['innerBlocks'] );
		}

		$next_blocks[] = $block;
	}

	return $next_blocks;
}

/**
 * Removes the nth inner-block null slot from `innerContent`.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $inner_content Parsed block innerContent.
 * @param int   $child_index   Retained child block index to remove.
 * @return array Updated innerContent.
 */
function wp_de_rtc_remove_inner_content_block_slot( $inner_content, $child_index ) {
	$next_inner_content = array();
	$null_index         = 0;

	foreach ( (array) $inner_content as $chunk ) {
		if ( null === $chunk ) {
			if ( $null_index === (int) $child_index ) {
				++$null_index;
				continue;
			}

			++$null_index;
		}

		$next_inner_content[] = $chunk;
	}

	return $next_inner_content;
}

/**
 * Checks whether a proposed risky block is a top-level insertion.
 *
 * The KSES review classifier compares flattened block records by path before a
 * durable block identity contract exists for this path. When an unsafe block is
 * inserted before a safe modified sibling, ordinal comparison can make the
 * unsafe block look like a modification of the sibling. This helper keeps that
 * case narrow: removing the proposed top-level block must leave the same
 * top-level block-name sequence as the base document.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $base_content     Base stripped post content.
 * @param string $proposed_content Proposed stripped post content.
 * @param array  $proposed_record  Proposed flattened block review record.
 * @return bool Whether the record is a top-level insertion.
 */
function wp_de_rtc_is_kses_top_level_inserted_review_record( $base_content, $proposed_content, $proposed_record ) {
	$block_path = isset( $proposed_record['block_path'] ) && is_array( $proposed_record['block_path'] )
		? array_values( array_map( 'absint', $proposed_record['block_path'] ) )
		: array();

	if ( 1 !== count( $block_path ) ) {
		return false;
	}

	$block_index      = (int) $block_path[0];
	$base_records     = wp_de_rtc_get_top_level_serialized_block_records( $base_content );
	$proposed_records = wp_de_rtc_get_top_level_serialized_block_records( $proposed_content );

	if ( is_wp_error( $base_records ) || is_wp_error( $proposed_records ) ) {
		return false;
	}

	if ( count( $proposed_records ) !== count( $base_records ) + 1 || ! array_key_exists( $block_index, $proposed_records ) ) {
		return false;
	}

	$candidate_records = $proposed_records;
	unset( $candidate_records[ $block_index ] );
	$candidate_records = array_values( $candidate_records );

	return wp_de_rtc_top_level_serialized_block_names_match( $base_records, $candidate_records );
}

/**
 * Checks whether two serialized top-level block lists keep the same block kinds.
 *
 * Partial-safe saves may drop an unsafe inserted block while retaining safe
 * edits inside neighboring blocks. Matching only block names keeps this narrow:
 * WordPress can preserve safe text/formatting changes in retained blocks, but
 * it will not guess across block type conversion, deletion, or reorder.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string[] $base_records      Base serialized top-level block records.
 * @param string[] $candidate_records Candidate serialized top-level block records.
 * @return bool Whether the top-level block names match by ordinal.
 */
function wp_de_rtc_top_level_serialized_block_names_match( $base_records, $candidate_records ) {
	if ( count( $base_records ) !== count( $candidate_records ) ) {
		return false;
	}

	$base_records      = array_values( $base_records );
	$candidate_records = array_values( $candidate_records );

	foreach ( $base_records as $index => $base_record ) {
		$candidate_record = $candidate_records[ $index ];
		$base_blocks      = parse_blocks( $base_record );
		$candidate_blocks = parse_blocks( $candidate_record );
		$base_name        = isset( $base_blocks[0]['blockName'] ) ? (string) $base_blocks[0]['blockName'] : '';
		$candidate_name   = isset( $candidate_blocks[0]['blockName'] ) ? (string) $candidate_blocks[0]['blockName'] : '';

		if ( $base_name !== $candidate_name ) {
			return false;
		}
	}

	return true;
}

/**
 * Returns block review records keyed by serialized block hash.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array[] $records Block records.
 * @return array[] Block record keys grouped by serialized block hash.
 */
function wp_de_rtc_get_kses_block_review_records_by_hash( $records ) {
	$records_by_hash = array();

	foreach ( $records as $path_key => $record ) {
		$hash = wp_de_rtc_hash_content( $record['serialized_block'] );

		if ( ! isset( $records_by_hash[ $hash ] ) ) {
			$records_by_hash[ $hash ] = array();
		}

		$records_by_hash[ $hash ][] = $path_key;
	}

	return $records_by_hash;
}

/**
 * Finds an unmatched base block record with the same serialized block hash.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array[] $records_by_hash          Block record keys grouped by hash.
 * @param string  $hash                     Serialized proposed block hash.
 * @param bool[]  $matched_base_record_keys Matched base record keys.
 * @return string|null Matching record key, or null when none is available.
 */
function wp_de_rtc_find_matching_kses_block_review_record_key( $records_by_hash, $hash, $matched_base_record_keys ) {
	if ( empty( $records_by_hash[ $hash ] ) || ! is_array( $records_by_hash[ $hash ] ) ) {
		return null;
	}

	foreach ( $records_by_hash[ $hash ] as $path_key ) {
		if ( empty( $matched_base_record_keys[ $path_key ] ) ) {
			return $path_key;
		}
	}

	return null;
}

/**
 * Returns flattened block records for KSES block review classification.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $post_content Post content.
 * @return array[] Block records keyed by path.
 */
function wp_de_rtc_get_kses_block_review_records( $post_content ) {
	$records = array();

	wp_de_rtc_collect_kses_block_review_records(
		parse_blocks( (string) $post_content ),
		array(),
		$records
	);

	return $records;
}

/**
 * Collects flattened block records for KSES block review classification.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $blocks  Parsed block list.
 * @param int[] $path    Current block path.
 * @param array $records Collected block records.
 */
function wp_de_rtc_collect_kses_block_review_records( $blocks, $path, &$records ) {
	$retained_index = 0;

	foreach ( (array) $blocks as $index => $block ) {
		if ( ! is_array( $block ) ) {
			continue;
		}

		$serialized_block = serialize_block( $block );

		if ( empty( $block['blockName'] ) && '' === trim( $serialized_block ) ) {
			continue;
		}

		$block_path       = array_merge( $path, array( $retained_index ) );
		++$retained_index;
		$block_name       = ! empty( $block['blockName'] ) && is_string( $block['blockName'] ) ? $block['blockName'] : 'core/freeform';
		$path_key         = implode( '.', $block_path );
		$own_block        = wp_de_rtc_get_block_without_inner_blocks( $block );

		$records[ $path_key ] = array(
			'path_key'             => $path_key,
			'block_path'           => $block_path,
			'block_name'           => $block_name,
			'block_label'          => wp_de_rtc_get_kses_block_review_label( $block_name ),
			'serialized_block'     => $serialized_block,
			'serialized_own_block' => serialize_block( $own_block ),
		);

		if ( ! empty( $block['innerBlocks'] ) && is_array( $block['innerBlocks'] ) ) {
			wp_de_rtc_collect_kses_block_review_records( $block['innerBlocks'], $block_path, $records );
		}
	}
}

/**
 * Returns a parsed block clone containing only the block's own wrapper/content.
 *
 * Parent blocks often serialize their descendants. KSES review must flag the
 * immediate offending block, not every ancestor that happens to contain it, so
 * classification evaluates this childless clone while retaining full serialized
 * hashes for review matching and later source-pair validation.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $block Parsed block.
 * @return array Parsed block without inner blocks.
 */
function wp_de_rtc_get_block_without_inner_blocks( $block ) {
	$own_block                = $block;
	$own_block['innerBlocks'] = array();

	if ( isset( $own_block['innerContent'] ) && is_array( $own_block['innerContent'] ) ) {
		$own_block['innerContent'] = array_values(
			array_filter(
				$own_block['innerContent'],
				static function ( $chunk ) {
					return null !== $chunk;
				}
			)
		);
	}

	return $own_block;
}

/**
 * Returns whether an added block introduced KSES-sensitive content.
 *
 * Gutenberg may serialize safe void elements in a compact form that KSES
 * rewrites to WordPress' spaced self-closing form, for example `<hr/>` to
 * `<hr />`. That normalization must not block ordinary author saves, while
 * substantive removals such as SCRIPT elements or event-handler attributes
 * still require review from a user with `unfiltered_html`.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $proposed_block  Proposed serialized block without descendants.
 * @param array  $proposed_review Proposed block KSES evidence.
 * @return bool Whether review is required for this added block.
 */
function wp_de_rtc_added_kses_block_change_requires_review( $proposed_block, $proposed_review ) {
	$proposed_would_change = is_array( $proposed_review ) && ! empty( $proposed_review['would_change_content'] );

	if ( ! $proposed_would_change ) {
		return false;
	}

	if ( ! empty( wp_de_rtc_get_kses_sensitive_element_hashes( $proposed_block ) ) ) {
		return true;
	}

	return ! wp_de_rtc_is_kses_normalization_only_change(
		$proposed_block,
		wp_de_rtc_get_kses_filtered_post_content( $proposed_block )
	);
}

/**
 * Returns whether a modified block introduced or changed KSES-sensitive content.
 *
 * Existing markup may have been saved by an authorized editor. A later author
 * text edit should not be blocked only because that unchanged markup would be
 * normalized by KSES if it were newly introduced.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $base_block              Base serialized block without descendants.
 * @param string $proposed_block          Proposed serialized block without descendants.
 * @param array  $base_review             Base block KSES evidence.
 * @param array  $proposed_review         Proposed block KSES evidence.
 * @return bool Whether review is required for this modified block.
 */
function wp_de_rtc_modified_kses_block_change_requires_review( $base_block, $proposed_block, $base_review, $proposed_review ) {
	$base_would_change     = is_array( $base_review ) && ! empty( $base_review['would_change_content'] );
	$proposed_would_change = is_array( $proposed_review ) && ! empty( $proposed_review['would_change_content'] );

	if ( ! $base_would_change && ! $proposed_would_change ) {
		return false;
	}

	if ( ! $base_would_change || ! $proposed_would_change ) {
		return true;
	}

	if ( $base_block === $proposed_block ) {
		return false;
	}

	if ( wp_de_rtc_get_kses_sensitive_element_hashes( $base_block ) !== wp_de_rtc_get_kses_sensitive_element_hashes( $proposed_block ) ) {
		return true;
	}

	$base_signature     = wp_de_rtc_get_kses_removed_fragment_signature( $base_block );
	$proposed_signature = wp_de_rtc_get_kses_removed_fragment_signature( $proposed_block );

	if ( null === $base_signature || null === $proposed_signature ) {
		return true;
	}

	return $base_signature !== $proposed_signature;
}

/**
 * Returns whether KSES only normalized serialized HTML spelling.
 *
 * This deliberately accepts only narrow formatter-level changes. It is not a
 * replacement for KSES and it does not bless filtered content for persistence;
 * it only prevents the review gate from confusing WordPress' harmless void-tag
 * spacing rewrite with dangerous content.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $post_content          Original serialized content.
 * @param string $filtered_post_content KSES-filtered serialized content.
 * @return bool Whether the two strings differ only by safe KSES normalization.
 */
function wp_de_rtc_is_kses_normalization_only_change( $post_content, $filtered_post_content ) {
	$post_content          = (string) $post_content;
	$filtered_post_content = (string) $filtered_post_content;

	if ( $post_content === $filtered_post_content ) {
		return true;
	}

	return wp_de_rtc_canonicalize_kses_normalized_serialized_html( $post_content ) === wp_de_rtc_canonicalize_kses_normalized_serialized_html( $filtered_post_content );
}

/**
 * Canonicalizes the narrow HTML spellings KSES may normalize for safe blocks.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $post_content Serialized content.
 * @return string Canonicalized serialized content.
 */
function wp_de_rtc_canonicalize_kses_normalized_serialized_html( $post_content ) {
	$post_content = (string) $post_content;
	$post_content = wp_de_rtc_canonicalize_serialized_block_boundary_whitespace( $post_content );
	$post_content = preg_replace(
		'~<((?:area|base|br|col|embed|hr|img|input|link|meta|param|source|track|wbr)\b[^<>]*?)\s*/>~i',
		'<$1 />',
		$post_content
	);

	return is_string( $post_content ) ? $post_content : '';
}

/**
 * Returns hashes of raw fragments KSES removes from content.
 *
 * The raw fragments are hashed before comparison so this helper cannot
 * accidentally become a source of unsafe review payload material.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $post_content Raw post content.
 * @return string[]|null Fragment hashes, or null when the filtered content is not a subsequence.
 */
function wp_de_rtc_get_kses_removed_fragment_signature( $post_content ) {
	$post_content     = (string) $post_content;
	$filtered_content = wp_de_rtc_get_kses_filtered_post_content( $post_content );

	if ( $filtered_content === $post_content ) {
		return array();
	}

	$removed_fragments = wp_de_rtc_get_removed_subsequence_fragments( $post_content, $filtered_content );

	if ( null === $removed_fragments ) {
		return null;
	}

	return array_map( 'wp_de_rtc_hash_content', $removed_fragments );
}

/**
 * Returns raw fragments skipped when matching a filtered subsequence.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $raw        Raw content.
 * @param string $subsequence Expected subsequence.
 * @return string[]|null Removed fragments, or null when the expected subsequence cannot be matched.
 */
function wp_de_rtc_get_removed_subsequence_fragments( $raw, $subsequence ) {
	$raw          = (string) $raw;
	$subsequence  = (string) $subsequence;
	$raw_offset   = 0;
	$raw_length   = strlen( $raw );
	$sub_length   = strlen( $subsequence );
	$fragments    = array();

	for ( $index = 0; $index < $sub_length; ++$index ) {
		$next_offset = strpos( $raw, $subsequence[ $index ], $raw_offset );

		if ( false === $next_offset ) {
			return null;
		}

		if ( $next_offset > $raw_offset ) {
			$fragments[] = substr( $raw, $raw_offset, $next_offset - $raw_offset );
		}

		$raw_offset = $next_offset + 1;
	}

	if ( $raw_offset < $raw_length ) {
		$fragments[] = substr( $raw, $raw_offset );
	}

	return array_values(
		array_filter(
			$fragments,
			static function ( $fragment ) {
				return '' !== $fragment;
			}
		)
	);
}

/**
 * Returns hashes for whole sensitive elements whose contents must not change.
 *
 * KSES may strip only the SCRIPT tag while leaving text behind, so removed
 * fragment comparison alone cannot detect code edits inside the element.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $post_content Post content.
 * @return string[] Sensitive element hashes.
 */
function wp_de_rtc_get_kses_sensitive_element_hashes( $post_content ) {
	$post_content = (string) $post_content;

	if ( ! preg_match_all( '~<\s*(script|style)\b[^>]*>[\s\S]*?<\s*/\s*\1\s*>|<\s*(iframe|object|embed)\b[\s\S]*?(?:<\s*/\s*\2\s*>|>)~i', $post_content, $matches ) ) {
		return array();
	}

	return array_map( 'wp_de_rtc_hash_content', $matches[0] );
}

/**
 * Creates a hash-only risky block review item.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $block_record Block record.
 * @param array $args         Review item arguments.
 * @return array Hash-only review item.
 */
function wp_de_rtc_create_kses_block_review_item( $block_record, $args ) {
	$id_source = implode( '/', $block_record['block_path'] ) . '|' . $block_record['block_name'] . '|' . $args['base_content_hash'] . '|' . $args['proposed_content_hash'];

	return array(
		'id'                         => 'kses-review-' . substr( hash( 'sha256', $id_source ), 0, 16 ),
		'block_client_id'            => 'server-block-' . str_replace( '.', '-', $block_record['path_key'] ),
		'block_name'                 => $block_record['block_name'],
		'block_label'                => $block_record['block_label'],
		'block_path'                 => $block_record['block_path'],
		'change_kind'                => $args['change_kind'],
		'risk_reason'                => $args['risk_reason'],
		'author_id'                  => $args['author_id'],
		'base_version'               => null === $args['base_version'] ? null : (string) $args['base_version'],
		'server_version'             => null === $args['server_version'] ? null : (string) $args['server_version'],
		'base_content_hash'          => $args['base_content_hash'],
		'proposed_content_hash'      => $args['proposed_content_hash'],
		'kses_filtered_content_hash' => $args['kses_filtered_content_hash'],
		'review_status'              => 'pending_review',
		'review_evidence_type'       => 'kses_block_hash_only_change',
		'content_review_policy'      => 'kses',
		'raw_content_included'       => false,
		'exposes_raw_content'        => false,
	);
}

/**
 * Returns a readable block label for KSES review output.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $block_name Block name.
 * @return string Block label.
 */
function wp_de_rtc_get_kses_block_review_label( $block_name ) {
	if ( 'core/freeform' === $block_name ) {
		return 'Classic';
	}

	if ( 'core/html' === $block_name ) {
		return 'HTML';
	}

	if ( 0 === strpos( $block_name, 'core/' ) ) {
		$core_label = substr( $block_name, 5 );
		$core_label = str_replace( array( '-', '_' ), ' ', $core_label );

		return ucwords( $core_label );
	}

	return $block_name;
}

/**
 * Returns the risk reason for a block-level KSES review item.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string     $change_kind     Change kind.
 * @param array|null $base_review     Base block KSES evidence.
 * @param array      $proposed_review Proposed block KSES evidence.
 * @param string     $block_content   Serialized proposed block content.
 * @return string Risk reason.
 */
function wp_de_rtc_get_kses_block_review_risk_reason( $change_kind, $base_review, $proposed_review, $block_content ) {
	if ( 'deleted_block' === $change_kind ) {
		return 'unfiltered_html_block_deleted';
	}

	if ( ! empty( $proposed_review['would_change_content'] ) ) {
		if ( false !== stripos( $block_content, '<script' ) ) {
			return 'kses_would_remove_script';
		}

		if ( false !== stripos( $block_content, 'javascript:' ) || preg_match( '/\son[a-z]+\s*=/i', $block_content ) ) {
			return 'kses_would_alter_attributes';
		}

		return 'kses_would_modify_html';
	}

	if ( is_array( $base_review ) && ! empty( $base_review['would_change_content'] ) ) {
		return 'unfiltered_html_block_modified';
	}

	return 'kses_would_modify_html';
}

/**
 * Adds the scoped KSES allowance for server-owned sync metadata SCRIPT markup.
 *
 * @since 7.1.0
 * @access private
 */
function wp_de_rtc_enable_sync_meta_script_kses_allowance() {
	add_filter( 'wp_kses_allowed_html', 'wp_de_rtc_filter_sync_meta_script_kses_allowance', 10, 2 );
}

/**
 * Removes the scoped KSES allowance for server-owned sync metadata SCRIPT markup.
 *
 * @since 7.1.0
 * @access private
 */
function wp_de_rtc_disable_sync_meta_script_kses_allowance() {
	remove_filter( 'wp_kses_allowed_html', 'wp_de_rtc_filter_sync_meta_script_kses_allowance', 10 );
}

/**
 * Allows the DE-RTC sync-meta SCRIPT element through post KSES in guarded saves.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array[]|string $tags    Allowed HTML tags.
 * @param string         $context KSES context.
 * @return array[]|string Filtered allowed HTML tags.
 */
function wp_de_rtc_filter_sync_meta_script_kses_allowance( $tags, $context ) {
	if ( 'post' !== $context || ! is_array( $tags ) ) {
		return $tags;
	}

	$tags['script'] = array(
		'type'                  => true,
		'data-sync-meta-format' => true,
		'data-wp-sync-meta'     => true,
	);

	return $tags;
}

/**
 * Returns the escalation reason for an unfiltered HTML review rejection.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array|null $proposed_post_content_kses_review  Proposed-content KSES evidence.
 * @param array|null $candidate_post_content_kses_review Retry-save candidate KSES evidence.
 * @return string Escalation reason.
 */
function wp_de_rtc_get_unfiltered_html_review_escalation_reason(
	$proposed_post_content_kses_review,
	$candidate_post_content_kses_review
) {
	$proposed_would_change  = is_array( $proposed_post_content_kses_review ) && ! empty( $proposed_post_content_kses_review['would_change_content'] );
	$candidate_would_change = is_array( $candidate_post_content_kses_review ) && ! empty( $candidate_post_content_kses_review['would_change_content'] );

	if ( $proposed_would_change && $candidate_would_change ) {
		return 'proposed_content_and_retry_save_candidate_would_change_by_kses';
	}

	if ( $proposed_would_change ) {
		return 'proposed_content_would_change_by_kses';
	}

	if ( $candidate_would_change ) {
		return 'retry_save_candidate_would_change_by_kses';
	}

	return 'content_capability_review_required';
}

/**
 * Returns the canonical unfiltered HTML review result.
 *
 * This helper only defines the review vocabulary for collaborative content
 * authority. It does not inspect content, save posts, create revisions,
 * register REST behavior, replace post locks, or wire normal save paths.
 * When a caller has already persisted a partial-safe subset, the authoritative
 * server content returns as a normal response so Gutenberg does not process a
 * successful partial write through its failed-save path.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post Post ID or object.
 * @param array       $args {
 *     Optional rejection data.
 *
 *     @type mixed  $pending_change_count               Pending local change count. Default 1.
 *     @type string $rest_route                         Response route label. Default 'post_content_capability_review'.
 *     @type string $proposed_post_content_hash         Proposed stripped post-content hash.
 *     @type string $candidate_post_content_hash        Retry-save candidate post-content hash.
 *     @type array  $proposed_post_content_kses_review  Proposed-content KSES comparison evidence.
 *     @type array  $candidate_post_content_kses_review Retry-save candidate KSES comparison evidence.
 * }
 * @return array|WP_Error Unfiltered HTML review result with normalized DE-RTC data.
 */
function wp_de_rtc_get_unfiltered_html_review_rejection_error( $post, $args = array() ) {
	$post                 = get_post( $post );
	$post_id              = $post ? (int) $post->ID : 0;
	$pending_change_count = array_key_exists( 'pending_change_count', $args ) ? max( 0, (int) $args['pending_change_count'] ) : 1;
	$rest_route           = isset( $args['rest_route'] ) ? sanitize_key( $args['rest_route'] ) : 'post_content_capability_review';
	$permission_contract  = wp_de_rtc_get_rest_recovery_permission_contract( $post );
	$review_items         = isset( $args['review_items'] ) && is_array( $args['review_items'] ) ? array_values( $args['review_items'] ) : array();
	$partial_safe_merge   = isset( $args['partial_safe_merge'] ) && is_array( $args['partial_safe_merge'] ) ? $args['partial_safe_merge'] : array();

	$proposed_post_content_kses_review = null;
	if ( isset( $args['proposed_post_content_kses_review'] ) && is_array( $args['proposed_post_content_kses_review'] ) ) {
		$proposed_post_content_kses_review = $args['proposed_post_content_kses_review'];
	}

	$candidate_post_content_kses_review = null;
	if ( isset( $args['candidate_post_content_kses_review'] ) && is_array( $args['candidate_post_content_kses_review'] ) ) {
		$candidate_post_content_kses_review = $args['candidate_post_content_kses_review'];
	}

	$proposed_would_change = null;
	if ( is_array( $proposed_post_content_kses_review ) && array_key_exists( 'would_change_content', $proposed_post_content_kses_review ) ) {
		$proposed_would_change = (bool) $proposed_post_content_kses_review['would_change_content'];
	}

	$candidate_would_change = null;
	if ( is_array( $candidate_post_content_kses_review ) && array_key_exists( 'would_change_content', $candidate_post_content_kses_review ) ) {
		$candidate_would_change = (bool) $candidate_post_content_kses_review['would_change_content'];
	}

	$content_would_change = true === $proposed_would_change || true === $candidate_would_change;
	$escalation_reason    = wp_de_rtc_get_unfiltered_html_review_escalation_reason( $proposed_post_content_kses_review, $candidate_post_content_kses_review );

	$proposed_hash = null;
	if ( isset( $args['proposed_post_content_hash'] ) ) {
		$proposed_hash = sanitize_text_field( (string) $args['proposed_post_content_hash'] );
	} elseif ( is_array( $proposed_post_content_kses_review ) && isset( $proposed_post_content_kses_review['content_hash'] ) ) {
		$proposed_hash = sanitize_text_field( (string) $proposed_post_content_kses_review['content_hash'] );
	}

	$filtered_proposed_hash = null;
	if ( is_array( $proposed_post_content_kses_review ) && isset( $proposed_post_content_kses_review['filtered_content_hash'] ) ) {
		$filtered_proposed_hash = sanitize_text_field( (string) $proposed_post_content_kses_review['filtered_content_hash'] );
	}

	$candidate_hash = null;
	if ( isset( $args['candidate_post_content_hash'] ) ) {
		$candidate_hash = sanitize_text_field( (string) $args['candidate_post_content_hash'] );
	} elseif ( is_array( $candidate_post_content_kses_review ) && isset( $candidate_post_content_kses_review['content_hash'] ) ) {
		$candidate_hash = sanitize_text_field( (string) $candidate_post_content_kses_review['content_hash'] );
	}

	$filtered_candidate_hash = null;
	if ( is_array( $candidate_post_content_kses_review ) && isset( $candidate_post_content_kses_review['filtered_content_hash'] ) ) {
		$filtered_candidate_hash = sanitize_text_field( (string) $candidate_post_content_kses_review['filtered_content_hash'] );
	}

	$review_contract = array(
		'status'                                 => 'requires_reviewer_escalation',
		'type'                                   => 'unfiltered_html_content_capability_review',
		'review_action'                          => 'request_unfiltered_html_reviewer',
		'review_required_capability'             => 'unfiltered_html',
		'review_scope'                           => 'collaborative_post_content',
		'reviewer_capability'                    => 'unfiltered_html',
		'escalation_required'                    => true,
		'escalation_reason'                      => $escalation_reason,
		'content_filter'                         => 'wp_filter_post_kses',
		'content_filter_context'                 => 'content_save_pre',
		'content_would_change_by_kses'           => $content_would_change,
		'proposed_content_would_change_by_kses'  => $proposed_would_change,
		'candidate_content_would_change_by_kses' => $candidate_would_change,
		'proposed_content_hash'                  => $proposed_hash,
		'kses_filtered_proposed_content_hash'    => $filtered_proposed_hash,
		'candidate_content_hash'                 => $candidate_hash,
		'kses_filtered_candidate_content_hash'   => $filtered_candidate_hash,
		'raw_content_included'                   => false,
	);

	if ( ! empty( $review_items ) ) {
		$review_contract['review_items']              = $review_items;
		$review_contract['review_item_count']         = count( $review_items );
		$review_contract['pending_review_item_count'] = count( $review_items );
	}

	if ( ! empty( $partial_safe_merge ) ) {
		$review_contract['partial_safe_merge_applied'] = ! empty( $partial_safe_merge['partial_safe_merge_applied'] );
		$review_contract['partial_safe_merge_status']  = isset( $partial_safe_merge['partial_safe_merge_status'] ) ? sanitize_key( (string) $partial_safe_merge['partial_safe_merge_status'] ) : null;

		if ( isset( $partial_safe_merge['review_item_queue'] ) && is_array( $partial_safe_merge['review_item_queue'] ) ) {
			$review_contract['review_item_queue_status'] = isset( $partial_safe_merge['review_item_queue']['review_item_queue_status'] ) ? sanitize_key( (string) $partial_safe_merge['review_item_queue']['review_item_queue_status'] ) : '';
			$review_contract['review_item_descriptors']  = isset( $partial_safe_merge['review_item_queue']['review_item_descriptors'] ) && is_array( $partial_safe_merge['review_item_queue']['review_item_descriptors'] ) ? array_values( $partial_safe_merge['review_item_queue']['review_item_descriptors'] ) : array();
			$review_contract['review_item_queue_recorded_count'] = isset( $partial_safe_merge['review_item_queue']['review_item_queued_count'] ) ? max( 0, (int) $partial_safe_merge['review_item_queue']['review_item_queued_count'] ) : 0;
		}
	}

	$error_data = array(
		'detail'                              => 'collaborative_unfiltered_html_review_required',
		'post_id'                             => $post_id,
		'rest_route'                          => $rest_route,
		'pending_change_count'                => $pending_change_count,
		'requires_edit_post'                  => true,
		'requires_unfiltered_html'            => true,
		'unfiltered_html_allowed'             => current_user_can( 'unfiltered_html' ),
		'authorship_review_required'          => true,
		'content_capability_review_required'  => true,
		'review_status'                       => 'requires_reviewer_escalation',
		'reviewer_capability'                 => 'unfiltered_html',
		'escalation_required'                 => true,
		'escalation_reason'                   => $escalation_reason,
		'requires_reviewer_escalation'        => true,
		'review_action'                       => 'request_unfiltered_html_reviewer',
		'review_required_capability'          => 'unfiltered_html',
		'review_scope'                        => 'collaborative_post_content',
		'content_filter'                      => 'wp_filter_post_kses',
		'content_filter_context'              => 'content_save_pre',
		'content_would_change_by_kses'        => $content_would_change,
		'proposed_content_hash'               => $proposed_hash,
		'kses_filtered_proposed_content_hash' => $filtered_proposed_hash,
		'candidate_content_hash'              => $candidate_hash,
		'kses_filtered_candidate_content_hash' => $filtered_candidate_hash,
		'raw_content_included'                => false,
		'review_contract'                     => $review_contract,
		'recovery_actions'                    => array(
			'export_local_updates',
			'request_unfiltered_html_reviewer',
			'refetch_server_state',
		),
		'requires_manual_conflict_resolution' => true,
		'can_export_local_updates'            => $pending_change_count > 0,
		'saves_post'                          => false,
		'mutates_post_content'                => false,
		'creates_revision'                    => false,
		'claims_saved'                        => false,
		'permission_contract'                 => $permission_contract,
		'result'                              => ! empty( $review_items ) ? 'block_review_required' : null,
		'review_items'                        => $review_items,
		'review_item_count'                   => count( $review_items ),
		'pending_review_item_count'           => count( $review_items ),
		'pre_publish_review_required'         => ! empty( $review_items ),
		'save_action'                         => ! empty( $review_items ) ? 'open_pre_publish_review' : null,
		'unsafe_raw_content_included'         => false,
	);

	if ( ! empty( $partial_safe_merge ) ) {
		$error_data = array_merge(
			$error_data,
			$partial_safe_merge
		);

		if (
			! empty( $partial_safe_merge['partial_safe_merge_applied'] ) &&
			! empty( $partial_safe_merge['partial_safe_merge_persisted'] ) &&
			! empty( $partial_safe_merge['safe_server_content_included'] )
		) {
			/*
			 * WordPress has an authoritative server copy for the safe subset. Keep
			 * the unsafe review pending, but do not force Gutenberg through its
			 * failed-save catch path after the server content has already advanced.
			 */
			unset( $error_data['status'] );

			$error_data['result']                        = 'retry_save_partial_safe_merge';
			$error_data['reason_code']                   = 'de_rtc_unfiltered_html_would_change_content';
			$error_data['retry_save_accepted']           = true;
			$error_data['remaining_review_required']     = true;
			$error_data['requires_server_state_refetch'] = false;
			$error_data['recovery_actions']              = array(
				'request_unfiltered_html_reviewer',
			);
			$error_data['can_export_local_updates']      = false;

			if ( isset( $partial_safe_merge['review_item_queue'] ) && is_array( $partial_safe_merge['review_item_queue'] ) ) {
				$error_data['review_item_queue_status'] = isset( $partial_safe_merge['review_item_queue']['review_item_queue_status'] ) ? sanitize_key( (string) $partial_safe_merge['review_item_queue']['review_item_queue_status'] ) : '';
				$error_data['review_item_descriptors']  = isset( $partial_safe_merge['review_item_queue']['review_item_descriptors'] ) && is_array( $partial_safe_merge['review_item_queue']['review_item_descriptors'] ) ? array_values( $partial_safe_merge['review_item_queue']['review_item_descriptors'] ) : array();
				$error_data['review_item_pending_count'] = isset( $partial_safe_merge['review_item_queue']['review_item_pending_count'] ) ? max( 0, (int) $partial_safe_merge['review_item_queue']['review_item_pending_count'] ) : 0;
			}

			return $error_data;
		}

		$error_data['status'] = 403;
	}

	return wp_de_rtc_get_reason_error(
		'de_rtc_unfiltered_html_would_change_content',
		__( 'Distributed Editing rejected the update because collaborative content changes require unfiltered HTML review.' ),
		$error_data
	);
}

/**
 * Returns the current sync-meta version for a post.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post Post ID or object.
 * @return string|null Sync-meta version, or null when no version is available.
 */
function wp_de_rtc_get_post_sync_meta_version( $post ) {
	$post = get_post( $post );

	if ( ! $post ) {
		return null;
	}

	$parsed = wp_de_rtc_parse_post_content_sync_meta( $post->post_content );

	if ( is_wp_error( $parsed ) || ! isset( $parsed['sync_meta'] ) || ! is_array( $parsed['sync_meta'] ) ) {
		return null;
	}

	if ( ! array_key_exists( 'version', $parsed['sync_meta'] ) ) {
		return null;
	}

	return (string) $parsed['sync_meta']['version'];
}

/**
 * Adds the current DE-RTC base version to normal post REST responses.
 *
 * The legacy post endpoint now exposes the CRDT version a client should submit
 * back as `base_version` on a future update. This is intentionally read-only:
 * malformed or missing sync meta simply omits the value instead of attempting
 * recovery from a response preparation hook.
 *
 * @since 7.1.0
 *
 * @param WP_REST_Response $response Response object.
 * @param WP_Post          $post     Post object.
 * @param WP_REST_Request  $request  Request object.
 * @return WP_REST_Response Unchanged or augmented response.
 */
function wp_de_rtc_rest_prepare_post_base_version( $response, $post, $request ) {
	if ( ! $response instanceof WP_REST_Response ) {
		return $response;
	}

	$post = get_post( $post );

	if ( ! $post || ! current_user_can( 'edit_post', $post->ID ) ) {
		return $response;
	}

	if ( ! wp_de_rtc_is_enabled_for_post( $post ) ) {
		return $response;
	}

	if ( ! wp_de_rtc_rest_normal_post_update_request_matches_post_type( $request, $post ) ) {
		return $response;
	}

	$base_version = wp_de_rtc_get_post_sync_meta_version( $post );

	if ( null === $base_version || '' === $base_version ) {
		return $response;
	}

	$data                 = $response->get_data();
	$data['base_version'] = $base_version;

	$response->set_data( $data );

	return $response;
}

/**
 * Returns whether Distributed Editing is enabled for the site.
 *
 * @since 7.1.0
 *
 * @return bool Whether Distributed Editing is enabled.
 */
function wp_de_rtc_is_enabled() {
	return (bool) get_option( 'wp_de_rtc_enabled', false );
}

/**
 * Returns whether Distributed Editing is enabled for a post.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post Post ID or object.
 * @return bool Whether Distributed Editing is enabled.
 */
function wp_de_rtc_is_enabled_for_post( $post ) {
	$post = get_post( $post );

	if ( ! $post ) {
		return false;
	}

	if ( ! wp_de_rtc_is_enabled() ) {
		return false;
	}

	/**
	 * Filters whether Distributed Editing is enabled for a post.
	 *
	 * @since 7.1.0
	 *
	 * @param bool    $enabled Whether Distributed Editing is enabled for the post.
	 * @param WP_Post $post    Post object.
	 */
	return (bool) apply_filters( 'wp_de_rtc_enabled_for_post', true, $post );
}

/**
 * Returns the current recovery endpoint permission contract.
 *
 * @since 7.1.0
 * @access private
 *
 * @param int|WP_Post $post Post ID or object.
 * @return array Permission contract metadata.
 */
function wp_de_rtc_get_rest_recovery_permission_contract( $post ) {
	$post = get_post( $post );

	if ( ! $post ) {
		return array(
			'post_id'                            => 0,
			'requires_edit_post'                 => true,
			'feature_enabled'                    => false,
			'unfiltered_html_review_required'    => true,
			'unfiltered_html_allowed'            => current_user_can( 'unfiltered_html' ),
			'authorship_review_required'         => true,
			'content_capability_review_required' => true,
			'unfiltered_html_rejection_code'     => 'de_rtc_unfiltered_html_would_change_content',
			'unfiltered_html_review_action'      => 'request_unfiltered_html_reviewer',
			'unfiltered_html_review_capability'  => 'unfiltered_html',
			'unfiltered_html_review_scope'       => 'collaborative_post_content',
		);
	}

	return array(
		'post_id'                            => (int) $post->ID,
		'post_type'                          => $post->post_type,
		'post_type_rest_base'                => wp_de_rtc_get_post_type_rest_base( $post->post_type ),
		'requires_edit_post'                 => true,
		'feature_enabled'                    => wp_de_rtc_is_enabled_for_post( $post ),
		'unfiltered_html_review_required'    => true,
		'unfiltered_html_allowed'            => current_user_can( 'unfiltered_html' ),
		'authorship_review_required'         => true,
		'content_capability_review_required' => true,
		'unfiltered_html_rejection_code'     => 'de_rtc_unfiltered_html_would_change_content',
		'unfiltered_html_review_action'      => 'request_unfiltered_html_reviewer',
		'unfiltered_html_review_capability'  => 'unfiltered_html',
		'unfiltered_html_review_scope'       => 'collaborative_post_content',
	);
}

/**
 * Returns runtime availability for the native PHP Automerge integration.
 *
 * The pinned port intentionally uses PHP 8.2 syntax. WordPress still supports
 * older PHP versions, so the server must check the version before registering
 * the autoloader or touching any class file from the vendored runtime.
 *
 * @since 7.1.0
 *
 * @return array Availability details.
 */
function wp_de_rtc_get_automerge_runtime_status() {
	$library_path = ABSPATH . WPINC . '/automerge-php/src';

	return array(
		'available'        => PHP_VERSION_ID >= 80200 && function_exists( 'mb_convert_encoding' ) && file_exists( $library_path . '/NativePort.php' ),
		'php_version_id'   => PHP_VERSION_ID,
		'required_version' => 80200,
		'mbstring_loaded'  => function_exists( 'mb_convert_encoding' ),
		'library_path'     => $library_path,
		'format'           => 'native-automerge-blocks-v1',
	);
}

/**
 * Registers the native PHP Automerge autoloader when the runtime can parse it.
 *
 * @since 7.1.0
 *
 * @return true|WP_Error True on success, otherwise an error.
 */
function wp_de_rtc_load_automerge_runtime() {
	$status = wp_de_rtc_get_automerge_runtime_status();

	if ( empty( $status['available'] ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_feature_disabled',
			__( 'Distributed Editing Automerge support is not available on this server.' ),
			array(
				'detail'           => 'automerge_runtime_unavailable',
				'php_version_id'   => $status['php_version_id'],
				'required_version' => $status['required_version'],
				'mbstring_loaded'  => $status['mbstring_loaded'],
				'library_present'  => file_exists( $status['library_path'] . '/NativePort.php' ),
			)
		);
	}

	if ( empty( $GLOBALS['wp_de_rtc_automerge_autoload_registered'] ) ) {
		spl_autoload_register( 'wp_de_rtc_automerge_autoload' );
		$GLOBALS['wp_de_rtc_automerge_autoload_registered'] = true;
	}

	if ( ! class_exists( 'WordPress\\DistributedEditing\\Automerge\\NativePort' ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_feature_disabled',
			__( 'Distributed Editing could not load the Automerge runtime.' ),
			array(
				'detail' => 'automerge_runtime_class_missing',
			)
		);
	}

	return true;
}

/**
 * Autoloads classes from the vendored native PHP Automerge runtime.
 *
 * @since 7.1.0
 *
 * @param string $class Fully-qualified class name.
 */
function wp_de_rtc_automerge_autoload( $class ) {
	$prefix = 'WordPress\\DistributedEditing\\Automerge\\';

	if ( 0 !== strpos( $class, $prefix ) ) {
		return;
	}

	$relative = substr( $class, strlen( $prefix ) );
	$path     = ABSPATH . WPINC . '/automerge-php/src/' . str_replace( '\\', '/', $relative ) . '.php';

	if ( file_exists( $path ) ) {
		require_once $path;
	}
}

/**
 * Returns the native PHP Automerge adapter.
 *
 * @since 7.1.0
 *
 * @return object|WP_Error Adapter instance, or an error.
 */
function wp_de_rtc_get_automerge_native_port() {
	$loaded = wp_de_rtc_load_automerge_runtime();

	if ( is_wp_error( $loaded ) ) {
		return $loaded;
	}

	return new WordPress\DistributedEditing\Automerge\NativePort();
}

/**
 * Creates a native Automerge update for the single contiguous change between strings.
 *
 * This intentionally starts with the smallest trustworthy representation:
 * ordinary editor Saves currently submit a complete proposed post string, so
 * the server derives a bounded update from the base/proposed pair and rejects
 * overlapping stale ranges before merging.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $base  Base post content without sync metadata.
 * @param string $next  Next post content without sync metadata.
 * @param string $actor Actor label for operation IDs.
 * @return array Native update plus server-derived range evidence.
 */
function wp_de_rtc_create_automerge_update_for_content_change( $base, $next, $actor ) {
	$base         = wp_de_rtc_canonicalize_post_content_core_block_names( $base );
	$next         = wp_de_rtc_canonicalize_post_content_core_block_names( $next );
	$base_records = wp_de_rtc_get_top_level_serialized_block_records( $base );
	$next_records = wp_de_rtc_get_top_level_serialized_block_records( $next );

	if ( is_wp_error( $base_records ) || is_wp_error( $next_records ) ) {
		$descriptor = wp_de_rtc_get_automerge_content_change_descriptor( $base, $next );

		return array(
			'format'              => 'native-automerge-blocks-v1',
			'schema'              => 'de-rtc-automerge-v1',
			'operations'          => array(
				array(
					'type'                => 'document.replace_unsupported',
					'automergePrimitive'        => 'Automerge.Map.set',
					'actor'               => $actor,
					'sequence'            => 0,
					'id'                  => $actor . ':0',
					'baseContentHash'     => wp_de_rtc_hash_content( $base ),
					'proposedContentHash' => wp_de_rtc_hash_content( $next ),
					'changeRange'         => wp_de_rtc_format_automerge_change_range_for_client( $descriptor['change_range'] ),
				),
			),
			'stateVector'         => array( $actor => 1 ),
			'baseContentHash'     => wp_de_rtc_hash_content( $base ),
			'proposedContentHash' => wp_de_rtc_hash_content( $next ),
			'baseBlockCount'      => null,
			'proposedBlockCount'  => null,
		);
	}

	$operations = wp_de_rtc_get_automerge_block_native_operations( $base_records, $next_records, $actor );

	return array(
		'format'              => 'native-automerge-blocks-v1',
		'schema'              => 'de-rtc-automerge-v1',
		'operations'          => $operations,
		'stateVector'         => count( $operations ) > 0 ? array( $actor => count( $operations ) ) : array(),
		'baseContentHash'     => wp_de_rtc_hash_content( $base ),
		'proposedContentHash' => wp_de_rtc_hash_content( $next ),
		'baseBlockCount'      => count( $base_records ),
		'proposedBlockCount'  => count( $next_records ),
		'change_range'        => wp_de_rtc_get_automerge_content_change_descriptor( $base, $next )['change_range'],
	);
}

/**
 * Formats a server-side change-range descriptor using the client payload keys.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $range Server change-range descriptor.
 * @return array Client-shaped descriptor.
 */
function wp_de_rtc_format_automerge_change_range_for_client( $range ) {
	return array(
		'start'        => isset( $range['start'] ) ? (int) $range['start'] : 0,
		'end'          => isset( $range['end'] ) ? (int) $range['end'] : 0,
		'deleteLength' => isset( $range['delete_length'] ) ? (int) $range['delete_length'] : 0,
		'insertLength' => isset( $range['insert_length'] ) ? (int) $range['insert_length'] : 0,
		'changed'      => ! empty( $range['changed'] ),
	);
}

/**
 * Builds block-native Automerge operation evidence for a serialized block change.
 *
 * The operations are intentionally block-scoped. They may carry the serialized
 * block needed to materialize a changed or inserted block, instead of treating
 * the whole post as one text range.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string[] $base_records Accepted-base serialized block records.
 * @param string[] $next_records Proposed serialized block records.
 * @param string   $actor        Actor label for operation IDs.
 * @return array[] Block-native operations.
 */
function wp_de_rtc_get_automerge_block_native_operations( $base_records, $next_records, $actor ) {
	$operations  = array();
	$base_hashes = array_map( 'wp_de_rtc_hash_content', $base_records );
	$next_hashes = array_map( 'wp_de_rtc_hash_content', $next_records );

	if (
		count( $base_records ) === count( $next_records ) &&
		$base_records !== $next_records &&
		wp_de_rtc_have_same_serialized_block_multiset( $base_records, $next_records ) &&
		count( array_unique( $base_hashes ) ) === count( $base_hashes )
	) {
		foreach ( $next_records as $index => $next_record ) {
			if ( $base_records[ $index ] === $next_record ) {
				continue;
			}

			$from_index = array_search( $next_hashes[ $index ], $base_hashes, true );

			if ( false !== $from_index && $from_index !== $index ) {
				wp_de_rtc_append_automerge_block_native_operation(
					$operations,
					$actor,
					array(
						'type'         => 'block.move',
						'automergePrimitive' => 'Automerge.List.move',
						'fromPath'     => array( (int) $from_index ),
						'toPath'       => array( (int) $index ),
						'blockUid'     => 'top:' . $next_hashes[ $index ],
						'blockHash'    => $next_hashes[ $index ],
					)
				);
			}
		}

		return $operations;
	}

	if ( count( $base_records ) === count( $next_records ) ) {
		foreach ( $base_records as $index => $base_record ) {
			if ( $base_record === $next_records[ $index ] ) {
				continue;
			}

			wp_de_rtc_append_automerge_block_native_operation(
				$operations,
				$actor,
				wp_de_rtc_get_automerge_block_native_update_operation(
					$base_record,
					$next_records[ $index ],
					$base_hashes[ $index ],
					$next_hashes[ $index ],
					array( (int) $index )
				)
			);
		}

		return $operations;
	}

	$prefix = 0;
	while (
		$prefix < count( $base_records ) &&
		$prefix < count( $next_records ) &&
		$base_records[ $prefix ] === $next_records[ $prefix ]
	) {
		++$prefix;
	}

	$suffix = 0;
	while (
		$suffix < count( $base_records ) - $prefix &&
		$suffix < count( $next_records ) - $prefix &&
		$base_records[ count( $base_records ) - 1 - $suffix ] === $next_records[ count( $next_records ) - 1 - $suffix ]
	) {
		++$suffix;
	}

	for ( $index = count( $base_records ) - $suffix - 1; $index >= $prefix; --$index ) {
		wp_de_rtc_append_automerge_block_native_operation(
			$operations,
			$actor,
			array(
				'type'         => 'block.delete',
				'automergePrimitive' => 'Automerge.List.delete',
				'path'         => array( (int) $index ),
				'index'        => (int) $index,
				'blockUid'     => 'top:' . $base_hashes[ $index ],
				'blockHash'    => $base_hashes[ $index ],
			)
		);
	}

	for ( $index = $prefix; $index < count( $next_records ) - $suffix; ++$index ) {
		wp_de_rtc_append_automerge_block_native_operation(
			$operations,
			$actor,
			array(
				'type'            => 'block.insert',
				'automergePrimitive'    => 'Automerge.List.insert',
				'path'            => array( (int) $index ),
				'index'           => (int) $index,
				'blockUid'        => 'top:' . $next_hashes[ $index ],
				'blockHash'       => $next_hashes[ $index ],
				'blockName'       => wp_de_rtc_get_serialized_block_record_name( $next_records[ $index ] ),
				'serializedBlock' => $next_records[ $index ],
			)
		);
	}

	return $operations;
}

/**
 * Appends actor and sequence metadata to a block-native operation.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array[] $operations Operations built so far.
 * @param string  $actor      Actor label.
 * @param array   $operation  Operation body.
 */
function wp_de_rtc_append_automerge_block_native_operation( &$operations, $actor, $operation ) {
	$sequence     = count( $operations );
	$operations[] = array_merge(
		array(
			'actor'    => $actor,
			'sequence' => $sequence,
			'id'       => $actor . ':' . $sequence,
		),
		$operation
	);
}

/**
 * Returns whether two serialized-block arrays have the same content multiset.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string[] $first  First block list.
 * @param string[] $second Second block list.
 * @return bool Whether the lists contain the same serialized blocks.
 */
function wp_de_rtc_have_same_serialized_block_multiset( $first, $second ) {
	if ( count( $first ) !== count( $second ) ) {
		return false;
	}

	$counts = array();

	foreach ( $first as $block ) {
		$hash            = wp_de_rtc_hash_content( $block );
		$counts[ $hash ] = isset( $counts[ $hash ] ) ? $counts[ $hash ] + 1 : 1;
	}

	foreach ( $second as $block ) {
		$hash = wp_de_rtc_hash_content( $block );

		if ( empty( $counts[ $hash ] ) ) {
			return false;
		}

		--$counts[ $hash ];
	}

	foreach ( $counts as $count ) {
		if ( 0 !== $count ) {
			return false;
		}
	}

	return true;
}

/**
 * Builds an update operation for one changed serialized block.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $base_block          Base serialized block.
 * @param string $next_block          Proposed serialized block.
 * @param string $base_block_hash     Base block hash.
 * @param string $next_block_hash     Proposed block hash.
 * @param int[]  $path                Top-level ordinal path.
 * @return array Block-native operation body.
 */
function wp_de_rtc_get_automerge_block_native_update_operation( $base_block, $next_block, $base_block_hash, $next_block_hash, $path ) {
	$base_block_name = wp_de_rtc_get_serialized_block_record_name( $base_block );
	$next_block_name = wp_de_rtc_get_serialized_block_record_name( $next_block );

	if ( null !== $base_block_name && $base_block_name === $next_block_name ) {
		$rich_text_operation = wp_de_rtc_get_automerge_block_native_rich_text_operation(
			$base_block,
			$next_block,
			$base_block_hash,
			$next_block_hash,
			$base_block_name,
			$path
		);

		if ( null !== $rich_text_operation ) {
			return $rich_text_operation;
		}

		return array(
			'type'              => 'block.update_serialized',
			'automergePrimitive'      => 'Automerge.Map.set',
			'path'              => $path,
			'blockUid'          => 'top:' . $base_block_hash,
			'blockName'         => $base_block_name,
			'baseBlockHash'     => $base_block_hash,
			'proposedBlockHash' => $next_block_hash,
			'changeRange'       => wp_de_rtc_format_automerge_change_range_for_client( wp_de_rtc_get_automerge_content_change_descriptor( $base_block, $next_block )['change_range'] ),
			'serializedBlock'   => $next_block,
		);
	}

	return array(
		'type'              => 'block.replace',
		'automergePrimitive'      => 'Automerge.Map.set+Automerge.List.insert',
		'path'              => $path,
		'blockUid'          => 'top:' . $next_block_hash,
		'baseBlockHash'     => $base_block_hash,
		'proposedBlockHash' => $next_block_hash,
		'baseBlockName'     => $base_block_name,
		'proposedBlockName' => $next_block_name,
		'serializedBlock'   => $next_block,
	);
}

/**
 * Builds a block-native rich text formatting operation when safe to describe.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $base_block      Base serialized block.
 * @param string $next_block      Proposed serialized block.
 * @param string $base_hash       Base block hash.
 * @param string $next_hash       Proposed block hash.
 * @param string $block_name      Block name.
 * @param int[]  $path            Top-level ordinal path.
 * @return array|null Operation body, or null when not a rich-text mark edit.
 */
function wp_de_rtc_get_automerge_block_native_rich_text_operation( $base_block, $next_block, $base_hash, $next_hash, $block_name, $path ) {
	$base = wp_de_rtc_get_paragraph_rich_text_block_parts( $base_block );
	$next = wp_de_rtc_get_paragraph_rich_text_block_parts( $next_block );

	if ( ! $base || ! $next || $base['open'] !== $next['open'] || $base['close'] !== $next['close'] ) {
		return null;
	}

	$base_model = wp_de_rtc_get_rich_text_format_model( $base['html'] );
	$next_model = wp_de_rtc_get_rich_text_format_model( $next['html'] );

	if ( ! $base_model || ! $next_model ) {
		return null;
	}

	if ( $base_model['text'] !== $next_model['text'] ) {
		return array(
			'type'              => 'block.rich_text_content',
			'automergePrimitive'      => 'Automerge.Text.splice',
			'path'              => $path,
			'blockUid'          => 'top:' . $base_hash,
			'blockName'         => $block_name,
			'field'             => 'innerHTML',
			'baseBlockHash'     => $base_hash,
			'proposedBlockHash' => $next_hash,
			'textSplice'        => wp_de_rtc_format_rich_text_text_splice_for_client(
				wp_de_rtc_get_rich_text_text_splice( $base_model['text'], $next_model['text'] )
			),
			'serializedBlock'   => $next_block,
		);
	}

	return array(
		'type'               => 'block.rich_text_format',
		'automergePrimitive'       => 'Automerge.Text.mark',
		'path'               => $path,
		'blockUid'           => 'top:' . $base_hash,
		'blockName'          => $block_name,
		'field'              => 'innerHTML',
		'baseBlockHash'      => $base_hash,
		'proposedBlockHash'  => $next_hash,
		'changedTextIndexes' => array_values( wp_de_rtc_get_rich_text_changed_indexes( $base_model, $next_model ) ),
		'serializedBlock'    => $next_block,
	);
}

/**
 * Creates a whole-text Automerge update for the guarded fallback path.
 *
 * New DE-RTC save paths should use `native-automerge-blocks-v1`; this helper is
 * retained only for the current same-range fallback while block-native coverage
 * is expanded.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $base  Base post content without sync metadata.
 * @param string $next  Next post content without sync metadata.
 * @param string $actor Actor label for operation IDs.
 * @return array Native text update plus server-derived range evidence.
 */
function wp_de_rtc_create_legacy_automerge_update_for_content_change( $base, $next, $actor ) {
	$base       = wp_de_rtc_canonicalize_post_content_core_block_names( $base );
	$next       = wp_de_rtc_canonicalize_post_content_core_block_names( $next );
	$descriptor = wp_de_rtc_get_automerge_content_change_descriptor( $base, $next );
	$operations = array();
	$sequence   = 0;

	if ( $descriptor['delete_length'] > 0 ) {
		$operations[] = array(
			'type'     => 'delete',
			'index'    => $descriptor['index'],
			'length'   => $descriptor['delete_length'],
			'actor'    => $actor,
			'sequence' => $sequence,
			'id'       => $actor . ':' . $sequence,
		);
		++$sequence;
	}

	if ( '' !== $descriptor['insert_text'] ) {
		$operations[] = array(
			'type'     => 'insert',
			'index'    => $descriptor['index'],
			'text'     => $descriptor['insert_text'],
			'actor'    => $actor,
			'sequence' => $sequence,
			'id'       => $actor . ':' . $sequence,
		);
		++$sequence;
	}

	return array(
		'format'       => 'native-automerge-php-v1',
		'operations'   => $operations,
		'stateVector'  => $sequence > 0 ? array( $actor => $sequence ) : array(),
		'change_range' => $descriptor['change_range'],
	);
}

/**
 * Returns the single changed range between two UTF-8 strings.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $base Base string.
 * @param string $next Next string.
 * @return array Change descriptor.
 */
function wp_de_rtc_get_automerge_content_change_descriptor( $base, $next ) {
	$base_chars = wp_de_rtc_split_utf8_string( (string) $base );
	$next_chars = wp_de_rtc_split_utf8_string( (string) $next );
	$base_count = count( $base_chars );
	$next_count = count( $next_chars );
	$prefix     = 0;

	while (
		$prefix < $base_count &&
		$prefix < $next_count &&
		$base_chars[ $prefix ] === $next_chars[ $prefix ]
	) {
		++$prefix;
	}

	$suffix = 0;
	while (
		$suffix < $base_count - $prefix &&
		$suffix < $next_count - $prefix &&
		$base_chars[ $base_count - 1 - $suffix ] === $next_chars[ $next_count - 1 - $suffix ]
	) {
		++$suffix;
	}

	$deleted_text = implode( '', array_slice( $base_chars, $prefix, $base_count - $prefix - $suffix ) );
	$insert_text  = implode( '', array_slice( $next_chars, $prefix, $next_count - $prefix - $suffix ) );
	$before_text  = implode( '', array_slice( $base_chars, 0, $prefix ) );
	$index        = wp_de_rtc_get_automerge_utf16_length( $before_text );
	$delete_units = wp_de_rtc_get_automerge_utf16_length( $deleted_text );
	$insert_units = wp_de_rtc_get_automerge_utf16_length( $insert_text );

	return array(
		'index'         => $index,
		'delete_length' => $delete_units,
		'insert_text'   => $insert_text,
		'insert_length' => $insert_units,
		'change_range'  => array(
			'start'         => $index,
			'end'           => $index + $delete_units,
			'delete_length' => $delete_units,
			'insert_length' => $insert_units,
			'changed'       => $delete_units > 0 || $insert_text !== '',
		),
	);
}

/**
 * Splits a UTF-8 string into Unicode code points.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $text Text to split.
 * @return string[] Characters.
 */
function wp_de_rtc_split_utf8_string( $text ) {
	if ( '' === $text ) {
		return array();
	}

	$matched = preg_match_all( '/./us', $text, $matches );

	if ( false === $matched ) {
		return str_split( $text );
	}

	return $matches[0];
}

/**
 * Returns the UTF-16 code-unit length used by text-indexed update evidence.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $text Text to measure.
 * @return int UTF-16 code-unit length.
 */
function wp_de_rtc_get_automerge_utf16_length( $text ) {
	if ( '' === $text ) {
		return 0;
	}

	if ( ! function_exists( 'mb_convert_encoding' ) ) {
		return strlen( $text );
	}

	return (int) ( strlen( mb_convert_encoding( $text, 'UTF-16LE', 'UTF-8' ) ) / 2 );
}

/**
 * Normalizes client-submitted native Automerge update evidence.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $update Client update.
 * @return array|WP_Error Normalized update or an error.
 */
function wp_de_rtc_normalize_automerge_client_update( $update ) {
	if ( null === $update ) {
		return null;
	}

	if ( ! is_array( $update ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the Automerge update because it is malformed.' ),
			array(
				'detail' => 'automerge_client_update_not_object',
			)
		);
	}

	if ( isset( $update['postContent'] ) || isset( $update['post_content'] ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the Automerge update because clients may not submit raw document state as Automerge metadata.' ),
			array(
				'detail' => 'automerge_client_update_raw_document_rejected',
			)
		);
	}

	$format = isset( $update['format'] ) ? (string) $update['format'] : 'native-automerge-php-v1';

	if ( ! in_array( $format, array( 'native-automerge-php-v1', 'native-automerge-blocks-v1' ), true ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the Automerge update because the encoding is unsupported.' ),
			array(
				'detail' => 'automerge_client_update_unsupported_format',
				'format' => sanitize_text_field( $format ),
			)
		);
	}

	if ( ! isset( $update['operations'] ) || ! is_array( $update['operations'] ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the Automerge update because operations are missing.' ),
			array(
				'detail' => 'automerge_client_update_missing_operations',
			)
		);
	}

	foreach ( $update['operations'] as $operation ) {
		if ( ! is_array( $operation ) || ! isset( $operation['type'] ) || ! is_string( $operation['type'] ) ) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_malformed_sync_payload',
				__( 'Distributed Editing rejected the Automerge update because an operation is malformed.' ),
				array(
					'detail' => 'automerge_client_update_malformed_operation',
				)
			);
		}
	}

	return array(
		'format'      => $format,
		'schema'      => isset( $update['schema'] ) && is_string( $update['schema'] ) ? sanitize_text_field( $update['schema'] ) : null,
		'operations'  => array_values( $update['operations'] ),
		'stateVector' => isset( $update['stateVector'] ) && is_array( $update['stateVector'] ) ? $update['stateVector'] : array(),
		'baseContentHash' => isset( $update['baseContentHash'] ) && is_string( $update['baseContentHash'] ) ? sanitize_text_field( $update['baseContentHash'] ) : null,
		'proposedContentHash' => isset( $update['proposedContentHash'] ) && is_string( $update['proposedContentHash'] ) ? sanitize_text_field( $update['proposedContentHash'] ) : null,
		'baseBlockCount' => isset( $update['baseBlockCount'] ) ? (int) $update['baseBlockCount'] : null,
		'proposedBlockCount' => isset( $update['proposedBlockCount'] ) ? (int) $update['proposedBlockCount'] : null,
	);
}

/**
 * Returns whether two server-derived Automerge change ranges overlap.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $left  First range.
 * @param array $right Second range.
 * @return bool Whether the ranges overlap.
 */
function wp_de_rtc_automerge_change_ranges_overlap( $left, $right ) {
	if ( empty( $left['changed'] ) || empty( $right['changed'] ) ) {
		return false;
	}

	$left_start  = (int) $left['start'];
	$left_end    = (int) $left['end'];
	$right_start = (int) $right['start'];
	$right_end   = (int) $right['end'];

	if ( $left_start === $left_end && $right_start === $right_end ) {
		return $left_start === $right_start;
	}

	if ( $left_start === $left_end ) {
		return $left_start >= $right_start && $left_start <= $right_end;
	}

	if ( $right_start === $right_end ) {
		return $right_start >= $left_start && $right_start <= $left_end;
	}

	return $left_start < $right_end && $right_start < $left_end;
}

/**
 * Returns whether a serialized block record can be unambiguously matched by content.
 *
 * This is a deliberately narrow guard for the Automerge idempotent-insert merge. In
 * the absence of durable block IDs, repeated serialized base blocks make
 * ordinal inference unsafe, so the server falls back to the normal conflict
 * path instead of guessing.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string[] $records Serialized top-level block records.
 * @return bool Whether every record appears once.
 */
function wp_de_rtc_serialized_block_records_are_unique( $records ) {
	$seen = array();

	foreach ( $records as $record ) {
		$hash = wp_de_rtc_hash_content( (string) $record );

		if ( isset( $seen[ $hash ] ) ) {
			return false;
		}

		$seen[ $hash ] = true;
	}

	return true;
}

/**
 * Returns the parsed block name for a single serialized top-level block record.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $record Serialized block record.
 * @return string|null Block name, or null when parsing is ambiguous.
 */
	function wp_de_rtc_get_serialized_block_record_name( $record ) {
		$record = wp_de_rtc_canonicalize_post_content_for_hash( $record );
		$blocks = parse_blocks( (string) $record );

	if (
		1 !== count( $blocks ) ||
		empty( $blocks[0]['blockName'] ) ||
		! is_string( $blocks[0]['blockName'] ) ||
		serialize_block( $blocks[0] ) !== $record
	) {
		return null;
	}

	return $blocks[0]['blockName'];
}

/**
 * Returns whether two serialized block records represent the same block type.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $left  First serialized block record.
 * @param string $right Second serialized block record.
 * @return bool Whether the records share a parsed block name.
 */
function wp_de_rtc_serialized_block_record_names_match( $left, $right ) {
	$left_name  = wp_de_rtc_get_serialized_block_record_name( $left );
	$right_name = wp_de_rtc_get_serialized_block_record_name( $right );

	return null !== $left_name && $left_name === $right_name;
}

/**
 * Builds an insertion-only plan for a current body relative to an accepted base.
 *
 * Retained base blocks must be byte-identical and in order. Inserted blocks
 * that equal any base block are rejected because content-only matching cannot
 * distinguish insertion from movement or duplication of retained content.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string[] $base_records      Accepted-base serialized block records.
 * @param string[] $candidate_records Candidate serialized block records.
 * @return array|null Insertion plan by accepted-base gap, or null when unsafe.
 */
function wp_de_rtc_get_automerge_insertion_only_block_plan( $base_records, $candidate_records ) {
	if ( ! wp_de_rtc_serialized_block_records_are_unique( $base_records ) ) {
		return null;
	}

	$base_lookup = array_fill_keys(
		array_map(
			static function ( $record ) {
				return wp_de_rtc_hash_content( (string) $record );
			},
			$base_records
		),
		true
	);
	$base_count  = count( $base_records );
	$gaps        = array_fill( 0, $base_count + 1, array() );
	$index       = 0;

	for ( $base_index = 0; $base_index < $base_count; $base_index++ ) {
		while (
			$index < count( $candidate_records ) &&
			! hash_equals( $base_records[ $base_index ], $candidate_records[ $index ] )
		) {
			$inserted_record_hash = wp_de_rtc_hash_content( (string) $candidate_records[ $index ] );

			if ( isset( $base_lookup[ $inserted_record_hash ] ) ) {
				return null;
			}

			$gaps[ $base_index ][] = $candidate_records[ $index ];
			++$index;
		}

		if (
			$index >= count( $candidate_records ) ||
			! hash_equals( $base_records[ $base_index ], $candidate_records[ $index ] )
		) {
			return null;
		}

		++$index;
	}

	while ( $index < count( $candidate_records ) ) {
		$inserted_record_hash = wp_de_rtc_hash_content( (string) $candidate_records[ $index ] );

		if ( isset( $base_lookup[ $inserted_record_hash ] ) ) {
			return null;
		}

		$gaps[ $base_count ][] = $candidate_records[ $index ];
		++$index;
	}

	return array(
		'gaps'           => $gaps,
		'inserted_count' => count( $candidate_records ) - $base_count,
	);
}

/**
 * Applies an insertion-only server plan to a proposed body and keeps retained edits.
 *
 * The proposed side must contain exactly the same inserted blocks in exactly
 * the same accepted-base gaps as the already-saved server body. Only retained
 * base blocks may differ locally, and those retained edits must preserve the
 * parsed block type.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string[] $base_records     Accepted-base serialized block records.
 * @param string[] $proposed_records Proposed serialized block records.
 * @param array    $server_plan      Insertion-only plan from the current server body.
 * @return array|null Merge data or null when unsafe.
 */
function wp_de_rtc_apply_automerge_idempotent_insert_plan_to_proposed_blocks( $base_records, $proposed_records, $server_plan ) {
	if ( ! isset( $server_plan['gaps'] ) || ! is_array( $server_plan['gaps'] ) ) {
		return null;
	}

	$base_count            = count( $base_records );
	$proposed_index        = 0;
	$merged_blocks         = array();
	$server_changed_indexes = array();
	$local_changed_indexes = array();
	$retained_edit_indexes = array();

	for ( $gap_index = 0; $gap_index <= $base_count; $gap_index++ ) {
		$gap_records = isset( $server_plan['gaps'][ $gap_index ] ) && is_array( $server_plan['gaps'][ $gap_index ] )
			? $server_plan['gaps'][ $gap_index ]
			: array();

		foreach ( $gap_records as $gap_record ) {
			if (
				$proposed_index >= count( $proposed_records ) ||
				! hash_equals( $gap_record, $proposed_records[ $proposed_index ] )
			) {
				return null;
			}

			$server_changed_indexes[] = count( $merged_blocks );
			$merged_blocks[]          = $gap_record;
			++$proposed_index;
		}

		if ( $gap_index >= $base_count ) {
			continue;
		}

		if ( $proposed_index >= count( $proposed_records ) ) {
			return null;
		}

		$base_record     = $base_records[ $gap_index ];
		$proposed_record = $proposed_records[ $proposed_index ];

		if (
			! hash_equals( $base_record, $proposed_record ) &&
			! wp_de_rtc_serialized_block_record_names_match( $base_record, $proposed_record )
		) {
			return null;
		}

		if ( ! hash_equals( $base_record, $proposed_record ) ) {
			$local_changed_indexes[] = count( $merged_blocks );
			$retained_edit_indexes[] = count( $merged_blocks );
		}

		$merged_blocks[] = $proposed_record;
		++$proposed_index;
	}

	if ( $proposed_index !== count( $proposed_records ) || empty( $server_changed_indexes ) || empty( $local_changed_indexes ) ) {
		return null;
	}

	return array(
		'merged_blocks'          => $merged_blocks,
		'server_changed_indexes' => $server_changed_indexes,
		'local_changed_indexes'  => $local_changed_indexes,
		'retained_edit_indexes'  => $retained_edit_indexes,
	);
}

/**
 * Merges the idempotent Automerge case where a stale client repeats an inserted block.
 *
 * A common offline/realtime shape is: editor A inserts a block, editor B made
 * the same insertion from the same base and also edited a different retained
 * block. The server must absorb the already-saved duplicate insertion and
 * preserve B's separate edit. This helper accepts only that narrow shape.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $base_content     Accepted-base stripped content.
 * @param string $current_content  Current server stripped content.
 * @param string $proposed_content Client-proposed stripped content.
 * @param array  $args             Optional merge evidence.
 * @return array|null Merge result, or null when the shape is unsafe.
 */
function wp_de_rtc_get_automerge_idempotent_block_insert_merge_result( $base_content, $current_content, $proposed_content, $args = array() ) {
	$base_records     = wp_de_rtc_get_top_level_serialized_block_records( $base_content );
	$current_records  = wp_de_rtc_get_top_level_serialized_block_records( $current_content );
	$proposed_records = wp_de_rtc_get_top_level_serialized_block_records( $proposed_content );

	foreach ( array( $base_records, $current_records, $proposed_records ) as $records ) {
		if ( is_wp_error( $records ) ) {
			return null;
		}
	}

	if ( count( $base_records ) >= count( $current_records ) || count( $current_records ) !== count( $proposed_records ) ) {
		return null;
	}

	$server_plan = wp_de_rtc_get_automerge_insertion_only_block_plan( $base_records, $current_records );

	if ( null === $server_plan || empty( $server_plan['inserted_count'] ) ) {
		return null;
	}

	$proposed_plan = wp_de_rtc_apply_automerge_idempotent_insert_plan_to_proposed_blocks( $base_records, $proposed_records, $server_plan );

	if ( null === $proposed_plan ) {
		return null;
	}

	$merged_content = implode( '', $proposed_plan['merged_blocks'] );

	return array(
		'merged_content'                        => $merged_content,
		'merge_status'                          => 'merged',
		'merge_strategy'                        => 'native_automerge_php_v1',
		'automerge_idempotent_duplicate_insert_absorbed' => true,
		'base_version'                          => isset( $args['base_version'] ) ? sanitize_text_field( (string) $args['base_version'] ) : null,
		'server_version'                        => isset( $args['server_version'] ) ? sanitize_text_field( (string) $args['server_version'] ) : null,
		'base_revision_id'                      => isset( $args['base_revision_id'] ) ? (int) $args['base_revision_id'] : 0,
		'block_count'                           => count( $proposed_plan['merged_blocks'] ),
		'base_block_count'                      => count( $base_records ),
		'server_block_count'                    => count( $current_records ),
		'proposed_block_count'                  => count( $proposed_records ),
		'merged_block_count'                    => count( $proposed_plan['merged_blocks'] ),
		'server_changed_indexes'                => $proposed_plan['server_changed_indexes'],
		'local_changed_indexes'                 => $proposed_plan['local_changed_indexes'],
		'server_changed_block_count'            => count( $proposed_plan['server_changed_indexes'] ),
		'local_changed_block_count'             => count( $proposed_plan['local_changed_indexes'] ),
		'block_identity_retained_edit_indexes'  => $proposed_plan['retained_edit_indexes'],
		'block_identity_retained_edit_block_count' => count( $proposed_plan['retained_edit_indexes'] ),
		'merged_stripped_content_hash'          => wp_de_rtc_hash_content( $merged_content ),
		'base_content_hash'                     => wp_de_rtc_hash_content( $base_content ),
		'server_content_hash'                   => wp_de_rtc_hash_content( $current_content ),
		'proposed_content_hash'                 => wp_de_rtc_hash_content( $proposed_content ),
	);
}

/**
 * Computes a Automerge-backed retry-save materialization.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $base_content     Accepted-base stripped content.
 * @param string $current_content  Current server stripped content.
 * @param string $proposed_content Proposed stripped content.
 * @param mixed  $client_update    Optional client update evidence.
 * @return array|WP_Error Merge/materialization result.
 */
function wp_de_rtc_get_automerge_retry_save_result( $base_content, $current_content, $proposed_content, $client_update = null ) {
	$base_content     = wp_de_rtc_canonicalize_post_content_core_block_names( $base_content );
	$current_content  = wp_de_rtc_canonicalize_post_content_core_block_names( $current_content );
	$proposed_content = wp_de_rtc_canonicalize_post_content_core_block_names( $proposed_content );

	$normalized_client_update = wp_de_rtc_normalize_automerge_client_update( $client_update );

	if ( is_wp_error( $normalized_client_update ) ) {
		return $normalized_client_update;
	}

	if ( null === $normalized_client_update ) {
		$normalized_client_update = wp_de_rtc_create_automerge_update_for_content_change( $base_content, $proposed_content, 'client' );
	}

	if ( isset( $normalized_client_update['format'] ) && 'native-automerge-blocks-v1' === $normalized_client_update['format'] ) {
		return wp_de_rtc_get_automerge_block_native_retry_save_result(
			$base_content,
			$current_content,
			$proposed_content,
			$normalized_client_update
		);
	}

	$port = wp_de_rtc_get_automerge_native_port();

	if ( is_wp_error( $port ) ) {
		return $port;
	}

	$server_update      = wp_de_rtc_create_legacy_automerge_update_for_content_change( $base_content, $current_content, 'server' );
	$client_descriptor = wp_de_rtc_get_automerge_content_change_descriptor( $base_content, $proposed_content );
	$server_descriptor = wp_de_rtc_get_automerge_content_change_descriptor( $base_content, $current_content );
	$client_check      = $port->merge( $base_content, array( 'operations' => array() ), $normalized_client_update );

	if ( empty( $client_check['ok'] ) || ! isset( $client_check['postContent'] ) || $client_check['postContent'] !== $proposed_content ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because the Automerge update did not match the proposed content.' ),
			array(
				'detail'               => 'automerge_client_update_materialization_mismatch',
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	if ( wp_de_rtc_automerge_change_ranges_overlap( $server_descriptor['change_range'], $client_descriptor['change_range'] ) ) {
		$idempotent_insert_merge = wp_de_rtc_get_automerge_idempotent_block_insert_merge_result(
			$base_content,
			$current_content,
			$proposed_content
		);

		if ( is_array( $idempotent_insert_merge ) ) {
			$effective_client_update = wp_de_rtc_create_legacy_automerge_update_for_content_change(
				$current_content,
				$idempotent_insert_merge['merged_content'],
				'client'
			);
			$effective_merge         = $port->merge( $current_content, array( 'operations' => array() ), $effective_client_update );

			if (
				! empty( $effective_merge['ok'] ) &&
				isset( $effective_merge['postContent'] ) &&
				$effective_merge['postContent'] === $idempotent_insert_merge['merged_content']
			) {
				$idempotent_insert_merge['automerge_metadata']          = isset( $effective_merge['metadata'] ) && is_array( $effective_merge['metadata'] ) ? $effective_merge['metadata'] : array();
				$idempotent_insert_merge['automerge_client_update']     = $normalized_client_update;
				$idempotent_insert_merge['automerge_effective_update']  = $effective_client_update;
				$idempotent_insert_merge['automerge_server_update']     = $server_update;
				$idempotent_insert_merge['server_change_range']   = $server_descriptor['change_range'];
				$idempotent_insert_merge['client_change_range']   = $client_descriptor['change_range'];
				$idempotent_insert_merge['server_merge_strategy'] = 'native_automerge_php_v1';

				return $idempotent_insert_merge;
			}
		}

		return wp_de_rtc_get_server_merge_conflict_error(
			'automerge_overlapping_change_ranges',
			array(
				'server_merge_strategy' => 'native_automerge_php_v1',
				'server_change_range'   => $server_descriptor['change_range'],
				'client_change_range'   => $client_descriptor['change_range'],
			)
		);
	}

	$merged = $port->merge( $base_content, $server_update, $normalized_client_update );

	if ( empty( $merged['ok'] ) || ! isset( $merged['postContent'] ) || ! is_string( $merged['postContent'] ) ) {
		return wp_de_rtc_get_server_merge_conflict_error(
			'automerge_merge_failed',
			array(
				'server_merge_strategy' => 'native_automerge_php_v1',
			)
		);
	}

	$base_records     = wp_de_rtc_get_top_level_serialized_block_records( $base_content );
	$current_records  = wp_de_rtc_get_top_level_serialized_block_records( $current_content );
	$proposed_records = wp_de_rtc_get_top_level_serialized_block_records( $proposed_content );
	$records          = wp_de_rtc_get_top_level_serialized_block_records( $merged['postContent'] );

	foreach ( array( $base_records, $current_records, $proposed_records, $records ) as $record_result ) {
		if ( is_wp_error( $record_result ) ) {
			return $record_result;
		}
	}

	return array(
		'merged_content'        => $merged['postContent'],
		'merge_status'          => 'merged',
		'merge_strategy'        => 'native_automerge_php_v1',
		'block_count'           => count( $records ),
		'base_block_count'      => count( $base_records ),
		'server_block_count'    => count( $current_records ),
		'proposed_block_count'  => count( $proposed_records ),
		'merged_block_count'    => count( $records ),
		'merged_stripped_content_hash' => wp_de_rtc_hash_content( $merged['postContent'] ),
		'base_content_hash'     => wp_de_rtc_hash_content( $base_content ),
		'server_content_hash'   => wp_de_rtc_hash_content( $current_content ),
		'proposed_content_hash' => wp_de_rtc_hash_content( $proposed_content ),
		'automerge_metadata'          => isset( $merged['metadata'] ) && is_array( $merged['metadata'] ) ? $merged['metadata'] : array(),
		'automerge_client_update'     => $normalized_client_update,
		'automerge_server_update'     => $server_update,
		'server_change_range'   => $server_descriptor['change_range'],
		'client_change_range'   => $client_descriptor['change_range'],
		'server_merge_strategy' => 'native_automerge_php_v1',
	);
}

/**
 * Computes a block-native Automerge retry-save materialization.
 *
 * This is the replacement path for new DE-RTC saves. The client update proves
 * block-scoped operations against the accepted base; WordPress still validates
 * that those operations materialize the submitted proposed content and then
 * owns the server merge and serialized-block persistence.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $base_content     Accepted-base stripped content.
 * @param string $current_content  Current server stripped content.
 * @param string $proposed_content Client-proposed stripped content.
 * @param array  $client_update    Normalized block-native client update.
 * @return array|WP_Error Merge/materialization result.
 */
function wp_de_rtc_get_automerge_block_native_retry_save_result( $base_content, $current_content, $proposed_content, $client_update ) {
	$validation = wp_de_rtc_validate_automerge_block_native_update_matches_content( $base_content, $proposed_content, $client_update );

	if ( is_wp_error( $validation ) ) {
		return $validation;
	}

	if ( hash_equals( wp_de_rtc_hash_content( $base_content ), wp_de_rtc_hash_content( $current_content ) ) ) {
		$merge_result = wp_de_rtc_get_automerge_block_native_current_base_merge_result( $base_content, $proposed_content );
	} else {
		$merge_result = wp_de_rtc_get_automerge_idempotent_block_insert_merge_result( $base_content, $current_content, $proposed_content );

		if ( null === $merge_result ) {
			$merge_result = wp_de_rtc_get_serialized_block_server_merge_result( $base_content, $current_content, $proposed_content );
		}
	}

	if ( is_wp_error( $merge_result ) ) {
		return $merge_result;
	}

	$server_update = wp_de_rtc_create_automerge_update_for_content_change( $base_content, $current_content, 'server' );
	$operations    = array_merge(
		isset( $server_update['operations'] ) && is_array( $server_update['operations'] ) ? $server_update['operations'] : array(),
		isset( $client_update['operations'] ) && is_array( $client_update['operations'] ) ? $client_update['operations'] : array()
	);

	$merge_result['merge_strategy']        = 'native_automerge_blocks_v1';
	$merge_result['automerge_metadata']          = array(
		'format'      => 'native-automerge-blocks-v1',
		'schema'      => 'de-rtc-automerge-v1',
		'operations'  => $operations,
		'stateVector' => wp_de_rtc_merge_automerge_state_vectors(
			isset( $server_update['stateVector'] ) && is_array( $server_update['stateVector'] ) ? $server_update['stateVector'] : array(),
			isset( $client_update['stateVector'] ) && is_array( $client_update['stateVector'] ) ? $client_update['stateVector'] : array()
		),
	);
	$merge_result['automerge_client_update']     = $client_update;
	$merge_result['automerge_server_update']     = $server_update;
	$merge_result['server_merge_strategy'] = 'native_automerge_blocks_v1';

	return $merge_result;
}

/**
 * Validates block-native client evidence against the submitted body.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $base_content     Accepted-base stripped content.
 * @param string $proposed_content Client-proposed stripped content.
 * @param array  $client_update    Normalized block-native update.
 * @return true|WP_Error True when valid, otherwise an error.
 */
function wp_de_rtc_validate_automerge_block_native_update_matches_content( $base_content, $proposed_content, $client_update ) {
	if ( ! is_array( $client_update ) || ! isset( $client_update['format'] ) || 'native-automerge-blocks-v1' !== $client_update['format'] ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the retry save because the block-native Automerge update is malformed.' ),
			array(
				'detail' => 'automerge_block_native_update_format_missing',
			)
		);
	}

	$base_hash     = wp_de_rtc_hash_content( $base_content );
	$proposed_hash = wp_de_rtc_hash_content( $proposed_content );

	if ( isset( $client_update['baseContentHash'] ) && is_string( $client_update['baseContentHash'] ) && ! hash_equals( $base_hash, $client_update['baseContentHash'] ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because the block-native base hash does not match.' ),
			array(
				'detail'               => 'automerge_block_native_base_hash_mismatch',
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	if ( isset( $client_update['proposedContentHash'] ) && is_string( $client_update['proposedContentHash'] ) && ! hash_equals( $proposed_hash, $client_update['proposedContentHash'] ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because the block-native proposed hash does not match.' ),
			array(
				'detail'               => 'automerge_block_native_proposed_hash_mismatch',
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$expected_update = wp_de_rtc_create_automerge_update_for_content_change( $base_content, $proposed_content, 'client' );
	$expected        = wp_de_rtc_get_automerge_block_native_operation_fingerprints( $expected_update['operations'] );
	$actual          = wp_de_rtc_get_automerge_block_native_operation_fingerprints( $client_update['operations'] );

	if ( $expected !== $actual ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because the block-native Automerge update did not match the proposed content.' ),
			array(
				'detail'               => 'automerge_client_update_materialization_mismatch',
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	return true;
}

/**
 * Returns comparable operation fingerprints without actor/session metadata.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array[] $operations Block-native operations.
 * @return array[] Comparable fingerprints.
 */
function wp_de_rtc_get_automerge_block_native_operation_fingerprints( $operations ) {
	$fingerprints = array();

	foreach ( is_array( $operations ) ? $operations : array() as $operation ) {
		if ( ! is_array( $operation ) ) {
			continue;
		}

		$fingerprints[] = array(
			'type'              => isset( $operation['type'] ) ? (string) $operation['type'] : '',
			'path'              => isset( $operation['path'] ) && is_array( $operation['path'] ) ? array_map( 'intval', $operation['path'] ) : null,
			'fromPath'          => isset( $operation['fromPath'] ) && is_array( $operation['fromPath'] ) ? array_map( 'intval', $operation['fromPath'] ) : null,
			'toPath'            => isset( $operation['toPath'] ) && is_array( $operation['toPath'] ) ? array_map( 'intval', $operation['toPath'] ) : null,
			'index'             => isset( $operation['index'] ) ? (int) $operation['index'] : null,
			'blockHash'         => isset( $operation['blockHash'] ) ? (string) $operation['blockHash'] : null,
			'baseBlockHash'     => isset( $operation['baseBlockHash'] ) ? (string) $operation['baseBlockHash'] : null,
			'proposedBlockHash' => isset( $operation['proposedBlockHash'] ) ? (string) $operation['proposedBlockHash'] : null,
			'blockName'         => isset( $operation['blockName'] ) ? (string) $operation['blockName'] : null,
			'baseBlockName'     => isset( $operation['baseBlockName'] ) ? (string) $operation['baseBlockName'] : null,
			'proposedBlockName' => isset( $operation['proposedBlockName'] ) ? (string) $operation['proposedBlockName'] : null,
			'serializedBlockHash' => isset( $operation['serializedBlock'] ) && is_string( $operation['serializedBlock'] ) ? wp_de_rtc_hash_content( $operation['serializedBlock'] ) : null,
			'changedTextIndexes' => isset( $operation['changedTextIndexes'] ) && is_array( $operation['changedTextIndexes'] ) ? array_map( 'intval', $operation['changedTextIndexes'] ) : null,
			'textSplice'        => wp_de_rtc_get_automerge_block_native_text_splice_fingerprint( isset( $operation['textSplice'] ) ? $operation['textSplice'] : null ),
		);
	}

	return $fingerprints;
}

/**
 * Returns comparable text-splice evidence without exposing inserted text.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array|null $splice Client or server text-splice evidence.
 * @return array|null Comparable text-splice fingerprint.
 */
function wp_de_rtc_get_automerge_block_native_text_splice_fingerprint( $splice ) {
	if ( ! is_array( $splice ) ) {
		return null;
	}

	$insert_text = isset( $splice['insertText'] ) ? (string) $splice['insertText'] : ( isset( $splice['insert_text'] ) ? (string) $splice['insert_text'] : '' );

	return array(
		'changed'        => ! empty( $splice['changed'] ),
		'start'          => isset( $splice['start'] ) ? (int) $splice['start'] : 0,
		'deleteCount'    => isset( $splice['deleteCount'] ) ? (int) $splice['deleteCount'] : ( isset( $splice['delete_count'] ) ? (int) $splice['delete_count'] : 0 ),
		'insertTextHash' => hash( 'sha256', $insert_text ),
		'insertCount'    => isset( $splice['insertCount'] ) ? (int) $splice['insertCount'] : ( isset( $splice['insert_count'] ) ? (int) $splice['insert_count'] : strlen( $insert_text ) ),
		'end'            => isset( $splice['end'] ) ? (int) $splice['end'] : 0,
		'delta'          => isset( $splice['delta'] ) ? (int) $splice['delta'] : 0,
	);
}

/**
 * Builds a current-base block-native merge result.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $base_content     Accepted-base stripped content.
 * @param string $proposed_content Client-proposed stripped content.
 * @return array|WP_Error Merge result.
 */
function wp_de_rtc_get_automerge_block_native_current_base_merge_result( $base_content, $proposed_content ) {
	$base_records     = wp_de_rtc_get_top_level_serialized_block_records( $base_content );
	$proposed_records = wp_de_rtc_get_top_level_serialized_block_records( $proposed_content );

	if ( is_wp_error( $proposed_records ) ) {
		return $proposed_records;
	}

	/*
	 * A current-base retry-save has no remote change to merge against. In that
	 * case, allow the editor to materialize a legacy/freeform server body as
	 * normal serialized blocks while still rejecting freeform boundaries in the
	 * proposed content and in stale three-way merge paths.
	 */
	$base_block_count = is_wp_error( $base_records ) ? null : count( $base_records );

	if ( is_wp_error( $base_records ) ) {
		$base_records = array();
	}

	return array(
		'merged_content'        => $proposed_content,
		'merge_status'          => 'merged',
		'merge_strategy'        => 'native_automerge_blocks_v1',
		'block_count'           => count( $proposed_records ),
		'base_block_count'      => $base_block_count,
		'server_block_count'    => $base_block_count,
		'proposed_block_count'  => count( $proposed_records ),
		'merged_block_count'    => count( $proposed_records ),
		'merged_stripped_content_hash' => wp_de_rtc_hash_content( $proposed_content ),
		'base_content_hash'     => wp_de_rtc_hash_content( $base_content ),
		'server_content_hash'   => wp_de_rtc_hash_content( $base_content ),
		'proposed_content_hash' => wp_de_rtc_hash_content( $proposed_content ),
	);
}

/**
 * Merges Automerge-style state vectors.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $left  First state vector.
 * @param array $right Second state vector.
 * @return array Merged state vector.
 */
	function wp_de_rtc_merge_automerge_state_vectors( $left, $right ) {
		$merged = array();

	foreach ( array( $left, $right ) as $vector ) {
		foreach ( is_array( $vector ) ? $vector : array() as $actor => $sequence ) {
			if ( ! is_string( $actor ) && ! is_int( $actor ) ) {
				continue;
			}

			$actor            = (string) $actor;
			$merged[ $actor ] = max( isset( $merged[ $actor ] ) ? (int) $merged[ $actor ] : 0, (int) $sequence );
		}
	}

		ksort( $merged );
		return $merged;
	}

	/**
	 * Returns the current retry-save request's server-owned authorship context.
	 *
	 * Clients may submit an opaque session key so WordPress can link saved changes
	 * to the same presence avatar. The persisted attribution key is derived from
	 * the server-side presence hash; client-supplied Automerge actor strings remain
	 * validation evidence only and are not trusted for authorship.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param WP_Post  $post        Post being saved.
	 * @param string   $session_key Opaque editor session key.
	 * @param int|null $user_id     Optional user to attribute the edit to. Defaults to current user.
	 * @return array Authorship context.
	 */
	function wp_de_rtc_get_retry_save_authorship_context( $post, $session_key = '', $user_id = null ) {
	$post            = get_post( $post );
	$post_id         = $post ? (int) $post->ID : 0;
	$attribution_key = wp_de_rtc_get_presence_attribution_key_for_session_key( $post_id, $session_key );
	$has_presence_attribution = '' !== $attribution_key;
	$user_id         = null === $user_id ? get_current_user_id() : absint( $user_id );

	if ( '' === $attribution_key ) {
			$actor_hash       = wp_de_rtc_get_presence_actor_hash( $user_id );
			$attribution_key = '' !== $actor_hash ? 'user:' . substr( $actor_hash, 0, 24 ) : 'server:unknown';
		}

	return array(
		'attributionKey'       => $attribution_key,
		'displayName'          => wp_de_rtc_get_history_author_display_name( $user_id ),
		'source'               => $has_presence_attribution ? 'presence_session' : 'current_user',
		'rawSessionKeyIncluded' => false,
		'exposesUserId'        => false,
		'exposesLogin'         => false,
			'exposesEmail'         => false,
		);
	}

	/**
	 * Rewrites client-authored Automerge operations to the server-owned key.
	 *
	 * Stale saves may include server-synthesized operations for already-persisted
	 * peer changes. Those stay as "server" and are ignored by the authorship
	 * update so existing attribution metadata remains the authority.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param array $automerge_result   Automerge retry-save result.
	 * @param array $authorship_context Server-owned authorship context.
	 * @return array Updated Automerge retry-save result.
	 */
	function wp_de_rtc_apply_authorship_context_to_automerge_result( $automerge_result, $authorship_context ) {
		if ( ! is_array( $automerge_result ) || empty( $authorship_context['attributionKey'] ) ) {
			return $automerge_result;
		}

		$attribution_key = (string) $authorship_context['attributionKey'];
		$rewrite_operations = static function ( $operations ) use ( $attribution_key ) {
			$rewritten = array();
			$sequence  = 0;

			foreach ( is_array( $operations ) ? $operations : array() as $operation ) {
				if ( ! is_array( $operation ) ) {
					continue;
				}

				if ( 'server' !== ( isset( $operation['actor'] ) ? (string) $operation['actor'] : '' ) ) {
					$operation['actor']    = $attribution_key;
					$operation['sequence'] = $sequence;
					$operation['id']       = $attribution_key . ':' . $sequence;
					++$sequence;
				}

				$rewritten[] = $operation;
			}

			return $rewritten;
		};

		if ( isset( $automerge_result['automerge_client_update']['operations'] ) && is_array( $automerge_result['automerge_client_update']['operations'] ) ) {
			$client_operations = $rewrite_operations( $automerge_result['automerge_client_update']['operations'] );
			$automerge_result['automerge_client_update']['operations']  = $client_operations;
			$automerge_result['automerge_client_update']['stateVector'] = count( $client_operations ) > 0 ? array( $attribution_key => count( $client_operations ) ) : array();
		}

		if ( isset( $automerge_result['automerge_metadata']['operations'] ) && is_array( $automerge_result['automerge_metadata']['operations'] ) ) {
			$metadata_operations = array();
			$client_count        = 0;

			foreach ( $automerge_result['automerge_metadata']['operations'] as $operation ) {
				if ( ! is_array( $operation ) ) {
					continue;
				}

				if ( 'server' !== ( isset( $operation['actor'] ) ? (string) $operation['actor'] : '' ) ) {
					$operation['actor']    = $attribution_key;
					$operation['sequence'] = $client_count;
					$operation['id']       = $attribution_key . ':' . $client_count;
					++$client_count;
				}

				$metadata_operations[] = $operation;
			}

			$state_vector = isset( $automerge_result['automerge_metadata']['stateVector'] ) && is_array( $automerge_result['automerge_metadata']['stateVector'] )
				? $automerge_result['automerge_metadata']['stateVector']
				: array();

			foreach ( array_keys( $state_vector ) as $actor ) {
				if ( 'server' !== (string) $actor ) {
					unset( $state_vector[ $actor ] );
				}
			}

			if ( $client_count > 0 ) {
				$state_vector[ $attribution_key ] = $client_count;
			}

			ksort( $state_vector );
			$automerge_result['automerge_metadata']['operations']  = $metadata_operations;
			$automerge_result['automerge_metadata']['stateVector'] = $state_vector;
		}

		return $automerge_result;
	}

	/**
	 * Adds or updates block authorship metadata in sync meta.
	 *
	 * The map intentionally stores attribution keys and text ranges, not raw
	 * content. Serialized hashes bind each entry to the current body while the
	 * actual post content remains the durable authority.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param array  $sync_meta           Existing sync metadata.
	 * @param string $save_post_content   Stripped content being saved.
	 * @param array  $automerge_result    Automerge retry-save result.
	 * @param array  $authorship_context  Server-owned authorship context.
	 * @return array Updated sync metadata.
	 */
	function wp_de_rtc_apply_automerge_authorship_to_sync_meta( $sync_meta, $save_post_content, $automerge_result, $authorship_context ) {
		if ( ! is_array( $sync_meta ) || empty( $authorship_context['attributionKey'] ) ) {
			return $sync_meta;
		}

		$records = wp_de_rtc_get_top_level_serialized_block_records( $save_post_content );

		if ( is_wp_error( $records ) ) {
			return $sync_meta;
		}

		$previous_blocks = array();
		if ( isset( $sync_meta['authorship']['blocks'] ) && is_array( $sync_meta['authorship']['blocks'] ) ) {
			foreach ( $sync_meta['authorship']['blocks'] as $block ) {
				if ( ! is_array( $block ) || ! isset( $block['path'] ) || ! is_array( $block['path'] ) ) {
					continue;
				}

				$previous_blocks[ implode( '.', array_map( 'intval', $block['path'] ) ) ] = $block;
			}
		}

		$blocks_by_path = array();
		foreach ( $records as $index => $record ) {
			$path_key = (string) (int) $index;
			$hash     = wp_de_rtc_hash_content( $record );
			$block_name = wp_de_rtc_get_serialized_block_record_name( $record );
			$previous   = array();

			if ( isset( $previous_blocks[ $path_key ] ) && is_array( $previous_blocks[ $path_key ] ) ) {
				$candidate_previous = $previous_blocks[ $path_key ];
				$previous_hash      = isset( $candidate_previous['serializedBlockHash'] ) ? (string) $candidate_previous['serializedBlockHash'] : '';
				$previous_name      = isset( $candidate_previous['blockName'] ) ? (string) $candidate_previous['blockName'] : '';
				$previous_rich_text = isset( $candidate_previous['richText'] ) && is_array( $candidate_previous['richText'] ) ? $candidate_previous['richText'] : array();

				if (
					( '' !== $previous_hash && hash_equals( $previous_hash, $hash ) ) ||
					( $block_name && $previous_name === $block_name && ! empty( $previous_rich_text['ranges'] ) )
				) {
					$previous = $candidate_previous;
				}
			}

			$blocks_by_path[ $path_key ] = array(
				'path'                => array( (int) $index ),
				'blockName'           => $block_name,
				'serializedBlockHash' => $hash,
				'attributionKey'      => isset( $previous['attributionKey'] ) && is_string( $previous['attributionKey'] ) ? $previous['attributionKey'] : null,
				'richText'            => isset( $previous['richText'] ) && is_array( $previous['richText'] ) ? $previous['richText'] : array(),
			);
		}

		$attribution_key = (string) $authorship_context['attributionKey'];
		$operations      = isset( $automerge_result['automerge_client_update']['operations'] ) && is_array( $automerge_result['automerge_client_update']['operations'] )
			? $automerge_result['automerge_client_update']['operations']
			: array();

		foreach ( $operations as $operation ) {
			if ( ! is_array( $operation ) || ( isset( $operation['actor'] ) && (string) $operation['actor'] !== $attribution_key ) ) {
				continue;
			}

			$path = isset( $operation['path'] ) && is_array( $operation['path'] ) ? array_map( 'intval', $operation['path'] ) : array();
			if ( 1 !== count( $path ) ) {
				continue;
			}

			$path_key = (string) $path[0];
			if ( ! isset( $blocks_by_path[ $path_key ] ) ) {
				continue;
			}

			$type = isset( $operation['type'] ) ? (string) $operation['type'] : '';
			if ( in_array( $type, array( 'block.insert', 'block.replace', 'block.update_serialized' ), true ) ) {
				$blocks_by_path[ $path_key ]['attributionKey'] = $attribution_key;
				$blocks_by_path[ $path_key ]['richText']       = array();
				continue;
			}

			if ( in_array( $type, array( 'block.rich_text_content', 'block.rich_text_format' ), true ) ) {
				$blocks_by_path[ $path_key ]['attributionKey'] = null;
				$blocks_by_path[ $path_key ]['richText']       = wp_de_rtc_add_automerge_authorship_rich_text_ranges(
					$blocks_by_path[ $path_key ]['richText'],
					$operation,
					$attribution_key
				);
			}
		}

		$sessions = isset( $sync_meta['authorship']['sessions'] ) && is_array( $sync_meta['authorship']['sessions'] )
			? $sync_meta['authorship']['sessions']
			: array();
		$sessions[ $attribution_key ] = array(
			'attributionKey'       => $attribution_key,
			'displayName'          => isset( $authorship_context['displayName'] ) ? (string) $authorship_context['displayName'] : __( 'Editor' ),
			'source'               => isset( $authorship_context['source'] ) ? (string) $authorship_context['source'] : 'presence_session',
			'rawSessionKeyIncluded' => false,
			'exposesUserId'        => false,
			'exposesLogin'         => false,
			'exposesEmail'         => false,
		);

		$sync_meta['authorship'] = array(
			'schema'              => 'de-rtc-authorship-v1',
			'updatedAtGmt'        => current_time( 'mysql', true ),
			'contentFree'         => true,
			'sessions'            => $sessions,
			'blocks'              => array_values( $blocks_by_path ),
			'rawContentIncluded'  => false,
			'rawSessionKeyIncluded' => false,
		);

		return $sync_meta;
	}

	/**
	 * Adds rich-text attribution ranges from a block-native operation.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param array  $rich_text       Existing rich-text attribution metadata.
	 * @param array  $operation       Block-native Automerge operation.
	 * @param string $attribution_key Server-owned attribution key.
	 * @return array Updated rich-text attribution metadata.
	 */
	function wp_de_rtc_add_automerge_authorship_rich_text_ranges( $rich_text, $operation, $attribution_key ) {
		$rich_text = is_array( $rich_text ) ? $rich_text : array();
		$ranges    = isset( $rich_text['ranges'] ) && is_array( $rich_text['ranges'] ) ? $rich_text['ranges'] : array();
		$type      = isset( $operation['type'] ) ? (string) $operation['type'] : '';

		if ( 'block.rich_text_content' === $type && isset( $operation['textSplice'] ) && is_array( $operation['textSplice'] ) ) {
			$start        = isset( $operation['textSplice']['start'] ) ? (int) $operation['textSplice']['start'] : 0;
			$insert_count = isset( $operation['textSplice']['insertCount'] ) ? (int) $operation['textSplice']['insertCount'] : 0;
			if ( $insert_count > 0 ) {
				$ranges[] = array(
					'start'          => max( 0, $start ),
					'end'            => max( 0, $start + $insert_count ),
					'attributionKey' => $attribution_key,
					'changeKind'     => 'text_insert',
				);
			}
		}

		if ( 'block.rich_text_format' === $type && isset( $operation['changedTextIndexes'] ) && is_array( $operation['changedTextIndexes'] ) ) {
			foreach ( wp_de_rtc_get_contiguous_integer_ranges( $operation['changedTextIndexes'] ) as $range ) {
				$ranges[] = array(
					'start'          => $range['start'],
					'end'            => $range['end'],
					'attributionKey' => $attribution_key,
					'changeKind'     => 'format_change',
				);
			}
		}

		return array(
			'field'             => isset( $operation['field'] ) ? sanitize_key( (string) $operation['field'] ) : 'innerHTML',
			'ranges'            => wp_de_rtc_normalize_automerge_authorship_ranges( $ranges ),
			'rawContentIncluded' => false,
		);
	}

	/**
	 * Returns sorted contiguous integer ranges as half-open [start, end) spans.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param int[] $indexes Integer indexes.
	 * @return array[] Half-open ranges.
	 */
	function wp_de_rtc_get_contiguous_integer_ranges( $indexes ) {
		$indexes = array_values( array_unique( array_map( 'intval', is_array( $indexes ) ? $indexes : array() ) ) );
		sort( $indexes, SORT_NUMERIC );
		$ranges = array();
		$start  = null;
		$end    = null;

		foreach ( $indexes as $index ) {
			if ( null === $start ) {
				$start = $index;
				$end   = $index + 1;
				continue;
			}

			if ( $index === $end ) {
				$end = $index + 1;
				continue;
			}

			$ranges[] = array(
				'start' => max( 0, $start ),
				'end'   => max( 0, $end ),
			);
			$start = $index;
			$end   = $index + 1;
		}

		if ( null !== $start ) {
			$ranges[] = array(
				'start' => max( 0, $start ),
				'end'   => max( 0, $end ),
			);
		}

		return $ranges;
	}

	/**
	 * Normalizes rich-text attribution ranges.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param array[] $ranges Candidate ranges.
	 * @return array[] Normalized ranges.
	 */
	function wp_de_rtc_normalize_automerge_authorship_ranges( $ranges ) {
		$normalized = array();

		foreach ( is_array( $ranges ) ? $ranges : array() as $range ) {
			if ( ! is_array( $range ) || empty( $range['attributionKey'] ) ) {
				continue;
			}

			$start = isset( $range['start'] ) ? max( 0, (int) $range['start'] ) : 0;
			$end   = isset( $range['end'] ) ? max( 0, (int) $range['end'] ) : 0;

			if ( $end <= $start ) {
				continue;
			}

			$normalized[] = array(
				'start'          => $start,
				'end'            => $end,
				'attributionKey' => sanitize_text_field( (string) $range['attributionKey'] ),
				'changeKind'     => isset( $range['changeKind'] ) ? sanitize_key( (string) $range['changeKind'] ) : 'unknown',
			);
		}

		usort(
			$normalized,
			static function ( $left, $right ) {
				if ( $left['start'] === $right['start'] ) {
					return $left['end'] <=> $right['end'];
				}

				return $left['start'] <=> $right['start'];
			}
		);

		return array_slice( $normalized, -100 );
	}

	/**
	 * Returns public Automerge encoding evidence for a retry-save result.
	 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $automerge_result Retry-save Automerge result.
 * @return string|null Encoding label, or null when no Automerge result exists.
 */
function wp_de_rtc_get_automerge_result_encoding( $automerge_result ) {
	if ( ! is_array( $automerge_result ) ) {
		return null;
	}

	if (
		isset( $automerge_result['automerge_metadata'] ) &&
		is_array( $automerge_result['automerge_metadata'] ) &&
		isset( $automerge_result['automerge_metadata']['format'] ) &&
		is_string( $automerge_result['automerge_metadata']['format'] )
	) {
		return sanitize_text_field( $automerge_result['automerge_metadata']['format'] );
	}

	return 'native-automerge-php-v1';
}

/**
 * Adds server-owned native Automerge metadata to sync metadata.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array  $sync_meta        Existing sync metadata.
 * @param array  $automerge_result       Automerge retry-save result.
 * @param string $save_content_hash Hash of stripped saved content.
 * @return array|WP_Error Updated sync metadata or an error.
 */
	function wp_de_rtc_apply_automerge_metadata_to_sync_meta( $sync_meta, $automerge_result, $save_content_hash ) {
		$metadata     = isset( $automerge_result['automerge_metadata'] ) && is_array( $automerge_result['automerge_metadata'] ) ? $automerge_result['automerge_metadata'] : array();
		$operations   = isset( $metadata['operations'] ) && is_array( $metadata['operations'] ) ? array_values( $metadata['operations'] ) : array();
		$state_vector = isset( $metadata['stateVector'] ) && is_array( $metadata['stateVector'] ) ? $metadata['stateVector'] : array();
		$format       = isset( $metadata['format'] ) && 'native-automerge-blocks-v1' === $metadata['format'] ? 'native-automerge-blocks-v1' : 'native-automerge-php-v1';
		$schema       = 'native-automerge-blocks-v1' === $format ? 'de-rtc-automerge-v1' : 'de-rtc-automerge-v1';
	$update       = array(
		'format'      => $format,
		'schema'      => $schema,
		'operations'  => $operations,
		'stateVector' => $state_vector,
	);
	$encoded      = wp_json_encode( $update, JSON_UNESCAPED_SLASHES );

	if ( false === $encoded ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing could not encode the Automerge metadata.' ),
			array(
				'detail' => 'automerge_metadata_encode_failed',
			)
		);
	}

	$sync_meta['schema']            = $schema;
	$sync_meta['automerge_encoding']      = $format;
	$sync_meta['automerge_state_vector']  = $state_vector;
	$sync_meta['automerge_update']        = base64_encode( $encoded );
	$sync_meta['automerge_operation_count'] = count( $operations );
	$sync_meta['post_content_hash'] = $save_content_hash;

	return $sync_meta;
}

/**
 * Returns how many stripped-content snapshots Automerge sync meta should keep.
 *
 * These snapshots are a compatibility bridge for old REST clients that only
 * know a CRDT document version. Healthy saves resolve the referenced base
 * from current post_content metadata instead of scanning WordPress revisions.
 *
 * @since 7.1.0
 * @access private
 *
 * @return int Snapshot limit.
 */
function wp_de_rtc_get_automerge_version_snapshot_limit() {
	return 20;
}

/**
 * Adds bounded base-version snapshots to Automerge sync metadata.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array       $sync_meta        Existing sync metadata.
 * @param string      $previous_version Previous server version.
 * @param string      $previous_content Previous stripped post content.
 * @param string|null $next_version     Optional next server version.
 * @param string|null $next_content     Optional next stripped post content.
 * @return array Updated sync metadata.
 */
function wp_de_rtc_update_automerge_version_snapshots( $sync_meta, $previous_version, $previous_content, $next_version = null, $next_content = null ) {
	if ( ! is_array( $sync_meta ) ) {
		$sync_meta = array();
	}

	$snapshots = isset( $sync_meta['version_snapshots'] ) && is_array( $sync_meta['version_snapshots'] )
		? $sync_meta['version_snapshots']
		: array();

	$add_snapshot = static function ( $version, $content ) use ( &$snapshots ) {
		$version = sanitize_text_field( (string) $version );

		if ( '' === $version || ! is_string( $content ) ) {
			return;
		}

		unset( $snapshots[ $version ] );

		$snapshots[ $version ] = array(
			'encoding'         => 'base64',
			'content_base64'   => base64_encode( $content ),
			'content_hash'     => wp_de_rtc_hash_content( $content ),
			'raw_content_hash' => hash( 'sha256', $content ),
		);
	};

	$add_snapshot( $previous_version, $previous_content );

	if ( null !== $next_version && null !== $next_content ) {
		$add_snapshot( $next_version, $next_content );
	}

	$limit = wp_de_rtc_get_automerge_version_snapshot_limit();

	if ( count( $snapshots ) > $limit ) {
		$snapshots = array_slice( $snapshots, -$limit, null, true );
	}

	$sync_meta['version_snapshots']       = $snapshots;
	$sync_meta['version_snapshot_count'] = count( $snapshots );
	$sync_meta['version_snapshot_limit'] = $limit;

	return $sync_meta;
}

/**
 * Resolves a CRDT document version to stripped content from current sync meta.
 *
 * @since 7.1.0
 * @access private
 *
 * @param int|WP_Post $post         Post being updated.
 * @param array       $current      Parsed current post content.
 * @param mixed       $base_version Requested CRDT document version.
 * @return array|WP_Error Base content evidence or an error.
 */
function wp_de_rtc_get_automerge_base_content_for_version( $post, $current, $base_version ) {
	$post         = get_post( $post );
	$base_version = sanitize_text_field( (string) $base_version );

	if (
		'' === $base_version ||
		! is_array( $current ) ||
		! isset( $current['content'] ) ||
		! is_string( $current['content'] ) ||
		! isset( $current['sync_meta'] ) ||
		! is_array( $current['sync_meta'] )
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing could not resolve the requested base version.' ),
			array(
				'detail'               => 'automerge_base_version_resolution_payload_malformed',
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$server_version = isset( $current['sync_meta']['version'] ) ? sanitize_text_field( (string) $current['sync_meta']['version'] ) : '';

	if ( $server_version === $base_version ) {
		return array(
			'found'        => true,
			'version'      => $base_version,
			'content'      => $current['content'],
			'source'       => 'current_post_content',
			'content_hash' => wp_de_rtc_hash_content( $current['content'] ),
		);
	}

	$snapshots = isset( $current['sync_meta']['version_snapshots'] ) && is_array( $current['sync_meta']['version_snapshots'] )
		? $current['sync_meta']['version_snapshots']
		: array();

	if ( ! isset( $snapshots[ $base_version ] ) || ! is_array( $snapshots[ $base_version ] ) ) {
		return wp_de_rtc_get_stale_base_rejection_error(
			$post,
			array(
				'client_base_version'      => $base_version,
				'server_version'           => $server_version,
				'rest_route'               => 'post_save_base_version_update',
				'can_attempt_local_rebase' => false,
			)
		);
	}

	$snapshot = $snapshots[ $base_version ];
	$encoded  = isset( $snapshot['content_base64'] ) && is_string( $snapshot['content_base64'] ) ? $snapshot['content_base64'] : '';
	$content  = base64_decode( $encoded, true );

	if ( ! is_string( $content ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the update because the base-version snapshot is malformed.' ),
			array(
				'detail'               => 'automerge_base_version_snapshot_decode_failed',
				'client_base_version'  => $base_version,
				'server_version'       => $server_version,
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	$content_hash     = wp_de_rtc_hash_content( $content );
	$stored_hash      = isset( $snapshot['content_hash'] ) ? sanitize_text_field( (string) $snapshot['content_hash'] ) : '';
	$stored_raw_hash  = isset( $snapshot['raw_content_hash'] ) ? sanitize_text_field( (string) $snapshot['raw_content_hash'] ) : '';
	$content_raw_hash = hash( 'sha256', $content );

	if (
		( '' !== $stored_hash && ! hash_equals( $stored_hash, $content_hash ) ) ||
		( '' !== $stored_raw_hash && ! hash_equals( $stored_raw_hash, $content_raw_hash ) )
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the update because the base-version snapshot hash does not match.' ),
			array(
				'detail'               => 'automerge_base_version_snapshot_hash_mismatch',
				'client_base_version'  => $base_version,
				'server_version'       => $server_version,
				'raw_content_included' => false,
				'saves_post'           => false,
				'mutates_post_content' => false,
				'creates_revision'     => false,
				'claims_saved'         => false,
			)
		);
	}

	return array(
		'found'        => true,
		'version'      => $base_version,
		'content'      => $content,
		'source'       => 'current_sync_meta_version_snapshot',
		'content_hash' => $content_hash,
	);
}

	/**
	 * Returns whether parsed sync metadata is the current server-owned Automerge schema.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param mixed  $sync_meta Sync metadata.
	 * @param string $format    Parsed sync-meta format.
	 * @return bool Whether the metadata is the current Automerge schema.
	 */
function wp_de_rtc_is_current_automerge_sync_meta( $sync_meta, $format ) {
	return (
		'automerge' === $format &&
		is_array( $sync_meta ) &&
		isset( $sync_meta['schema'] ) &&
		'de-rtc-automerge-v1' === $sync_meta['schema']
	);
}

	/**
	 * Returns the stripped-content hash recorded in Automerge sync metadata.
	 *
	 * External writers can change the body while leaving the pseudo-block intact.
	 * The server treats the stored hash as a cheap coherence check; it is not a
	 * client proof and must be repaired only by server-owned save paths.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param array $sync_meta Sync metadata.
	 * @return string|null Stored stripped-content hash, or null when unavailable.
	 */
	function wp_de_rtc_get_automerge_sync_meta_content_hash( $sync_meta ) {
		if ( ! is_array( $sync_meta ) ) {
			return null;
		}

		foreach ( array( 'post_content_hash', 'content_hash' ) as $field ) {
			if ( isset( $sync_meta[ $field ] ) && wp_de_rtc_is_sha256_hash( $sync_meta[ $field ] ) ) {
				return (string) $sync_meta[ $field ];
			}
		}

		if (
			isset( $sync_meta['last_server_update'] ) &&
			is_array( $sync_meta['last_server_update'] ) &&
			isset( $sync_meta['last_server_update']['saved_stripped_content_hash'] ) &&
			wp_de_rtc_is_sha256_hash( $sync_meta['last_server_update']['saved_stripped_content_hash'] )
		) {
			return (string) $sync_meta['last_server_update']['saved_stripped_content_hash'];
		}

		return null;
	}

	/**
	 * Creates empty Automerge sync metadata for a server-side import repair.
	 *
	 * This is the last-resort path for content whose pseudo-block was deleted and
	 * no usable revision can restore it. It deliberately preserves no old history;
	 * the next repair update imports the current body as the first Automerge change.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param WP_Post $post Post being repaired.
	 * @return array Empty server-owned Automerge sync metadata.
	 */
	function wp_de_rtc_get_empty_automerge_sync_meta_for_external_import( $post ) {
		$post = get_post( $post );

		return array(
			'schema'              => 'de-rtc-automerge-v1',
			'version'             => '0',
			'previous_version'    => null,
			'automerge_encoding'        => 'native-automerge-blocks-v1',
			'automerge_state_vector'    => array(),
			'automerge_update'          => base64_encode( '{"format":"native-automerge-blocks-v1","schema":"de-rtc-automerge-v1","operations":[],"stateVector":[]}' ),
			'automerge_operation_count' => 0,
			'post_content_hash'   => wp_de_rtc_hash_content( '' ),
			'document_uuid'       => $post ? 'de-rtc-post-' . (int) $post->ID : 'de-rtc-post-0',
		);
	}

	/**
	 * Returns the synthetic actor descriptor for server-side sync-meta recovery.
	 *
	 * Recovery models content changed outside Distributed Editing as a server-made
	 * metadata repair. It must not borrow the identity of the user who happened to
	 * trigger the repair endpoint or create a fake WordPress user.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param WP_Post|int|null $post Post being repaired.
	 * @param array            $args Content-free repair evidence used to derive a per-repair actor ID.
	 * @return array Synthetic recovery actor descriptor.
	 */
	function wp_de_rtc_get_system_recovery_actor_descriptor( $post = null, $args = array() ) {
		$post                 = get_post( $post );
		$args                 = is_array( $args ) ? $args : array();
		$post_id              = $post ? (int) $post->ID : 0;
		$document_uuid        = isset( $args['document_uuid'] ) && is_string( $args['document_uuid'] ) && '' !== $args['document_uuid']
			? sanitize_text_field( $args['document_uuid'] )
			: 'de-rtc-post-' . $post_id;
		$base_version         = isset( $args['base_version'] ) ? sanitize_text_field( (string) $args['base_version'] ) : '0';
		$mode                 = isset( $args['mode'] ) ? sanitize_key( (string) $args['mode'] ) : 'sync_meta_recovery';
		$base_revision_id     = isset( $args['base_revision_id'] ) ? (int) $args['base_revision_id'] : 0;
		$current_content_hash = isset( $args['current_content_hash'] ) && is_string( $args['current_content_hash'] ) ? sanitize_text_field( $args['current_content_hash'] ) : '';
		$actor_id             = 'wp-de-rtc-recovery-' . substr( hash( 'sha256', implode( '|', array( $document_uuid, $post_id, $base_version, $mode, $base_revision_id, $current_content_hash ) ) ), 0, 24 );

		return array(
			'actor_type'          => 'system',
			'actor_id'            => $actor_id,
			'attribution_key'     => 'system:distributed-editing-recovery',
			'display_name'        => 'Recovered external changes',
			'source'              => 'sync_meta_recovery',
			'human_actor'         => false,
			'focusable'           => false,
			'exposes_user_id'     => false,
			'exposes_login'       => false,
			'exposes_email'       => false,
			'exposes_session_key' => false,
		);
	}

	/**
	 * Returns whether a value is the canonical server recovery actor descriptor.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param mixed       $actor             Candidate descriptor.
	 * @param string|null $expected_actor_id Optional expected per-repair actor ID.
	 * @return bool Whether the descriptor is the server-owned recovery actor.
	 */
	function wp_de_rtc_is_system_recovery_actor_descriptor( $actor, $expected_actor_id = null ) {
		if ( ! is_array( $actor ) ) {
			return false;
		}

		foreach ( array( 'user_id', 'userId', 'login', 'user_login', 'email', 'user_email', 'session_key', 'sessionKey' ) as $forbidden_key ) {
			if ( array_key_exists( $forbidden_key, $actor ) ) {
				return false;
			}
		}

		if (
			! isset( $actor['actor_type'], $actor['actor_id'], $actor['attribution_key'], $actor['source'] ) ||
			! isset( $actor['display_name'] ) ||
			! is_string( $actor['display_name'] ) ||
			'' === trim( $actor['display_name'] ) ||
			! array_key_exists( 'human_actor', $actor ) ||
			! array_key_exists( 'focusable', $actor ) ||
			! array_key_exists( 'exposes_user_id', $actor ) ||
			! array_key_exists( 'exposes_login', $actor ) ||
			! array_key_exists( 'exposes_email', $actor ) ||
			! array_key_exists( 'exposes_session_key', $actor ) ||
			'system' !== $actor['actor_type'] ||
			'system:distributed-editing-recovery' !== $actor['attribution_key'] ||
			'sync_meta_recovery' !== $actor['source'] ||
			false !== $actor['human_actor'] ||
			false !== $actor['focusable'] ||
			false !== $actor['exposes_user_id'] ||
			false !== $actor['exposes_login'] ||
			false !== $actor['exposes_email'] ||
			false !== $actor['exposes_session_key']
		) {
			return false;
		}

		if ( null !== $expected_actor_id && ! hash_equals( (string) $expected_actor_id, (string) $actor['actor_id'] ) ) {
			return false;
		}

		return true;
	}

	/**
	 * Adds server recovery attribution to native Automerge update evidence.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param array $update Native Automerge update evidence.
	 * @param array $actor  Recovery actor descriptor.
	 * @return array Update evidence with system attribution.
	 */
	function wp_de_rtc_apply_system_recovery_actor_to_automerge_update( $update, $actor ) {
		if ( ! is_array( $update ) || ! wp_de_rtc_is_system_recovery_actor_descriptor( $actor ) ) {
			return $update;
		}

		$update['actor_type']      = 'system';
		$update['attribution_key'] = $actor['attribution_key'];
		$update['human_actor']     = false;
		$update['repair_actor']    = $actor;

		if ( isset( $update['operations'] ) && is_array( $update['operations'] ) ) {
			foreach ( $update['operations'] as $index => $operation ) {
				if ( ! is_array( $operation ) ) {
					continue;
				}

				$operation['actor']           = $actor['actor_id'];
				$operation['actor_type']      = 'system';
				$operation['attribution_key'] = $actor['attribution_key'];
				$operation['human_actor']     = false;
				$operation['sequence']        = isset( $operation['sequence'] ) ? (int) $operation['sequence'] : (int) $index;
				$operation['id']              = $actor['actor_id'] . ':' . $operation['sequence'];
				$update['operations'][ $index ] = $operation;
			}
		}

		if ( isset( $update['operations'], $update['stateVector'] ) && is_array( $update['operations'] ) && is_array( $update['stateVector'] ) && count( $update['operations'] ) > 0 ) {
			$update['stateVector'] = array(
				$actor['actor_id'] => count( $update['operations'] ),
			);
		}

		return $update;
	}

	/**
	 * Returns recovery attribution stored in sync metadata.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param mixed $sync_meta Sync metadata.
	 * @return array|null Recovery attribution descriptor, or null when absent.
	 */
	function wp_de_rtc_get_sync_meta_recovery_attribution( $sync_meta ) {
		if ( ! is_array( $sync_meta ) ) {
			return null;
		}

		if (
			isset( $sync_meta['last_sync_meta_recovery'] ) &&
			is_array( $sync_meta['last_sync_meta_recovery'] ) &&
			isset( $sync_meta['last_sync_meta_recovery']['actor'] ) &&
			wp_de_rtc_is_system_recovery_actor_descriptor( $sync_meta['last_sync_meta_recovery']['actor'] )
		) {
			return $sync_meta['last_sync_meta_recovery'];
		}

		if (
			isset( $sync_meta['last_server_update'] ) &&
			is_array( $sync_meta['last_server_update'] ) &&
			isset( $sync_meta['last_server_update']['repair_actor'] ) &&
			wp_de_rtc_is_system_recovery_actor_descriptor( $sync_meta['last_server_update']['repair_actor'] )
		) {
			return array(
				'type'  => isset( $sync_meta['last_server_update']['type'] ) ? sanitize_key( (string) $sync_meta['last_server_update']['type'] ) : 'external_repair',
				'actor' => $sync_meta['last_server_update']['repair_actor'],
			);
		}

		return null;
	}

	/**
	 * Returns content-free response fields for recovery attribution.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param array|null $attribution Recovery attribution descriptor.
	 * @return array Response fields.
	 */
	function wp_de_rtc_get_recovery_attribution_response_fields( $attribution ) {
		if (
			! is_array( $attribution ) ||
			! isset( $attribution['actor'] ) ||
			! wp_de_rtc_is_system_recovery_actor_descriptor( $attribution['actor'] )
		) {
			return array(
				'recovery_attribution'        => null,
				'recovery_actor_type'         => null,
				'recovery_attribution_key'    => null,
				'recovery_attribution_source' => null,
			);
		}

		$actor = $attribution['actor'];

		return array(
			'recovery_attribution'        => array(
				'type'                    => isset( $attribution['type'] ) ? sanitize_key( (string) $attribution['type'] ) : 'sync_meta_recovery',
				'mode'                    => isset( $attribution['mode'] ) ? sanitize_key( (string) $attribution['mode'] ) : '',
				'actor_type'              => $actor['actor_type'],
				'attribution_key'         => $actor['attribution_key'],
				'display_name'            => $actor['display_name'],
				'source'                  => $actor['source'],
				'human_actor'             => false,
				'focusable'               => false,
				'exposes_user_id'         => false,
				'exposes_login'           => false,
				'exposes_email'           => false,
				'exposes_session_key'     => false,
				'content_hash_algorithm'  => isset( $attribution['content_hash_algorithm'] ) ? sanitize_key( (string) $attribution['content_hash_algorithm'] ) : 'sha256',
			),
			'recovery_actor_type'         => $actor['actor_type'],
			'recovery_attribution_key'    => $actor['attribution_key'],
			'recovery_attribution_source' => $actor['source'],
		);
	}

	/**
	 * Validates server-owned recovery attribution in a candidate sync-meta value.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param mixed $sync_meta Candidate sync metadata.
	 * @return bool Whether recovery attribution is canonical and non-human.
	 */
	function wp_de_rtc_validate_sync_meta_recovery_attribution( $sync_meta ) {
		$attribution = wp_de_rtc_get_sync_meta_recovery_attribution( $sync_meta );

		if ( ! is_array( $attribution ) || ! isset( $attribution['actor'] ) ) {
			return false;
		}

		$actor = $attribution['actor'];

		if ( ! wp_de_rtc_is_system_recovery_actor_descriptor( $actor ) ) {
			return false;
		}

		if (
			isset( $sync_meta['last_server_update'] ) &&
			is_array( $sync_meta['last_server_update'] ) &&
			array_key_exists( 'user_id', $sync_meta['last_server_update'] ) &&
			'external_repair' === ( $sync_meta['last_server_update']['type'] ?? null )
		) {
			return false;
		}

		if ( wp_de_rtc_is_current_automerge_sync_meta( $sync_meta, 'automerge' ) && isset( $sync_meta['automerge_update'] ) ) {
			$update = wp_de_rtc_decode_automerge_sync_meta_update( $sync_meta['automerge_update'] );

			if ( is_wp_error( $update ) || ! is_array( $update ) ) {
				return false;
			}

			$operations = isset( $update['operations'] ) && is_array( $update['operations'] ) ? $update['operations'] : array();

			foreach ( $operations as $index => $operation ) {
				if (
					! is_array( $operation ) ||
					! isset( $operation['actor'], $operation['id'] ) ||
					! hash_equals( $actor['actor_id'], (string) $operation['actor'] ) ||
					! hash_equals( $actor['actor_id'] . ':' . ( isset( $operation['sequence'] ) ? (int) $operation['sequence'] : (int) $index ), (string) $operation['id'] )
				) {
					return false;
				}
			}

			$state_vector = isset( $update['stateVector'] ) && is_array( $update['stateVector'] ) ? $update['stateVector'] : array();

			if ( count( $operations ) > 0 && ( ! isset( $state_vector[ $actor['actor_id'] ] ) || (int) $state_vector[ $actor['actor_id'] ] !== count( $operations ) ) ) {
				return false;
			}
		}

		return true;
	}

	/**
	 * Builds a server-owned Automerge repair for current post content.
	 *
	 * The body remains authoritative when an outside writer changes it. This
	 * helper models that outside change as one Automerge update from the last trusted
	 * body to the current stripped body, then returns repaired metadata for the
	 * caller's eventual save candidate. It does not persist the repair by itself.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param WP_Post $post              Post being repaired.
	 * @param array   $args {
	 *     Repair arguments.
	 *
	 *     @type string $base_content      Trusted stripped base content.
	 *     @type array  $base_sync_meta    Trusted base Automerge sync metadata.
	 *     @type string $base_version      Trusted base sync version.
	 *     @type string $current_content   Current stripped post content.
	 *     @type string $mode              Repair mode label.
	 *     @type int    $base_revision_id  Trusted base revision ID. Default 0.
	 *     @type string $sync_meta_position Position for the repaired pseudo-block.
	 * }
	 * @return array|WP_Error Repair data, or an error.
	 */
	function wp_de_rtc_get_automerge_external_repair_update( $post, $args ) {
		$post            = get_post( $post );
		$base_content    = isset( $args['base_content'] ) && is_string( $args['base_content'] ) ? $args['base_content'] : '';
		$current_content = isset( $args['current_content'] ) && is_string( $args['current_content'] ) ? $args['current_content'] : '';
		$base_sync_meta  = isset( $args['base_sync_meta'] ) && is_array( $args['base_sync_meta'] ) ? $args['base_sync_meta'] : array();
		$base_version    = isset( $args['base_version'] ) ? sanitize_text_field( (string) $args['base_version'] ) : '0';
		$mode            = isset( $args['mode'] ) ? sanitize_key( (string) $args['mode'] ) : 'body_hash_drift';
		$base_revision_id = isset( $args['base_revision_id'] ) ? (int) $args['base_revision_id'] : 0;
		$sync_meta_position = isset( $args['sync_meta_position'] ) && is_string( $args['sync_meta_position'] ) ? $args['sync_meta_position'] : 'prefix-block';
		$current_hash    = wp_de_rtc_hash_content( $current_content );
		$recovery_actor  = wp_de_rtc_get_system_recovery_actor_descriptor(
			$post,
			array(
				'document_uuid'        => isset( $base_sync_meta['document_uuid'] ) && is_string( $base_sync_meta['document_uuid'] ) ? $base_sync_meta['document_uuid'] : null,
				'base_version'         => $base_version,
				'mode'                 => $mode,
				'base_revision_id'     => $base_revision_id,
				'current_content_hash' => $current_hash,
			)
		);
		$actor           = $recovery_actor['actor_id'];
		$external_update = wp_de_rtc_create_legacy_automerge_update_for_content_change( $base_content, $current_content, $actor );
		$external_update = wp_de_rtc_apply_system_recovery_actor_to_automerge_update( $external_update, $recovery_actor );
		$port            = wp_de_rtc_get_automerge_native_port();

		if ( is_wp_error( $port ) ) {
			return $port;
		}

		try {
			$base_document = $port->createDocument(
				$base_content,
				array(
					'schema'       => 'de-rtc-automerge-v1',
					'actorId'      => $actor,
					'repair_mode'  => $mode,
					'base_version' => $base_version,
				)
			);
			$repair_document = $port->applyServerPostUpdate( $base_document, $current_content, $actor );
			$materialized    = $port->materialize( $repair_document );
		} catch ( Throwable $exception ) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_sync_meta_unrecoverable',
				__( 'Distributed Editing could not materialize the external post update.' ),
				array(
					'detail'          => 'automerge_external_repair_materialization_failed',
					'exception_class' => get_class( $exception ),
				)
			);
		}

		if ( ! is_string( $materialized ) || $materialized !== $current_content ) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_sync_meta_tampered',
				__( 'Distributed Editing could not verify the external post update.' ),
				array(
					'detail'                    => 'automerge_external_repair_materialization_mismatch',
					'base_content_hash'         => wp_de_rtc_hash_content( $base_content ),
					'current_content_hash'      => wp_de_rtc_hash_content( $current_content ),
					'materialized_content_hash' => is_string( $materialized ) ? wp_de_rtc_hash_content( $materialized ) : null,
					'saves_post'                => false,
					'mutates_post_content'      => false,
					'creates_revision'          => false,
					'claims_saved'              => false,
				)
			);
		}

		$next_version  = wp_de_rtc_get_next_sync_meta_version( $base_version, $current_hash );
		$base_records  = wp_de_rtc_get_top_level_serialized_block_records( $base_content );
		$current_records = wp_de_rtc_get_top_level_serialized_block_records( $current_content );
		$automerge_result = array(
			'merged_content'        => $current_content,
			'merge_status'          => 'merged',
			'merge_strategy'        => 'native_automerge_external_repair_v1',
			'block_count'           => is_wp_error( $current_records ) ? null : count( $current_records ),
			'base_block_count'      => is_wp_error( $base_records ) ? null : count( $base_records ),
			'server_block_count'    => is_wp_error( $base_records ) ? null : count( $base_records ),
			'proposed_block_count'  => is_wp_error( $current_records ) ? null : count( $current_records ),
			'merged_block_count'    => is_wp_error( $current_records ) ? null : count( $current_records ),
			'merged_stripped_content_hash' => $current_hash,
			'base_content_hash'     => wp_de_rtc_hash_content( $base_content ),
			'server_content_hash'   => wp_de_rtc_hash_content( $base_content ),
			'proposed_content_hash' => $current_hash,
			'automerge_metadata'    => array(
				'format'      => 'native-automerge-php-v1',
				'schema'      => 'de-rtc-automerge-v1',
				'operations'  => isset( $external_update['operations'] ) && is_array( $external_update['operations'] ) ? $external_update['operations'] : array(),
				'stateVector' => isset( $external_update['stateVector'] ) && is_array( $external_update['stateVector'] ) ? $external_update['stateVector'] : array(),
				'repair_actor' => $recovery_actor,
			),
			'automerge_client_update' => $external_update,
			'automerge_external_repair_update' => $external_update,
			'server_change_range'   => array(
				'start'         => 0,
				'end'           => 0,
				'delete_length' => 0,
				'insert_length' => 0,
				'changed'       => false,
			),
			'client_change_range'   => isset( $external_update['change_range'] ) && is_array( $external_update['change_range'] ) ? $external_update['change_range'] : array(),
			'server_merge_strategy' => 'native_automerge_external_repair_v1',
		);
		$next_sync_meta = wp_de_rtc_apply_automerge_metadata_to_sync_meta( $base_sync_meta, $automerge_result, $current_hash );

			if ( is_wp_error( $next_sync_meta ) ) {
				return $next_sync_meta;
			}

			$next_sync_meta = wp_de_rtc_update_automerge_version_snapshots(
				$next_sync_meta,
				$base_version,
				$base_content,
				$next_version,
				$current_content
			);

			unset(
				$next_sync_meta['pending_automerge_update'],
			$next_sync_meta['pending_automerge_encoding'],
			$next_sync_meta['automerge_client_update'],
			$next_sync_meta['automerge_update_role'],
			$next_sync_meta['client_base_version']
		);

		$next_sync_meta['version']            = $next_version;
		$next_sync_meta['previous_version']   = $base_version;
		$next_sync_meta['last_sync_meta_recovery'] = array(
			'type'                        => 'external_repair',
			'mode'                        => $mode,
			'actor'                       => $recovery_actor,
			'previous_server_version'     => $base_version,
			'repaired_server_version'     => $next_version,
			'saved_stripped_content_hash' => $current_hash,
			'base_content_hash'           => wp_de_rtc_hash_content( $base_content ),
			'current_content_hash'        => $current_hash,
			'content_hash_algorithm'      => 'sha256',
		);

		if ( $base_revision_id ) {
			$next_sync_meta['last_sync_meta_recovery']['base_revision_id'] = $base_revision_id;
		}

		$next_sync_meta['last_server_update'] = array(
			'type'                        => 'external_repair',
			'actor_type'                  => 'system',
			'repair_actor'                => $recovery_actor,
			'session_label'               => $recovery_actor['display_name'],
			'external_repair_mode'        => $mode,
			'previous_server_version'     => $base_version,
			'saved_stripped_content_hash' => $current_hash,
			'merge_strategy'              => 'native_automerge_external_repair_v1',
			'base_content_hash'           => wp_de_rtc_hash_content( $base_content ),
			'current_content_hash'        => $current_hash,
			'content_hash_algorithm'      => 'sha256',
		);

		if ( $base_revision_id ) {
			$next_sync_meta['last_server_update']['base_revision_id'] = $base_revision_id;
		}

		return array(
			'content'                 => $current_content,
			'sync_meta'               => $next_sync_meta,
			'sync_meta_format'        => 'automerge',
			'sync_meta_position'      => $sync_meta_position,
			'raw_sync_meta'           => null,
			'repair_required'         => true,
			'external_repair_mode'    => $mode,
			'base_version'            => $base_version,
			'server_version'          => $next_version,
			'base_revision_id'        => $base_revision_id,
			'base_content_hash'       => wp_de_rtc_hash_content( $base_content ),
			'current_content_hash'    => $current_hash,
			'recovery_actor'          => $recovery_actor,
			'automerge_external_repair_result' => $automerge_result,
		);
	}

	/**
	 * Repairs a parsed current post snapshot when Automerge metadata and body diverge.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param WP_Post $post    Current post.
	 * @param array   $current Parsed current post content.
	 * @param array   $options Optional repair options.
	 * @return array|null|WP_Error Repaired parsed snapshot, null when no repair applies, or an error.
	 */
	function wp_de_rtc_get_repaired_automerge_current_post_snapshot( $post, $current, $options = array() ) {
		$post               = get_post( $post );
		$options            = is_array( $options ) ? $options : array();
		$allow_empty_import = ! empty( $options['allow_empty_import'] );

		if ( ! $post || ! is_array( $current ) || ! isset( $current['content'] ) || ! is_string( $current['content'] ) ) {
			return null;
		}

		$current_hash     = wp_de_rtc_hash_content( $current['content'] );
		$current_raw_hash = hash( 'sha256', $current['content'] );

		if ( wp_de_rtc_is_current_automerge_sync_meta( $current['sync_meta'], $current['sync_meta_format'] ) ) {
			$stored_hash = wp_de_rtc_get_automerge_sync_meta_content_hash( $current['sync_meta'] );

			if (
				null === $stored_hash ||
				hash_equals( $stored_hash, $current_hash ) ||
				hash_equals( $stored_hash, $current_raw_hash )
			) {
				return null;
			}

			$base_version = isset( $current['sync_meta']['version'] ) ? sanitize_text_field( (string) $current['sync_meta']['version'] ) : '';

			if ( '' === $base_version ) {
				return wp_de_rtc_get_reason_error(
					'de_rtc_sync_meta_unrecoverable',
					__( 'Distributed Editing could not repair Automerge metadata because the base version is missing.' ),
					array(
						'detail' => 'automerge_external_repair_missing_base_version',
					)
				);
			}

			$base_revision = wp_de_rtc_find_revision_with_sync_meta_version( $post, $base_version );

			if ( is_wp_error( $base_revision ) ) {
				return $base_revision;
			}

			if (
				empty( $base_revision['found'] ) ||
				! is_string( $base_revision['content'] ) ||
				(
					! hash_equals( $stored_hash, wp_de_rtc_hash_content( $base_revision['content'] ) ) &&
					! hash_equals( $stored_hash, hash( 'sha256', $base_revision['content'] ) )
				) ||
				! wp_de_rtc_is_current_automerge_sync_meta( $base_revision['sync_meta'], $base_revision['sync_meta_format'] )
			) {
				return wp_de_rtc_get_reason_error(
					'de_rtc_sync_meta_unrecoverable',
					__( 'Distributed Editing could not repair Automerge metadata because no trusted base body was found.' ),
					array(
						'detail'                       => 'automerge_external_repair_base_revision_not_found',
						'base_version'                 => $base_version,
						'expected_base_content_hash'    => $stored_hash,
						'current_stripped_content_hash' => $current_hash,
					)
				);
			}

			return wp_de_rtc_get_automerge_external_repair_update(
				$post,
				array(
					'base_content'       => $base_revision['content'],
					'base_sync_meta'     => $base_revision['sync_meta'],
					'base_version'       => $base_version,
					'current_content'    => $current['content'],
					'mode'               => 'body_hash_drift',
					'base_revision_id'   => isset( $base_revision['revision_id'] ) ? (int) $base_revision['revision_id'] : 0,
					'sync_meta_position' => is_string( $current['sync_meta_position'] ) ? $current['sync_meta_position'] : 'prefix-block',
				)
			);
		}

		if ( null !== $current['sync_meta'] ) {
			return null;
		}

		$revision_scan = wp_de_rtc_find_latest_revision_with_sync_meta( $post );

		if ( is_wp_error( $revision_scan ) ) {
			return $revision_scan;
		}

		if (
			! empty( $revision_scan['found'] ) &&
			wp_de_rtc_is_current_automerge_sync_meta( $revision_scan['sync_meta'], $revision_scan['sync_meta_format'] )
		) {
			$base_version = isset( $revision_scan['sync_meta']['version'] ) ? sanitize_text_field( (string) $revision_scan['sync_meta']['version'] ) : '0';

			return wp_de_rtc_get_automerge_external_repair_update(
				$post,
				array(
					'base_content'       => $revision_scan['content'],
					'base_sync_meta'     => $revision_scan['sync_meta'],
					'base_version'       => $base_version,
					'current_content'    => $current['content'],
					'mode'               => 'missing_sync_meta_revision',
					'base_revision_id'   => isset( $revision_scan['revision_id'] ) ? (int) $revision_scan['revision_id'] : 0,
					'sync_meta_position' => isset( $revision_scan['sync_meta_position'] ) && is_string( $revision_scan['sync_meta_position'] ) ? $revision_scan['sync_meta_position'] : 'prefix-block',
				)
			);
		}

		if ( ! $allow_empty_import || ! empty( $revision_scan['found'] ) ) {
			return null;
		}

		return wp_de_rtc_get_automerge_external_repair_update(
			$post,
			array(
				'base_content'       => '',
				'base_sync_meta'     => wp_de_rtc_get_empty_automerge_sync_meta_for_external_import( $post ),
				'base_version'       => '0',
				'current_content'    => $current['content'],
				'mode'               => 'empty_import',
				'base_revision_id'   => 0,
				'sync_meta_position' => 'prefix-block',
			)
		);
	}

/**
 * Decodes a native Automerge update stored inside post sync metadata.
 *
 * The normal Save path now carries DE-RTC evidence inside `post_content`
 * instead of in a side-channel REST payload. This helper accepts the current
 * metadata field shapes without trusting the submitted metadata as server
 * authority.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $encoded_update Base64 JSON update, decoded update array, or null.
 * @return array|null|WP_Error Native update, null when absent, or an error.
 */
function wp_de_rtc_decode_automerge_sync_meta_update( $encoded_update ) {
	if ( null === $encoded_update ) {
		return null;
	}

	if ( is_array( $encoded_update ) ) {
		return wp_de_rtc_normalize_automerge_client_update( $encoded_update );
	}

	if ( ! is_string( $encoded_update ) || '' === trim( $encoded_update ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the Automerge update because it is malformed.' ),
			array(
				'detail' => 'automerge_sync_meta_update_not_base64_json',
			)
		);
	}

	$json = base64_decode( trim( $encoded_update ), true );

	if ( false === $json ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the Automerge update because it is malformed.' ),
			array(
				'detail' => 'automerge_sync_meta_update_base64_decode_failed',
			)
		);
	}

	$update = json_decode( $json, true );

	if ( JSON_ERROR_NONE !== json_last_error() || ! is_array( $update ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing rejected the Automerge update because it is malformed.' ),
			array(
				'detail'          => 'automerge_sync_meta_update_json_decode_failed',
				'json_error_code' => json_last_error(),
			)
		);
	}

	return wp_de_rtc_normalize_automerge_client_update( $update );
}

/**
 * Extracts the client Automerge update from submitted post sync metadata.
 *
 * Server-owned historical `automerge_update` is intentionally ignored unless the
 * client labels it as a pending update. Replaying old server metadata as a
 * client edit was one of the ways ordinary Save drifted into confusing stale
 * and paused states.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array|null $sync_meta Submitted sync metadata.
 * @return array|null|WP_Error Native update, null when absent, or an error.
 */
function wp_de_rtc_get_pending_automerge_update_from_sync_meta( $sync_meta ) {
	if ( ! is_array( $sync_meta ) ) {
		return null;
	}

	if ( array_key_exists( 'pending_automerge_update', $sync_meta ) ) {
		return wp_de_rtc_decode_automerge_sync_meta_update( $sync_meta['pending_automerge_update'] );
	}

	if ( array_key_exists( 'automerge_client_update', $sync_meta ) ) {
		return wp_de_rtc_decode_automerge_sync_meta_update( $sync_meta['automerge_client_update'] );
	}

	if (
		isset( $sync_meta['automerge_update_role'] ) &&
		'client_update' === $sync_meta['automerge_update_role'] &&
		array_key_exists( 'automerge_update', $sync_meta )
	) {
		return wp_de_rtc_decode_automerge_sync_meta_update( $sync_meta['automerge_update'] );
	}

	return null;
}

/**
 * Prepares server-owned post content for a raw post_content Automerge save.
 *
 * The only Save contract this path needs from the client is the complete
 * submitted post content. When that content includes the sync-meta pseudo-block,
 * WordPress splits it off, applies the pending Automerge update if present, and then
 * writes a fresh server-owned pseudo-block above the merged body. Direct
 * `wp_update_post()` calls that submit only body content still get a derived
 * single-change update so older entry points do not strip the metadata.
 *
 * @since 7.1.0
 * @access private
 *
	 * @param WP_Post $post                 Current post.
	 * @param string  $incoming_post_content Submitted raw post content.
	 * @param string  $source               Save entry-point label.
	 * @param array   $args                 Optional behavior arguments.
	 * @return string|null|WP_Error Candidate post_content, null when DE-RTC should not handle it, or an error.
	 */
	function wp_de_rtc_prepare_automerge_raw_post_content_update( $post, $incoming_post_content, $source, $args = array() ) {
		if ( ! $post || ! wp_de_rtc_is_enabled_for_post( $post ) || ! is_string( $incoming_post_content ) ) {
			return null;
		}

		$args                                = is_array( $args ) ? $args : array();
		$explicit_base_version               = isset( $args['base_version'] ) ? sanitize_text_field( (string) $args['base_version'] ) : '';
		$normal_rest_base_version_update     = '' !== $explicit_base_version && ! empty( $args['normal_rest_base_version_update'] );
		$wp_update_post_base_version_update  = '' !== $explicit_base_version && ! empty( $args['wp_update_post_base_version_update'] );
		$explicit_base_version_update        = $normal_rest_base_version_update || $wp_update_post_base_version_update;
		$attributed_user_id                  = isset( $args['on_behalf_of'] ) ? absint( $args['on_behalf_of'] ) : get_current_user_id();
		$executor_user_id                    = isset( $args['executor_user_id'] ) ? absint( $args['executor_user_id'] ) : get_current_user_id();
		$attributed_user_can_unfiltered_html = $attributed_user_id ? user_can( $attributed_user_id, 'unfiltered_html' ) : current_user_can( 'unfiltered_html' );
		$authorship_context                  = array();
		$client_sync_meta_ignored_reason     = null;
		$client_sync_meta_adopted            = false;
		$automerge_update_source             = 'fabricated_from_submitted_content';

		$current = wp_de_rtc_parse_post_content_sync_meta( $post->post_content );

	if ( is_wp_error( $current ) ) {
		return $current;
	}

	$incoming = wp_de_rtc_parse_post_content_sync_meta( $incoming_post_content );

	if ( is_wp_error( $incoming ) ) {
		return $incoming;
	}

	$current_is_automerge = 'automerge' === $current['sync_meta_format'] && is_array( $current['sync_meta'] );
	$incoming_is_automerge = 'automerge' === $incoming['sync_meta_format'] && is_array( $incoming['sync_meta'] );

			if ( null !== $incoming['sync_meta'] && ! $incoming_is_automerge && ! $current_is_automerge ) {
				return null;
			}

			if ( null !== $incoming['sync_meta'] && ! $incoming_is_automerge ) {
				if ( $explicit_base_version_update && $current_is_automerge ) {
					$client_sync_meta_ignored_reason = 'incoming_sync_meta_format_not_automerge';
				} else {
				return wp_de_rtc_get_reason_error(
					'de_rtc_unknown_sync_meta_format',
					__( 'Distributed Editing rejected the save because the sync metadata format is not supported.' ),
					array(
					'format' => $incoming['sync_meta_format'],
					)
				);
				}
			}

			$current_external_repair = wp_de_rtc_get_repaired_automerge_current_post_snapshot(
				$post,
				$current,
				array(
					'allow_empty_import' => $current_is_automerge || $incoming_is_automerge || $explicit_base_version_update,
				)
			);

		if ( is_wp_error( $current_external_repair ) ) {
			return $current_external_repair;
		}

		if ( is_array( $current_external_repair ) ) {
			$current        = $current_external_repair;
			$current_is_automerge = true;
		}

			if ( ! $current_is_automerge && ! $incoming_is_automerge ) {
				if ( $explicit_base_version_update ) {
					return wp_de_rtc_get_reason_error(
						'de_rtc_sync_meta_unrecoverable',
						__( 'Distributed Editing could not merge the REST update because the current post has no Automerge sync metadata.' ),
						array(
							'detail'               => 'automerge_base_version_requires_current_sync_meta',
							'client_base_version'  => $explicit_base_version,
							'raw_content_included' => false,
							'saves_post'           => false,
							'mutates_post_content' => false,
							'creates_revision'     => false,
							'claims_saved'         => false,
						)
					);
				}

				return null;
			}

		$client_update = $incoming_is_automerge ? wp_de_rtc_get_pending_automerge_update_from_sync_meta( $incoming['sync_meta'] ) : null;

		if ( is_wp_error( $client_update ) ) {
			if ( $explicit_base_version_update ) {
				$client_sync_meta_ignored_reason = $client_update->get_error_code();
				$client_update                   = null;
			} else {
			return $client_update;
			}
		}

		$current_content     = $current['content'];
		$proposed_content    = $incoming['content'];
		$server_version      = $current_is_automerge && isset( $current['sync_meta']['version'] ) ? sanitize_text_field( (string) $current['sync_meta']['version'] ) : '0';
		$client_base_version = $incoming_is_automerge && isset( $incoming['sync_meta']['client_base_version'] ) ? sanitize_text_field( (string) $incoming['sync_meta']['client_base_version'] ) : '';

		if ( $explicit_base_version_update ) {
			if ( '' !== $client_base_version && $client_base_version !== $explicit_base_version ) {
				$client_sync_meta_ignored_reason = 'client_sync_meta_base_version_mismatch';
				$client_update                   = null;
			}

			if ( $incoming_is_automerge && isset( $incoming['sync_meta']['version'] ) ) {
				$incoming_sync_meta_version = sanitize_text_field( (string) $incoming['sync_meta']['version'] );

				if ( '' !== $incoming_sync_meta_version && $incoming_sync_meta_version !== $explicit_base_version ) {
					$client_sync_meta_ignored_reason = 'client_sync_meta_version_mismatch';
					$client_update                   = null;
				}
			}

			$client_base_version = $explicit_base_version;
		} elseif ( '' === $client_base_version && $incoming_is_automerge && isset( $incoming['sync_meta']['version'] ) ) {
			$client_base_version = sanitize_text_field( (string) $incoming['sync_meta']['version'] );
		}

	$base_content     = $current_content;
	$base_revision_id = 0;
	$effective_client_base_version = '' !== $client_base_version ? $client_base_version : $server_version;
	$automerge_result       = null;

		if ( '' !== $client_base_version && $client_base_version !== $server_version ) {
			if ( $explicit_base_version_update ) {
				$base_snapshot = wp_de_rtc_get_automerge_base_content_for_version( $post, $current, $client_base_version );

				if ( is_wp_error( $base_snapshot ) ) {
					return $base_snapshot;
				}

				$base_content                   = $base_snapshot['content'];
				$effective_client_base_version = $client_base_version;
			} else {
			$base_revision = wp_de_rtc_find_revision_with_sync_meta_version( $post, $client_base_version );

			if ( is_wp_error( $base_revision ) ) {
			return $base_revision;
		}

		if ( empty( $base_revision['found'] ) || ! is_string( $base_revision['content'] ) ) {
			if ( null !== $client_update ) {
				$current_base_result = wp_de_rtc_get_automerge_retry_save_result( $current_content, $current_content, $proposed_content, $client_update );

				if ( ! is_wp_error( $current_base_result ) ) {
					/*
					 * Some raw editor saves can only prove their base by
					 * materializing the pending Automerge update against the current
					 * server body. Accept that narrow case so a clean Save does
					 * not become a false stale-base rejection.
					 */
					$automerge_result                    = $current_base_result;
					$effective_client_base_version = $server_version;
				} else {
					$current_base_error_data   = $current_base_result->get_error_data( $current_base_result->get_error_code() );
					$current_base_error_detail = is_array( $current_base_error_data ) && isset( $current_base_error_data['detail'] ) ? (string) $current_base_error_data['detail'] : '';

					if ( 'de_rtc_sync_meta_tampered' !== $current_base_result->get_error_code() || 'automerge_client_update_materialization_mismatch' !== $current_base_error_detail ) {
						return $current_base_result;
					}
				}
			}

			if ( null === $automerge_result ) {
				return wp_de_rtc_get_server_merge_conflict_error(
					'automerge_raw_save_base_revision_not_found',
					array(
						'server_merge_strategy'         => 'native_automerge_php_v1',
						'source'                        => $source,
						'client_base_version'           => $client_base_version,
						'server_version'                => $server_version,
						'base_revision_found'           => false,
						'requires_server_state_refetch' => true,
					)
				);
			}
		} else {
			$base_content                  = $base_revision['content'];
				$base_revision_id             = isset( $base_revision['revision_id'] ) ? (int) $base_revision['revision_id'] : 0;
				$effective_client_base_version = $client_base_version;
			}
			}
		}

		if ( null === $automerge_result ) {
			$client_update_from_sync_meta = null !== $client_update;

			if ( null === $client_update ) {
				$client_update = wp_de_rtc_create_automerge_update_for_content_change( $base_content, $proposed_content, 'client' );
				$automerge_update_source = $explicit_base_version_update ? 'fabricated_from_base_version' : 'fabricated_from_submitted_content';
			} else {
				$automerge_update_source = 'client_sync_meta';
			}

			$automerge_result = wp_de_rtc_get_automerge_retry_save_result( $base_content, $current_content, $proposed_content, $client_update );

			if ( is_wp_error( $automerge_result ) ) {
				if ( ! $explicit_base_version_update || ! $client_update_from_sync_meta ) {
					return $automerge_result;
				}

				$client_sync_meta_ignored_reason = $automerge_result->get_error_code();
				$client_update                   = wp_de_rtc_create_automerge_update_for_content_change( $base_content, $proposed_content, 'client' );
				$automerge_update_source         = 'fabricated_from_base_version';
				$automerge_result                = wp_de_rtc_get_automerge_retry_save_result( $base_content, $current_content, $proposed_content, $client_update );

				if ( is_wp_error( $automerge_result ) ) {
					return $automerge_result;
				}
			} elseif ( $client_update_from_sync_meta ) {
				$client_sync_meta_adopted = true;
			}
		}

		if ( $explicit_base_version_update ) {
			$authorship_context = wp_de_rtc_get_retry_save_authorship_context( $post, '', $attributed_user_id );
			$automerge_result  = wp_de_rtc_apply_authorship_context_to_automerge_result( $automerge_result, $authorship_context );
		}

		$merged_content = $automerge_result['merged_content'];
		$save_hash      = wp_de_rtc_hash_content( $merged_content );

		if ( $explicit_base_version_update && ! $attributed_user_can_unfiltered_html ) {
			$normal_rest_kses_classification = wp_de_rtc_classify_kses_risky_block_review_items(
				$post,
				$merged_content,
				array(
					'base_post_content'        => $current_content,
					'client_base_version'      => $client_base_version,
					'server_version'           => $server_version,
					'user_can_unfiltered_html' => false,
					'author_id'                => $attributed_user_id,
				)
			);

			if ( is_wp_error( $normal_rest_kses_classification ) ) {
				return $normal_rest_kses_classification;
			}

			$normal_rest_review_items = isset( $normal_rest_kses_classification['review_items'] ) && is_array( $normal_rest_kses_classification['review_items'] )
				? array_values( $normal_rest_kses_classification['review_items'] )
				: array();

			if ( ! empty( $normal_rest_review_items ) ) {
				return wp_de_rtc_get_unfiltered_html_review_rejection_error(
					$post,
					array(
						'pending_change_count'               => count( $normal_rest_review_items ),
						'rest_route'                         => 'post_save_base_version_update',
						'proposed_post_content_hash'         => wp_de_rtc_hash_content( $proposed_content ),
						'candidate_post_content_hash'        => $save_hash,
						'proposed_post_content_kses_review'  => wp_de_rtc_get_kses_post_content_review_evidence( $proposed_content ),
						'candidate_post_content_kses_review' => wp_de_rtc_get_kses_post_content_review_evidence( $merged_content ),
						'review_items'                       => $normal_rest_review_items,
					)
				);
			}
		}

		$next_version   = wp_de_rtc_get_next_sync_meta_version( $server_version, $save_hash );
		$next_sync_meta = $current_is_automerge ? $current['sync_meta'] : array();
		$next_sync_meta = wp_de_rtc_apply_automerge_metadata_to_sync_meta( $next_sync_meta, $automerge_result, $save_hash );

	if ( is_wp_error( $next_sync_meta ) ) {
			return $next_sync_meta;
		}

		if ( $explicit_base_version_update ) {
			$next_sync_meta = wp_de_rtc_apply_automerge_authorship_to_sync_meta( $next_sync_meta, $merged_content, $automerge_result, $authorship_context );
		}

		$next_sync_meta = wp_de_rtc_update_automerge_version_snapshots(
			$next_sync_meta,
			$server_version,
			$current_content,
			$next_version,
			$merged_content
		);

		unset(
			$next_sync_meta['pending_automerge_update'],
		$next_sync_meta['pending_automerge_encoding'],
		$next_sync_meta['automerge_client_update'],
		$next_sync_meta['automerge_update_role'],
		$next_sync_meta['client_base_version']
	);

	$next_sync_meta['version']            = $next_version;
	$next_sync_meta['previous_version']   = $server_version;
		$next_sync_meta['last_server_update'] = array(
			'type'                       => $source,
			'user_id'                    => $attributed_user_id,
				'session_label'              => wp_de_rtc_get_history_author_display_name( $attributed_user_id ),
				'attribution_key'            => isset( $authorship_context['attributionKey'] ) ? $authorship_context['attributionKey'] : null,
				'client_base_version'        => $effective_client_base_version,
			'previous_server_version'    => $server_version,
			'saved_stripped_content_hash' => $save_hash,
				'merge_strategy'             => $automerge_result['merge_strategy'],
				'automerge_update_source'    => $automerge_update_source,
				'client_sync_meta_adopted'   => $client_sync_meta_adopted,
			);

			if ( $normal_rest_base_version_update ) {
				$next_sync_meta['last_server_update']['normal_rest_base_version_update'] = true;
			}

			if ( $wp_update_post_base_version_update ) {
				$next_sync_meta['last_server_update']['wp_update_post_base_version_update'] = true;
				$next_sync_meta['last_server_update']['on_behalf_of']                       = $attributed_user_id;
				$next_sync_meta['last_server_update']['executor_user_id']                   = $executor_user_id;
			}

			if ( null !== $client_sync_meta_ignored_reason ) {
				$next_sync_meta['last_server_update']['client_sync_meta_ignored_reason'] = sanitize_key( (string) $client_sync_meta_ignored_reason );
			}

		if ( is_array( $current_external_repair ) ) {
			$next_sync_meta['last_server_update']['external_repair'] = array(
				'mode'                 => $current_external_repair['external_repair_mode'],
				'base_version'         => $current_external_repair['base_version'],
				'repaired_version'     => $current_external_repair['server_version'],
				'base_revision_id'     => $current_external_repair['base_revision_id'],
				'base_content_hash'    => $current_external_repair['base_content_hash'],
				'current_content_hash' => $current_external_repair['current_content_hash'],
				'repair_actor'         => isset( $current_external_repair['recovery_actor'] ) ? $current_external_repair['recovery_actor'] : null,
				'content_hash_algorithm' => 'sha256',
			);
		}

		if ( $base_revision_id ) {
			$next_sync_meta['last_server_update']['base_revision_id'] = $base_revision_id;
		}

	return wp_de_rtc_add_sync_meta_to_post_content( $merged_content, 'automerge', $next_sync_meta, 'prefix-block' );
}

/**
 * Validates and prepares raw post_content Automerge saves before REST persistence.
 *
 * @since 7.1.0
 *
 * @param stdClass|WP_Error $prepared_post Prepared post object or an earlier error.
 * @param WP_REST_Request   $request       Request object.
 * @return stdClass|WP_Error Prepared post or a merge/apply error.
 */
	function wp_de_rtc_rest_pre_insert_automerge_raw_post_content_update( $prepared_post, $request ) {
		if ( is_wp_error( $prepared_post ) || ! is_object( $prepared_post ) || ! isset( $prepared_post->post_content ) ) {
			return $prepared_post;
		}

	$post_id = 0;

	if ( isset( $prepared_post->ID ) ) {
		$post_id = (int) $prepared_post->ID;
	}

	if ( ! $post_id && isset( $request['id'] ) ) {
		$post_id = (int) $request['id'];
	}

	$post = get_post( $post_id );

		if ( ! $post ) {
			return $prepared_post;
		}

		$base_version = $request->get_param( 'base_version' );
		$args         = array();

		if ( null !== $base_version ) {
			$base_version = sanitize_text_field( (string) $base_version );

			if ( '' === $base_version ) {
				return wp_de_rtc_get_reason_error(
					'de_rtc_malformed_sync_payload',
					__( 'Distributed Editing could not merge the REST update because base_version is empty.' ),
					array(
						'detail'               => 'normal_rest_base_version_empty',
						'post_id'              => (int) $post->ID,
						'raw_content_included' => false,
						'saves_post'           => false,
						'mutates_post_content' => false,
						'creates_revision'     => false,
						'claims_saved'         => false,
					)
				);
			}

			if ( ! wp_de_rtc_rest_normal_post_update_request_matches_post_type( $request, $post ) ) {
				return wp_de_rtc_get_reason_error(
					'rest_post_invalid_id',
					__( 'Invalid post ID.' ),
					array(
						'status'               => 404,
						'detail'               => 'normal_rest_base_version_route_post_type_mismatch',
						'post_id'              => (int) $post->ID,
						'raw_content_included' => false,
						'saves_post'           => false,
						'mutates_post_content' => false,
						'creates_revision'     => false,
						'claims_saved'         => false,
					)
				);
			}

			if ( ! $request->has_param( 'content' ) ) {
				return wp_de_rtc_get_reason_error(
					'de_rtc_malformed_sync_payload',
					__( 'Distributed Editing could not merge the REST update because post content is missing.' ),
					array(
						'detail'               => 'normal_rest_base_version_content_missing',
						'post_id'              => (int) $post->ID,
						'client_base_version'  => $base_version,
						'raw_content_included' => false,
						'saves_post'           => false,
						'mutates_post_content' => false,
						'creates_revision'     => false,
						'claims_saved'         => false,
					)
				);
			}

			$args = array(
				'base_version'                    => $base_version,
				'normal_rest_base_version_update' => true,
			);
		}

		$candidate = wp_de_rtc_prepare_automerge_raw_post_content_update( $post, $prepared_post->post_content, 'rest_post_update', $args );

		if ( is_wp_error( $candidate ) ) {
			return $candidate;
		}

	if ( null === $candidate ) {
		return $prepared_post;
	}

	global $wp_de_rtc_prepared_automerge_raw_save_content;

	if ( ! is_array( $wp_de_rtc_prepared_automerge_raw_save_content ) ) {
		$wp_de_rtc_prepared_automerge_raw_save_content = array();
	}

		$wp_de_rtc_prepared_automerge_raw_save_content[ (int) $post->ID ] = $candidate;
		$prepared_post->post_content                               = $candidate;

		if ( null !== $base_version && ! current_user_can( 'unfiltered_html' ) ) {
			global $wp_de_rtc_rest_automerge_raw_save_kses_allowance_active;

			if ( ! is_array( $wp_de_rtc_rest_automerge_raw_save_kses_allowance_active ) ) {
				$wp_de_rtc_rest_automerge_raw_save_kses_allowance_active = array();
			}

			$wp_de_rtc_rest_automerge_raw_save_kses_allowance_active[ (int) $post->ID ] = true;
			wp_de_rtc_enable_sync_meta_script_kses_allowance();
		}

		return $prepared_post;
	}

	/**
	 * Returns whether a normal REST post update route matches the post type.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param WP_REST_Request $request Request object.
	 * @param WP_Post         $post    Post object.
	 * @return bool Whether the route is the normal post/page update route.
	 */
	function wp_de_rtc_rest_normal_post_update_request_matches_post_type( $request, $post ) {
		$requested_rest_base = wp_de_rtc_get_rest_normal_post_update_request_rest_base( $request );
		$post_rest_base      = wp_de_rtc_get_post_type_rest_base( $post->post_type );
		$supported_bases     = wp_de_rtc_get_rest_recovery_post_type_rest_bases();

		return (
			'' !== $requested_rest_base &&
			'' !== $post_rest_base &&
			$requested_rest_base === $post_rest_base &&
			in_array( $post_rest_base, $supported_bases, true )
		);
	}

	/**
	 * Returns the post type REST base from a normal REST post update route.
	 *
	 * Autosaves deliberately do not match this helper. The `base_version`
	 * compatibility trigger only applies to normal post/page updates.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param WP_REST_Request $request Request object.
	 * @return string Requested post type REST base, or empty string.
	 */
	function wp_de_rtc_get_rest_normal_post_update_request_rest_base( $request ) {
		$route = $request->get_route();

		if ( ! is_string( $route ) ) {
			return '';
		}

		if ( ! preg_match( '#^/wp/v2/([^/]+)/\d+$#', $route, $matches ) ) {
			return '';
		}

		return sanitize_key( $matches[1] );
	}

	/**
	 * Cleans up temporary KSES allowance for normal REST base-version saves.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param WP_REST_Response|WP_HTTP_Response|WP_Error|mixed $response Result to send to the client.
	 * @param array                                            $handler  Matched route handler.
	 * @param WP_REST_Request                                  $request  Request object.
	 * @return mixed Unchanged response.
	 */
	function wp_de_rtc_rest_cleanup_automerge_raw_post_content_update( $response, $handler, $request ) {
		global $wp_de_rtc_rest_automerge_raw_save_kses_allowance_active;

		if ( is_array( $wp_de_rtc_rest_automerge_raw_save_kses_allowance_active ) && ! empty( $wp_de_rtc_rest_automerge_raw_save_kses_allowance_active ) ) {
			$wp_de_rtc_rest_automerge_raw_save_kses_allowance_active = array();
			wp_de_rtc_disable_sync_meta_script_kses_allowance();
		}

		return $response;
	}

	/**
	 * Prepares an explicit `base_version` update submitted through wp_update_post().
	 *
	 * `base_version` is intentionally the only trigger. When it is present,
	 * WordPress treats the submitted post_content as a DE-aware merge request
	 * rather than as a raw replacement, and attributes the semantic edit to
	 * `on_behalf_of` when supplied.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param array $postarr       Slashed caller-supplied post array.
	 * @param array $existing_post Slashed existing post row.
	 * @return array|null|WP_Error Updated post array, null when not a DE update, or an error.
	 */
	function wp_de_rtc_preflight_wp_update_post_base_version( $postarr, $existing_post ) {
		if ( ! is_array( $postarr ) || ! array_key_exists( 'base_version', $postarr ) ) {
			return null;
		}

		$post_id = isset( $postarr['ID'] ) ? absint( $postarr['ID'] ) : 0;
		$post    = get_post( $post_id );

		if ( ! $post ) {
			return null;
		}

		$base_version = sanitize_text_field( (string) wp_unslash( $postarr['base_version'] ) );

		if ( '' === $base_version ) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_malformed_sync_payload',
				__( 'Distributed Editing could not merge the wp_update_post() update because base_version is empty.' ),
				array(
					'detail'               => 'wp_update_post_base_version_empty',
					'post_id'              => (int) $post->ID,
					'raw_content_included' => false,
					'saves_post'           => false,
					'mutates_post_content' => false,
					'creates_revision'     => false,
					'claims_saved'         => false,
				)
			);
		}

		if ( 'attachment' === $post->post_type ) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_malformed_sync_payload',
				__( 'Distributed Editing cannot merge attachment updates through wp_update_post().' ),
				array(
					'detail'               => 'wp_update_post_base_version_attachment_not_supported',
					'post_id'              => (int) $post->ID,
					'raw_content_included' => false,
					'saves_post'           => false,
					'mutates_post_content' => false,
					'creates_revision'     => false,
					'claims_saved'         => false,
				)
			);
		}

		if ( ! wp_de_rtc_is_enabled_for_post( $post ) ) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_feature_disabled',
				__( 'Distributed Editing is not enabled for this post.' ),
				array(
					'detail'               => 'wp_update_post_base_version_feature_disabled',
					'post_id'              => (int) $post->ID,
					'raw_content_included' => false,
					'saves_post'           => false,
					'mutates_post_content' => false,
					'creates_revision'     => false,
					'claims_saved'         => false,
				)
			);
		}

		$actor_user_id = isset( $postarr['on_behalf_of'] ) ? absint( wp_unslash( $postarr['on_behalf_of'] ) ) : get_current_user_id();

		if ( ! $actor_user_id || ! get_userdata( $actor_user_id ) ) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_malformed_sync_payload',
				__( 'Distributed Editing could not merge the wp_update_post() update because on_behalf_of does not identify a user.' ),
				array(
					'detail'               => 'wp_update_post_base_version_missing_actor',
					'post_id'              => (int) $post->ID,
					'raw_content_included' => false,
					'saves_post'           => false,
					'mutates_post_content' => false,
					'creates_revision'     => false,
					'claims_saved'         => false,
				)
			);
		}

		if ( ! user_can( $actor_user_id, 'edit_post', (int) $post->ID ) ) {
			return wp_de_rtc_get_reason_error(
				'rest_cannot_edit',
				__( 'Sorry, you are not allowed to edit this post.' ),
				array(
					'status'               => rest_authorization_required_code(),
					'detail'               => 'wp_update_post_base_version_actor_cannot_edit_post',
					'post_id'              => (int) $post->ID,
					'raw_content_included' => false,
					'saves_post'           => false,
					'mutates_post_content' => false,
					'creates_revision'     => false,
					'claims_saved'         => false,
				)
			);
		}

		$incoming_post_content = array_key_exists( 'post_content', $postarr )
			? wp_unslash( $postarr['post_content'] )
			: ( isset( $existing_post['post_content'] ) ? wp_unslash( $existing_post['post_content'] ) : $post->post_content );

		$candidate = wp_de_rtc_prepare_automerge_raw_post_content_update(
			$post,
			$incoming_post_content,
			'wp_update_post',
			array(
				'base_version'                       => $base_version,
				'wp_update_post_base_version_update' => true,
				'on_behalf_of'                       => $actor_user_id,
				'executor_user_id'                   => get_current_user_id(),
			)
		);

		if ( is_wp_error( $candidate ) ) {
			return $candidate;
		}

		if ( null === $candidate ) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_sync_meta_unrecoverable',
				__( 'Distributed Editing could not merge the wp_update_post() update because sync metadata is unavailable.' ),
				array(
					'detail'               => 'wp_update_post_base_version_prepare_returned_null',
					'post_id'              => (int) $post->ID,
					'client_base_version'  => $base_version,
					'raw_content_included' => false,
					'saves_post'           => false,
					'mutates_post_content' => false,
					'creates_revision'     => false,
					'claims_saved'         => false,
				)
			);
		}

		global $wp_de_rtc_prepared_automerge_raw_save_content;

		if ( ! is_array( $wp_de_rtc_prepared_automerge_raw_save_content ) ) {
			$wp_de_rtc_prepared_automerge_raw_save_content = array();
		}

		$wp_de_rtc_prepared_automerge_raw_save_content[ (int) $post->ID ] = $candidate;
		$postarr['post_content'] = wp_slash( $candidate );

		wp_de_rtc_activate_wp_update_post_on_behalf_capability_context( $actor_user_id );

		if ( ! user_can( $actor_user_id, 'unfiltered_html' ) ) {
			global $wp_de_rtc_wp_update_post_automerge_raw_save_kses_allowance_active;

			if ( ! is_array( $wp_de_rtc_wp_update_post_automerge_raw_save_kses_allowance_active ) ) {
				$wp_de_rtc_wp_update_post_automerge_raw_save_kses_allowance_active = array();
			}

			$wp_de_rtc_wp_update_post_automerge_raw_save_kses_allowance_active[ (int) $post->ID ] = true;
			wp_de_rtc_enable_sync_meta_script_kses_allowance();
		}

		return $postarr;
	}

	/**
	 * Clears temporary wp_update_post() DE merge state.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param array $postarr Slashed post array.
	 */
	function wp_de_rtc_cleanup_wp_update_post_base_version_preflight( $postarr = array() ) {
		if ( ! is_array( $postarr ) || ! array_key_exists( 'base_version', $postarr ) ) {
			return;
		}

		global $wp_de_rtc_prepared_automerge_raw_save_content;

		$post_id = isset( $postarr['ID'] ) ? absint( $postarr['ID'] ) : 0;

		if ( $post_id && is_array( $wp_de_rtc_prepared_automerge_raw_save_content ) ) {
			unset( $wp_de_rtc_prepared_automerge_raw_save_content[ $post_id ] );
		}

		global $wp_de_rtc_wp_update_post_automerge_raw_save_kses_allowance_active;

		if ( is_array( $wp_de_rtc_wp_update_post_automerge_raw_save_kses_allowance_active ) && ! empty( $wp_de_rtc_wp_update_post_automerge_raw_save_kses_allowance_active ) ) {
			$wp_de_rtc_wp_update_post_automerge_raw_save_kses_allowance_active = array();
			wp_de_rtc_disable_sync_meta_script_kses_allowance();
		}

		wp_de_rtc_deactivate_wp_update_post_on_behalf_capability_context();
	}

	/**
	 * Temporarily lets KSES capability checks use the `on_behalf_of` user.
	 *
	 * The PHP API is a trusted server-side entry point; attribution and
	 * capability checks must follow the semantic editing user without forcing
	 * plugins or cron jobs to mutate the global current user.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param int $user_id User ID to use as the capability source.
	 */
	function wp_de_rtc_activate_wp_update_post_on_behalf_capability_context( $user_id ) {
		global $wp_de_rtc_wp_update_post_on_behalf_capability_user_id;

		$wp_de_rtc_wp_update_post_on_behalf_capability_user_id = absint( $user_id );
		add_filter( 'user_has_cap', 'wp_de_rtc_filter_wp_update_post_on_behalf_user_has_cap', 10, 4 );
	}

	/**
	 * Clears the temporary `on_behalf_of` capability context.
	 *
	 * @since 7.1.0
	 * @access private
	 */
	function wp_de_rtc_deactivate_wp_update_post_on_behalf_capability_context() {
		global $wp_de_rtc_wp_update_post_on_behalf_capability_user_id;

		$wp_de_rtc_wp_update_post_on_behalf_capability_user_id = 0;
		remove_filter( 'user_has_cap', 'wp_de_rtc_filter_wp_update_post_on_behalf_user_has_cap', 10 );
	}

	/**
	 * Mirrors primitive capabilities from the trusted `on_behalf_of` user.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param bool[]  $allcaps All capabilities for the current user.
	 * @param string[] $caps    Required primitive capabilities.
	 * @param array   $args     Capability check arguments.
	 * @param WP_User $user     Current user object.
	 * @return bool[] Filtered capabilities.
	 */
	function wp_de_rtc_filter_wp_update_post_on_behalf_user_has_cap( $allcaps, $caps, $args, $user ) {
		global $wp_de_rtc_wp_update_post_on_behalf_capability_user_id;

		$actor_user_id = isset( $wp_de_rtc_wp_update_post_on_behalf_capability_user_id ) ? absint( $wp_de_rtc_wp_update_post_on_behalf_capability_user_id ) : 0;

		if ( ! $actor_user_id || ! is_array( $allcaps ) ) {
			return $allcaps;
		}

		$actor = get_userdata( $actor_user_id );

		if ( ! $actor || ! is_array( $actor->allcaps ) ) {
			return $allcaps;
		}

		foreach ( $actor->allcaps as $capability => $granted ) {
			if ( ! is_string( $capability ) || '' === $capability ) {
				continue;
			}

			$allcaps[ $capability ] = (bool) $granted;
		}

		return $allcaps;
	}

/**
 * Preserves server-owned Automerge sync metadata for normal post update entry points.
 *
 * @since 7.1.0
 *
 * @param array $data                Slashed post data.
 * @param array $postarr             Sanitized post array.
 * @param array $unsanitized_postarr Unsanitized post array.
 * @param bool  $update              Whether this is an update.
 * @return array Filtered post data.
 */
function wp_de_rtc_preserve_automerge_sync_meta_on_post_update( $data, $postarr, $unsanitized_postarr, $update ) {
	if ( ! $update || empty( $postarr['ID'] ) || ! isset( $data['post_content'] ) ) {
		return $data;
	}

	global $wp_de_rtc_prepared_automerge_raw_save_content;
	global $wp_de_rtc_retry_save_candidate_post_content;

	if (
		is_array( $wp_de_rtc_retry_save_candidate_post_content ) &&
		array_key_exists( (int) $postarr['ID'], $wp_de_rtc_retry_save_candidate_post_content )
	) {
		$data['post_content'] = wp_slash( $wp_de_rtc_retry_save_candidate_post_content[ (int) $postarr['ID'] ] );

		return $data;
	}

	if ( is_array( $wp_de_rtc_prepared_automerge_raw_save_content ) && array_key_exists( (int) $postarr['ID'], $wp_de_rtc_prepared_automerge_raw_save_content ) ) {
		$data['post_content'] = wp_slash( $wp_de_rtc_prepared_automerge_raw_save_content[ (int) $postarr['ID'] ] );
		unset( $wp_de_rtc_prepared_automerge_raw_save_content[ (int) $postarr['ID'] ] );

		return $data;
	}

	$post = get_post( (int) $postarr['ID'] );

	if ( ! $post || ! wp_de_rtc_is_enabled_for_post( $post ) ) {
		return $data;
	}

	$candidate = wp_de_rtc_prepare_automerge_raw_post_content_update( $post, wp_unslash( $data['post_content'] ), 'wp_update_post' );

	if ( is_wp_error( $candidate ) ) {
		$data['post_content'] = wp_slash( $post->post_content );

		return $data;
	}

	if ( null === $candidate ) {
		return $data;
	}

	$data['post_content'] = wp_slash( $candidate );

	return $data;
}

/**
 * Formats Distributed Editing sync metadata as a SCRIPT element.
 *
 * The JSON is encoded so that user-controlled values cannot produce a literal
 * `</script` sequence inside the script contents.
 *
 * @since 7.1.0
 *
 * @param string $format    Sync-meta format label.
 * @param mixed  $sync_meta Sync metadata to JSON-encode.
 * @return string|WP_Error SCRIPT element on success, otherwise a WP_Error.
 */
function wp_de_rtc_format_sync_meta( $format, $sync_meta ) {
	$format = wp_de_rtc_normalize_sync_meta_format( $format );

	if ( ! in_array( $format, wp_de_rtc_get_supported_sync_meta_formats(), true ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_unknown_sync_meta_format',
			__( 'The Distributed Editing sync metadata format is not supported.' ),
			array(
				'format' => $format,
			)
		);
	}

	$json = wp_json_encode(
		$sync_meta,
		JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_UNESCAPED_SLASHES
	);

	if ( false === $json || false !== stripos( $json, '</script' ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'The Distributed Editing sync metadata could not be encoded.' ),
			array(
				'detail' => 'json_encode_failed',
			)
		);
	}

	$script = wp_get_inline_script_tag(
		$json,
		array(
			'type'                  => 'application/json',
			'data-wp-sync-meta'     => 'distributed-editing',
			'data-sync-meta-format' => $format,
		)
	);

	if ( '' === $script ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'The Distributed Editing sync metadata could not be embedded.' ),
			array(
				'detail' => 'script_embedding_failed',
			)
		);
	}

	return $script;
}

/**
 * Adds Distributed Editing sync metadata to post content.
 *
 * @since 7.1.0
 *
 * @param string $content   Post content.
 * @param string $format    Sync-meta format label.
 * @param mixed  $sync_meta Sync metadata to JSON-encode.
 * @param string $position  Optional. Sync-meta position: 'trailer', 'prefix', or 'prefix-block'. Default 'trailer'.
 * @return string|WP_Error Post content with sync metadata on success, otherwise a WP_Error.
 */
	function wp_de_rtc_add_sync_meta_to_post_content( $content, $format, $sync_meta, $position = 'trailer' ) {
		$content = wp_de_rtc_canonicalize_post_content_core_block_names( $content );
		$script = wp_de_rtc_format_sync_meta( $format, $sync_meta );

	if ( is_wp_error( $script ) ) {
		return $script;
	}

	if ( 'prefix' === $position ) {
		return $script . $content;
	}

	if ( 'prefix-block' === $position ) {
			return '<!-- wp:sync-meta {"format":"' . esc_attr( $format ) . "\"} -->\n" . $script . "\n<!-- /wp:sync-meta -->" . $content;
		}

	if ( 'trailer' === $position ) {
		return $content . $script;
	}

	return wp_de_rtc_get_reason_error(
		'de_rtc_malformed_sync_payload',
		__( 'The Distributed Editing sync metadata position is not supported.' ),
		array(
			'detail'   => 'unknown_sync_meta_position',
			'position' => $position,
		)
	);
}

/**
 * Parses Distributed Editing sync metadata from the edge of post content.
 *
 * This recognizes sync metadata only at a content edge. Gutenberg may wrap an
 * otherwise inert SCRIPT element in paragraph/freeform markup after an editor
 * round-trip, so the parser accepts those wrappers without treating them as
 * human-authored post content.
 *
 * @since 7.1.0
 *
 * @param string $content Post content.
 * @param array  $args {
 *     Optional parser controls.
 *
 *     @type bool $allow_script_stripped_sync_meta Whether revision scans may accept a sync-meta pseudo-block whose
 *                                                SCRIPT wrapper was stripped by KSES. Default false.
 * }
 * @return array|WP_Error Parsed content data on success, otherwise a WP_Error.
 */
function wp_de_rtc_parse_post_content_sync_meta( $content, $args = array() ) {
	$allow_script_stripped_sync_meta = is_array( $args ) && ! empty( $args['allow_script_stripped_sync_meta'] );
	$sync_meta_script_count = wp_de_rtc_count_post_content_sync_meta_scripts( $content );

	if ( $sync_meta_script_count > 1 ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing sync metadata must appear once.' ),
			array(
				'detail'                 => 'duplicate_sync_meta',
				'sync_meta_script_count' => $sync_meta_script_count,
			)
		);
	}

	$prefix = wp_de_rtc_match_edge_sync_meta_script( $content, 'prefix' );

	if ( false !== $prefix ) {
		$parsed = wp_de_rtc_parse_sync_meta_script( $prefix['script'], $prefix['json'] );

		if ( is_wp_error( $parsed ) ) {
			return $parsed;
		}

		if ( false !== $parsed ) {
			return array(
					'content'            => wp_de_rtc_canonicalize_post_content_core_block_names( substr( $content, strlen( $prefix['match'] ) ) ),
					'sync_meta'          => $parsed['sync_meta'],
					'sync_meta_format'   => $parsed['sync_meta_format'],
					'sync_meta_position' => isset( $prefix['position'] ) ? $prefix['position'] : 'prefix',
				'raw_sync_meta'      => $prefix['script'],
			);
		}
	}

	$trailer = wp_de_rtc_match_edge_sync_meta_script( $content, 'trailer' );

	if ( false !== $trailer ) {
		$parsed = wp_de_rtc_parse_sync_meta_script( $trailer['script'], $trailer['json'] );

		if ( is_wp_error( $parsed ) ) {
			return $parsed;
		}

		if ( false !== $parsed ) {
			return array(
					'content'            => wp_de_rtc_canonicalize_post_content_core_block_names( substr( $content, 0, strlen( $content ) - strlen( $trailer['match'] ) ) ),
					'sync_meta'          => $parsed['sync_meta'],
					'sync_meta_format'   => $parsed['sync_meta_format'],
					'sync_meta_position' => 'trailer',
				'raw_sync_meta'      => $trailer['script'],
			);
		}
	}

	if ( $allow_script_stripped_sync_meta ) {
		$prefix_block = wp_de_rtc_match_edge_script_stripped_sync_meta_block( $content, 'prefix' );

		if ( false !== $prefix_block ) {
			$parsed = wp_de_rtc_parse_script_stripped_sync_meta_block( $prefix_block );

			if ( is_wp_error( $parsed ) ) {
				return $parsed;
			}

			return array(
					'content'            => wp_de_rtc_canonicalize_post_content_core_block_names( substr( $content, strlen( $prefix_block['match'] ) ) ),
					'sync_meta'          => $parsed['sync_meta'],
					'sync_meta_format'   => $parsed['sync_meta_format'],
					'sync_meta_position' => 'prefix-block',
				'raw_sync_meta'      => $prefix_block['match'],
			);
		}

		$trailer_block = wp_de_rtc_match_edge_script_stripped_sync_meta_block( $content, 'trailer' );

		if ( false !== $trailer_block ) {
			$parsed = wp_de_rtc_parse_script_stripped_sync_meta_block( $trailer_block );

			if ( is_wp_error( $parsed ) ) {
				return $parsed;
			}

			return array(
					'content'            => wp_de_rtc_canonicalize_post_content_core_block_names( substr( $content, 0, strlen( $content ) - strlen( $trailer_block['match'] ) ) ),
					'sync_meta'          => $parsed['sync_meta'],
					'sync_meta_format'   => $parsed['sync_meta_format'],
					'sync_meta_position' => 'prefix-block',
				'raw_sync_meta'      => $trailer_block['match'],
			);
		}
	}

	if ( $sync_meta_script_count > 0 ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'Distributed Editing sync metadata must appear at a supported content edge.' ),
			array(
				'detail'                 => 'sync_meta_not_at_content_edge',
				'sync_meta_script_count' => $sync_meta_script_count,
			)
		);
	}

	return array(
			'content'            => wp_de_rtc_canonicalize_post_content_core_block_names( $content ),
			'sync_meta'          => null,
			'sync_meta_format'   => null,
		'sync_meta_position' => null,
		'raw_sync_meta'      => null,
	);
}

/**
 * Finds the most recent revision containing parseable Distributed Editing sync metadata.
 *
 * This helper only scans confirmed revision content. It skips autosave
 * revisions and does not restore revisions, update the parent post, repair
 * missing metadata, or create new revisions.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post Post ID or object.
 * @return array|WP_Error {
 *     Revision scan result on success, or a WP_Error when the post is invalid.
 *
 *     @type bool        $found                    Whether parseable sync metadata was found.
 *     @type int         $post_id                  Parent post ID.
 *     @type int         $revision_id              Revision ID containing sync metadata, or 0 when none was found.
 *     @type string|null $revision_date_gmt        Revision GMT date, or null when none was found.
 *     @type array|null  $sync_meta                Parsed sync metadata, or null when none was found.
 *     @type string|null $sync_meta_format         Sync metadata format, or null when none was found.
 *     @type string|null $sync_meta_position       Sync metadata position, or null when none was found.
 *     @type string|null $raw_sync_meta            Raw sync metadata SCRIPT element, or null when none was found.
 *     @type string|null $content                  Revision content without sync metadata, or null when none was found.
 *     @type int         $scanned_revisions        Number of revisions inspected.
 *     @type int[]       $malformed_revision_ids   Revision IDs skipped because sync metadata could not be parsed.
 * }
 */
function wp_de_rtc_find_latest_revision_with_sync_meta( $post ) {
	$post = get_post( $post );

	if ( ! $post || empty( $post->ID ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_unrecoverable',
			__( 'Distributed Editing could not scan revisions because the post does not exist.' ),
			array(
				'detail' => 'invalid_post',
			)
		);
	}

	$revisions = wp_get_post_revisions(
		$post,
		array(
			'check_enabled' => false,
			'numberposts'   => -1,
			'order'         => 'DESC',
			'orderby'       => 'date ID',
		)
	);

	$scanned_revisions      = 0;
	$malformed_revision_ids = array();

	foreach ( $revisions as $revision ) {
		++$scanned_revisions;

		if ( wp_is_post_autosave( $revision ) ) {
			continue;
		}

		$parsed = wp_de_rtc_parse_post_content_sync_meta(
			$revision->post_content,
			array(
				'allow_script_stripped_sync_meta' => true,
			)
		);

		if ( is_wp_error( $parsed ) ) {
			$malformed_revision_ids[] = (int) $revision->ID;
			continue;
		}

		if ( null === $parsed['sync_meta'] ) {
			continue;
		}

		return array(
			'found'                  => true,
			'post_id'                => (int) $post->ID,
			'revision_id'            => (int) $revision->ID,
			'revision_date_gmt'      => $revision->post_date_gmt,
			'sync_meta'              => $parsed['sync_meta'],
			'sync_meta_format'       => $parsed['sync_meta_format'],
			'sync_meta_position'     => $parsed['sync_meta_position'],
			'raw_sync_meta'          => $parsed['raw_sync_meta'],
			'content'                => $parsed['content'],
			'scanned_revisions'      => $scanned_revisions,
			'malformed_revision_ids' => $malformed_revision_ids,
		);
	}

	return array(
		'found'                  => false,
		'post_id'                => (int) $post->ID,
		'revision_id'            => 0,
		'revision_date_gmt'      => null,
		'sync_meta'              => null,
		'sync_meta_format'       => null,
		'sync_meta_position'     => null,
		'raw_sync_meta'          => null,
		'content'                => null,
		'scanned_revisions'      => $scanned_revisions,
		'malformed_revision_ids' => $malformed_revision_ids,
	);
}

/**
 * Finds the newest non-autosave revision containing a specific sync-meta version.
 *
 * This read-only helper lets retry-save reconstruct the server state that was
 * accepted by an earlier proof when the current post has advanced again. It
 * does not restore revisions, update posts, create revisions, or change locks.
 *
 * @since 7.1.0
 * @access private
 *
 * @param int|WP_Post $post    Post ID or object.
 * @param mixed       $version Sync-meta version to find.
 * @return array|WP_Error Revision scan result.
 */
function wp_de_rtc_find_revision_with_sync_meta_version( $post, $version ) {
	$post    = get_post( $post );
	$version = sanitize_text_field( (string) $version );

	if ( ! $post || empty( $post->ID ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_unrecoverable',
			__( 'Distributed Editing could not scan revisions because the post does not exist.' ),
			array(
				'detail' => 'invalid_post',
			)
		);
	}

	$revisions = wp_get_post_revisions(
		$post,
		array(
			'check_enabled' => false,
			'numberposts'   => -1,
			'order'         => 'DESC',
			'orderby'       => 'date ID',
		)
	);

	$scanned_revisions      = 0;
	$malformed_revision_ids = array();

	foreach ( $revisions as $revision ) {
		++$scanned_revisions;

		if ( wp_is_post_autosave( $revision ) ) {
			continue;
		}

		$parsed = wp_de_rtc_parse_post_content_sync_meta(
			$revision->post_content,
			array(
				'allow_script_stripped_sync_meta' => true,
			)
		);

		if ( is_wp_error( $parsed ) ) {
			$malformed_revision_ids[] = (int) $revision->ID;
			continue;
		}

		if (
			null === $parsed['sync_meta'] ||
			! is_array( $parsed['sync_meta'] ) ||
			! array_key_exists( 'version', $parsed['sync_meta'] ) ||
			$version !== sanitize_text_field( (string) $parsed['sync_meta']['version'] )
		) {
			continue;
		}

		return array(
			'found'                  => true,
			'post_id'                => (int) $post->ID,
			'revision_id'            => (int) $revision->ID,
			'revision_date_gmt'      => $revision->post_date_gmt,
			'sync_meta'              => $parsed['sync_meta'],
			'sync_meta_format'       => $parsed['sync_meta_format'],
			'sync_meta_position'     => $parsed['sync_meta_position'],
			'raw_sync_meta'          => $parsed['raw_sync_meta'],
			'content'                => $parsed['content'],
			'scanned_revisions'      => $scanned_revisions,
			'malformed_revision_ids' => $malformed_revision_ids,
		);
	}

	return array(
		'found'                  => false,
		'post_id'                => (int) $post->ID,
		'revision_id'            => 0,
		'revision_date_gmt'      => null,
		'sync_meta'              => null,
		'sync_meta_format'       => null,
		'sync_meta_position'     => null,
		'raw_sync_meta'          => null,
		'content'                => null,
		'scanned_revisions'      => $scanned_revisions,
		'malformed_revision_ids' => $malformed_revision_ids,
	);
}

/**
 * Gets the Distributed Editing sync-meta recovery decision for a post.
 *
 * This helper is intentionally inert and read-only. It parses the current post
 * content and, only when sync metadata is missing, consumes the latest-revision
 * scan helper output. It does not restore revisions, update posts, repair
 * content, create revisions, change locks, register REST behavior, or save.
 *
 * @since 7.1.0
 *
 * @param int|WP_Post $post Post ID or object.
 * @return array|WP_Error {
 *     Recovery decision on success, or a WP_Error when current sync metadata is malformed.
 *
 *     @type string      $decision                   Decision label.
 *     @type int         $post_id                    Post ID.
 *     @type bool        $recovery_required          Whether recovery is required.
 *     @type bool        $restorable                 Whether automatic restoration data is available.
 *     @type bool        $manual_resolution_required Whether manual resolution is required.
 *     @type array|null  $reason                     Canonical reason data, or null when no recovery is required.
 *     @type string      $current_content            Current post content without sync metadata.
 *     @type string      $current_content_hash       SHA-256 hash of current content without sync metadata.
 *     @type string      $content_hash_algorithm     Content hash algorithm.
 *     @type array|null  $current_sync_meta          Parsed current sync metadata, or null when missing.
 *     @type string|null $current_sync_meta_format   Current sync metadata format, or null when missing.
 *     @type string|null $current_sync_meta_position Current sync metadata position, or null when missing.
 *     @type string|null $current_raw_sync_meta      Current raw sync metadata SCRIPT, or null when missing.
 *     @type array|null  $base_revision              Restorable revision data, or null when unavailable.
 *     @type string|null $base_revision_content_hash SHA-256 hash of base revision content, or null when unavailable.
 *     @type array|null  $revision_scan              Revision scan result, or null when no scan was needed.
 *     @type array|null  $external_change            Data for a later mutation helper to reconstruct the external change.
 * }
 */
function wp_de_rtc_get_post_sync_meta_recovery_decision( $post ) {
	$post = get_post( $post );

	if ( ! $post || empty( $post->ID ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_unrecoverable',
			__( 'Distributed Editing could not decide sync metadata recovery because the post does not exist.' ),
			array(
				'detail' => 'invalid_post',
			)
		);
	}

	$current = wp_de_rtc_parse_post_content_sync_meta( $post->post_content );

	if ( is_wp_error( $current ) ) {
		return $current;
	}

		$current_content_hash = wp_de_rtc_hash_content( $current['content'] );

		if ( null !== $current['sync_meta'] ) {
			if ( wp_de_rtc_is_current_automerge_sync_meta( $current['sync_meta'], $current['sync_meta_format'] ) ) {
				$stored_content_hash = wp_de_rtc_get_automerge_sync_meta_content_hash( $current['sync_meta'] );

				if ( null !== $stored_content_hash && ! hash_equals( $stored_content_hash, $current_content_hash ) ) {
					$base_version  = isset( $current['sync_meta']['version'] ) ? sanitize_text_field( (string) $current['sync_meta']['version'] ) : '';
					$base_revision = '' !== $base_version ? wp_de_rtc_find_revision_with_sync_meta_version( $post, $base_version ) : null;

					if (
						is_array( $base_revision ) &&
						! empty( $base_revision['found'] ) &&
						is_string( $base_revision['content'] ) &&
						hash_equals( $stored_content_hash, wp_de_rtc_hash_content( $base_revision['content'] ) ) &&
						wp_de_rtc_is_current_automerge_sync_meta( $base_revision['sync_meta'], $base_revision['sync_meta_format'] )
					) {
						$base_revision_content_hash = wp_de_rtc_hash_content( $base_revision['content'] );

						return array(
							'decision'                   => 'recovery_required_restorable',
							'post_id'                    => (int) $post->ID,
							'recovery_required'          => true,
							'restorable'                 => true,
							'manual_resolution_required' => false,
							'reason'                     => wp_de_rtc_get_reason_data(
								'de_rtc_sync_meta_repaired_from_body',
								array(
									'detail'               => 'automerge_body_hash_drift',
									'recovery_reason_code' => 'de_rtc_sync_meta_repaired_from_body',
								)
							),
							'current_content'            => $current['content'],
							'current_content_hash'       => $current_content_hash,
							'content_hash_algorithm'     => 'sha256',
							'current_sync_meta'          => $current['sync_meta'],
							'current_sync_meta_format'   => $current['sync_meta_format'],
							'current_sync_meta_position' => $current['sync_meta_position'],
							'current_raw_sync_meta'      => $current['raw_sync_meta'],
							'base_revision'              => array(
								'revision_id'            => $base_revision['revision_id'],
								'revision_date_gmt'      => $base_revision['revision_date_gmt'],
								'content'                => $base_revision['content'],
								'content_hash'           => $base_revision_content_hash,
								'sync_meta'              => $base_revision['sync_meta'],
								'sync_meta_format'       => $base_revision['sync_meta_format'],
								'sync_meta_position'     => $base_revision['sync_meta_position'],
								'raw_sync_meta'          => $base_revision['raw_sync_meta'],
								'scanned_revisions'      => $base_revision['scanned_revisions'],
								'malformed_revision_ids' => $base_revision['malformed_revision_ids'],
							),
							'base_revision_content_hash' => $base_revision_content_hash,
							'revision_scan'              => $base_revision,
							'external_change'            => array(
								'mode'                    => 'body_hash_drift',
								'base_revision_id'        => $base_revision['revision_id'],
								'base_revision_date_gmt'  => $base_revision['revision_date_gmt'],
								'base_content'            => $base_revision['content'],
								'base_content_hash'       => $base_revision_content_hash,
								'current_content'         => $current['content'],
								'current_content_hash'    => $current_content_hash,
								'content_hash_algorithm'  => 'sha256',
								'recovery_reason_code'    => 'de_rtc_sync_meta_repaired_from_body',
							),
						);
					}

					return array(
						'decision'                   => 'manual_resolution_required',
						'post_id'                    => (int) $post->ID,
						'recovery_required'          => true,
						'restorable'                 => false,
						'manual_resolution_required' => true,
						'reason'                     => wp_de_rtc_get_reason_data(
							'de_rtc_sync_meta_unrecoverable',
							array(
								'detail'                       => 'automerge_body_hash_drift_without_trusted_base',
								'base_version'                 => $base_version,
								'expected_base_content_hash'    => $stored_content_hash,
								'current_stripped_content_hash' => $current_content_hash,
							)
						),
						'current_content'            => $current['content'],
						'current_content_hash'       => $current_content_hash,
						'content_hash_algorithm'     => 'sha256',
						'current_sync_meta'          => $current['sync_meta'],
						'current_sync_meta_format'   => $current['sync_meta_format'],
						'current_sync_meta_position' => $current['sync_meta_position'],
						'current_raw_sync_meta'      => $current['raw_sync_meta'],
						'base_revision'              => null,
						'base_revision_content_hash' => null,
						'revision_scan'              => is_array( $base_revision ) ? $base_revision : null,
						'external_change'            => null,
					);
				}
			}

			return array(
				'decision'                   => 'no_recovery_required',
				'post_id'                    => (int) $post->ID,
			'recovery_required'          => false,
			'restorable'                 => false,
			'manual_resolution_required' => false,
			'reason'                     => null,
			'current_content'            => $current['content'],
			'current_content_hash'       => $current_content_hash,
			'content_hash_algorithm'     => 'sha256',
			'current_sync_meta'          => $current['sync_meta'],
			'current_sync_meta_format'   => $current['sync_meta_format'],
			'current_sync_meta_position' => $current['sync_meta_position'],
			'current_raw_sync_meta'      => $current['raw_sync_meta'],
			'base_revision'              => null,
			'base_revision_content_hash' => null,
			'revision_scan'              => null,
			'external_change'            => null,
		);
	}

	$revision_scan = wp_de_rtc_find_latest_revision_with_sync_meta( $post );

	if ( is_wp_error( $revision_scan ) ) {
		return $revision_scan;
	}

	if ( $revision_scan['found'] ) {
		$base_revision_content_hash = wp_de_rtc_hash_content( $revision_scan['content'] );

		return array(
			'decision'                   => 'recovery_required_restorable',
			'post_id'                    => (int) $post->ID,
			'recovery_required'          => true,
			'restorable'                 => true,
			'manual_resolution_required' => false,
			'reason'                     => wp_de_rtc_get_reason_data(
				'de_rtc_missing_sync_meta',
				array(
					'detail'               => 'restorable_revision_found',
					'recovery_reason_code' => 'de_rtc_sync_meta_restored_from_revision',
				)
			),
			'current_content'            => $current['content'],
			'current_content_hash'       => $current_content_hash,
			'content_hash_algorithm'     => 'sha256',
			'current_sync_meta'          => null,
			'current_sync_meta_format'   => null,
			'current_sync_meta_position' => null,
			'current_raw_sync_meta'      => null,
			'base_revision'              => array(
				'revision_id'            => $revision_scan['revision_id'],
				'revision_date_gmt'      => $revision_scan['revision_date_gmt'],
				'content'                => $revision_scan['content'],
				'content_hash'           => $base_revision_content_hash,
				'sync_meta'              => $revision_scan['sync_meta'],
				'sync_meta_format'       => $revision_scan['sync_meta_format'],
				'sync_meta_position'     => $revision_scan['sync_meta_position'],
				'raw_sync_meta'          => $revision_scan['raw_sync_meta'],
				'scanned_revisions'      => $revision_scan['scanned_revisions'],
				'malformed_revision_ids' => $revision_scan['malformed_revision_ids'],
			),
			'base_revision_content_hash' => $base_revision_content_hash,
			'revision_scan'              => $revision_scan,
			'external_change'            => array(
				'base_revision_id'              => $revision_scan['revision_id'],
				'base_revision_date_gmt'        => $revision_scan['revision_date_gmt'],
				'base_content'                  => $revision_scan['content'],
				'base_content_hash'             => $base_revision_content_hash,
				'current_content'               => $current['content'],
				'current_content_hash'          => $current_content_hash,
				'content_hash_algorithm'        => 'sha256',
				'restored_sync_meta'            => $revision_scan['sync_meta'],
				'restored_sync_meta_format'     => $revision_scan['sync_meta_format'],
				'restored_sync_meta_position'   => $revision_scan['sync_meta_position'],
				'restored_raw_sync_meta'        => $revision_scan['raw_sync_meta'],
				'recovery_reason_code'          => 'de_rtc_sync_meta_restored_from_revision',
				'missing_sync_meta_reason_code' => 'de_rtc_missing_sync_meta',
			),
		);
	}

		$empty_sync_meta = wp_de_rtc_get_empty_automerge_sync_meta_for_external_import( $post );

		return array(
			'decision'                   => 'recovery_required_restorable',
			'post_id'                    => (int) $post->ID,
			'recovery_required'          => true,
			'restorable'                 => true,
			'manual_resolution_required' => false,
			'reason'                     => wp_de_rtc_get_reason_data(
				'de_rtc_missing_sync_meta',
				array(
					'detail'                 => 'empty_automerge_import_required',
					'recovery_reason_code'   => 'de_rtc_sync_meta_empty_automerge_import',
					'scanned_revisions'      => $revision_scan['scanned_revisions'],
					'malformed_revision_ids' => $revision_scan['malformed_revision_ids'],
				)
			),
			'current_content'            => $current['content'],
			'current_content_hash'       => $current_content_hash,
			'content_hash_algorithm'     => 'sha256',
			'current_sync_meta'          => null,
			'current_sync_meta_format'   => null,
			'current_sync_meta_position' => null,
			'current_raw_sync_meta'      => null,
			'base_revision'              => array(
				'revision_id'            => 0,
				'revision_date_gmt'      => null,
				'content'                => '',
				'content_hash'           => wp_de_rtc_hash_content( '' ),
				'sync_meta'              => $empty_sync_meta,
				'sync_meta_format'       => 'automerge',
				'sync_meta_position'     => 'prefix-block',
				'raw_sync_meta'          => null,
				'scanned_revisions'      => $revision_scan['scanned_revisions'],
				'malformed_revision_ids' => $revision_scan['malformed_revision_ids'],
			),
			'base_revision_content_hash' => wp_de_rtc_hash_content( '' ),
			'revision_scan'              => $revision_scan,
			'external_change'            => array(
				'mode'                       => 'empty_import',
				'base_revision_id'           => 0,
				'base_revision_date_gmt'     => null,
				'base_content'               => '',
				'base_content_hash'          => wp_de_rtc_hash_content( '' ),
				'current_content'            => $current['content'],
				'current_content_hash'       => $current_content_hash,
				'content_hash_algorithm'     => 'sha256',
				'recovery_reason_code'       => 'de_rtc_sync_meta_empty_automerge_import',
				'missing_sync_meta_reason_code' => 'de_rtc_missing_sync_meta',
			),
		);
	}

/**
 * Plans a read-only Distributed Editing sync-meta recovery update.
 *
 * This helper accepts either a recovery decision array from
 * wp_de_rtc_get_post_sync_meta_recovery_decision() or a post ID/object from
 * which the decision should be derived. It only returns candidate data for a
 * later write path; it does not update posts, restore revisions, create
 * revisions, change locks, register REST behavior, or save.
 *
 * @since 7.1.0
 *
 * @param array|int|WP_Post|WP_Error $decision_or_post Recovery decision, post ID/object, or existing error.
 * @return array|WP_Error {
 *     Read-only recovery update plan on success, or a WP_Error when the source decision is invalid.
 *
 *     @type string      $plan                              Plan label.
 *     @type string      $decision                          Source recovery decision label.
 *     @type int         $post_id                           Post ID.
 *     @type bool        $can_apply                         Whether a later mutation path may apply this plan.
 *     @type bool        $recovery_required                 Whether recovery is required.
 *     @type bool        $manual_resolution_required        Whether manual resolution is required.
 *     @type array|null  $reason                            Canonical reason data, or null for no-op plans.
 *     @type string|null $reason_code                       Canonical reason code, or null for no-op plans.
 *     @type string      $current_content                   Current post content without sync metadata.
 *     @type string      $current_content_hash              SHA-256 hash of current content without sync metadata.
 *     @type string      $content_hash_algorithm            Content hash algorithm.
 *     @type string|null $base_revision_content_hash        SHA-256 hash of base revision content, if available.
 *     @type string|null $candidate_stripped_content        Candidate content without sync metadata.
 *     @type string|null $candidate_stripped_content_hash   SHA-256 hash of candidate stripped content.
 *     @type string|null $candidate_post_content            Candidate post_content, or null when blocked.
 *     @type string|null $candidate_post_content_hash       SHA-256 hash of candidate post_content.
 *     @type array|null  $restored_sync_meta                Restored sync metadata, if available.
 *     @type string|null $restored_sync_meta_format         Restored sync metadata format, if available.
 *     @type string|null $restored_sync_meta_position       Restored sync metadata position, if available.
 *     @type string|null $restored_raw_sync_meta            Generated restored sync metadata SCRIPT, if available.
 *     @type array|null  $external_change                   External-change evidence for later persistence.
 * }
 */
function wp_de_rtc_plan_sync_meta_recovery_update( $decision_or_post ) {
	if ( is_wp_error( $decision_or_post ) ) {
		return $decision_or_post;
	}

	$current_post_content = null;

	if ( is_array( $decision_or_post ) && isset( $decision_or_post['decision'] ) ) {
		$decision = $decision_or_post;
	} else {
		$post = get_post( $decision_or_post );

		if ( $post ) {
			$current_post_content = $post->post_content;
		}

		$decision = wp_de_rtc_get_post_sync_meta_recovery_decision( $decision_or_post );
	}

	if ( is_wp_error( $decision ) ) {
		return $decision;
	}

	if (
		! is_array( $decision ) ||
		empty( $decision['decision'] ) ||
		! isset( $decision['post_id'], $decision['current_content'] ) ||
		! is_string( $decision['decision'] ) ||
		! is_string( $decision['current_content'] )
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_unrecoverable',
			__( 'Distributed Editing could not plan sync metadata recovery because the recovery decision is invalid.' ),
			array(
				'detail' => 'invalid_recovery_decision',
			)
		);
	}

	$current_content      = $decision['current_content'];
	$current_content_hash = isset( $decision['current_content_hash'] ) && is_string( $decision['current_content_hash'] )
		? $decision['current_content_hash']
		: wp_de_rtc_hash_content( $current_content );

	if ( 'no_recovery_required' === $decision['decision'] ) {
		if ( null === $current_post_content ) {
			if (
				isset( $decision['current_raw_sync_meta'], $decision['current_sync_meta_position'] ) &&
				is_string( $decision['current_raw_sync_meta'] ) &&
				is_string( $decision['current_sync_meta_position'] )
			) {
				if ( 'prefix' === $decision['current_sync_meta_position'] ) {
					$current_post_content = $decision['current_raw_sync_meta'] . $current_content;
				} elseif ( 'trailer' === $decision['current_sync_meta_position'] ) {
					$current_post_content = $current_content . $decision['current_raw_sync_meta'];
				}
			}

			if ( null === $current_post_content ) {
				$current_post_content = $current_content;
			}
		}

		return array(
			'plan'                            => 'sync_meta_recovery_update',
			'decision'                        => $decision['decision'],
			'post_id'                         => (int) $decision['post_id'],
			'can_apply'                       => false,
			'recovery_required'               => false,
			'manual_resolution_required'      => false,
			'reason'                          => null,
			'reason_code'                     => null,
			'current_content'                 => $current_content,
			'current_content_hash'            => $current_content_hash,
			'content_hash_algorithm'          => 'sha256',
			'base_revision_content_hash'      => null,
			'candidate_stripped_content'      => $current_content,
			'candidate_stripped_content_hash' => wp_de_rtc_hash_content( $current_content ),
			'candidate_post_content'          => $current_post_content,
			'candidate_post_content_hash'     => wp_de_rtc_hash_content( $current_post_content ),
			'restored_sync_meta'              => null,
			'restored_sync_meta_format'       => null,
			'restored_sync_meta_position'     => null,
			'restored_raw_sync_meta'          => null,
			'external_change'                 => null,
		);
	}

	if ( 'manual_resolution_required' === $decision['decision'] ) {
		$reason      = isset( $decision['reason'] ) && is_array( $decision['reason'] )
			? $decision['reason']
			: wp_de_rtc_get_reason_data(
				'de_rtc_sync_meta_unrecoverable',
				array(
					'detail' => 'manual_resolution_required',
				)
			);
		$reason_code = isset( $reason['reason_code'] ) && is_string( $reason['reason_code'] ) ? $reason['reason_code'] : null;

		return array(
			'plan'                            => 'sync_meta_recovery_update',
			'decision'                        => $decision['decision'],
			'post_id'                         => (int) $decision['post_id'],
			'can_apply'                       => false,
			'recovery_required'               => true,
			'manual_resolution_required'      => true,
			'reason'                          => $reason,
			'reason_code'                     => $reason_code,
			'current_content'                 => $current_content,
			'current_content_hash'            => $current_content_hash,
			'content_hash_algorithm'          => 'sha256',
			'base_revision_content_hash'      => null,
			'candidate_stripped_content'      => null,
			'candidate_stripped_content_hash' => null,
			'candidate_post_content'          => null,
			'candidate_post_content_hash'     => null,
			'restored_sync_meta'              => null,
			'restored_sync_meta_format'       => null,
			'restored_sync_meta_position'     => null,
			'restored_raw_sync_meta'          => null,
			'external_change'                 => null,
		);
	}

	if (
		'recovery_required_restorable' !== $decision['decision'] ||
		empty( $decision['base_revision'] ) ||
		! is_array( $decision['base_revision'] ) ||
		empty( $decision['base_revision']['sync_meta_format'] ) ||
		empty( $decision['base_revision']['sync_meta_position'] ) ||
		! isset( $decision['base_revision']['sync_meta'] ) ||
		! is_string( $decision['base_revision']['sync_meta_format'] ) ||
		! is_string( $decision['base_revision']['sync_meta_position'] )
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_unrecoverable',
			__( 'Distributed Editing could not plan sync metadata recovery because the restorable decision is invalid.' ),
			array(
				'detail'   => 'invalid_restorable_recovery_decision',
				'decision' => $decision['decision'],
			)
		);
	}

	$base_revision          = $decision['base_revision'];

	if ( wp_de_rtc_is_current_automerge_sync_meta( $base_revision['sync_meta'], $base_revision['sync_meta_format'] ) ) {
		$external_change = isset( $decision['external_change'] ) && is_array( $decision['external_change'] )
			? $decision['external_change']
			: array();
		$repair_mode     = isset( $external_change['mode'] ) && is_string( $external_change['mode'] )
			? sanitize_key( $external_change['mode'] )
			: ( empty( $base_revision['revision_id'] ) ? 'empty_import' : 'missing_sync_meta_revision' );
		$base_version    = isset( $base_revision['sync_meta']['version'] ) ? sanitize_text_field( (string) $base_revision['sync_meta']['version'] ) : '0';
		$repair          = wp_de_rtc_get_automerge_external_repair_update(
			get_post( (int) $decision['post_id'] ),
			array(
				'base_content'       => isset( $base_revision['content'] ) && is_string( $base_revision['content'] ) ? $base_revision['content'] : '',
				'base_sync_meta'     => $base_revision['sync_meta'],
				'base_version'       => $base_version,
				'current_content'    => $current_content,
				'mode'               => $repair_mode,
				'base_revision_id'   => isset( $base_revision['revision_id'] ) ? (int) $base_revision['revision_id'] : 0,
				'sync_meta_position' => $base_revision['sync_meta_position'],
			)
		);

		if ( is_wp_error( $repair ) ) {
			return $repair;
		}

		$candidate_post_content = wp_de_rtc_add_sync_meta_to_post_content(
			$current_content,
			'automerge',
			$repair['sync_meta'],
			$repair['sync_meta_position']
		);

		if ( is_wp_error( $candidate_post_content ) ) {
			return $candidate_post_content;
		}

		$restored_raw_sync_meta           = wp_de_rtc_format_sync_meta( 'automerge', $repair['sync_meta'] );
		$candidate_stripped_content_hash = wp_de_rtc_hash_content( $current_content );
		$candidate_post_content_hash     = wp_de_rtc_hash_content( $candidate_post_content );
		$base_revision_content_hash      = isset( $decision['base_revision_content_hash'] ) && is_string( $decision['base_revision_content_hash'] )
			? $decision['base_revision_content_hash']
			: wp_de_rtc_hash_content( isset( $base_revision['content'] ) && is_string( $base_revision['content'] ) ? $base_revision['content'] : '' );
		$reason_code                     = 'empty_import' === $repair_mode ? 'de_rtc_sync_meta_empty_automerge_import' : 'de_rtc_sync_meta_repaired_from_body';
		$reason_detail                   = 'empty_import' === $repair_mode ? 'planned_empty_automerge_import' : 'planned_automerge_external_body_repair';

		if ( is_wp_error( $restored_raw_sync_meta ) ) {
			return $restored_raw_sync_meta;
		}

		$external_change = array_merge(
			$external_change,
			array(
				'mode'                              => $repair_mode,
				'candidate_stripped_content_hash' => $candidate_stripped_content_hash,
				'candidate_post_content_hash'     => $candidate_post_content_hash,
				'candidate_sync_meta_format'      => 'automerge',
				'candidate_sync_meta_position'    => $repair['sync_meta_position'],
				'candidate_reason_code'           => $reason_code,
				'repaired_sync_meta_version'      => $repair['server_version'],
			)
		);

		return array(
			'plan'                            => 'sync_meta_recovery_update',
			'decision'                        => $decision['decision'],
			'post_id'                         => (int) $decision['post_id'],
			'can_apply'                       => true,
			'recovery_required'               => true,
			'manual_resolution_required'      => false,
			'reason'                          => wp_de_rtc_get_reason_data(
				$reason_code,
				array_filter(
					array(
						'detail'           => $reason_detail,
						'base_revision_id' => isset( $base_revision['revision_id'] ) ? (int) $base_revision['revision_id'] : null,
					)
				)
			),
			'reason_code'                     => $reason_code,
			'current_content'                 => $current_content,
			'current_content_hash'            => $current_content_hash,
			'content_hash_algorithm'          => 'sha256',
			'base_revision_content_hash'      => $base_revision_content_hash,
			'candidate_stripped_content'      => $current_content,
			'candidate_stripped_content_hash' => $candidate_stripped_content_hash,
			'candidate_post_content'          => $candidate_post_content,
			'candidate_post_content_hash'     => $candidate_post_content_hash,
			'restored_sync_meta'              => $repair['sync_meta'],
			'restored_sync_meta_format'       => 'automerge',
			'restored_sync_meta_position'     => $repair['sync_meta_position'],
			'restored_raw_sync_meta'          => rtrim( $restored_raw_sync_meta ),
			'external_change'                 => $external_change,
		);
	}

	$restored_sync_meta = $base_revision['sync_meta'];

	if ( is_array( $restored_sync_meta ) ) {
		$legacy_recovery_actor = wp_de_rtc_get_system_recovery_actor_descriptor(
			get_post( (int) $decision['post_id'] ),
			array(
				'document_uuid'        => isset( $restored_sync_meta['document_uuid'] ) && is_string( $restored_sync_meta['document_uuid'] ) ? $restored_sync_meta['document_uuid'] : null,
				'base_version'         => isset( $restored_sync_meta['version'] ) ? sanitize_text_field( (string) $restored_sync_meta['version'] ) : '0',
				'mode'                 => 'legacy_sync_meta_restore',
				'base_revision_id'     => isset( $base_revision['revision_id'] ) ? (int) $base_revision['revision_id'] : 0,
				'current_content_hash' => $current_content_hash,
			)
		);
		$restored_sync_meta['last_sync_meta_recovery'] = array(
			'type'                        => 'sync_meta_restored_from_revision',
			'mode'                        => 'legacy_sync_meta_restore',
			'actor'                       => $legacy_recovery_actor,
			'previous_server_version'     => isset( $restored_sync_meta['version'] ) ? sanitize_text_field( (string) $restored_sync_meta['version'] ) : '',
			'repaired_server_version'     => isset( $restored_sync_meta['version'] ) ? sanitize_text_field( (string) $restored_sync_meta['version'] ) : '',
			'saved_stripped_content_hash' => $current_content_hash,
			'content_hash_algorithm'      => 'sha256',
		);

		if ( isset( $base_revision['revision_id'] ) ) {
			$restored_sync_meta['last_sync_meta_recovery']['base_revision_id'] = (int) $base_revision['revision_id'];
		}
	}

	$restored_raw_sync_meta = wp_de_rtc_format_sync_meta( $base_revision['sync_meta_format'], $restored_sync_meta );

	if ( is_wp_error( $restored_raw_sync_meta ) ) {
		return $restored_raw_sync_meta;
	}

	$restored_raw_sync_meta = rtrim( $restored_raw_sync_meta );

	$candidate_post_content = wp_de_rtc_add_sync_meta_to_post_content(
		$current_content,
		$base_revision['sync_meta_format'],
		$restored_sync_meta,
		$base_revision['sync_meta_position']
	);

	if ( is_wp_error( $candidate_post_content ) ) {
		return $candidate_post_content;
	}

	$candidate_stripped_content_hash = wp_de_rtc_hash_content( $current_content );
	$candidate_post_content_hash     = wp_de_rtc_hash_content( $candidate_post_content );
	$base_revision_content_hash      = isset( $decision['base_revision_content_hash'] ) && is_string( $decision['base_revision_content_hash'] )
		? $decision['base_revision_content_hash']
		: null;

	if ( null === $base_revision_content_hash && isset( $base_revision['content'] ) && is_string( $base_revision['content'] ) ) {
		$base_revision_content_hash = wp_de_rtc_hash_content( $base_revision['content'] );
	}

	$source_reason_code = null;

	if ( isset( $decision['reason']['reason_code'] ) && is_string( $decision['reason']['reason_code'] ) ) {
		$source_reason_code = $decision['reason']['reason_code'];
	}

	$reason = wp_de_rtc_get_reason_data(
		'de_rtc_sync_meta_restored_from_revision',
		array_filter(
			array(
				'detail'             => 'planned_sync_meta_recovery_update',
				'source_reason_code' => $source_reason_code,
				'base_revision_id'   => isset( $base_revision['revision_id'] ) ? (int) $base_revision['revision_id'] : null,
			)
		)
	);

	$external_change = isset( $decision['external_change'] ) && is_array( $decision['external_change'] )
		? $decision['external_change']
		: array();

	$external_change = array_merge(
		$external_change,
		array(
			'candidate_stripped_content_hash' => $candidate_stripped_content_hash,
			'candidate_post_content_hash'     => $candidate_post_content_hash,
			'candidate_sync_meta_format'      => $base_revision['sync_meta_format'],
			'candidate_sync_meta_position'    => $base_revision['sync_meta_position'],
			'candidate_reason_code'           => 'de_rtc_sync_meta_restored_from_revision',
		)
	);

	return array(
		'plan'                            => 'sync_meta_recovery_update',
		'decision'                        => $decision['decision'],
		'post_id'                         => (int) $decision['post_id'],
		'can_apply'                       => true,
		'recovery_required'               => true,
		'manual_resolution_required'      => false,
		'reason'                          => $reason,
		'reason_code'                     => 'de_rtc_sync_meta_restored_from_revision',
		'current_content'                 => $current_content,
		'current_content_hash'            => $current_content_hash,
		'content_hash_algorithm'          => 'sha256',
		'base_revision_content_hash'      => $base_revision_content_hash,
		'candidate_stripped_content'      => $current_content,
		'candidate_stripped_content_hash' => $candidate_stripped_content_hash,
		'candidate_post_content'          => $candidate_post_content,
		'candidate_post_content_hash'     => $candidate_post_content_hash,
		'restored_sync_meta'              => $restored_sync_meta,
		'restored_sync_meta_format'       => $base_revision['sync_meta_format'],
		'restored_sync_meta_position'     => $base_revision['sync_meta_position'],
		'restored_raw_sync_meta'          => $restored_raw_sync_meta,
		'external_change'                 => $external_change,
	);
}

/**
 * Dry-runs a Distributed Editing sync-meta recovery update plan.
 *
 * This helper validates candidate recovery output from
 * wp_de_rtc_plan_sync_meta_recovery_update() but never applies it. It creates
 * an explicit dry-run boundary for a later apply helper and does not update
 * posts, restore revisions, create revisions, change locks, register REST
 * behavior, or save.
 *
 * @since 7.1.0
 *
 * @param array|int|WP_Post|WP_Error $plan_decision_or_post Recovery plan, recovery decision, post ID/object, or existing error.
 * @return array|WP_Error {
 *     Dry-run result on success, or a WP_Error when the plan cannot be validated.
 *
 *     @type string      $mode                    Dry-run mode label.
 *     @type string      $result                  Dry-run result label.
 *     @type string      $validation_status       Validation status label.
 *     @type string      $decision                Source recovery decision label.
 *     @type int         $post_id                 Post ID.
 *     @type bool        $valid                   Whether the candidate is valid.
 *     @type bool        $can_apply               Whether a later apply helper may apply the plan.
 *     @type bool        $would_apply             Always false for this dry-run helper.
 *     @type bool        $recovery_required       Whether recovery is required.
 *     @type bool        $manual_resolution_required Whether manual resolution is required.
 *     @type array|null  $reason                  Canonical reason data, or null for no-op results.
 *     @type string|null $reason_code             Canonical reason code, or null for no-op results.
 *     @type array       $checks                  Validation checks.
 *     @type array       $plan                    Source recovery update plan.
 * }
 */
function wp_de_rtc_dry_run_sync_meta_recovery_update( $plan_decision_or_post ) {
	if ( is_wp_error( $plan_decision_or_post ) ) {
		return $plan_decision_or_post;
	}

	if ( is_array( $plan_decision_or_post ) && isset( $plan_decision_or_post['plan'] ) ) {
		$plan = $plan_decision_or_post;
	} else {
		$plan = wp_de_rtc_plan_sync_meta_recovery_update( $plan_decision_or_post );
	}

	if ( is_wp_error( $plan ) ) {
		return $plan;
	}

	if (
		! is_array( $plan ) ||
		empty( $plan['plan'] ) ||
		'sync_meta_recovery_update' !== $plan['plan'] ||
		empty( $plan['decision'] ) ||
		! isset( $plan['post_id'], $plan['current_content'] ) ||
		! is_string( $plan['decision'] ) ||
		! is_string( $plan['current_content'] )
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_unrecoverable',
			__( 'Distributed Editing could not dry-run sync metadata recovery because the recovery plan is invalid.' ),
			array(
				'detail' => 'invalid_recovery_update_plan',
			)
		);
	}

	if ( 'no_recovery_required' === $plan['decision'] ) {
		return wp_de_rtc_create_recovery_dry_run_result(
			$plan,
			'no_update_required',
			'noop',
			true,
			false,
			array(
				'candidate_required'     => false,
				'candidate_content_safe' => true,
			)
		);
	}

	if ( 'manual_resolution_required' === $plan['decision'] ) {
		return wp_de_rtc_create_recovery_dry_run_result(
			$plan,
			'manual_resolution_required',
			'blocked',
			false,
			false,
			array(
				'candidate_required'     => false,
				'candidate_content_safe' => false,
			)
		);
	}

	if ( 'recovery_required_restorable' !== $plan['decision'] ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_unrecoverable',
			__( 'Distributed Editing could not dry-run sync metadata recovery because the plan decision is unsupported.' ),
			array(
				'detail'   => 'unsupported_recovery_update_plan',
				'decision' => $plan['decision'],
			)
		);
	}

	$checks = wp_de_rtc_validate_recovery_update_candidate( $plan );
	$valid  = ! in_array( false, $checks, true );

	return wp_de_rtc_create_recovery_dry_run_result(
		$plan,
		$valid ? 'candidate_update_valid' : 'candidate_update_invalid',
		$valid ? 'valid_candidate' : 'invalid_candidate',
		$valid,
		$valid && ! empty( $plan['can_apply'] ),
		$checks
	);
}

/**
 * Applies a Distributed Editing sync-meta recovery update plan when explicitly requested.
 *
 * This helper creates the first guarded write boundary for sync-meta recovery.
 * It always dry-runs and validates the candidate first. It does not write
 * unless the caller passes an options array with `mode` set to `apply`.
 *
 * @since 7.1.0
 *
 * @param array|int|WP_Post|WP_Error $plan_decision_or_post Recovery plan, recovery decision, post ID/object, or existing error.
 * @param array                      $options               Optional. Apply options. Requires `mode => 'apply'` to persist.
 * @return array|WP_Error Apply result on success, guarded no-op result when apply was not requested, or a WP_Error.
 */
function wp_de_rtc_apply_sync_meta_recovery_update( $plan_decision_or_post, $options = array() ) {
	if ( is_wp_error( $plan_decision_or_post ) ) {
		return $plan_decision_or_post;
	}

	if ( ! is_array( $options ) ) {
		$options = array();
	}

	$dry_run = wp_de_rtc_dry_run_sync_meta_recovery_update( $plan_decision_or_post );

	if ( is_wp_error( $dry_run ) ) {
		return $dry_run;
	}

	$requested_mode = isset( $options['mode'] ) && is_string( $options['mode'] ) ? $options['mode'] : 'dry_run';

	if ( 'apply' !== $requested_mode ) {
		return wp_de_rtc_create_recovery_apply_result(
			$dry_run,
			'apply_not_requested',
			false,
			array(
				'requested_mode' => $requested_mode,
			)
		);
	}

	if ( empty( $dry_run['valid'] ) || empty( $dry_run['can_apply'] ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing could not apply sync metadata recovery because the dry-run candidate is not valid.' ),
			array(
				'detail'                => 'invalid_recovery_update_candidate',
				'dry_run_result'        => isset( $dry_run['result'] ) ? $dry_run['result'] : null,
				'dry_run_valid'         => ! empty( $dry_run['valid'] ),
				'dry_run_can_apply'     => ! empty( $dry_run['can_apply'] ),
				'dry_run_reason_code'   => isset( $dry_run['reason_code'] ) ? $dry_run['reason_code'] : null,
				'dry_run_check_results' => isset( $dry_run['checks'] ) ? $dry_run['checks'] : array(),
			)
		);
	}

	if (
		! isset( $dry_run['plan']['candidate_post_content'], $dry_run['plan']['candidate_post_content_hash'] ) ||
		! is_string( $dry_run['plan']['candidate_post_content'] ) ||
		! is_string( $dry_run['plan']['candidate_post_content_hash'] )
	) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_unrecoverable',
			__( 'Distributed Editing could not apply sync metadata recovery because the candidate post content is missing.' ),
			array(
				'detail' => 'missing_recovery_update_candidate',
			)
		);
	}

	$post_id                     = (int) $dry_run['post_id'];
	$revision_ids_before_apply   = wp_de_rtc_get_post_revision_ids( $post_id );
	$candidate_post_content_hash = $dry_run['plan']['candidate_post_content_hash'];
	$candidate_post_content      = $dry_run['plan']['candidate_post_content'];
	$added_sync_meta_kses_allowance = false === has_filter( 'wp_kses_allowed_html', 'wp_de_rtc_filter_sync_meta_script_kses_allowance' );

	if ( $added_sync_meta_kses_allowance ) {
		wp_de_rtc_enable_sync_meta_script_kses_allowance();
	}

	global $wp_de_rtc_prepared_automerge_raw_save_content;

	if ( ! is_array( $wp_de_rtc_prepared_automerge_raw_save_content ) ) {
		$wp_de_rtc_prepared_automerge_raw_save_content = array();
	}

	$wp_de_rtc_prepared_automerge_raw_save_content[ $post_id ] = $candidate_post_content;

	try {
		$updated_post_id = wp_update_post(
			wp_slash(
				array(
					'ID'           => $post_id,
					'post_content' => $candidate_post_content,
				)
			),
			true
		);
	} finally {
		unset( $wp_de_rtc_prepared_automerge_raw_save_content[ $post_id ] );

		if ( $added_sync_meta_kses_allowance ) {
			wp_de_rtc_disable_sync_meta_script_kses_allowance();
		}
	}

	if ( is_wp_error( $updated_post_id ) ) {
		return $updated_post_id;
	}

	if ( ! $updated_post_id ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_storage_failure',
			__( 'Distributed Editing could not apply sync metadata recovery because the post update failed.' ),
			array(
				'detail'  => 'post_update_failed',
				'post_id' => $post_id,
			)
		);
	}

	$revision_ids_after_apply = wp_de_rtc_get_post_revision_ids( $post_id );
	$created_revision_ids     = array_values( array_diff( $revision_ids_after_apply, $revision_ids_before_apply ) );

	return wp_de_rtc_create_recovery_apply_result(
		$dry_run,
		'candidate_update_applied',
		true,
		array(
			'updated_post_id'             => (int) $updated_post_id,
			'candidate_post_content_hash' => $candidate_post_content_hash,
			'revision_ids_before_apply'   => $revision_ids_before_apply,
			'revision_ids_after_apply'    => $revision_ids_after_apply,
			'created_revision_ids'        => $created_revision_ids,
			'revision_created'            => ! empty( $created_revision_ids ),
		)
	);
}

/**
 * Creates a WP_Error with canonical Distributed Editing reason data.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $reason_code Canonical DE-RTC reason code.
 * @param string $message     Error message.
 * @param array  $data        Optional. Additional error data.
 * @return WP_Error Error with status and reason-code data.
 */
function wp_de_rtc_get_reason_error( $reason_code, $message, $data = array() ) {
	$codes  = wp_de_rtc_get_reason_codes();
	$status = isset( $codes[ $reason_code ] ) ? $codes[ $reason_code ] : 500;

	return new WP_Error(
		$reason_code,
		$message,
		array_merge(
			array(
				'status'      => $status,
				'reason_code' => $reason_code,
			),
			$data
		)
	);
}

/**
 * Creates canonical Distributed Editing reason data.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $reason_code Canonical DE-RTC reason code.
 * @param array  $data        Optional. Additional reason data.
 * @return array Reason data with status and reason-code fields.
 */
function wp_de_rtc_get_reason_data( $reason_code, $data = array() ) {
	$codes  = wp_de_rtc_get_reason_codes();
	$status = isset( $codes[ $reason_code ] ) ? $codes[ $reason_code ] : 500;

	return array_merge(
		array(
			'status'      => $status,
			'reason_code' => $reason_code,
		),
		$data
	);
}

/**
 * Creates a DE-RTC dry-run result for a recovery update plan.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array  $plan              Recovery update plan.
 * @param string $result            Result label.
 * @param string $validation_status Validation status label.
 * @param bool   $valid             Whether the dry run validated successfully.
 * @param bool   $can_apply         Whether a later apply helper may apply the plan.
 * @param array  $checks            Validation checks.
 * @return array Dry-run result.
 */
function wp_de_rtc_create_recovery_dry_run_result( $plan, $result, $validation_status, $valid, $can_apply, $checks ) {
	$attribution = isset( $plan['restored_sync_meta'] ) ? wp_de_rtc_get_sync_meta_recovery_attribution( $plan['restored_sync_meta'] ) : null;

	return array_merge(
		array(
			'mode'                       => 'dry_run',
			'result'                     => $result,
			'validation_status'          => $validation_status,
			'decision'                   => $plan['decision'],
			'post_id'                    => (int) $plan['post_id'],
			'valid'                      => $valid,
			'can_apply'                  => $can_apply,
			'would_apply'                => false,
			'recovery_required'          => ! empty( $plan['recovery_required'] ),
			'manual_resolution_required' => ! empty( $plan['manual_resolution_required'] ),
			'reason'                     => isset( $plan['reason'] ) && is_array( $plan['reason'] ) ? $plan['reason'] : null,
			'reason_code'                => isset( $plan['reason_code'] ) && is_string( $plan['reason_code'] ) ? $plan['reason_code'] : null,
			'checks'                     => $checks,
			'plan'                       => $plan,
		),
		wp_de_rtc_get_recovery_attribution_response_fields( $attribution )
	);
}

/**
 * Creates a DE-RTC apply result for a recovery update dry run.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array  $dry_run Apply source dry-run result.
 * @param string $result  Apply result label.
 * @param bool   $applied Whether the candidate was applied.
 * @param array  $extra   Optional. Additional result data.
 * @return array Apply result.
 */
function wp_de_rtc_create_recovery_apply_result( $dry_run, $result, $applied, $extra = array() ) {
	$attribution_fields = array(
		'recovery_attribution'        => isset( $dry_run['recovery_attribution'] ) ? $dry_run['recovery_attribution'] : null,
		'recovery_actor_type'         => isset( $dry_run['recovery_actor_type'] ) ? $dry_run['recovery_actor_type'] : null,
		'recovery_attribution_key'    => isset( $dry_run['recovery_attribution_key'] ) ? $dry_run['recovery_attribution_key'] : null,
		'recovery_attribution_source' => isset( $dry_run['recovery_attribution_source'] ) ? $dry_run['recovery_attribution_source'] : null,
	);

	return array_merge(
		array(
			'mode'                       => 'apply',
			'result'                     => $result,
			'validation_status'          => isset( $dry_run['validation_status'] ) ? $dry_run['validation_status'] : null,
			'decision'                   => isset( $dry_run['decision'] ) ? $dry_run['decision'] : null,
			'post_id'                    => isset( $dry_run['post_id'] ) ? (int) $dry_run['post_id'] : 0,
			'valid'                      => ! empty( $dry_run['valid'] ),
			'can_apply'                  => ! empty( $dry_run['can_apply'] ),
			'would_apply'                => $applied,
			'applied'                    => $applied,
			'recovery_required'          => ! empty( $dry_run['recovery_required'] ),
			'manual_resolution_required' => ! empty( $dry_run['manual_resolution_required'] ),
			'reason'                     => isset( $dry_run['reason'] ) && is_array( $dry_run['reason'] ) ? $dry_run['reason'] : null,
			'reason_code'                => isset( $dry_run['reason_code'] ) && is_string( $dry_run['reason_code'] ) ? $dry_run['reason_code'] : null,
			'checks'                     => isset( $dry_run['checks'] ) && is_array( $dry_run['checks'] ) ? $dry_run['checks'] : array(),
			'dry_run'                    => $dry_run,
		),
		$attribution_fields,
		$extra
	);
}

/**
 * Returns current revision IDs for a post.
 *
 * @since 7.1.0
 * @access private
 *
 * @param int $post_id Post ID.
 * @return int[] Revision IDs in WordPress revision query order.
 */
function wp_de_rtc_get_post_revision_ids( $post_id ) {
	global $wpdb;

	$post_id = (int) $post_id;

	if ( $post_id <= 0 ) {
		return array();
	}

	/*
	 * Retry-save responses only need revision IDs for before/after evidence.
	 * `wp_get_post_revisions()` materializes every revision post object, which
	 * scales poorly once long collaborative tests have hundreds of large
	 * revisions. Keep this helper ID-only so normal saves do not spend their
	 * memory budget loading historical post bodies.
	 */
	return array_map(
		'intval',
		$wpdb->get_col(
			$wpdb->prepare(
				"SELECT ID FROM {$wpdb->posts} WHERE post_parent = %d AND post_type = 'revision' ORDER BY post_date DESC, ID DESC",
				$post_id
			)
		)
	);
}

/**
 * Attempts a paragraph rich-text merge for one serialized block.
 *
 * This is deliberately narrower than a general HTML merge. It only accepts a
 * top-level paragraph with the same block shell. It can merge disjoint inline
 * strong/em mark changes, and the common editing shape where one side changes
 * paragraph text while the other side only changes marks on retained text.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $base_block     Accepted-base serialized block.
 * @param string $server_block   Current server serialized block.
 * @param string $proposed_block Client-proposed serialized block.
 * @return array|null Merge result or null when the block must stay a conflict.
 */
	function wp_de_rtc_get_rich_text_serialized_block_merge_candidate( $base_block, $server_block, $proposed_block ) {
	$base     = wp_de_rtc_get_paragraph_rich_text_block_parts( $base_block );
	$server   = wp_de_rtc_get_paragraph_rich_text_block_parts( $server_block );
	$proposed = wp_de_rtc_get_paragraph_rich_text_block_parts( $proposed_block );

	if ( ! $base || ! $server || ! $proposed ) {
		return null;
	}

	if (
		$base['open'] !== $server['open'] ||
		$base['open'] !== $proposed['open'] ||
		$base['close'] !== $server['close'] ||
		$base['close'] !== $proposed['close']
	) {
		return null;
	}

	$base_model     = wp_de_rtc_get_rich_text_format_model( $base['html'] );
	$server_model   = wp_de_rtc_get_rich_text_format_model( $server['html'] );
	$proposed_model = wp_de_rtc_get_rich_text_format_model( $proposed['html'] );

	if (
		! $base_model ||
		! $server_model ||
		! $proposed_model
	) {
		return null;
	}

	$server_splice   = wp_de_rtc_get_rich_text_text_splice( $base_model['text'], $server_model['text'] );
	$proposed_splice = wp_de_rtc_get_rich_text_text_splice( $base_model['text'], $proposed_model['text'] );
	$server_text_changed   = ! empty( $server_splice['changed'] );
	$proposed_text_changed = ! empty( $proposed_splice['changed'] );

	if ( ! $server_text_changed && ! $proposed_text_changed ) {
		$server_changed   = wp_de_rtc_get_rich_text_changed_indexes( $base_model, $server_model );
		$proposed_changed = wp_de_rtc_get_rich_text_changed_indexes( $base_model, $proposed_model );

		if ( wp_de_rtc_rich_text_changed_indexes_overlap( $server_changed, $proposed_changed ) ) {
			return null;
		}

		$merged_model = wp_de_rtc_merge_rich_text_format_models(
			$base_model,
			$server_model,
			$server_changed,
			$proposed_model,
			$proposed_changed
		);

		return array(
			'merged_block' => $base['open'] . wp_de_rtc_format_rich_text_model_html( $merged_model ) . $base['close'],
		);
	}

	if ( $server_text_changed && $proposed_text_changed ) {
		$merged_model = wp_de_rtc_merge_rich_text_text_splice_models(
			$base_model,
			$server_model,
			$server_splice,
			$proposed_model,
			$proposed_splice
		);

		if ( null === $merged_model ) {
			return null;
		}

		return array(
			'merged_block' => $base['open'] . wp_de_rtc_format_rich_text_model_html( $merged_model ) . $base['close'],
		);
	}

	if ( $server_text_changed ) {
		$format_changed = wp_de_rtc_get_rich_text_changed_indexes( $base_model, $proposed_model );
		$text_changed   = wp_de_rtc_get_retained_rich_text_mark_changed_indexes( $base_model, $server_model, $server_splice );

		if ( is_wp_error( $text_changed ) || wp_de_rtc_rich_text_changed_indexes_overlap( $text_changed, $format_changed ) ) {
			return null;
		}

		$merged_model = wp_de_rtc_merge_rich_text_text_and_format_models( $server_model, $proposed_model, $server_splice, $format_changed );
	} else {
		$format_changed = wp_de_rtc_get_rich_text_changed_indexes( $base_model, $server_model );
		$text_changed   = wp_de_rtc_get_retained_rich_text_mark_changed_indexes( $base_model, $proposed_model, $proposed_splice );

		if ( is_wp_error( $text_changed ) || wp_de_rtc_rich_text_changed_indexes_overlap( $text_changed, $format_changed ) ) {
			return null;
		}

		$merged_model = wp_de_rtc_merge_rich_text_text_and_format_models( $proposed_model, $server_model, $proposed_splice, $format_changed );
	}

	if ( null === $merged_model ) {
		return null;
	}

	return array(
		'merged_block' => $base['open'] . wp_de_rtc_format_rich_text_model_html( $merged_model ) . $base['close'],
	);
	}

	/**
	 * Attempts a conservative table-cell merge for one serialized table block.
	 *
	 * Only cell inner HTML may differ. The table wrapper, row structure, cell
	 * tags, and cell attributes must match exactly, which keeps row/column
	 * edits, table settings changes, and same-cell edits out of this automatic
	 * path until the server has durable nested block identity.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param string $base_block     Accepted-base serialized block.
	 * @param string $server_block   Current server serialized block.
	 * @param string $proposed_block Client-proposed serialized block.
	 * @return array|null Merge result or null when the block must stay a conflict.
	 */
	function wp_de_rtc_get_table_cell_serialized_block_merge_candidate( $base_block, $server_block, $proposed_block ) {
		$base     = wp_de_rtc_get_table_cell_serialized_block_model( $base_block );
		$server   = wp_de_rtc_get_table_cell_serialized_block_model( $server_block );
		$proposed = wp_de_rtc_get_table_cell_serialized_block_model( $proposed_block );

		if ( ! $base || ! $server || ! $proposed ) {
			return null;
		}

		if (
			$base['shell'] !== $server['shell'] ||
			$base['shell'] !== $proposed['shell'] ||
			count( $base['cells'] ) !== count( $server['cells'] ) ||
			count( $base['cells'] ) !== count( $proposed['cells'] )
		) {
			return null;
		}

		$server_changed   = array();
		$proposed_changed = array();
		$cell_count       = count( $base['cells'] );

		for ( $index = 0; $index < $cell_count; $index++ ) {
			if ( $base['cells'][ $index ] !== $server['cells'][ $index ] ) {
				$server_changed[] = $index;
			}

			if ( $base['cells'][ $index ] !== $proposed['cells'][ $index ] ) {
				$proposed_changed[] = $index;
			}
		}

		if ( empty( $server_changed ) || empty( $proposed_changed ) ) {
			return null;
		}

		$server_changed_lookup = array_fill_keys( $server_changed, true );

		foreach ( $proposed_changed as $index ) {
			if ( isset( $server_changed_lookup[ $index ] ) && $server['cells'][ $index ] !== $proposed['cells'][ $index ] ) {
				return null;
			}
		}

		$merged_cells = $base['cells'];

		foreach ( $server_changed as $index ) {
			$merged_cells[ $index ] = $server['cells'][ $index ];
		}

		foreach ( $proposed_changed as $index ) {
			$merged_cells[ $index ] = $proposed['cells'][ $index ];
		}

		$merged_block = wp_de_rtc_render_table_cell_serialized_block_model( $base, $merged_cells );

		if ( null === $merged_block ) {
			return null;
		}

		return array(
			'merged_block'         => $merged_block,
			'server_changed_cells' => wp_de_rtc_get_table_cell_change_evidence( $base, $server_changed ),
			'local_changed_cells'  => wp_de_rtc_get_table_cell_change_evidence( $base, $proposed_changed ),
		);
	}

	/**
	 * Builds a serialized table block model with cell contents separated.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param string $block Serialized block.
	 * @return array|null Table-cell model or null when unsupported.
	 */
	function wp_de_rtc_get_table_cell_serialized_block_model( $block ) {
		if ( ! is_string( $block ) || false === strpos( $block, '<!-- wp:table' ) ) {
			return null;
		}

		$parsed_blocks = wp_de_rtc_remove_empty_freeform_blocks( parse_blocks( $block ) );

		if (
			1 !== count( $parsed_blocks ) ||
			! isset( $parsed_blocks[0]['blockName'] ) ||
			'core/table' !== $parsed_blocks[0]['blockName']
		) {
			return null;
		}

		$matched = preg_match_all(
			'/<(?P<tag>t[dh])\b(?P<attrs>[^>]*)>(?P<content>.*?)<\/(?P=tag)>/is',
			$block,
			$matches,
			PREG_SET_ORDER | PREG_OFFSET_CAPTURE
		);

		if ( false === $matched || 0 === $matched ) {
			return null;
		}

		$shell        = '';
		$cells        = array();
		$cell_offsets = array();
		$last_offset  = 0;

		foreach ( $matches as $match ) {
			$content        = $match['content'][0];
			$content_offset = (int) $match['content'][1];
			$content_length = strlen( $content );

			$shell          .= substr( $block, $last_offset, $content_offset - $last_offset ) . "\0DE_RTC_TABLE_CELL\0";
			$last_offset     = $content_offset + $content_length;
			$cells[]         = $content;
			$cell_offsets[]  = (int) $match[0][1];
		}

		$shell .= substr( $block, $last_offset );

		return array(
			'shell'       => $shell,
			'cells'       => $cells,
			'coordinates' => wp_de_rtc_get_table_cell_coordinates( $block, $cell_offsets ),
		);
	}

	/**
	 * Returns best-effort row and column coordinates for table-cell evidence.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param string $block        Serialized table block.
	 * @param int[]  $cell_offsets Absolute offsets of table cell start tags.
	 * @return array[] Cell coordinates keyed by flat cell index.
	 */
	function wp_de_rtc_get_table_cell_coordinates( $block, $cell_offsets ) {
		$coordinates = array();

		foreach ( $cell_offsets as $index => $offset ) {
			$coordinates[ $index ] = array(
				'cell_index'   => (int) $index,
				'row_index'    => null,
				'column_index' => null,
			);
		}

		$offset_to_index = array();

		foreach ( $cell_offsets as $index => $offset ) {
			$offset_to_index[ (int) $offset ] = (int) $index;
		}

		$matched_rows = preg_match_all( '/<tr\b[^>]*>.*?<\/tr>/is', $block, $rows, PREG_SET_ORDER | PREG_OFFSET_CAPTURE );

		if ( false === $matched_rows || 0 === $matched_rows ) {
			return $coordinates;
		}

		foreach ( $rows as $row_index => $row ) {
			$row_html   = $row[0][0];
			$row_offset = (int) $row[0][1];
			$matched_cells = preg_match_all( '/<t[dh]\b[^>]*>.*?<\/t[dh]>/is', $row_html, $row_cells, PREG_SET_ORDER | PREG_OFFSET_CAPTURE );

			if ( false === $matched_cells || 0 === $matched_cells ) {
				continue;
			}

			foreach ( $row_cells as $column_index => $cell ) {
				$absolute_offset = $row_offset + (int) $cell[0][1];

				if ( isset( $offset_to_index[ $absolute_offset ] ) ) {
					$cell_index = $offset_to_index[ $absolute_offset ];
					$coordinates[ $cell_index ]['row_index']    = (int) $row_index;
					$coordinates[ $cell_index ]['column_index'] = (int) $column_index;
				}
			}
		}

		return $coordinates;
	}

	/**
	 * Renders a serialized table block model with replacement cell contents.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param array    $model Table-cell model.
	 * @param string[] $cells Replacement cell contents.
	 * @return string|null Serialized block or null when malformed.
	 */
	function wp_de_rtc_render_table_cell_serialized_block_model( $model, $cells ) {
		if ( ! is_array( $model ) || ! isset( $model['shell'] ) || ! is_string( $model['shell'] ) || ! is_array( $cells ) ) {
			return null;
		}

		$parts = explode( "\0DE_RTC_TABLE_CELL\0", $model['shell'] );

		if ( count( $parts ) !== count( $cells ) + 1 ) {
			return null;
		}

		$block = '';

		foreach ( $cells as $index => $cell ) {
			$block .= $parts[ $index ] . $cell;
		}

		$block .= $parts[ count( $parts ) - 1 ];

		return $block;
	}

	/**
	 * Returns content-free table-cell merge evidence.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param array $model           Table-cell model.
	 * @param int[] $changed_indexes Changed flat cell indexes.
	 * @return array[] Cell coordinate evidence.
	 */
	function wp_de_rtc_get_table_cell_change_evidence( $model, $changed_indexes ) {
		$evidence = array();

		foreach ( $changed_indexes as $index ) {
			$index      = (int) $index;
			$coordinate = isset( $model['coordinates'][ $index ] ) && is_array( $model['coordinates'][ $index ] )
				? $model['coordinates'][ $index ]
				: array(
					'cell_index'   => $index,
					'row_index'    => null,
					'column_index' => null,
				);

			$evidence[] = array(
				'cell_index'   => isset( $coordinate['cell_index'] ) ? (int) $coordinate['cell_index'] : $index,
				'row_index'    => isset( $coordinate['row_index'] ) && null !== $coordinate['row_index'] ? (int) $coordinate['row_index'] : null,
				'column_index' => isset( $coordinate['column_index'] ) && null !== $coordinate['column_index'] ? (int) $coordinate['column_index'] : null,
			);
		}

		return $evidence;
	}

	/**
	 * Adds a top-level block index to table-cell evidence records.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param array[] $cells       Cell evidence.
	 * @param int     $block_index Top-level block index.
	 * @return array[] Indexed cell evidence.
	 */
	function wp_de_rtc_add_block_index_to_table_cell_evidence( $cells, $block_index ) {
		$indexed = array();

		foreach ( is_array( $cells ) ? $cells : array() as $cell ) {
			if ( ! is_array( $cell ) ) {
				continue;
			}

			$indexed[] = array(
				'block_index'  => (int) $block_index,
				'cell_index'   => isset( $cell['cell_index'] ) ? (int) $cell['cell_index'] : 0,
				'row_index'    => isset( $cell['row_index'] ) && null !== $cell['row_index'] ? (int) $cell['row_index'] : null,
				'column_index' => isset( $cell['column_index'] ) && null !== $cell['column_index'] ? (int) $cell['column_index'] : null,
			);
		}

		return $indexed;
	}

	/**
	 * Splits a serialized core/paragraph block into shell and rich-text HTML.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $block Serialized block.
 * @return array|null Paragraph parts or null when unsupported.
 */
function wp_de_rtc_get_paragraph_rich_text_block_parts( $block ) {
	if ( ! is_string( $block ) ) {
		return null;
	}

	$matched = preg_match( '/^(<!--\\s+wp:paragraph\\b[\\s\\S]*?-->\\s*<p\\b[^>]*>)([\\s\\S]*?)(<\\/p>\\s*<!--\\s+\\/wp:paragraph\\s+-->)$/i', $block, $matches );

	if ( 1 !== $matched ) {
		return null;
	}

	return array(
		'open'  => $matches[1],
		'html'  => $matches[2],
		'close' => $matches[3],
	);
}

/**
 * Builds a minimal rich-text mark model from paragraph inner HTML.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $html Paragraph inner HTML.
 * @return array|null Rich-text model or null for unsupported HTML.
 */
function wp_de_rtc_get_rich_text_format_model( $html ) {
	$tokens = preg_split( '/(<[^>]+>)/', (string) $html, -1, PREG_SPLIT_DELIM_CAPTURE | PREG_SPLIT_NO_EMPTY );

	if ( ! is_array( $tokens ) ) {
		return null;
	}

	$text         = '';
	$marks        = array();
	$active_marks = array();
	$offset       = 0;

	foreach ( $tokens as $token ) {
		if ( '' === $token ) {
			continue;
		}

		if ( '<' === $token[0] ) {
			$normalized = strtolower( preg_replace( '/\\s+/', '', $token ) );

			if ( in_array( $normalized, array( '<strong>', '<b>' ), true ) ) {
				$active_marks[] = 'strong';
				continue;
			}

			if ( in_array( $normalized, array( '</strong>', '</b>' ), true ) ) {
				if ( ! wp_de_rtc_pop_rich_text_active_mark( $active_marks, 'strong' ) ) {
					return null;
				}
				continue;
			}

			if ( in_array( $normalized, array( '<em>', '<i>' ), true ) ) {
				$active_marks[] = 'em';
				continue;
			}

			if ( in_array( $normalized, array( '</em>', '</i>' ), true ) ) {
				if ( ! wp_de_rtc_pop_rich_text_active_mark( $active_marks, 'em' ) ) {
					return null;
				}
				continue;
			}

			return null;
		}

		$decoded = html_entity_decode( $token, ENT_QUOTES | ENT_HTML5, 'UTF-8' );
		$chars   = wp_de_rtc_split_utf8_string( $decoded );
		foreach ( $chars as $char ) {
			$text .= $char;
			foreach ( $active_marks as $mark ) {
				$marks[] = array(
					'type'  => $mark,
					'start' => $offset,
					'end'   => $offset + 1,
				);
			}
			++$offset;
		}
	}

	if ( ! empty( $active_marks ) ) {
		return null;
	}

	return array(
		'text'  => $text,
		'marks' => wp_de_rtc_coalesce_rich_text_marks( $marks ),
	);
}

/**
 * Pops one active mark from the rich-text parser stack.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array  $active_marks Active mark stack.
 * @param string $mark         Mark to pop.
 * @return bool Whether the mark was popped.
 */
function wp_de_rtc_pop_rich_text_active_mark( &$active_marks, $mark ) {
	for ( $index = count( $active_marks ) - 1; $index >= 0; --$index ) {
		if ( $active_marks[ $index ] === $mark ) {
			array_splice( $active_marks, $index, 1 );
			return true;
		}
	}

	return false;
}

/**
 * Returns character indexes whose rich-text marks changed.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $base Base rich-text model.
 * @param array $next Candidate rich-text model.
 * @return int[] Changed character indexes.
 */
function wp_de_rtc_get_rich_text_changed_indexes( $base, $next ) {
	$changed = array();
	$chars   = wp_de_rtc_split_utf8_string( $base['text'] );
	$count   = count( $chars );

	for ( $index = 0; $index < $count; ++$index ) {
		foreach ( array( 'strong', 'em' ) as $mark ) {
			if (
				wp_de_rtc_rich_text_has_mark_at( $base, $mark, $index ) !==
				wp_de_rtc_rich_text_has_mark_at( $next, $mark, $index )
			) {
				$changed[ $index ] = $index;
			}
		}
	}

	return array_values( $changed );
}

/**
 * Returns whether two changed-index lists overlap.
 *
 * @since 7.1.0
 * @access private
 *
 * @param int[] $left  First changed indexes.
 * @param int[] $right Second changed indexes.
 * @return bool Whether they overlap.
 */
function wp_de_rtc_rich_text_changed_indexes_overlap( $left, $right ) {
	$right_lookup = array_fill_keys( array_map( 'intval', $right ), true );

	foreach ( $left as $index ) {
		if ( isset( $right_lookup[ (int) $index ] ) ) {
			return true;
		}
	}

	return false;
}

/**
 * Returns the single text splice between two rich-text plain text values.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $base_text Base visible text.
 * @param string $next_text Next visible text.
 * @return array Text splice evidence.
 */
function wp_de_rtc_get_rich_text_text_splice( $base_text, $next_text ) {
	if ( $base_text === $next_text ) {
		return array(
			'changed'      => false,
			'start'        => 0,
			'delete_count' => 0,
			'insert_text'  => '',
			'insert_count' => 0,
			'end'          => 0,
			'delta'        => 0,
		);
	}

	$base_chars = wp_de_rtc_split_utf8_string( $base_text );
	$next_chars = wp_de_rtc_split_utf8_string( $next_text );
	$base_count = count( $base_chars );
	$next_count = count( $next_chars );
	$prefix     = 0;

	while ( $prefix < $base_count && $prefix < $next_count && $base_chars[ $prefix ] === $next_chars[ $prefix ] ) {
		++$prefix;
	}

	$suffix = 0;
	while (
		$suffix < $base_count - $prefix &&
		$suffix < $next_count - $prefix &&
		$base_chars[ $base_count - 1 - $suffix ] === $next_chars[ $next_count - 1 - $suffix ]
	) {
		++$suffix;
	}

	$delete_count = $base_count - $prefix - $suffix;
	$insert_chars = array_slice( $next_chars, $prefix, $next_count - $prefix - $suffix );
	$insert_count = count( $insert_chars );

	return array(
		'changed'      => true,
		'start'        => $prefix,
		'delete_count' => $delete_count,
		'insert_text'  => implode( '', $insert_chars ),
		'insert_count' => $insert_count,
		'end'          => $prefix + $delete_count,
		'delta'        => $insert_count - $delete_count,
	);
}

/**
 * Formats PHP text-splice evidence into the client operation vocabulary.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $splice PHP text-splice evidence.
 * @return array Client-shaped text-splice evidence.
 */
function wp_de_rtc_format_rich_text_text_splice_for_client( $splice ) {
	return array(
		'changed'     => ! empty( $splice['changed'] ),
		'start'       => isset( $splice['start'] ) ? (int) $splice['start'] : 0,
		'deleteCount' => isset( $splice['delete_count'] ) ? (int) $splice['delete_count'] : 0,
		'insertText'  => isset( $splice['insert_text'] ) ? (string) $splice['insert_text'] : '',
		'insertCount' => isset( $splice['insert_count'] ) ? (int) $splice['insert_count'] : 0,
		'end'         => isset( $splice['end'] ) ? (int) $splice['end'] : 0,
		'delta'       => isset( $splice['delta'] ) ? (int) $splice['delta'] : 0,
	);
}

/**
 * Maps a retained base-text index through a text splice.
 *
 * @since 7.1.0
 * @access private
 *
 * @param int   $index  Base text index.
 * @param array $splice Text splice evidence.
 * @return int|null Target index, or null when the base character was deleted.
 */
function wp_de_rtc_transform_rich_text_base_index( $index, $splice ) {
	$index = (int) $index;

	if ( empty( $splice['changed'] ) ) {
		return $index;
	}

	$start        = (int) $splice['start'];
	$delete_count = (int) $splice['delete_count'];
	$end          = $start + $delete_count;

	if ( $index < $start ) {
		return $index;
	}

	if ( $index >= $end ) {
		return $index + (int) $splice['delta'];
	}

	return null;
}

/**
 * Returns mark changes on retained text after accounting for a text splice.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $base   Base rich-text model.
 * @param array $next   Text-changing rich-text model.
 * @param array $splice Text splice evidence.
 * @return int[]|WP_Error Base indexes whose marks changed on retained text.
 */
function wp_de_rtc_get_retained_rich_text_mark_changed_indexes( $base, $next, $splice ) {
	$changed    = array();
	$base_chars = wp_de_rtc_split_utf8_string( $base['text'] );
	$next_chars = wp_de_rtc_split_utf8_string( $next['text'] );
	$next_count = count( $next_chars );

	foreach ( $base_chars as $index => $char ) {
		$target_index = wp_de_rtc_transform_rich_text_base_index( $index, $splice );

		if ( null === $target_index ) {
			continue;
		}

		if ( $target_index < 0 || $target_index >= $next_count ) {
			return wp_de_rtc_get_reason_error(
				'de_rtc_rebase_failed',
				__( 'Distributed Editing could not map rich text marks through a text edit.' ),
				array(
					'detail' => 'rich_text_mark_index_transform_failed',
				)
			);
		}

		foreach ( array( 'strong', 'em' ) as $mark ) {
			if ( wp_de_rtc_rich_text_has_mark_at( $base, $mark, $index ) !== wp_de_rtc_rich_text_has_mark_at( $next, $mark, $target_index ) ) {
				$changed[ $index ] = $index;
			}
		}
	}

	return array_values( $changed );
}

/**
 * Applies format-only changes onto the model produced by a text edit.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $text_changed_model    Model from the text-changing side.
 * @param array $format_changed_model  Model from the format-only side.
 * @param array $text_splice           Text splice evidence for the text-changing side.
 * @param int[] $format_changed_indexes Base indexes changed by the format-only side.
 * @return array|null Merged model, or null when indexes cannot be transformed.
 */
function wp_de_rtc_merge_rich_text_text_and_format_models( $text_changed_model, $format_changed_model, $text_splice, $format_changed_indexes ) {
	$target_chars = wp_de_rtc_split_utf8_string( $text_changed_model['text'] );
	$target_count = count( $target_chars );
	$marks        = array();

	for ( $index = 0; $index < $target_count; ++$index ) {
		foreach ( array( 'strong', 'em' ) as $mark ) {
			if ( wp_de_rtc_rich_text_has_mark_at( $text_changed_model, $mark, $index ) ) {
				$marks[ $index ][ $mark ] = true;
			}
		}
	}

	foreach ( $format_changed_indexes as $base_index ) {
		$target_index = wp_de_rtc_transform_rich_text_base_index( $base_index, $text_splice );

		if ( null === $target_index || $target_index < 0 || $target_index >= $target_count ) {
			return null;
		}

		foreach ( array( 'strong', 'em' ) as $mark ) {
			if ( wp_de_rtc_rich_text_has_mark_at( $format_changed_model, $mark, (int) $base_index ) ) {
				$marks[ $target_index ][ $mark ] = true;
			} elseif ( isset( $marks[ $target_index ][ $mark ] ) ) {
				unset( $marks[ $target_index ][ $mark ] );
			}
		}
	}

	$merged_marks = array();

	for ( $index = 0; $index < $target_count; ++$index ) {
		foreach ( array( 'strong', 'em' ) as $mark ) {
			if ( ! empty( $marks[ $index ][ $mark ] ) ) {
				$merged_marks[] = array(
					'type'  => $mark,
					'start' => $index,
					'end'   => $index + 1,
				);
			}
		}
	}

	return array(
		'text'  => $text_changed_model['text'],
		'marks' => wp_de_rtc_coalesce_rich_text_marks( $merged_marks ),
	);
}

/**
 * Merges two disjoint paragraph text splices against the same base model.
 *
 * This intentionally stays conservative. It only accepts two independently
 * mapped text edits when their base text ranges do not overlap; same-position
 * competing insertions remain a manual conflict until the product has an
 * explicit ordering policy.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $base             Accepted-base rich-text model.
 * @param array $server           Current-server rich-text model.
 * @param array $server_splice    Server text-splice evidence.
 * @param array $proposed         Client-proposed rich-text model.
 * @param array $proposed_splice  Client-proposed text-splice evidence.
 * @return array|null Merged rich-text model, or null when unsafe to merge.
 */
function wp_de_rtc_merge_rich_text_text_splice_models( $base, $server, $server_splice, $proposed, $proposed_splice ) {
	if ( wp_de_rtc_rich_text_text_splices_conflict( $server_splice, $proposed_splice ) ) {
		return null;
	}

	$server_mark_changed = wp_de_rtc_get_retained_rich_text_mark_changed_indexes( $base, $server, $server_splice );
	$proposed_mark_changed = wp_de_rtc_get_retained_rich_text_mark_changed_indexes( $base, $proposed, $proposed_splice );

	if (
		is_wp_error( $server_mark_changed ) ||
		is_wp_error( $proposed_mark_changed ) ||
		wp_de_rtc_rich_text_changed_indexes_overlap( $server_mark_changed, $proposed_mark_changed ) ||
		wp_de_rtc_rich_text_changed_indexes_touch_splice( $server_mark_changed, $proposed_splice ) ||
		wp_de_rtc_rich_text_changed_indexes_touch_splice( $proposed_mark_changed, $server_splice )
	) {
		return null;
	}

	$server_mark_lookup   = array_fill_keys( array_map( 'intval', $server_mark_changed ), true );
	$proposed_mark_lookup = array_fill_keys( array_map( 'intval', $proposed_mark_changed ), true );
	$base_chars           = wp_de_rtc_split_utf8_string( $base['text'] );
	$splices              = array(
		array(
			'kind'   => 'server',
			'model'  => $server,
			'splice' => $server_splice,
		),
		array(
			'kind'   => 'proposed',
			'model'  => $proposed,
			'splice' => $proposed_splice,
		),
	);

	usort(
		$splices,
		static function ( $left, $right ) {
			$left_start  = (int) $left['splice']['start'];
			$right_start = (int) $right['splice']['start'];

			if ( $left_start === $right_start ) {
				return (int) $left['splice']['end'] <=> (int) $right['splice']['end'];
			}

			return $left_start <=> $right_start;
		}
	);

	$sources = array();
	$cursor  = 0;

	foreach ( $splices as $entry ) {
		$splice = $entry['splice'];
		$start  = (int) $splice['start'];
		$end    = (int) $splice['end'];

		for ( ; $cursor < $start; ++$cursor ) {
			$sources[] = array(
				'kind'       => 'base',
				'base_index' => $cursor,
			);
		}

		$insert_count = (int) $splice['insert_count'];
		for ( $offset = 0; $offset < $insert_count; ++$offset ) {
			$sources[] = array(
				'kind'        => $entry['kind'],
				'model'       => $entry['model'],
				'model_index' => $start + $offset,
			);
		}

		$cursor = $end;
	}

	for ( $count = count( $base_chars ); $cursor < $count; ++$cursor ) {
		$sources[] = array(
			'kind'       => 'base',
			'base_index' => $cursor,
		);
	}

	$chars = array();
	$marks = array();

	foreach ( $sources as $target_index => $source ) {
		if ( 'base' === $source['kind'] ) {
			$base_index = (int) $source['base_index'];
			$chars[]    = $base_chars[ $base_index ];

			foreach ( array( 'strong', 'em' ) as $mark ) {
				if ( isset( $proposed_mark_lookup[ $base_index ] ) ) {
					$marked = wp_de_rtc_rich_text_has_mark_at_transformed_index( $proposed, $mark, $base_index, $proposed_splice );
				} elseif ( isset( $server_mark_lookup[ $base_index ] ) ) {
					$marked = wp_de_rtc_rich_text_has_mark_at_transformed_index( $server, $mark, $base_index, $server_splice );
				} else {
					$marked = wp_de_rtc_rich_text_has_mark_at( $base, $mark, $base_index );
				}

				if ( null === $marked ) {
					return null;
				}

				if ( $marked ) {
					$marks[] = array(
						'type'  => $mark,
						'start' => $target_index,
						'end'   => $target_index + 1,
					);
				}
			}

			continue;
		}

		$model       = $source['model'];
		$model_index = (int) $source['model_index'];
		$model_chars = wp_de_rtc_split_utf8_string( $model['text'] );

		if ( ! isset( $model_chars[ $model_index ] ) ) {
			return null;
		}

		$chars[] = $model_chars[ $model_index ];

		foreach ( array( 'strong', 'em' ) as $mark ) {
			if ( wp_de_rtc_rich_text_has_mark_at( $model, $mark, $model_index ) ) {
				$marks[] = array(
					'type'  => $mark,
					'start' => $target_index,
					'end'   => $target_index + 1,
				);
			}
		}
	}

	return array(
		'text'  => implode( '', $chars ),
		'marks' => wp_de_rtc_coalesce_rich_text_marks( $marks ),
	);
}

/**
 * Returns whether two base-relative rich-text splices must remain a conflict.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $left  First text-splice evidence.
 * @param array $right Second text-splice evidence.
 * @return bool Whether the splices conflict.
 */
function wp_de_rtc_rich_text_text_splices_conflict( $left, $right ) {
	$left_start  = (int) $left['start'];
	$left_end    = (int) $left['end'];
	$right_start = (int) $right['start'];
	$right_end   = (int) $right['end'];

	if ( $left_start < $right_end && $right_start < $left_end ) {
		return true;
	}

	return (
		0 === (int) $left['delete_count'] &&
		0 === (int) $right['delete_count'] &&
		$left_start === $right_start &&
		! empty( $left['insert_text'] ) &&
		! empty( $right['insert_text'] )
	);
}

/**
 * Returns whether changed retained indexes touch a deleted/replaced splice range.
 *
 * @since 7.1.0
 * @access private
 *
 * @param int[] $indexes Changed base indexes.
 * @param array $splice  Text-splice evidence.
 * @return bool Whether any index touches the splice replacement range.
 */
function wp_de_rtc_rich_text_changed_indexes_touch_splice( $indexes, $splice ) {
	$start = (int) $splice['start'];
	$end   = (int) $splice['end'];

	foreach ( $indexes as $index ) {
		$index = (int) $index;
		if ( $start <= $index && $index < $end ) {
			return true;
		}
	}

	return false;
}

/**
 * Reads mark state for a retained base index after a text splice.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array  $model      Text-spliced rich-text model.
 * @param string $mark       Mark type.
 * @param int    $base_index Base text index.
 * @param array  $splice     Text-splice evidence.
 * @return bool|null Mark state, or null when the index cannot be mapped.
 */
function wp_de_rtc_rich_text_has_mark_at_transformed_index( $model, $mark, $base_index, $splice ) {
	$target_index = wp_de_rtc_transform_rich_text_base_index( $base_index, $splice );

	if ( null === $target_index ) {
		return null;
	}

	return wp_de_rtc_rich_text_has_mark_at( $model, $mark, $target_index );
}

/**
 * Merges disjoint rich-text mark changes.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $base             Base rich-text model.
 * @param array $server           Server rich-text model.
 * @param int[] $server_changed   Server changed indexes.
 * @param array $proposed         Proposed rich-text model.
 * @param int[] $proposed_changed Proposed changed indexes.
 * @return array Merged rich-text model.
 */
function wp_de_rtc_merge_rich_text_format_models( $base, $server, $server_changed, $proposed, $proposed_changed ) {
	$server_lookup   = array_fill_keys( array_map( 'intval', $server_changed ), true );
	$proposed_lookup = array_fill_keys( array_map( 'intval', $proposed_changed ), true );
	$chars           = wp_de_rtc_split_utf8_string( $base['text'] );
	$marks           = array();

	foreach ( $chars as $index => $char ) {
		foreach ( array( 'strong', 'em' ) as $mark ) {
			if ( isset( $proposed_lookup[ $index ] ) ) {
				$marked = wp_de_rtc_rich_text_has_mark_at( $proposed, $mark, $index );
			} elseif ( isset( $server_lookup[ $index ] ) ) {
				$marked = wp_de_rtc_rich_text_has_mark_at( $server, $mark, $index );
			} else {
				$marked = wp_de_rtc_rich_text_has_mark_at( $base, $mark, $index );
			}

			if ( $marked ) {
				$marks[] = array(
					'type'  => $mark,
					'start' => $index,
					'end'   => $index + 1,
				);
			}
		}
	}

	return array(
		'text'  => $base['text'],
		'marks' => wp_de_rtc_coalesce_rich_text_marks( $marks ),
	);
}

/**
 * Returns whether a rich-text model has a mark at a character index.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array  $model Rich-text model.
 * @param string $mark  Mark type.
 * @param int    $index Character index.
 * @return bool Whether the mark is active.
 */
function wp_de_rtc_rich_text_has_mark_at( $model, $mark, $index ) {
	foreach ( $model['marks'] as $range ) {
		if ( $range['type'] === $mark && $range['start'] <= $index && $index < $range['end'] ) {
			return true;
		}
	}

	return false;
}

/**
 * Coalesces adjacent rich-text marks of the same type.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $marks Mark ranges.
 * @return array Coalesced mark ranges.
 */
function wp_de_rtc_coalesce_rich_text_marks( $marks ) {
	usort(
		$marks,
		static function ( $a, $b ) {
			if ( $a['type'] === $b['type'] ) {
				if ( $a['start'] === $b['start'] ) {
					return $a['end'] <=> $b['end'];
				}
				return $a['start'] <=> $b['start'];
			}
			return strcmp( $a['type'], $b['type'] );
		}
	);

	$coalesced = array();

	foreach ( $marks as $mark ) {
		$last_index = count( $coalesced ) - 1;
		if ( $last_index >= 0 && $coalesced[ $last_index ]['type'] === $mark['type'] && $coalesced[ $last_index ]['end'] === $mark['start'] ) {
			$coalesced[ $last_index ]['end'] = $mark['end'];
		} else {
			$coalesced[] = $mark;
		}
	}

	return $coalesced;
}

/**
 * Serializes a rich-text model into paragraph inner HTML.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $model Rich-text model.
 * @return string Serialized HTML.
 */
function wp_de_rtc_format_rich_text_model_html( $model ) {
	$events = array();

	foreach ( $model['marks'] as $mark ) {
		$start = (int) $mark['start'];
		$end   = (int) $mark['end'];

		if ( ! isset( $events[ $start ] ) ) {
			$events[ $start ] = array(
				'open'  => array(),
				'close' => array(),
			);
		}
		if ( ! isset( $events[ $end ] ) ) {
			$events[ $end ] = array(
				'open'  => array(),
				'close' => array(),
			);
		}

		$events[ $start ]['open'][]  = $mark['type'];
		$events[ $end ]['close'][] = $mark['type'];
	}

	$chars = wp_de_rtc_split_utf8_string( $model['text'] );
	$html  = '';
	$count = count( $chars );

	for ( $index = 0; $index <= $count; ++$index ) {
		if ( isset( $events[ $index ] ) ) {
			sort( $events[ $index ]['open'] );
			rsort( $events[ $index ]['close'] );

			foreach ( $events[ $index ]['close'] as $mark ) {
				$html .= '</' . $mark . '>';
			}
			foreach ( $events[ $index ]['open'] as $mark ) {
				$html .= '<' . $mark . '>';
			}
		}

		if ( $index < $count ) {
			$html .= esc_html( $chars[ $index ] );
		}
	}

	return $html;
}

/**
 * Attempts a conservative server-side merge across top-level serialized blocks.
 *
 * This helper is intentionally narrow: it only merges same-count top-level
 * serialized block edits, a strict one-sided edge insertion where the
 * inserting side's existing blocks still match the accepted base, or a strict
 * one-sided deletion where the retained blocks still match the accepted base
 * and the other side did not edit the deleted blocks. Anything else becomes a
 * conflict for the editor.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $base_content     Stripped post content for the accepted proof version.
 * @param string $server_content   Current stripped server post content.
 * @param string $proposed_content Client-proposed stripped post content.
 * @param array  $args             Optional merge evidence.
 * @return array|WP_Error Merge result, or conflict error.
 */
function wp_de_rtc_get_serialized_block_server_merge_result( $base_content, $server_content, $proposed_content, $args = array() ) {
	$base_records     = wp_de_rtc_get_top_level_serialized_block_records( $base_content );
	$server_records   = wp_de_rtc_get_top_level_serialized_block_records( $server_content );
	$proposed_records = wp_de_rtc_get_top_level_serialized_block_records( $proposed_content );

	foreach ( array( $base_records, $server_records, $proposed_records ) as $record_set ) {
		if ( is_wp_error( $record_set ) ) {
			return $record_set;
		}
	}

	$base_count           = count( $base_records );
	$server_count         = count( $server_records );
	$proposed_count       = count( $proposed_records );
	$edge_insert_source   = null;
	$edge_insert_position = null;
	$edge_inserted_blocks = array();
	$server_base_offset   = 0;
	$local_base_offset    = 0;
	$merged_index_offset  = 0;

	if ( 0 === $base_count ) {
		return wp_de_rtc_get_server_merge_conflict_error(
			'top_level_serialized_block_count_changed',
			array(
				'base_block_count'           => $base_count,
				'server_block_count'         => $server_count,
				'proposed_block_count'       => $proposed_count,
				'server_block_count_changed' => $base_count !== $server_count,
				'local_block_count_changed'  => $base_count !== $proposed_count,
				'server_block_count_delta'   => $server_count - $base_count,
				'local_block_count_delta'    => $proposed_count - $base_count,
			)
		);
	}

	if ( $base_count !== $server_count || $base_count !== $proposed_count ) {
		$server_deleted = $server_count < $base_count && $proposed_count === $base_count;
		$local_deleted  = $proposed_count < $base_count && $server_count === $base_count;

		if ( $server_deleted || $local_deleted ) {
			return wp_de_rtc_get_serialized_block_deletion_merge_result(
				$base_records,
				$server_records,
				$proposed_records,
				$base_content,
				$server_content,
				$proposed_content,
				$args
			);
		}

		$server_edge_inserted = $server_count > $base_count && $proposed_count === $base_count;
		$local_edge_inserted  = $proposed_count > $base_count && $server_count === $base_count;

		if ( $server_edge_inserted || $local_edge_inserted ) {
			$edge_insert_records = $server_edge_inserted ? $server_records : $proposed_records;
			$edge_insert         = wp_de_rtc_get_serialized_block_edge_insertion( $base_records, $edge_insert_records );

			if ( null !== $edge_insert ) {
				$edge_insert_source   = $server_edge_inserted ? 'server' : 'local';
				$edge_insert_position = $edge_insert['position'];
				$edge_inserted_blocks = $edge_insert['blocks'];

				if ( 'ambiguous' === $edge_insert_position ) {
					return wp_de_rtc_get_server_merge_conflict_error(
						'ambiguous_edge_insertion',
						array(
							'base_block_count'           => $base_count,
							'server_block_count'         => $server_count,
							'proposed_block_count'       => $proposed_count,
							'server_block_count_changed' => $base_count !== $server_count,
							'local_block_count_changed'  => $base_count !== $proposed_count,
							'server_block_count_delta'   => $server_count - $base_count,
							'local_block_count_delta'    => $proposed_count - $base_count,
							'edge_insert_source'         => $edge_insert_source,
							'edge_insert_position'       => $edge_insert_position,
							'edge_insert_ambiguous'      => true,
						)
					);
				}
			}
		}

		if ( null === $edge_insert_source ) {
			return wp_de_rtc_get_server_merge_conflict_error(
				'top_level_serialized_block_count_changed',
				array(
					'base_block_count'           => $base_count,
					'server_block_count'         => $server_count,
					'proposed_block_count'       => $proposed_count,
					'server_block_count_changed' => $base_count !== $server_count,
					'local_block_count_changed'  => $base_count !== $proposed_count,
					'server_block_count_delta'   => $server_count - $base_count,
					'local_block_count_delta'    => $proposed_count - $base_count,
				)
			);
		}

		if ( 'prepend' === $edge_insert_position ) {
			$merged_index_offset = count( $edge_inserted_blocks );

			if ( 'server' === $edge_insert_source ) {
				$server_base_offset = $merged_index_offset;
			} else {
				$local_base_offset = $merged_index_offset;
			}
		}
	}

	if ( $base_count === $server_count && $base_count === $proposed_count ) {
		$server_reordered_indexes = wp_de_rtc_get_reordered_serialized_block_indexes( $base_records, $server_records );
		$local_reordered_indexes  = wp_de_rtc_get_reordered_serialized_block_indexes( $base_records, $proposed_records );

		if ( ! empty( $server_reordered_indexes ) || ! empty( $local_reordered_indexes ) ) {
			return wp_de_rtc_get_server_merge_conflict_error(
				'top_level_serialized_block_reordered',
				array(
					'base_block_count'              => $base_count,
					'server_block_count'            => $server_count,
					'proposed_block_count'          => $proposed_count,
					'server_block_count_changed'    => false,
					'local_block_count_changed'     => false,
					'server_block_count_delta'      => 0,
					'local_block_count_delta'       => 0,
					'server_block_order_changed'    => ! empty( $server_reordered_indexes ),
					'local_block_order_changed'     => ! empty( $local_reordered_indexes ),
					'server_reordered_block_indexes' => $server_reordered_indexes,
					'local_reordered_block_indexes' => $local_reordered_indexes,
				)
			);
		}
	}

	$merged_blocks            = array();
	$server_changed_indexes   = array();
	$local_changed_indexes    = array();
		$conflicting_indexes      = array();
		$conflicting_block_hashes = array();
		$rich_text_merged_indexes = array();
		$table_cell_merged_indexes = array();
		$table_cell_server_changed_cells = array();
		$table_cell_local_changed_cells  = array();

	if ( 'prepend' === $edge_insert_position && ! empty( $edge_inserted_blocks ) ) {
		foreach ( $edge_inserted_blocks as $offset => $edge_inserted_block ) {
			if ( 'server' === $edge_insert_source ) {
				$server_changed_indexes[] = $offset;
			} else {
				$local_changed_indexes[] = $offset;
			}

			$merged_blocks[] = $edge_inserted_block;
		}
	}

	for ( $index = 0; $index < $base_count; $index++ ) {
		$base_block     = $base_records[ $index ];
		$server_block   = $server_records[ $index + $server_base_offset ];
		$proposed_block = $proposed_records[ $index + $local_base_offset ];
		$merged_index   = $index + $merged_index_offset;
		$server_changed = ! hash_equals( $base_block, $server_block );
		$local_changed  = ! hash_equals( $base_block, $proposed_block );

		if ( $server_changed ) {
			$server_changed_indexes[] = $merged_index;
		}

		if ( $local_changed ) {
			$local_changed_indexes[] = $merged_index;
		}

			if ( $server_changed && $local_changed && ! hash_equals( $server_block, $proposed_block ) ) {
				$rich_text_merge = wp_de_rtc_get_rich_text_serialized_block_merge_candidate( $base_block, $server_block, $proposed_block );

				if ( is_array( $rich_text_merge ) && ! empty( $rich_text_merge['merged_block'] ) ) {
					$merged_blocks[]            = $rich_text_merge['merged_block'];
					$rich_text_merged_indexes[] = $merged_index;
					continue;
				}

				$table_cell_merge = wp_de_rtc_get_table_cell_serialized_block_merge_candidate( $base_block, $server_block, $proposed_block );

				if ( is_array( $table_cell_merge ) && ! empty( $table_cell_merge['merged_block'] ) ) {
					$merged_blocks[]              = $table_cell_merge['merged_block'];
					$table_cell_merged_indexes[]  = $merged_index;
					$table_cell_server_changed_cells = array_merge(
						$table_cell_server_changed_cells,
						wp_de_rtc_add_block_index_to_table_cell_evidence( $table_cell_merge['server_changed_cells'], $merged_index )
					);
					$table_cell_local_changed_cells = array_merge(
						$table_cell_local_changed_cells,
						wp_de_rtc_add_block_index_to_table_cell_evidence( $table_cell_merge['local_changed_cells'], $merged_index )
					);
					continue;
				}

				$conflicting_indexes[] = $merged_index;
				$conflicting_block_hashes[] = array(
				'block_index'         => $merged_index,
				'base_block_hash'     => wp_de_rtc_hash_content( $base_block ),
				'server_block_hash'   => wp_de_rtc_hash_content( $server_block ),
				'proposed_block_hash' => wp_de_rtc_hash_content( $proposed_block ),
			);
		}

		$merged_blocks[] = $local_changed ? $proposed_block : $server_block;
	}

	if ( ! empty( $conflicting_indexes ) ) {
		return wp_de_rtc_get_server_merge_conflict_error(
			'same_serialized_block_changed',
			array(
				'conflicting_block_index'    => (int) $conflicting_indexes[0],
				'conflicting_block_indexes'  => array_map( 'intval', $conflicting_indexes ),
				'conflicting_block_count'    => count( $conflicting_indexes ),
				'server_changed_indexes'     => $server_changed_indexes,
				'local_changed_indexes'      => $local_changed_indexes,
				'server_changed_block_count' => count( $server_changed_indexes ),
				'local_changed_block_count'  => count( $local_changed_indexes ),
				'conflicting_block_hashes'   => $conflicting_block_hashes,
			)
		);
	}

	if ( 'append' === $edge_insert_position && ! empty( $edge_inserted_blocks ) ) {
		foreach ( $edge_inserted_blocks as $offset => $appended_block ) {
			$appended_index = $base_count + $offset;

			if ( 'server' === $edge_insert_source ) {
				$server_changed_indexes[] = $appended_index;
			} else {
				$local_changed_indexes[] = $appended_index;
			}

			$merged_blocks[] = $appended_block;
		}
	}

	$merged_content = implode( '', $merged_blocks );
	$merged_count   = count( $merged_blocks );

	return array(
		'merge_status'                 => 'merged',
		'merge_strategy'               => 'top_level_serialized_block_three_way',
		'base_version'                 => isset( $args['base_version'] ) ? sanitize_text_field( (string) $args['base_version'] ) : null,
		'server_version'               => isset( $args['server_version'] ) ? sanitize_text_field( (string) $args['server_version'] ) : null,
		'base_revision_id'             => isset( $args['base_revision_id'] ) ? (int) $args['base_revision_id'] : 0,
		'block_count'                  => $merged_count,
		'base_block_count'             => $base_count,
		'server_block_count'           => $server_count,
		'proposed_block_count'         => $proposed_count,
		'merged_block_count'           => $merged_count,
		'edge_insert_source'           => $edge_insert_source,
		'edge_insert_position'         => $edge_insert_position,
		'edge_inserted_block_count'    => count( $edge_inserted_blocks ),
		'append_source'                => 'append' === $edge_insert_position ? $edge_insert_source : null,
		'appended_block_count'         => 'append' === $edge_insert_position ? count( $edge_inserted_blocks ) : 0,
		'prepend_source'               => 'prepend' === $edge_insert_position ? $edge_insert_source : null,
		'prepended_block_count'        => 'prepend' === $edge_insert_position ? count( $edge_inserted_blocks ) : 0,
		'server_changed_indexes'       => $server_changed_indexes,
			'local_changed_indexes'        => $local_changed_indexes,
			'rich_text_merged_indexes'     => array_map( 'intval', $rich_text_merged_indexes ),
			'rich_text_merged_block_count' => count( $rich_text_merged_indexes ),
			'table_cell_merged_indexes'    => array_map( 'intval', $table_cell_merged_indexes ),
			'table_cell_merged_block_count' => count( $table_cell_merged_indexes ),
			'table_cell_server_changed_cells' => $table_cell_server_changed_cells,
			'table_cell_local_changed_cells' => $table_cell_local_changed_cells,
			'server_changed_block_count'   => count( $server_changed_indexes ),
		'local_changed_block_count'    => count( $local_changed_indexes ),
		'merged_content'               => $merged_content,
		'merged_stripped_content_hash' => wp_de_rtc_hash_content( $merged_content ),
		'base_content_hash'            => wp_de_rtc_hash_content( $base_content ),
		'server_content_hash'          => wp_de_rtc_hash_content( $server_content ),
		'proposed_content_hash'        => wp_de_rtc_hash_content( $proposed_content ),
	);
}

/**
 * Returns a proof-backed block identity merge for a newer server body.
 *
 * This intentionally does not merge arbitrary changed bodies. It lets a stale
 * retry-save use a validated identity request proof when the current server
 * content and identity map still match the accepted-base revision, or when the
 * current server identity map proves server-only insertions in gaps different
 * from the client's identity-proven insertions.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $base_content                            Stripped post content for the accepted proof version.
 * @param string $server_content                          Current stripped server post content.
 * @param string $proposed_content                        Client-proposed stripped post content.
 * @param mixed  $block_identity_request_proof            Request proof candidate.
 * @param array  $block_identity_request_proof_validation Validated proof evidence.
 * @param array  $args                                    Optional merge evidence.
 * @return array|WP_Error Merge result, or conflict error.
 */
function wp_de_rtc_get_block_identity_server_merge_result( $base_content, $server_content, $proposed_content, $block_identity_request_proof, $block_identity_request_proof_validation, $args = array() ) {
	$base_records     = wp_de_rtc_get_top_level_serialized_block_records( $base_content );
	$server_records   = wp_de_rtc_get_top_level_serialized_block_records( $server_content );
	$proposed_records = wp_de_rtc_get_top_level_serialized_block_records( $proposed_content );

	foreach ( array( $base_records, $server_records, $proposed_records ) as $record_set ) {
		if ( is_wp_error( $record_set ) ) {
			return $record_set;
		}
	}

	$base_count     = count( $base_records );
	$server_count   = count( $server_records );
	$proposed_count = count( $proposed_records );

	$proof_map_check = wp_de_rtc_validate_block_identity_request_proof_matches_proposed_content(
		$block_identity_request_proof,
		isset( $args['base_sync_meta'] ) ? $args['base_sync_meta'] : null,
		$proposed_records
	);

	if ( is_wp_error( $proof_map_check ) ) {
		return $proof_map_check;
	}

	if (
		! is_array( $block_identity_request_proof_validation ) ||
		! isset( $block_identity_request_proof_validation['proposed_block_count'] ) ||
		(int) $block_identity_request_proof_validation['proposed_block_count'] !== $proposed_count
	) {
		return wp_de_rtc_get_server_merge_conflict_error(
			'block_identity_proof_content_mismatch',
			array(
				'server_merge_strategy' => 'top_level_serialized_block_identity_map',
				'base_block_count'      => $base_count,
				'server_block_count'    => $server_count,
				'proposed_block_count'  => $proposed_count,
			)
		);
	}

	if (
		! hash_equals( $base_content, $server_content ) ||
		! wp_de_rtc_block_identity_sync_meta_stable_map_matches(
			isset( $args['base_sync_meta'] ) ? $args['base_sync_meta'] : null,
			isset( $args['current_sync_meta'] ) ? $args['current_sync_meta'] : null
		)
	) {
		if (
			$base_count === $server_count &&
			$base_count === $proposed_count &&
			isset( $block_identity_request_proof_validation['inserted_block_count'], $block_identity_request_proof_validation['deleted_block_count'], $block_identity_request_proof_validation['moved_block_count'] ) &&
			0 === (int) $block_identity_request_proof_validation['inserted_block_count'] &&
			0 === (int) $block_identity_request_proof_validation['deleted_block_count'] &&
			0 === (int) $block_identity_request_proof_validation['moved_block_count']
		) {
			return wp_de_rtc_get_block_identity_retained_edits_server_merge_result(
				$base_records,
				$server_records,
				$proposed_records,
				$base_content,
				$server_content,
				$proposed_content,
				$block_identity_request_proof,
				$block_identity_request_proof_validation,
				$args
			);
		}

		return wp_de_rtc_get_block_identity_insertions_only_server_merge_result(
			$base_records,
			$server_records,
			$proposed_records,
			$base_content,
			$server_content,
			$proposed_content,
			$block_identity_request_proof,
			$block_identity_request_proof_validation,
			$args
		);
	}

	if ( ! empty( $proof_map_check['retained_block_changed_indexes'] ) ) {
		return wp_de_rtc_get_server_merge_conflict_error(
			'block_identity_retained_block_changed',
			array(
				'server_merge_strategy' => 'top_level_serialized_block_identity_map',
				'block_index'           => (int) $proof_map_check['retained_block_changed_indexes'][0],
			)
		);
	}

	$local_changed_indexes = $proof_map_check['inserted_block_indexes'];

	return array(
		'merge_status'                        => 'merged',
		'merge_strategy'                      => 'top_level_serialized_block_identity_map',
		'base_version'                        => isset( $args['base_version'] ) ? sanitize_text_field( (string) $args['base_version'] ) : null,
		'server_version'                      => isset( $args['server_version'] ) ? sanitize_text_field( (string) $args['server_version'] ) : null,
		'base_revision_id'                    => isset( $args['base_revision_id'] ) ? (int) $args['base_revision_id'] : 0,
		'block_count'                         => $proposed_count,
		'base_block_count'                    => $base_count,
		'server_block_count'                  => $server_count,
		'proposed_block_count'                => $proposed_count,
		'merged_block_count'                  => $proposed_count,
		'edge_insert_source'                  => null,
		'edge_insert_position'                => null,
		'edge_inserted_block_count'           => 0,
		'append_source'                       => null,
		'appended_block_count'                => 0,
		'prepend_source'                      => null,
		'prepended_block_count'               => 0,
		'server_changed_indexes'              => array(),
		'local_changed_indexes'               => $local_changed_indexes,
		'server_changed_block_count'          => 0,
		'local_changed_block_count'           => count( $local_changed_indexes ),
		'block_identity_base_current_match'   => true,
		'block_identity_base_current_insertions_only' => false,
		'block_identity_inserted_indexes'     => $proof_map_check['inserted_block_indexes'],
		'block_identity_inserted_block_count' => $block_identity_request_proof_validation['inserted_block_count'],
		'block_identity_server_inserted_indexes' => array(),
		'block_identity_server_inserted_block_count' => 0,
		'block_identity_moved_block_count'    => $block_identity_request_proof_validation['moved_block_count'],
		'merged_content'                      => $proposed_content,
		'merged_stripped_content_hash'        => wp_de_rtc_hash_content( $proposed_content ),
		'base_content_hash'                   => wp_de_rtc_hash_content( $base_content ),
		'server_content_hash'                 => wp_de_rtc_hash_content( $server_content ),
		'proposed_content_hash'               => wp_de_rtc_hash_content( $proposed_content ),
	);
}

/**
 * Returns a proof-backed block identity merge for retained block edits.
 *
 * This helper accepts only same-count, same-order retained block edits. A
 * server edit to one retained block and a local edit to a different retained
 * block can merge. Competing edits to the same retained block require manual
 * resolution.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string[] $base_records                           Accepted-base serialized block records.
 * @param string[] $server_records                         Current server serialized block records.
 * @param string[] $proposed_records                       Client-proposed serialized block records.
 * @param string   $base_content                           Stripped post content for the accepted proof version.
 * @param string   $server_content                         Current stripped server post content.
 * @param string   $proposed_content                       Client-proposed stripped post content.
 * @param mixed    $block_identity_request_proof           Request proof candidate.
 * @param array    $block_identity_request_proof_validation Validated proof evidence.
 * @param array    $args                                   Optional merge evidence.
 * @return array|WP_Error Merge result, or conflict error.
 */
function wp_de_rtc_get_block_identity_retained_edits_server_merge_result( $base_records, $server_records, $proposed_records, $base_content, $server_content, $proposed_content, $block_identity_request_proof, $block_identity_request_proof_validation, $args ) {
	$base_sync_meta    = isset( $args['base_sync_meta'] ) ? $args['base_sync_meta'] : null;
	$current_sync_meta = isset( $args['current_sync_meta'] ) ? $args['current_sync_meta'] : null;
	$base_sequence     = wp_de_rtc_get_block_identity_base_sequence_for_merge( $base_sync_meta, $base_records );

	if ( is_wp_error( $base_sequence ) ) {
		return $base_sequence;
	}

	$server_sequence = wp_de_rtc_get_block_identity_current_sequence_for_merge(
		$current_sync_meta,
		$base_sequence,
		$server_records,
		$proposed_records,
		$server_content,
		array(
			'allow_retained_block_edits' => true,
		)
	);

	if ( is_wp_error( $server_sequence ) ) {
		return $server_sequence;
	}

	$proposed_sequence = wp_de_rtc_get_block_identity_proposed_sequence_for_merge(
		$block_identity_request_proof,
		$base_sequence,
		$proposed_records,
		$server_records,
		array(
			'allow_retained_block_edits' => true,
		)
	);

	if ( is_wp_error( $proposed_sequence ) ) {
		return $proposed_sequence;
	}

	$merged_blocks             = array();
		$merged_block_map          = array();
		$server_changed_indexes    = array();
		$local_changed_indexes     = array();
		$retained_edit_indexes     = array();
		$table_cell_merged_indexes = array();
		$table_cell_server_changed_cells = array();
		$table_cell_local_changed_cells  = array();
		$rich_text_merged_indexes        = array();
		$base_count                = count( $base_records );

	for ( $index = 0; $index < $base_count; $index++ ) {
		$base_item     = $base_sequence['items'][ $index ];
		$server_item   = $server_sequence[ $index ];
		$proposed_item = $proposed_sequence[ $index ];

		if (
			! isset( $server_item['block_uid'], $proposed_item['block_uid'], $base_item['block_uid'] ) ||
			$server_item['block_uid'] !== $base_item['block_uid'] ||
			$proposed_item['block_uid'] !== $base_item['block_uid']
		) {
			return wp_de_rtc_get_block_identity_insertions_only_conflict(
				'block_identity_base_drift',
				$base_records,
				$server_records,
				$proposed_records
			);
		}

		$server_changed = ! hash_equals( $base_item['serialized_hash'], $server_item['serialized_hash'] );
		$local_changed  = ! hash_equals( $base_item['serialized_hash'], $proposed_item['serialized_hash'] );
		$merged_index   = count( $merged_blocks );

			if ( $server_changed && $local_changed && ! hash_equals( $server_item['serialized_hash'], $proposed_item['serialized_hash'] ) ) {
				$rich_text_merge = wp_de_rtc_get_rich_text_serialized_block_merge_candidate( $base_item['record'], $server_item['record'], $proposed_item['record'] );

				if ( is_array( $rich_text_merge ) && ! empty( $rich_text_merge['merged_block'] ) ) {
					$merged_record                   = $rich_text_merge['merged_block'];
					$merged_item                     = $base_item;
					$merged_item['record']           = $merged_record;
					$merged_item['serialized_hash']  = wp_de_rtc_hash_content( $merged_record );
					$server_changed_indexes[]        = $merged_index;
					$local_changed_indexes[]         = $merged_index;
					$retained_edit_indexes[]         = $merged_index;
					$rich_text_merged_indexes[]      = $merged_index;
					$merged_blocks[]                 = $merged_item['record'];
					$merged_block_map[]              = wp_de_rtc_get_block_identity_merged_map_record( $merged_item, $merged_index );
					continue;
				}

				$table_cell_merge = wp_de_rtc_get_table_cell_serialized_block_merge_candidate( $base_item['record'], $server_item['record'], $proposed_item['record'] );

				if ( is_array( $table_cell_merge ) && ! empty( $table_cell_merge['merged_block'] ) ) {
					$merged_record                         = $table_cell_merge['merged_block'];
					$merged_item                           = $base_item;
					$merged_item['record']                 = $merged_record;
					$merged_item['serialized_hash']        = wp_de_rtc_hash_content( $merged_record );
					$server_changed_indexes[]              = $merged_index;
					$local_changed_indexes[]               = $merged_index;
					$retained_edit_indexes[]               = $merged_index;
					$table_cell_merged_indexes[]           = $merged_index;
					$table_cell_server_changed_cells       = array_merge(
						$table_cell_server_changed_cells,
						wp_de_rtc_add_block_index_to_table_cell_evidence( $table_cell_merge['server_changed_cells'], $merged_index )
					);
					$table_cell_local_changed_cells        = array_merge(
						$table_cell_local_changed_cells,
						wp_de_rtc_add_block_index_to_table_cell_evidence( $table_cell_merge['local_changed_cells'], $merged_index )
					);
					$merged_blocks[]                       = $merged_item['record'];
					$merged_block_map[]                    = wp_de_rtc_get_block_identity_merged_map_record( $merged_item, $merged_index );
					continue;
				}

				return wp_de_rtc_get_block_identity_insertions_only_conflict(
					'block_identity_retained_block_conflict',
				$base_records,
				$server_records,
				$proposed_records,
				array(
					'block_index'                  => (int) $index,
					'conflicting_block_index'      => (int) $index,
					'conflicting_block_indexes'    => array( (int) $index ),
					'conflicting_block_count'      => 1,
					'server_changed_indexes'       => array( (int) $index ),
					'local_changed_indexes'        => array( (int) $index ),
					'server_changed_block_count'   => 1,
					'local_changed_block_count'    => 1,
					'block_identity_base_current_retained_edits_only' => false,
				)
			);
		}

		if ( $server_changed ) {
			$merged_item              = $server_item;
			$server_changed_indexes[] = $merged_index;
			$retained_edit_indexes[]  = $merged_index;
		} elseif ( $local_changed ) {
			$merged_item             = $proposed_item;
			$local_changed_indexes[] = $merged_index;
			$retained_edit_indexes[] = $merged_index;
		} else {
			$merged_item = $base_item;
		}

		$merged_blocks[]    = $merged_item['record'];
		$merged_block_map[] = wp_de_rtc_get_block_identity_merged_map_record( $merged_item, $merged_index );
	}

	if ( empty( $server_changed_indexes ) || empty( $local_changed_indexes ) ) {
		return wp_de_rtc_get_block_identity_insertions_only_conflict(
			'block_identity_base_drift',
			$base_records,
			$server_records,
			$proposed_records
		);
	}

	$merged_content = implode( '', $merged_blocks );
	$merged_count   = count( $merged_blocks );

	return array(
		'merge_status'                        => 'merged',
		'merge_strategy'                      => 'top_level_serialized_block_identity_map',
		'base_version'                        => isset( $args['base_version'] ) ? sanitize_text_field( (string) $args['base_version'] ) : null,
		'server_version'                      => isset( $args['server_version'] ) ? sanitize_text_field( (string) $args['server_version'] ) : null,
		'base_revision_id'                    => isset( $args['base_revision_id'] ) ? (int) $args['base_revision_id'] : 0,
		'block_count'                         => $merged_count,
		'base_block_count'                    => $base_count,
		'server_block_count'                  => count( $server_records ),
		'proposed_block_count'                => count( $proposed_records ),
		'merged_block_count'                  => $merged_count,
		'edge_insert_source'                  => null,
		'edge_insert_position'                => null,
		'edge_inserted_block_count'           => 0,
		'append_source'                       => null,
		'appended_block_count'                => 0,
		'prepend_source'                      => null,
		'prepended_block_count'               => 0,
		'server_changed_indexes'              => $server_changed_indexes,
		'local_changed_indexes'               => $local_changed_indexes,
		'server_changed_block_count'          => count( $server_changed_indexes ),
		'local_changed_block_count'           => count( $local_changed_indexes ),
		'block_identity_base_current_match'   => false,
		'block_identity_base_current_insertions_only' => false,
			'block_identity_base_current_retained_edits_only' => true,
			'block_identity_retained_edit_indexes' => $retained_edit_indexes,
			'block_identity_retained_edit_block_count' => count( $retained_edit_indexes ),
			'table_cell_merged_indexes'          => array_map( 'intval', $table_cell_merged_indexes ),
			'table_cell_merged_block_count'      => count( $table_cell_merged_indexes ),
			'table_cell_server_changed_cells'    => $table_cell_server_changed_cells,
			'table_cell_local_changed_cells'     => $table_cell_local_changed_cells,
			'rich_text_merged_indexes'           => array_map( 'intval', $rich_text_merged_indexes ),
			'rich_text_merged_block_count'       => count( $rich_text_merged_indexes ),
			'block_identity_inserted_indexes'     => array(),
		'block_identity_inserted_block_count' => $block_identity_request_proof_validation['inserted_block_count'],
		'block_identity_server_inserted_indexes' => array(),
		'block_identity_server_inserted_block_count' => 0,
		'block_identity_moved_block_count'    => $block_identity_request_proof_validation['moved_block_count'],
		'block_identity_merged_block_map'     => $merged_block_map,
		'merged_content'                      => $merged_content,
		'merged_stripped_content_hash'        => wp_de_rtc_hash_content( $merged_content ),
		'base_content_hash'                   => wp_de_rtc_hash_content( $base_content ),
		'server_content_hash'                 => wp_de_rtc_hash_content( $server_content ),
		'proposed_content_hash'               => wp_de_rtc_hash_content( $proposed_content ),
	);
}

/**
 * Returns a proof-backed block identity merge for insertions in distinct gaps.
 *
 * This helper accepts only insertion-only divergence from the accepted base.
 * Retained base blocks must appear in the original order with unchanged hashes
 * on both the server and proposed sides. If both sides inserted into the same
 * gap, ordering is ambiguous and the merge is rejected for manual resolution.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string[] $base_records                           Accepted-base serialized block records.
 * @param string[] $server_records                         Current server serialized block records.
 * @param string[] $proposed_records                       Client-proposed serialized block records.
 * @param string   $base_content                           Stripped post content for the accepted proof version.
 * @param string   $server_content                         Current stripped server post content.
 * @param string   $proposed_content                       Client-proposed stripped post content.
 * @param mixed    $block_identity_request_proof           Request proof candidate.
 * @param array    $block_identity_request_proof_validation Validated proof evidence.
 * @param array    $args                                   Optional merge evidence.
 * @return array|WP_Error Merge result, or conflict error.
 */
function wp_de_rtc_get_block_identity_insertions_only_server_merge_result( $base_records, $server_records, $proposed_records, $base_content, $server_content, $proposed_content, $block_identity_request_proof, $block_identity_request_proof_validation, $args ) {
	$base_sync_meta    = isset( $args['base_sync_meta'] ) ? $args['base_sync_meta'] : null;
	$current_sync_meta = isset( $args['current_sync_meta'] ) ? $args['current_sync_meta'] : null;
	$base_sequence     = wp_de_rtc_get_block_identity_base_sequence_for_merge( $base_sync_meta, $base_records );

	if ( is_wp_error( $base_sequence ) ) {
		return $base_sequence;
	}

	if (
		! is_array( $block_identity_request_proof_validation ) ||
		! isset( $block_identity_request_proof_validation['deleted_block_count'] ) ||
		0 !== (int) $block_identity_request_proof_validation['deleted_block_count']
	) {
		return wp_de_rtc_get_block_identity_insertions_only_conflict(
			'block_identity_unsupported_delta',
			$base_records,
			$server_records,
			$proposed_records
		);
	}

	$server_sequence = wp_de_rtc_get_block_identity_current_sequence_for_merge(
		$current_sync_meta,
		$base_sequence,
		$server_records,
		$proposed_records,
		$server_content
	);

	if ( is_wp_error( $server_sequence ) ) {
		return $server_sequence;
	}

	$proposed_sequence = wp_de_rtc_get_block_identity_proposed_sequence_for_merge(
		$block_identity_request_proof,
		$base_sequence,
		$proposed_records,
		$server_records
	);

	if ( is_wp_error( $proposed_sequence ) ) {
		return $proposed_sequence;
	}

	$base_count       = count( $base_records );
	$server_gaps      = wp_de_rtc_get_block_identity_insertions_by_gap( $server_sequence, $base_count );
	$proposed_gaps    = wp_de_rtc_get_block_identity_insertions_by_gap( $proposed_sequence, $base_count );
	$merged_blocks    = array();
	$merged_block_map = array();
	$server_changed_indexes = array();
	$local_changed_indexes  = array();
	$server_inserted_indexes = array();
	$local_inserted_indexes  = array();

	for ( $gap_index = 0; $gap_index <= $base_count; $gap_index++ ) {
		$server_insertions   = $server_gaps[ $gap_index ];
		$proposed_insertions = $proposed_gaps[ $gap_index ];

		if ( ! empty( $server_insertions ) && ! empty( $proposed_insertions ) ) {
			return wp_de_rtc_get_block_identity_insertions_only_conflict(
				'block_identity_inserted_block_gap_conflict',
				$base_records,
				$server_records,
				$proposed_records,
				array(
					'block_identity_conflicting_gap_index' => $gap_index,
					'block_identity_server_inserted_block_count_in_gap' => count( $server_insertions ),
					'block_identity_local_inserted_block_count_in_gap' => count( $proposed_insertions ),
				)
			);
		}

		foreach ( $server_insertions as $inserted_item ) {
			$merged_index              = count( $merged_blocks );
			$merged_blocks[]           = $inserted_item['record'];
			$server_changed_indexes[]  = $merged_index;
			$server_inserted_indexes[] = $merged_index;
			$merged_block_map[]        = wp_de_rtc_get_block_identity_merged_map_record( $inserted_item, $merged_index );
		}

		foreach ( $proposed_insertions as $inserted_item ) {
			$merged_index             = count( $merged_blocks );
			$merged_blocks[]          = $inserted_item['record'];
			$local_changed_indexes[]  = $merged_index;
			$local_inserted_indexes[] = $merged_index;
			$merged_block_map[]       = wp_de_rtc_get_block_identity_merged_map_record( $inserted_item, $merged_index );
		}

		if ( $gap_index < $base_count ) {
			$base_item          = $base_sequence['items'][ $gap_index ];
			$merged_index       = count( $merged_blocks );
			$merged_blocks[]    = $base_item['record'];
			$merged_block_map[] = wp_de_rtc_get_block_identity_merged_map_record( $base_item, $merged_index );
		}
	}

	$merged_content = implode( '', $merged_blocks );
	$merged_count   = count( $merged_blocks );

	return array(
		'merge_status'                        => 'merged',
		'merge_strategy'                      => 'top_level_serialized_block_identity_map',
		'base_version'                        => isset( $args['base_version'] ) ? sanitize_text_field( (string) $args['base_version'] ) : null,
		'server_version'                      => isset( $args['server_version'] ) ? sanitize_text_field( (string) $args['server_version'] ) : null,
		'base_revision_id'                    => isset( $args['base_revision_id'] ) ? (int) $args['base_revision_id'] : 0,
		'block_count'                         => $merged_count,
		'base_block_count'                    => $base_count,
		'server_block_count'                  => count( $server_records ),
		'proposed_block_count'                => count( $proposed_records ),
		'merged_block_count'                  => $merged_count,
		'edge_insert_source'                  => null,
		'edge_insert_position'                => null,
		'edge_inserted_block_count'           => 0,
		'append_source'                       => null,
		'appended_block_count'                => 0,
		'prepend_source'                      => null,
		'prepended_block_count'               => 0,
		'server_changed_indexes'              => $server_changed_indexes,
		'local_changed_indexes'               => $local_changed_indexes,
		'server_changed_block_count'          => count( $server_changed_indexes ),
		'local_changed_block_count'           => count( $local_changed_indexes ),
		'block_identity_base_current_match'   => false,
		'block_identity_base_current_insertions_only' => true,
		'block_identity_inserted_indexes'     => $local_inserted_indexes,
		'block_identity_inserted_block_count' => $block_identity_request_proof_validation['inserted_block_count'],
		'block_identity_server_inserted_indexes' => $server_inserted_indexes,
		'block_identity_server_inserted_block_count' => count( $server_inserted_indexes ),
		'block_identity_moved_block_count'    => $block_identity_request_proof_validation['moved_block_count'],
		'block_identity_merged_block_map'     => $merged_block_map,
		'merged_content'                      => $merged_content,
		'merged_stripped_content_hash'        => wp_de_rtc_hash_content( $merged_content ),
		'base_content_hash'                   => wp_de_rtc_hash_content( $base_content ),
		'server_content_hash'                 => wp_de_rtc_hash_content( $server_content ),
		'proposed_content_hash'               => wp_de_rtc_hash_content( $proposed_content ),
	);
}

/**
 * Returns accepted-base block identity sequence data for a merge.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed    $base_sync_meta Accepted-base sync metadata.
 * @param string[] $base_records   Accepted-base serialized block records.
 * @return array|WP_Error Sequence data, or conflict error.
 */
function wp_de_rtc_get_block_identity_base_sequence_for_merge( $base_sync_meta, $base_records ) {
	$validation = wp_de_rtc_validate_block_identity_sync_meta_contract( $base_sync_meta );

	if ( is_wp_error( $validation ) ) {
		return wp_de_rtc_get_block_identity_insertions_only_conflict(
			'block_identity_base_drift',
			$base_records,
			array(),
			array()
		);
	}

	$base_sync_meta = wp_de_rtc_normalize_block_identity_object( $base_sync_meta );
	$blocks         = isset( $base_sync_meta['blocks'] ) && is_array( $base_sync_meta['blocks'] ) ? $base_sync_meta['blocks'] : array();

	if ( count( $blocks ) !== count( $base_records ) ) {
		return wp_de_rtc_get_block_identity_insertions_only_conflict(
			'block_identity_base_drift',
			$base_records,
			array(),
			array()
		);
	}

	$items  = array();
	$by_uid = array();
	$uids   = array();

	foreach ( $blocks as $index => $block ) {
		$block       = wp_de_rtc_normalize_block_identity_object( $block );
		$record_hash = wp_de_rtc_hash_content( $base_records[ $index ] );

		if (
			! is_array( $block ) ||
			! isset( $block['block_uid'], $block['block_name'], $block['serialized_hash'] ) ||
			! hash_equals( (string) $block['serialized_hash'], $record_hash )
		) {
			return wp_de_rtc_get_block_identity_insertions_only_conflict(
				'block_identity_base_drift',
				$base_records,
				array(),
				array()
			);
		}

		$item = array(
			'type'            => 'base',
			'base_index'      => (int) $index,
			'block_uid'       => sanitize_text_field( (string) $block['block_uid'] ),
			'block_name'      => sanitize_text_field( (string) $block['block_name'] ),
			'serialized_hash' => $record_hash,
			'record'          => $base_records[ $index ],
		);

		$items[]                  = $item;
		$by_uid[ $item['block_uid'] ] = $item;
		$uids[]                   = $item['block_uid'];
	}

	return array(
		'document_uuid' => $validation['document_uuid'],
		'records' => $base_records,
		'items'  => $items,
		'by_uid' => $by_uid,
		'uids'   => $uids,
	);
}

/**
 * Returns current-server block identity sequence data for a merge.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed    $current_sync_meta Current server sync metadata.
 * @param array    $base_sequence     Accepted-base sequence data.
 * @param string[] $server_records    Current server serialized block records.
 * @param string[] $proposed_records  Client-proposed serialized block records.
 * @param string   $server_content    Current stripped server post content.
 * @param array    $options           Optional validation controls.
 * @return array|WP_Error Sequence data, or conflict error.
 */
function wp_de_rtc_get_block_identity_current_sequence_for_merge( $current_sync_meta, $base_sequence, $server_records, $proposed_records = array(), $server_content = null, $options = array() ) {
	$validation = wp_de_rtc_validate_block_identity_sync_meta_contract( $current_sync_meta );
	$base_count = count( $base_sequence['items'] );
	$base_records = isset( $base_sequence['records'] ) && is_array( $base_sequence['records'] ) ? $base_sequence['records'] : $base_sequence['items'];
	$allow_retained_block_edits = ! empty( $options['allow_retained_block_edits'] );

	if ( is_wp_error( $validation ) ) {
		return wp_de_rtc_get_block_identity_insertions_only_conflict(
			'block_identity_base_drift',
			$base_records,
			$server_records,
			$proposed_records
		);
	}

	if (
		! isset( $base_sequence['document_uuid'] ) ||
		$validation['document_uuid'] !== $base_sequence['document_uuid'] ||
		( null !== $server_content && ! hash_equals( $validation['content_hash'], wp_de_rtc_hash_content( (string) $server_content ) ) )
	) {
		return wp_de_rtc_get_block_identity_insertions_only_conflict(
			'block_identity_base_drift',
			$base_records,
			$server_records,
			$proposed_records
		);
	}

	$current_sync_meta = wp_de_rtc_normalize_block_identity_object( $current_sync_meta );
	$blocks            = isset( $current_sync_meta['blocks'] ) && is_array( $current_sync_meta['blocks'] ) ? $current_sync_meta['blocks'] : array();

	if ( count( $blocks ) !== count( $server_records ) ) {
		return wp_de_rtc_get_block_identity_insertions_only_conflict(
			'block_identity_base_drift',
			$base_records,
			$server_records,
			$proposed_records
		);
	}

	$sequence        = array();
	$next_base_index = 0;

	foreach ( $blocks as $index => $block ) {
		$block       = wp_de_rtc_normalize_block_identity_object( $block );
		$record_hash = wp_de_rtc_hash_content( $server_records[ $index ] );

		if (
			! is_array( $block ) ||
			! isset( $block['block_uid'], $block['block_name'], $block['serialized_hash'] ) ||
			! hash_equals( (string) $block['serialized_hash'], $record_hash )
		) {
			return wp_de_rtc_get_block_identity_insertions_only_conflict(
				'block_identity_base_drift',
				$base_records,
				$server_records,
				$proposed_records
			);
		}

		$block_uid = sanitize_text_field( (string) $block['block_uid'] );

		if ( isset( $base_sequence['by_uid'][ $block_uid ] ) ) {
			if (
				$next_base_index >= $base_count ||
				$base_sequence['uids'][ $next_base_index ] !== $block_uid ||
				( ! $allow_retained_block_edits && ! hash_equals( $base_sequence['by_uid'][ $block_uid ]['serialized_hash'], $record_hash ) )
			) {
				return wp_de_rtc_get_block_identity_insertions_only_conflict(
					'block_identity_base_drift',
					$base_records,
					$server_records,
					$proposed_records
				);
			}

			$sequence[] = array_merge(
				$base_sequence['by_uid'][ $block_uid ],
				array(
					'accepted_serialized_hash' => $base_sequence['by_uid'][ $block_uid ]['serialized_hash'],
					'serialized_hash'          => $record_hash,
					'record'                   => $server_records[ $index ],
				)
			);
			++$next_base_index;
			continue;
		}

		$sequence[] = array(
			'type'            => 'server_inserted',
			'base_index'      => null,
			'block_uid'       => $block_uid,
			'block_name'      => sanitize_text_field( (string) $block['block_name'] ),
			'serialized_hash' => $record_hash,
			'record'          => $server_records[ $index ],
		);
	}

	if ( $next_base_index !== $base_count ) {
		return wp_de_rtc_get_block_identity_insertions_only_conflict(
			'block_identity_base_drift',
			$base_records,
			$server_records,
			$proposed_records
		);
	}

	return $sequence;
}

/**
 * Returns proposed-client block identity sequence data for a merge.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed    $request_proof    Validated request proof.
 * @param array    $base_sequence    Accepted-base sequence data.
 * @param string[] $proposed_records Client-proposed serialized block records.
 * @param string[] $server_records   Current server serialized block records.
 * @param array    $options          Optional validation controls.
 * @return array|WP_Error Sequence data, or conflict error.
 */
function wp_de_rtc_get_block_identity_proposed_sequence_for_merge( $request_proof, $base_sequence, $proposed_records, $server_records = array(), $options = array() ) {
	$request_proof = wp_de_rtc_normalize_block_identity_object( $request_proof );
	$proposed_map  = isset( $request_proof['proposed_block_map'] ) && is_array( $request_proof['proposed_block_map'] ) ? $request_proof['proposed_block_map'] : array();
	$base_count    = count( $base_sequence['items'] );
	$base_records  = isset( $base_sequence['records'] ) && is_array( $base_sequence['records'] ) ? $base_sequence['records'] : $base_sequence['items'];
	$allow_retained_block_edits = ! empty( $options['allow_retained_block_edits'] );

	if ( count( $proposed_map ) !== count( $proposed_records ) ) {
		return wp_de_rtc_get_block_identity_insertions_only_conflict(
			'block_identity_proof_content_mismatch',
			$base_records,
			$server_records,
			$proposed_records
		);
	}

	$sequence        = array();
	$next_base_index = 0;

	foreach ( $proposed_map as $index => $block ) {
		$block       = wp_de_rtc_normalize_block_identity_object( $block );
		$record_hash = wp_de_rtc_hash_content( $proposed_records[ $index ] );

		if ( ! is_array( $block ) || ! isset( $block['block_name'], $block['serialized_hash'] ) || ! hash_equals( (string) $block['serialized_hash'], $record_hash ) ) {
			return wp_de_rtc_get_block_identity_insertions_only_conflict(
				'block_identity_proof_content_mismatch',
				$base_records,
				$server_records,
				$proposed_records
			);
		}

		if ( isset( $block['block_uid'] ) && '' !== (string) $block['block_uid'] ) {
			$block_uid = sanitize_text_field( (string) $block['block_uid'] );

			if (
				$next_base_index >= $base_count ||
				$base_sequence['uids'][ $next_base_index ] !== $block_uid ||
				( ! $allow_retained_block_edits && ! hash_equals( $base_sequence['by_uid'][ $block_uid ]['serialized_hash'], $record_hash ) )
			) {
				return wp_de_rtc_get_block_identity_insertions_only_conflict(
					'block_identity_base_drift',
					$base_records,
					$server_records,
					$proposed_records
				);
			}

			$sequence[] = array_merge(
				$base_sequence['by_uid'][ $block_uid ],
				array(
					'accepted_serialized_hash' => $base_sequence['by_uid'][ $block_uid ]['serialized_hash'],
					'serialized_hash'          => $record_hash,
					'record'                   => $proposed_records[ $index ],
				)
			);
			++$next_base_index;
			continue;
		}

		if ( ! isset( $block['inserted_block_nonce'] ) || '' === (string) $block['inserted_block_nonce'] ) {
			return wp_de_rtc_get_block_identity_insertions_only_conflict(
				'block_identity_proof_content_mismatch',
				$base_records,
				$server_records,
				$proposed_records
			);
		}

		$sequence[] = array(
			'type'                 => 'local_inserted',
			'base_index'           => null,
			'inserted_block_nonce' => sanitize_text_field( (string) $block['inserted_block_nonce'] ),
			'block_name'           => sanitize_text_field( (string) $block['block_name'] ),
			'serialized_hash'      => $record_hash,
			'record'               => $proposed_records[ $index ],
		);
	}

	if ( $next_base_index !== $base_count ) {
		return wp_de_rtc_get_block_identity_insertions_only_conflict(
			'block_identity_unsupported_delta',
			$base_records,
			$server_records,
			$proposed_records
		);
	}

	return $sequence;
}

/**
 * Returns inserted block sequence items grouped by accepted-base gap.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $sequence   Block identity sequence items.
 * @param int   $base_count Accepted-base block count.
 * @return array[] Insertions keyed by gap index.
 */
function wp_de_rtc_get_block_identity_insertions_by_gap( $sequence, $base_count ) {
	$gaps        = array_fill( 0, $base_count + 1, array() );
	$current_gap = 0;

	foreach ( $sequence as $item ) {
		if ( isset( $item['type'] ) && 'base' === $item['type'] ) {
			$current_gap = isset( $item['base_index'] ) ? (int) $item['base_index'] + 1 : $current_gap;
			continue;
		}

		$gaps[ $current_gap ][] = $item;
	}

	return $gaps;
}

/**
 * Returns a sync-meta block-map record for merged block identity content.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $item         Block identity sequence item.
 * @param int   $merged_index Merged block index.
 * @return array Block map record.
 */
function wp_de_rtc_get_block_identity_merged_map_record( $item, $merged_index ) {
	$record = array(
		'block_name'      => isset( $item['block_name'] ) ? sanitize_text_field( (string) $item['block_name'] ) : '',
		'ordinal_path'    => array( (int) $merged_index ),
		'serialized_hash' => isset( $item['serialized_hash'] ) ? sanitize_text_field( (string) $item['serialized_hash'] ) : '',
	);

	if ( isset( $item['block_uid'] ) && '' !== (string) $item['block_uid'] ) {
		$record['block_uid'] = sanitize_text_field( (string) $item['block_uid'] );
	} elseif ( isset( $item['inserted_block_nonce'] ) ) {
		$record['inserted_block_nonce'] = sanitize_text_field( (string) $item['inserted_block_nonce'] );
	}

	return $record;
}

/**
 * Creates an insertions-only block identity merge conflict.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $detail           Conflict detail.
 * @param array  $base_records     Accepted-base records or sequence items.
 * @param array  $server_records   Current server records.
 * @param array  $proposed_records Client-proposed records.
 * @param array  $extra            Optional extra data.
 * @return WP_Error Conflict error.
 */
function wp_de_rtc_get_block_identity_insertions_only_conflict( $detail, $base_records, $server_records, $proposed_records, $extra = array() ) {
	return wp_de_rtc_get_server_merge_conflict_error(
		$detail,
		array_merge(
			array(
				'server_merge_strategy'           => 'top_level_serialized_block_identity_map',
				'base_block_count'                => count( $base_records ),
				'server_block_count'              => count( $server_records ),
				'proposed_block_count'            => count( $proposed_records ),
				'server_block_count_changed'      => count( $base_records ) !== count( $server_records ),
				'local_block_count_changed'       => count( $base_records ) !== count( $proposed_records ),
				'server_block_count_delta'        => count( $server_records ) - count( $base_records ),
				'local_block_count_delta'         => count( $proposed_records ) - count( $base_records ),
				'block_identity_base_current_match' => false,
				'block_identity_base_current_insertions_only' => false,
			),
			$extra
		)
	);
}

/**
 * Attempts a conservative one-sided deletion merge across serialized blocks.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string[] $base_records     Accepted-base serialized block records.
 * @param string[] $server_records   Current server serialized block records.
 * @param string[] $proposed_records Client-proposed serialized block records.
 * @param string   $base_content     Stripped post content for the accepted proof version.
 * @param string   $server_content   Current stripped server post content.
 * @param string   $proposed_content Client-proposed stripped post content.
 * @param array    $args             Optional merge evidence.
 * @return array|WP_Error Merge result, or conflict error.
 */
function wp_de_rtc_get_serialized_block_deletion_merge_result( $base_records, $server_records, $proposed_records, $base_content, $server_content, $proposed_content, $args = array() ) {
	$base_count     = count( $base_records );
	$server_count   = count( $server_records );
	$proposed_count = count( $proposed_records );
	$server_deleted = $server_count < $base_count && $proposed_count === $base_count;
	$local_deleted  = $proposed_count < $base_count && $server_count === $base_count;

	if ( ! $server_deleted && ! $local_deleted ) {
		return wp_de_rtc_get_server_merge_conflict_error(
			'top_level_serialized_block_count_changed',
			array(
				'base_block_count'           => $base_count,
				'server_block_count'         => $server_count,
				'proposed_block_count'       => $proposed_count,
				'server_block_count_changed' => $base_count !== $server_count,
				'local_block_count_changed'  => $base_count !== $proposed_count,
				'server_block_count_delta'   => $server_count - $base_count,
				'local_block_count_delta'    => $proposed_count - $base_count,
			)
		);
	}

	$deletion_source  = $server_deleted ? 'server' : 'local';
	$stable_source    = $server_deleted ? 'local' : 'server';
	$deleting_records = $server_deleted ? $server_records : $proposed_records;
	$stable_records   = $server_deleted ? $proposed_records : $server_records;
	$deletion         = wp_de_rtc_get_serialized_block_deletion( $base_records, $deleting_records );

	if ( null === $deletion ) {
		return wp_de_rtc_get_server_merge_conflict_error(
			'top_level_serialized_block_count_changed',
			array(
				'base_block_count'           => $base_count,
				'server_block_count'         => $server_count,
				'proposed_block_count'       => $proposed_count,
				'server_block_count_changed' => $base_count !== $server_count,
				'local_block_count_changed'  => $base_count !== $proposed_count,
				'server_block_count_delta'   => $server_count - $base_count,
				'local_block_count_delta'    => $proposed_count - $base_count,
				'deletion_source'            => $deletion_source,
			)
		);
	}

	if ( 'ambiguous' === $deletion['status'] ) {
		return wp_de_rtc_get_server_merge_conflict_error(
			'ambiguous_block_deletion',
			array(
				'base_block_count'           => $base_count,
				'server_block_count'         => $server_count,
				'proposed_block_count'       => $proposed_count,
				'server_block_count_changed' => $base_count !== $server_count,
				'local_block_count_changed'  => $base_count !== $proposed_count,
				'server_block_count_delta'   => $server_count - $base_count,
				'local_block_count_delta'    => $proposed_count - $base_count,
				'deletion_source'            => $deletion_source,
				'deletion_ambiguous'         => true,
			)
		);
	}

	$stable_reordered_indexes = wp_de_rtc_get_reordered_serialized_block_indexes( $base_records, $stable_records );

	if ( ! empty( $stable_reordered_indexes ) ) {
		return wp_de_rtc_get_server_merge_conflict_error(
			'top_level_serialized_block_reordered',
			array(
				'base_block_count'              => $base_count,
				'server_block_count'            => $server_count,
				'proposed_block_count'          => $proposed_count,
				'server_block_count_changed'    => $base_count !== $server_count,
				'local_block_count_changed'     => $base_count !== $proposed_count,
				'server_block_count_delta'      => $server_count - $base_count,
				'local_block_count_delta'       => $proposed_count - $base_count,
				'server_block_order_changed'    => 'server' === $stable_source,
				'local_block_order_changed'     => 'local' === $stable_source,
				'server_reordered_block_indexes' => 'server' === $stable_source ? $stable_reordered_indexes : array(),
				'local_reordered_block_indexes' => 'local' === $stable_source ? $stable_reordered_indexes : array(),
				'deletion_source'               => $deletion_source,
				'deleted_block_indexes'         => $deletion['deleted_indexes'],
				'deleted_block_count'           => count( $deletion['deleted_indexes'] ),
			)
		);
	}

	$deleted_lookup         = array_fill_keys( $deletion['deleted_indexes'], true );
	$merged_blocks          = array();
	$server_changed_indexes = array();
	$local_changed_indexes  = array();

	for ( $index = 0; $index < $base_count; $index++ ) {
		$base_block     = $base_records[ $index ];
		$stable_block   = $stable_records[ $index ];
		$stable_changed = ! hash_equals( $base_block, $stable_block );

		if ( isset( $deleted_lookup[ $index ] ) ) {
			if ( $stable_changed ) {
				return wp_de_rtc_get_server_merge_conflict_error(
					'deleted_serialized_block_changed',
					array(
						'conflicting_block_index'    => (int) $index,
						'conflicting_block_indexes'  => array( (int) $index ),
						'conflicting_block_count'    => 1,
						'base_block_count'           => $base_count,
						'server_block_count'         => $server_count,
						'proposed_block_count'       => $proposed_count,
						'server_block_count_changed' => $base_count !== $server_count,
						'local_block_count_changed'  => $base_count !== $proposed_count,
						'server_block_count_delta'   => $server_count - $base_count,
						'local_block_count_delta'    => $proposed_count - $base_count,
						'deletion_source'            => $deletion_source,
						'deleted_block_indexes'      => $deletion['deleted_indexes'],
						'deleted_block_count'        => count( $deletion['deleted_indexes'] ),
						'deleted_block_changed_source' => $stable_source,
						'server_changed_indexes'     => 'server' === $stable_source ? array( (int) $index ) : array(),
						'local_changed_indexes'      => 'local' === $stable_source ? array( (int) $index ) : array(),
						'server_changed_block_count' => ( 'server' === $stable_source ? 1 : 0 ) + ( 'server' === $deletion_source ? count( $deletion['deleted_indexes'] ) : 0 ),
						'local_changed_block_count'  => ( 'local' === $stable_source ? 1 : 0 ) + ( 'local' === $deletion_source ? count( $deletion['deleted_indexes'] ) : 0 ),
					)
				);
			}

			continue;
		}

		$merged_index = count( $merged_blocks );

		if ( $stable_changed ) {
			if ( 'server' === $stable_source ) {
				$server_changed_indexes[] = $merged_index;
			} else {
				$local_changed_indexes[] = $merged_index;
			}
		}

		$merged_blocks[] = $stable_changed ? $stable_block : $base_block;
	}

	$merged_content = implode( '', $merged_blocks );
	$merged_count   = count( $merged_blocks );

	return array(
		'merge_status'                 => 'merged',
		'merge_strategy'               => 'top_level_serialized_block_three_way',
		'base_version'                 => isset( $args['base_version'] ) ? sanitize_text_field( (string) $args['base_version'] ) : null,
		'server_version'               => isset( $args['server_version'] ) ? sanitize_text_field( (string) $args['server_version'] ) : null,
		'base_revision_id'             => isset( $args['base_revision_id'] ) ? (int) $args['base_revision_id'] : 0,
		'block_count'                  => $merged_count,
		'base_block_count'             => $base_count,
		'server_block_count'           => $server_count,
		'proposed_block_count'         => $proposed_count,
		'merged_block_count'           => $merged_count,
		'edge_insert_source'           => null,
		'edge_insert_position'         => null,
		'edge_inserted_block_count'    => 0,
		'append_source'                => null,
		'appended_block_count'         => 0,
		'prepend_source'               => null,
		'prepended_block_count'        => 0,
		'deletion_source'              => $deletion_source,
		'deleted_block_indexes'        => $deletion['deleted_indexes'],
		'deleted_block_count'          => count( $deletion['deleted_indexes'] ),
		'server_changed_indexes'       => $server_changed_indexes,
		'local_changed_indexes'        => $local_changed_indexes,
		'server_changed_block_count'   => count( $server_changed_indexes ) + ( 'server' === $deletion_source ? count( $deletion['deleted_indexes'] ) : 0 ),
		'local_changed_block_count'    => count( $local_changed_indexes ) + ( 'local' === $deletion_source ? count( $deletion['deleted_indexes'] ) : 0 ),
		'merged_content'               => $merged_content,
		'merged_stripped_content_hash' => wp_de_rtc_hash_content( $merged_content ),
		'base_content_hash'            => wp_de_rtc_hash_content( $base_content ),
		'server_content_hash'          => wp_de_rtc_hash_content( $server_content ),
		'proposed_content_hash'        => wp_de_rtc_hash_content( $proposed_content ),
	);
}

/**
 * Returns strict one-sided edge insertion data for serialized blocks.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string[] $base_records      Accepted-base serialized block records.
 * @param string[] $candidate_records Candidate serialized block records.
 * @return array|null Edge insertion data, or null when the candidate is not a strict edge insertion.
 */
function wp_de_rtc_get_serialized_block_edge_insertion( $base_records, $candidate_records ) {
	$base_count      = count( $base_records );
	$candidate_count = count( $candidate_records );

	if ( $candidate_count <= $base_count ) {
		return null;
	}

	$inserted_count = $candidate_count - $base_count;
	$matches_prefix = true;
	$matches_suffix = true;

	for ( $index = 0; $index < $base_count; $index++ ) {
		if ( ! hash_equals( $base_records[ $index ], $candidate_records[ $index ] ) ) {
			$matches_prefix = false;
			break;
		}
	}

	for ( $index = 0; $index < $base_count; $index++ ) {
		if ( ! hash_equals( $base_records[ $index ], $candidate_records[ $index + $inserted_count ] ) ) {
			$matches_suffix = false;
			break;
		}
	}

	if ( $matches_prefix && $matches_suffix ) {
		return array(
			'position' => 'ambiguous',
			'blocks'   => array(),
		);
	}

	if ( $matches_prefix ) {
		return array(
			'position' => 'append',
			'blocks'   => array_slice( $candidate_records, $base_count ),
		);
	}

	if ( $matches_suffix ) {
		return array(
			'position' => 'prepend',
			'blocks'   => array_slice( $candidate_records, 0, $inserted_count ),
		);
	}

	return null;
}

/**
 * Returns strict one-sided deletion data for serialized blocks.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string[] $base_records      Accepted-base serialized block records.
 * @param string[] $candidate_records Candidate serialized block records.
 * @return array|null Deletion data, or null when the candidate is not a strict deletion.
 */
function wp_de_rtc_get_serialized_block_deletion( $base_records, $candidate_records ) {
	$base_count      = count( $base_records );
	$candidate_count = count( $candidate_records );

	if ( $candidate_count >= $base_count ) {
		return null;
	}

	$leftmost_indexes = array();
	$candidate_index  = 0;

	for ( $base_index = 0; $base_index < $base_count && $candidate_index < $candidate_count; $base_index++ ) {
		if ( hash_equals( $base_records[ $base_index ], $candidate_records[ $candidate_index ] ) ) {
			$leftmost_indexes[] = $base_index;
			$candidate_index++;
		}
	}

	if ( $candidate_index !== $candidate_count ) {
		return null;
	}

	$rightmost_indexes = array_fill( 0, $candidate_count, null );
	$candidate_index   = $candidate_count - 1;

	for ( $base_index = $base_count - 1; $base_index >= 0 && $candidate_index >= 0; $base_index-- ) {
		if ( hash_equals( $base_records[ $base_index ], $candidate_records[ $candidate_index ] ) ) {
			$rightmost_indexes[ $candidate_index ] = $base_index;
			$candidate_index--;
		}
	}

	if ( -1 !== $candidate_index ) {
		return null;
	}

	if ( $leftmost_indexes !== $rightmost_indexes ) {
		return array(
			'status'          => 'ambiguous',
			'deleted_indexes' => array(),
		);
	}

	$matched_lookup            = array_fill_keys( $leftmost_indexes, true );
	$base_to_candidate_indexes = array();
	$deleted_indexes           = array();
	$candidate_index_by_base   = array();

	foreach ( $leftmost_indexes as $candidate_offset => $base_index ) {
		$candidate_index_by_base[ $base_index ] = $candidate_offset;
	}

	for ( $base_index = 0; $base_index < $base_count; $base_index++ ) {
		if ( isset( $matched_lookup[ $base_index ] ) ) {
			$base_to_candidate_indexes[ $base_index ] = $candidate_index_by_base[ $base_index ];
		} else {
			$base_to_candidate_indexes[ $base_index ] = null;
			$deleted_indexes[]                        = $base_index;
		}
	}

	return array(
		'status'                    => 'deleted',
		'deleted_indexes'           => $deleted_indexes,
		'base_to_candidate_indexes' => $base_to_candidate_indexes,
	);
}

/**
 * Returns exact top-level serialized block records for a content string.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $content Stripped post content.
 * @return string[]|WP_Error Serialized top-level records, or an unsafe-boundary error.
 */
	function wp_de_rtc_get_top_level_serialized_block_records( $content ) {
		$content   = wp_de_rtc_canonicalize_post_content_for_hash( $content );
		$blocks    = parse_blocks( $content );
	$records   = array();
	$roundtrip = '';

	foreach ( $blocks as $block ) {
		$serialized = serialize_block( $block );
		$roundtrip .= $serialized;

		if ( ! isset( $block['blockName'] ) ) {
			if ( '' !== trim( $serialized ) ) {
				return wp_de_rtc_get_server_merge_conflict_error( 'freeform_html_boundary' );
			}

			continue;
		}

		$records[] = $serialized;
	}

	if ( $roundtrip !== $content ) {
		return wp_de_rtc_get_server_merge_conflict_error( 'serialized_block_roundtrip_changed' );
	}

	return $records;
}

/**
 * Creates a server-merge conflict error for retry-save.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $detail Conflict detail.
 * @param array  $extra  Optional conflict data.
 * @return WP_Error Conflict error.
 */
function wp_de_rtc_get_server_merge_conflict_error( $detail, $extra = array() ) {
	return wp_de_rtc_get_reason_error(
		'de_rtc_rebase_failed',
		__( 'Distributed Editing could not merge the retry save with the current server content.' ),
		array_merge(
			array(
				'detail'                              => 'retry_save_server_merge_' . sanitize_key( $detail ),
				'server_merge_attempted'              => true,
				'server_merge_status'                 => 'manual_conflict_required',
				'server_merge_strategy'               => 'top_level_serialized_block_three_way',
				'requires_manual_conflict_resolution' => true,
				'saves_post'                          => false,
				'mutates_post_content'                => false,
				'creates_revision'                    => false,
				'claims_saved'                        => false,
			),
			$extra
		)
	);
}

/**
 * Returns indexes that are reordered relative to the accepted base.
 *
 * This is intentionally limited to content-identical block permutations. If a
 * block was edited while moving, the current merge proof cannot prove identity
 * without content-aware block IDs, so later same-block checks still protect the
 * save boundary conservatively.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string[] $base_records      Accepted-base serialized block records.
 * @param string[] $candidate_records Candidate serialized block records.
 * @return int[] Reordered top-level block indexes, or an empty array.
 */
function wp_de_rtc_get_reordered_serialized_block_indexes( $base_records, $candidate_records ) {
	if ( count( $base_records ) !== count( $candidate_records ) ) {
		return array();
	}

	$base_hash_counts      = array();
	$candidate_hash_counts = array();
	$reordered_indexes     = array();

	foreach ( $base_records as $index => $base_record ) {
		$candidate_record = $candidate_records[ $index ];
		$base_hash        = wp_de_rtc_hash_content( $base_record );
		$candidate_hash   = wp_de_rtc_hash_content( $candidate_record );

		if ( ! isset( $base_hash_counts[ $base_hash ] ) ) {
			$base_hash_counts[ $base_hash ] = 0;
		}

		if ( ! isset( $candidate_hash_counts[ $candidate_hash ] ) ) {
			$candidate_hash_counts[ $candidate_hash ] = 0;
		}

		$base_hash_counts[ $base_hash ]++;
		$candidate_hash_counts[ $candidate_hash ]++;

		if ( ! hash_equals( $base_record, $candidate_record ) ) {
			$reordered_indexes[] = (int) $index;
		}
	}

	if ( empty( $reordered_indexes ) ) {
		return array();
	}

	ksort( $base_hash_counts );
	ksort( $candidate_hash_counts );

	if ( $base_hash_counts !== $candidate_hash_counts ) {
		return array();
	}

	return $reordered_indexes;
}

/**
 * Returns whether two block identity sync-meta maps are stable equivalents.
 *
 * Version labels may differ because this helper is used across a stale retry
 * save. The document identity and per-block identity/hash/path evidence must
 * remain the same.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $base_sync_meta    Accepted-base sync metadata.
 * @param mixed $current_sync_meta Current server sync metadata.
 * @return bool Whether the stable identity map matches.
 */
function wp_de_rtc_block_identity_sync_meta_stable_map_matches( $base_sync_meta, $current_sync_meta ) {
	$base_validation    = wp_de_rtc_validate_block_identity_sync_meta_contract( $base_sync_meta );
	$current_validation = wp_de_rtc_validate_block_identity_sync_meta_contract( $current_sync_meta );

	if ( is_wp_error( $base_validation ) || is_wp_error( $current_validation ) ) {
		return false;
	}

	if (
		$base_validation['document_uuid'] !== $current_validation['document_uuid'] ||
		$base_validation['content_hash'] !== $current_validation['content_hash'] ||
		(int) $base_validation['block_count'] !== (int) $current_validation['block_count'] ||
		$base_validation['block_uids'] !== $current_validation['block_uids']
	) {
		return false;
	}

	$base_sync_meta    = wp_de_rtc_normalize_block_identity_object( $base_sync_meta );
	$current_sync_meta = wp_de_rtc_normalize_block_identity_object( $current_sync_meta );

	foreach ( $base_sync_meta['blocks'] as $index => $base_block ) {
		$base_block    = wp_de_rtc_normalize_block_identity_object( $base_block );
		$current_block = wp_de_rtc_normalize_block_identity_object( $current_sync_meta['blocks'][ $index ] );

		foreach ( array( 'block_uid', 'parent_uid', 'block_name', 'ordinal_path', 'serialized_hash' ) as $field ) {
			if ( $base_block[ $field ] !== $current_block[ $field ] ) {
				return false;
			}
		}
	}

	return true;
}

/**
 * Validates that identity request proof describes the proposed stripped content.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed    $request_proof    Request proof candidate.
 * @param mixed    $base_sync_meta   Accepted-base sync metadata.
 * @param string[] $proposed_records Proposed top-level serialized block records.
 * @return array|WP_Error Content-free proof match evidence, or conflict error.
 */
function wp_de_rtc_validate_block_identity_request_proof_matches_proposed_content( $request_proof, $base_sync_meta, $proposed_records ) {
	$request_proof = wp_de_rtc_normalize_block_identity_object( $request_proof );
	$base_sync_meta = wp_de_rtc_normalize_block_identity_object( $base_sync_meta );

	if (
		! is_array( $request_proof ) ||
		! isset( $request_proof['proposed_block_map'] ) ||
		! is_array( $request_proof['proposed_block_map'] ) ||
		! is_array( $base_sync_meta ) ||
		! isset( $base_sync_meta['blocks'] ) ||
		! is_array( $base_sync_meta['blocks'] ) ||
		count( $request_proof['proposed_block_map'] ) !== count( $proposed_records )
	) {
		return wp_de_rtc_get_server_merge_conflict_error(
			'block_identity_proof_content_mismatch',
			array(
				'server_merge_strategy' => 'top_level_serialized_block_identity_map',
			)
		);
	}

	$accepted_hashes_by_uid = array();

	foreach ( $base_sync_meta['blocks'] as $block ) {
		$block = wp_de_rtc_normalize_block_identity_object( $block );

		if (
			is_array( $block ) &&
			isset( $block['block_uid'], $block['serialized_hash'] ) &&
			is_string( $block['block_uid'] )
		) {
			$accepted_hashes_by_uid[ $block['block_uid'] ] = (string) $block['serialized_hash'];
		}
	}

	$inserted_block_indexes         = array();
	$retained_block_changed_indexes = array();

	foreach ( $request_proof['proposed_block_map'] as $index => $proof_block ) {
		$proof_block    = wp_de_rtc_normalize_block_identity_object( $proof_block );
		$record_hash    = wp_de_rtc_hash_content( $proposed_records[ $index ] );

		if ( ! is_array( $proof_block ) ) {
			return wp_de_rtc_get_server_merge_conflict_error(
				'block_identity_proof_content_mismatch',
				array(
					'server_merge_strategy' => 'top_level_serialized_block_identity_map',
					'block_index'           => (int) $index,
				)
			);
		}

		$proof_hash     = isset( $proof_block['serialized_hash'] ) ? sanitize_text_field( (string) $proof_block['serialized_hash'] ) : '';
		$block_uid      = isset( $proof_block['block_uid'] ) ? sanitize_text_field( (string) $proof_block['block_uid'] ) : '';
		$inserted_nonce = isset( $proof_block['inserted_block_nonce'] ) ? sanitize_text_field( (string) $proof_block['inserted_block_nonce'] ) : '';

		if ( ! hash_equals( $record_hash, $proof_hash ) ) {
			return wp_de_rtc_get_server_merge_conflict_error(
				'block_identity_proof_content_mismatch',
				array(
					'server_merge_strategy' => 'top_level_serialized_block_identity_map',
					'block_index'           => (int) $index,
				)
			);
		}

		if ( '' !== $block_uid ) {
			if ( ! isset( $accepted_hashes_by_uid[ $block_uid ] ) ) {
				return wp_de_rtc_get_server_merge_conflict_error(
					'block_identity_proof_content_mismatch',
					array(
						'server_merge_strategy' => 'top_level_serialized_block_identity_map',
						'block_index'           => (int) $index,
					)
				);
			}

			if ( ! hash_equals( $accepted_hashes_by_uid[ $block_uid ], $proof_hash ) ) {
				$retained_block_changed_indexes[] = (int) $index;
			}

			continue;
		}

		if ( '' !== $inserted_nonce ) {
			$inserted_block_indexes[] = (int) $index;
			continue;
		}

		return wp_de_rtc_get_server_merge_conflict_error(
			'block_identity_proof_content_mismatch',
			array(
				'server_merge_strategy' => 'top_level_serialized_block_identity_map',
				'block_index'           => (int) $index,
			)
		);
	}

	return array(
		'inserted_block_indexes'         => $inserted_block_indexes,
		'retained_block_changed_indexes' => $retained_block_changed_indexes,
	);
}

/**
 * Returns content-free merge evidence safe for REST responses and sync meta.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $server_merge_result Internal server merge result.
 * @return array Public merge evidence without raw post content.
 */
function wp_de_rtc_get_public_server_merge_evidence( $server_merge_result ) {
	$server_changed_indexes          = isset( $server_merge_result['server_changed_indexes'] ) ? array_map( 'intval', $server_merge_result['server_changed_indexes'] ) : array();
	$local_changed_indexes           = isset( $server_merge_result['local_changed_indexes'] ) ? array_map( 'intval', $server_merge_result['local_changed_indexes'] ) : array();
	$block_identity_inserted_indexes = (
		isset( $server_merge_result['block_identity_inserted_indexes'] ) &&
		is_array( $server_merge_result['block_identity_inserted_indexes'] )
	) ? array_map( 'intval', $server_merge_result['block_identity_inserted_indexes'] ) : array();
	$block_identity_server_inserted_indexes = (
		isset( $server_merge_result['block_identity_server_inserted_indexes'] ) &&
		is_array( $server_merge_result['block_identity_server_inserted_indexes'] )
	) ? array_map( 'intval', $server_merge_result['block_identity_server_inserted_indexes'] ) : array();
	$block_identity_retained_edit_indexes = (
		isset( $server_merge_result['block_identity_retained_edit_indexes'] ) &&
		is_array( $server_merge_result['block_identity_retained_edit_indexes'] )
	) ? array_map( 'intval', $server_merge_result['block_identity_retained_edit_indexes'] ) : array();
		$rich_text_merged_indexes = (
			isset( $server_merge_result['rich_text_merged_indexes'] ) &&
			is_array( $server_merge_result['rich_text_merged_indexes'] )
		) ? array_map( 'intval', $server_merge_result['rich_text_merged_indexes'] ) : array();
		$table_cell_merged_indexes = (
			isset( $server_merge_result['table_cell_merged_indexes'] ) &&
			is_array( $server_merge_result['table_cell_merged_indexes'] )
		) ? array_map( 'intval', $server_merge_result['table_cell_merged_indexes'] ) : array();

		return array(
		'merge_status'                 => isset( $server_merge_result['merge_status'] ) ? $server_merge_result['merge_status'] : null,
		'merge_strategy'               => isset( $server_merge_result['merge_strategy'] ) ? $server_merge_result['merge_strategy'] : null,
		'base_version'                 => isset( $server_merge_result['base_version'] ) ? $server_merge_result['base_version'] : null,
		'server_version'               => isset( $server_merge_result['server_version'] ) ? $server_merge_result['server_version'] : null,
		'base_revision_id'             => isset( $server_merge_result['base_revision_id'] ) ? (int) $server_merge_result['base_revision_id'] : 0,
		'block_count'                  => isset( $server_merge_result['block_count'] ) ? (int) $server_merge_result['block_count'] : 0,
		'base_block_count'             => isset( $server_merge_result['base_block_count'] ) ? (int) $server_merge_result['base_block_count'] : 0,
		'server_block_count'           => isset( $server_merge_result['server_block_count'] ) ? (int) $server_merge_result['server_block_count'] : 0,
		'proposed_block_count'         => isset( $server_merge_result['proposed_block_count'] ) ? (int) $server_merge_result['proposed_block_count'] : 0,
		'merged_block_count'           => isset( $server_merge_result['merged_block_count'] ) ? (int) $server_merge_result['merged_block_count'] : 0,
		'edge_insert_source'           => isset( $server_merge_result['edge_insert_source'] ) ? $server_merge_result['edge_insert_source'] : null,
		'edge_insert_position'         => isset( $server_merge_result['edge_insert_position'] ) ? $server_merge_result['edge_insert_position'] : null,
		'edge_inserted_block_count'    => isset( $server_merge_result['edge_inserted_block_count'] ) ? (int) $server_merge_result['edge_inserted_block_count'] : 0,
		'append_source'                => isset( $server_merge_result['append_source'] ) ? $server_merge_result['append_source'] : null,
		'appended_block_count'         => isset( $server_merge_result['appended_block_count'] ) ? (int) $server_merge_result['appended_block_count'] : 0,
		'prepend_source'               => isset( $server_merge_result['prepend_source'] ) ? $server_merge_result['prepend_source'] : null,
		'prepended_block_count'        => isset( $server_merge_result['prepended_block_count'] ) ? (int) $server_merge_result['prepended_block_count'] : 0,
		'deletion_source'              => isset( $server_merge_result['deletion_source'] ) ? $server_merge_result['deletion_source'] : null,
		'deleted_block_indexes'        => isset( $server_merge_result['deleted_block_indexes'] ) && is_array( $server_merge_result['deleted_block_indexes'] ) ? array_map( 'intval', $server_merge_result['deleted_block_indexes'] ) : array(),
		'deleted_block_count'          => isset( $server_merge_result['deleted_block_count'] ) ? (int) $server_merge_result['deleted_block_count'] : 0,
		'server_changed_indexes'       => $server_changed_indexes,
		'local_changed_indexes'        => $local_changed_indexes,
			'rich_text_merged_indexes'     => $rich_text_merged_indexes,
			'rich_text_merged_block_count' => isset( $server_merge_result['rich_text_merged_block_count'] ) ? (int) $server_merge_result['rich_text_merged_block_count'] : count( $rich_text_merged_indexes ),
			'table_cell_merged_indexes'    => $table_cell_merged_indexes,
			'table_cell_merged_block_count' => isset( $server_merge_result['table_cell_merged_block_count'] ) ? (int) $server_merge_result['table_cell_merged_block_count'] : count( $table_cell_merged_indexes ),
			'table_cell_server_changed_cells' => isset( $server_merge_result['table_cell_server_changed_cells'] ) && is_array( $server_merge_result['table_cell_server_changed_cells'] ) ? $server_merge_result['table_cell_server_changed_cells'] : array(),
			'table_cell_local_changed_cells' => isset( $server_merge_result['table_cell_local_changed_cells'] ) && is_array( $server_merge_result['table_cell_local_changed_cells'] ) ? $server_merge_result['table_cell_local_changed_cells'] : array(),
			'server_changed_block_count'   => isset( $server_merge_result['server_changed_block_count'] ) ? (int) $server_merge_result['server_changed_block_count'] : count( $server_changed_indexes ),
		'local_changed_block_count'    => isset( $server_merge_result['local_changed_block_count'] ) ? (int) $server_merge_result['local_changed_block_count'] : count( $local_changed_indexes ),
		'block_identity_base_current_match'   => isset( $server_merge_result['block_identity_base_current_match'] ) ? (bool) $server_merge_result['block_identity_base_current_match'] : null,
		'block_identity_base_current_insertions_only' => isset( $server_merge_result['block_identity_base_current_insertions_only'] ) ? (bool) $server_merge_result['block_identity_base_current_insertions_only'] : null,
		'block_identity_base_current_retained_edits_only' => isset( $server_merge_result['block_identity_base_current_retained_edits_only'] ) ? (bool) $server_merge_result['block_identity_base_current_retained_edits_only'] : null,
		'block_identity_retained_edit_indexes' => $block_identity_retained_edit_indexes,
		'block_identity_retained_edit_block_count' => isset( $server_merge_result['block_identity_retained_edit_block_count'] ) ? (int) $server_merge_result['block_identity_retained_edit_block_count'] : count( $block_identity_retained_edit_indexes ),
		'block_identity_inserted_indexes'     => $block_identity_inserted_indexes,
		'block_identity_inserted_block_count' => isset( $server_merge_result['block_identity_inserted_block_count'] ) ? (int) $server_merge_result['block_identity_inserted_block_count'] : 0,
		'block_identity_server_inserted_indexes' => $block_identity_server_inserted_indexes,
		'block_identity_server_inserted_block_count' => isset( $server_merge_result['block_identity_server_inserted_block_count'] ) ? (int) $server_merge_result['block_identity_server_inserted_block_count'] : 0,
		'block_identity_moved_block_count'    => isset( $server_merge_result['block_identity_moved_block_count'] ) ? (int) $server_merge_result['block_identity_moved_block_count'] : 0,
		'merged_stripped_content_hash' => isset( $server_merge_result['merged_stripped_content_hash'] ) ? $server_merge_result['merged_stripped_content_hash'] : null,
		'base_content_hash'            => isset( $server_merge_result['base_content_hash'] ) ? $server_merge_result['base_content_hash'] : null,
		'server_content_hash'          => isset( $server_merge_result['server_content_hash'] ) ? $server_merge_result['server_content_hash'] : null,
		'proposed_content_hash'        => isset( $server_merge_result['proposed_content_hash'] ) ? $server_merge_result['proposed_content_hash'] : null,
	);
}

/**
 * Returns normalized request hash evidence.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array  $args Request arguments.
 * @param string $key  Hash argument key.
 * @return string|null Lowercase SHA-256 hash candidate, or null when absent.
 */
function wp_de_rtc_get_request_hash_evidence( $args, $key ) {
	if ( ! array_key_exists( $key, $args ) || null === $args[ $key ] ) {
		return null;
	}

	return strtolower( sanitize_text_field( (string) $args[ $key ] ) );
}

/**
 * Returns whether a value is lowercase SHA-256 hash evidence.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $hash Hash candidate.
 * @return bool Whether the value is a SHA-256 hash.
 */
function wp_de_rtc_is_sha256_hash( $hash ) {
	return is_string( $hash ) && 1 === preg_match( '/^[a-f0-9]{64}$/', $hash );
}

/**
 * Finds raw post-content parameter paths in a request payload.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed  $payload Request payload.
 * @param string $prefix  Current parameter path.
 * @return string[] Raw post-content parameter paths.
 */
function wp_de_rtc_find_raw_post_content_param_paths( $payload, $prefix = '' ) {
	if ( is_object( $payload ) ) {
		$payload = get_object_vars( $payload );
	}

	if ( ! is_array( $payload ) ) {
		return array();
	}

	$raw_content_keys = array(
		'content',
		'post_content',
		'proposed_post_content',
		'proposedPostContent',
		'candidate_post_content',
		'candidatePostContent',
		'saved_post_content',
		'savedPostContent',
		'raw_content',
		'rawContent',
		'raw_post_content',
		'rawPostContent',
	);
	$paths            = array();

	foreach ( $payload as $key => $value ) {
		$key_string = is_string( $key ) ? $key : (string) $key;
		$path       = '' === $prefix ? $key_string : $prefix . '.' . $key_string;

		if ( in_array( $key_string, $raw_content_keys, true ) ) {
			$paths[] = $path;
		}

		if ( is_array( $value ) || is_object( $value ) ) {
			$paths = array_merge( $paths, wp_de_rtc_find_raw_post_content_param_paths( $value, $path ) );
		}
	}

	return $paths;
}

/**
 * Finds private proof-token parameter paths in a public evidence payload.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed  $payload Request payload.
 * @param string $prefix  Current parameter path.
 * @return string[] Private proof parameter paths.
 */
function wp_de_rtc_find_private_proof_param_paths( $payload, $prefix = '' ) {
	if ( is_object( $payload ) ) {
		$payload = get_object_vars( $payload );
	}

	if ( ! is_array( $payload ) ) {
		return array();
	}

	$private_proof_keys = array(
		'token',
		'token_hash',
		'tokenHash',
		'proof',
		'proof_token',
		'proofToken',
		'proof_signature',
		'proofSignature',
		'proof_internals',
		'proofInternals',
		'proof_signature_valid',
		'proofSignatureValid',
		'field_based_review_approval_proof',
		'fieldBasedReviewApprovalProof',
		'review_approval_proof',
		'reviewApprovalProof',
		'accepted_review_approval_proof',
		'acceptedReviewApprovalProof',
		'reviewer_user_id',
		'reviewerUserId',
		'low_privileged_saver_user_id',
		'lowPrivilegedSaverUserId',
		'saver_user_id',
		'saverUserId',
		'reviewed_block_items',
		'reviewedBlockItems',
	);
	$paths              = array();

	foreach ( $payload as $key => $value ) {
		$key_string = is_string( $key ) ? $key : (string) $key;
		$path       = '' === $prefix ? $key_string : $prefix . '.' . $key_string;

		if ( in_array( $key_string, $private_proof_keys, true ) ) {
			$paths[] = $path;
		}

		$paths = array_merge( $paths, wp_de_rtc_find_private_proof_param_paths( $value, $path ) );
	}

	return $paths;
}

/**
 * Returns the minimum durable block-identity contract fields.
 *
 * @since 7.1.0
 * @access private
 *
 * @return array Required sync-meta, block, and request-proof fields.
 */
function wp_de_rtc_get_block_identity_contract_required_fields() {
	return array(
		'sync_meta'     => array(
			'schema',
			'document_uuid',
			'version',
			'content_hash',
			'blocks',
		),
		'block'         => array(
			'block_uid',
			'parent_uid',
			'block_name',
			'ordinal_path',
			'serialized_hash',
		),
		'request_proof' => array(
			'client_base_version',
			'proposed_post_content_hash',
			'proposed_block_map',
			'retained_block_uids',
			'inserted_block_nonces',
			'deleted_block_uids',
			'moved_block_uids',
		),
	);
}

/**
 * Validates block identity proof at the guarded retry-save boundary.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed       $request_proof              Request proof candidate.
 * @param mixed       $accepted_sync_meta          Accepted-base sync metadata.
 * @param string      $proposed_post_content_hash SHA-256 hash of proposed stripped content.
 * @param int|WP_Post $post                       Post ID or object.
 * @param string[]    $alternate_proposed_post_content_hashes Optional accepted equivalent proposed-content hashes.
 * @return array|WP_Error Validation evidence, or a no-write error.
 */
function wp_de_rtc_validate_retry_save_block_identity_request_proof( $request_proof, $accepted_sync_meta, $proposed_post_content_hash, $post, $alternate_proposed_post_content_hashes = array() ) {
	$post       = get_post( $post );
	$validation = wp_de_rtc_validate_block_identity_request_proof( $request_proof, $accepted_sync_meta );

	if ( is_wp_error( $validation ) ) {
		$data = $validation->get_error_data();

		if ( ! is_array( $data ) ) {
			$data = array();
		}

		$data['post_id']    = $post ? (int) $post->ID : 0;
		$data['rest_route'] = 'post_retry_save_block_identity';

		$validation->add_data( $data, $validation->get_error_code() );

		return $validation;
	}

	$proposed_hash_matches = hash_equals( $validation['proposed_post_content_hash'], $proposed_post_content_hash );

	foreach ( is_array( $alternate_proposed_post_content_hashes ) ? $alternate_proposed_post_content_hashes : array() as $alternate_hash ) {
		if ( is_string( $alternate_hash ) && wp_de_rtc_is_sha256_hash( $alternate_hash ) && hash_equals( $validation['proposed_post_content_hash'], $alternate_hash ) ) {
			$proposed_hash_matches = true;
			break;
		}
	}

	if ( ! $proposed_hash_matches ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_sync_meta_tampered',
			__( 'Distributed Editing rejected the retry save because block identity proof targeted different proposed content.' ),
			wp_de_rtc_get_block_identity_no_write_data(
				array(
					'detail'                               => 'retry_save_block_identity_request_proof_hash_mismatch',
					'post_id'                              => $post ? (int) $post->ID : 0,
					'rest_route'                           => 'post_retry_save_block_identity',
					'proposed_post_content_hash'           => $proposed_post_content_hash,
					'block_identity_proposed_content_hash' => $validation['proposed_post_content_hash'],
				)
			)
		);
	}

	$validation['validated_for_retry_save'] = true;
	$validation['rest_route']               = 'post_retry_save_block_identity';
	$validation['post_id']                  = $post ? (int) $post->ID : 0;

	return $validation;
}

/**
 * Applies validated block identity request proof to server-owned sync metadata.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array  $sync_meta                 Current sync metadata.
 * @param mixed  $request_proof             Validated request proof.
 * @param string $next_version              Next server sync version.
 * @param string $save_post_content_hash    SHA-256 hash of saved stripped content.
 * @return array Updated sync metadata.
 */
function wp_de_rtc_apply_block_identity_request_proof_to_sync_meta( $sync_meta, $request_proof, $next_version, $save_post_content_hash ) {
	$request_proof = wp_de_rtc_normalize_block_identity_object( $request_proof );

	if ( ! is_array( $sync_meta ) || ! is_array( $request_proof ) || empty( $request_proof['proposed_block_map'] ) || ! is_array( $request_proof['proposed_block_map'] ) ) {
		return $sync_meta;
	}

	$document_uuid = isset( $sync_meta['document_uuid'] ) ? sanitize_text_field( (string) $sync_meta['document_uuid'] ) : '';
	$blocks        = array();

	foreach ( $request_proof['proposed_block_map'] as $index => $block ) {
		$block = wp_de_rtc_normalize_block_identity_object( $block );

		if ( ! is_array( $block ) ) {
			continue;
		}

		$block_uid = isset( $block['block_uid'] )
			? sanitize_text_field( (string) $block['block_uid'] )
			: wp_de_rtc_generate_inserted_block_identity_uid(
				$document_uuid,
				$next_version,
				isset( $block['inserted_block_nonce'] ) ? (string) $block['inserted_block_nonce'] : '',
				isset( $block['serialized_hash'] ) ? (string) $block['serialized_hash'] : '',
				$index
			);

		$blocks[] = array(
			'block_uid'       => $block_uid,
			'parent_uid'      => null,
			'block_name'      => isset( $block['block_name'] ) ? sanitize_text_field( (string) $block['block_name'] ) : '',
			'ordinal_path'    => array_map( 'intval', isset( $block['ordinal_path'] ) && is_array( $block['ordinal_path'] ) ? $block['ordinal_path'] : array( $index ) ),
			'serialized_hash' => isset( $block['serialized_hash'] ) ? sanitize_text_field( (string) $block['serialized_hash'] ) : '',
		);
	}

	$sync_meta['schema']       = 'de-rtc-block-identity-v1';
	$sync_meta['content_hash'] = $save_post_content_hash;
	$sync_meta['blocks']       = $blocks;

	return $sync_meta;
}

/**
 * Generates a server-owned UID for an inserted block from content-free proof.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $document_uuid        Document UUID.
 * @param string $next_version         Next server sync version.
 * @param string $inserted_block_nonce Client nonce for this inserted block.
 * @param string $serialized_hash      Serialized block SHA-256 hash.
 * @param int    $index                Proposed block index.
 * @return string Server-owned block UID.
 */
function wp_de_rtc_generate_inserted_block_identity_uid( $document_uuid, $next_version, $inserted_block_nonce, $serialized_hash, $index ) {
	return 'block-' . substr(
		hash(
			'sha256',
			implode(
				'|',
				array(
					'wp-de-rtc-block-identity-v1',
					sanitize_text_field( (string) $document_uuid ),
					sanitize_text_field( (string) $next_version ),
					sanitize_text_field( (string) $inserted_block_nonce ),
					sanitize_text_field( (string) $serialized_hash ),
					(int) $index,
				)
			)
		),
		0,
		24
	);
}

/**
 * Validates read-only block identity sync metadata.
 *
 * This helper only validates shape. It must not save, mutate post content,
 * create revisions, change locks, or claim saved state.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $sync_meta Sync metadata candidate.
 * @return array|WP_Error Validation evidence, or malformed-payload error.
 */
function wp_de_rtc_validate_block_identity_sync_meta_contract( $sync_meta ) {
	$sync_meta = wp_de_rtc_normalize_block_identity_object( $sync_meta );

	if ( ! is_array( $sync_meta ) ) {
		return wp_de_rtc_get_block_identity_validation_error( 'block_identity_sync_meta_missing' );
	}

	$raw_content_paths = wp_de_rtc_find_raw_post_content_param_paths( $sync_meta );

	if ( ! empty( $raw_content_paths ) ) {
		return wp_de_rtc_get_block_identity_validation_error(
			'block_identity_raw_content_rejected',
			array(
				'raw_content_param_paths' => $raw_content_paths,
			)
		);
	}

	$client_id_paths = wp_de_rtc_find_gutenberg_client_id_param_paths( $sync_meta );

	if ( ! empty( $client_id_paths ) ) {
		return wp_de_rtc_get_block_identity_validation_error(
			'block_identity_client_id_rejected',
			array(
				'client_id_param_paths' => $client_id_paths,
			)
		);
	}

	$required = wp_de_rtc_get_block_identity_contract_required_fields();

	foreach ( $required['sync_meta'] as $field ) {
		if ( ! array_key_exists( $field, $sync_meta ) ) {
			return wp_de_rtc_get_block_identity_validation_error(
				'block_identity_sync_meta_missing_required_field',
				array(
					'missing_field' => $field,
				)
			);
		}
	}

	if ( 'de-rtc-block-identity-v1' !== $sync_meta['schema'] ) {
		$schema = is_scalar( $sync_meta['schema'] ) ? sanitize_text_field( (string) $sync_meta['schema'] ) : null;

		return wp_de_rtc_get_block_identity_validation_error(
			'block_identity_schema_mismatch',
			array(
				'schema' => $schema,
			)
		);
	}

	if (
		! is_string( $sync_meta['document_uuid'] ) ||
		'' === $sync_meta['document_uuid'] ||
		! wp_de_rtc_is_block_identity_version_label( $sync_meta['version'] ) ||
		! wp_de_rtc_is_sha256_hash( $sync_meta['content_hash'] ) ||
		! is_array( $sync_meta['blocks'] )
	) {
		return wp_de_rtc_get_block_identity_validation_error( 'block_identity_sync_meta_invalid_required_field' );
	}

	$block_uids = array();

	foreach ( $sync_meta['blocks'] as $index => $block ) {
		$block_validation = wp_de_rtc_validate_block_identity_block_record( $block );

		if ( is_wp_error( $block_validation ) ) {
			$data                = $block_validation->get_error_data();
			$data['block_index'] = (int) $index;

			return wp_de_rtc_get_block_identity_validation_error(
				isset( $data['detail'] ) ? $data['detail'] : 'block_identity_block_invalid',
				$data
			);
		}

		$block_uid = $block_validation['block_uid'];

		if ( isset( $block_uids[ $block_uid ] ) ) {
			return wp_de_rtc_get_block_identity_validation_error(
				'block_identity_duplicate_block_uid',
				array(
					'block_uid'    => $block_uid,
					'block_index'  => (int) $index,
					'first_index'  => $block_uids[ $block_uid ],
				)
			);
		}

		$block_uids[ $block_uid ] = (int) $index;
	}

	return wp_de_rtc_get_block_identity_no_write_data(
		array(
			'status'          => 'valid',
			'detail'          => null,
			'schema'          => $sync_meta['schema'],
			'document_uuid'   => $sync_meta['document_uuid'],
			'version'         => sanitize_text_field( (string) $sync_meta['version'] ),
			'content_hash'    => $sync_meta['content_hash'],
			'block_count'     => count( $sync_meta['blocks'] ),
			'block_uids'      => array_keys( $block_uids ),
			'required_fields' => $required,
		)
	);
}

/**
 * Validates read-only block identity request proof against accepted sync meta.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $request_proof      Request proof candidate.
 * @param mixed $accepted_sync_meta Accepted-base sync metadata candidate.
 * @return array|WP_Error Validation evidence, or malformed-payload error.
 */
function wp_de_rtc_validate_block_identity_request_proof( $request_proof, $accepted_sync_meta ) {
	$sync_meta_validation = wp_de_rtc_validate_block_identity_sync_meta_contract( $accepted_sync_meta );

	if ( is_wp_error( $sync_meta_validation ) ) {
		$sync_meta_error_data = $sync_meta_validation->get_error_data();

		return wp_de_rtc_get_block_identity_validation_error(
			'block_identity_accepted_sync_meta_invalid',
			array(
				'accepted_sync_meta_error_code'   => $sync_meta_validation->get_error_code(),
				'accepted_sync_meta_error_detail' => isset( $sync_meta_error_data['detail'] ) ? $sync_meta_error_data['detail'] : null,
			)
		);
	}

	$request_proof = wp_de_rtc_normalize_block_identity_object( $request_proof );

	if ( ! is_array( $request_proof ) ) {
		return wp_de_rtc_get_block_identity_validation_error( 'block_identity_request_proof_missing' );
	}

	$raw_content_paths = wp_de_rtc_find_raw_post_content_param_paths( $request_proof );

	if ( ! empty( $raw_content_paths ) ) {
		return wp_de_rtc_get_block_identity_validation_error(
			'block_identity_raw_content_rejected',
			array(
				'raw_content_param_paths' => $raw_content_paths,
			)
		);
	}

	$client_id_paths = wp_de_rtc_find_gutenberg_client_id_param_paths( $request_proof );

	if ( ! empty( $client_id_paths ) ) {
		return wp_de_rtc_get_block_identity_validation_error(
			'block_identity_client_id_rejected',
			array(
				'client_id_param_paths' => $client_id_paths,
			)
		);
	}

	$required = wp_de_rtc_get_block_identity_contract_required_fields();

	foreach ( $required['request_proof'] as $field ) {
		if ( ! array_key_exists( $field, $request_proof ) ) {
			return wp_de_rtc_get_block_identity_validation_error(
				'block_identity_request_proof_missing_required_field',
				array(
					'missing_field' => $field,
				)
			);
		}
	}

	if ( ! wp_de_rtc_is_block_identity_version_label( $request_proof['client_base_version'] ) ) {
		return wp_de_rtc_get_block_identity_validation_error( 'block_identity_request_proof_invalid_required_field' );
	}

	$client_base_version = sanitize_text_field( (string) $request_proof['client_base_version'] );

	if ( $client_base_version !== $sync_meta_validation['version'] ) {
		return wp_de_rtc_get_block_identity_validation_error(
			'block_identity_request_proof_base_version_mismatch',
			array(
				'client_base_version' => $client_base_version,
				'server_version'      => $sync_meta_validation['version'],
			)
		);
	}

	if (
		! wp_de_rtc_is_sha256_hash( $request_proof['proposed_post_content_hash'] ) ||
		! is_array( $request_proof['proposed_block_map'] ) ||
		! is_array( $request_proof['retained_block_uids'] ) ||
		! is_array( $request_proof['inserted_block_nonces'] ) ||
		! is_array( $request_proof['deleted_block_uids'] ) ||
		! is_array( $request_proof['moved_block_uids'] )
	) {
		return wp_de_rtc_get_block_identity_validation_error( 'block_identity_request_proof_invalid_required_field' );
	}

	$accepted_block_uids   = array_fill_keys( $sync_meta_validation['block_uids'], true );
	$inserted_block_nonces = wp_de_rtc_validate_block_identity_string_list(
		$request_proof['inserted_block_nonces'],
		'inserted_block_nonces'
	);

	if ( is_wp_error( $inserted_block_nonces ) ) {
		return $inserted_block_nonces;
	}

	$inserted_block_nonce_lookup = array_fill_keys( $inserted_block_nonces, true );
	$retained_block_uids         = wp_de_rtc_validate_block_identity_uid_list(
		$request_proof['retained_block_uids'],
		'retained_block_uids',
		$accepted_block_uids
	);
	$deleted_block_uids          = wp_de_rtc_validate_block_identity_uid_list(
		$request_proof['deleted_block_uids'],
		'deleted_block_uids',
		$accepted_block_uids
	);
	$moved_block_uids            = wp_de_rtc_validate_block_identity_uid_list(
		$request_proof['moved_block_uids'],
		'moved_block_uids',
		$accepted_block_uids
	);

	foreach ( array( $retained_block_uids, $deleted_block_uids, $moved_block_uids ) as $validated_uids ) {
		if ( is_wp_error( $validated_uids ) ) {
			return $validated_uids;
		}
	}

	foreach ( $request_proof['proposed_block_map'] as $index => $block ) {
		$block_validation = wp_de_rtc_validate_block_identity_proposed_block_record(
			$block,
			$accepted_block_uids,
			$inserted_block_nonce_lookup
		);

		if ( is_wp_error( $block_validation ) ) {
			$data                = $block_validation->get_error_data();
			$data['block_index'] = (int) $index;

			return wp_de_rtc_get_block_identity_validation_error(
				isset( $data['detail'] ) ? $data['detail'] : 'block_identity_proposed_block_invalid',
				$data
			);
		}
	}

	return wp_de_rtc_get_block_identity_no_write_data(
		array(
			'status'                     => 'valid',
			'detail'                     => null,
			'client_base_version'        => $client_base_version,
			'proposed_post_content_hash' => $request_proof['proposed_post_content_hash'],
			'proposed_block_count'       => count( $request_proof['proposed_block_map'] ),
			'retained_block_count'       => count( $retained_block_uids ),
			'inserted_block_count'       => count( $inserted_block_nonces ),
			'deleted_block_count'        => count( $deleted_block_uids ),
			'moved_block_count'          => count( $moved_block_uids ),
			'required_fields'            => $required,
		)
	);
}

/**
 * Finds Gutenberg clientId paths in block identity proof.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed  $payload Payload to inspect.
 * @param string $prefix  Current parameter path.
 * @return string[] Client ID paths.
 */
function wp_de_rtc_find_gutenberg_client_id_param_paths( $payload, $prefix = '' ) {
	if ( is_object( $payload ) ) {
		$payload = get_object_vars( $payload );
	}

	if ( ! is_array( $payload ) ) {
		return array();
	}

	$paths = array();

	foreach ( $payload as $key => $value ) {
		$key_string = is_string( $key ) ? $key : (string) $key;
		$path       = '' === $prefix ? $key_string : $prefix . '.' . $key_string;

		if ( in_array( $key_string, array( 'clientId', 'client_id' ), true ) ) {
			$paths[] = $path;
		}

		$paths = array_merge( $paths, wp_de_rtc_find_gutenberg_client_id_param_paths( $value, $path ) );
	}

	return $paths;
}

/**
 * Normalizes object payloads into arrays for block identity validation.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $value Payload value.
 * @return mixed Normalized payload.
 */
function wp_de_rtc_normalize_block_identity_object( $value ) {
	if ( is_object( $value ) ) {
		return get_object_vars( $value );
	}

	return $value;
}

/**
 * Validates a durable block identity record.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $block Block record candidate.
 * @return array|WP_Error Validated block evidence, or malformed-payload error.
 */
function wp_de_rtc_validate_block_identity_block_record( $block ) {
	$block = wp_de_rtc_normalize_block_identity_object( $block );

	if ( ! is_array( $block ) ) {
		return wp_de_rtc_get_block_identity_validation_error( 'block_identity_block_invalid' );
	}

	$required = wp_de_rtc_get_block_identity_contract_required_fields();

	foreach ( $required['block'] as $field ) {
		if ( ! array_key_exists( $field, $block ) ) {
			return wp_de_rtc_get_block_identity_validation_error(
				'block_identity_block_missing_required_field',
				array(
					'missing_field' => $field,
				)
			);
		}
	}

	if (
		! is_string( $block['block_uid'] ) ||
		'' === $block['block_uid'] ||
		! ( is_string( $block['parent_uid'] ) || null === $block['parent_uid'] ) ||
		! is_string( $block['block_name'] ) ||
		'' === $block['block_name'] ||
		! wp_de_rtc_is_block_identity_ordinal_path( $block['ordinal_path'] ) ||
		! wp_de_rtc_is_sha256_hash( $block['serialized_hash'] )
	) {
		return wp_de_rtc_get_block_identity_validation_error( 'block_identity_block_invalid_required_field' );
	}

	return array(
		'block_uid'       => $block['block_uid'],
		'parent_uid'      => $block['parent_uid'],
		'block_name'      => $block['block_name'],
		'ordinal_path'    => array_map( 'intval', $block['ordinal_path'] ),
		'serialized_hash' => $block['serialized_hash'],
	);
}

/**
 * Validates a proposed block identity record in request proof.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $block                       Proposed block record.
 * @param array $accepted_block_uids         Accepted-base block UID lookup.
 * @param array $inserted_block_nonce_lookup Client insertion nonce lookup.
 * @return array|WP_Error Validated block evidence, or malformed-payload error.
 */
function wp_de_rtc_validate_block_identity_proposed_block_record(
	$block,
	$accepted_block_uids,
	$inserted_block_nonce_lookup
) {
	$block = wp_de_rtc_normalize_block_identity_object( $block );

	if ( ! is_array( $block ) ) {
		return wp_de_rtc_get_block_identity_validation_error( 'block_identity_proposed_block_invalid' );
	}

	foreach ( array( 'block_name', 'ordinal_path', 'serialized_hash' ) as $field ) {
		if ( ! array_key_exists( $field, $block ) ) {
			return wp_de_rtc_get_block_identity_validation_error(
				'block_identity_proposed_block_missing_required_field',
				array(
					'missing_field' => $field,
				)
			);
		}
	}

	if (
		! is_string( $block['block_name'] ) ||
		'' === $block['block_name'] ||
		! wp_de_rtc_is_block_identity_ordinal_path( $block['ordinal_path'] ) ||
		! wp_de_rtc_is_sha256_hash( $block['serialized_hash'] )
	) {
		return wp_de_rtc_get_block_identity_validation_error( 'block_identity_proposed_block_invalid_required_field' );
	}

	$has_block_uid      = isset( $block['block_uid'] ) && is_string( $block['block_uid'] ) && '' !== $block['block_uid'];
	$has_inserted_nonce = (
		isset( $block['inserted_block_nonce'] ) &&
		is_string( $block['inserted_block_nonce'] ) &&
		'' !== $block['inserted_block_nonce']
	);

	if ( $has_block_uid && $has_inserted_nonce ) {
		return wp_de_rtc_get_block_identity_validation_error( 'block_identity_proposed_block_ambiguous_identity' );
	}

	if ( $has_block_uid ) {
		if ( ! isset( $accepted_block_uids[ $block['block_uid'] ] ) ) {
			return wp_de_rtc_get_block_identity_validation_error(
				'block_identity_request_proof_unknown_block_uid',
				array(
					'unknown_block_uid' => $block['block_uid'],
					'field'             => 'proposed_block_map',
				)
			);
		}

		return array(
			'identity_kind' => 'retained',
			'block_uid'     => $block['block_uid'],
		);
	}

	if ( $has_inserted_nonce ) {
		if ( ! isset( $inserted_block_nonce_lookup[ $block['inserted_block_nonce'] ] ) ) {
			return wp_de_rtc_get_block_identity_validation_error(
				'block_identity_request_proof_unknown_inserted_nonce',
				array(
					'unknown_inserted_block_nonce' => $block['inserted_block_nonce'],
					'field'                        => 'proposed_block_map',
				)
			);
		}

		return array(
			'identity_kind'        => 'inserted',
			'inserted_block_nonce' => $block['inserted_block_nonce'],
		);
	}

	return wp_de_rtc_get_block_identity_validation_error( 'block_identity_proposed_block_unknown_identity' );
}

/**
 * Validates a content-free string list for block identity proof.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array  $values List values.
 * @param string $field  Request-proof field name.
 * @return string[]|WP_Error Sanitized strings, or malformed-payload error.
 */
function wp_de_rtc_validate_block_identity_string_list( $values, $field ) {
	$validated = array();
	$seen      = array();

	foreach ( $values as $index => $value ) {
		if ( ! is_string( $value ) || '' === $value ) {
			return wp_de_rtc_get_block_identity_validation_error(
				'block_identity_request_proof_invalid_required_field',
				array(
					'field' => $field,
					'index' => (int) $index,
				)
			);
		}

		if ( isset( $seen[ $value ] ) ) {
			return wp_de_rtc_get_block_identity_validation_error(
				'block_identity_request_proof_duplicate_value',
				array(
					'field' => $field,
					'value' => $value,
					'index' => (int) $index,
				)
			);
		}

		$seen[ $value ] = true;
		$validated[]   = $value;
	}

	return $validated;
}

/**
 * Validates an accepted-base block UID list for block identity proof.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array  $values              UID list values.
 * @param string $field               Request-proof field name.
 * @param array  $accepted_block_uids Accepted-base UID lookup.
 * @return string[]|WP_Error Validated UIDs, or malformed-payload error.
 */
function wp_de_rtc_validate_block_identity_uid_list( $values, $field, $accepted_block_uids ) {
	$validated = wp_de_rtc_validate_block_identity_string_list( $values, $field );

	if ( is_wp_error( $validated ) ) {
		return $validated;
	}

	foreach ( $validated as $index => $block_uid ) {
		if ( ! isset( $accepted_block_uids[ $block_uid ] ) ) {
			return wp_de_rtc_get_block_identity_validation_error(
				'block_identity_request_proof_unknown_block_uid',
				array(
					'field'             => $field,
					'index'             => (int) $index,
					'unknown_block_uid' => $block_uid,
				)
			);
		}
	}

	return $validated;
}

/**
 * Returns whether a block identity version label is acceptable.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $version Version candidate.
 * @return bool Whether the version is a non-empty scalar label.
 */
function wp_de_rtc_is_block_identity_version_label( $version ) {
	return ( is_string( $version ) || is_int( $version ) ) && '' !== (string) $version;
}

/**
 * Returns whether a block identity ordinal path is valid.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $path Ordinal path candidate.
 * @return bool Whether the path is an array of non-negative integers.
 */
function wp_de_rtc_is_block_identity_ordinal_path( $path ) {
	if ( ! is_array( $path ) ) {
		return false;
	}

	foreach ( $path as $part ) {
		if ( ! is_int( $part ) || $part < 0 ) {
			return false;
		}
	}

	return true;
}

/**
 * Adds no-write evidence to a block identity validation result.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $data Validation result data.
 * @return array Validation result data with no-write evidence.
 */
function wp_de_rtc_get_block_identity_no_write_data( $data ) {
	return array_merge(
		$data,
		array(
			'saves_post'           => false,
			'mutates_post_content' => false,
			'creates_revision'     => false,
			'changes_post_lock'    => false,
			'claims_saved'         => false,
		)
	);
}

/**
 * Creates a malformed-payload error for block identity validation.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $detail Validation detail.
 * @param array  $extra  Optional extra data.
 * @return WP_Error Validation error.
 */
function wp_de_rtc_get_block_identity_validation_error( $detail, $extra = array() ) {
	return wp_de_rtc_get_reason_error(
		'de_rtc_malformed_sync_payload',
		__( 'Distributed Editing block identity proof is incomplete or malformed.' ),
		wp_de_rtc_get_block_identity_no_write_data(
			array_merge(
				array(
					'detail' => $detail,
				),
				$extra
			)
		)
	);
}

/**
 * Validates candidate post content from a recovery update plan.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $plan Recovery update plan.
 * @return bool[] Validation checks.
 */
function wp_de_rtc_validate_recovery_update_candidate( $plan ) {
	$checks = array(
		'candidate_post_content_present'          => isset( $plan['candidate_post_content'] ) && is_string( $plan['candidate_post_content'] ) && '' !== $plan['candidate_post_content'],
		'candidate_post_content_hash_matches'     => false,
		'candidate_stripped_content_hash_matches' => false,
		'candidate_parseable'                     => false,
		'candidate_stripped_content_matches'      => false,
		'candidate_sync_meta_matches'             => false,
		'candidate_sync_meta_format_matches'      => false,
		'candidate_recovery_attribution_valid'    => false,
	);

	if ( ! $checks['candidate_post_content_present'] ) {
		return $checks;
	}

	$checks['candidate_post_content_hash_matches'] = (
		isset( $plan['candidate_post_content_hash'] ) &&
		is_string( $plan['candidate_post_content_hash'] ) &&
		hash_equals( $plan['candidate_post_content_hash'], wp_de_rtc_hash_content( $plan['candidate_post_content'] ) )
	);

	$checks['candidate_stripped_content_hash_matches'] = (
		isset( $plan['candidate_stripped_content'], $plan['candidate_stripped_content_hash'] ) &&
		is_string( $plan['candidate_stripped_content'] ) &&
		is_string( $plan['candidate_stripped_content_hash'] ) &&
		hash_equals( $plan['candidate_stripped_content_hash'], wp_de_rtc_hash_content( $plan['candidate_stripped_content'] ) )
	);

	$parsed = wp_de_rtc_parse_post_content_sync_meta( $plan['candidate_post_content'] );

	if ( is_wp_error( $parsed ) || ! is_array( $parsed ) ) {
		return $checks;
	}

	$checks['candidate_parseable'] = true;

	$checks['candidate_stripped_content_matches'] = (
		isset( $plan['candidate_stripped_content'] ) &&
		is_string( $plan['candidate_stripped_content'] ) &&
		$parsed['content'] === $plan['candidate_stripped_content']
	);

	$checks['candidate_sync_meta_matches'] = (
		isset( $plan['restored_sync_meta'] ) &&
		$parsed['sync_meta'] === $plan['restored_sync_meta']
	);

	$checks['candidate_sync_meta_format_matches'] = (
		isset( $plan['restored_sync_meta_format'] ) &&
		is_string( $plan['restored_sync_meta_format'] ) &&
		$parsed['sync_meta_format'] === $plan['restored_sync_meta_format']
	);

	$checks['candidate_recovery_attribution_valid'] = wp_de_rtc_validate_sync_meta_recovery_attribution( $parsed['sync_meta'] );

	return $checks;
}

/**
 * Hashes stripped post content for DE-RTC base-evidence comparisons.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $content Post content without sync metadata.
 * @return string SHA-256 content hash.
 */
	function wp_de_rtc_hash_content( $content ) {
		return hash( 'sha256', wp_de_rtc_canonicalize_post_content_for_hash( $content ) );
	}

	/**
	 * Canonicalizes serialized post content for DE-RTC evidence hashes.
	 *
	 * Hash evidence must not depend on whether Gutenberg or WordPress emitted
	 * harmless whitespace around serialized block comment boundaries. Persistence
	 * still uses the caller's original content; this helper only normalizes the
	 * material fed into SHA-256 comparisons.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param string $content Serialized post content.
	 * @return string Canonicalized content for hash evidence.
	 */
	function wp_de_rtc_canonicalize_post_content_for_hash( $content ) {
		return wp_de_rtc_canonicalize_serialized_block_boundary_whitespace(
			wp_de_rtc_canonicalize_post_content_core_block_names( $content )
		);
	}

	/**
	 * Removes insignificant whitespace around serialized block boundaries.
	 *
	 * WordPress may persist pretty serialized blocks while Gutenberg exposes the
	 * same blocks compactly in the editor store. DE-RTC evidence compares the
	 * block document, not typography between block delimiters and their saved
	 * HTML.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param string $content Serialized post content.
	 * @return string Content with block-boundary whitespace normalized.
	 */
	function wp_de_rtc_canonicalize_serialized_block_boundary_whitespace( $content ) {
		$content = (string) $content;
		$content = preg_replace( '~(<!--\s*wp:[\s\S]*?-->)\s+(?=<)~', '$1', $content );
		$content = preg_replace( '~(?<=>)\s+(<!--\s*/wp:[\s\S]*?-->)~', '$1', $content );
		$content = preg_replace( '~(<!--\s*/wp:[\s\S]*?-->)\s+(?=<!--\s*wp:)~', '$1', $content );

		return $content;
	}

	/**
	 * Canonicalizes implicit-core serialized block delimiters for DE-RTC evidence.
	 *
	 * WordPress and Gutenberg serialize core blocks without the `core/` prefix,
	 * while parsed block names and block-identity metadata still use registered
	 * names such as `core/paragraph`. DE-RTC hashes and merge guards must compare
	 * the serialized form WordPress writes, without turning unrelated freeform
	 * HTML or unsafe block boundaries into accepted content.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param string $content Serialized post content.
	 * @return string Canonical content when only implicit-core delimiters differ; otherwise the original content.
	 */
	function wp_de_rtc_canonicalize_post_content_core_block_names( $content ) {
		$content = (string) $content;

		if ( false === stripos( $content, 'wp:core/' ) ) {
			return $content;
		}

		$blocks    = parse_blocks( $content );
		$roundtrip = '';

		foreach ( $blocks as $block ) {
			$roundtrip .= serialize_block( $block );
		}

		if ( $roundtrip === $content ) {
			return $content;
		}

		if ( wp_de_rtc_strip_core_block_namespace_from_serialized_comments( $content ) === $roundtrip ) {
			return $roundtrip;
		}

		return $content;
	}

	/**
	 * Returns serialized content with only `wp:core/*` comment delimiters stripped.
	 *
	 * This helper is used to prove a parser/serializer round trip changed only
	 * the implicit core namespace spelling. Its output is never trusted by itself
	 * for persistence.
	 *
	 * @since 7.1.0
	 * @access private
	 *
	 * @param string $content Serialized post content.
	 * @return string Content with implicit-core delimiter spelling normalized.
	 */
	function wp_de_rtc_strip_core_block_namespace_from_serialized_comments( $content ) {
		$normalized = preg_replace(
			'~<!--\s*(/?)wp:core/([^\s>]+)([\s\S]*?)-->~',
			'<!-- $1wp:$2$3-->',
			(string) $content
		);

		return is_string( $normalized ) ? $normalized : (string) $content;
	}

/**
 * Returns the next sync-meta version label for a retry save.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $current_version Current sync-meta version.
 * @param string $content_hash    Proposed stripped content hash.
 * @return string Next sync-meta version.
 */
function wp_de_rtc_get_next_sync_meta_version( $current_version, $content_hash ) {
	$current_version = (string) $current_version;
	$content_hash    = (string) $content_hash;

	if ( ctype_digit( $current_version ) ) {
		return (string) ( (int) $current_version + 1 );
	}

	return substr( hash( 'sha256', $current_version . '|' . $content_hash ), 0, 16 );
}

/**
 * Normalizes a sync-meta format label.
 *
 * @since 7.1.0
 * @access private
 *
 * @param mixed $format Sync-meta format label.
 * @return string Normalized label.
 */
function wp_de_rtc_normalize_sync_meta_format( $format ) {
	if ( ! is_string( $format ) ) {
		return '';
	}

	return strtolower( trim( $format ) );
}

/**
 * Counts Distributed Editing sync-meta SCRIPT elements in post content.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $content Post content.
 * @return int Number of DE-RTC sync-meta SCRIPT elements.
 */
function wp_de_rtc_count_post_content_sync_meta_scripts( $content ) {
	if (
		! is_string( $content ) ||
		(
			false === stripos( $content, 'wp/post-sync-meta' ) &&
			false === stripos( $content, 'wp:core/sync-meta' ) &&
			false === stripos( $content, 'wp:sync-meta' ) &&
			false === stripos( $content, 'data-wp-sync-meta' )
		)
	) {
		return 0;
	}

	$legacy_count = preg_match_all(
		'~<script\b(?=[^>]*\btype\s*=\s*(["\'])\s*wp/post-sync-meta\s*\1)[^>]*>[\s\S]*?</script\s*>~i',
		$content
	);
	$json_count   = preg_match_all(
		'~<script\b(?=[^>]*\btype\s*=\s*(["\'])\s*application/json\s*\1)(?=[^>]*\bdata-wp-sync-meta\s*=\s*(["\'])\s*distributed-editing\s*\2)[^>]*>[\s\S]*?</script\s*>~i',
		$content
	);
	$core_count   = preg_match_all(
		'~<!--\s*wp:(?:core/)?sync-meta\b[\s\S]*?<!--\s*/wp:(?:core/)?sync-meta\s*-->~i',
		$content
	);

	if ( false === $legacy_count ) {
		$legacy_count = 0;
	}

	if ( false === $core_count ) {
		$core_count = 0;
	}

	if ( false === $json_count ) {
		$json_count = 0;
	}

	if ( $core_count > 0 ) {
		return (int) $legacy_count + (int) $core_count;
	}

	return (int) $legacy_count + (int) $json_count;
}

/**
 * Matches a possible sync-meta SCRIPT element at one content edge.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $content  Post content.
 * @param string $position Edge position, either 'prefix' or 'trailer'.
 * @return array|false Matched SCRIPT data, or false when no edge script exists.
 */
function wp_de_rtc_match_edge_sync_meta_script( $content, $position ) {
	$script_pattern             = '(<script\b[^>]*>(.*?)</script\s*>)';
	$paragraph_wrapped_pattern  = '<p>\s*' . $script_pattern . '\s*</p>';
	$freeform_wrapped_pattern   = '<!--\s*wp:freeform\s*-->\s*' . $paragraph_wrapped_pattern . '\s*<!--\s*/wp:freeform\s*-->';
	$html_block_wrapped_pattern = '<!--\s*wp:html\s*-->\s*' . $script_pattern . '\s*<!--\s*/wp:html\s*-->';
	$core_block_wrapped_pattern = '<!--\s*wp:(?:core/)?sync-meta\b[^>]*-->\s*' . $script_pattern . '\s*<!--\s*/wp:(?:core/)?sync-meta\s*-->';
	$wrapped_pattern            = '(?|' . $core_block_wrapped_pattern . '|' . $html_block_wrapped_pattern . '|' . $freeform_wrapped_pattern . '|' . $paragraph_wrapped_pattern . ')';

	if ( 'prefix' === $position ) {
		$pattern = '~\A[ \t\r\n]*(?:' . $wrapped_pattern . '|' . $script_pattern . ')[ \t\r\n]*~is';

		if ( ! preg_match( $pattern, $content, $matches ) ) {
			return false;
		}

		$script = isset( $matches[1] ) && '' !== $matches[1] ? $matches[1] : ( $matches[3] ?? '' );
		$json   = isset( $matches[2] ) && '' !== $matches[2] ? $matches[2] : ( $matches[4] ?? '' );

		return array(
			'match'  => $matches[0],
			'script' => $script,
			'json'   => $json,
			'position' => false !== stripos( $matches[0], 'wp:core/sync-meta' ) || false !== stripos( $matches[0], 'wp:sync-meta' ) || false !== stripos( $matches[0], 'wp:html' ) ? 'prefix-block' : 'prefix',
		);
	}

	$trimmed_content = rtrim( $content );

	$wrapped_trailer_pattern = '~[ \t\r\n]*' . $wrapped_pattern . '[ \t\r\n]*\z~is';

	if ( preg_match( $wrapped_trailer_pattern, $trimmed_content, $matches, PREG_OFFSET_CAPTURE ) ) {
		return array(
			'match'  => substr( $content, $matches[0][1] ),
			'script' => $matches[1][0],
			'json'   => $matches[2][0],
			'position' => 'trailer',
		);
	}

	$script_start    = strripos( $trimmed_content, '<script' );

	if ( false === $script_start ) {
		return false;
	}

	while ( $script_start > 0 && preg_match( '/[ \t\r\n]/', $content[ $script_start - 1 ] ) ) {
		--$script_start;
	}

	$trailer = substr( $content, $script_start );
	$pattern = '~\A[ \t\r\n]*' . $script_pattern . '[ \t\r\n]*\z~is';

	if ( ! preg_match( $pattern, $trailer, $matches ) ) {
		return false;
	}

	return array(
		'match'  => $trailer,
		'script' => $matches[1],
		'json'   => $matches[2],
		'position' => 'trailer',
	);
}

/**
 * Matches a sync-meta pseudo-block whose SCRIPT wrapper was stripped.
 *
 * This is intentionally not part of the normal parser path. It lets revision
 * scans recover accepted bases created before DE-RTC preserved SCRIPT through
 * author KSES, while live saves still require the server-owned SCRIPT wrapper.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $content  Post content.
 * @param string $position Edge position, either 'prefix' or 'trailer'.
 * @return array|false Matched pseudo-block data, or false when absent.
 */
function wp_de_rtc_match_edge_script_stripped_sync_meta_block( $content, $position ) {
	if ( ! is_string( $content ) || false === stripos( $content, 'sync-meta' ) ) {
		return false;
	}

	$block_pattern = '(<!--\s*wp:(?:core/)?sync-meta\b(?P<attrs>[^>]*)-->\s*(?P<json>[\s\S]*?)\s*<!--\s*/wp:(?:core/)?sync-meta\s*-->)';

	if ( 'prefix' === $position ) {
		$pattern = '~\A[ \t\r\n]*' . $block_pattern . '[ \t\r\n]*~i';

		if ( ! preg_match( $pattern, $content, $matches ) ) {
			return false;
		}

		return array(
			'match' => $matches[0],
			'json'  => isset( $matches['json'] ) ? trim( $matches['json'] ) : '',
			'attrs' => isset( $matches['attrs'] ) ? trim( $matches['attrs'] ) : '',
		);
	}

	$trimmed_content = rtrim( $content );
	$pattern         = '~[ \t\r\n]*' . $block_pattern . '[ \t\r\n]*\z~i';

	if ( ! preg_match( $pattern, $trimmed_content, $matches, PREG_OFFSET_CAPTURE ) ) {
		return false;
	}

	return array(
		'match' => substr( $content, $matches[1][1] ),
		'json'  => isset( $matches['json'][0] ) ? trim( $matches['json'][0] ) : '',
		'attrs' => isset( $matches['attrs'][0] ) ? trim( $matches['attrs'][0] ) : '',
	);
}

/**
 * Parses a KSES-stripped sync-meta pseudo-block match.
 *
 * @since 7.1.0
 * @access private
 *
 * @param array $block Matched block data.
 * @return array|WP_Error Parsed sync metadata.
 */
function wp_de_rtc_parse_script_stripped_sync_meta_block( $block ) {
	$json = isset( $block['json'] ) && is_string( $block['json'] ) ? trim( $block['json'] ) : '';

	if ( '' === $json || '{' !== $json[0] || '}' !== substr( $json, -1 ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'The Distributed Editing sync metadata JSON is malformed.' ),
			array(
				'detail' => 'malformed_script_stripped_json',
			)
		);
	}

	$format = wp_de_rtc_get_script_stripped_sync_meta_block_format( isset( $block['attrs'] ) ? $block['attrs'] : '' );
	$script = '<script type="application/json" data-wp-sync-meta="distributed-editing"';

	if ( '' !== $format ) {
		$script .= ' data-sync-meta-format="' . esc_attr( $format ) . '"';
	}

	$script .= '></script>';

	return wp_de_rtc_parse_sync_meta_script( $script, $json );
}

/**
 * Extracts the sync-meta format from pseudo-block attributes.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $attrs Serialized block attributes.
 * @return string Normalized sync-meta format, or empty when absent.
 */
function wp_de_rtc_get_script_stripped_sync_meta_block_format( $attrs ) {
	$attrs = trim( (string) $attrs );

	if ( '' === $attrs || '{' !== $attrs[0] ) {
		return '';
	}

	$decoded = json_decode( $attrs, true );

	if ( JSON_ERROR_NONE !== json_last_error() || ! is_array( $decoded ) || empty( $decoded['format'] ) ) {
		return '';
	}

	return wp_de_rtc_normalize_sync_meta_format( $decoded['format'] );
}

/**
 * Parses a possible Distributed Editing sync-meta SCRIPT element.
 *
 * @since 7.1.0
 * @access private
 *
 * @param string $script SCRIPT element HTML.
 * @param string $json   SCRIPT text content.
 * @return array|false|WP_Error Parsed sync metadata, false for non-DE-RTC scripts, or a WP_Error.
 */
function wp_de_rtc_parse_sync_meta_script( $script, $json ) {
	$processor = new WP_HTML_Tag_Processor( $script );

	if ( ! $processor->next_tag( 'script' ) ) {
		return false;
	}

	$type = $processor->get_attribute( 'type' );

	$is_legacy_script = is_string( $type ) && 'wp/post-sync-meta' === strtolower( trim( $type ) );
	$is_json_script   = is_string( $type ) && 'application/json' === strtolower( trim( $type ) );
	$is_core_script   = $is_json_script && 'distributed-editing' === strtolower( trim( (string) $processor->get_attribute( 'data-wp-sync-meta' ) ) );

	if ( ! $is_legacy_script && ! $is_core_script ) {
		return false;
	}

	$format = wp_de_rtc_normalize_sync_meta_format( $processor->get_attribute( 'data-sync-meta-format' ) );
	$sync_meta = json_decode( trim( $json ), true );

	if ( JSON_ERROR_NONE !== json_last_error() || ! is_array( $sync_meta ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'The Distributed Editing sync metadata JSON is malformed.' ),
			array(
				'detail'          => 'malformed_json',
				'json_error_code' => json_last_error(),
			)
		);
	}

	if ( '' === $format && isset( $sync_meta['schema'] ) && 'de-rtc-automerge-v1' === $sync_meta['schema'] ) {
		$format = 'automerge';
	}

	if ( '' === $format ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_malformed_sync_payload',
			__( 'The Distributed Editing sync metadata format is missing.' ),
			array(
				'detail' => 'missing_sync_meta_format',
			)
		);
	}

	if ( ! in_array( $format, wp_de_rtc_get_supported_sync_meta_formats(), true ) ) {
		return wp_de_rtc_get_reason_error(
			'de_rtc_unknown_sync_meta_format',
			__( 'The Distributed Editing sync metadata format is not supported.' ),
			array(
				'format' => $format,
			)
		);
	}

	return array(
		'sync_meta'        => $sync_meta,
		'sync_meta_format' => $format,
	);
}
